"@

        $actionStart = Get-Date
        $result = $null
        $invocationError = $null
        try {
            $description = if ($Operation -eq 'Rename') {
                'Rename protected mpssvc DebugedLoopbackApps registry value'
            }
            else {
                'Inspect protected mpssvc DebugedLoopbackApps registry value'
            }
            ExecuteAsSystem -cmd $systemCommand -Description $description -SuppressActionLog
            if (-not (Test-Path -LiteralPath $resultPath)) {
                throw "SYSTEM did not return a Windows Firewall AppCs result for $AppCsPath."
            }
            $result = Get-Content -LiteralPath $resultPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        }
        catch {
            $invocationError = $_
        }
        finally {
            if (Test-Path -LiteralPath $resultPath) {
                Remove-Item -LiteralPath $resultPath -Force -ErrorAction SilentlyContinue
            }
        }

        $actionEnd = Get-Date
        $actionSucceeded = ($null -ne $result) -and [bool]$result.Success -and ($null -eq $invocationError)
        $shouldLogAction = ($Operation -eq 'Rename') -or
            (($null -ne $result) -and [bool]$result.PermissionsAdjusted)
        if ($shouldLogAction) {
            $mutations = [System.Collections.Generic.List[string]]::new()
            if ($result -and $result.PermissionsAdjusted) {
                $mutations.Add('Captured the AppCs owner/DACL and temporarily granted SYSTEM/Administrators FullControl')
            }
            if ($result -and $result.ReplacedExistingRenamed) {
                $mutations.Add('Removed the previous DebugedLoopbackApps_ value')
            }
            if ($result -and $result.RenamePerformed) {
                $mutations.Add('Renamed DebugedLoopbackApps to DebugedLoopbackApps_')
            }
            if ($result -and $result.EmptyValueCreated) {
                $mutations.Add('Created an empty DebugedLoopbackApps value with the preserved registry type')
            }
            if ($result -and $result.PermissionsRestored) {
                $mutations.Add('Restored and verified the captured AppCs owner and DACL')
            }
            $actionLogDetails = @{
                Description = "Windows Firewall AppCs $Operation as SYSTEM"
                Start       = $actionStart.ToString('o')
                End         = $actionEnd.ToString('o')
                Success     = $actionSucceeded
                Details     = @{
                    Operation                 = $Operation
                    Path                      = $AppCsPath
                    ExecutedAsSystem          = $true
                    Mutations                 = [string[]]$mutations
                    BeforeState               = if ($result) { $result.BeforeState } else { $null }
                    AfterState                = if ($result) { $result.State } else { $null }
                    PermissionsAdjusted       = if ($result) { [bool]$result.PermissionsAdjusted } else { $false }
                    PermissionsRestored       = if ($result) { [bool]$result.PermissionsRestored } else { $false }
                    RenamePerformed           = if ($result) { [bool]$result.RenamePerformed } else { $false }
                    ReplacedExistingRenamed   = if ($result) { [bool]$result.ReplacedExistingRenamed } else { $false }
                    EmptyValueCreated         = if ($result) { [bool]$result.EmptyValueCreated } else { $false }
                    OriginalMissing           = if ($result) { [bool]$result.OriginalMissing } else { $false }
                }
            }
            if ($invocationError) {
                $actionLogDetails.Error = $invocationError.ToString()
            }
            elseif ($result -and -not $result.Success) {
                $actionLogDetails.Error = [string]$result.Error
            }
            Write-ActionLog -Event 'ActionExecuted' -Details $actionLogDetails
        }

        if ($invocationError) {
            throw $invocationError
        }
        if (-not $result.Success) {
            throw "Unable to $($Operation.ToLowerInvariant()) $AppCsPath as SYSTEM: $($result.Error)"
        }
        $result.State | Add-Member -NotePropertyName PermissionsAdjusted -NotePropertyValue ([bool]$result.PermissionsAdjusted) -Force
        $result.State | Add-Member -NotePropertyName PermissionsRestored -NotePropertyValue ([bool]$result.PermissionsRestored) -Force
        $result.State | Add-Member -NotePropertyName RenamePerformed -NotePropertyValue ([bool]$result.RenamePerformed) -Force
        $result.State | Add-Member -NotePropertyName ReplacedExistingRenamed -NotePropertyValue ([bool]$result.ReplacedExistingRenamed) -Force
        $result.State | Add-Member -NotePropertyName OriginalMissing -NotePropertyValue ([bool]$result.OriginalMissing) -Force
        $result.State | Add-Member -NotePropertyName EmptyValueCreated -NotePropertyValue ([bool]$result.EmptyValueCreated) -Force
        return $result.State
    }

    function Get-FirewallDebugLoopbackAppsState {
        param(
            [Parameter(Mandatory = $true)][string]$AppCsPath
        )

        $activeValueName = 'DebugedLoopbackApps'
        $renamedValueName = 'DebugedLoopbackApps_'
        $pathExists = Test-Path -LiteralPath $AppCsPath -ErrorAction Stop
        $activeValueExists = $false
        $renamedValueExists = $false
        $entries = @()
        $sidEntries = @()
        $duplicateGroups = @()

        if ($pathExists) {
            $properties = Get-ItemProperty -LiteralPath $AppCsPath -ErrorAction Stop
            if ($properties) {
                $activeProperty = $properties.PSObject.Properties[$activeValueName]
                $renamedProperty = $properties.PSObject.Properties[$renamedValueName]
                $activeValueExists = $null -ne $activeProperty
                $renamedValueExists = $null -ne $renamedProperty

                if ($activeValueExists) {
                    $parsedEntries = [System.Collections.Generic.List[string]]::new()
                    foreach ($rawItem in @($activeProperty.Value)) {
                        if ($null -eq $rawItem) { continue }
                        foreach ($part in ([string]$rawItem -split '[,\r\n]+')) {
                            $entry = $part.Trim().Trim('"')
                            if (-not [string]::IsNullOrWhiteSpace($entry)) {
                                $parsedEntries.Add($entry)
                            }
                        }
                    }
                    $entries = @($parsedEntries)
                    $sidEntries = @($entries | Where-Object { $_ -match '^S-\d-\d+(?:-\d+)+$' })
                    $duplicateGroups = @($sidEntries | Group-Object | Where-Object Count -gt 1)
                }
            }
        }

        $duplicateEntryCount = 0
        foreach ($group in $duplicateGroups) {
            $duplicateEntryCount += ($group.Count - 1)
        }

        return [PSCustomObject]@{
            Path                 = $AppCsPath
            PathExists           = $pathExists
            ActiveValueExists    = $activeValueExists
            RenamedValueExists   = $renamedValueExists
            EntryCount           = $entries.Count
            SidCount             = $sidEntries.Count
            NonSidEntryCount     = $entries.Count - $sidEntries.Count
            UniqueSidCount       = @($sidEntries | Sort-Object -Unique).Count
            DuplicateSidCount    = $duplicateGroups.Count
            DuplicateEntryCount  = $duplicateEntryCount
            DuplicateSids        = [string[]]@($duplicateGroups | ForEach-Object Name)
        }
    }

    function Get-FirewallDebugLoopbackAppsEntrySeverity {
        param(
            [ValidateRange(0, [int]::MaxValue)][int]$EntryCount
        )

        if ($EntryCount -ge 683) { return 'CRIT' }
        if ($EntryCount -gt 600) { return 'WARN' }
        return 'OK'
    }

    # Returns Current/Default/LKGC control sets for explicit multi-control-set diagnostics or repairs.
    # Default repair writes should use Get-CurrentOfflineControlSetName to preserve LKGC.
    function Get-OfflineControlSetNames {
        $names = [System.Collections.Generic.List[string]]::new()
        $select = Get-ItemProperty 'HKLM:\BROKENSYSTEM\Select' -ErrorAction SilentlyContinue
        foreach ($value in @($select.Current, $select.Default, $select.LastKnownGood)) {
            if ($null -eq $value) { continue }
            $name = 'ControlSet{0:d3}' -f [int]$value
            if (-not $names.Contains($name) -and (Test-Path "HKLM:\BROKENSYSTEM\$name")) {
                $names.Add($name)
            }
        }
        if ($names.Count -eq 0 -and (Test-Path 'HKLM:\BROKENSYSTEM\ControlSet001')) {
            $names.Add('ControlSet001')
        }
        return @($names)
    }

    function Get-BootStorageDriverSpec {
        @(
            [PSCustomObject]@{ Name = 'acpi';     Binary = 'acpi.sys';     Start = 0; AllowedStarts = [int[]]@(0);       Required = $true;  CanRecreate = $false; ErrorControl = 3; Group = 'Boot Bus Extender'; CheckStartOverride = $false; Description = 'ACPI platform bus' }
            [PSCustomObject]@{ Name = 'pci';      Binary = 'pci.sys';      Start = 0; AllowedStarts = [int[]]@(0);    Required = $true;  CanRecreate = $true;  ErrorControl = 3; Group = 'Boot Bus Extender'; CheckStartOverride = $false; Description = 'PCI boot bus' }
            [PSCustomObject]@{ Name = 'vdrvroot'; Binary = 'vdrvroot.sys'; Start = 0; AllowedStarts = [int[]]@(0, 1, 3); Required = $true;  CanRecreate = $false; ErrorControl = 1; Group = 'System Bus Extender'; CheckStartOverride = $false; Description = 'virtual drive root enumerator' }
            [PSCustomObject]@{ Name = 'intelide'; Binary = 'intelide.sys'; Start = 0; AllowedStarts = [int[]]@(0);    Required = $false; CanRecreate = $false; ErrorControl = 3; Group = 'System Bus Extender'; CheckStartOverride = $true;  ExpectedStartOverride = 3; Description = 'legacy IDE controller' }
            [PSCustomObject]@{ Name = 'pciide';   Binary = 'pciide.sys';   Start = 0; AllowedStarts = [int[]]@(0);    Required = $false; CanRecreate = $false; ErrorControl = 3; Group = 'System Bus Extender'; CheckStartOverride = $true;  ExpectedStartOverride = 3; Description = 'PCI IDE controller' }
            [PSCustomObject]@{ Name = 'atapi';    Binary = 'atapi.sys';    Start = 0; AllowedStarts = [int[]]@(0);    Required = $false; CanRecreate = $false; ErrorControl = 3; Group = 'SCSI Miniport';       CheckStartOverride = $true;  ExpectedStartOverride = 3; Description = 'IDE channel driver' }
            [PSCustomObject]@{ Name = 'storahci'; Binary = 'storahci.sys'; Start = 0; AllowedStarts = [int[]]@(0);    Required = $false; CanRecreate = $false; ErrorControl = 3; Group = 'SCSI Miniport';       CheckStartOverride = $true;  ExpectedStartOverride = 3; Description = 'AHCI storage miniport' }
            [PSCustomObject]@{ Name = 'vmbus';    Binary = 'vmbus.sys';    Start = 0; AllowedStarts = [int[]]@(0);       Required = $true;  CanRecreate = $false; ErrorControl = 3; Group = 'Boot Bus Extender'; CheckStartOverride = $true;  ExpectedStartOverride = 0; Description = 'Hyper-V VMBus' }
            [PSCustomObject]@{ Name = 'storvsc';  Binary = 'storvsc.sys';  Start = 0; AllowedStarts = [int[]]@(0);       Required = $true;  CanRecreate = $false; ErrorControl = 3; Group = 'SCSI Miniport';       CheckStartOverride = $true;  ExpectedStartOverride = 0; Description = 'Hyper-V storage' }
            [PSCustomObject]@{ Name = 'storport'; Binary = 'storport.sys'; Start = 0; AllowedStarts = [int[]]@(0);    Required = $false; CanRecreate = $false; ErrorControl = 3; Group = 'SCSI Miniport';       CheckStartOverride = $false; Description = 'storage port driver' }
            [PSCustomObject]@{ Name = 'disk';     Binary = 'disk.sys';     Start = 0; AllowedStarts = [int[]]@(0);    Required = $true;  CanRecreate = $true;  ErrorControl = 3; Group = 'SCSI Class';          CheckStartOverride = $false; Description = 'disk class driver' }
            [PSCustomObject]@{ Name = 'partmgr';  Binary = 'partmgr.sys';  Start = 0; AllowedStarts = [int[]]@(0, 1); Required = $true;  CanRecreate = $true;  ErrorControl = 3; Group = 'Boot Bus Extender'; CheckStartOverride = $false; Description = 'partition manager' }
            [PSCustomObject]@{ Name = 'volmgr';   Binary = 'volmgr.sys';   Start = 0; AllowedStarts = [int[]]@(0);    Required = $true;  CanRecreate = $true;  ErrorControl = 3; Group = 'System Bus Extender'; CheckStartOverride = $false; Description = 'volume manager' }
            [PSCustomObject]@{ Name = 'mountmgr'; Binary = 'mountmgr.sys'; Start = 0; AllowedStarts = [int[]]@(0);       Required = $true;  CanRecreate = $false; ErrorControl = 1; Group = 'System Bus Extender'; CheckStartOverride = $false; Description = 'mount point manager' }
            [PSCustomObject]@{ Name = 'volsnap';  Binary = 'volsnap.sys';  Start = 1; AllowedStarts = [int[]]@(0, 1, 3); Required = $true;  CanRecreate = $false; ErrorControl = 3; Group = 'Filter';             CheckStartOverride = $false; Description = 'volume shadow copy filter' }
            # Note: fvevol (BitLocker volume filter) is intentionally NOT listed here.
            # Whether its service key is required depends on the OS volume actually being
            # BitLocker-encrypted, which cannot be reliably determined from the offline
            # registry hive alone, so flagging a missing key would produce false positives.
        )
    }

    function Test-BootStorageDriverBinaryReady {
        param(
            [Parameter(Mandatory = $true)]$Spec
        )

        $binaryPath = if ($Spec.Binary) { Resolve-GuestImagePath "system32\drivers\$($Spec.Binary)" } else { '' }
        if (-not $binaryPath -or -not (Test-Path -LiteralPath $binaryPath)) { return $false }
        $item = Get-Item -LiteralPath $binaryPath -Force -ErrorAction SilentlyContinue
        if (-not $item -or $item.Length -eq 0) { return $false }

        $signature = Test-MicrosoftSignature -FilePath $binaryPath
        return [bool]$signature.IsAcceptableMicrosoft
    }

    function New-BootStorageServiceKey {
        param(
            [Parameter(Mandatory = $true)][string]$ControlSetName,
            [Parameter(Mandatory = $true)]$Spec
        )

        $svcPath = "HKLM:\BROKENSYSTEM\$ControlSetName\Services\$($Spec.Name)"
        if (Test-Path $svcPath) { return $false }
        if (-not $Spec.CanRecreate) { return $false }

        $binaryPath = if ($Spec.Binary) { Resolve-GuestImagePath "system32\drivers\$($Spec.Binary)" } else { '' }
        if (-not $binaryPath -or -not (Test-Path -LiteralPath $binaryPath)) {
            Write-Warning "  Cannot recreate $ControlSetName\Services\$($Spec.Name): driver binary not found at $binaryPath"
            return $false
        }
        $binaryItem = Get-Item -LiteralPath $binaryPath -Force -ErrorAction SilentlyContinue
        if (-not $binaryItem -or $binaryItem.Length -eq 0) {
            Write-Warning "  Cannot recreate $ControlSetName\Services\$($Spec.Name): driver binary is missing or 0 bytes at $binaryPath"
            return $false
        }

        $signature = Test-MicrosoftSignature -FilePath $binaryPath
        if (-not $signature.IsAcceptableMicrosoft) {
            Write-Warning "  Cannot recreate $ControlSetName\Services\$($Spec.Name): driver binary failed trust validation - $(Get-TrustStateDescription -Signature $signature)"
            return $false
        }

        Write-Host "    Creating missing $($Spec.Name) service key from inbox driver template ($($Spec.Binary))" -ForegroundColor Yellow
        New-Item-Logged -Path $svcPath -Force | Out-Null
        Set-ItemProperty-Logged -Path $svcPath -Name Type -Value 1 -Type DWord -Force | Out-Null
        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $Spec.Start -Type DWord -Force | Out-Null
        Set-ItemProperty-Logged -Path $svcPath -Name ErrorControl -Value $Spec.ErrorControl -Type DWord -Force | Out-Null
        Set-ItemProperty-Logged -Path $svcPath -Name ImagePath -Value "system32\drivers\$($Spec.Binary)" -Type ExpandString -Force | Out-Null
        if ($Spec.Group) {
            Set-ItemProperty-Logged -Path $svcPath -Name Group -Value $Spec.Group -Type String -Force | Out-Null
        }

        Write-ActionLog -Event 'BootStorageServiceKeyCreated' -Details @{
            ControlSet   = $ControlSetName
            Service      = $Spec.Name
            Binary       = $Spec.Binary
            BinaryPath   = $binaryPath
            Start        = $Spec.Start
            ErrorControl = $Spec.ErrorControl
            Group        = $Spec.Group
        }
        return $true
    }

    function Get-BootStorageDriverFindings {
        param(
            [Parameter(Mandatory = $true)][string[]]$ControlSetNames
        )

        $findings = [System.Collections.Generic.List[object]]::new()
        foreach ($csName in $ControlSetNames) {
            $svcRoot = "HKLM:\BROKENSYSTEM\$csName\Services"
            foreach ($spec in (Get-BootStorageDriverSpec)) {
                $svcPath = "$svcRoot\$($spec.Name)"
                if (-not (Test-Path $svcPath)) {
                    if ($spec.Required) {
                        $canRecreate = [bool]$spec.CanRecreate -and (Test-BootStorageDriverBinaryReady -Spec $spec)
                        $severity = if ($spec.Name -ieq 'storport') { 1 } else { 2 }
                        $message = if ($spec.Name -ieq 'storport') {
                            "$($spec.Name) service key is missing - this can affect some migrated storage stacks, but may be normal on this Windows image"
                        }
                        else {
                            "$($spec.Name) service key is missing - $($spec.Description) cannot participate in boot storage enumeration"
                        }
                        $fix = if ($canRecreate) {
                            '-FixBootStorageDrivers'
                        }
                        elseif ($spec.CanRecreate) {
                            "-RepairSystemFile $($spec.Binary), then rerun -FixBootStorageDrivers to recreate the service key"
                        }
                        else {
                            'Restore the service key from a matching Windows image or repair the offline registry; this script checks this key but does not recreate it'
                        }
                        $findings.Add([PSCustomObject]@{
                            ControlSet = $csName
                            Driver     = $spec.Name
                            Severity   = $severity
                            Message    = $message
                            Fix        = $fix
                        })
                    }
                    continue
                }

                $props = Get-ItemProperty $svcPath -ErrorAction SilentlyContinue
                if ($null -eq $props -or $null -eq $props.Start) {
                    $findings.Add([PSCustomObject]@{
                        ControlSet = $csName
                        Driver     = $spec.Name
                        Severity   = 2
                        Message    = "$($spec.Name) has no Start value - boot storage load order is incomplete"
                        Fix        = '-FixBootStorageDrivers'
                    })
                }
                elseif ([int]$props.Start -notin @($spec.AllowedStarts)) {
                    $expectedText = (@($spec.AllowedStarts) | ForEach-Object { [string]$_ }) -join ' or '
                    $findings.Add([PSCustomObject]@{
                        ControlSet = $csName
                        Driver     = $spec.Name
                        Severity   = 2
                        Message    = "$($spec.Name) Start=$($props.Start) (expected $expectedText) - $($spec.Description) may not load early enough after migration"
                        Fix        = '-FixBootStorageDrivers'
                    })
                }

                if ($spec.CheckStartOverride) {
                    if ($null -eq $spec.ExpectedStartOverride) { continue }
                    $expectedStartOverride = [int]$spec.ExpectedStartOverride
                    $overrideContext = if ($spec.Required) { 'required boot-storage driver' } else { 'optional IDE/AHCI driver baseline' }
                    $overridePath = "$svcPath\StartOverride"
                    if (Test-Path $overridePath) {
                        $overrideProps = Get-ItemProperty $overridePath -ErrorAction SilentlyContinue
                        foreach ($prop in @($overrideProps.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' })) {
                            if ($null -eq $prop.Value) { continue }
                            if ([int]$prop.Value -ne $expectedStartOverride) {
                                $findings.Add([PSCustomObject]@{
                                    ControlSet = $csName
                                    Driver     = $spec.Name
                                    Severity   = 1
                                    Message    = "$($spec.Name) StartOverride\$($prop.Name)=$($prop.Value) (expected $expectedStartOverride for $overrideContext)"
                                    Fix        = '-FixBootStorageDrivers'
                                })
                            }
                        }
                    }
                }
            }
        }

        return @($findings)
    }

    function Get-BootCriticalDeviceInstanceFilterFindings {
        param(
            [Parameter(Mandatory = $true)][string[]]$ControlSetNames
        )

        $findings = [System.Collections.Generic.List[object]]::new()
        $bootBusServices = [string[]]@('pci', 'vmbus')

        foreach ($csName in $ControlSetNames) {
            $enumRoot = "HKLM:\BROKENSYSTEM\$csName\Enum\ACPI"
            if (-not (Test-Path $enumRoot)) { continue }

            Get-ChildItem $enumRoot -ErrorAction SilentlyContinue | ForEach-Object {
                $deviceId = $_.PSChildName
                Get-ChildItem $_.PSPath -ErrorAction SilentlyContinue | ForEach-Object {
                    $instanceId = $_.PSChildName
                    $props = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                    if ($null -eq $props -or $bootBusServices -inotcontains $props.Service) { return }

                    foreach ($filterType in @('UpperFilters', 'LowerFilters')) {
                        $active = @($props.$filterType | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                        if ($active.Count -eq 0) { continue }

                        $findings.Add([PSCustomObject]@{
                            ControlSet  = $csName
                            Device      = "ACPI\$deviceId\$instanceId"
                            Service     = $props.Service
                            RegistryPath = "HKLM:\BROKENSYSTEM\$csName\Enum\ACPI\$deviceId\$instanceId"
                            FilterType  = $filterType
                            Filters     = [string[]]$active
                            Message     = "ACPI\$deviceId\$instanceId ($($props.Service)) $filterType contains boot-critical device instance filter(s): $($active -join ', ')"
                            Fix         = '-FixDeviceFilters'
                        })
                    }
                }
            }
        }

        return @($findings)
    }

    function Ensure-GuestTempDir {
        # Creates the \Temp directory on the offline guest disk if it does not already exist.
        if (-not (Test-Path -Path "$script:WinDriveLetter\Temp")) {
            New-Item-Logged -Path "$script:WinDriveLetter\Temp" -ItemType Directory -Force | Out-Null
        }
    }

    function Get-ThirdPartyDriverStartBackupPath {
        return (Join-Path $PSScriptRoot 'Repair-AzVMDisk_ThirdPartyDriverStartBackup.json')
    }

    function ConvertFrom-ThirdPartyDriverStartBackupJson {
        param(
            [Parameter(Mandatory = $true)][string]$Json
        )

        $entries = [System.Collections.Generic.List[object]]::new()
        if ([string]::IsNullOrWhiteSpace($Json)) { return @() }

        $parsed = ConvertFrom-Json -InputObject $Json
        if ($null -eq $parsed) { return @() }

        if ($parsed -is [System.Array]) {
            foreach ($item in $parsed) {
                if ($null -ne $item) { $entries.Add($item) }
            }
        }
        else {
            $entries.Add($parsed)
        }

        return @($entries)
    }

    # Returns the offline guest's OS version as a PSCustomObject
    # (ProductName / CurrentBuildNumber / UBR). Prefers the already-selected
    # Windows install so the SOFTWARE hive is not re-mounted on every caller;
    # falls back to a single SOFTWARE-hive read when no install is selected yet.
    function Get-GuestCurrentVersion {
        if ($script:SelectedWindowsInstall -and $script:SelectedWindowsInstall.CurrentBuildNumber) {
            return [PSCustomObject]@{
                ProductName        = [string]$script:SelectedWindowsInstall.ProductName
                CurrentBuildNumber = [string]$script:SelectedWindowsInstall.CurrentBuildNumber
                UBR                = [string]$script:SelectedWindowsInstall.UBR
            }
        }

        $info = $null
        try {
            $info = Invoke-WithHive 'SOFTWARE' {
                $cv = Get-ItemProperty 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
                if ($cv) {
                    [PSCustomObject]@{
                        ProductName        = [string]$cv.ProductName
                        CurrentBuildNumber = [string]$cv.CurrentBuildNumber
                        UBR                = if ($null -ne $cv.UBR) { [string]$cv.UBR } else { '' }
                    }
                }
            }
        }
        catch { <# best-effort: guest version is optional diagnostic context #> }

        if ($info) {
            return [PSCustomObject]@{
                ProductName        = [string]$info.ProductName
                CurrentBuildNumber = [string]$info.CurrentBuildNumber
                UBR                = [string]$info.UBR
            }
        }

        return [PSCustomObject]@{ ProductName = ''; CurrentBuildNumber = ''; UBR = '' }
    }

    # Formats a Windows build label as "<Build>.<UBR>" (or just "<Build>" when UBR
    # is absent). Returns $Fallback when no build number is available. $Prefix is
    # prepended to a non-fallback label (e.g. 'Build ').
    function Format-WindowsBuildLabel {
        param(
            [string]$Build,
            [string]$Ubr,
            [string]$Prefix = '',
            [string]$Fallback = ''
        )
        if ([string]::IsNullOrWhiteSpace($Build)) { return $Fallback }
        $label = if (-not [string]::IsNullOrWhiteSpace($Ubr)) { "$Build.$Ubr" } else { "$Build" }
        return "$Prefix$label"
    }

    # Helper: probe a currently-mounted volume for its NTFS dirty bit and spot-verifier
    # ($corrupt) state. The volume must be online with a drive letter (e.g. 'F:').
    # Returns a PSCustomObject:
    #   .Letter      - normalised 'X:'
    #   .DirtyBit    - $true if dirty, $false if not dirty, $null if undetermined
    #   .DirtyRaw    - raw 'fsutil dirty query' text
    #   .RepairState - 'healthy' | 'corrupt' | 'unknown' (parsed from 'fsutil repair state')
    #   .RepairRaw   - raw 'fsutil repair state' text
    function Get-OfflineVolumeFsState {
        param([Parameter(Mandatory)][string]$Letter)

        $norm = $Letter.TrimEnd('\')
        $result = [PSCustomObject]@{ Letter = $norm; DirtyBit = $null; DirtyRaw = ''; RepairState = 'unknown'; RepairRaw = '' }
        if ($norm -notmatch '^[A-Za-z]:$') { return $result }

        # Classic dirty bit: definitive 'Volume - X: is [NOT] Dirty'. Check 'not dirty' first.
        try {
            $result.DirtyRaw = (& fsutil.exe dirty query $norm 2>&1 | Out-String).Trim()
            if ($result.DirtyRaw -match '(?i)not\s+dirty') { $result.DirtyBit = $false }
            elseif ($result.DirtyRaw -match '(?i)\bdirty\b') { $result.DirtyBit = $true }
        }
        catch {}

        # Spot-verifier / self-heal state via 'fsutil repair state', which prints a line like:
        #   Corruption State:  0x00 - Clean
        #   Corruption State:  0x01 - Verifying
        #   Corruption State:  0x02 - Corrupt
        # Parse that specific line (NOT the bare word 'Corrupt', which also appears in the
        # 'Corruption State:' label and would otherwise match a clean volume). 0x0* / Clean
        # -> healthy; any other state value -> corrupt; unparseable -> unknown (callers then
        # key off Get-Volume health).
        try {
            $result.RepairRaw = (& fsutil.exe repair state $norm 2>&1 | Out-String).Trim()
            $stateMatch = [regex]::Match($result.RepairRaw, '(?im)^\s*Corruption State:\s*(0x[0-9a-fA-F]+)\s*-\s*(.+?)\s*$')
            if ($stateMatch.Success) {
                $stateValue = $stateMatch.Groups[1].Value
                $stateLabel = $stateMatch.Groups[2].Value
                if ($stateValue -match '^0x0+$' -or $stateLabel -match '(?i)clean') { $result.RepairState = 'healthy' }
                else { $result.RepairState = 'corrupt' }
            }
            elseif ($result.RepairRaw -match '(?i)\bclean\b') { $result.RepairState = 'healthy' }
        }
        catch {}

        return $result
    }

    # -------------------------------------------------------------------------
    # NTFS metafile $ATTRIBUTE_LIST helpers
    #
    # A reserved MFT record (file record 0-31) can carry an ATTRIBUTE_LIST_ENTRY
    # whose NameOffset field is 0x1c where the canonical layout uses 0x1a. Older
    # NTFS revisions accept that representation; newer ones validate it, reject
    # the record while resolving the referenced stream and fail the volume mount.
    # In the guest this surfaces as a boot loop with bugcheck 0x24
    # (NTFS_FILE_SYSTEM), typically immediately after a servicing operation, and
    # the volume mounts again if that servicing operation is reverted.
    #
    # The costly instance is the $Secure metafile (file record 9), whose
    # attribute list references the $SDS security-descriptor stream. chkdsk is
    # not a safe repair for this: it discards the entire attribute list instead
    # of correcting the field, which orphans every child record the list pointed
    # at - including $SDS - and leaves the volume with default security
    # descriptors. The repair implemented here rewrites the single NameOffset
    # byte and shifts the attribute name back two bytes, leaving record lengths,
    # allocation and every other structure untouched.
    # -------------------------------------------------------------------------

    # Canonical vs. known-bad ATTRIBUTE_LIST_ENTRY.NameOffset values.
    $script:NtfsAttrListGoodNameOffset = 0x1A
    $script:NtfsAttrListBadNameOffset = 0x1C
    # Reserved/system file record range scanned for the condition.
    $script:NtfsAttrListMaxFrn = 31

    function Initialize-NtfsRawVolumeIo {
        # Raw volume read/write primitives. Loaded on demand so the script has no
        # cost when no attribute-list operation is requested.
        if (([System.Management.Automation.PSTypeName]'RepairAzVMDiskRawVolumeIo').Type) { return }
        Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;

public static class RepairAzVMDiskRawVolumeIo
{
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    private static extern SafeFileHandle CreateFileW(
        string lpFileName, uint dwDesiredAccess, uint dwShareMode,
        IntPtr lpSecurityAttributes, uint dwCreationDisposition,
        uint dwFlagsAndAttributes, IntPtr hTemplateFile);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool ReadFile(SafeFileHandle hFile, byte[] lpBuffer,
        uint nNumberOfBytesToRead, out uint lpNumberOfBytesRead, IntPtr lpOverlapped);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool WriteFile(SafeFileHandle hFile, byte[] lpBuffer,
        uint nNumberOfBytesToWrite, out uint lpNumberOfBytesWritten, IntPtr lpOverlapped);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool SetFilePointerEx(SafeFileHandle hFile,
        long liDistanceToMove, out long lpNewFilePointer, uint dwMoveMethod);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FlushFileBuffers(SafeFileHandle hFile);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool DeviceIoControl(SafeFileHandle hDevice, uint dwIoControlCode,
        IntPtr lpInBuffer, uint nInBufferSize, IntPtr lpOutBuffer, uint nOutBufferSize,
        out uint lpBytesReturned, IntPtr lpOverlapped);

    private const uint GENERIC_READ          = 0x80000000;
    private const uint GENERIC_WRITE         = 0x40000000;
    private const uint FILE_SHARE_RW         = 0x00000003;
    private const uint OPEN_EXISTING         = 3;
    private const uint FSCTL_LOCK_VOLUME     = 0x00090018;
    private const uint FSCTL_UNLOCK_VOLUME   = 0x0009001C;
    private const uint FSCTL_DISMOUNT_VOLUME = 0x00090020;

    public static SafeFileHandle OpenVolume(string path, bool forWrite)
    {
        uint access = GENERIC_READ | (forWrite ? GENERIC_WRITE : 0);
        SafeFileHandle handle = CreateFileW(path, access, FILE_SHARE_RW, IntPtr.Zero,
                                            OPEN_EXISTING, 0, IntPtr.Zero);
        if (handle.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error());
        return handle;
    }

    public static byte[] Read(SafeFileHandle handle, long offset, int size)
    {
        long position;
        if (!SetFilePointerEx(handle, offset, out position, 0))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        byte[] buffer = new byte[size];
        uint read;
        if (!ReadFile(handle, buffer, (uint)size, out read, IntPtr.Zero))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        if (read != (uint)size)
            throw new IOException("Short read at offset " + offset + ": expected " + size + " bytes, got " + read + ".");
        return buffer;
    }

    public static void Write(SafeFileHandle handle, long offset, byte[] data)
    {
        long position;
        if (!SetFilePointerEx(handle, offset, out position, 0))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        uint written;
        if (!WriteFile(handle, data, (uint)data.Length, out written, IntPtr.Zero))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        if (written != (uint)data.Length)
            throw new IOException("Short write at offset " + offset + ": expected " + data.Length + " bytes, wrote " + written + ".");
    }

    public static void Flush(SafeFileHandle handle)
    {
        if (!FlushFileBuffers(handle))
            throw new Win32Exception(Marshal.GetLastWin32Error());
    }

    public static void LockVolume(SafeFileHandle handle)
    {
        uint returned;
        if (!DeviceIoControl(handle, FSCTL_LOCK_VOLUME, IntPtr.Zero, 0, IntPtr.Zero, 0, out returned, IntPtr.Zero))
            throw new Win32Exception(Marshal.GetLastWin32Error());
    }

    public static void DismountVolume(SafeFileHandle handle)
    {
        uint returned;
        if (!DeviceIoControl(handle, FSCTL_DISMOUNT_VOLUME, IntPtr.Zero, 0, IntPtr.Zero, 0, out returned, IntPtr.Zero))
            throw new Win32Exception(Marshal.GetLastWin32Error());
    }

    public static void UnlockVolume(SafeFileHandle handle)
    {
        uint returned;
        DeviceIoControl(handle, FSCTL_UNLOCK_VOLUME, IntPtr.Zero, 0, IntPtr.Zero, 0, out returned, IntPtr.Zero);
    }
}
'@
    }

    function Get-NtfsLeUInt16 { param([byte[]]$Buffer, [int]$Offset) return [BitConverter]::ToUInt16($Buffer, $Offset) }
    function Get-NtfsLeUInt32 { param([byte[]]$Buffer, [int]$Offset) return [BitConverter]::ToUInt32($Buffer, $Offset) }
    function Get-NtfsLeUInt64 { param([byte[]]$Buffer, [int]$Offset) return [BitConverter]::ToUInt64($Buffer, $Offset) }

    function ConvertTo-NtfsVolumePath {
        # Accepts 'F', 'F:', 'F:\' or '\\.\F:' and returns the raw device form '\\.\F:'.
        param([Parameter(Mandatory)][string]$Volume)
        $value = $Volume.Trim()
        if ($value -match '^\\\\[.?]\\') { return ($value.TrimEnd('\')) }
        $letter = $value.TrimEnd('\').TrimEnd(':')
        if ($letter -notmatch '^[A-Za-z]$') { throw "Unsupported volume specification: $Volume" }
        return "\\.\$($letter.ToUpperInvariant()):"
    }

    function Read-NtfsVolumeAligned {
        # Raw volume handles only accept sector-aligned offsets and sector-multiple
        # sizes. Reads the enclosing aligned window and returns just the requested slice.
        param(
            [Parameter(Mandatory)]$Handle,
            [Parameter(Mandatory)][long]$Offset,
            [Parameter(Mandatory)][int]$Size,
            [Parameter(Mandatory)][int]$BytesPerSector
        )
        $start = [long]([math]::Floor($Offset / $BytesPerSector) * $BytesPerSector)
        $delta = [int]($Offset - $start)
        $span = [int]([math]::Ceiling(($delta + $Size) / [double]$BytesPerSector) * $BytesPerSector)
        $window = [RepairAzVMDiskRawVolumeIo]::Read($Handle, $start, $span)
        $result = New-Object byte[] $Size
        [Array]::Copy($window, $delta, $result, 0, $Size)
        # Comma operator: a bare 'return $result' unrolls the byte[] into the
        # pipeline, so the caller receives an Object[]. Binding that to a
        # [byte[]] parameter silently converts it to a *new* array, which would
        # discard in-place multi-sector fixups applied by the callee.
        return , $result
    }

    function Write-NtfsVolumeAligned {
        # Sector-aligned read-modify-write so callers can patch arbitrary offsets.
        param(
            [Parameter(Mandatory)]$Handle,
            [Parameter(Mandatory)][long]$Offset,
            [Parameter(Mandatory)][byte[]]$Data,
            [Parameter(Mandatory)][int]$BytesPerSector
        )
        $start = [long]([math]::Floor($Offset / $BytesPerSector) * $BytesPerSector)
        $delta = [int]($Offset - $start)
        $span = [int]([math]::Ceiling(($delta + $Data.Length) / [double]$BytesPerSector) * $BytesPerSector)
        $window = [RepairAzVMDiskRawVolumeIo]::Read($Handle, $start, $span)
        [Array]::Copy($Data, 0, $window, $delta, $Data.Length)
        [RepairAzVMDiskRawVolumeIo]::Write($Handle, $start, $window)
    }

    function Convert-NtfsMappingPairs {
        # Decodes an NTFS mapping-pairs run list into absolute LCN/cluster-count pairs.
        param([byte[]]$Record, [int]$StartOffset)
        $runs = [System.Collections.Generic.List[PSCustomObject]]::new()
        $lcn = [long]0
        $pos = $StartOffset
        while ($pos -lt $Record.Length) {
            $header = $Record[$pos]
            if ($header -eq 0) { break }
            $pos++
            $lengthSize = $header -band 0x0F
            $offsetSize = ($header -shr 4) -band 0x0F
            if ($lengthSize -eq 0 -or ($pos + $lengthSize + $offsetSize) -gt $Record.Length) { break }

            [long]$runLength = 0
            for ($i = 0; $i -lt $lengthSize; $i++) { $runLength = $runLength -bor ([long]$Record[$pos + $i] -shl ($i * 8)) }
            $pos += $lengthSize

            if ($offsetSize -gt 0) {
                [long]$runOffset = 0
                for ($i = 0; $i -lt $offsetSize; $i++) { $runOffset = $runOffset -bor ([long]$Record[$pos + $i] -shl ($i * 8)) }
                # Sign-extend the delta: run offsets are signed and may move backwards.
                if ($Record[$pos + $offsetSize - 1] -band 0x80) {
                    for ($i = $offsetSize; $i -lt 8; $i++) { $runOffset = $runOffset -bor ([long]0xFF -shl ($i * 8)) }
                }
                $pos += $offsetSize
                $lcn += $runOffset
            }
            if ($runLength -le 0) { break }
            $runs.Add([PSCustomObject]@{ Lcn = $lcn; Clusters = $runLength })
        }
        return $runs
    }

    function Get-NtfsAttributeTypeName {
        param([uint32]$TypeCode)
        switch ($TypeCode) {
            0x10 { '$STANDARD_INFORMATION' }
            0x20 { '$ATTRIBUTE_LIST' }
            0x30 { '$FILE_NAME' }
            0x40 { '$OBJECT_ID' }
            0x50 { '$SECURITY_DESCRIPTOR' }
            0x60 { '$VOLUME_NAME' }
            0x70 { '$VOLUME_INFORMATION' }
            0x80 { '$DATA' }
            0x90 { '$INDEX_ROOT' }
            0xA0 { '$INDEX_ALLOCATION' }
            0xB0 { '$BITMAP' }
            0xC0 { '$REPARSE_POINT' }
            0x100 { '$LOGGED_UTILITY_STREAM' }
            default { "0x$($TypeCode.ToString('x'))" }
        }
    }

    function Resolve-NtfsUsaFixup {
        # Applies the update-sequence-array fixup in place (on-disk -> in-memory).
        # Returns $false when the record's sector tails do not carry the expected
        # update sequence number, which means the record is not safe to interpret.
        param([byte[]]$Record, [int]$BytesPerSector)
        $usaOffset = Get-NtfsLeUInt16 $Record 4
        $usaCount = Get-NtfsLeUInt16 $Record 6
        if ($usaCount -lt 1 -or ($usaOffset + $usaCount * 2) -gt $Record.Length) { return $false }
        $usn = Get-NtfsLeUInt16 $Record $usaOffset
        for ($i = 1; $i -lt $usaCount; $i++) {
            $sectorEnd = $i * $BytesPerSector - 2
            if (($sectorEnd + 2) -gt $Record.Length) { return $false }
            if ((Get-NtfsLeUInt16 $Record $sectorEnd) -ne $usn) { return $false }
            $stored = Get-NtfsLeUInt16 $Record ($usaOffset + $i * 2)
            $Record[$sectorEnd] = [byte]($stored -band 0xFF)
            $Record[$sectorEnd + 1] = [byte](($stored -shr 8) -band 0xFF)
        }
        return $true
    }

    function Set-NtfsUsaFixup {
        # Re-applies the update-sequence-array fixup in place (in-memory -> on-disk).
        # Exact inverse of Resolve-NtfsUsaFixup, so a record can be patched in its
        # readable form and written back without corrupting the sector tails.
        param([byte[]]$Record, [int]$BytesPerSector)
        $usaOffset = Get-NtfsLeUInt16 $Record 4
        $usaCount = Get-NtfsLeUInt16 $Record 6
        $usn = Get-NtfsLeUInt16 $Record $usaOffset
        for ($i = 1; $i -lt $usaCount; $i++) {
            $sectorEnd = $i * $BytesPerSector - 2
            $real = Get-NtfsLeUInt16 $Record $sectorEnd
            $Record[$usaOffset + $i * 2] = [byte]($real -band 0xFF)
            $Record[$usaOffset + $i * 2 + 1] = [byte](($real -shr 8) -band 0xFF)
            $Record[$sectorEnd] = [byte]($usn -band 0xFF)
            $Record[$sectorEnd + 1] = [byte](($usn -shr 8) -band 0xFF)
        }
    }

    function Get-NtfsAttributeListLocation {
        # Locates the $ATTRIBUTE_LIST attribute inside a fixed-up file record and
        # describes where its value lives (inside the record, or in disk runs).
        param(
            [byte[]]$FileRecord,
            [long]$FileRecordOffset,
            [int]$ClusterSize
        )
        $pos = Get-NtfsLeUInt16 $FileRecord 0x14
        while (($pos + 8) -le $FileRecord.Length) {
            $typeCode = Get-NtfsLeUInt32 $FileRecord $pos
            # Compare against [uint32]::MaxValue: the literal 0xFFFFFFFF parses as
            # Int32 -1, which never equals an unsigned type code.
            if ($typeCode -eq [uint32]::MaxValue) { break }
            $recordLength = Get-NtfsLeUInt32 $FileRecord ($pos + 4)
            if ($recordLength -lt 16 -or ($pos + $recordLength) -gt $FileRecord.Length) { break }

            if ($typeCode -eq 0x20) {
                $isResident = ($FileRecord[$pos + 8] -eq 0)
                if ($isResident) {
                    $valueLength = Get-NtfsLeUInt32 $FileRecord ($pos + 0x10)
                    $valueOffset = Get-NtfsLeUInt16 $FileRecord ($pos + 0x14)
                    if (($pos + $valueOffset + $valueLength) -gt $FileRecord.Length) { return $null }
                    return [PSCustomObject]@{
                        IsResident       = $true
                        DataSize         = [int]$valueLength
                        RecordValueStart = [int]($pos + $valueOffset)
                        Runs             = @()
                    }
                }
                $mappingOffset = Get-NtfsLeUInt16 $FileRecord ($pos + 0x20)
                $dataSize = Get-NtfsLeUInt64 $FileRecord ($pos + 0x30)
                $runs = @(Convert-NtfsMappingPairs -Record $FileRecord -StartOffset ($pos + $mappingOffset))
                if ($runs.Count -eq 0) { return $null }
                return [PSCustomObject]@{
                    IsResident       = $false
                    DataSize         = [int]$dataSize
                    RecordValueStart = -1
                    Runs             = $runs
                }
            }
            $pos += $recordLength
        }
        return $null
    }

    function Get-NtfsVolumeGeometry {
        # Reads NTFS boot-sector geometry through an open raw volume handle.
        param([Parameter(Mandatory)]$Handle)
        # 4096 covers both 512-byte and 4Kn sector sizes in a single aligned read.
        $boot = [RepairAzVMDiskRawVolumeIo]::Read($Handle, 0, 4096)
        if ([System.Text.Encoding]::ASCII.GetString($boot, 3, 4) -ne 'NTFS') {
            throw 'Volume does not carry an NTFS boot sector.'
        }
        $bytesPerSector = Get-NtfsLeUInt16 $boot 0x0B
        # Sectors-per-cluster and clusters-per-record both switch to a signed
        # representation once the value no longer fits a byte: N > 0x80 means
        # 2^(256-N) rather than N literally.
        $rawSectorsPerCluster = $boot[0x0D]
        $sectorsPerCluster = if ($rawSectorsPerCluster -le 0x80) { [int]$rawSectorsPerCluster } else { 1 -shl (256 - $rawSectorsPerCluster) }
        if ($bytesPerSector -le 0 -or $sectorsPerCluster -le 0) { throw 'Invalid NTFS boot sector geometry.' }
        $clusterSize = $bytesPerSector * $sectorsPerCluster
        $rawRecordSize = $boot[0x40]
        $recordSize = if ($rawRecordSize -lt 0x80) { $rawRecordSize * $clusterSize } else { 1 -shl (256 - $rawRecordSize) }
        return [PSCustomObject]@{
            BytesPerSector = [int]$bytesPerSector
            ClusterSize    = [int]$clusterSize
            MftLcn         = [long](Get-NtfsLeUInt64 $boot 0x30)
            RecordSize     = [int]$recordSize
        }
    }

    function Get-NtfsMetafileAttrListState {
        # Read-only scan of the reserved file records on one volume. Reports every
        # ATTRIBUTE_LIST_ENTRY whose NameOffset is not the canonical 0x1a, split into
        # entries this script can repair (0x1c) and entries it will not touch.
        # Never writes; safe to call from diagnostic paths. Pass an already-open
        # handle to scan under a lock the caller is holding.
        param(
            [Parameter(Mandatory)][string]$Volume,
            $Handle = $null
        )

        Initialize-NtfsRawVolumeIo
        $volumePath = ConvertTo-NtfsVolumePath -Volume $Volume
        $result = [PSCustomObject]@{
            Volume     = $volumePath
            Label      = ($volumePath -replace '^\\\\[.?]\\', '')
            Scanned    = $false
            Geometry   = $null
            Records    = @()
            Fixable    = 0
            Unfixable  = 0
            Error      = ''
        }

        $ownsHandle = ($null -eq $Handle)
        $handle = $Handle
        try {
            if ($ownsHandle) { $handle = [RepairAzVMDiskRawVolumeIo]::OpenVolume($volumePath, $false) }
            $geometry = Get-NtfsVolumeGeometry -Handle $handle
            $result.Geometry = $geometry
            $records = [System.Collections.Generic.List[PSCustomObject]]::new()

            for ($frn = 0; $frn -le $script:NtfsAttrListMaxFrn; $frn++) {
                $recordOffset = [long]$geometry.MftLcn * $geometry.ClusterSize + $frn * $geometry.RecordSize
                $record = Read-NtfsVolumeAligned -Handle $handle -Offset $recordOffset -Size $geometry.RecordSize -BytesPerSector $geometry.BytesPerSector

                if ([System.Text.Encoding]::ASCII.GetString($record, 0, 4) -ne 'FILE') { continue }
                $flags = Get-NtfsLeUInt16 $record 0x16
                if (($flags -band 0x01) -eq 0) { continue }
                if (-not (Resolve-NtfsUsaFixup -Record $record -BytesPerSector $geometry.BytesPerSector)) { continue }

                $location = Get-NtfsAttributeListLocation -FileRecord $record -FileRecordOffset $recordOffset -ClusterSize $geometry.ClusterSize
                if ($null -eq $location) { continue }

                # Materialise the attribute-list bytes. Resident lists come from the
                # fixed-up record; non-resident lists are read from their runs, whole
                # runs at a time so the write-back path stays cluster-aligned.
                $listBytes = $null
                if ($location.IsResident) {
                    $listBytes = New-Object byte[] $location.DataSize
                    [Array]::Copy($record, $location.RecordValueStart, $listBytes, 0, $location.DataSize)
                }
                else {
                    $allocated = 0
                    foreach ($run in $location.Runs) { $allocated += [int]($run.Clusters * $geometry.ClusterSize) }
                    if ($allocated -lt $location.DataSize) { continue }
                    $listBytes = New-Object byte[] $allocated
                    $cursor = 0
                    foreach ($run in $location.Runs) {
                        $runBytes = [int]($run.Clusters * $geometry.ClusterSize)
                        $chunk = Read-NtfsVolumeAligned -Handle $handle -Offset ([long]$run.Lcn * $geometry.ClusterSize) -Size $runBytes -BytesPerSector $geometry.BytesPerSector
                        [Array]::Copy($chunk, 0, $listBytes, $cursor, $runBytes)
                        $cursor += $runBytes
                    }
                }

                $entries = [System.Collections.Generic.List[PSCustomObject]]::new()
                $malformed = $false
                $position = 0
                while (($position + 8) -le $location.DataSize) {
                    $typeCode = Get-NtfsLeUInt32 $listBytes $position
                    if ($typeCode -eq 0 -or $typeCode -eq [uint32]::MaxValue) { break }
                    $entryLength = Get-NtfsLeUInt16 $listBytes ($position + 4)
                    if ($entryLength -lt 0x1A -or ($position + $entryLength) -gt $location.DataSize) { $malformed = $true; break }

                    $nameLength = $listBytes[$position + 6]
                    $nameOffset = $listBytes[$position + 7]
                    $name = ''
                    if ($nameLength -gt 0 -and ($nameOffset + $nameLength * 2) -le $entryLength) {
                        $name = [System.Text.Encoding]::Unicode.GetString($listBytes, $position + $nameOffset, $nameLength * 2)
                    }

                    if ($nameOffset -ne $script:NtfsAttrListGoodNameOffset) {
                        $canRepair = ($nameOffset -eq $script:NtfsAttrListBadNameOffset) -and
                                     ($nameLength -gt 0) -and
                                     (($script:NtfsAttrListGoodNameOffset + $nameLength * 2) -le $entryLength) -and
                                     (($nameOffset + $nameLength * 2) -le $entryLength)
                        $entries.Add([PSCustomObject]@{
                            EntryOffset = $position
                            TypeCode    = $typeCode
                            TypeName    = Get-NtfsAttributeTypeName $typeCode
                            NameLength  = $nameLength
                            NameOffset  = $nameOffset
                            Name        = $name
                            CanRepair   = $canRepair
                        })
                    }
                    $position += $entryLength
                }

                if ($entries.Count -gt 0 -or $malformed) {
                    $records.Add([PSCustomObject]@{
                        Frn              = $frn
                        Name             = Get-NtfsMetafileName -Frn $frn
                        IsResident       = $location.IsResident
                        Malformed        = $malformed
                        RecordOffset     = $recordOffset
                        RecordValueStart = $location.RecordValueStart
                        DataSize         = $location.DataSize
                        Runs             = @($location.Runs)
                        Entries          = @($entries)
                    })
                }
            }

            $result.Records = @($records)
            $result.Fixable = @($records | ForEach-Object { $_.Entries } | Where-Object { $_.CanRepair }).Count
            $result.Unfixable = @($records | ForEach-Object { $_.Entries } | Where-Object { -not $_.CanRepair }).Count
            $result.Scanned = $true
        }
        catch {
            $result.Error = $_.Exception.Message
        }
        finally {
            if ($ownsHandle -and $handle -and -not $handle.IsClosed) { $handle.Close() }
        }

        return $result
    }

    function Get-NtfsMetafileName {
        # Friendly name for the well-known reserved file records.
        param([int]$Frn)
        switch ($Frn) {
            0 { '$MFT' }
            1 { '$MFTMirr' }
            2 { '$LogFile' }
            3 { '$Volume' }
            4 { '$AttrDef' }
            5 { '. (root)' }
            6 { '$Bitmap' }
            7 { '$Boot' }
            8 { '$BadClus' }
            9 { '$Secure' }
            10 { '$UpCase' }
            11 { '$Extend' }
            default { "file record $Frn" }
        }
    }

    function Get-NtfsAttrListScanTargets {
        # NTFS volumes on the attached guest disk that currently carry a drive
        # letter. The condition is per-volume, so every NTFS partition is scanned
        # rather than just the Windows partition.
        param([int]$DiskNumber = -1)
        $targets = [System.Collections.Generic.List[string]]::new()
        $number = if ($DiskNumber -ge 0) { $DiskNumber } else { $script:DiskNumber }
        if ($null -eq $number -or $number -lt 0) { return $targets }
        foreach ($partition in (Get-Partition -DiskNumber $number -ErrorAction SilentlyContinue)) {
            if (-not $partition.DriveLetter -or $partition.DriveLetter -eq "`0") { continue }
            $volume = Get-Volume -Partition $partition -ErrorAction SilentlyContinue
            if (-not $volume -or $volume.FileSystemType -ne 'NTFS') { continue }
            $targets.Add("$($partition.DriveLetter):") | Out-Null
        }
        return $targets
    }

    function FixDiskCorruption {
        param([string]$DriveLetter = '')
        $target = if ($DriveLetter) { $DriveLetter.TrimEnd('\') } else { $script:WinDriveLetter.TrimEnd('\') }

        # chkdsk is not a safe repair when a reserved file record carries a
        # non-canonical attribute list name offset: it discards the attribute list
        # rather than correcting the field, which orphans every child record the
        # list referenced - including the $Secure metafile's $SDS stream - and
        # leaves the volume with default security descriptors. Repair that first.
        try {
            $attrGuard = Get-NtfsMetafileAttrListState -Volume $target
            if ($attrGuard.Scanned -and ($attrGuard.Fixable -gt 0 -or $attrGuard.Unfixable -gt 0)) {
                Write-Host ""
                Write-Warning "$target carries NTFS metafile attribute list entries with a non-canonical name offset."
                Show-NtfsAttrListFindings -State $attrGuard
                Write-Warning "chkdsk was NOT run: it discards the whole attribute list instead of correcting the field, which drops the child records it referenced."
                if ($attrGuard.Fixable -gt 0) {
                    Write-Host "  Run -FixNtfsAttributeList -DriveLetter $target first, then repeat -FixFileSystem." -ForegroundColor Cyan
                }
                Write-ActionLog -Event 'FixDiskCorruptionBlocked' -Details @{
                    Target    = $target
                    Reason    = 'Non-canonical NTFS metafile attribute list name offset present'
                    Fixable   = $attrGuard.Fixable
                    Unfixable = $attrGuard.Unfixable
                }
                return
            }
        }
        catch { Write-Warning "Attribute list pre-check failed for ${target}: $_" }

        # Inline helper: run the requested chkdsk mode against $target.
        $runChkdsk = {
            param([ValidateSet('spotfix', 'full')][string]$Mode)
            if ($Mode -eq 'spotfix') {
                # chkdsk /spotfix briefly takes the volume offline and drains the $corrupt queue
                # (the spot-verifier logged-corruption record that drives Get-Volume HealthStatus=Warning).
                # This is the targeted fix that a full chkdsk /F does not reliably perform - common on
                # Windows Server 2012 R2, whose proactive-scan model logs corruption that is retired by
                # spotfix or boot-time/idle maintenance rather than by a one-shot /F pass.
                Write-Host "Running chkdsk /spotfix on $target (drains the spot-verifier `$corrupt queue) ..." -ForegroundColor Yellow
                $chkdskResult = Invoke-NativeCommandLogged -Description 'chkdsk /spotfix' -Details @{
                    Target = $target
                    Mode = 'spotfix'
                } -AcceptedExitCodes @(0, 1, 2) -ScriptBlock { & chkdsk $target /spotfix }
                $chkdskResult.Output | Out-Host
            }
            else {
                Write-Host "Running chkdsk /F /X on $target ..." -ForegroundColor Yellow
                $chkdskResult = Invoke-NativeCommandLogged -Description 'chkdsk /F /X' -Details @{
                    Target = $target
                    Mode = 'full'
                } -AcceptedExitCodes @(0, 1, 2) -ScriptBlock { & chkdsk $target /F /X }
                $chkdskResult.Output | Out-Host
            }
        }

        # Inline helper: probe + print the current NTFS state for $target and report whether it is bad.
        $reportState = {
            param([string]$Phase)
            $st = Get-OfflineVolumeFsState -Letter $target
            $vl = Get-Volume -DriveLetter ($target.TrimEnd(':')) -ErrorAction SilentlyContinue
            $dirtyLabel = if ($st.DirtyBit -eq $true) { 'DIRTY' } elseif ($st.DirtyBit -eq $false) { 'not dirty' } else { 'unknown' }
            $health = if ($vl) { [string]$vl.HealthStatus } else { 'unknown' }
            $bad = ($st.DirtyBit -eq $true) -or ($st.RepairState -eq 'corrupt') -or ($health -ne 'Healthy' -and $health -ne 'unknown')
            $color = if ($bad) { 'Yellow' } else { 'Green' }
            Write-Host "  $target $Phase : dirty bit=$dirtyLabel; spot-verifier (`$corrupt) state=$($st.RepairState); Get-Volume health=$health" -ForegroundColor $color
            return [PSCustomObject]@{ State = $st; Health = $health; IsBad = $bad }
        }

        # Probe first and auto-select the correct repair (no -SpotFix switch needed):
        #   - spot-verifier logged corruption ($corrupt) / Get-Volume Warning WITHOUT the classic
        #     dirty bit          -> chkdsk /spotfix (the only thing that reliably clears it)
        #   - dirty bit set, or state otherwise unclear/healthy -> full chkdsk /F /X
        $before = & $reportState 'before repair'
        $st = $before.State
        $dirty = ($st.DirtyBit -eq $true)
        $spotNeeded = (-not $dirty) -and (($st.RepairState -eq 'corrupt') -or ($before.Health -ne 'Healthy' -and $before.Health -ne 'unknown'))
        $primaryMode = if ($spotNeeded) { 'spotfix' } else { 'full' }

        $ranSpotfix = $false
        $ranFull = $false
        try {
            & $runChkdsk $primaryMode
            if ($primaryMode -eq 'spotfix') { $ranSpotfix = $true } else { $ranFull = $true }
        }
        catch {
            Write-Error "FixDiskCorruption failed: $_"
            return
        }

        $after = & $reportState 'after repair '

        # Follow-up: if the primary pass did not clear it, run the other mode once.
        if ($after.IsBad) {
            $followMode = if ($primaryMode -eq 'spotfix') { 'full' } else { 'spotfix' }
            Write-Host "  Still not clean after chkdsk /$primaryMode - running chkdsk /$followMode as a follow-up ..." -ForegroundColor DarkCyan
            try {
                & $runChkdsk $followMode
                if ($followMode -eq 'spotfix') { $ranSpotfix = $true } else { $ranFull = $true }
            }
            catch {
                Write-Warning "Follow-up chkdsk /$followMode failed: $_"
            }
            $after = & $reportState 'after follow-up'
        }

        if ($after.IsBad) {
            Write-Host "  $target is still not Healthy after offline repair. The corruption may only be retired by booting the guest (autochk / ProactiveScan maintenance), or it may be a genuine on-disk fault." -ForegroundColor Yellow
        }

        $modeList = [System.Collections.Generic.List[string]]::new()
        if ($ranFull) { $modeList.Add('full (/F /X)') }
        if ($ranSpotfix) { $modeList.Add('spotfix') }

        Write-ActionLog -Event 'FixDiskCorruption' -Details @{
            Target       = $target
            Mode         = ($modeList -join ' + ')
            DirtyBefore  = $before.State.DirtyBit
            DirtyAfter   = $after.State.DirtyBit
            RepairBefore = $before.State.RepairState
            RepairAfter  = $after.State.RepairState
            HealthAfter  = $after.Health
        }
    }

    function Set-NtfsAttrListEntryNameOffset {
        # Rewrites one ATTRIBUTE_LIST_ENTRY to the canonical layout: shifts the
        # attribute name back two bytes and sets NameOffset to 0x1a.
        #
        # RecordLength is deliberately left untouched. The entry keeps its original
        # size and the two freed trailing bytes become zero padding, so neither the
        # attribute list's length nor its on-disk allocation changes - which is what
        # keeps this a single-record edit rather than a structural rewrite.
        param(
            [Parameter(Mandatory)][byte[]]$Buffer,
            [Parameter(Mandatory)][int]$EntryStart,
            [Parameter(Mandatory)][int]$NameLength
        )
        $good = $script:NtfsAttrListGoodNameOffset
        $bad = $script:NtfsAttrListBadNameOffset
        $byteCount = $NameLength * 2
        $nameBytes = New-Object byte[] $byteCount
        [Array]::Copy($Buffer, $EntryStart + $bad, $nameBytes, 0, $byteCount)
        for ($i = 0; $i -lt $byteCount; $i++) { $Buffer[$EntryStart + $bad + $i] = 0 }
        [Array]::Copy($nameBytes, 0, $Buffer, $EntryStart + $good, $byteCount)
        $Buffer[$EntryStart + 7] = [byte]$good
    }

    function Show-NtfsAttrListFindings {
        # Console rendering shared by the scan and repair paths.
        param([Parameter(Mandatory)]$State)
        if ($State.Records.Count -eq 0) {
            Write-Host "  [OK] $($State.Label): all attribute list entries use the canonical name offset." -ForegroundColor Green
            return
        }
        foreach ($record in $State.Records) {
            if ($record.Malformed) {
                Write-Host "  $($State.Label) $($record.Name): attribute list is truncated or malformed - not repairable here." -ForegroundColor Red
            }
            foreach ($entry in $record.Entries) {
                $label = if ($entry.Name) { "$($entry.TypeName):$($entry.Name)" } else { $entry.TypeName }
                $offsetText = "0x$($entry.NameOffset.ToString('x2'))"
                if ($entry.CanRepair) {
                    Write-Host "  $($State.Label) $($record.Name): $label  NameOffset=$offsetText (repairable)" -ForegroundColor Yellow
                }
                else {
                    Write-Host "  $($State.Label) $($record.Name): $label  NameOffset=$offsetText (not repairable)" -ForegroundColor Red
                }
            }
        }
    }

    function Repair-NtfsAttrListVolume {
        # Applies the canonical name offset to one volume. The volume is locked and
        # dismounted first, then re-scanned through the same handle so the repair
        # acts on exactly the bytes it validated. Every region is captured to a
        # restore manifest before the first write.
        param([Parameter(Mandatory)][string]$Volume)

        $volumePath = ConvertTo-NtfsVolumePath -Volume $Volume
        $label = $volumePath -replace '^\\\\[.?]\\', ''
        $handle = $null
        $locked = $false
        $repaired = 0
        $backupPath = ''

        try {
            try {
                $handle = [RepairAzVMDiskRawVolumeIo]::OpenVolume($volumePath, $true)
                [RepairAzVMDiskRawVolumeIo]::LockVolume($handle)
                $locked = $true
                [RepairAzVMDiskRawVolumeIo]::DismountVolume($handle)
            }
            catch {
                Write-Warning "$label could not be locked for exclusive access: $($_.Exception.Message)"
                Write-Warning "Close any open handles to $label and unload offline hives (-UnloadHive SYSTEM, SOFTWARE, ...) before retrying."
                return 0
            }

            $state = Get-NtfsMetafileAttrListState -Volume $volumePath -Handle $handle
            if (-not $state.Scanned) { throw "Re-scan under volume lock failed: $($state.Error)" }
            $geometry = $state.Geometry

            # Pass 1: compute every byte range that will change. Nothing is written yet.
            $operations = [System.Collections.Generic.List[PSCustomObject]]::new()
            $planned = [System.Collections.Generic.List[string]]::new()

            foreach ($record in $state.Records) {
                $fixable = @($record.Entries | Where-Object { $_.CanRepair })
                if ($fixable.Count -eq 0) { continue }

                if ($record.IsResident) {
                    $frs = Read-NtfsVolumeAligned -Handle $handle -Offset $record.RecordOffset -Size $geometry.RecordSize -BytesPerSector $geometry.BytesPerSector
                    $original = $frs.Clone()
                    if (-not (Resolve-NtfsUsaFixup -Record $frs -BytesPerSector $geometry.BytesPerSector)) {
                        Write-Warning "  $label $($record.Name): update sequence check failed on re-read; skipped."
                        continue
                    }
                    foreach ($entry in $fixable) {
                        Set-NtfsAttrListEntryNameOffset -Buffer $frs -EntryStart ($record.RecordValueStart + $entry.EntryOffset) -NameLength $entry.NameLength
                    }
                    # Restore the sector tails so the record is written back in on-disk form.
                    Set-NtfsUsaFixup -Record $frs -BytesPerSector $geometry.BytesPerSector
                    $operations.Add([PSCustomObject]@{ Offset = [long]$record.RecordOffset; Original = $original; Updated = $frs }) | Out-Null
                }
                else {
                    $allocated = 0
                    foreach ($run in $record.Runs) { $allocated += [int]($run.Clusters * $geometry.ClusterSize) }
                    $buffer = New-Object byte[] $allocated
                    $cursor = 0
                    foreach ($run in $record.Runs) {
                        $runBytes = [int]($run.Clusters * $geometry.ClusterSize)
                        $chunk = Read-NtfsVolumeAligned -Handle $handle -Offset ([long]$run.Lcn * $geometry.ClusterSize) -Size $runBytes -BytesPerSector $geometry.BytesPerSector
                        [Array]::Copy($chunk, 0, $buffer, $cursor, $runBytes)
                        $cursor += $runBytes
                    }
                    $original = $buffer.Clone()
                    foreach ($entry in $fixable) {
                        Set-NtfsAttrListEntryNameOffset -Buffer $buffer -EntryStart $entry.EntryOffset -NameLength $entry.NameLength
                    }
                    # Attribute list runs are not update-sequence protected; write them back verbatim.
                    $cursor = 0
                    foreach ($run in $record.Runs) {
                        $runBytes = [int]($run.Clusters * $geometry.ClusterSize)
                        $originalSlice = New-Object byte[] $runBytes
                        $updatedSlice = New-Object byte[] $runBytes
                        [Array]::Copy($original, $cursor, $originalSlice, 0, $runBytes)
                        [Array]::Copy($buffer, $cursor, $updatedSlice, 0, $runBytes)
                        $operations.Add([PSCustomObject]@{
                            Offset   = [long]($run.Lcn * $geometry.ClusterSize)
                            Original = $originalSlice
                            Updated  = $updatedSlice
                        }) | Out-Null
                        $cursor += $runBytes
                    }
                }

                foreach ($entry in $fixable) {
                    $name = if ($entry.Name) { "$($entry.TypeName):$($entry.Name)" } else { $entry.TypeName }
                    $planned.Add("$($record.Name) ($($entry.TypeName)$(if ($entry.Name) { ":$($entry.Name)" }))") | Out-Null
                    $repaired++
                }
            }

            if ($operations.Count -eq 0) {
                Write-Host "  ${label}: nothing to repair." -ForegroundColor DarkGray
                return 0
            }

            # Capture the pre-image of every region before the first write, so the
            # volume can be put back byte for byte if the result is not what we want.
            try {
                $backupDir = Split-Path -Parent $script:ActionLogPath
                $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
                $safeLabel = $label -replace '[^A-Za-z0-9]', ''
                $backupPath = Join-Path $backupDir "Repair-AzVMDisk_attrlist_${safeLabel}_${stamp}.json"
                $manifest = [ordered]@{
                    Volume         = $volumePath
                    CapturedUtc    = (Get-Date).ToUniversalTime().ToString('o')
                    BytesPerSector = $geometry.BytesPerSector
                    Regions        = @($operations | ForEach-Object {
                            [ordered]@{ Offset = $_.Offset; Length = $_.Original.Length; OriginalBase64 = [Convert]::ToBase64String($_.Original) }
                        })
                }
                $manifest | ConvertTo-Json -Depth 6 | Out-File -FilePath $backupPath -Encoding UTF8
                Write-Host "  Saved pre-repair image of $($operations.Count) region(s) to $backupPath" -ForegroundColor DarkCyan
            }
            catch {
                throw "Refusing to write: the pre-repair backup could not be saved ($($_.Exception.Message))."
            }

            # Pass 2: apply.
            foreach ($operation in $operations) {
                Write-NtfsVolumeAligned -Handle $handle -Offset $operation.Offset -Data $operation.Updated -BytesPerSector $geometry.BytesPerSector
            }
            [RepairAzVMDiskRawVolumeIo]::Flush($handle)

            # Verify through the same locked handle before releasing the volume.
            $verify = Get-NtfsMetafileAttrListState -Volume $volumePath -Handle $handle
            if (-not $verify.Scanned) {
                Write-Warning "  ${label}: repair written but the verification pass could not run - $($verify.Error)"
            }
            elseif ($verify.Fixable -gt 0) {
                Write-Warning "  ${label}: $($verify.Fixable) entry/entries still report a non-canonical name offset after the repair."
            }
            else {
                foreach ($item in $planned) {
                    Write-Host "  [OK] $label $item  NameOffset 0x1c -> 0x1a" -ForegroundColor Green
                }
                Write-Host "  [OK] $label verified: all attribute list entries now use the canonical name offset." -ForegroundColor Green
            }

            Write-ActionLog -Event 'FixNtfsAttributeList' -Details @{
                Volume         = $volumePath
                EntriesFixed   = $repaired
                RegionsWritten = $operations.Count
                BackupPath     = $backupPath
                VerifiedClean  = ($verify.Scanned -and $verify.Fixable -eq 0)
            }

            return $repaired
        }
        catch {
            Write-Error "Attribute list repair failed on ${label}: $_"
            if ($backupPath) { Write-Warning "The pre-repair image is available at $backupPath" }
            return 0
        }
        finally {
            if ($handle -and -not $handle.IsClosed) {
                if ($locked) { try { [RepairAzVMDiskRawVolumeIo]::UnlockVolume($handle) } catch { } }
                $handle.Close()
            }
        }
    }

    function FixNtfsAttributeList {
        # Repairs reserved-file-record attribute list entries whose NameOffset is
        # 0x1c instead of the canonical 0x1a. Newer NTFS revisions reject that
        # layout while resolving the referenced stream and fail the volume mount,
        # which the guest shows as a boot loop with bugcheck 0x24 (NTFS_FILE_SYSTEM).
        param([string]$DriveLetter = '')

        Write-Host "Inspecting NTFS metafile attribute lists..." -ForegroundColor Yellow
        Initialize-NtfsRawVolumeIo

        $targets = if ($DriveLetter) { @($DriveLetter.TrimEnd('\')) } else { @(Get-NtfsAttrListScanTargets -DiskNumber $script:DiskNumber) }
        if ($targets.Count -eq 0) {
            Write-Warning "No lettered NTFS volume was found on disk $script:DiskNumber to inspect."
            return
        }

        $states = [System.Collections.Generic.List[PSCustomObject]]::new()
        foreach ($target in $targets) {
            $state = Get-NtfsMetafileAttrListState -Volume $target
            if (-not $state.Scanned) {
                Write-Warning "$($state.Label) could not be inspected: $($state.Error)"
                continue
            }
            Show-NtfsAttrListFindings -State $state
            $states.Add($state) | Out-Null
        }

        $repairable = @($states | Where-Object { $_.Fixable -gt 0 })
        $blocked = @($states | Where-Object { $_.Unfixable -gt 0 -or ($_.Records | Where-Object { $_.Malformed }) })

        if ($repairable.Count -eq 0) {
            if ($blocked.Count -gt 0) {
                Write-Host ""
                Write-Warning "Non-canonical attribute list entries were found that this repair does not cover."
                Write-Warning "Do not run chkdsk against the affected volume(s): it discards the attribute list rather than correcting it, which drops the child records it referenced."
            }
            else {
                Write-Host "  [OK] No attribute list name offset problem found." -ForegroundColor Green
            }
            return
        }

        $detail = ($repairable | ForEach-Object {
                $names = (@($_.Records | Where-Object { @($_.Entries | Where-Object { $_.CanRepair }).Count -gt 0 } | ForEach-Object { $_.Name }) -join ', ')
                "  $($_.Label): $($_.Fixable) entry/entries in $names"
            }) -join "`n"

        if (-not (Confirm-CriticalOperation -Operation 'Repair NTFS metafile attribute list name offsets (-FixNtfsAttributeList)' -Details @"
Rewrites ATTRIBUTE_LIST_ENTRY.NameOffset from 0x1c to the canonical 0x1a and
shifts the attribute name back two bytes on:
$detail

Each affected volume is locked and dismounted for the write, then re-scanned to
confirm the result. Record lengths, allocation and every other structure are left
unchanged, and the original bytes of every region are written to a restore
manifest next to the action log before anything is modified.

The volume(s) will be dismounted during the write, so any offline registry hive
loaded from them must be unloaded first.
"@)) { return }

        $total = 0
        foreach ($state in $repairable) {
            $total += [int](Repair-NtfsAttrListVolume -Volume $state.Volume)
        }

        Write-Host ""
        if ($total -gt 0) {
            Write-Host "COMPLETE: $total attribute list entry/entries repaired." -ForegroundColor Green
            Write-Host "Reattach the disk and boot the guest to confirm the volume mounts." -ForegroundColor Cyan
        }
        else {
            Write-Warning "No entry was repaired."
        }
    }

    function RunDismHealth {
        param([string]$RepairSource = '')

        Write-Host "Repairing component store (DISM ScanHealth + RestoreHealth)..." -ForegroundColor Yellow
        try {
            if (-not (Test-Path "C:\temp")) { mkdir C:\temp | Out-Null }

            # Detect guest OS build to warn about version mismatch with host
            $guestBuild = (Get-GuestCurrentVersion).CurrentBuildNumber
            $hostBuild = [System.Environment]::OSVersion.Version.Build

            # Determine repair source
            $sourceArg = ''
            $mountedIso = $null
            $extractedCab = $null

            if ($RepairSource) {
                if (-not (Test-Path $RepairSource)) {
                    Write-Error "RepairSource file not found: $RepairSource"
                    return
                }

                $ext = [System.IO.Path]::GetExtension($RepairSource).ToLower()
                switch ($ext) {
                    '.iso' {
                        Write-Host "Mounting ISO: $RepairSource" -ForegroundColor Cyan
                        $mountedIso = (Resolve-Path $RepairSource).Path
                        $mountResult = Mount-DiskImage -ImagePath $mountedIso -PassThru
                        $isoDrive = ($mountResult | Get-Volume).DriveLetter
                        $wimPath = "$($isoDrive):\sources\install.wim"
                        if (-not (Test-Path $wimPath)) {
                            Write-Error "install.wim not found at $wimPath inside the ISO."
                            return
                        }
                        Write-Host "Available images in WIM:" -ForegroundColor Cyan
                        & dism /Get-WimInfo /WimFile:"$wimPath" | Out-Host
                        $wimIndex = Read-Host "Enter the image index to use as repair source (e.g. 1, 2, 3)"
                        $sourceArg = "/Source:wim:$($wimPath):$wimIndex /LimitAccess"
                        Write-Host "Using ISO source: wim:$($wimPath):$wimIndex" -ForegroundColor Green
                    }
                    '.wim' {
                        Write-Host "Available images in WIM:" -ForegroundColor Cyan
                        & dism /Get-WimInfo /WimFile:"$RepairSource" | Out-Host
                        $wimIndex = Read-Host "Enter the image index to use as repair source (e.g. 1, 2, 3)"
                        $sourceArg = "/Source:wim:$($RepairSource):$wimIndex /LimitAccess"
                        Write-Host "Using WIM source: wim:$($RepairSource):$wimIndex" -ForegroundColor Green
                    }
                    '.msu' {
                        Write-Host "Extracting .msu to C:\temp\RepairSource_msu ..." -ForegroundColor Cyan
                        $msuExtract = 'C:\temp\RepairSource_msu'
                        if (Test-Path $msuExtract) { Remove-Item $msuExtract -Recurse -Force }
                        New-Item $msuExtract -ItemType Directory -Force | Out-Null
                        & expand.exe -F:* $RepairSource $msuExtract | Out-Null
                        $cabFile = Get-ChildItem $msuExtract -Filter '*.cab' | Where-Object { $_.Name -ne 'WSUSSCAN.cab' } | Select-Object -First 1
                        if (-not $cabFile) {
                            Write-Error "No payload .cab found inside the .msu."
                            return
                        }
                        Write-Host "Extracted cab: $($cabFile.Name)" -ForegroundColor Cyan
                        $sourceArg = "/Source:$($cabFile.FullName) /LimitAccess"
                        $extractedCab = $msuExtract
                        Write-Host "Using MSU/CAB source: $($cabFile.FullName)" -ForegroundColor Green
                    }
                    '.cab' {
                        $sourceArg = "/Source:$RepairSource /LimitAccess"
                        Write-Host "Using CAB source: $RepairSource" -ForegroundColor Green
                    }
                    default {
                        Write-Error "Unsupported RepairSource format '$ext'. Accepted: .wim, .iso, .msu, .cab"
                        return
                    }
                }
            }
            else {
                # No explicit source - check version match
                if ($guestBuild -and $hostBuild -and $guestBuild -ne "$hostBuild") {
                    Write-Warning "Guest OS build ($guestBuild) differs from host OS build ($hostBuild)."
                    Write-Warning "DISM /RestoreHealth will use the host's WinSxS as source, which may not have"
                    Write-Warning "matching components for the guest OS - this typically causes CBS_E_SOURCE_MISSING."
                    Write-Warning ""
                    Write-Warning "To provide a matching source, use one of:"
                    Write-Warning "  -RepairComponentStore -RepairSource <path-to-install.wim>"
                    Write-Warning "  -RepairComponentStore -RepairSource <path-to-.iso>"
                    Write-Warning "  -RepairComponentStore -RepairSource <path-to-cumulative-update.msu>"
                    Write-Warning ""
                    Write-Warning "Tip: Run -AnalyzeComponentStore first to identify exactly which components are"
                    Write-Warning "corrupt and which KB/update you need to download."
                    Write-Warning ""
                    $answer = Read-Host "Continue anyway with host WinSxS as source? [Y/N] (default: N)"
                    if ($answer -ne 'Y' -and $answer -ne 'y') {
                        Write-Host "Skipped. Run -AnalyzeComponentStore to identify the needed update." -ForegroundColor DarkGray
                        return
                    }
                }
                $sourceArg = "/Source:C:\Windows\WinSxS /LimitAccess"
            }

            Write-Host "Step 1/2: ScanHealth" -ForegroundColor Cyan
            $scanResult = Invoke-NativeCommandLogged -Description 'DISM ScanHealth' -Details @{
                Image = $script:WinDriveLetter
            } -ScriptBlock { & dism /Image:$script:WinDriveLetter /Cleanup-Image /ScanHealth /ScratchDir:C:\Temp }
            $scanResult.Output | Out-Host

            Write-Host "Step 2/2: RestoreHealth" -ForegroundColor Cyan
            $restoreCmd = "dism /Image:$($script:WinDriveLetter) /Cleanup-Image /RestoreHealth $sourceArg /ScratchDir:C:\Temp"
            Write-Host "  [exec] $restoreCmd" -ForegroundColor DarkGray
            $restoreResult = Invoke-NativeCommandLogged -Description 'DISM RestoreHealth' -Details @{
                Command = $restoreCmd
                Image = $script:WinDriveLetter
                RepairSource = $RepairSource
            } -ScriptBlock { & cmd.exe /c $restoreCmd }
            $restoreResult.Output | Out-Host
        }
        catch {
            Write-Error "RepairComponentStore failed: $_"
            throw
        }
        finally {
            if ($mountedIso -and (Get-DiskImage -ImagePath $mountedIso -ErrorAction SilentlyContinue).Attached) {
                Write-Host "Dismounting ISO..." -ForegroundColor Cyan
                Dismount-DiskImage -ImagePath $mountedIso | Out-Null
            }
            if ($extractedCab -and (Test-Path $extractedCab)) {
                Remove-Item $extractedCab -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    function RunSFC {
        Write-Host "Executing SFC /scannow"
        try {
            $sfcCmd = "sfc /SCANNOW /OFFBOOTDIR=$script:WinDriveLetter /OFFWINDIR=$($script:WinDriveLetter)windows"
            Write-Host "  [exec] $sfcCmd" -ForegroundColor DarkGray
            $sfcResult = Invoke-NativeCommandLogged -Description 'SFC offline scan and repair' -Details @{
                Command = $sfcCmd
                OffBootDir = $script:WinDriveLetter
                OffWinDir = "$($script:WinDriveLetter)windows"
            } -ScriptBlock {
                & sfc /SCANNOW /OFFBOOTDIR=$script:WinDriveLetter /OFFWINDIR=$($script:WinDriveLetter)windows
            }
            $sfcResult.Output | Out-Host
        }
        catch {
            Write-Error "RunSFC failed: $_"
        }
    }

    function SetLKGC {
        Invoke-WithHive 'SYSTEM' {
            $CurrentBoot = (Get-ItemProperty -Path "HKLM:\BROKENSYSTEM\Select" -Name Current).Current
            $LastKnownGood = (Get-ItemProperty -Path "HKLM:\BROKENSYSTEM\Select" -Name LastKnownGood).LastKnownGood
            Write-Host "Current HKLM: $CurrentBoot`r`nLast Known Good: $LastKnownGood" -ForegroundColor Green
            Write-Host "`r`nSetting next boot to LKGD: $LastKnownGood" -ForegroundColor Yellow
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Select" -Name Current -Value $LastKnownGood -Type DWord -Force
        }
    }

    function RevertLKGC {
        Invoke-WithHive 'SYSTEM' {
            $CurrentBoot = (Get-ItemProperty -Path "HKLM:\BROKENSYSTEM\Select" -Name Current).Current
            Write-Host "Current HKLM: $CurrentBoot" -ForegroundColor Green

            # Pick a control set other than the current one. Parse the numeric suffix
            # robustly (strip all non-digits) so ControlSet010+ is handled correctly;
            # the old 'ControlSet00' trim produced wrong numbers / parse errors for those.
            $NextSetting = Get-ChildItem 'HKLM:\BROKENSYSTEM' |
                Where-Object { $_.PSChildName -like 'ControlSet*' } |
                ForEach-Object { [int]($_.PSChildName -replace '\D', '') } |
                Where-Object { $_ -ne $CurrentBoot } |
                Select-Object -First 1

            Write-Host "`r`nSetting boot registry to: $NextSetting" -ForegroundColor Yellow
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Select" -Name Current -Value $NextSetting -Type DWord -Force
        }
    }

    function SetBootLog {
        $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
        $identifier = Get-BcdBootLoaderId -StorePath $storePath
    
        if (-not $identifier) { return }
    
        Write-Host "Enabling boot logging..." -ForegroundColor Green

        $NtBtLog = Join-Path $script:WinDriveLetter "Windows\ntbtlog.txt"
        if (Test-Path $NtBtLog) {
            Write-Host "Deleting existing ntbtlog.txt..." -ForegroundColor Yellow
            Remove-Item-Logged -Path $NtBtLog -Force
        }

        Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier bootlog yes"
    }

    function SetSafeMode {
        $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
        $identifier = Get-BcdBootLoaderId -StorePath $storePath
    
        if (-not $identifier) { return }
    
        Write-Host "Setting Safe Mode minimal flag..." -ForegroundColor Green
        Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier safeboot minimal"
    }

    function RemoveSafeMode {
        $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
        $identifier = Get-BcdBootLoaderId -StorePath $storePath
    
        if (-not $identifier) { return }
    
        Write-Host "Removing Safe Mode flag..."
        Invoke-BcdEdit -StorePath $storePath -Command "/deletevalue $identifier safeboot"
    }

    function ConfigureFullMemDump {
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath

            Write-Host "Configuring full memory dump settings..." -ForegroundColor Yellow
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name CrashDumpEnabled -Value 1 -Type DWord -Force
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name DumpFile -Value "%SystemRoot%\MEMORY.DMP" -Type ExpandString -Force
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name DedicatedDumpFile -Value "C:\DD.sys" -Type String -Force
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name Overwrite -Value 1 -Type DWord -Force
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name NMICrashDump -Value 1 -Type DWord -Force
            Set-ItemProperty-Logged -Path "$SystemRoot\Control\CrashControl" -Name AutoReboot -Value 1 -Type DWord -Force

            Write-Host "Check for dump as '%SystemRoot%\MEMORY.DMP' (usually C:\Windows\MEMORY.DMP)." -ForegroundColor Green

            $CurrentPagefile = (Get-ItemProperty -Path "$SystemRoot\Control\Session Manager\Memory Management" -Name PagingFiles).PagingFiles
            if ($CurrentPagefile -notmatch "C:") {
                Write-Host "Configuring pagefile to C: drive..." -ForegroundColor Yellow
                Set-ItemProperty-Logged -Path "$SystemRoot\Control\Session Manager\Memory Management" -Name PagingFiles -Value "C:\pagefile.sys 0 0" -Type MultiString -Force
            }
        }
    }

    function RebuildBCD {
        try {
            # Guard: verify the boot partition exists before trying to write to it
            $rbcPartitions = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue
            if ($script:VMGen -eq 2) {
                $rbcEsp = $rbcPartitions | Where-Object { $_.Type -eq 'System' }
                if (-not $rbcEsp) {
                    Write-Error "EFI System Partition does not exist on disk $($script:DiskNumber). Run -RecreateBootPartition first to create the ESP, then -FixBoot if needed."
                    return
                }
            }
            else {
                $rbcWinTrimmed = $script:WinDriveLetter.TrimEnd('\')
                $rbcBootTrimmed = $script:BootDriveLetter.TrimEnd('\')
                if ($rbcWinTrimmed -eq $rbcBootTrimmed) {
                    # Boot and Windows are the same drive - check it's Active
                    $rbcWinPart = $rbcPartitions | Where-Object {
                        $_.AccessPaths | Where-Object { $_ -and $_.TrimEnd('\') -eq $rbcWinTrimmed }
                    }
                    if ($rbcWinPart -and -not $rbcWinPart.IsActive) {
                        Write-Warning "Windows partition is not Active. Setting Active flag so BIOS can find the boot sector..."
                        Invoke-Logged -Description 'Set Windows partition Active for BIOS boot' -Details @{
                            DiskNumber = $script:DiskNumber
                            PartitionNumber = $rbcWinPart.PartitionNumber
                            IsActive = $true
                        } -ScriptBlock {
                            Set-Partition -DiskNumber $script:DiskNumber -PartitionNumber $rbcWinPart.PartitionNumber -IsActive $true
                        } | Out-Null
                    }
                }
            }

            # Pre-flight: bcdboot requires the BCD-Template hive to create a new BCD store.
            # If it is missing, bcdboot will fail with BFSVC error c000000f (cannot open BCD template store).
            $bcdTemplatePath = Join-Path $script:WinDriveLetter 'Windows\System32\config\BCD-Template'
            if (-not (Test-Path -LiteralPath $bcdTemplatePath)) {

                # Check whether the host can supply a matching copy before reporting an error
                $hostTemplate = "$env:SystemRoot\System32\config\BCD-Template"
                $guestBuildNum = (Get-GuestCurrentVersion).CurrentBuildNumber
                $hostBuildNum = [System.Environment]::OSVersion.Version.Build.ToString()
                $buildsMatch = $guestBuildNum -and ($guestBuildNum -eq $hostBuildNum)

                if ((Test-Path -LiteralPath $hostTemplate) -and $buildsMatch) {
                    # Offer to copy the file from the host and continue with -FixBoot
                    $doCopy = Confirm-CriticalOperation `
                        -Operation 'Restore BCD-Template from host before rebuilding BCD' `
                        -Details @"
BCD-Template hive is missing from the guest:
  $bcdTemplatePath

A compatible copy was found on this host (guest and host are both build $hostBuildNum).
The script will copy it to the guest before running bcdboot, then proceed with -FixBoot normally.

  Source : $hostTemplate
  Target : $bcdTemplatePath
"@
                    if ($doCopy) {
                        Copy-Item-Logged -Path $hostTemplate -Destination $bcdTemplatePath -Force
                        Write-Host "  [OK] BCD-Template copied from host. Proceeding with BCD rebuild." -ForegroundColor Green
                    }
                    else {
                        $script:_userFacingError = $true
                        throw "BCD-Template hive is missing: $bcdTemplatePath"
                    }
                }
                else {
                    # No usable copy available on this host - print actionable error and stop
                    $guestLabel = if ($guestBuildNum) { "build $guestBuildNum" } else { 'unknown build' }
                    Write-Host "`n[ERROR] -FixBoot pre-flight check failed" -ForegroundColor Red
                    Write-Host "  BCD-Template hive is missing: $bcdTemplatePath" -ForegroundColor Red
                    Write-Host "  bcdboot requires this file to rebuild the BCD store." -ForegroundColor Yellow
                    if ((Test-Path -LiteralPath $hostTemplate)) {
                        Write-Host "  Note  : A BCD-Template exists on this host (build $hostBuildNum) but the guest is $guestLabel." -ForegroundColor Yellow
                        Write-Host "          Using a mismatched copy may cause subtle boot issues." -ForegroundColor Yellow
                    }
                    Write-Host "  Fix   : Copy BCD-Template from a source matching the guest OS version, then re-run -FixBoot." -ForegroundColor Yellow
                    Write-Host "          (e.g. mount a matching WinPE/recovery ISO and copy from X:\Windows\System32\config\BCD-Template)" -ForegroundColor Yellow
                    $script:_userFacingError = $true
                    throw "BCD-Template hive is missing: $bcdTemplatePath"
                }
            }

            $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter

            # Backup existing BCD if present
            if (Test-Path -LiteralPath $storePath) {
                $bakPath = New-UniqueBackupPath -BasePath $storePath -BakSuffix ".bak"
                Write-Host "Renaming BCD: $storePath -> $bakPath"
                Move-Item-Logged -LiteralPath $storePath -Destination $bakPath -Force
            }
            else {
                Write-Warning "BCD not found at $storePath; will still run bcdboot to create a fresh store."
            }

            # Prepare drive letters (strip trailing backslashes for bcdboot syntax)
            $WinDrive = $script:WinDriveLetter.TrimEnd('\')
            $SysDrive = $script:BootDriveLetter.TrimEnd('\')

            # Rebuild BCD from scratch
            $format = if ($script:VMGen -eq 1) { "BIOS" } else { "UEFI" }
            $rebuildCmd = "bcdboot $WinDrive\Windows /s $SysDrive /v /f $format"
            Write-Host "Rebuilding BCD (Gen$script:VMGen): $rebuildCmd"
            $bcdbootResult = Invoke-NativeCommandLogged -Description 'bcdboot rebuild BCD' -Details @{
                Command = $rebuildCmd
                StorePath = $storePath
                Generation = $script:VMGen
            } -ScriptBlock { & cmd.exe /c $rebuildCmd }
            $bcdbootResult.Output | Out-Host
            if ($bcdbootResult.ExitCode -ne 0) {
                # bcdboot failed - restore original BCD if we backed it up
                if ($bakPath -and (Test-Path -LiteralPath $bakPath)) {
                    Write-Warning "bcdboot failed (exit $($bcdbootResult.ExitCode)). Restoring original BCD from backup: $bakPath -> $storePath"
                    Move-Item-Logged -LiteralPath $bakPath -Destination $storePath -Force
                }
                throw "bcdboot failed with exit code $($bcdbootResult.ExitCode). BCD was not created. See BFSVC output above for details."
            }

            # Verify rebuild
            $verifyCmd = "bcdedit /store `"$storePath`" /enum"
            Write-Host "Verifying: $verifyCmd"
            & cmd.exe /c $verifyCmd | Out-Host

            # Get boot loader identifier
            $identifier = Get-BcdBootLoaderId -StorePath $storePath
            if (-not $identifier) { return }

            $originalBcdInventory = $script:BcdInventory
            $originalLoaders = @($originalBcdInventory.Loaders)
            $originalSetupLoaders = @($originalLoaders | Where-Object { $_.IsSetupEntry })
            if ($script:SelectedWindowsInstall) {
                $selectedBuild = Format-WindowsBuildLabel -Build $script:SelectedWindowsInstall.CurrentBuildNumber -Ubr $script:SelectedWindowsInstall.UBR -Fallback 'unknown'
                Write-Host "Selected Windows install for BCD rebuild: $($script:SelectedWindowsInstall.Drive) ($($script:SelectedWindowsInstall.ProductName), build $selectedBuild)" -ForegroundColor Cyan
            }
            if ($originalSetupLoaders.Count -gt 0) {
                $setupLabels = ($originalSetupLoaders | ForEach-Object { if ($_.Description) { $_.Description } else { $_.Identifier } }) -join ', '
                Write-Host "Detected setup/stale BCD loader entries in the previous store: $setupLabels" -ForegroundColor Yellow
                Write-Host "The rebuilt store will boot directly into the selected Windows installation." -ForegroundColor Yellow
            }

            # Apply additional boot configuration flags (same for both Gen1 and Gen2)
            $extraCmds = @(
                "/set {bootmgr} default $identifier",
                "/set {bootmgr} integrityservices enable",
                "/set $identifier integrityservices enable",
                "/set $identifier recoveryenabled Off",
                "/set $identifier bootstatuspolicy IgnoreAllFailures",
                "/set {bootmgr} displaybootmenu yes",
                "/set {bootmgr} timeout 5",
                "/set {bootmgr} bootems yes",
                "/ems $identifier on",
                "/emssettings EMSPORT:1 EMSBAUDRATE:115200"
            )

            foreach ($cmd in $extraCmds) {
                Write-Host "Applying extra setting: $cmd" -ForegroundColor Yellow
                Invoke-BcdEdit -StorePath $storePath -Command $cmd
            }

            $script:BcdInventory = Get-BcdInventory -StorePath $storePath

            # Gen1 (BIOS/MBR): ensure the boot partition is marked as Active.
            # Without the Active flag the BIOS has no way to find the boot sector
            # and the VM fails with a black screen / "No bootable device".
            if ($script:VMGen -eq 1) {
                $bootPartition = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.AccessPaths | Where-Object {
                        $_ -and $script:BootDriveLetter.TrimEnd('\') -eq $_.TrimEnd('\')
                    }
                }
                if ($bootPartition -and -not $bootPartition.IsActive) {
                    Write-Host "Boot partition (Partition $($bootPartition.PartitionNumber)) is not marked Active - setting Active flag..." -ForegroundColor Yellow
                    Invoke-Logged -Description 'Set boot partition Active' -Details @{
                        DiskNumber = $script:DiskNumber
                        PartitionNumber = $bootPartition.PartitionNumber
                        IsActive = $true
                    } -ScriptBlock {
                        Set-Partition -DiskNumber $script:DiskNumber -PartitionNumber $bootPartition.PartitionNumber -IsActive $true
                    } | Out-Null
                    Write-ActionLog -Event 'SetBootPartitionActive' -Details @{
                        DiskNumber      = $script:DiskNumber
                        PartitionNumber = $bootPartition.PartitionNumber
                    }
                    Write-Host "Boot partition is now marked as Active." -ForegroundColor Green
                }
                elseif ($bootPartition) {
                    Write-Host "Boot partition Active flag: OK" -ForegroundColor Green
                }
            }
        }
        catch {
            if (-not $script:_userFacingError) { Write-Error "RebuildBCD failed: $_" }
            throw
        }
    }

    function Get-EfiFallbackBootFileName {
        $guestArch = Get-OfflineGuestProcessorArchitecture
        switch ($guestArch) {
            'ARM64' { return 'bootaa64.efi' }
            'x86' { return 'bootia32.efi' }
            default { return 'bootx64.efi' }
        }
    }

    function Invoke-OfflineSfcScanFile {
        param(
            [Parameter(Mandatory = $true)][string]$RelativePath,
            [Parameter(Mandatory = $true)][string]$Label,
            [switch]$Optional
        )

        $targetPath = Join-Path $script:WinDriveLetter $RelativePath
        if ($Optional -and -not (Test-Path -LiteralPath $targetPath)) {
            Write-Host "  Skipping optional $Label (not present): $targetPath" -ForegroundColor DarkGray
            return
        }

        $offBoot = $script:WinDriveLetter
        $offWin = Join-Path $script:WinDriveLetter 'Windows'
        Write-Host "  Repairing $Label with offline SFC: $targetPath" -ForegroundColor Cyan
        try {
            $output = Invoke-Logged -Description "SFC scanfile $Label" -Details @{ File = $targetPath; OffBootDir = $offBoot; OffWinDir = $offWin } -ScriptBlock {
                & sfc.exe "/SCANFILE=$targetPath" "/OFFBOOTDIR=$offBoot" "/OFFWINDIR=$offWin" 2>&1 | Out-String -Width 9999
            }
            if ($output -and ([string]$output).Trim()) {
                ([string]$output).Trim() -split "`r?`n" | ForEach-Object { Write-Host "    $_" -ForegroundColor DarkGray }
            }
        }
        catch {
            Write-Warning "  Targeted SFC failed for $Label ($targetPath): $_"
        }

        if (-not (Test-Path -LiteralPath $targetPath)) {
            $level = if ($Optional) { 'DarkGray' } else { 'Yellow' }
            Write-Host "  $Label still missing after targeted SFC: $targetPath" -ForegroundColor $level
            return
        }

        $item = Get-Item -LiteralPath $targetPath -Force -ErrorAction SilentlyContinue
        if ($item -and $item.Length -eq 0) {
            Write-Warning "  $Label is still 0 bytes after targeted SFC: $targetPath"
            return
        }

        if ($targetPath -match '\.(efi|exe|dll|sys)$') {
            $sig = Test-MicrosoftSignature -FilePath $targetPath
            if (-not $sig.IsAcceptableMicrosoft) {
                Write-Warning "  $Label failed trust validation after targeted SFC - $(Get-TrustStateDescription -Signature $sig): $targetPath"
            }
        }
    }

    function Get-CodeIntegrityPolicyPayloadSpec {
        @(
            @{
                FileName       = 'Driver.stl'
                RelativePath   = 'Windows\System32\CodeIntegrity\Driver.stl'
                Label          = 'Code Integrity driver revocation list (Driver.stl)'
                ComponentRegex = 'microsoft-onecore-c.*riverrevocationlist'
                ComponentDirectoryFilter = '*microsoft-onecore-c*riverrevocationlist*'
            }
            @{
                FileName       = 'DriverSiPolicy.p7b'
                RelativePath   = 'Windows\System32\CodeIntegrity\DriverSiPolicy.p7b'
                Label          = 'Code Integrity driver signing policy (DriverSiPolicy.p7b)'
                ComponentRegex = 'microsoft-windows-c.*egrity-driverpolicy'
                ComponentDirectoryFilter = '*microsoft-windows-c*egrity-driverpolicy*'
            }
            @{
                # Delivered by Secure Boot servicing rather than as a WinSxS component
                # payload, so there is deliberately no component filter here: the only
                # real sources are an explicit known-good folder or a same-build host.
                # It still has to be repaired before the EFI copy step runs, because
                # that step propagates this exact file to the EFI System Partition.
                FileName       = 'SKUSiPolicy.p7b'
                RelativePath   = 'Windows\System32\SecureBootUpdates\SKUSiPolicy.p7b'
                Label          = 'Secure Boot SKU policy source (SKUSiPolicy.p7b)'
                ComponentRegex = ''
                ComponentDirectoryFilter = ''
            }
        )
    }

    function Get-WinSxSComponentVersionFromPath {
        param([string]$Path)

        foreach ($segment in @($Path -split '[\\/]')) {
            if ($segment -match '_(\d+\.\d+\.\d+\.\d+)_') {
                return $Matches[1]
            }
        }
        return ''
    }

    function Get-CodeIntegrityFileHash {
        param([string]$Path)

        try {
            return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path -ErrorAction Stop).Hash
        }
        catch {
            return ''
        }
    }

    function Add-CodeIntegrityCandidate {
        param(
            [Parameter(Mandatory = $true)]$Candidates,
            [Parameter(Mandatory = $true)][hashtable]$Spec,
            [Parameter(Mandatory = $true)][string]$Path,
            [Parameter(Mandatory = $true)][string]$Source,
            [Parameter(Mandatory = $true)][int]$Priority,
            [string]$ReferenceVersion = ''
        )

        $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
        if (-not $item -or $item.Length -le 0) { return }
        if ($item.DirectoryName -match '\\(f|r)$') { return }

        $componentVersion = Get-WinSxSComponentVersionFromPath -Path $item.FullName
        $fileHash = Get-CodeIntegrityFileHash -Path $item.FullName
        if ([string]::IsNullOrWhiteSpace($fileHash)) { return }

        $versionObject = $null
        if ($componentVersion) {
            try { $versionObject = [version]$componentVersion } catch { $versionObject = [version]'0.0.0.0' }
        }
        if (-not $versionObject) { $versionObject = [version]'0.0.0.0' }

        $Candidates.Add([PSCustomObject]@{
                FileName         = $Spec.FileName
                Label            = $Spec.Label
                Path             = $item.FullName
                Source           = $Source
                Priority         = $Priority
                Size             = $item.Length
                LastWrite        = $item.LastWriteTime
                Hash             = $fileHash
                ComponentVersion = $componentVersion
                VersionObject    = $versionObject
                MatchesReference = ($ReferenceVersion -and $componentVersion -eq $ReferenceVersion)
            })
    }

    function Get-CodeIntegrityReferenceCandidate {
        $windowsRoot = Join-Path $script:WinDriveLetter 'Windows'
        $winsxsDir = Join-Path $windowsRoot 'WinSxS'
        if (-not (Test-Path -LiteralPath $winsxsDir)) { return $null }

        $candidates = [System.Collections.Generic.List[object]]::new()
        Get-ChildItem -Path $winsxsDir -Directory -Filter '*microsoft-windows-codeintegrity_*' -ErrorAction SilentlyContinue |
        ForEach-Object {
            $candidatePath = Join-Path $_.FullName 'ci.dll'
            $candidateItem = Get-Item -LiteralPath $candidatePath -Force -ErrorAction SilentlyContinue
            if (-not $candidateItem -or $candidateItem.Length -le 0) { return }
            $versionText = Get-WinSxSComponentVersionFromPath -Path $candidateItem.FullName
            $versionObject = [version]'0.0.0.0'
            if ($versionText) { try { $versionObject = [version]$versionText } catch {} }
            $candidates.Add([PSCustomObject]@{
                Path             = $candidateItem.FullName
                Size             = $candidateItem.Length
                LastWrite        = $candidateItem.LastWriteTime
                ComponentVersion = $versionText
                VersionObject    = $versionObject
            })
        }

        return @($candidates | Sort-Object @{ Expression = 'VersionObject'; Descending = $true }, @{ Expression = 'Size'; Descending = $true }, @{ Expression = 'LastWrite'; Descending = $true } | Select-Object -First 1)
    }

    function Test-HostBuildMatchesGuest {
        $guestBuild = if ($script:SelectedWindowsInstall -and $script:SelectedWindowsInstall.CurrentBuildNumber) { [string]$script:SelectedWindowsInstall.CurrentBuildNumber } else { '' }
        $guestUBR = if ($script:SelectedWindowsInstall -and $script:SelectedWindowsInstall.UBR) { [string]$script:SelectedWindowsInstall.UBR } else { '' }
        $hostCv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
        $hostBuild = if ($hostCv -and $hostCv.CurrentBuildNumber) { [string]$hostCv.CurrentBuildNumber } else { [System.Environment]::OSVersion.Version.Build.ToString() }
        $hostUBR = if ($hostCv -and $null -ne $hostCv.UBR) { [string]$hostCv.UBR } else { '' }

        if ([string]::IsNullOrWhiteSpace($guestBuild)) {
            $softwareHivePath = Join-Path $script:WinDriveLetter 'Windows\System32\Config\SOFTWARE'
            if (Test-Path -LiteralPath $softwareHivePath) {
                $tempKey = 'RVMTEMP_CI_{0}' -f ([guid]::NewGuid().ToString('N'))
                $loaded = $false
                try {
                    $null = reg.exe load "HKLM\$tempKey" "$softwareHivePath" 2>&1 | Out-String
                    if ($LASTEXITCODE -eq 0) {
                        $loaded = $true
                        $guestCv = Get-ItemProperty "HKLM:\$tempKey\Microsoft\Windows NT\CurrentVersion" -ErrorAction SilentlyContinue
                        if ($guestCv) {
                            $guestBuild = if ($guestCv.CurrentBuildNumber) { [string]$guestCv.CurrentBuildNumber } else { '' }
                            $guestUBR = if ($null -ne $guestCv.UBR) { [string]$guestCv.UBR } else { '' }
                        }
                    }
                }
                finally {
                    if ($loaded) { reg.exe unload "HKLM\$tempKey" 2>&1 | Out-Null }
                }
            }
        }

        $guestLabel = if ($guestUBR) { "$guestBuild.$guestUBR" } else { $guestBuild }
        $hostLabel = if ($hostUBR) { "$hostBuild.$hostUBR" } else { $hostBuild }

        if ([string]::IsNullOrWhiteSpace($guestBuild)) {
            return [PSCustomObject]@{ Matches = $false; Guest = 'unknown'; Host = $hostLabel; Reason = 'guest build unavailable' }
        }

        $matches = $false
        if ($guestUBR -and $hostUBR) { $matches = ($guestBuild -eq $hostBuild -and $guestUBR -eq $hostUBR) }
        else { $matches = ($guestBuild -eq $hostBuild) }

        return [PSCustomObject]@{ Matches = $matches; Guest = $guestLabel; Host = $hostLabel; Reason = if ($matches) { 'match' } else { 'host and guest builds differ' } }
    }

    function Test-CodeIntegrityExplicitSourceAllowed {
        param([string]$SourcePath)

        if ([string]::IsNullOrWhiteSpace($SourcePath)) {
            return [PSCustomObject]@{ Allowed = $true; IsHostSource = $false; Reason = '' }
        }

        $resolvedSource = ''
        try {
            if (Test-Path -LiteralPath $SourcePath) {
                $resolvedSource = (Resolve-Path -LiteralPath $SourcePath -ErrorAction Stop).ProviderPath
            }
        }
        catch {}

        if ([string]::IsNullOrWhiteSpace($resolvedSource)) {
            return [PSCustomObject]@{ Allowed = $true; IsHostSource = $false; Reason = '' }
        }

        $hostRoot = $env:SystemRoot.TrimEnd('\')
        $isHostSource = $resolvedSource.StartsWith($hostRoot, [System.StringComparison]::OrdinalIgnoreCase)
        if (-not $isHostSource) {
            return [PSCustomObject]@{ Allowed = $true; IsHostSource = $false; Reason = '' }
        }

        $buildMatch = Test-HostBuildMatchesGuest
        if ($buildMatch.Matches) {
            return [PSCustomObject]@{ Allowed = $true; IsHostSource = $true; Reason = "host build matches guest ($($buildMatch.Host))" }
        }

        return [PSCustomObject]@{ Allowed = $false; IsHostSource = $true; Reason = "host build $($buildMatch.Host) is not compatible with guest build $($buildMatch.Guest): $($buildMatch.Reason)" }
    }

    function Get-CodeIntegrityCandidateSubPath {
        param(
            [Parameter(Mandatory = $true)][hashtable]$Spec,
            [Parameter(Mandatory = $true)][string]$Root,
            [switch]$HostLayout
        )

        # Payload specs no longer all live under System32\CodeIntegrity, so the places
        # a donor file might sit are derived from the spec's own relative path instead
        # of being hard-coded. A donor folder is accepted flat, or with any suffix of
        # the file's normal Windows path preserved.
        $relative = [string]$Spec.RelativePath
        $relativeDir = [System.IO.Path]::GetDirectoryName($relative)
        $segments = @($relativeDir -split '[\\/]' | Where-Object { $_ })
        $root = $Root.TrimEnd('\')

        if ($HostLayout) {
            # $env:SystemRoot already is the Windows directory, so drop the leading one.
            if ($segments.Count -gt 0 -and $segments[0] -ieq 'Windows') {
                $segments = @($segments | Select-Object -Skip 1)
            }
            if ($segments.Count -eq 0) { return @(Join-Path $root $Spec.FileName) }
            return @(Join-Path $root (Join-Path ($segments -join '\') $Spec.FileName))
        }

        $paths = [System.Collections.Generic.List[string]]::new()
        $paths.Add((Join-Path $root $Spec.FileName))
        for ($i = $segments.Count - 1; $i -ge 0; $i--) {
            $suffix = ($segments[$i..($segments.Count - 1)] -join '\')
            $paths.Add((Join-Path $root (Join-Path $suffix $Spec.FileName)))
        }
        return @($paths | Select-Object -Unique)
    }

    function Get-CodeIntegrityPolicyCandidates {
        param(
            [Parameter(Mandatory = $true)][hashtable]$Spec,
            [string]$ReferenceVersion = '',
            [string]$SourcePath = '',
            [switch]$IncludeHostFallback
        )

        $candidates = [System.Collections.Generic.List[object]]::new()

        if (-not [string]::IsNullOrWhiteSpace($SourcePath)) {
            $sourceAllowed = Test-CodeIntegrityExplicitSourceAllowed -SourcePath $SourcePath
            if (-not $sourceAllowed.Allowed) {
                Write-Warning "  Explicit source path '$SourcePath' was skipped for $($Spec.FileName): $($sourceAllowed.Reason). Use a same-build source folder instead."
            }
            else {
                $sourceLabel = if ($sourceAllowed.IsHostSource) { "ExplicitHostSource ($($sourceAllowed.Reason))" } else { 'ExplicitSource' }
                $sourceItem = Get-Item -LiteralPath $SourcePath -Force -ErrorAction SilentlyContinue
                if ($sourceItem -and -not $sourceItem.PSIsContainer) {
                    if ($sourceItem.Name -ieq $Spec.FileName) {
                        Add-CodeIntegrityCandidate -Candidates $candidates -Spec $Spec -Path $sourceItem.FullName -Source $sourceLabel -Priority 0 -ReferenceVersion $ReferenceVersion
                    }
                }
                else {
                    $sourceRoot = $SourcePath.TrimEnd('\')
                    foreach ($explicitPath in @(Get-CodeIntegrityCandidateSubPath -Spec $Spec -Root $sourceRoot)) {
                        Add-CodeIntegrityCandidate -Candidates $candidates -Spec $Spec -Path $explicitPath -Source $sourceLabel -Priority 0 -ReferenceVersion $ReferenceVersion
                    }
                }
            }
        }

        $windowsRoot = Join-Path $script:WinDriveLetter 'Windows'
        $winsxsDir = Join-Path $windowsRoot 'WinSxS'
        if ((-not [string]::IsNullOrWhiteSpace($Spec.ComponentDirectoryFilter)) -and (Test-Path -LiteralPath $winsxsDir)) {
            Get-ChildItem -Path $winsxsDir -Directory -Filter $Spec.ComponentDirectoryFilter -ErrorAction SilentlyContinue |
            ForEach-Object {
                Add-CodeIntegrityCandidate -Candidates $candidates -Spec $Spec -Path (Join-Path $_.FullName $Spec.FileName) -Source 'OfflineWinSxS' -Priority 1 -ReferenceVersion $ReferenceVersion
            }
        }

        if ($IncludeHostFallback) {
            $buildMatch = Test-HostBuildMatchesGuest
            if ($buildMatch.Matches) {
                foreach ($hostPath in @(Get-CodeIntegrityCandidateSubPath -Spec $Spec -Root $env:SystemRoot -HostLayout)) {
                    Add-CodeIntegrityCandidate -Candidates $candidates -Spec $Spec -Path $hostPath -Source "HostSystem32CodeIntegrity ($($buildMatch.Host))" -Priority 2 -ReferenceVersion $ReferenceVersion
                }

                $hostWinsxsDir = Join-Path $env:SystemRoot 'WinSxS'
                if ((-not [string]::IsNullOrWhiteSpace($Spec.ComponentDirectoryFilter)) -and (Test-Path -LiteralPath $hostWinsxsDir)) {
                    Get-ChildItem -Path $hostWinsxsDir -Directory -Filter $Spec.ComponentDirectoryFilter -ErrorAction SilentlyContinue |
                    ForEach-Object {
                        Add-CodeIntegrityCandidate -Candidates $candidates -Spec $Spec -Path (Join-Path $_.FullName $Spec.FileName) -Source "HostWinSxS ($($buildMatch.Host))" -Priority 3 -ReferenceVersion $ReferenceVersion
                    }
                }
            }
            else {
                Write-Host "  Host fallback skipped for $($Spec.FileName): guest build $($buildMatch.Guest), host build $($buildMatch.Host) ($($buildMatch.Reason))." -ForegroundColor DarkGray
            }
        }

        return @($candidates |
            Sort-Object @{ Expression = 'Priority'; Ascending = $true },
                        @{ Expression = { if ($ReferenceVersion -and $_.ComponentVersion -eq $ReferenceVersion) { 0 } else { 1 } } },
                        @{ Expression = 'VersionObject'; Descending = $true },
                        @{ Expression = 'Size'; Descending = $true },
                        @{ Expression = 'LastWrite'; Descending = $true })
    }

    function Repair-CodeIntegrityPolicyPayloads {
        param([string]$SourcePath = '')

        $referenceCandidate = Get-CodeIntegrityReferenceCandidate
        $referenceVersion = if ($referenceCandidate -and $referenceCandidate.ComponentVersion) { [string]$referenceCandidate.ComponentVersion } else { '' }
        if ($referenceCandidate) {
            Write-Host "`nCode Integrity component reference: $($referenceCandidate.ComponentVersion) ($($referenceCandidate.Path))" -ForegroundColor Cyan
        }
        else {
            Write-Host "`nCode Integrity component reference could not be resolved from offline WinSxS; policy repair will use best available candidates." -ForegroundColor Yellow
        }

        foreach ($spec in (Get-CodeIntegrityPolicyPayloadSpec)) {
            $targetPath = Join-Path $script:WinDriveLetter $spec.RelativePath
            $targetItem = Get-Item -LiteralPath $targetPath -Force -ErrorAction SilentlyContinue
            $targetHash = if ($targetItem -and $targetItem.Length -gt 0) { Get-CodeIntegrityFileHash -Path $targetPath } else { '' }
            $candidates = @(Get-CodeIntegrityPolicyCandidates -Spec $spec -ReferenceVersion $referenceVersion -SourcePath $SourcePath -IncludeHostFallback)
            $best = @($candidates | Select-Object -First 1)

            Write-Host "`nChecking $($spec.Label):" -ForegroundColor Yellow
            Write-Host "  Target: $targetPath" -ForegroundColor DarkGray
            if ($targetItem) {
                Write-Host "  Current: size=$($targetItem.Length), date=$($targetItem.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss')), hash=$targetHash" -ForegroundColor DarkGray
            }
            else {
                Write-Host "  Current: missing" -ForegroundColor DarkGray
            }

            if (-not $best) {
                Write-Warning "  No usable replacement candidate found for $($spec.FileName) in the explicit source, offline WinSxS, or same-build host fallback."
                Write-Warning "  Copy this file from a working VM with the same OS build/LCU into a folder and rerun with -CodeIntegrityPolicySourcePath <folder>."
                continue
            }

            Write-Host "  Candidate: $($best.Path)" -ForegroundColor Cyan
            Write-Host "    Source=$($best.Source), component=$($best.ComponentVersion), size=$($best.Size), date=$($best.LastWrite.ToString('yyyy-MM-dd HH:mm:ss')), hash=$($best.Hash)" -ForegroundColor DarkGray

            if ($targetHash -and $targetHash -eq $best.Hash) {
                Write-Host "  [OK] $($spec.FileName) already matches the selected Code Integrity payload candidate." -ForegroundColor Green
                continue
            }

            if ($referenceVersion -and $best.ComponentVersion -and $best.ComponentVersion -ne $referenceVersion -and $best.Source -ne 'ExplicitSource') {
                Write-Warning "  Selected $($spec.FileName) component version $($best.ComponentVersion) does not match Code Integrity reference $referenceVersion. Using best available candidate."
            }
            if ($best.Source -like 'Host*') {
                Write-Warning "  Using same-build rescue host fallback for $($spec.FileName). Prefer offline WinSxS or an explicit known-good source when available."
            }
            if ($best.Source -eq 'ExplicitSource') {
                Write-Warning "  Using explicit source for $($spec.FileName). Verify it came from a working VM with the same OS build/LCU."
            }

            # The backup is made by Install-ProtectedSystemFile below, which renames the
            # existing file aside rather than copying it. A copy would need the same
            # rights the replacement needs, and would leave nothing to roll back to if
            # the overwrite then failed halfway.

            $targetDir = Split-Path -Parent $targetPath
            if (-not (Test-Path -LiteralPath $targetDir)) {
                New-Item-Logged -Path $targetDir -ItemType Directory -Force
            }

            # Routed through the same installer every other replacement in this script
            # uses, so this path also gets the hard-link guard, the descriptor replay and
            # the rollback. It previously called takeown.exe and icacls.exe, which leave
            # a granted ACE behind and set an owner Windows never had.
            $ciValidation = {
                param($installedPath)

                $installedItem = Get-Item -LiteralPath $installedPath -Force -ErrorAction Stop
                $installedHash = Get-CodeIntegrityFileHash -Path $installedPath
                if ($installedItem.Length -ne $best.Size -or $installedHash -ne $best.Hash) {
                    throw "Copy verification failed for $installedPath (expected hash $($best.Hash), got $installedHash)."
                }
            }

            $ciInstall = Install-ProtectedSystemFile `
                -Source $best.Path `
                -Destination $targetPath `
                -BackupSuffix '.codeintegrity.bak' `
                -PostCopyValidation $ciValidation `
                -Description $spec.FileName

            if (-not $ciInstall.Installed) {
                throw "Could not replace $($spec.FileName): $($ciInstall.Reason)"
            }

            $newItem = Get-Item -LiteralPath $targetPath -Force -ErrorAction Stop
            $newHash = Get-CodeIntegrityFileHash -Path $targetPath
            if ($newItem.Length -ne $best.Size -or $newHash -ne $best.Hash) {
                throw "Copy verification failed for $targetPath (expected hash $($best.Hash), got $newHash)."
            }

            Write-ActionLog -Event 'CodeIntegrityPolicyPayloadRepaired' -Details @{
                FileName         = $spec.FileName
                TargetPath       = $targetPath
                SourcePath       = $best.Path
                Source           = $best.Source
                ComponentVersion = $best.ComponentVersion
                PreviousHash     = $targetHash
                NewHash          = $newHash
            }
            Write-Host "  [OK] Replaced $($spec.FileName) with matching Code Integrity payload candidate." -ForegroundColor Green
        }
    }

    function RepairSecureBootCodeIntegrity {
        param([string]$CodeIntegrityPolicySourcePath = '')

        if ($script:VMGen -ne 2) {
            Write-Error "-FixSecureBootCodeIntegrity applies only to Generation 2 / UEFI disks. Gen1 disks do not have an EFI System Partition."
            return
        }
        if (-not [string]::IsNullOrWhiteSpace($CodeIntegrityPolicySourcePath) -and -not (Test-Path -LiteralPath $CodeIntegrityPolicySourcePath)) {
            Write-Error "Code Integrity policy source path does not exist: $CodeIntegrityPolicySourcePath"
            return
        }

        $sourceBootManager = Join-Path $script:WinDriveLetter 'Windows\Boot\EFI\bootmgfw.efi'
        $sourceSkuPolicy = Join-Path $script:WinDriveLetter 'Windows\System32\SecureBootUpdates\SKUSiPolicy.p7b'
        $ciPolicySourceLabel = if ([string]::IsNullOrWhiteSpace($CodeIntegrityPolicySourcePath)) { 'offline WinSxS first, then same-build rescue host fallback' } else { $CodeIntegrityPolicySourcePath }
        $microsoftBootDir = Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot'
        $fallbackBootDir = Join-Path $script:BootDriveLetter 'EFI\Boot'
        $destBootManager = Join-Path $microsoftBootDir 'bootmgfw.efi'
        $fallbackName = Get-EfiFallbackBootFileName
        $destFallbackBoot = Join-Path $fallbackBootDir $fallbackName
        $destSkuPolicy = Join-Path $microsoftBootDir 'SKUSiPolicy.p7b'

        if (-not (Confirm-CriticalOperation -Operation 'Fix Secure Boot / Code Integrity boot files (-FixSecureBootCodeIntegrity)' -Details @"
Refreshes the Gen2 EFI System Partition from the offline Windows installation:
  Source boot manager : $sourceBootManager
  Target boot manager : $destBootManager
  Target fallback     : $destFallbackBoot
  Source SKU policy   : $sourceSkuPolicy
  Target SKU policy   : $destSkuPolicy
    CI payload source   : $ciPolicySourceLabel

This targets Gen2 winload.efi / Code Integrity recovery failures such as
0xc0430001 when the EFI System Partition has stale or missing boot manager
and SKUSiPolicy.p7b files, or when OS CodeIntegrity policy payloads such as
Driver.stl and DriverSiPolicy.p7b are stale compared with the component store.

Before the EFI copy, it also runs targeted offline SFC repairs for winload.efi,
ci.dll, Driver.stl, DriverSiPolicy.p7b, kernel/HAL, and related OS-loader
dependencies on the Windows partition.
"@)) { return }

        $loaderRepairTargets = @(
            @{ RelativePath = 'Windows\Boot\EFI\bootmgfw.efi'; Label = 'Windows-staged boot manager'; Optional = $false }
            @{ RelativePath = 'Windows\System32\winload.efi'; Label = 'Windows OS loader (winload.efi)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\winresume.efi'; Label = 'Windows resume loader (winresume.efi)'; Optional = $true }
            @{ RelativePath = 'Windows\System32\ci.dll'; Label = 'Code Integrity engine (ci.dll)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\ntoskrnl.exe'; Label = 'NT kernel (ntoskrnl.exe)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\hal.dll'; Label = 'Hardware Abstraction Layer (hal.dll)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\kdcom.dll'; Label = 'kernel debug transport (kdcom.dll)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\pshed.dll'; Label = 'platform hardware error driver (pshed.dll)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\drivers\clfs.sys'; Label = 'Common Log File System driver (clfs.sys)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\hvloader.dll'; Label = 'Hyper-V loader (hvloader.dll)'; Optional = $true }
            @{ RelativePath = 'Windows\System32\hvix64.exe'; Label = 'Hyper-V hypervisor image (hvix64.exe)'; Optional = $true }
            @{ RelativePath = 'Windows\System32\CodeIntegrity\SiPolicy.p7b'; Label = 'Code Integrity policy (SiPolicy.p7b)'; Optional = $true }
            @{ RelativePath = 'Windows\System32\CodeIntegrity\Driver.stl'; Label = 'Code Integrity driver revocation list (Driver.stl)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\CodeIntegrity\DriverSiPolicy.p7b'; Label = 'Code Integrity driver signing policy (DriverSiPolicy.p7b)'; Optional = $false }
            @{ RelativePath = 'Windows\System32\SecureBootUpdates\SKUSiPolicy.p7b'; Label = 'Secure Boot SKU policy source (SKUSiPolicy.p7b)'; Optional = $false }
        )

        Write-Host "`nRepairing Windows loader / Code Integrity source files with targeted offline SFC..." -ForegroundColor Yellow
        foreach ($target in $loaderRepairTargets) {
            Invoke-OfflineSfcScanFile -RelativePath $target.RelativePath -Label $target.Label -Optional:([bool]$target.Optional)
        }

        Write-Host "`nValidating Code Integrity driver policy payloads against available source candidates..." -ForegroundColor Yellow
        Repair-CodeIntegrityPolicyPayloads -SourcePath $CodeIntegrityPolicySourcePath

        $missingSources = @()
        if (-not (Test-Path -LiteralPath $sourceBootManager)) { $missingSources += $sourceBootManager }
        if (-not (Test-Path -LiteralPath $sourceSkuPolicy)) { $missingSources += $sourceSkuPolicy }
        if ($missingSources.Count -gt 0) {
            Write-Host "`n[ERROR] Required Secure Boot recovery source file(s) were not found on the offline Windows partition:" -ForegroundColor Red
            $missingSources | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
            Write-Host "`nThese files are required source artifacts from the offline Windows installation used to refresh the EFI boot manager and Code Integrity policy." -ForegroundColor Yellow
            Write-Host "Apply the appropriate Windows update, or repair the component store from matching media, then rerun -FixSecureBootCodeIntegrity." -ForegroundColor Yellow
            $script:_userFacingError = $true
            throw "Missing Secure Boot recovery source file(s): $($missingSources -join ', ')"
        }

        # Last line of defence before the EFI System Partition is written. Copying a
        # damaged source over a good ESP copy turns a repairable disk into an unbootable
        # one, so the sources are sanity-checked for their expected file signature first.
        $sourceChecks = @(
            @{ Path = $sourceBootManager; Magic = @(0x4D, 0x5A); Kind = 'PE image'; Label = 'boot manager (bootmgfw.efi)' }
            @{ Path = $sourceSkuPolicy;   Magic = @(0x30, 0x82); Kind = 'DER-encoded PKCS#7'; Label = 'Secure Boot SKU policy (SKUSiPolicy.p7b)' }
        )
        $badSources = @()
        foreach ($check in $sourceChecks) {
            $header = $null
            try {
                $stream = [System.IO.File]::OpenRead($check.Path)
                try {
                    $header = New-Object byte[] 2
                    if ($stream.Read($header, 0, 2) -lt 2) { $header = $null }
                }
                finally { $stream.Dispose() }
            }
            catch { $header = $null }

            if ((-not $header) -or $header[0] -ne $check.Magic[0] -or $header[1] -ne $check.Magic[1]) {
                $badSources += "$($check.Label) at $($check.Path) is not a valid $($check.Kind)"
            }
        }
        if ($badSources.Count -gt 0) {
            Write-Host "`n[ERROR] Secure Boot source file(s) on the offline Windows partition are damaged:" -ForegroundColor Red
            $badSources | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
            Write-Host "`nCopying these to the EFI System Partition would overwrite the existing copies with damaged data and could make the disk unbootable." -ForegroundColor Yellow
            Write-Host "Supply a known-good folder from a VM with the same build and LCU using -CodeIntegrityPolicySourcePath, then rerun -FixSecureBootCodeIntegrity." -ForegroundColor Yellow
            $script:_userFacingError = $true
            throw "Damaged Secure Boot source file(s); EFI System Partition was left unchanged."
        }

        foreach ($dir in @($microsoftBootDir, $fallbackBootDir)) {
            if (-not (Test-Path -LiteralPath $dir)) {
                New-Item-Logged -Path $dir -ItemType Directory -Force
            }
        }

        function Copy-SecureBootArtifact {
            param(
                [Parameter(Mandatory = $true)][string]$Source,
                [Parameter(Mandatory = $true)][string]$Destination,
                [Parameter(Mandatory = $true)][string]$Label
            )

            # Routed through the shared installer so this path gets the same backup,
            # rollback, hash verification and protected-path handling as every other
            # replacement. The destination here is normally on the FAT32 EFI System
            # Partition, which the installer detects and handles by leaving ACLs alone.
            Write-Host "  Copying ${Label}: $Source -> $Destination" -ForegroundColor Cyan
            $install = Install-ProtectedSystemFile `
                -Source $Source `
                -Destination $Destination `
                -BackupSuffix '.secureboot.bak' `
                -Description $Label

            if (-not $install.Installed) {
                throw "Copy failed for $Destination : $($install.Reason)"
            }
        }

        Copy-SecureBootArtifact -Source $sourceBootManager -Destination $destBootManager -Label 'EFI Microsoft boot manager'
        Copy-SecureBootArtifact -Source $sourceBootManager -Destination $destFallbackBoot -Label 'EFI fallback boot manager'
        Copy-SecureBootArtifact -Source $sourceSkuPolicy -Destination $destSkuPolicy -Label 'Secure Boot SKU policy'

        Write-ActionLog -Event 'SecureBootCodeIntegrityRepaired' -Details @{
            SourceBootManager = $sourceBootManager
            DestBootManager   = $destBootManager
            DestFallbackBoot  = $destFallbackBoot
            SourceSkuPolicy   = $sourceSkuPolicy
            DestSkuPolicy     = $destSkuPolicy
            CiPolicySource    = $ciPolicySourceLabel
        }
        Write-Host "Secure Boot / Code Integrity boot files refreshed." -ForegroundColor Green
        Write-Host "If Secure Boot was disabled as a workaround, shut down the VM, re-enable Secure Boot, then test boot." -ForegroundColor Yellow
    }

    function RecreateBootPartition {
        Write-Host "Checking boot partition status..." -ForegroundColor Yellow
        try {
            $partitions = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue
            $disk = Get-Disk -Number $script:DiskNumber

            if ($script:VMGen -eq 2) {
                # -- Gen2 (UEFI/GPT): EFI System Partition ----
                $existingEsp = $partitions | Where-Object { $_.Type -eq 'System' }
                if ($existingEsp) {
                    Write-Host "EFI System Partition already exists (Partition $($existingEsp.PartitionNumber)). No action needed." -ForegroundColor Green
                    Write-Host "If the BCD is missing or corrupt, use -FixBoot to rebuild it." -ForegroundColor DarkCyan
                    return
                }

                $idealSize = 100MB
                $minSize = 80MB
                $freeSpace = $disk.LargestFreeExtent
                if ($freeSpace -lt $minSize) {
                    Write-Error "Not enough unallocated space on disk $($script:DiskNumber). Need at least 80 MB, available: $([math]::Round($freeSpace / 1MB, 1)) MB."
                    return
                }
                $useSize = if ($freeSpace -ge $idealSize) { $idealSize } else { $freeSpace }
                $sizeMB = [math]::Round($useSize / 1MB, 0)

                $confirmed = Confirm-CriticalOperation -Operation "Recreate EFI System Partition (Gen2/UEFI)" -Details @"
- Create a $sizeMB MB FAT32 partition with GPT type 'EFI System Partition'
- Run bcdboot to populate it with EFI boot files and a fresh BCD store
- The Windows partition at $($script:WinDriveLetter) will be referenced as the OS source
"@
                if (-not $confirmed) { return }

                Write-Host "Creating $sizeMB MB EFI System Partition..." -ForegroundColor Cyan
                $newPart = Invoke-LoggedValue -Description 'Create EFI System Partition' -Details @{
                    DiskNumber = $script:DiskNumber
                    Size = $useSize
                    GptType = '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}'
                } -ScriptBlock {
                    New-Partition -DiskNumber $script:DiskNumber -Size $useSize `
                        -GptType '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}' -AssignDriveLetter
                } | Select-Object -First 1
                $newLetter = $newPart.DriveLetter
                if (-not $newLetter -or $newLetter -eq "`0") {
                    Invoke-Logged -Description 'Assign drive letter to EFI System Partition' -Details @{
                        DiskNumber = $script:DiskNumber
                        PartitionNumber = $newPart.PartitionNumber
                    } -ScriptBlock {
                        $newPart | Add-PartitionAccessPath -AssignDriveLetter -ErrorAction SilentlyContinue
                    } | Out-Null
                    $newPart = Get-Partition -DiskNumber $script:DiskNumber -PartitionNumber $newPart.PartitionNumber
                    $newLetter = $newPart.DriveLetter
                }

                Write-Host "Formatting as FAT32 (label: SYSTEM)..." -ForegroundColor Cyan
                Invoke-Logged -Description 'Format EFI System Partition' -Details @{
                    DiskNumber = $script:DiskNumber
                    PartitionNumber = $newPart.PartitionNumber
                    FileSystem = 'FAT32'
                    Label = 'SYSTEM'
                } -ScriptBlock {
                    Format-Volume -Partition $newPart -FileSystem FAT32 -NewFileSystemLabel "SYSTEM" -Confirm:$false
                } | Out-Null

                $bootDrive = "$($newLetter):"
                $WinDrive = $script:WinDriveLetter.TrimEnd('\')
                $rebuildCmd = "bcdboot $WinDrive\Windows /s $bootDrive /v /f UEFI"
                Write-Host "Running: $rebuildCmd" -ForegroundColor Cyan
                Invoke-Logged -Description "bcdboot (recreate ESP)" -Details @{ Command = $rebuildCmd } -ScriptBlock {
                    & cmd.exe /c $rebuildCmd
                } | Out-Host

                $script:BootDriveLetter = "$bootDrive\"

                Write-ActionLog -Event 'RecreateBootPartition' -Details @{
                    Generation      = 2
                    DiskNumber      = $script:DiskNumber
                    PartitionNumber = $newPart.PartitionNumber
                    DriveLetter     = $bootDrive
                    FileSystem      = 'FAT32'
                    Size            = "${sizeMB}MB"
                }

                Write-Host "EFI System Partition created and boot files populated successfully." -ForegroundColor Green
                Write-Host "Boot drive is now: $bootDrive" -ForegroundColor Green
            }
            else {
                # -- Gen1 (BIOS/MBR): System Reserved partition ----
                $winTrimmed = $script:WinDriveLetter.TrimEnd('\')
                $separateBootPart = $partitions | Where-Object {
                    $_.IsActive -and ($_.AccessPaths | Where-Object { $_ -and $_.TrimEnd('\') -ne $winTrimmed })
                }
                if ($separateBootPart) {
                    Write-Host "An Active boot partition already exists (Partition $($separateBootPart.PartitionNumber)). No action needed." -ForegroundColor Green
                    Write-Host "If the BCD is missing or corrupt, use -FixBoot to rebuild it." -ForegroundColor DarkCyan
                    return
                }

                $winPartition = $partitions | Where-Object {
                    $_.AccessPaths | Where-Object { $_ -and $_.TrimEnd('\') -eq $winTrimmed }
                }

                $idealSize = 500MB
                $minSize = 350MB
                $freeSpace = $disk.LargestFreeExtent
                if ($freeSpace -lt $minSize) {
                    if ($winPartition -and $winPartition.IsActive) {
                        Write-Host "No separate boot partition and not enough free space, but the Windows partition is Active." -ForegroundColor Green
                        Write-Host "This is a valid single-partition layout. Use -FixBoot to rebuild BCD on the Windows partition if needed." -ForegroundColor DarkCyan
                    }
                    else {
                        Write-Error "Not enough unallocated space on disk $($script:DiskNumber). Need at least 350 MB, available: $([math]::Round($freeSpace / 1MB, 1)) MB."
                    }
                    return
                }
                $useSize = if ($freeSpace -ge $idealSize) { $idealSize } else { $freeSpace }
                $sizeMB = [math]::Round($useSize / 1MB, 0)

                $confirmed = Confirm-CriticalOperation -Operation "Recreate System Reserved Partition (Gen1/BIOS)" -Details @"
- Create a $sizeMB MB NTFS partition and mark it as Active
- Run bcdboot to populate it with boot files and a fresh BCD store
- The Windows partition at $($script:WinDriveLetter) will be referenced as the OS source
- The current Windows partition Active flag (if set) will be cleared
"@
                if (-not $confirmed) { return }

                Write-Host "Creating $sizeMB MB System Reserved partition..." -ForegroundColor Cyan
                $newPart = Invoke-LoggedValue -Description 'Create System Reserved partition' -Details @{
                    DiskNumber = $script:DiskNumber
                    Size = $useSize
                } -ScriptBlock {
                    New-Partition -DiskNumber $script:DiskNumber -Size $useSize -AssignDriveLetter
                } | Select-Object -First 1
                $newLetter = $newPart.DriveLetter
                if (-not $newLetter -or $newLetter -eq "`0") {
                    Invoke-Logged -Description 'Assign drive letter to System Reserved partition' -Details @{
                        DiskNumber = $script:DiskNumber
                        PartitionNumber = $newPart.PartitionNumber
                    } -ScriptBlock {
                        $newPart | Add-PartitionAccessPath -AssignDriveLetter -ErrorAction SilentlyContinue
                    } | Out-Null
                    $newPart = Get-Partition -DiskNumber $script:DiskNumber -PartitionNumber $newPart.PartitionNumber
                    $newLetter = $newPart.DriveLetter
                }

                Write-Host "Formatting as NTFS (label: System Reserved)..." -ForegroundColor Cyan
                Invoke-Logged -Description 'Format System Reserved partition' -Details @{
                    DiskNumber = $script:DiskNumber
                    PartitionNumber = $newPart.PartitionNumber
                    FileSystem = 'NTFS'
                    Label = 'System Reserved'
                } -ScriptBlock {
                    Format-Volume -Partition $newPart -FileSystem NTFS -NewFileSystemLabel "System Reserved" -Confirm:$false
                } | Out-Null

                Write-Host "Setting Active flag on new partition (Partition $($newPart.PartitionNumber))..." -ForegroundColor Cyan
                Invoke-Logged -Description 'Set System Reserved partition Active' -Details @{
                    DiskNumber = $script:DiskNumber
                    PartitionNumber = $newPart.PartitionNumber
                    IsActive = $true
                } -ScriptBlock {
                    Set-Partition -DiskNumber $script:DiskNumber -PartitionNumber $newPart.PartitionNumber -IsActive $true
                } | Out-Null

                if ($winPartition -and $winPartition.IsActive) {
                    Write-Host "Clearing Active flag from Windows partition (Partition $($winPartition.PartitionNumber))..." -ForegroundColor Cyan
                    Invoke-Logged -Description 'Clear Windows partition Active flag' -Details @{
                        DiskNumber = $script:DiskNumber
                        PartitionNumber = $winPartition.PartitionNumber
                        IsActive = $false
                    } -ScriptBlock {
                        Set-Partition -DiskNumber $script:DiskNumber -PartitionNumber $winPartition.PartitionNumber -IsActive $false
                    } | Out-Null
                }

                $bootDrive = "$($newLetter):"
                $WinDrive = $script:WinDriveLetter.TrimEnd('\')
                $rebuildCmd = "bcdboot $WinDrive\Windows /s $bootDrive /v /f BIOS"
                Write-Host "Running: $rebuildCmd" -ForegroundColor Cyan
                Invoke-Logged -Description "bcdboot (recreate System Reserved)" -Details @{ Command = $rebuildCmd } -ScriptBlock {
                    & cmd.exe /c $rebuildCmd
                } | Out-Host

                $script:BootDriveLetter = "$bootDrive\"

                Write-ActionLog -Event 'RecreateBootPartition' -Details @{
                    Generation      = 1
                    DiskNumber      = $script:DiskNumber
                    PartitionNumber = $newPart.PartitionNumber
                    DriveLetter     = $bootDrive
                    FileSystem      = 'NTFS'
                    Size            = "${sizeMB}MB"
                }

                Write-Host "System Reserved partition created and boot files populated successfully." -ForegroundColor Green
                Write-Host "Boot drive is now: $bootDrive" -ForegroundColor Green
            }
        }
        catch {
            Write-Error "RecreateBootPartition failed: $_"
            throw
        }
    }

    function AddNewUser {
        Param (
            [Parameter(Mandatory = $True)][string]$WinDrive,
            [Parameter(Mandatory = $True)][pscredential]$Credential
        )

        If ($WinDrive) {
            If (-Not $WinDrive.Contains(":")) {
                $WinDrive += ":"
            }

            If (-Not $WinDrive.EndsWith("\")) {
                $WinDrive += "\"
            }
        }

        If (-Not $Credential) {
            $Credential = Get-Credential
        }

        $Username = $Credential.GetNetworkCredential().UserName
        $Password = $Credential.GetNetworkCredential().Password

        $GptIni = @"
[General]
gPCFunctionalityVersion=2
gPCMachineExtensionNames=[{42B5FAAE-6536-11D2-AE5A-0000F87571E3}{40B6664F-4972-11D1-A7CA-0000F87571E3}]
Version=1    
"@

        $FixAzureVM = @"
@echo off
net user Username "Password" /add /Y
net localgroup administrators Username /add
net localgroup "Remote Desktop Users" Username /add
del /F C:\Windows\System32\GroupPolicy\Machine\Scripts\scripts.ini
del /F C:\Windows\System32\GroupPolicy\gpt.ini
del /F C:\Windows\System32\GroupPolicy\Machine\Scripts\Startup\FixAzureVM.cmd
"@

        $ScriptsIni = @"
[Startup]
0CmdLine=FixAzureVM.cmd
0Parameters=
"@

        $System32Path = Join-Path $WinDrive "Windows\System32"

        If (-Not (Test-Path -Path "$System32Path\GroupPolicy")) {
            New-Item-Logged -Path "$System32Path\GroupPolicy" -ItemType Directory -Force
        }

        If (-Not (Test-Path -Path "$System32Path\GroupPolicy\Scripts")) {
            New-Item-Logged -Path "$System32Path\GroupPolicy\Scripts" -ItemType Directory -Force
        }

        If (-Not (Test-Path -Path "$System32Path\GroupPolicy\Scripts\Startup")) {
            New-Item-Logged -Path "$System32Path\GroupPolicy\Scripts\Startup" -ItemType Directory -Force
        }

        #Create gpt.ini
        New-Item-Logged -Path "$System32Path\GroupPolicy" -Name "gpt.ini" -ItemType File -Value $GptIni.ToString().Trim() -Force
        #Create scripts.ini
        New-Item-Logged -Path "$System32Path\GroupPolicy\Machine\Scripts" -Name "scripts.ini" -ItemType File -Value $ScriptsIni.ToString().Trim() -Force
        #Create FixAzureVM.cmd
        New-Item-Logged -Path "$System32Path\GroupPolicy\Machine\Scripts\Startup" -Name "FixAzureVM.cmd" -ItemType File -Value $FixAzureVM.ToString().Trim().Replace("Username", $Username).Replace("Password", $Password) -Force -RedactValue

        Write-Host "If the VM is domain joined, local GPO may not apply, try -AddTempUser2 if this doesn't work."
    }

    function AddNewUser2 {
        param (
            [Parameter(Mandatory = $True)][pscredential]$Credential
        )

        Invoke-WithHive 'SYSTEM' {
            Write-Host "Configuring setup and adding script..." -ForegroundColor Green
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\adduser.cmd" -Type String -Force

            If (-Not $Credential) {
                $Credential = Get-Credential
            }

            $Username = $Credential.GetNetworkCredential().UserName
            $Password = $Credential.GetNetworkCredential().Password

            $NewUserScript = @"
@echo off
net user Username "Password" /add /Y
net localgroup administrators Username /add
net localgroup "Remote Desktop Users" Username /add
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\Temp\adduser.cmd > NUL
"@

            Ensure-GuestTempDir
            New-Item-Logged -Path "$script:WinDriveLetter\Temp" -Name "adduser.cmd" -ItemType File -Value $NewUserScript.ToString().Trim().Replace("Username", $Username).Replace("Password", $Password) -Force -RedactValue

            Write-Host "A script to add the user $Username will run at next boot. If the VM is domain joined, this should work even if local GPO is blocked." -ForegroundColor Green
        }
    }


    function GetRdpAuthPolicySnapshot {
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath
            $SoftwareRoot = "HKLM:\BROKENSOFTWARE"

            $checks = @(
                # --- RDP listener ---
                @{ Path = "$SystemRoot\Control\Terminal Server\WinStations\RDP-Tcp"; Name = "SecurityLayer" },
                @{ Path = "$SystemRoot\Control\Terminal Server\WinStations\RDP-Tcp"; Name = "UserAuthentication" },
                @{ Path = "$SystemRoot\Control\Terminal Server\WinStations\RDP-Tcp"; Name = "SSLCertificateSHA1Hash" },

                # --- NTLM restrictions ---
                @{ Path = "$SystemRoot\Control\Lsa\MSV1_0"; Name = "RestrictReceivingNTLMTraffic" },
                @{ Path = "$SystemRoot\Control\Lsa\MSV1_0"; Name = "RestrictSendingNTLMTraffic" },
                @{ Path = "$SystemRoot\Control\Lsa"; Name = "LmCompatibilityLevel" },

                # --- CredSSP / Encryption Oracle ---
                @{ Path = "$SoftwareRoot\Microsoft\Windows\CurrentVersion\Policies\System\CredSSP\Parameters"; Name = "AllowEncryptionOracle" }
            )

            foreach ($c in $checks) {
                $val = $null
                $status = "Missing"

                try {
                    if (Test-Path $c.Path) {
                        $p = Get-ItemProperty -Path $c.Path -ErrorAction Stop
                        if ($null -ne $p.($c.Name)) {
                            $val = $p.($c.Name)
                            $status = "Present"
                        }
                    }

                    # Special handling: SSLCertificateSHA1Hash is REG_BINARY -> show as hex string
                    if ($status -eq "Present" -and $c.Name -eq "SSLCertificateSHA1Hash" -and $val -is [byte[]]) {
                        $val = ([BitConverter]::ToString($val) -replace '-', '')
                    }
                }
                catch {
                    $status = "Error: $($_.Exception.Message)"
                }

                [PSCustomObject]@{
                    RegistryPath = $c.Path
                    Name         = $c.Name
                    Value        = $val
                    Status       = $status
                }
            }
        }
    }

    function SetRdpAuthPolicyOptimal {
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath
            $SoftwareRoot = "HKLM:\BROKENSOFTWARE"

            # --- Define the changes to apply: Path, Name, new Value ---
            $rdpTcp = "$SystemRoot\Control\Terminal Server\WinStations\RDP-Tcp"
            $msv10 = "$SystemRoot\Control\Lsa\MSV1_0"
            $lsa = "$SystemRoot\Control\Lsa"
            $credssp = "$SoftwareRoot\Microsoft\Windows\CurrentVersion\Policies\System\CredSSP\Parameters"

            $changes = @(
                @{ Path = $rdpTcp; Name = "SecurityLayer"; Value = 2 },
                @{ Path = $rdpTcp; Name = "UserAuthentication"; Value = 0 },
                @{ Path = $msv10; Name = "RestrictReceivingNTLMTraffic"; Value = 0 },
                @{ Path = $msv10; Name = "RestrictSendingNTLMTraffic"; Value = 0 },
                @{ Path = $lsa; Name = "LmCompatibilityLevel"; Value = 3 },
                @{ Path = $credssp; Name = "AllowEncryptionOracle"; Value = 2 }
            )

            # --- Snapshot current values before making any changes ---
            $snapshots = foreach ($c in $changes) {
                $before = $null
                $existed = $false
                if (Test-Path $c.Path) {
                    $prop = Get-ItemProperty -Path $c.Path -Name $c.Name -ErrorAction SilentlyContinue
                    if ($null -ne $prop.($c.Name)) {
                        $before = $prop.($c.Name)
                        $existed = $true
                    }
                }
                [PSCustomObject]@{
                    Path     = $c.Path
                    Name     = $c.Name
                    NewValue = $c.Value
                    Before   = $before
                    Existed  = $existed
                }
            }

            # --- Apply changes ---
            $results = @()
            foreach ($c in $changes) {
                $results += Set-DwordValue -Path $c.Path -Name $c.Name -Value $c.Value
            }

            Write-Host "`nApplied the following RDP auth policy changes:" -ForegroundColor Green
            $results | Format-Table -AutoSize

            Write-Host "RDP will use TLS security layer but allow fallback to non-NLA auth, NTLM auth will be allowed with NTLMv2-only responses, and CredSSP will allow vulnerable encryption oracle for compatibility." -ForegroundColor Yellow
            Write-Host "These settings are for recovery purposes only. After the VM is accessible again, restore the original values using the commands below." -ForegroundColor Yellow

            # --- Print restore commands based on the captured snapshots ---
            Write-Host "`n--- REVERT COMMANDS (run these on the VM after recovery to restore original settings) ---" -ForegroundColor Cyan
            Write-Host "# Mount the offline hives first if reverting via the repair host, or run directly on the live VM." -ForegroundColor DarkCyan
            foreach ($s in $snapshots) {
                # Convert the BROKEN hive path back to the live registry path for the restore commands
                $livePath = $s.Path -replace '^HKLM:\\BROKENSYSTEM\\', 'HKLM:\SYSTEM\' `
                    -replace '^HKLM:\\BROKENSOFTWARE\\', 'HKLM:\SOFTWARE\'
                if ($s.Existed) {
                    Write-Host "Set-ItemProperty -Path '$livePath' -Name '$($s.Name)' -Value $($s.Before) -Type DWord -Force" -ForegroundColor White
                }
                else {
                    Write-Host "Remove-ItemProperty -Path '$livePath' -Name '$($s.Name)' -ErrorAction SilentlyContinue  # value did not exist before" -ForegroundColor DarkGray
                }
            }
            Write-Host "-------------------------------------------------------------------------------------`n" -ForegroundColor Cyan
        }
    }

    function ResetRDPSettings {
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath
            $SoftwareRoot = "HKLM:\BROKENSOFTWARE"
            $TSKeyPath = "$SystemRoot\Control\Terminal Server"
            $WinStationsPath = "$SystemRoot\Control\Terminal Server\Winstations"
            $RdpTcpPath = "$SystemRoot\Control\Terminal Server\Winstations\RDP-Tcp"
            $TSPolicyPath = "$SoftwareRoot\Policies\Microsoft\Windows NT\Terminal Services"
            Write-Host "Setting RDP to default configuration..." -ForegroundColor Yellow

            # -- Enable RDP at the canonical registry key --------------------------
            # fDenyTSConnections=0 must be set on the Terminal Server key itself,
            # not only on the policy path, otherwise RDP remains blocked.
            Set-ItemProperty-Logged -Path $TSKeyPath -Name fDenyTSConnections -Value 0 -Type Dword -Force

            # -- RDP and connectivity services --------------------------------------
            # Startup values follow the Azure "Prepare a Windows VHD to upload" guidance:
            #   Manual (3)    - TermService and its two helpers. Windows starts these on
            #                   demand through the RDP listener trigger, so Manual is the
            #                   supported default; forcing Automatic diverges from it.
            #   Automatic (2) - the core networking stack. If any of these are Disabled the
            #                   guest can lose TCP/IP, DHCP or the firewall engine outright,
            #                   which presents as "no RDP" even when RDP itself is healthy.
            # Only a Disabled (4) or missing value is corrected, so an intentional
            # configuration is never overridden.
            $rdpServices = @(
                @{ Name = 'TermService'; DefaultStart = 3 }   # Remote Desktop Services
                @{ Name = 'SessionEnv'; DefaultStart = 3 }   # Remote Desktop Configuration
                @{ Name = 'UmRdpService'; DefaultStart = 3 }   # RD UserMode Port Redirector
                @{ Name = 'nsi'; DefaultStart = 2 }   # Network Store Interface - TCP/IP fails without it
                @{ Name = 'BFE'; DefaultStart = 2 }   # Base Filtering Engine - mpssvc cannot start without it
                @{ Name = 'mpssvc'; DefaultStart = 2 }   # Windows Firewall
                @{ Name = 'Dhcp'; DefaultStart = 2 }   # DHCP Client - no lease means no address
                @{ Name = 'Dnscache'; DefaultStart = 2 }   # DNS Client
                @{ Name = 'IKEEXT'; DefaultStart = 2 }   # IKE / AuthIP keying modules
                @{ Name = 'iphlpsvc'; DefaultStart = 2 }   # IP Helper
            )
            $startLabels = @{ 2 = 'Automatic (2)'; 3 = 'Manual (3)' }
            foreach ($svc in $rdpServices) {
                $svcPath = "$SystemRoot\Services\$($svc.Name)"
                if (Test-Path $svcPath) {
                    $current = (Get-ItemProperty $svcPath -ErrorAction SilentlyContinue).Start
                    if ($current -eq 4 -or $null -eq $current) {
                        Write-Host "  $($svc.Name): Start was $(if ($null -eq $current) {'(not set)'} else {'Disabled (4)'}) -> setting to $($startLabels[$svc.DefaultStart])" -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $svc.DefaultStart -Type DWord -Force
                    }
                    else {
                        Write-Host "  $($svc.Name): Start=$current (no change needed)" -ForegroundColor DarkGray
                    }
                }
                else {
                    Write-Host "  $($svc.Name): service key not found - skipping" -ForegroundColor DarkGray
                }
            }

            Set-ItemProperty-Logged -Path $WinStationsPath -Name SelfSignedCertStore -Value 'Remote Desktop' -Type String -Force

            Set-ItemProperty-Logged -Path $RdpTcpPath -Name PortNumber -Value 3389 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fInheritReconnectSame -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fReconnectSame -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fInheritMaxSessionTime -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fInheritMaxDisconnectionTime -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name MaxDisconnectionTime -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name MaxConnectionTime -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fInheritMaxIdleTime -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name MaxIdleTime -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name MaxInstanceCount -Value 4294967295 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name LanAdapter -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name TSServerDrainMode -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name fQueryUserConfigFromLocalMachine -Value 1 -Type Dword -Force

            # KeepAliveTimeout lives on the listener key, not only under Policies.
            # Writing just the policy copy leaves the listener running its own default.
            Set-ItemProperty-Logged -Path $RdpTcpPath -Name KeepAliveTimeout -Value 1 -Type Dword -Force

            Set-ItemProperty-Logged -Path $TSPolicyPath -Name KeepAliveEnable -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $TSPolicyPath -Name KeepAliveInterval -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $TSPolicyPath -Name KeepAliveTimeout -Value 1 -Type Dword -Force
            Set-ItemProperty-Logged -Path $TSPolicyPath -Name fDenyTSConnections -Value 0 -Type Dword -Force
            Set-ItemProperty-Logged -Path $TSPolicyPath -Name fDisableAutoReconnect -Value 0 -Type Dword -Force

            # -- Drop any certificate pinned to the RDP listener --------------------
            # A stale or self-signed SSLCertificateSHA1Hash whose private key no longer
            # resolves makes the TLS handshake fail before authentication, so the client
            # sees a generic "internal error". Removing the value lets Windows fall back
            # to regenerating a self-signed listener certificate on the next start.
            if ((Get-Item -Path $RdpTcpPath -ErrorAction SilentlyContinue).Property -contains 'SSLCertificateSHA1Hash') {
                Write-Host "Removing pinned RDP listener certificate (SSLCertificateSHA1Hash)..." -ForegroundColor Yellow
                Remove-ItemProperty-Logged -Path $RdpTcpPath -Name SSLCertificateSHA1Hash -Force
            }
            else {
                Write-Host "No pinned RDP listener certificate present (SSLCertificateSHA1Hash)." -ForegroundColor DarkGray
            }

            $SSLPolicyPath = "HKLM:\BROKENSOFTWARE\Policies\Microsoft\Cryptography\Configuration\SSL\00010002"
            Write-Host "Clearing SSL 00010002 'Functions'..." -ForegroundColor Yellow
            if (Test-Path -Path $SSLPolicyPath) {
                Remove-ItemProperty-Logged -Path $SSLPolicyPath -Name Functions -Force -ErrorAction SilentlyContinue
            }
            else {
                New-Item-Logged -Path $SSLPolicyPath -Force
            }

            $tls12Paths = @(
                "$SystemRoot\Control\SecurityProviders\SCHANNEL\Protocols\TLS 1.2\Client",
                "$SystemRoot\Control\SecurityProviders\SCHANNEL\Protocols\TLS 1.2\Server"
            )

            foreach ($tls12Path in $tls12Paths) {
                if (-not (Test-Path $tls12Path)) {
                    New-Item-Logged -Path $tls12Path -Force
                }

                Set-ItemProperty-Logged -Path $tls12Path -Name Enabled -Value 1 -Type DWord -Force | Out-Null
                Set-ItemProperty-Logged -Path $tls12Path -Name DisabledByDefault -Value 0 -Type DWord -Force | Out-Null
            }
        }
    }

    function ResetRDPPrivKeyPermissions {
        Write-Host "Resetting Windows RSA MachineKeys permissions..." -ForegroundColor Green
        $machineKeysPath = "$($script:WinDriveLetter)ProgramData\Microsoft\Crypto\RSA\MachineKeys"
        Write-Host "  [exec] takeown /f '$machineKeysPath' /a /r" -ForegroundColor DarkGray
        Invoke-NativeCommandLogged -Description 'Take ownership of RSA MachineKeys' -Details @{
            Path = $machineKeysPath
            Recursive = $true
        } -ScriptBlock { & takeown /f $machineKeysPath /a /r } | Out-Null
        Write-Host "  [exec] icacls '$machineKeysPath' /t /c /grant 'NT AUTHORITY\SYSTEM:(F)'" -ForegroundColor DarkGray
        Invoke-NativeCommandLogged -Description 'Grant SYSTEM FullControl on RSA MachineKeys' -Details @{
            Path = $machineKeysPath
            Principal = 'NT AUTHORITY\SYSTEM'
            Rights = 'FullControl'
            Recursive = $true
        } -ScriptBlock { & icacls $machineKeysPath /t /c /grant "NT AUTHORITY\SYSTEM:(F)" } | Out-Null
        Write-Host "  [exec] icacls '$machineKeysPath' /t /c /grant 'NT AUTHORITY\NETWORK SERVICE:(R)'" -ForegroundColor DarkGray
        Invoke-NativeCommandLogged -Description 'Grant NETWORK SERVICE Read on RSA MachineKeys' -Details @{
            Path = $machineKeysPath
            Principal = 'NT AUTHORITY\NETWORK SERVICE'
            Rights = 'Read'
            Recursive = $true
        } -ScriptBlock { & icacls $machineKeysPath /t /c /grant "NT AUTHORITY\NETWORK SERVICE:(R)" } | Out-Null
        Write-Host "  [exec] icacls '$machineKeysPath' /t /c /grant 'BUILTIN\Administrators:(F)'" -ForegroundColor DarkGray
        Invoke-NativeCommandLogged -Description 'Grant Administrators FullControl on RSA MachineKeys' -Details @{
            Path = $machineKeysPath
            Principal = 'BUILTIN\Administrators'
            Rights = 'FullControl'
            Recursive = $true
        } -ScriptBlock { & icacls $machineKeysPath /t /c /grant "BUILTIN\Administrators:(F)" } | Out-Null

        $PrivKeys = Get-ChildItem -Path "$($script:WinDriveLetter)ProgramData\Microsoft\Crypto\RSA\MachineKeys\f686aace6942fb7f7ceb231212eef4a4*"

        Write-Host "Resetting RDP certificate private key permissions..." -ForegroundColor Green

        ForEach ($PrivKey in $PrivKeys) {
            $pkPath = $PrivKey.FullName
            Write-Host "  [exec] takeown /f '$pkPath'" -ForegroundColor DarkGray
            Invoke-NativeCommandLogged -Description 'Take ownership of RDP private key' -Details @{
                Path = $pkPath
            } -ScriptBlock { & takeown.exe /f $pkPath } | Out-Null
            Write-Host "  [exec] icacls '$pkPath' /c /grant 'NT AUTHORITY\SYSTEM:(F)'" -ForegroundColor DarkGray
            Invoke-NativeCommandLogged -Description 'Grant SYSTEM FullControl on RDP private key' -Details @{
                Path = $pkPath
                Principal = 'NT AUTHORITY\SYSTEM'
                Rights = 'FullControl'
            } -ScriptBlock { & icacls.exe $pkPath /c /grant "NT AUTHORITY\SYSTEM:(F)" } | Out-Null
            Write-Host "  [exec] icacls '$pkPath' /c /grant 'NT AUTHORITY\NETWORK SERVICE:(R)'" -ForegroundColor DarkGray
            Invoke-NativeCommandLogged -Description 'Grant NETWORK SERVICE Read on RDP private key' -Details @{
                Path = $pkPath
                Principal = 'NT AUTHORITY\NETWORK SERVICE'
                Rights = 'Read'
            } -ScriptBlock { & icacls.exe $pkPath /c /grant "NT AUTHORITY\NETWORK SERVICE:(R)" } | Out-Null
            Write-Host "  [exec] icacls '$pkPath' /c /grant 'NT Service\SessionEnv:(F)'" -ForegroundColor DarkGray
            Invoke-NativeCommandLogged -Description 'Grant SessionEnv FullControl on RDP private key' -Details @{
                Path = $pkPath
                Principal = 'NT Service\SessionEnv'
                Rights = 'FullControl'
            } -ScriptBlock { & icacls.exe $pkPath /c /grant "NT Service\SessionEnv:(F)" } | Out-Null
            Write-Host "  [exec] icacls '$pkPath' (display current ACL)" -ForegroundColor DarkGray
            & icacls.exe $pkPath

            ExecuteAsSystem "icacls.exe `"$pkPath`" /setowner 'NT AUTHORITY\SYSTEM'"
        }

        Write-Host "Setting certificate services to default: CertPropSvc, KeyIso, CryptSvc, SessionEnv" -ForegroundColor Yellow
        Enable-ServiceOrDriver -ServiceName CertPropSvc -StartValue 3
        Enable-ServiceOrDriver -ServiceName KeyIso -StartValue 3
        Enable-ServiceOrDriver -ServiceName CryptSvc -StartValue 2
        Enable-ServiceOrDriver -ServiceName SessionEnv -StartValue 3
    }

    function RecreateRDPCertificate {
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath

            Write-Host "Configuring setup and adding script..." -ForegroundColor Green
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\newrdscert.cmd" -Type String -Force

            $newrdscert = @"
@echo off
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -ExecutionPolicy Bypass -File C:\temp\rdscert.ps1
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\temp\rdscert.ps1 > NUL
del /F C:\temp\newrdscert.cmd > NUL
"@

            $RecreateRDPCert = @'
$Passwd =  "REPLACE_WITH_PASSWORD"
$CertPasswd = ConvertTo-SecureString -String $Passwd -Force -AsPlainText
 
#Import certificate into 'Remote Desktop' and 'My' stores
Import-PfxCertificate -FilePath C:\temp\rds.pfx -CertStoreLocation 'Cert:\LocalMachine\Remote Desktop\' -Password $CertPasswd
Import-PfxCertificate -FilePath C:\temp\rds.pfx -CertStoreLocation 'Cert:\LocalMachine\My\' -Password $CertPasswd
 
#Set RDP protocol to use that just imported certificate
wmic /namespace:\\root\cimv2\TerminalServices PATH Win32_TSGeneralSetting Set SSLCertificateSHA1Hash="REPLACE_WITH_THUMBPRINT"

$bytes = (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp").SSLCertificateSHA1Hash

$expected = "REPLACE_WITH_THUMBPRINT"
$actual = ([BitConverter]::ToString($bytes) -replace '-', '')
$certbinary = ([byte[]]([regex]::Matches($expected,"..") | % { [Convert]::ToByte($_.Value,16) }))

$expected = $expected.ToUpper()
$actual   = $actual.ToUpper()

    if ($actual -ne $expected) {
        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name SSLCertificateSHA1Hash -Type Binary -Force -Value $certbinary
    }
 
#Restart RDP service (try to restart twice)
Restart-Service TermService -Force
Restart-Service TermService -Force

#Enable RDP and SMB rules in Windows Firewall
Enable-NetFirewallRule FPS-SMB-In-TCP
Enable-NetFirewallRule RemoteDesktop-UserMode-In-TCP

#Clean up
Remove-Item -Path C:\temp\rds.pfx -Force
'@

            Ensure-GuestTempDir
            $guestName = if ($script:GuestComputerName) { $script:GuestComputerName } else { (Get-ItemProperty "$SystemRoot\Control\ComputerName\ComputerName").ComputerName }

            Write-Host "Generating new certificate to guest $guestname locally..." -ForegroundColor Green
            $cert = New-SelfSignedCertificate -Type Custom -KeySpec Signature -Subject "CN=$($guestName)" -KeyExportPolicy Exportable -HashAlgorithm sha256 -KeyLength 2048 `
                -CertStoreLocation "Cert:\LocalMachine\My" -TextExtension @("2.5.29.37={text}1.3.6.1.5.5.7.3.1") -NotAfter (Get-Date).AddYears(5)

            # Generate a cryptographically random one-time PFX transport password (never hardcoded).
            # Use the RandomNumberGenerator instance API (Create().GetBytes([byte[]])) rather than the
            # static GetBytes(int) overload, which only exists on .NET 6+ and is unavailable on the
            # Windows PowerShell 5.1 / .NET Framework 4.x host used to repair downlevel guests.
            $rngBytes = New-Object 'byte[]' 24
            $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
            try { $rng.GetBytes($rngBytes) } finally { $rng.Dispose() }
            $PfxPassword = [System.Convert]::ToBase64String($rngBytes) -replace '[^A-Za-z0-9]', 'x'
            $certpwd = ConvertTo-SecureString $PfxPassword -AsPlainText -Force

            $hostPfx = Join-Path $WinDriveLetter "Temp\rds.pfx"
            Write-Host "Exporting new cert with thumbprint $($cert.Thumbprint) to $hostPfx..." -ForegroundColor Green
            Export-PfxCertificate -Cert $cert -FilePath $hostPfx -Password $certpwd | Out-Null
            Remove-Item-Logged -Path "Cert:\LocalMachine\My\$($cert.Thumbprint)" -Force

            New-Item-Logged -Path "$WinDriveLetter\Temp" -Name "newrdscert.cmd" -ItemType File -Value $newrdscert.ToString().Trim() -Force
            New-Item-Logged -Path "$WinDriveLetter\Temp" -Name "rdscert.ps1" -ItemType File -Value $RecreateRDPCert.ToString().Trim().Replace("REPLACE_WITH_PASSWORD", $PfxPassword).Replace("REPLACE_WITH_THUMBPRINT", $cert.Thumbprint) -Force -RedactValue

            Write-Host "A script to recreate the RDP certificate will run at next boot. If the RDP service fails to restart after that, you may need to restart the VM." -ForegroundColor Green
        }
    }

    function SetNLA {
        param([bool]$Enable)
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath
            $SoftwareRoot = "HKLM:\BROKENSOFTWARE"

            $RdpTcpPath = "$SystemRoot\Control\Terminal Server\Winstations\RDP-Tcp"
            $TSPolicyPath = "$SoftwareRoot\Policies\Microsoft\Windows NT\Terminal Services"

            if ($Enable) {
                Write-Host "Enabling NLA..." -ForegroundColor Green

                Set-ItemProperty-Logged -Path $RdpTcpPath -Name UserAuthentication -Value 1 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name SecurityLayer -Value 2 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name fAllowSecProtocolNegotiation -Value 1 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name MinEncryptionLevel -Value 2 -Type Dword -Force

                # Clear any policy overrides that would re-disable NLA after reboot.
                # These values may not exist (e.g. on a clean VM), so suppress the error.
                if (Test-Path $TSPolicyPath) {
                    foreach ($val in @('UserAuthentication', 'SecurityLayer', 'fAllowSecProtocolNegotiation', 'MinEncryptionLevel')) {
                        Remove-ItemProperty-Logged -Path $TSPolicyPath -Name $val -Force -ErrorAction SilentlyContinue
                    }
                }
            }
            else {
                Write-Host "Disabling NLA..." -ForegroundColor Green

                Set-ItemProperty-Logged -Path $RdpTcpPath -Name UserAuthentication -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name SecurityLayer -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name fAllowSecProtocolNegotiation -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $RdpTcpPath -Name MinEncryptionLevel -Value 1 -Type Dword -Force
 
                Set-ItemProperty-Logged -Path $TSPolicyPath -Name UserAuthentication -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $TSPolicyPath -Name SecurityLayer -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $TSPolicyPath -Name fAllowSecProtocolNegotiation -Value 0 -Type Dword -Force
                Set-ItemProperty-Logged -Path $TSPolicyPath -Name MinEncryptionLevel -Value 1 -Type Dword -Force
            }
        }
    }

    # ==========================================================================
    # Servicing transaction log cleanup
    # ==========================================================================
    # Windows keeps CLFS/KTM transaction logs (.blf and .regtrans-ms) next to the
    # registry hives they protect. When those logs fill up, or are left inconsistent
    # by an interrupted servicing operation, updates fail with 0x800719e4
    # (ERROR_LOG_FULL) or the guest hangs processing updates at boot. The documented
    # repair is to delete the log files and let Windows recreate them at next boot:
    # https://learn.microsoft.com/troubleshoot/windows-server/installing-updates-features-roles/error-0x800719e4-windows-update-fails
    #
    # None of the three folders involved holds only transaction logs:
    #   Windows\System32\config             SYSTEM, SOFTWARE, SAM, SECURITY, DEFAULT
    #   Windows\System32\SMI\Store\Machine  SCHEMA.DAT
    #   Windows\System32\config\TxR         resource manager logs; ACL-restricted
    #
    # .LOG1 and .LOG2 are hive RECOVERY logs, not transaction logs. Removing one from
    # under a dirty hive turns a recoverable installation into a 0xC0000218 at boot.
    # Selection is therefore an explicit extension whitelist rather than a wildcard
    # filter, and the attribute change, the backup and the deletion all operate on
    # that one list - never on a re-enumeration of the folder.
    $script:TransactionLogExtensions = @('.blf', '.regtrans-ms')

    # Test-RegistryHiveFile copies a hive to validate it, and runs twice per repair
    # (baseline and verification). Above this size the hive is reported as skipped
    # rather than copied; the file-level comparison still proves it was not modified.
    $script:TransactionLogHiveTestMaxBytes = 512MB

    function Get-TransactionLogScopeInfo {
        # Target folder and the hives protected by that folder's resource manager.
        param([Parameter(Mandatory = $true)][ValidateSet('TxR', 'Config', 'SMI')][string]$Scope)

        $configFolder = Join-Path $script:WinDriveLetter 'Windows\System32\config'
        $registryHives = @('SYSTEM', 'SOFTWARE', 'SAM', 'SECURITY', 'DEFAULT', 'COMPONENTS')

        switch ($Scope) {
            'TxR' {
                return [pscustomobject]@{
                    Scope      = 'TxR'
                    Label      = 'config\TxR'
                    Path       = (Join-Path $configFolder 'TxR')
                    HiveFolder = $configFolder
                    HiveNames  = $registryHives
                }
            }
            'Config' {
                return [pscustomobject]@{
                    Scope      = 'Config'
                    Label      = 'config'
                    Path       = $configFolder
                    HiveFolder = $configFolder
                    HiveNames  = $registryHives
                }
            }
            'SMI' {
                $smiFolder = Join-Path $script:WinDriveLetter 'Windows\System32\SMI\Store\Machine'
                return [pscustomobject]@{
                    Scope      = 'SMI'
                    Label      = 'SMI\Store\Machine'
                    Path       = $smiFolder
                    HiveFolder = $smiFolder
                    HiveNames  = @('SCHEMA.DAT')
                }
            }
        }
    }

    function Get-TransactionLogFileHash {
        param([Parameter(Mandatory = $true)][string]$Path)
        try { return (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash }
        catch { return $null }
    }

    function Get-TransactionLogFolderSnapshot {
        # Records everything needed to prove afterwards that only the intended files
        # changed: the log files themselves, every other file in the folder, and the
        # folder's own identity (creation time and security descriptor).
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [switch]$IncludeHash
        )

        $snapshot = [pscustomobject]@{
            Path        = $Path
            Present     = $false
            Accessible  = $false
            AccessError = ''
            CreatedUtc  = $null
            Sddl        = $null
            LogFiles    = @()
            OtherFiles  = @()
        }

        # Directory.Exists reports presence from the parent entry, so a folder that
        # denies enumeration is still correctly reported as present rather than missing.
        if (-not [System.IO.Directory]::Exists($Path)) { return $snapshot }
        $snapshot.Present = $true

        try { $snapshot.CreatedUtc = (Get-Item -LiteralPath $Path -Force -ErrorAction Stop).CreationTimeUtc }
        catch { }

        try {
            $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
            $snapshot.Sddl = $acl.GetSecurityDescriptorSddlForm(
                [System.Security.AccessControl.AccessControlSections]::Owner -bor
                [System.Security.AccessControl.AccessControlSections]::Access)
        }
        catch {
            # config\TxR restricts its descriptor on some builds. An unreadable SDDL is
            # recorded as $null; folder identity is then asserted via CreationTimeUtc.
            $snapshot.Sddl = $null
        }

        $logFiles = [System.Collections.Generic.List[object]]::new()
        $otherFiles = [System.Collections.Generic.List[object]]::new()
        try {
            $children = @(Get-ChildItem -LiteralPath $Path -File -Force -ErrorAction Stop)
            $snapshot.Accessible = $true
            foreach ($child in $children) {
                $entry = [pscustomobject]@{
                    Name             = $child.Name
                    FullName         = $child.FullName
                    Length           = $child.Length
                    LastWriteTimeUtc = $child.LastWriteTimeUtc
                    Attributes       = [string]$child.Attributes
                    Sha256           = $null
                }
                if ($script:TransactionLogExtensions -contains $child.Extension.ToLowerInvariant()) {
                    if ($IncludeHash) { $entry.Sha256 = Get-TransactionLogFileHash -Path $child.FullName }
                    $logFiles.Add($entry) | Out-Null
                }
                else {
                    $otherFiles.Add($entry) | Out-Null
                }
            }
        }
        catch {
            $snapshot.Accessible = $false
            $snapshot.AccessError = $_.Exception.Message
        }

        $snapshot.LogFiles = $logFiles.ToArray()
        $snapshot.OtherFiles = $otherFiles.ToArray()
        return $snapshot
    }

    function Get-TransactionLogHiveState {
        # Loads each protected hive through RegLoadAppKey so a genuinely damaged hive is
        # detected rather than assumed healthy from its header alone.
        param([Parameter(Mandatory = $true)]$ScopeInfo)

        $results = [System.Collections.Generic.List[object]]::new()
        foreach ($hiveName in $ScopeInfo.HiveNames) {
            $hivePath = Join-Path $ScopeInfo.HiveFolder $hiveName
            $entry = [pscustomobject]@{
                Name    = $hiveName
                Path    = $hivePath
                Present = $false
                Tested  = $false
                IsValid = $null
                Size    = 0
                Reason  = ''
            }

            if (-not [System.IO.File]::Exists($hivePath)) {
                $entry.Reason = 'not present'
                $results.Add($entry) | Out-Null
                continue
            }
            $entry.Present = $true
            try { $entry.Size = (Get-Item -LiteralPath $hivePath -Force -ErrorAction Stop).Length } catch { }

            if ($entry.Size -gt $script:TransactionLogHiveTestMaxBytes) {
                $entry.Reason = 'skipped - {0} MB exceeds the {1} MB validation limit' -f `
                    [math]::Round($entry.Size / 1MB), [math]::Round($script:TransactionLogHiveTestMaxBytes / 1MB)
                $results.Add($entry) | Out-Null
                continue
            }

            try {
                $test = Test-RegistryHiveFile -Path $hivePath
                $entry.Tested = $true
                $entry.IsValid = [bool]$test.IsValid
                if (-not $entry.IsValid) { $entry.Reason = [string]$test.Reason }
            }
            catch {
                $entry.Reason = "validation could not run: $($_.Exception.Message)"
            }

            $results.Add($entry) | Out-Null
        }
        return $results.ToArray()
    }

    function Get-TransactionLogCleanupPlan {
        # Read-only. Produces everything the repair and its verification need, and
        # writes nothing, so it is safe to call for reporting on its own.
        param(
            [Parameter(Mandatory = $true)][ValidateSet('TxR', 'Config', 'SMI')][string[]]$Scope,
            [switch]$SkipHiveState
        )

        $plans = [System.Collections.Generic.List[object]]::new()
        foreach ($scopeName in $Scope) {
            $info = Get-TransactionLogScopeInfo -Scope $scopeName
            $snapshot = Get-TransactionLogFolderSnapshot -Path $info.Path -IncludeHash
            $hives = if ($SkipHiveState) { @() } else { @(Get-TransactionLogHiveState -ScopeInfo $info) }
            $bytes = 0
            if ($snapshot.LogFiles.Count -gt 0) {
                $bytes = [long](($snapshot.LogFiles | Measure-Object -Property Length -Sum).Sum)
            }

            $plans.Add([pscustomobject]@{
                    Scope       = $info.Scope
                    Label       = $info.Label
                    Path        = $info.Path
                    Snapshot    = $snapshot
                    Hives       = $hives
                    BackupBytes = $bytes
                }) | Out-Null
        }
        return $plans.ToArray()
    }

    function Show-TransactionLogCleanupPlan {
        param([Parameter(Mandatory = $true)]$Plan)

        foreach ($scopePlan in $Plan) {
            if (-not $scopePlan.Snapshot.Present) {
                Write-Host "  $($scopePlan.Label): folder not found, skipping." -ForegroundColor DarkGray
                continue
            }
            if (-not $scopePlan.Snapshot.Accessible) {
                Write-Warning "  $($scopePlan.Label): folder could not be read - $($scopePlan.Snapshot.AccessError)"
                continue
            }

            $count = $scopePlan.Snapshot.LogFiles.Count
            if ($count -eq 0) {
                Write-Host "  $($scopePlan.Label): no .blf/.regtrans-ms files - nothing to do." -ForegroundColor Green
                continue
            }

            Write-Host "  $($scopePlan.Label): $count transaction log file(s), $([math]::Round($scopePlan.BackupBytes / 1KB)) KB" -ForegroundColor Yellow
            foreach ($file in $scopePlan.Snapshot.LogFiles) {
                Write-Host "      $($file.Name)" -ForegroundColor DarkGray
            }
            $keep = $scopePlan.Snapshot.OtherFiles.Count
            if ($keep -gt 0) {
                Write-Host "      ($keep other file(s) in this folder will not be touched)" -ForegroundColor DarkGray
            }
        }
    }

    function Test-TransactionLogCleanupResult {
        # The gate that decides pass or rollback. Re-reads each folder and compares it
        # against the pre-flight snapshot. Every way this repair could break a guest is
        # asserted here: hive damage, a lost folder ACL, and deletion of a recovery log.
        param(
            [Parameter(Mandatory = $true)]$ScopePlan,
            [Parameter(Mandatory = $true)][string]$BackupPath
        )

        $checks = [System.Collections.Generic.List[object]]::new()
        $addCheck = {
            param([string]$Name, [bool]$Passed, [string]$Detail)
            $checks.Add([pscustomobject]@{ Name = $Name; Passed = $Passed; Detail = $Detail }) | Out-Null
        }

        $before = $ScopePlan.Snapshot
        $info = Get-TransactionLogScopeInfo -Scope $ScopePlan.Scope
        $after = Get-TransactionLogFolderSnapshot -Path $ScopePlan.Path

        # 1. The folder still exists and is the same directory. A recreated folder gets a
        #    new creation time, which is exactly the defect this repair removed.
        if (-not $after.Present) {
            & $addCheck 'Folder still present' $false "$($ScopePlan.Path) is gone"
        }
        else {
            & $addCheck 'Folder still present' $true ''
            if ($before.CreatedUtc -and $after.CreatedUtc) {
                $sameFolder = ($before.CreatedUtc -eq $after.CreatedUtc)
                & $addCheck 'Folder not recreated' $sameFolder $(if ($sameFolder) { '' } else { "creation time changed from $($before.CreatedUtc.ToString('o')) to $($after.CreatedUtc.ToString('o'))" })
            }
        }

        # 2. The security descriptor is unchanged. Skipped, not failed, when the
        #    descriptor was unreadable to begin with.
        if ($null -eq $before.Sddl) {
            & $addCheck 'Folder ACL unchanged' $true 'skipped - descriptor not readable on this host'
        }
        else {
            $sameAcl = ($before.Sddl -eq $after.Sddl)
            & $addCheck 'Folder ACL unchanged' $sameAcl $(if ($sameAcl) { '' } else { 'security descriptor differs from the pre-repair capture' })
        }

        # 3. Exactly the planned files were removed - no more, no fewer.
        $plannedNames = @($before.LogFiles | ForEach-Object { $_.Name })
        $remainingNames = @($after.LogFiles | ForEach-Object { $_.Name })
        $unexpectedlyLeft = @($remainingNames | Where-Object { $plannedNames -contains $_ })
        & $addCheck 'Planned log files removed' ($unexpectedlyLeft.Count -eq 0) $(if ($unexpectedlyLeft.Count -eq 0) { "$($plannedNames.Count) removed" } else { "still present: $($unexpectedlyLeft -join ', ')" })

        # 4. Nothing else in the folder was modified. This is the direct proof that the
        #    hives and their .LOG1/.LOG2 were neither deleted nor stripped of
        #    System/Hidden by the attribute step.
        $afterOthers = @{}
        foreach ($file in $after.OtherFiles) { $afterOthers[$file.Name] = $file }
        $drift = [System.Collections.Generic.List[string]]::new()
        foreach ($file in $before.OtherFiles) {
            if (-not $afterOthers.ContainsKey($file.Name)) {
                $drift.Add("$($file.Name) is missing") | Out-Null
                continue
            }
            $now = $afterOthers[$file.Name]
            if ($now.Length -ne $file.Length) { $drift.Add("$($file.Name) size $($file.Length) -> $($now.Length)") | Out-Null }
            if ($now.LastWriteTimeUtc -ne $file.LastWriteTimeUtc) { $drift.Add("$($file.Name) modified time changed") | Out-Null }
            if ($now.Attributes -ne $file.Attributes) { $drift.Add("$($file.Name) attributes $($file.Attributes) -> $($now.Attributes)") | Out-Null }
        }
        & $addCheck 'Other files untouched' ($drift.Count -eq 0) $(if ($drift.Count -eq 0) { "$($before.OtherFiles.Count) file(s) unchanged" } else { ($drift -join '; ') })

        # 5. The backup holds a byte-identical copy of everything that was deleted, so
        #    the change is reversible.
        $backupProblems = [System.Collections.Generic.List[string]]::new()
        foreach ($file in $before.LogFiles) {
            $backupFile = Join-Path $BackupPath $file.Name
            if (-not [System.IO.File]::Exists($backupFile)) {
                $backupProblems.Add("$($file.Name) was not backed up") | Out-Null
                continue
            }
            $backupItem = Get-Item -LiteralPath $backupFile -Force -ErrorAction SilentlyContinue
            if ($null -eq $backupItem -or $backupItem.Length -ne $file.Length) {
                $backupProblems.Add("$($file.Name) backup size differs") | Out-Null
                continue
            }
            if ($file.Sha256) {
                $backupHash = Get-TransactionLogFileHash -Path $backupFile
                if ($backupHash -ne $file.Sha256) { $backupProblems.Add("$($file.Name) backup hash differs") | Out-Null }
            }
        }
        & $addCheck 'Backup complete and restorable' ($backupProblems.Count -eq 0) $(if ($backupProblems.Count -eq 0) { "$($before.LogFiles.Count) file(s) in $BackupPath" } else { ($backupProblems -join '; ') })

        # 6. Every hive that loaded before still loads. A hive going PASS -> FAIL is the
        #    condition that must trigger a rollback.
        if ($ScopePlan.Hives.Count -gt 0) {
            $hivesAfter = @{}
            foreach ($hive in (Get-TransactionLogHiveState -ScopeInfo $info)) { $hivesAfter[$hive.Name] = $hive }
            $regressed = [System.Collections.Generic.List[string]]::new()
            $revalidated = 0
            foreach ($hive in $ScopePlan.Hives) {
                if (-not $hive.Tested -or $hive.IsValid -ne $true) { continue }
                $revalidated++
                $now = $hivesAfter[$hive.Name]
                if ($null -eq $now -or $now.IsValid -ne $true) {
                    $regressed.Add("$($hive.Name) no longer loads") | Out-Null
                }
            }
            & $addCheck 'Registry hives still load' ($regressed.Count -eq 0) $(if ($regressed.Count -eq 0) { "$revalidated hive(s) revalidated" } else { ($regressed -join '; ') })
        }

        return [pscustomobject]@{
            Scope  = $ScopePlan.Scope
            Label  = $ScopePlan.Label
            Checks = $checks.ToArray()
            Passed = (@($checks | Where-Object { -not $_.Passed }).Count -eq 0)
        }
    }

    function Show-TransactionLogVerification {
        param([Parameter(Mandatory = $true)]$Result)

        foreach ($scopeResult in $Result) {
            $header = if ($scopeResult.Passed) { 'PASS' } else { 'FAIL' }
            $headerColor = if ($scopeResult.Passed) { 'Green' } else { 'Red' }
            Write-Host "  [$header] $($scopeResult.Label)" -ForegroundColor $headerColor
            foreach ($check in $scopeResult.Checks) {
                $mark = if ($check.Passed) { 'ok  ' } else { 'FAIL' }
                $color = if ($check.Passed) { 'DarkGray' } else { 'Red' }
                $detail = if ($check.Detail) { " - $($check.Detail)" } else { '' }
                Write-Host "         [$mark] $($check.Name)$detail" -ForegroundColor $color
            }
        }
    }

    function Restore-TransactionLogBackup {
        # Rollback path. Copies the backed-up log files back and restores the exact
        # attributes they carried before the repair.
        param(
            [Parameter(Mandatory = $true)]$ScopePlan,
            [Parameter(Mandatory = $true)][string]$BackupPath
        )

        Write-Warning "Rolling back transaction log cleanup for $($ScopePlan.Label)..."
        $restored = 0
        $failed = [System.Collections.Generic.List[string]]::new()
        foreach ($file in $ScopePlan.Snapshot.LogFiles) {
            $backupFile = Join-Path $BackupPath $file.Name
            if (-not [System.IO.File]::Exists($backupFile)) {
                $failed.Add("$($file.Name) has no backup copy") | Out-Null
                continue
            }
            try {
                Copy-Item-Logged -Path $backupFile -Destination $file.FullName -Force
                $restoredItem = Get-Item -LiteralPath $file.FullName -Force -ErrorAction Stop
                $restoredItem.Attributes = [System.IO.FileAttributes]$file.Attributes
                $restored++
            }
            catch {
                $failed.Add("$($file.Name): $($_.Exception.Message)") | Out-Null
            }
        }

        Write-ActionLog -Event 'ClearTransactionLogsRollback' -Details @{
            Scope    = $ScopePlan.Scope
            Path     = $ScopePlan.Path
            Backup   = $BackupPath
            Restored = $restored
            Failed   = $failed.ToArray()
        }

        if ($failed.Count -gt 0) {
            Write-Error "Rollback did not fully complete for $($ScopePlan.Label): $($failed -join '; ')"
            Write-Host "  Restore manually from: $BackupPath" -ForegroundColor Yellow
            Write-Host "    Copy-Item '$BackupPath\*' '$($ScopePlan.Path)' -Force" -ForegroundColor Yellow
            return $false
        }

        Write-Host "  Rolled back $restored file(s) to $($ScopePlan.Path)." -ForegroundColor Yellow
        return $true
    }

    function Enable-ServicingRepairPrivilege {
        # WinSxS, pending.xml and the CBS pending keys are owned by TrustedInstaller and
        # deny write to Administrators. Taking ownership requires these privileges to be
        # enabled in the token, not merely held, which is not the default.
        if (-not ('RepairAzVmDiskServicingPrivilege' -as [type])) {
            $privilegeSource = @'
using System;
using System.Runtime.InteropServices;

public static class RepairAzVmDiskServicingPrivilege
{
    [StructLayout(LayoutKind.Sequential)]
    private struct LUID { public UInt32 LowPart; public Int32 HighPart; }

    [StructLayout(LayoutKind.Sequential)]
    private struct LUID_AND_ATTRIBUTES { public LUID Luid; public UInt32 Attributes; }

    [StructLayout(LayoutKind.Sequential)]
    private struct TOKEN_PRIVILEGES { public UInt32 PrivilegeCount; public LUID_AND_ATTRIBUTES Privilege; }

    private const UInt32 TOKEN_ADJUST_PRIVILEGES = 0x0020;
    private const UInt32 TOKEN_QUERY = 0x0008;
    private const UInt32 SE_PRIVILEGE_ENABLED = 0x0002;

    [DllImport("advapi32.dll", SetLastError = true)]
    private static extern bool OpenProcessToken(IntPtr processHandle, UInt32 desiredAccess, out IntPtr tokenHandle);

    [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    private static extern bool LookupPrivilegeValue(string systemName, string privilegeName, out LUID luid);

    [DllImport("advapi32.dll", SetLastError = true)]
    private static extern bool AdjustTokenPrivileges(IntPtr tokenHandle, bool disableAll, ref TOKEN_PRIVILEGES newState, UInt32 bufferLength, IntPtr previousState, IntPtr returnLength);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool CloseHandle(IntPtr handle);

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetCurrentProcess();

    public static bool Enable(string privilegeName)
    {
        IntPtr token;
        if (!OpenProcessToken(GetCurrentProcess(), TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, out token))
        {
            return false;
        }
        try
        {
            LUID luid;
            if (!LookupPrivilegeValue(null, privilegeName, out luid))
            {
                return false;
            }
            TOKEN_PRIVILEGES privileges = new TOKEN_PRIVILEGES();
            privileges.PrivilegeCount = 1;
            privileges.Privilege.Luid = luid;
            privileges.Privilege.Attributes = SE_PRIVILEGE_ENABLED;
            if (!AdjustTokenPrivileges(token, false, ref privileges, 0, IntPtr.Zero, IntPtr.Zero))
            {
                return false;
            }
            return Marshal.GetLastWin32Error() == 0;
        }
        finally
        {
            CloseHandle(token);
        }
    }
}
'@
            Add-Type -TypeDefinition $privilegeSource -ErrorAction Stop
        }

        foreach ($privilege in @('SeTakeOwnershipPrivilege', 'SeRestorePrivilege', 'SeBackupPrivilege', 'SeSecurityPrivilege')) {
            [void][RepairAzVmDiskServicingPrivilege]::Enable($privilege)
        }
    }

    function Grant-ProtectedPathAccess {
        # Takes ownership of a TrustedInstaller-owned file or folder and grants this
        # account FullControl, returning the original descriptor in SDDL form so it can
        # be replayed verbatim afterwards.
        #
        # The descriptor is captured and replayed whole on purpose. Rebuilding one of
        # these ACLs rule by rule - or removing a granted ACE with icacls /remove:g -
        # also removes the ACEs Windows shipped, which silently damages WinSxS.
        param([Parameter(Mandatory = $true)][string]$Path)

        Enable-ServicingRepairPrivilege

        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        $isDirectory = $item.PSIsContainer
        $sections = 'Owner,Group,Access'

        $originalSddl = $null
        try { $originalSddl = (Get-Acl -LiteralPath $Path).GetSecurityDescriptorSddlForm($sections) }
        catch { Write-Warning "Could not read the security descriptor of $Path : $($_.Exception.Message)" }

        # An object that cannot be handed back should not be taken.
        if (-not $originalSddl) { return $null }

        $me = ([System.Security.Principal.WindowsIdentity]::GetCurrent()).User

        # Only the owner section is set here, so the existing DACL is left intact. The
        # DACL cannot be written until ownership is held - but writing the owner back to
        # the value it already holds is a privileged write that buys nothing, and an
        # existing owner already carries the WRITE_DAC the grant below needs.
        $currentOwner = ''
        try {
            $rawSd = [System.Security.AccessControl.RawSecurityDescriptor]::new($originalSddl)
            if ($rawSd.Owner) { $currentOwner = $rawSd.Owner.Value }
        }
        catch { }

        if ($currentOwner -ne $me.Value) {
            if ($isDirectory) {
                $ownerOnly = [System.Security.AccessControl.DirectorySecurity]::new()
                $ownerOnly.SetOwner($me)
                [System.IO.Directory]::SetAccessControl($Path, $ownerOnly)
            }
            else {
                $ownerOnly = [System.Security.AccessControl.FileSecurity]::new()
                $ownerOnly.SetOwner($me)
                [System.IO.File]::SetAccessControl($Path, $ownerOnly)
            }
        }

        # Built from the captured SDDL rather than from Get-Acl, so that only the DACL is
        # ever written. A descriptor that carries the SACL along demands SeSecurityPrivilege
        # for a change that has nothing to do with auditing, and fails for that reason alone.
        # The granted ACE deliberately does not inherit: pushing it onto children would
        # alter descriptors that were never captured and so could never be put back.
        $acl = if ($isDirectory) {
            [System.Security.AccessControl.DirectorySecurity]::new()
        }
        else {
            [System.Security.AccessControl.FileSecurity]::new()
        }
        $acl.SetSecurityDescriptorSddlForm($originalSddl, 'Access')
        $acl.AddAccessRule([System.Security.AccessControl.FileSystemAccessRule]::new(
                $me, 'FullControl', 'None', 'None', 'Allow'))
        if ($isDirectory) { [System.IO.Directory]::SetAccessControl($Path, $acl) }
        else { [System.IO.File]::SetAccessControl($Path, $acl) }

        return $originalSddl
    }

    function Restore-ProtectedPathAccess {
        # Replays a descriptor captured by Grant-ProtectedPathAccess. Missing paths are
        # ignored so the caller can offer both the original and the renamed path without
        # having to work out which one survived.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [string]$Sddl = ''
        )

        if (-not $Sddl) { return }
        if (-not (Test-Path -LiteralPath $Path)) { return }

        Enable-ServicingRepairPrivilege

        # Only the sections that actually differ are written. If ownership was never taken
        # - because it was already ours - then replaying the owner is a privileged write
        # with no effect, and on a restricted token it fails and takes the DACL restore
        # down with it.
        $sections = 'Owner,Group,Access'
        try {
            $capturedOwner = ([System.Security.AccessControl.RawSecurityDescriptor]::new($Sddl)).Owner
            $currentSddl = (Get-Acl -LiteralPath $Path).GetSecurityDescriptorSddlForm('Owner,Group,Access')
            $currentOwner = ([System.Security.AccessControl.RawSecurityDescriptor]::new($currentSddl)).Owner
            if ($capturedOwner -and $currentOwner -and $capturedOwner.Value -eq $currentOwner.Value) {
                $sections = 'Access'
            }
        }
        catch { }

        try {
            if ((Get-Item -LiteralPath $Path -Force).PSIsContainer) {
                $sd = [System.Security.AccessControl.DirectorySecurity]::new()
                $sd.SetSecurityDescriptorSddlForm($Sddl, $sections)
                [System.IO.Directory]::SetAccessControl($Path, $sd)
            }
            else {
                $sd = [System.Security.AccessControl.FileSecurity]::new()
                $sd.SetSecurityDescriptorSddlForm($Sddl, $sections)
                [System.IO.File]::SetAccessControl($Path, $sd)
            }
        }
        catch {
            Write-Warning "Could not restore the original ACL on $Path : $($_.Exception.Message)"
            Write-Host "  Restore it manually with: icacls '$Path' /setowner 'NT SERVICE\TrustedInstaller'" -ForegroundColor Yellow
        }
    }

    function Clear-ProtectedFileAttribute {
        # ReadOnly, Hidden and System all refuse a delete or rename, and the write that
        # clears them is itself refused on a protected file - which is why this is called
        # again after ownership is taken rather than only before.
        param([Parameter(Mandatory = $true)][string]$Path)

        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            $blocking = ([System.IO.FileAttributes]::ReadOnly -bor
                [System.IO.FileAttributes]::Hidden -bor
                [System.IO.FileAttributes]::System)
            if ($item.Attributes -band $blocking) {
                $item.Attributes = ($item.Attributes -band (-bnot $blocking))
            }
        }
        catch {
            Write-Verbose "Attributes on $Path could not be cleared: $($_.Exception.Message)"
        }
    }

    function Test-ProtectedPathReadable {
        # Whether this account can actually open the file for reading, which is not the
        # same question as whether it exists. Used to tell a protected source apart from
        # a protected destination, because the copy reports only one error for both.
        param([Parameter(Mandatory = $true)][string]$Path)

        try {
            $stream = [System.IO.File]::Open(
                $Path,
                [System.IO.FileMode]::Open,
                [System.IO.FileAccess]::Read,
                [System.IO.FileShare]'ReadWrite, Delete')
            $stream.Dispose()
            return $true
        }
        catch {
            return $false
        }
    }

    function Copy-ProtectedSystemFile {
        # Writes a file into a TrustedInstaller-owned folder, taking ownership of the
        # destination and its parent only when the plain copy is refused.
        #
        # On an offline guest disk, \Windows\System32\drivers\<driver>.sys is owned by
        # NT SERVICE\TrustedInstaller. The rescue VM's SYSTEM/Administrator token is not
        # the owner, so Copy-Item over the top fails with "Access to the path is denied"
        # - which is how a repair reports success while having changed nothing.
        #
        # The copy is made in place so the destination keeps its own descriptor rather
        # than inheriting the rescue VM's idea of the ACL. Both borrowed descriptors are
        # replayed in a finally, so the guest boots with TrustedInstaller owning its
        # system files again whether the copy succeeded, failed, or threw.
        param(
            [Parameter(Mandatory = $true)][string]$Source,
            [Parameter(Mandatory = $true)][string]$Destination
        )

        $result = [PSCustomObject]@{
            Copied        = $false
            TookOwnership = $false
            Restored      = $false
            Reason        = ''
        }

        if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) {
            $result.Reason = "The source file $Source was not present."
            return $result
        }

        $existed = $false
        try { $existed = Test-Path -LiteralPath $Destination -PathType Leaf -ErrorAction Stop }
        catch {
            Write-Verbose "Whether $Destination exists could not be checked ($($_.Exception.Message)). Treating that as protection rather than absence."
        }

        # SeRestorePrivilege on its own is usually enough to write over a file this
        # account has no rights to, so it is enabled before the plain attempt rather
        # than only in the fallback. That turns the common case into a single copy with
        # nobody's ACL touched, and leaves the take-ownership path for the rest.
        Enable-ServicingRepairPrivilege

        try {
            if ($existed) { Clear-ProtectedFileAttribute -Path $Destination }
            Copy-Item -LiteralPath $Source -Destination $Destination -Force -ErrorAction Stop
            $result.Copied = $true
            $result.Reason = 'Copied without changing any permission.'
            return $result
        }
        catch {
            $firstError = $_.Exception.Message
        }

        $parent = Split-Path -Path $Destination -Parent
        Write-Host "  $Destination could not be written ($firstError)." -ForegroundColor DarkGray

        $parentSddl = $null
        $fileSddl = $null
        $sourceSddl = $null
        $sourceParentSddl = $null
        try {
            # A protected source is as likely as a protected destination, because the
            # spare copy normally comes out of WinSxS and TrustedInstaller owns that too.
            # The copy reports one error for both ends, so the source is tested directly
            # rather than guessed at from the message.
            if (-not (Test-ProtectedPathReadable -Path $Source)) {
                Write-Host "  The source $Source cannot be read either. Taking it as well." -ForegroundColor DarkGray
                $sourceSddl = Grant-ProtectedPathAccess -Path $Source
                if (-not (Test-ProtectedPathReadable -Path $Source)) {
                    # Nothing under the folder can be opened until the folder itself
                    # allows a traverse, so the file's own ACL was never the obstacle.
                    $sourceParentSddl = Grant-ProtectedPathAccess -Path (Split-Path -Path $Source -Parent)
                    if (-not $sourceSddl) { $sourceSddl = Grant-ProtectedPathAccess -Path $Source }
                }
                $result.TookOwnership = [bool]($sourceSddl -or $sourceParentSddl)
            }

            Write-Host "  Taking ownership of $parent, retrying, and putting its ACL back either way." -ForegroundColor DarkGray
            $parentSddl = Grant-ProtectedPathAccess -Path $parent
            if (-not $parentSddl) {
                $result.Reason = "The folder's security descriptor could not be read, so its ownership was left alone. Original error: $firstError"
                return $result
            }
            $result.TookOwnership = $true

            # Re-checked now that the folder can actually be read: the first check ran
            # against a folder that may have been denying us, so its answer is unreliable.
            if (Test-Path -LiteralPath $Destination) {
                $fileSddl = Grant-ProtectedPathAccess -Path $Destination
                Clear-ProtectedFileAttribute -Path $Destination
            }

            Copy-Item -LiteralPath $Source -Destination $Destination -Force -ErrorAction Stop
            $result.Copied = $true
            $result.Reason = 'Copied after taking ownership of the destination and its parent folder.'
        }
        catch {
            $result.Reason = "The copy was still refused after taking ownership of the destination and its parent folder: $($_.Exception.Message)"
        }
        finally {
            # The destination's own descriptor is replayed onto whatever now sits at that
            # path, so a freshly written file ends up owned by TrustedInstaller exactly as
            # the one it replaced was. The file goes back first, while the parent rights
            # that make it reachable are still in place.
            if ($fileSddl) { Restore-ProtectedPathAccess -Path $Destination -Sddl $fileSddl }
            if ($parentSddl) { Restore-ProtectedPathAccess -Path $parent -Sddl $parentSddl }
            # The source was only borrowed to read it, so it is handed back untouched.
            if ($sourceSddl) { Restore-ProtectedPathAccess -Path $Source -Sddl $sourceSddl }
            if ($sourceParentSddl) { Restore-ProtectedPathAccess -Path (Split-Path -Path $Source -Parent) -Sddl $sourceParentSddl }
            $result.Restored = [bool]($fileSddl -or $parentSddl -or $sourceSddl -or $sourceParentSddl)
        }

        return $result
    }

    function Rename-ProtectedSystemFile {
        # Renames a file in a protected folder, taking the folder and the file only when
        # the plain rename is refused.
        #
        # A rename needs rights on both and neither alone is enough: the parent supplies
        # FILE_ADD_FILE for the new name, the file supplies the DELETE that Rename-Item
        # asks for when it opens the source. Granting on the parent with inheritance would
        # cover the file too, but would also rewrite every other child's descriptor.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [Parameter(Mandatory = $true)][string]$NewName
        )

        $parent = Split-Path -Path $Path -Parent
        $target = Join-Path $parent $NewName
        $result = [PSCustomObject]@{
            Renamed       = $false
            TookOwnership = $false
            NewPath       = ''
            Reason        = ''
        }

        try {
            if (-not (Test-Path -LiteralPath $Path -ErrorAction Stop)) {
                $result.Reason = 'The file was not present.'
                return $result
            }
        }
        catch {
            Write-Verbose "Whether $Path exists could not be checked ($($_.Exception.Message)). Treating that as protection rather than absence."
        }

        # See Copy-ProtectedSystemFile: the privileges alone usually carry the rename,
        # which leaves every descriptor on the disk exactly as the guest wrote it.
        Enable-ServicingRepairPrivilege

        try {
            Rename-Item -LiteralPath $Path -NewName $NewName -Force -ErrorAction Stop
            $result.Renamed = $true
            $result.NewPath = $target
            $result.Reason = 'Renamed without changing any permission.'
            return $result
        }
        catch {
            $firstError = $_.Exception.Message
        }

        Write-Host "  $Path could not be renamed ($firstError)." -ForegroundColor DarkGray
        Write-Host "  Taking ownership of $parent, retrying, and putting its ACL back either way." -ForegroundColor DarkGray

        $parentSddl = $null
        $fileSddl = $null
        try {
            $parentSddl = Grant-ProtectedPathAccess -Path $parent
            if (-not $parentSddl) {
                $result.Reason = "The folder's security descriptor could not be read, so its ownership was left alone. Original error: $firstError"
                return $result
            }

            if (-not (Test-Path -LiteralPath $Path)) {
                $result.Reason = 'The file was not present once the folder could be read.'
                return $result
            }

            $fileSddl = Grant-ProtectedPathAccess -Path $Path
            Clear-ProtectedFileAttribute -Path $Path
            $result.TookOwnership = $true
            Rename-Item -LiteralPath $Path -NewName $NewName -Force -ErrorAction Stop
            $result.Renamed = $true
            $result.NewPath = $target
            $result.Reason = 'Renamed after taking ownership of the file and its parent folder.'
        }
        catch {
            $result.Reason = "The rename was still refused after taking ownership of the file and its parent folder: $($_.Exception.Message)"
        }
        finally {
            # The file goes back first, under whichever name it ended up with, while the
            # parent rights that make it reachable are still in place.
            if ($fileSddl) {
                Restore-ProtectedPathAccess -Path $(if ($result.Renamed) { $target } else { $Path }) -Sddl $fileSddl
            }
            if ($parentSddl) { Restore-ProtectedPathAccess -Path $parent -Sddl $parentSddl }
        }

        return $result
    }

    function Install-ProtectedSystemFile {
        # The single way this script puts a file onto the offline guest disk.
        #
        # Every replacement has to survive the same five problems, so they are solved
        # once here rather than separately at each call site:
        #
        #   1. The destination is owned by NT SERVICE\TrustedInstaller, so a plain
        #      Copy-Item is refused and the repair "succeeds" having changed nothing.
        #   2. The spare copy is very often a hard link to the file being replaced.
        #      Windows keeps one instance of an inbox file and links it into place, so
        #      copying the store copy over the live file both changes nothing and fails,
        #      because Copy-Item opens the one file for reading and writing at once.
        #   3. Copy-Item creates a *new* file that inherits the folder's ACEs. Unless the
        #      original descriptor is put back, the repaired file is the only one in
        #      System32 carrying permissions Windows never wrote.
        #   4. A copy that lands but is wrong is worse than one that fails, so the
        #      content is hashed and the caller's own checks are run before it is kept.
        #   5. Anything that goes wrong has to leave the disk as it was found.
        #
        # takeown.exe and icacls.exe are deliberately not used. icacls /grant leaves its
        # ACE behind, takeown sets an owner that is not the one Windows shipped, and
        # neither can put a descriptor back the way it was.
        param(
            [Parameter(Mandatory = $true)][string]$Source,
            [Parameter(Mandatory = $true)][string]$Destination,
            [string]$BackupSuffix = '.replaced.bak',
            [switch]$NoBackup,
            # Run against the newly written file before it is accepted. Throwing from
            # here rolls the replacement back, which is how a caller rejects a copy that
            # arrived intact but is the wrong binary.
            [scriptblock]$PostCopyValidation,
            [string]$Description = 'system file'
        )

        $result = [PSCustomObject]@{
            Installed  = $false
            BackupPath = $null
            AclSource  = ''
            RolledBack = $false
            Hash       = ''
            Reason     = ''
        }

        if (-not (Test-Path -LiteralPath $Source -PathType Leaf)) {
            $result.Reason = "The source file $Source was not present."
            return $result
        }

        $destinationItem = Get-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
        $destinationExists = $null -ne $destinationItem
        $destinationIsDirectory = $destinationExists -and $destinationItem.PSIsContainer

        # The EFI System Partition is FAT32, which has no security descriptors and no
        # hard links at all. Asking for either there fails, and on FAT the file index
        # is not a reliable identity, so two unrelated files can look like one. Both
        # steps are therefore skipped rather than guessed at.
        $supportsSecurity = $true
        try {
            $driveFormat = ([System.IO.DriveInfo]::new([System.IO.Path]::GetPathRoot($Destination))).DriveFormat
            $supportsSecurity = $driveFormat -in @('NTFS', 'ReFS')
            if (-not $supportsSecurity) {
                Write-Verbose "$Destination is on a $driveFormat volume, which stores no ACLs. Ownership and descriptor handling are skipped."
            }
        }
        catch {
            Write-Verbose "The destination's file system could not be determined: $($_.Exception.Message)"
        }

        # -- Refuse to replace a file with itself -----------------------------
        if ($supportsSecurity -and $destinationExists -and -not $destinationIsDirectory) {
            $sourceIdentity = Get-FileIdentity -Path $Source
            $destinationIdentity = Get-FileIdentity -Path $Destination
            if ($sourceIdentity -and $destinationIdentity -and $sourceIdentity.Id -eq $destinationIdentity.Id) {
                $result.Reason = "The source and the destination are two hard links to one file (file ID $($destinationIdentity.Id), $($destinationIdentity.LinkCount) link(s)). Copying it over itself would change nothing while reporting success."
                return $result
            }
        }

        # -- Capture the descriptor before anything moves ---------------------
        # Only a descriptor that still looks like one Windows wrote is worth replaying.
        # When a file was *replaced* rather than damaged - by a bad update, a driver
        # installer or malware - the ACL sitting on it is the attacker's, not the
        # guest's, and putting it back on the repaired file would preserve exactly the
        # thing being repaired. In that case the standard baseline is the safer answer.
        $originalSddl = $null
        if ($supportsSecurity -and $destinationExists -and -not $destinationIsDirectory) {
            try {
                $candidateSddl = (Get-Acl -LiteralPath $Destination).GetSecurityDescriptorSddlForm('Owner,Group,Access')
                $ownerSid = ([System.Security.AccessControl.RawSecurityDescriptor]::new($candidateSddl)).Owner
                $systemOwners = @(
                    'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464', # NT SERVICE\TrustedInstaller
                    'S-1-5-18', # NT AUTHORITY\SYSTEM
                    'S-1-5-32-544'                                                     # BUILTIN\Administrators
                )
                if ($ownerSid -and $systemOwners -contains $ownerSid.Value) {
                    $originalSddl = $candidateSddl
                }
                else {
                    Write-Warning "  The existing file is owned by $($ownerSid.Value), which is not an owner Windows gives its system files. Its ACL will not be carried over to the replacement; the standard system-file baseline is applied instead."
                }
            }
            catch {
                Write-Verbose "The destination's security descriptor could not be read: $($_.Exception.Message)"
            }
        }

        # -- Back up whatever is there now ------------------------------------
        $backupCreated = $false
        $backupPath = $null
        if ($destinationExists -and -not $NoBackup) {
            $backupPath = New-UniqueBackupPath -BasePath $Destination -BakSuffix $BackupSuffix
            try {
                $renameResult = Invoke-LoggedValue -Description "Back up $Description" -Details @{
                    Path        = $Destination
                    Destination = $backupPath
                } -ScriptBlock {
                    Rename-ProtectedSystemFile -Path $Destination -NewName (Split-Path $backupPath -Leaf)
                } | Select-Object -Last 1
                if (-not $renameResult -or -not $renameResult.Renamed) {
                    throw $(if ($renameResult) { $renameResult.Reason } else { 'The rename helper returned no result.' })
                }
                if (-not (Test-Path -LiteralPath $backupPath)) { throw 'The backup path was not created.' }
                Write-Host "  [OK] $($renameResult.Reason)" -ForegroundColor DarkGray
                $backupCreated = $true
                $result.BackupPath = $backupPath
            }
            catch {
                $result.Reason = "The existing path could not be backed up, so the replacement was cancelled rather than run without a way back: $($_.Exception.Message)"
                return $result
            }
        }

        $parent = Split-Path -Path $Destination -Parent
        if ($parent -and -not (Test-Path -LiteralPath $parent)) {
            New-Item-Logged -Path $parent -ItemType Directory -Force | Out-Null
        }

        try {
            $sourceHash = (Get-FileHash -LiteralPath $Source -Algorithm SHA256 -ErrorAction Stop).Hash

            $copyResult = Invoke-LoggedValue -Description "Replace $Description" -Details @{
                Source      = $Source
                Destination = $Destination
            } -ScriptBlock {
                Copy-ProtectedSystemFile -Source $Source -Destination $Destination
            } | Select-Object -Last 1
            if (-not $copyResult -or -not $copyResult.Copied) {
                throw $(if ($copyResult) { $copyResult.Reason } else { 'The copy helper returned no result.' })
            }
            Write-Host "  [OK] $($copyResult.Reason)" -ForegroundColor DarkGray

            if (-not (Test-Path -LiteralPath $Destination -PathType Leaf)) {
                throw "The copy did not create a file at $Destination."
            }

            $destinationHash = (Get-FileHash -LiteralPath $Destination -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($sourceHash -ne $destinationHash) {
                throw 'SHA-256 verification failed after copying the replacement.'
            }
            $result.Hash = $destinationHash

            if ($PostCopyValidation) {
                & $PostCopyValidation $Destination
            }

            # -- Give the file its permissions back ----------------------------
            if (-not $supportsSecurity) {
                $result.AclSource = 'not applicable (volume stores no ACLs)'
            }
            else {
                Enable-ServicingRepairPrivilege

                if ($originalSddl) {
                    # Preferred: hand the file back the descriptor it actually had. A
                    # generic baseline is a guess, and a guess that is right for a driver
                    # is wrong for files that ship with extra capability SIDs.
                    try {
                        $originalSd = [System.Security.AccessControl.FileSecurity]::new()
                        $originalSd.SetSecurityDescriptorSddlForm($originalSddl, 'Owner,Group,Access')
                        Invoke-Logged -Description "Restore original ACL on $Description" -Details @{
                            Path = $Destination
                            Sddl = $originalSddl
                        } -ScriptBlock {
                            [System.IO.File]::SetAccessControl($Destination, $originalSd)
                        } | Out-Null
                        $result.AclSource = 'original descriptor'
                        Write-Host "  [OK] Restored the file's original owner, group and ACL." -ForegroundColor Green
                    }
                    catch {
                        Write-Warning "  The original descriptor could not be replayed ($($_.Exception.Message)). Falling back to the standard system-file baseline."
                    }
                }

                if (-not $result.AclSource) {
                    try {
                        # Set-Acl is deliberately not used: it refuses a protected (D:P)
                        # DACL unless the caller holds SeSecurityPrivilege, even though
                        # nothing about this write touches auditing.
                        $protectedAcl = New-ProtectedSystemFileAcl
                        Invoke-Logged -Description "Apply protected system-file ACL to $Description" -Details @{
                            Path  = $Destination
                            Owner = 'NT SERVICE\TrustedInstaller'
                        } -ScriptBlock {
                            [System.IO.File]::SetAccessControl($Destination, $protectedAcl)
                        } | Out-Null
                        $result.AclSource = 'protected system-file baseline'
                        Write-Host "  [OK] Applied protected Windows system-file ACL/owner baseline." -ForegroundColor Green
                    }
                    catch {
                        Write-Warning "  Replaced the file's content, but could not apply an owner/ACL: $($_.Exception.Message)"
                        Write-Warning "  After recovery, verify permissions with: icacls `"$Destination`""
                    }
                }
            }

            $result.Installed = $true
            $result.Reason = "Replaced $Destination."
            return $result
        }
        catch {
            $result.Reason = $_.Exception.Message
            Write-Error "  Failed to replace or verify $Description : $($result.Reason)"

            if ($backupCreated) {
                try {
                    if (Test-Path -LiteralPath $Destination) {
                        Enable-ServicingRepairPrivilege
                        $failedSddl = Grant-ProtectedPathAccess -Path $Destination
                        if ($failedSddl) { Clear-ProtectedFileAttribute -Path $Destination }
                        Remove-Item -LiteralPath $Destination -Recurse -Force -ErrorAction Stop
                    }
                    $rollback = Invoke-LoggedValue -Description "Roll back failed replacement of $Description" -Details @{
                        Backup      = $backupPath
                        Destination = $Destination
                    } -ScriptBlock {
                        Rename-ProtectedSystemFile -Path $backupPath -NewName (Split-Path $Destination -Leaf)
                    } | Select-Object -Last 1
                    if (-not $rollback -or -not $rollback.Renamed) {
                        throw $(if ($rollback) { $rollback.Reason } else { 'The rename helper returned no result.' })
                    }
                    $result.RolledBack = $true
                    $result.BackupPath = $null
                    Write-Warning "  Restored the original file from $backupPath."
                }
                catch {
                    Write-Warning "  Automatic rollback failed: $($_.Exception.Message)"
                    Write-Warning "  The original file is still available at $backupPath - restore it by hand."
                }
            }
            elseif (-not $destinationExists -and (Test-Path -LiteralPath $Destination)) {
                Remove-Item-Logged -Path $Destination -Force
            }

            return $result
        }
    }

    function ConvertTo-HklmSubKeyPath {
        # 'HKLM:\BROKENSOFTWARE\...' or a provider PSPath to the native subkey string the
        # Microsoft.Win32.Registry APIs expect.
        param([Parameter(Mandatory = $true)][string]$Path)

        if ($Path -match 'HKEY_LOCAL_MACHINE\\(.+)$') { return $Matches[1] }
        if ($Path -match '^HKLM:\\(.+)$') { return $Matches[1] }
        return $null
    }

    function Get-BackupPrivilegeRegistrySddl {
        # Reads Owner, Group and DACL of a key the caller has no granted access to.
        #
        # A key whose DACL grants nothing to Administrators denies READ_CONTROL as well
        # as write, so its descriptor cannot be read the ordinary way - and without the
        # original descriptor there is nothing to restore afterwards, which is why the
        # write path used to abort on such a key rather than escalate.
        #
        # SeBackupPrivilege lifts exactly that restriction, but only through
        # RegOpenKeyEx with REG_OPTION_BACKUP_RESTORE. The .NET RegistryKey APIs never
        # pass that flag, so this has to go to the Win32 entry points directly.
        param([Parameter(Mandatory = $true)][string]$SubKey)

        if (-not ('RepairAzVmDiskBackupRegistry' -as [type])) {
            Add-Type -ErrorAction Stop -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class RepairAzVmDiskBackupRegistry
{
    [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern int RegOpenKeyExW(IntPtr hKey, string subKey, int options, int sam, out IntPtr result);

    [DllImport("advapi32.dll", SetLastError = true)]
    private static extern int RegGetKeySecurity(IntPtr hKey, int securityInformation, byte[] descriptor, ref int length);

    [DllImport("advapi32.dll", SetLastError = true)]
    private static extern int RegCloseKey(IntPtr hKey);

    private static readonly IntPtr HKEY_LOCAL_MACHINE = new IntPtr(unchecked((int)0x80000002));
    private const int REG_OPTION_BACKUP_RESTORE = 0x00000004;
    private const int READ_CONTROL = 0x00020000;
    private const int OWNER_GROUP_DACL = 0x00000001 | 0x00000002 | 0x00000004;
    private const int ERROR_INSUFFICIENT_BUFFER = 122;

    public static byte[] GetSecurityDescriptor(string subKey)
    {
        IntPtr handle;
        if (RegOpenKeyExW(HKEY_LOCAL_MACHINE, subKey, REG_OPTION_BACKUP_RESTORE, READ_CONTROL, out handle) != 0)
        {
            return null;
        }

        try
        {
            int length = 0;
            int rc = RegGetKeySecurity(handle, OWNER_GROUP_DACL, null, ref length);
            if (rc != 0 && rc != ERROR_INSUFFICIENT_BUFFER)
            {
                return null;
            }

            byte[] buffer = new byte[length];
            if (RegGetKeySecurity(handle, OWNER_GROUP_DACL, buffer, ref length) != 0)
            {
                return null;
            }
            return buffer;
        }
        finally
        {
            RegCloseKey(handle);
        }
    }
}
'@
        }

        Enable-ServicingRepairPrivilege

        try {
            $raw = [RepairAzVmDiskBackupRegistry]::GetSecurityDescriptor($SubKey)
            if (-not $raw) { return $null }
            $security = [System.Security.AccessControl.RegistrySecurity]::new()
            $security.SetSecurityDescriptorBinaryForm($raw)
            return $security.GetSecurityDescriptorSddlForm('Owner,Group,Access')
        }
        catch {
            return $null
        }
    }

    function Get-ProtectedRegistryKeySddl {
        # Captures Owner, Group and DACL so the descriptor can be replayed verbatim.
        # The SACL is deliberately excluded: reading it needs SeSecurityPrivilege and
        # nothing here changes auditing.
        param([Parameter(Mandatory = $true)][string]$Path)

        $subKey = ConvertTo-HklmSubKeyPath -Path $Path
        if (-not $subKey) { return $null }

        $root = [Microsoft.Win32.Registry]::LocalMachine
        $key = $null
        try {
            $key = $root.OpenSubKey(
                $subKey,
                [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadSubTree,
                [System.Security.AccessControl.RegistryRights]::ReadPermissions)
            if ($key) {
                $sections = [System.Security.AccessControl.AccessControlSections]::Access -bor
                [System.Security.AccessControl.AccessControlSections]::Owner -bor
                [System.Security.AccessControl.AccessControlSections]::Group
                return $key.GetAccessControl($sections).GetSecurityDescriptorSddlForm('Owner,Group,Access')
            }
        }
        catch {
            # Falls through to the backup-privilege read below.
        }
        finally {
            if ($key) { $key.Close() }
        }

        return Get-BackupPrivilegeRegistrySddl -SubKey $subKey
    }

    function Restore-ProtectedRegistryKeyAccess {
        # Replays a descriptor captured by Get-ProtectedRegistryKeySddl. A null Sddl
        # means nothing was captured, so there is nothing to put back.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [string]$Sddl
        )

        if (-not $Sddl) { return }
        $subKey = ConvertTo-HklmSubKeyPath -Path $Path
        if (-not $subKey) { return }

        $root = [Microsoft.Win32.Registry]::LocalMachine
        $key = $null
        try {
            $rights = [System.Security.AccessControl.RegistryRights]::TakeOwnership -bor
            [System.Security.AccessControl.RegistryRights]::ChangePermissions -bor
            [System.Security.AccessControl.RegistryRights]::ReadPermissions
            $key = $root.OpenSubKey(
                $subKey,
                [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,
                $rights)
            if (-not $key) { return }
            $security = [System.Security.AccessControl.RegistrySecurity]::new()
            # Sections must be named. The default is All, which pulls in the SACL and so
            # demands SeSecurityPrivilege for a write that never touches auditing.
            $security.SetSecurityDescriptorSddlForm($Sddl, 'Owner,Group,Access')
            $key.SetAccessControl($security)
        }
        catch {
            Write-Warning "Could not restore the original security descriptor on $Path : $($_.Exception.Message)"
        }
        finally {
            if ($key) { $key.Close() }
            [System.GC]::Collect()
            [System.GC]::WaitForPendingFinalizers()
        }
    }

    function Grant-ProtectedRegistryKeyAccess {
        # Takes ownership of an offline-hive key and every key below it. Deleting a key
        # requires delete rights on that key and on all of its subkeys, so the whole
        # subtree is covered. The key named by -Path is granted before its children,
        # because they cannot be enumerated reliably until it is readable.
        #
        # -KeyOnly grants the named key alone. Use it for a parent such as 'Component
        # Based Servicing', where recursing would rewrite the ACL of every package key
        # in the hive - tens of thousands of them - for no benefit.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [switch]$KeyOnly
        )

        Enable-ServicingRepairPrivilege
        $me = ([System.Security.Principal.WindowsIdentity]::GetCurrent()).User

        $grantOne = {
            param([string]$KeyPath)

            $subKey = ConvertTo-HklmSubKeyPath -Path $KeyPath
            if (-not $subKey) { return }

            $root = [Microsoft.Win32.Registry]::LocalMachine
            $ownerKey = $null
            try {
                $ownerKey = $root.OpenSubKey(
                    $subKey,
                    [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,
                    [System.Security.AccessControl.RegistryRights]::TakeOwnership)
                if ($ownerKey) {
                    $ownerSecurity = [System.Security.AccessControl.RegistrySecurity]::new()
                    $ownerSecurity.SetOwner($me)
                    $ownerKey.SetAccessControl($ownerSecurity)
                }
            }
            finally {
                # Every handle must be closed or the hive will refuse to unload later.
                if ($ownerKey) { $ownerKey.Close() }
            }

            $accessKey = $null
            try {
                $rights = [System.Security.AccessControl.RegistryRights]::ReadPermissions -bor
                [System.Security.AccessControl.RegistryRights]::ChangePermissions
                $accessKey = $root.OpenSubKey(
                    $subKey,
                    [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,
                    $rights)
                if ($accessKey) {
                    $accessSecurity = $accessKey.GetAccessControl(
                        [System.Security.AccessControl.AccessControlSections]::Access)
                    $accessSecurity.AddAccessRule(
                        [System.Security.AccessControl.RegistryAccessRule]::new(
                            $me, 'FullControl', 'None', 'None', 'Allow'))
                    $accessKey.SetAccessControl($accessSecurity)
                }
            }
            finally {
                if ($accessKey) { $accessKey.Close() }
            }
        }

        & $grantOne $Path

        if (-not $KeyOnly) {
            $children = @(Get-ChildItem -LiteralPath $Path -Recurse -ErrorAction SilentlyContinue |
                ForEach-Object { $_.PSPath })
            foreach ($child in $children) { & $grantOne $child }
        }

        # The provider opens keys of its own while enumerating; releasing them keeps the
        # later reg unload from failing.
        [System.GC]::Collect()
        [System.GC]::WaitForPendingFinalizers()
    }

    function Test-RegistryAccessDenied {
        # An offline hive refuses a write in two different ways depending on which layer
        # rejects it: the provider surfaces UnauthorizedAccessException, while the
        # RegistryKey APIs raise SecurityException. Either one means "the ACL said no",
        # and only those two are worth retrying - a missing key or a bad value type must
        # keep failing loudly rather than being retried behind an ownership change.
        param([Parameter(Mandatory = $true)]$ErrorRecord)

        $ex = $ErrorRecord.Exception
        while ($ex) {
            if ($ex -is [System.UnauthorizedAccessException] -or $ex -is [System.Security.SecurityException]) { return $true }
            $ex = $ex.InnerException
        }
        return $false
    }

    function Get-NearestExistingRegistryKey {
        # Creating a value needs rights on its key; creating a key needs rights on the
        # nearest ancestor that actually exists, because that is the key whose ACL is
        # consulted when the first missing level is created.
        param([Parameter(Mandatory = $true)][string]$Path)

        $current = $Path
        while ($current) {
            if (Test-Path -LiteralPath $current) { return $current }
            $parent = Split-Path -Parent $current
            if ($parent -eq $current) { break }
            $current = $parent
        }
        return $null
    }

    function Get-ProtectedRegistryValue {
        # The read counterpart of Invoke-ProtectedRegistryWrite. A key locked to
        # SYSTEM:Read denies Administrators even READ_CONTROL, so reporting the current
        # value of a guarded key needs the same ownership dance the write does.
        #
        # -DefaultValue is returned when the value genuinely does not exist, which is a
        # different outcome from "exists but could not be read" and must not be confused
        # with it: mislabelling a locked value as absent is how a repair ends up logging
        # 'was: (not set)' about a value it never managed to see.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [Parameter(Mandatory = $true)][string]$Name,
            $DefaultValue = $null,
            [ref]$Found,
            [ref]$Denied
        )

        if ($Found) { $Found.Value = $false }
        if ($Denied) { $Denied.Value = $false }

        $read = {
            $props = Get-ItemProperty -Path $Path -Name $Name -ErrorAction Stop
            if ($props -and ($props.PSObject.Properties.Name -contains $Name)) {
                if ($Found) { $Found.Value = $true }
                return $props.$Name
            }
            return $DefaultValue
        }

        try { return & $read }
        catch {
            if (-not (Test-RegistryAccessDenied -ErrorRecord $_)) { return $DefaultValue }
        }

        if ($Denied) { $Denied.Value = $true }

        $guardPath = Get-NearestExistingRegistryKey -Path $Path
        if (-not $guardPath) { return $DefaultValue }
        $originalSddl = Get-ProtectedRegistryKeySddl -Path $guardPath
        if (-not $originalSddl) { return $DefaultValue }

        try { Grant-ProtectedRegistryKeyAccess -Path $guardPath -KeyOnly }
        catch {
            Restore-ProtectedRegistryKeyAccess -Path $guardPath -Sddl $originalSddl
            return $DefaultValue
        }

        try { return & $read }
        catch { return $DefaultValue }
        finally { Restore-ProtectedRegistryKeyAccess -Path $guardPath -Sddl $originalSddl }
    }

    function Invoke-ProtectedRegistryWrite {
        # The registry counterpart of Install-ProtectedSystemFile, and it exists for the
        # same reason: keys in an offline hive can be owned by TrustedInstaller and deny
        # write to Administrators, so a repair reports success having changed nothing.
        #
        # The plain write is attempted first and the ACL is only touched when the write
        # is actually refused. That matters here far more than it does for files: this
        # runs behind every registry write in the script, and unconditionally rewriting
        # a descriptor per value would be both slow and a change the guest never asked
        # for. The overwhelming majority of writes take the fast path and cost nothing.
        #
        # Only the guarded key itself is granted, never its subtree. A value write needs
        # KEY_SET_VALUE on one key; recursing would rewrite the ACL of every key beneath
        # it - which under a hive root is tens of thousands of keys - for no benefit.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [Parameter(Mandatory = $true)][scriptblock]$Action,
            [string]$Description = 'registry write'
        )

        try {
            & $Action
            return
        }
        catch {
            $firstError = $_
            if (-not (Test-RegistryAccessDenied -ErrorRecord $firstError)) { throw }
        }

        $guardPath = Get-NearestExistingRegistryKey -Path $Path
        if (-not $guardPath) { throw $firstError }

        # Captured before anything changes so the descriptor can be replayed verbatim.
        # A null means the path is not in HKLM and these APIs cannot address it, in
        # which case the original access-denied error is the honest outcome.
        $originalSddl = Get-ProtectedRegistryKeySddl -Path $guardPath
        if (-not $originalSddl) { throw $firstError }

        Write-Host "  $guardPath is protected by its own ACL; taking ownership to $Description." -ForegroundColor DarkGray

        try {
            Grant-ProtectedRegistryKeyAccess -Path $guardPath -KeyOnly
        }
        catch {
            Write-Warning "Could not take ownership of $guardPath : $($_.Exception.Message)"
            Restore-ProtectedRegistryKeyAccess -Path $guardPath -Sddl $originalSddl
            throw $firstError
        }

        try {
            & $Action
            Write-Host "  [OK] Completed after taking ownership; original owner, group and ACL restored." -ForegroundColor Green
        }
        finally {
            # Runs even when the retry fails, so a failed repair never leaves the key
            # owned by the repairing account.
            Restore-ProtectedRegistryKeyAccess -Path $guardPath -Sddl $originalSddl
        }
    }

    function Remove-ProtectedRegistryKey {
        # Remove-Item-Logged runs with -ErrorAction SilentlyContinue, so an access-denied
        # delete is silent. The CBS pending keys are owned by TrustedInstaller and deny
        # delete to Administrators on a real machine, so the plain attempt is verified
        # and ownership is taken only when it is actually needed.
        #
        # Owning the key itself is NOT sufficient. Deleting a subkey opens the PARENT for
        # write, so a parent such as 'Component Based Servicing' that grants SYSTEM only
        # KEY_READ refuses the delete with a SecurityException before the child's ACL is
        # ever consulted. Whether that bites depends on the parent's ACL, which varies by
        # OS build and servicing history, so the parent is always granted on the retry.
        #
        # The parent survives the repair, unlike the child, so its original descriptor is
        # captured first and replayed in a finally. Leaving CBS owned by the repairing
        # account would be the same class of regression as the old TxR rename.
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [string]$Label = ''
        )

        if (-not $Label) { $Label = $Path }
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        Remove-Item-Logged -Path $Path -Recurse -Force
        if (-not (Test-Path -LiteralPath $Path)) { return $true }

        Write-Host "  $Label is protected by its own ACL; taking ownership and retrying." -ForegroundColor DarkGray
        $parentPath = Split-Path -Parent $Path
        $parentSddl = $null
        try {
            if ($parentPath) {
                $parentSddl = Get-ProtectedRegistryKeySddl -Path $parentPath
                Grant-ProtectedRegistryKeyAccess -Path $parentPath -KeyOnly
            }
            Grant-ProtectedRegistryKeyAccess -Path $Path
        }
        catch {
            Write-Warning "Could not take ownership of $Label : $($_.Exception.Message)"
            if ($parentPath) { Restore-ProtectedRegistryKeyAccess -Path $parentPath -Sddl $parentSddl }
            return $false
        }

        try {
            Remove-Item-Logged -Path $Path -Recurse -Force
        }
        finally {
            if ($parentPath) { Restore-ProtectedRegistryKeyAccess -Path $parentPath -Sddl $parentSddl }
        }

        if (Test-Path -LiteralPath $Path) {
            Write-Warning "$Label could not be deleted even after taking ownership of it and its parent."
            return $false
        }

        Write-Host "  $Label removed after taking ownership." -ForegroundColor Green
        return $true
    }

    function Clear-ServicingTransactionLogs {
        # Deletes CLFS/KTM transaction logs in place, after backing them up, and proves
        # afterwards that nothing else in the folder changed. Callers own their own
        # confirmation prompt; this function does not prompt.
        param(
            [ValidateSet('TxR', 'Config', 'SMI')][string[]]$Scope = @('TxR', 'Config', 'SMI'),
            [string]$BackupRoot = ''
        )

        if (-not $BackupRoot) {
            $stamp = (Get-Date).ToString('yyyyMMdd-HHmmss')
            $BackupRoot = Join-Path $script:WinDriveLetter "Windows\Temp\RepairAzVMDisk\TransactionLogs_$stamp"
        }

        Write-Host "Inspecting servicing transaction logs..." -ForegroundColor Yellow
        $plan = Get-TransactionLogCleanupPlan -Scope $Scope
        Show-TransactionLogCleanupPlan -Plan $plan

        # Pre-flight baseline: record which hives load BEFORE anything is written.
        #
        # This is deliberately advisory and never aborts the run. Test-RegistryHiveFile
        # validates a copy of the hive through RegLoadAppKey, and application-hive loading
        # rejects hives that Windows itself mounts without complaint. Measured on healthy,
        # bootable Server 2012 R2 and Server 2016 disks, it reports SYSTEM, SAM, SECURITY
        # and DEFAULT as "corrupt" (error 1009) while `reg load` succeeds on the very same
        # files and the guests boot normally. Treating that as a stop condition would
        # refuse to run on precisely the machines this repair exists for.
        #
        # The baseline is still worth taking because the result is deterministic per file.
        # What carries meaning is the transition: a hive that loaded before and fails
        # afterwards is a real regression, and the post-repair verification treats it as a
        # hard failure. A hive that already failed is not a reason to stop, because this
        # repair removes only .blf / .regtrans-ms files and touches neither the hives nor
        # their .LOG1 / .LOG2 recovery logs.
        $brokenHives = [System.Collections.Generic.List[string]]::new()
        foreach ($scopePlan in $plan) {
            foreach ($hive in $scopePlan.Hives) {
                if ($hive.Tested -and $hive.IsValid -ne $true) {
                    $brokenHives.Add("$($hive.Name)") | Out-Null
                }
            }
        }
        if ($brokenHives.Count -gt 0) {
            $unique = @($brokenHives | Select-Object -Unique)
            Write-Host "  Baseline: $($unique -join ', ') did not load as application hives." -ForegroundColor DarkGray
            Write-Host "  This is recorded for the before/after comparison only and does not block the repair;" -ForegroundColor DarkGray
            Write-Host "  no hive or .LOG1/.LOG2 recovery log is modified. Use -CheckRegistryHealth for a" -ForegroundColor DarkGray
            Write-Host "  genuine registry health assessment." -ForegroundColor DarkGray
        }

        $actionable = @($plan | Where-Object { $_.Snapshot.Present -and $_.Snapshot.Accessible -and $_.Snapshot.LogFiles.Count -gt 0 })
        $unreadable = @($plan | Where-Object { $_.Snapshot.Present -and -not $_.Snapshot.Accessible })
        foreach ($scopePlan in $unreadable) {
            Write-Warning "$($scopePlan.Label) could not be enumerated and was skipped: $($scopePlan.Snapshot.AccessError)"
        }

        if ($actionable.Count -eq 0) {
            Write-Host "No transaction log files to remove - no changes made." -ForegroundColor Green
            return @()
        }

        # Pre-flight gate 2: the backup must fit. The logs are small, but a full OS disk
        # is exactly the situation this repair is called into.
        $requiredBytes = [long](($actionable | Measure-Object -Property BackupBytes -Sum).Sum)
        try {
            $driveLetter = ([System.IO.Path]::GetPathRoot($BackupRoot)).Substring(0, 1)
            $freeBytes = (Get-PSDrive -Name $driveLetter -ErrorAction Stop).Free
            if ($null -ne $freeBytes -and $freeBytes -lt ($requiredBytes * 2)) {
                Write-Error "Not enough free space on ${driveLetter}: for the backup ($([math]::Round($requiredBytes / 1KB)) KB needed, $([math]::Round($freeBytes / 1MB)) MB free)."
                return @()
            }
        }
        catch { Write-Warning "Free space could not be confirmed for $BackupRoot; continuing." }

        $results = [System.Collections.Generic.List[object]]::new()
        foreach ($scopePlan in $actionable) {
            $backupPath = Join-Path $BackupRoot $scopePlan.Scope
            Write-Host "Clearing transaction logs from $($scopePlan.Label)..." -ForegroundColor Yellow
            # Out-Null is load-bearing. New-Item-Logged returns Invoke-Logged's captured
            # output string, which would otherwise join this function's output stream and
            # be mistaken for a scope result by the callers below.
            New-Item-Logged -Path $backupPath -ItemType Directory -Force | Out-Null

            # Every step below walks the planned file list, never a fresh enumeration,
            # so the set whose attributes are changed, that is backed up, and that is
            # deleted is provably identical.
            $files = $scopePlan.Snapshot.LogFiles
            $removed = 0
            $failures = [System.Collections.Generic.List[string]]::new()

            Invoke-Logged -Description 'Clear transaction log file attributes' -Details @{
                Path = $scopePlan.Path; Files = @($files | ForEach-Object { $_.Name })
            } -ScriptBlock {
                foreach ($file in $files) {
                    try { (Get-Item -LiteralPath $file.FullName -Force).Attributes = 'Normal' } catch { }
                }
            } | Out-Null

            Invoke-Logged -Description 'Back up transaction log files' -Details @{
                Scope = $scopePlan.Scope; Path = $scopePlan.Path; Backup = $backupPath
                Files = @($files | ForEach-Object { $_.Name })
            } -ScriptBlock {
                foreach ($file in $files) {
                    try {
                        Copy-Item -LiteralPath $file.FullName -Destination (Join-Path $backupPath $file.Name) -Force -ErrorAction Stop
                    }
                    catch {
                        # A List, so the additions survive the scriptblock's child scope.
                        $failures.Add("backup of $($file.Name) failed: $($_.Exception.Message)") | Out-Null
                    }
                }
            } | Out-Null

            if ($failures.Count -gt 0) {
                Write-Error "Backup incomplete for $($scopePlan.Label); nothing was deleted. $($failures -join '; ')"
                continue
            }

            Invoke-Logged -Description 'Remove transaction log files' -Details @{
                Path = $scopePlan.Path; Files = @($files | ForEach-Object { $_.Name })
            } -ScriptBlock {
                foreach ($file in $files) {
                    Remove-Item -LiteralPath $file.FullName -Force -ErrorAction SilentlyContinue
                }
            } | Out-Null
            $removed = @($files | Where-Object { -not [System.IO.File]::Exists($_.FullName) }).Count

            $verification = Test-TransactionLogCleanupResult -ScopePlan $scopePlan -BackupPath $backupPath
            $rolledBack = $false
            if (-not $verification.Passed) {
                $rolledBack = Restore-TransactionLogBackup -ScopePlan $scopePlan -BackupPath $backupPath
            }

            $results.Add([pscustomobject]@{
                    Scope        = $scopePlan.Scope
                    Label        = $scopePlan.Label
                    Path         = $scopePlan.Path
                    Present      = $true
                    FilesFound   = $files.Count
                    FilesRemoved = $removed
                    BackupPath   = $backupPath
                    Verification = $verification
                    RolledBack   = $rolledBack
                }) | Out-Null
        }

        $summary = $results.ToArray()
        Write-Host ""
        Write-Host "Verifying the guest was left in a good state..." -ForegroundColor Yellow
        Show-TransactionLogVerification -Result @($summary | ForEach-Object { $_.Verification })

        Write-ActionLog -Event 'ClearTransactionLogs' -Details @{
            BackupRoot = $BackupRoot
            Scopes     = @($summary | ForEach-Object {
                    @{
                        Scope        = $_.Scope
                        Path         = $_.Path
                        FilesFound   = $_.FilesFound
                        FilesRemoved = $_.FilesRemoved
                        BackupPath   = $_.BackupPath
                        Passed       = $_.Verification.Passed
                        RolledBack   = $_.RolledBack
                    }
                })
        }

        return $summary
    }

    function ClearTxRLogs {
        # KB 0x800719e4 (ERROR_LOG_FULL) step 2 as a repair in its own right: clear the
        # transaction logs and let the update retry, without reverting pending servicing.
        param([string[]]$Scope = @('TxR'))

        $resolved = if ($Scope -contains 'All') { @('TxR', 'Config', 'SMI') } else { @($Scope) }
        $labels = @()
        foreach ($scopeName in $resolved) { $labels += (Get-TransactionLogScopeInfo -Scope $scopeName).Label }

        if (-not (Confirm-CriticalOperation -Operation 'Clear servicing transaction logs (-FixTxRLogs)' -Details @"
Removes CLFS/KTM transaction log files (.blf and .regtrans-ms) from:
  $($labels -join "`n  ")
Each file is backed up to Windows\Temp\RepairAzVMDisk before it is deleted.
Registry hives and their .LOG1/.LOG2 recovery logs are NOT touched.
The folders keep their existing ACLs; nothing is renamed or recreated.

This does NOT revert pending updates, remove packages, rename pending.xml
or delete CBS registry keys. Use -FixPendingUpdates for that.
"@)) { return }

        # Only real scope results carry a Verification property. Anything else that reaches
        # the output stream would read as $null.Passed, i.e. as a failed scope, and abort a
        # repair that actually succeeded.
        $summary = @(Clear-ServicingTransactionLogs -Scope $resolved | Where-Object { $null -ne $_ -and $_.PSObject.Properties['Verification'] })
        if (-not $summary -or @($summary).Count -eq 0) { return }

        $failed = @($summary | Where-Object { -not $_.Verification.Passed })
        if ($failed.Count -gt 0) {
            Write-Error "Transaction log cleanup did not verify cleanly. Review the checks above; affected scopes were rolled back where a backup existed."
            return
        }

        $totalRemoved = ($summary | Measure-Object -Property FilesRemoved -Sum).Sum
        Write-Host ""
        Write-Host "COMPLETE: $totalRemoved transaction log file(s) removed and verified." -ForegroundColor Green
        Write-Host "Windows recreates these logs on the next boot; that is expected and self-healing." -ForegroundColor DarkCyan
        Write-Host "Boot the VM and retry the update." -ForegroundColor DarkCyan

        # Only mention the heavier repair when there is actually pending servicing left.
        $pendingMarkers = [System.Collections.Generic.List[string]]::new()
        if (Test-Path -LiteralPath (Join-Path $script:WinDriveLetter 'Windows\WinSxS\pending.xml')) {
            $pendingMarkers.Add('WinSxS\pending.xml') | Out-Null
        }
        Invoke-WithHive 'SOFTWARE' {
            $cbs = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
            foreach ($keyName in @('PackagesPending', 'RebootPending', 'SessionsPending')) {
                if (Test-Path (Join-Path $cbs $keyName)) { $pendingMarkers.Add("CBS\$keyName") | Out-Null }
            }
        }
        if ($pendingMarkers.Count -gt 0) {
            Write-Host ""
            Write-Host "Pending servicing markers are still present: $($pendingMarkers -join ', ')" -ForegroundColor Yellow
            Write-Host "  If the guest still loops in the update stage, run -AnalyzeServicingState, then -FixPendingUpdates." -ForegroundColor DarkCyan
        }
    }

    function ClearPendingUpdates {
        if (-not (Confirm-CriticalOperation -Operation 'Fix Pending Updates (-FixPendingUpdates)' -Details @"
Runs DISM /RevertPendingActions to undo in-progress servicing operations.
Removes pending update packages found by DISM /Get-Packages.
Removes TxR, config and SMI transaction log files (.blf/.regtrans-ms).
  Each file is backed up first and deleted in place; the folders keep their
  ACLs, and registry hives and their .LOG1/.LOG2 recovery logs are not touched.
Renames pending.xml in WinSxS.
Clears CBS registry keys (PackagesPending, RebootPending, SessionsPending).
Runs DISM /StartComponentCleanup only if no pending servicing markers remain.
"@)) { return }

        $OfflineWindowsPath = Join-Path $WinDriveLetter "Windows"
        if (-not (Test-Path "C:\temp")) { mkdir C:\temp | Out-Null }

        Write-Host "Saving pending Windows Update packages..." -ForegroundColor Yellow
        $dismText = & dism /Image:$WinDriveLetter /Get-Packages /format:list 2>$null | Out-String -Width 9999
        $blocks = $dismText -split "(\r\n){2,}"

        $packages = foreach ($b in $blocks) {
            $h = @{}
            foreach ($line in ($b -split "`r`n")) {
                if ($line -match '^\s*([^:]+)\s*:\s*(.+)\s*$') {
                    $h[$matches[1].Trim()] = $matches[2].Trim()
                }
            }
            if ($h.ContainsKey('Package Identity')) {
                [pscustomobject]$h
            }
        }

        $pendingUpdates = $packages | Where-Object { $_.State -eq 'Pending' } | Select-Object -ExpandProperty 'Package Identity'
        $pendingUpdates | Set-Content -Path C:\Temp\PendingUpdatePackages.txt

        Write-Host "Running DISM /Cleanup-Image /RevertPendingActions (undo in-progress servicing)" -ForegroundColor Yellow
        $revertResult = Invoke-DismWithWatchdog -Description 'DISM RevertPendingActions' -ImageDriveLetter $WinDriveLetter -Details @{
            Image = $WinDriveLetter
        } -ArgumentList @("/Image:$WinDriveLetter", '/Cleanup-Image', '/RevertPendingActions', '/ScratchDir:C:\Temp')
        $revertResult.Output | Out-Host

        $pendingUpdates | ForEach-Object {
            Write-Host "Running package uninstall: $($_)" -ForegroundColor Yellow
            $packageName = $_
            $removePackageResult = Invoke-DismWithWatchdog -Description 'DISM remove pending package' -ImageDriveLetter $WinDriveLetter -Details @{
                Image = $WinDriveLetter
                PackageName = $packageName
            } -ArgumentList @("/Image:$WinDriveLetter", '/Remove-Package', "/PackageName:$packageName")
            $removePackageResult.Output | Out-Host
        }

        # Shared with -FixTxRLogs. Same three folders, same file selection; the helper
        # backs each log file up, deletes it in place, and then verifies that the
        # registry hives, their .LOG1/.LOG2 recovery logs and the folder ACLs were left
        # alone. A scope that fails verification is rolled back from its backup.
        # See ClearTxRLogs: only objects carrying a Verification property are scope results.
        $logCleanup = @(Clear-ServicingTransactionLogs -Scope 'TxR', 'Config', 'SMI' | Where-Object { $null -ne $_ -and $_.PSObject.Properties['Verification'] })
        $logCleanupFailed = @($logCleanup | Where-Object { -not $_.Verification.Passed })
        if ($logCleanupFailed.Count -gt 0) {
            Write-Error "Transaction log cleanup failed verification for: $(($logCleanupFailed | ForEach-Object { $_.Label }) -join ', ')."
            Write-Host "Stopping before pending.xml and the CBS registry changes - the guest just failed a safety check." -ForegroundColor Yellow
            Write-Host "Review the checks above, then re-run once the underlying problem is understood." -ForegroundColor Yellow
            return
        }

        Write-Host "Renaming pending.xml..." -ForegroundColor Yellow
        $pendingXmlPath = Join-Path $WinDriveLetter "Windows\WinSxS\pending.xml"
        if (Test-Path $pendingXmlPath) {
            $winSxsPath = Join-Path $WinDriveLetter "Windows\WinSxS"
            $pendingOld = Join-Path $WinDriveLetter "Windows\WinSxS\pending.old"
            $winSxsSddl = $null
            $pendingSddl = $null
            try {
                # WinSxS and pending.xml are owned by TrustedInstaller and deny write to
                # Administrators, so this rename fails with access denied on a real
                # machine unless ownership is taken first. Renaming a file needs delete
                # rights on the file and add-file rights on the directory, so both are
                # taken. Both descriptors are put back in the finally block.
                $winSxsSddl = Grant-ProtectedPathAccess -Path $winSxsPath
                $pendingSddl = Grant-ProtectedPathAccess -Path $pendingXmlPath

                # Remove stale pending.old from a previous run
                if (Test-Path $pendingOld) {
                    [void](Grant-ProtectedPathAccess -Path $pendingOld)
                    Remove-Item-Logged -Path $pendingOld -Force
                }
                Rename-Item-Logged -Path $pendingXmlPath -NewName "pending.old"
            }
            finally {
                # Exactly one of these two paths exists, depending on whether the rename
                # succeeded, and the other call is a no-op.
                Restore-ProtectedPathAccess -Path $pendingOld -Sddl $pendingSddl
                Restore-ProtectedPathAccess -Path $pendingXmlPath -Sddl $pendingSddl
                Restore-ProtectedPathAccess -Path $winSxsPath -Sddl $winSxsSddl
            }

            if (Test-Path $pendingXmlPath) {
                Write-Warning "pending.xml is still present at $pendingXmlPath - the rename did not take effect."
            }
            else {
                Write-Host "  pending.xml renamed to pending.old." -ForegroundColor Green
            }
        }
        else {
            Write-Host "  pending.xml not present, skipping." -ForegroundColor DarkGray
        }

        Write-Host "Deleting registry keys..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE', 'COMPONENTS' {
            $ComponentsReg = "HKLM:\BROKENCOMPONENTS"
            $CbsSoftwareReg = "HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing"

            Write-Host "Deleting COMPONENTS registry keys..." -ForegroundColor Yellow
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "ExecutionState" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "PendingXmlIdentifier" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "NextQueueEntryIndex" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "NextQueueEntryIndexBCDB" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "AdvancedInstallersNeedResolving" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty-Logged -Path $ComponentsReg -Name "StoreDirty" -Force -ErrorAction SilentlyContinue

            Write-Host "Deleting SOFTWARE registry keys..." -ForegroundColor Yellow
            foreach ($cbsKeyName in @('PackagesPending', 'RebootPending', 'SessionsPending')) {
                [void](Remove-ProtectedRegistryKey -Path (Join-Path $CbsSoftwareReg $cbsKeyName) -Label "CBS\$cbsKeyName")
            }
        }

        $remainingPendingMarkers = [System.Collections.Generic.List[string]]::new()
        if (Test-Path $pendingXmlPath) { $remainingPendingMarkers.Add('WinSxS\pending.xml') | Out-Null }
        Invoke-WithHive 'SOFTWARE', 'COMPONENTS' {
            $ComponentsReg = "HKLM:\BROKENCOMPONENTS"
            $CbsSoftwareReg = "HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing"

            $componentProps = Get-ItemProperty $ComponentsReg -ErrorAction SilentlyContinue
            foreach ($propName in @('ExecutionState', 'PendingXmlIdentifier', 'NextQueueEntryIndex', 'NextQueueEntryIndexBCDB', 'AdvancedInstallersNeedResolving', 'StoreDirty')) {
                $propValue = if ($componentProps) { $componentProps.$propName } else { $null }
                if ($null -ne $propValue -and $propValue -ne 0 -and $propValue -ne '') {
                    $remainingPendingMarkers.Add("COMPONENTS\$propName=$propValue") | Out-Null
                }
            }

            foreach ($keyName in @('PackagesPending', 'RebootPending', 'SessionsPending')) {
                if (Test-Path (Join-Path $CbsSoftwareReg $keyName)) {
                    $remainingPendingMarkers.Add("CBS\$keyName") | Out-Null
                }
            }
        }

        if ($remainingPendingMarkers.Count -gt 0) {
            Write-Warning "Skipping DISM /StartComponentCleanup because pending servicing markers are still present: $($remainingPendingMarkers -join ', ')"
            Write-Host "  This is expected when DISM still reports pending operations. Boot once or rerun -FixPendingUpdates, then run -RepairComponentStore if component cleanup/repair is still needed." -ForegroundColor Yellow
        }
        else {
            Write-Host "Running DISM /Cleanup-Image /StartComponentCleanup (best-effort reclaim of superseded components)" -ForegroundColor Yellow
            $cleanupResult = Invoke-DismWithWatchdog -Description 'DISM StartComponentCleanup' -ImageDriveLetter $WinDriveLetter -Details @{
                Image = $WinDriveLetter
            } -ArgumentList @("/Image:$WinDriveLetter", '/Cleanup-Image', '/StartComponentCleanup', '/ScratchDir:C:\Temp')
            $cleanupResult.Output | Out-Host
            if ($cleanupResult.StallDetected -or $cleanupResult.TimedOut) {
                Write-Warning "DISM /StartComponentCleanup was stopped after $($cleanupResult.DurationMinutes) minute(s) without completing. The pending-update repair itself is already finished; component cleanup is best-effort and can be retried later with -RepairComponentStore."
                Write-Host "  DISM's own log for this attempt: $($cleanupResult.DismLogPath)" -ForegroundColor Yellow
            }
            elseif ($cleanupResult.ExitCode -ne 0) {
                Write-Warning "DISM /StartComponentCleanup exited with code $($cleanupResult.ExitCode). Pending-update cleanup steps already completed; component cleanup is best-effort and can be retried later."
            }
        }

        Write-Host "You may want to run SFC and Dism /RestoreHealth with script parameters: -RunSFC -RepairComponentStore." -ForegroundColor Green
    }

    function SetWinRMHTTPSEnabled {
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath

            Write-Host "Configuring setup and adding script..." -ForegroundColor Green
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\installwinrmhttps.cmd" -Type String -Force

            $installwinrmhttps = @"
@echo off
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -ExecutionPolicy Bypass -File C:\temp\configwinrmhttps.ps1
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\temp\configwinrmhttps.ps1 > NUL
del /F C:\temp\winrm_https.pfx > NUL
del /F C:\temp\installwinrmhttps.cmd > NUL
"@

            $scriptContent = @'
$pwd = ConvertTo-SecureString "REPLACE_WITH_PASSWORD" -AsPlainText -Force

# 1) Import machine certificate (LocalMachine\My) and capture thumbprint
$imported = Import-PfxCertificate -FilePath "C:\temp\winrm_https.pfx" -CertStoreLocation "Cert:\LocalMachine\My" -Password $pwd
$thumb = $imported.Thumbprint

# 2) Enable WinRM for remoting + CredSSP (server)
Enable-PSRemoting -Force
Enable-WSManCredSSP -Role Server -Force

# 3) Firewall rule for 5986 (HTTPS)
New-NetFirewallRule -DisplayName "Windows Remote Management (HTTPS-In)" -Direction Inbound -LocalPort 5986 -Protocol TCP -Action Allow -Program "System" | Out-Null

# 4) Create HTTPS listener (remove any existing HTTPS listener first)
Get-ChildItem -Path WSMan:\localhost\Listener | Where-Object { $_.Keys -match "Transport=HTTPS" } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
New-Item -Path WSMan:\localhost\Listener -Transport HTTPS -Address * -Hostname $env:COMPUTERNAME -CertificateThumbprint $thumb -Port 5986 -Force | Out-Null

# 5) Ensure WinRM service is Auto + started
Set-Service -Name WinRM -StartupType Automatic
Restart-Service -Name WinRM -Force
'@

            Ensure-GuestTempDir
            $guestName = if ($script:GuestComputerName) { $script:GuestComputerName } else { (Get-ItemProperty "$SystemRoot\Control\ComputerName\ComputerName").ComputerName }

            $cert = New-SelfSignedCertificate -DnsName $guestName -CertStoreLocation 'Cert:\LocalMachine\My' -KeyExportPolicy Exportable
            # Generate a cryptographically random one-time PFX transport password (never hardcoded).
            # Use the RandomNumberGenerator instance API (Create().GetBytes([byte[]])) rather than the
            # static GetBytes(int) overload, which only exists on .NET 6+ and is unavailable on the
            # Windows PowerShell 5.1 / .NET Framework 4.x host used to repair downlevel guests.
            $rngBytes = New-Object 'byte[]' 24
            $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
            try { $rng.GetBytes($rngBytes) } finally { $rng.Dispose() }
            $PfxPassword = [System.Convert]::ToBase64String($rngBytes) -replace '[^A-Za-z0-9]', 'x'
            $certpwd = ConvertTo-SecureString $PfxPassword -AsPlainText -Force

            $hostPfx = Join-Path $WinDriveLetter "Temp\winrm_https.pfx"
            Export-PfxCertificate -Cert $cert -FilePath $hostPfx -Password $certpwd | Out-Null
            #Clean up locally
            Remove-Item-Logged -Path "Cert:\LocalMachine\My\$($cert.Thumbprint)" -Force

            New-Item-Logged -Path "$WinDriveLetter\Temp" -Name "installwinrmhttps.cmd" -ItemType File -Value $installwinrmhttps.ToString().Trim() -Force
            New-Item-Logged -Path "$WinDriveLetter\Temp" -Name "configwinrmhttps.ps1" -ItemType File -Value $scriptContent.ToString().Trim().Replace("REPLACE_WITH_PASSWORD", $PfxPassword) -Force -RedactValue
        }

        Write-Host "Now start the VM and wait for the script to configure WinRM over HTTPS. (DO NO CONNECT WITH ENHANCED SESSION)." -ForegroundColor Yellow
        Write-Host "VM will restart after completing the WinRM configuration." -ForegroundColor Yellow

        if ($VMIPAddress) {
            Write-Host "Connect with: Enter-PSSession -ConnectionUri 'https://$($VMIPAddress):5986' -Credential (Get-Credential) -SessionOption (New-PSSessionOption -SkipCACheck -SkipCNCheck -SkipRevocationCheck)" -ForegroundColor Yellow
        }
        else {
            Write-Host "Connect with: Enter-PSSession -ConnectionUri 'https://<VMIP>:5986' -Credential (Get-Credential) -SessionOption (New-PSSessionOption -SkipCACheck -SkipCNCheck -SkipRevocationCheck)" -ForegroundColor Yellow
        }
    }

    ################################################################################
    # New repair functions
    ################################################################################

    ################################################################################
    # Boot sector (MBR / VBR) inspection and repair
    #
    # bcdboot repairs boot FILES (bootmgr, \Boot\BCD). It never writes disk sectors.
    # The two links before bootmgr - the MBR bootstrap in sector 0 of the disk and
    # the NTFS volume boot record (VBR) in sector 0 of the active partition - are
    # only repaired by bootsect.exe, which does not ship in-box with Windows Server
    # and is therefore usually absent on an Azure rescue VM. The helpers below give
    # the script native visibility into, and repair of, those two sectors.
    #
    # Typical symptoms that live in this layer (and that -FixBoot can never fix):
    #   "An operating system wasn't found" / "Operating system not found"
    #   "Missing operating system" / "Invalid partition table"
    #   "A disk read error occurred. Press Ctrl+Alt+Del to restart"
    #   "BOOTMGR is missing" when \bootmgr is demonstrably present on the volume
    ################################################################################

    function Get-SectorAsciiView {
        param([byte[]]$Bytes)
        $sb = New-Object System.Text.StringBuilder
        foreach ($b in $Bytes) {
            if ($b -ge 32 -and $b -lt 127) { [void]$sb.Append([char]$b) } else { [void]$sb.Append('.') }
        }
        return $sb.ToString()
    }

    function Read-RawDiskBytes {
        param(
            [Parameter(Mandatory = $true)][int]$DiskNumber,
            [Parameter(Mandatory = $true)][UInt64]$ByteOffset,
            [int]$Length = 512
        )
        $fs = $null
        try {
            $fs = New-Object System.IO.FileStream("\\.\PhysicalDrive$DiskNumber",
                [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $null = $fs.Seek([long]$ByteOffset, [System.IO.SeekOrigin]::Begin)
            $buf = New-Object byte[] $Length
            $read = 0
            while ($read -lt $Length) {
                $n = $fs.Read($buf, $read, $Length - $read)
                if ($n -le 0) { break }
                $read += $n
            }
            if ($read -lt $Length) { throw "Short read at offset $ByteOffset : got $read of $Length bytes." }
            return $buf
        }
        finally { if ($fs) { $fs.Dispose() } }
    }

    function Write-RawDiskBytes {
        param(
            [Parameter(Mandatory = $true)][int]$DiskNumber,
            [Parameter(Mandatory = $true)][UInt64]$ByteOffset,
            [Parameter(Mandatory = $true)][byte[]]$Data
        )
        if ($Data.Length % 512 -ne 0) { throw "Sector writes must be a multiple of 512 bytes (got $($Data.Length))." }
        $fs = $null
        try {
            $fs = New-Object System.IO.FileStream("\\.\PhysicalDrive$DiskNumber",
                [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::ReadWrite)
            $null = $fs.Seek([long]$ByteOffset, [System.IO.SeekOrigin]::Begin)
            $fs.Write($Data, 0, $Data.Length)
            $fs.Flush($true)
        }
        finally { if ($fs) { $fs.Dispose() } }
    }

    function ConvertFrom-MbrSector {
        param([Parameter(Mandatory = $true)][byte[]]$Sector)

        if ($Sector.Length -lt 512) { throw "MBR sector must be at least 512 bytes (got $($Sector.Length))." }

        $result = [ordered]@{
            HasSignature      = ($Sector[510] -eq 0x55 -and $Sector[511] -eq 0xAA)
            BootCodeNonZero   = 0
            IsWindowsBootCode = $false
            IsProtectiveMbr   = $false
            DiskSignature     = ''
            Markers           = @()
            Partitions        = @()
            ActiveCount       = 0
        }

        $bootCode = $Sector[0..439]
        $result.BootCodeNonZero = @($bootCode | Where-Object { $_ -ne 0 }).Count

        # Strings carried by the standard Windows (NT/Vista/7/10/2016+) MBR bootstrap.
        $text = Get-SectorAsciiView -Bytes $bootCode
        foreach ($k in @('Invalid partition table', 'Error loading operating system', 'Missing operating system')) {
            if ($text.Contains($k)) { $result.Markers += $k }
        }
        $result.IsWindowsBootCode = ($result.Markers.Count -ge 2)

        $result.DiskSignature = '{0:X2}{1:X2}{2:X2}{3:X2}' -f $Sector[443], $Sector[442], $Sector[441], $Sector[440]

        for ($i = 0; $i -lt 4; $i++) {
            $off = 446 + ($i * 16)
            $type = $Sector[$off + 4]
            if ($type -eq 0 -and $Sector[$off] -eq 0) { continue }
            $isActive = ($Sector[$off] -eq 0x80)
            if ($isActive) { $result.ActiveCount++ }
            if ($type -eq 0xEE) { $result.IsProtectiveMbr = $true }
            $numSect = [BitConverter]::ToUInt32($Sector, $off + 12)
            $result.Partitions += [pscustomobject]@{
                Index       = $i + 1
                IsActive    = $isActive
                TypeByte    = ('0x{0:X2}' -f $type)
                StartLBA    = [BitConverter]::ToUInt32($Sector, $off + 8)
                SectorCount = $numSect
                SizeGB      = [math]::Round(($numSect * 512) / 1GB, 2)
            }
        }

        return [pscustomobject]$result
    }

    function ConvertFrom-NtfsVbr {
        param([Parameter(Mandatory = $true)][byte[]]$Bytes)

        if ($Bytes.Length -lt 512) { throw "VBR needs at least 512 bytes (got $($Bytes.Length))." }

        $oem = [Text.Encoding]::ASCII.GetString($Bytes, 3, 8)
        $result = [ordered]@{
            HasSignature      = ($Bytes[510] -eq 0x55 -and $Bytes[511] -eq 0xAA)
            OemId             = $oem
            IsNtfs            = ($oem -eq 'NTFS    ')
            BytesPerSector    = [BitConverter]::ToUInt16($Bytes, 11)
            SectorsPerCluster = $Bytes[13]
            SectorsPerTrack   = [BitConverter]::ToUInt16($Bytes, 24)
            NumberOfHeads     = [BitConverter]::ToUInt16($Bytes, 26)
            HiddenSectors     = [BitConverter]::ToUInt32($Bytes, 28)
            TotalSectors      = [UInt64]0
            BootCodeNonZero   = 0
            Loader            = 'None'
            Markers           = @()
        }
        if ($result.IsNtfs) { $result.TotalSectors = [BitConverter]::ToUInt64($Bytes, 40) }

        # NTFS bootstrap code in sector 0 runs from 0x54 to 0x1FD.
        $result.BootCodeNonZero = @($Bytes[0x54..0x1FD] | Where-Object { $_ -ne 0 }).Count

        $text = Get-SectorAsciiView -Bytes $Bytes
        foreach ($k in @('BOOTMGR is missing', 'BOOTMGR is compressed', 'A disk read error occurred',
                'Press Ctrl+Alt+Del to restart', 'NTLDR is missing', 'NTLDR is compressed', 'BOOTMGR', 'NTLDR')) {
            if ($text.Contains($k)) { $result.Markers += $k }
        }
        if ($result.Markers -contains 'BOOTMGR') { $result.Loader = 'BOOTMGR (NT60 - Vista+)' }
        elseif ($result.Markers -contains 'NTLDR') { $result.Loader = 'NTLDR (NT52 - XP/2003)' }

        return [pscustomobject]$result
    }

    ################################################################################
    # Get-BootSectorReport
    #
    # Read-only. Reads sector 0 of the disk (MBR), sector 0 of the boot partition
    # (VBR) and the NTFS backup boot sector (last sector of that partition), then
    # produces a findings list. Safe to call at any time; performs no writes.
    ################################################################################
    function Get-BootSectorReport {
        param(
            [Parameter(Mandatory = $true)][int]$DiskNumber,
            [string]$BootDriveLetter = ''
        )

        $report = [ordered]@{
            DiskNumber    = $DiskNumber
            Mbr           = $null
            Vbr           = $null
            BackupVbr     = $null
            BootPartition = $null
            VbrMatchesBackup = $null
            Findings      = @()
            Errors        = @()
        }

        try { $report.Mbr = ConvertFrom-MbrSector -Sector (Read-RawDiskBytes -DiskNumber $DiskNumber -ByteOffset 0 -Length 512) }
        catch { $report.Errors += "Could not read MBR of disk $DiskNumber : $_" }

        $bootPart = $null
        if ($BootDriveLetter) {
            $letter = $BootDriveLetter.TrimEnd('\', ':')
            $bootPart = Get-Partition -DiskNumber $DiskNumber -ErrorAction SilentlyContinue |
                Where-Object { $_.DriveLetter -and ([string]$_.DriveLetter) -eq $letter } | Select-Object -First 1
        }
        if (-not $bootPart) {
            $bootPart = Get-Partition -DiskNumber $DiskNumber -ErrorAction SilentlyContinue |
                Where-Object { $_.IsActive } | Select-Object -First 1
        }
        $report.BootPartition = $bootPart

        if ($bootPart) {
            try {
                $vbrBytes = Read-RawDiskBytes -DiskNumber $DiskNumber -ByteOffset ([UInt64]$bootPart.Offset) -Length 512
                $report.Vbr = ConvertFrom-NtfsVbr -Bytes $vbrBytes

                # NTFS keeps a byte-identical copy of sector 0 in the final sector of the
                # volume. TotalSectors excludes that backup sector, so it is exactly at
                # partitionOffset + TotalSectors * bytesPerSector.
                if ($report.Vbr.IsNtfs -and $report.Vbr.TotalSectors -gt 0 -and $report.Vbr.BytesPerSector -ge 512) {
                    $backupOffset = [UInt64]$bootPart.Offset + ([UInt64]$report.Vbr.TotalSectors * [UInt64]$report.Vbr.BytesPerSector)
                    if (($backupOffset + 512) -le [UInt64]($bootPart.Offset + $bootPart.Size)) {
                        $backupBytes = Read-RawDiskBytes -DiskNumber $DiskNumber -ByteOffset $backupOffset -Length 512
                        $report.BackupVbr = ConvertFrom-NtfsVbr -Bytes $backupBytes
                        $report.BackupVbr | Add-Member -NotePropertyName ByteOffset -NotePropertyValue $backupOffset -Force
                        $report.BackupVbr | Add-Member -NotePropertyName Raw -NotePropertyValue $backupBytes -Force
                        $report.VbrMatchesBackup = -not (Compare-Object $vbrBytes $backupBytes -SyncWindow 0)
                    }
                }
                $report.Vbr | Add-Member -NotePropertyName Raw -NotePropertyValue $vbrBytes -Force
            }
            catch { $report.Errors += "Could not read VBR of partition $($bootPart.PartitionNumber): $_" }
        }
        else {
            $report.Errors += "No boot partition could be resolved on disk $DiskNumber (no drive letter match and no Active partition)."
        }

        # ---------------- Findings ----------------
        $f = [System.Collections.Generic.List[object]]::new()
        $add = { param($Sev, $Msg, $Fix) $f.Add([pscustomobject]@{ Severity = $Sev; Message = $Msg; Fix = $Fix }) }

        if ($report.Mbr) {
            if (-not $report.Mbr.HasSignature) {
                & $add 'CRITICAL' 'MBR sector 0 has no 0x55AA boot signature - the BIOS will not treat this disk as bootable ("Operating system not found" / "No bootable device").' '-FixBootSector'
            }
            if ($report.Mbr.BootCodeNonZero -eq 0) {
                & $add 'CRITICAL' 'MBR bootstrap code (bytes 0-439) is entirely zero - nothing will execute after the BIOS hands over ("Operating system not found").' '-FixBootSector'
            }
            elseif (-not $report.Mbr.IsWindowsBootCode) {
                & $add 'WARNING' "MBR bootstrap code is present but does not look like the standard Windows MBR (expected strings not found; markers: $($report.Mbr.Markers -join ', ')). It may be a third-party or damaged bootloader." '-FixBootSector'
            }
            if ($report.Mbr.ActiveCount -eq 0) {
                & $add 'CRITICAL' 'No MBR partition is flagged Active - the Windows MBR bootstrap prints "Missing operating system" and stops.' '-FixBoot (sets Active) or -FixBootSector'
            }
            elseif ($report.Mbr.ActiveCount -gt 1) {
                & $add 'CRITICAL' "$($report.Mbr.ActiveCount) partitions are flagged Active - the MBR bootstrap requires exactly one." '-FixBootSector'
            }
        }

        if ($report.Vbr) {
            if (-not $report.Vbr.HasSignature) {
                & $add 'CRITICAL' 'Volume boot record (VBR) has no 0x55AA signature - the MBR bootstrap prints "Missing operating system".' '-FixBootSector'
            }
            if (-not $report.Vbr.IsNtfs) {
                & $add 'WARNING' "Boot partition OEM ID is '$($report.Vbr.OemId)', not 'NTFS    '. The boot volume may be RAW or a different filesystem." '-FixFileSystem'
            }
            if ($report.Vbr.BootCodeNonZero -eq 0) {
                & $add 'CRITICAL' 'VBR bootstrap code (offset 0x54-0x1FD) is entirely zero - the MBR loads it and nothing happens.' '-FixBootSector'
            }
            if ($report.Vbr.Loader -eq 'NTLDR (NT52 - XP/2003)') {
                & $add 'CRITICAL' 'VBR carries the NT52 (NTLDR) bootstrap, but this OS boots via BOOTMGR. The VBR will look for NTLDR and fail.' '-FixBootSector'
            }
            elseif ($report.Vbr.Loader -eq 'None' -and $report.Vbr.BootCodeNonZero -gt 0) {
                & $add 'WARNING' 'VBR bootstrap contains code but references neither BOOTMGR nor NTLDR - it is probably not a Windows boot sector.' '-FixBootSector'
            }

            # The single highest-value check: BPB HiddenSectors must equal the partition's
            # start LBA. The bootstrap adds HiddenSectors to every relative read, so a stale
            # value sends the BIOS reads to the wrong absolute sectors. Windows itself never
            # uses this field, so the volume mounts fine and chkdsk/sfc report no problems -
            # the failure only appears at BIOS boot as "A disk read error occurred".
            if ($report.BootPartition -and $report.Vbr.BytesPerSector -ge 512) {
                $expectedHidden = [UInt64]$report.BootPartition.Offset / [UInt64]$report.Vbr.BytesPerSector
                $report.Vbr | Add-Member -NotePropertyName ExpectedHiddenSectors -NotePropertyValue $expectedHidden -Force
                if ([UInt64]$report.Vbr.HiddenSectors -ne $expectedHidden) {
                    & $add 'CRITICAL' ("VBR BPB HiddenSectors = $($report.Vbr.HiddenSectors) but the partition actually starts at LBA $expectedHidden. " +
                        'The BIOS bootstrap will read from the wrong absolute sectors: "A disk read error occurred. Press Ctrl+Alt+Del to restart". ' +
                        'Windows ignores this field, which is why chkdsk and sfc come back clean.') '-FixBootSector'
                }
            }

            # Total sectors must fit inside the partition, otherwise the volume was resized
            # or the partition table was rewritten without updating the BPB.
            if ($report.BootPartition -and $report.Vbr.IsNtfs -and $report.Vbr.TotalSectors -gt 0) {
                $partSectors = [UInt64]$report.BootPartition.Size / [UInt64]$report.Vbr.BytesPerSector
                if ([UInt64]$report.Vbr.TotalSectors -ge $partSectors) {
                    & $add 'CRITICAL' ("VBR BPB TotalSectors = $($report.Vbr.TotalSectors) but the partition only holds $partSectors sectors. " +
                        'The filesystem believes it is larger than its container - this follows a bad resize and makes the NTFS backup boot sector unreachable.') '-FixFileSystem then -FixBootSector'
                }
            }

            if ($null -ne $report.VbrMatchesBackup -and -not $report.VbrMatchesBackup) {
                & $add 'WARNING' 'VBR does not match the NTFS backup boot sector at the end of the volume - one of the two has been modified or corrupted.' '-FixBootSector'
            }
            if ($report.Vbr.IsNtfs -and $null -eq $report.BackupVbr) {
                & $add 'WARNING' 'NTFS backup boot sector could not be read - native VBR restore is unavailable; bootsect.exe would be required.' ''
            }
        }

        $report.Findings = $f.ToArray()
        return [pscustomobject]$report
    }

    function Show-BootSectorReport {
        param([Parameter(Mandatory = $true)]$Report)

        Write-Host ""
        Write-Host "Boot sector analysis (disk $($Report.DiskNumber)):" -ForegroundColor Cyan

        if ($Report.Mbr) {
            $m = $Report.Mbr
            $sig = if ($m.HasSignature) { '0x55AA OK' } else { 'MISSING' }
            $code = if ($m.BootCodeNonZero -eq 0) { 'ZEROED' }
            elseif ($m.IsWindowsBootCode) { "Windows bootstrap ($($m.BootCodeNonZero) bytes)" }
            else { "unrecognised ($($m.BootCodeNonZero) bytes)" }
            Write-Host "  MBR  : signature $sig | bootstrap: $code | disk signature 0x$($m.DiskSignature) | active partitions: $($m.ActiveCount)"
            foreach ($p in $m.Partitions) {
                $flag = if ($p.IsActive) { 'ACTIVE' } else { '      ' }
                Write-Host ("         [$flag] entry $($p.Index): type $($p.TypeByte) | start LBA $($p.StartLBA) | $($p.SizeGB) GB") -ForegroundColor DarkGray
            }
        }

        if ($Report.Vbr) {
            $v = $Report.Vbr
            $letter = if ($Report.BootPartition -and $Report.BootPartition.DriveLetter) { "$($Report.BootPartition.DriveLetter):" } else { "partition $($Report.BootPartition.PartitionNumber)" }
            $sig = if ($v.HasSignature) { '0x55AA OK' } else { 'MISSING' }
            Write-Host "  VBR  : $letter | OEM '$($v.OemId)' | signature $sig | bootstrap: $($v.Loader) | $($v.BootCodeNonZero) code bytes"
            $hiddenNote = ''
            if ($null -ne $v.ExpectedHiddenSectors) {
                $hiddenNote = if ([UInt64]$v.HiddenSectors -eq [UInt64]$v.ExpectedHiddenSectors) { ' (matches partition start - OK)' }
                else { " (MISMATCH - partition starts at LBA $($v.ExpectedHiddenSectors))" }
            }
            Write-Host "         HiddenSectors $($v.HiddenSectors)$hiddenNote" -ForegroundColor DarkGray
            Write-Host "         TotalSectors $($v.TotalSectors) | $($v.BytesPerSector) B/sector | $($v.SectorsPerCluster) sectors/cluster" -ForegroundColor DarkGray
            if ($null -ne $Report.VbrMatchesBackup) {
                $bk = if ($Report.VbrMatchesBackup) { 'identical to backup boot sector' } else { 'DIFFERS from backup boot sector' }
                Write-Host "         Backup boot sector: $bk" -ForegroundColor DarkGray
            }
        }

        foreach ($e in $Report.Errors) { Write-Warning $e }

        if ($Report.Findings.Count -eq 0) {
            Write-Host "  [OK] No boot sector problems detected." -ForegroundColor Green
        }
        else {
            Write-Host ""
            foreach ($finding in $Report.Findings) {
                $colour = if ($finding.Severity -eq 'CRITICAL') { 'Red' } else { 'Yellow' }
                Write-Host "  [$($finding.Severity)] $($finding.Message)" -ForegroundColor $colour
                if ($finding.Fix) { Write-Host "             Fix: $($finding.Fix)" -ForegroundColor DarkGray }
            }
        }
        Write-Host ""
    }

    ################################################################################
    # Find-BootsectExe - bootsect.exe is not in-box on Windows Server. Look in every
    # place it realistically turns up on a rescue VM, including mounted ISOs.
    ################################################################################
    function Find-BootsectExe {
        param([string]$ExplicitPath = '')

        if ($ExplicitPath) {
            if (Test-Path -LiteralPath $ExplicitPath) { return $ExplicitPath }
            Write-Warning "BootsectPath '$ExplicitPath' does not exist; falling back to auto-discovery."
        }

        $candidates = @(
            "$env:ProgramFiles\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\amd64\BCDBoot\bootsect.exe",
            "${env:ProgramFiles(x86)}\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\amd64\BCDBoot\bootsect.exe",
            "$env:ProgramFiles\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\x86\BCDBoot\bootsect.exe",
            "${env:ProgramFiles(x86)}\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\x86\BCDBoot\bootsect.exe",
            "$env:SystemRoot\System32\bootsect.exe",
            "$env:SystemRoot\Boot\bootsect.exe",
            "$env:SystemDrive\bootsect.exe",
            (Join-Path $PSScriptRoot 'bootsect.exe')
        )
        foreach ($p in $candidates) {
            if ($p -and (Test-Path -LiteralPath $p)) { return $p }
        }

        $inPath = Get-Command bootsect.exe -ErrorAction SilentlyContinue
        if ($inPath) { return $inPath.Source }

        # Windows installation media (ISO/USB) always carries \boot\bootsect.exe and it
        # runs standalone. Check every optical / removable volume that is mounted.
        foreach ($vol in (Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.DriveType -in @('CD-ROM', 'Removable') })) {
            $p = "$($vol.DriveLetter):\boot\bootsect.exe"
            if (Test-Path -LiteralPath $p) { return $p }
        }

        return $null
    }

    ################################################################################
    # Get-WindowsMbrBootstrap - source a known-good 440-byte Windows MBR bootstrap.
    # The rescue VM itself is normally a Gen1 (BIOS/MBR) Azure VM, so its own disk 0
    # carries exactly the bootstrap we need. Never returns the target disk's own code.
    ################################################################################
    function Get-WindowsMbrBootstrap {
        param([int]$ExcludeDiskNumber = -1)

        $disks = @(Get-Disk -ErrorAction SilentlyContinue |
            Where-Object { $_.PartitionStyle -eq 'MBR' -and $_.Number -ne $ExcludeDiskNumber } |
            Sort-Object Number)

        foreach ($d in $disks) {
            try {
                $sector = Read-RawDiskBytes -DiskNumber $d.Number -ByteOffset 0 -Length 512
                $info = ConvertFrom-MbrSector -Sector $sector
                if ($info.HasSignature -and $info.IsWindowsBootCode -and -not $info.IsProtectiveMbr) {
                    return [pscustomobject]@{
                        SourceDisk = $d.Number
                        Bootstrap  = $sector[0..439]
                    }
                }
            }
            catch { continue }
        }
        return $null
    }

    function Save-BootSectorBackup {
        param(
            [Parameter(Mandatory = $true)][int]$DiskNumber,
            [Parameter(Mandatory = $true)]$Report
        )
        $dir = Join-Path $env:SystemDrive 'RepairAzVMDisk-Backups'
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $stamp = (Get-Date).ToString('yyyyMMdd-HHmmss')
        $saved = @()

        if ($Report.Mbr) {
            $path = Join-Path $dir "disk$DiskNumber-mbr-$stamp.bin"
            [System.IO.File]::WriteAllBytes($path, (Read-RawDiskBytes -DiskNumber $DiskNumber -ByteOffset 0 -Length 512))
            $saved += $path
        }
        if ($Report.Vbr -and $Report.Vbr.Raw) {
            $path = Join-Path $dir "disk$DiskNumber-part$($Report.BootPartition.PartitionNumber)-vbr-$stamp.bin"
            [System.IO.File]::WriteAllBytes($path, $Report.Vbr.Raw)
            $saved += $path
        }
        foreach ($p in $saved) { Write-Host "  Sector backup written: $p" -ForegroundColor DarkGray }
        Write-ActionLog -Event 'BootSectorBackup' -Details @{ DiskNumber = $DiskNumber; Files = $saved }
        return $saved
    }

    function FixBootSector {
        Write-Host "Fixing MBR/VBR boot sector..." -ForegroundColor Yellow
        try {
            if ($script:VMGen -ne 1) {
                Write-Warning "Gen2 (UEFI/GPT) VMs do not use MBR/VBR. Use -FixBoot to rebuild the EFI BCD store instead."
                return
            }

            $SysDrive = $script:BootDriveLetter.TrimEnd('\')
            $diskNum = $script:DiskNumber

            # ---------------------------------------------------------------
            # 1. Inspect first. Nothing here writes.
            # ---------------------------------------------------------------
            $report = Get-BootSectorReport -DiskNumber $diskNum -BootDriveLetter $SysDrive
            Show-BootSectorReport -Report $report
            $script:BootSectorReport = $report

            if (-not $report.BootPartition) {
                Write-Error "Cannot repair boot sectors: no boot partition resolved on disk $diskNum."
                return
            }

            $criticals = @($report.Findings | Where-Object { $_.Severity -eq 'CRITICAL' })
            if ($report.Findings.Count -eq 0) {
                Write-Host "Boot sectors already look healthy. Repairing anyway is harmless but usually unnecessary." -ForegroundColor DarkGray
            }

            $bootPart = $report.BootPartition
            $partLabel = if ($bootPart.DriveLetter) { "$($bootPart.DriveLetter): (partition $($bootPart.PartitionNumber))" } else { "partition $($bootPart.PartitionNumber)" }

            $proceed = Confirm-CriticalOperation `
                -Operation "Rewrite MBR bootstrap and volume boot record on disk $diskNum" `
                -Details @"
This writes raw sectors. It is the only repair in this script that does so.

  Disk           : $diskNum
  Boot partition : $partLabel
  Findings       : $($report.Findings.Count) ($($criticals.Count) critical)

Steps:
  - Back up the current MBR and VBR sectors to $env:SystemDrive\RepairAzVMDisk-Backups
  - Take disk $diskNum offline (raw sector writes into a mounted volume are blocked by Windows)
  - Repair the VBR bootstrap and correct the BPB HiddenSectors field
  - Repair the MBR bootstrap (partition table is preserved byte for byte)
  - Bring disk $diskNum back online

The MBR partition table and all filesystem data are left untouched.
"@
            if (-not $proceed) { return }

            Save-BootSectorBackup -DiskNumber $diskNum -Report $report | Out-Null

            # ---------------------------------------------------------------
            # 2. Prefer bootsect.exe when it is genuinely available.
            # ---------------------------------------------------------------
            $bootsect = Find-BootsectExe -ExplicitPath $script:BootsectPath
            $bootsectDone = $false
            if ($bootsect) {
                Write-Host "Using bootsect.exe: $bootsect" -ForegroundColor Cyan
                $bsCmd = "`"$bootsect`" /nt60 $SysDrive /mbr /force"
                $bsResult = Invoke-NativeCommandLogged -Description 'bootsect /nt60 /mbr' -Details @{
                    SysDrive = $SysDrive; Tool = $bootsect
                } -ScriptBlock { & cmd.exe /c $bsCmd }
                $bsResult.Output | Out-Host
                if ($bsResult.ExitCode -eq 0) {
                    Write-Host "MBR and VBR bootstrap rewritten via bootsect." -ForegroundColor Green
                    $bootsectDone = $true
                }
                else {
                    Write-Warning "bootsect.exe returned exit code $($bsResult.ExitCode). Falling back to the native repair."
                }
            }
            else {
                Write-Host "bootsect.exe not found (it is not in-box on Windows Server; it ships with the Windows ADK" -ForegroundColor DarkGray
                Write-Host "or as \boot\bootsect.exe on Windows installation media). Using the native repair instead." -ForegroundColor DarkGray
                Write-Host "You can also point the script at a copy with -BootsectPath <path>." -ForegroundColor DarkGray
            }

            # ---------------------------------------------------------------
            # 3. Native repair. Runs with the disk offline so Windows permits
            #    writes to sectors that belong to a mounted volume.
            #    Note: bootsect does NOT correct BPB HiddenSectors, so the
            #    HiddenSectors repair runs even when bootsect succeeded.
            # ---------------------------------------------------------------
            $wasOffline = (Get-Disk -Number $diskNum).IsOffline
            $changed = @()
            try {
                if (-not $wasOffline) {
                    Write-Host "Taking disk $diskNum offline for sector writes..." -ForegroundColor DarkGray
                    Set-Disk -Number $diskNum -IsOffline $true
                    Start-Sleep -Seconds 2
                }

                # ---- VBR ----
                $vbrOffset = [UInt64]$bootPart.Offset
                $current = Read-RawDiskBytes -DiskNumber $diskNum -ByteOffset $vbrOffset -Length 512
                $cur = ConvertFrom-NtfsVbr -Bytes $current
                $newVbr = $current.Clone()
                $vbrDirty = $false

                # 3a. Bootstrap code: restore from the NTFS backup boot sector when the
                #     live one is unusable. The backup is a byte-identical copy written at
                #     format time and kept in the final sector of the volume.
                $needBootstrap = (-not $cur.HasSignature) -or ($cur.BootCodeNonZero -eq 0) -or
                                 ($cur.Loader -eq 'NTLDR (NT52 - XP/2003)') -or ($cur.Loader -eq 'None')
                if ($needBootstrap -and -not $bootsectDone) {
                    if ($report.BackupVbr -and $report.BackupVbr.HasSignature -and
                        $report.BackupVbr.IsNtfs -and $report.BackupVbr.Loader -like 'BOOTMGR*') {
                        Write-Host "  Restoring VBR bootstrap from the NTFS backup boot sector at offset $($report.BackupVbr.ByteOffset)." -ForegroundColor Cyan
                        $newVbr = $report.BackupVbr.Raw.Clone()
                        $vbrDirty = $true
                        $changed += 'VBR bootstrap restored from NTFS backup boot sector'
                    }
                    else {
                        Write-Warning "  VBR bootstrap is damaged and no usable NTFS backup boot sector is available."
                        Write-Warning "  Supply bootsect.exe via -BootsectPath to rewrite the NT60 bootstrap."
                    }
                }

                # 3b. BPB HiddenSectors must equal the partition start LBA. This is the field
                #     that a partition move or a bad resize leaves stale, and neither bcdboot,
                #     bootsect, chkdsk nor sfc corrects it.
                $bps = if ($cur.BytesPerSector -ge 512) { [UInt64]$cur.BytesPerSector } else { [UInt64]512 }
                $expectedHidden = $vbrOffset / $bps
                $actualHidden = [UInt64][BitConverter]::ToUInt32($newVbr, 28)
                if ($actualHidden -ne $expectedHidden) {
                    if ($expectedHidden -gt [UInt32]::MaxValue) {
                        Write-Warning "  Partition starts at LBA $expectedHidden, which exceeds the 32-bit HiddenSectors field. Skipping."
                    }
                    else {
                        Write-Host "  Correcting BPB HiddenSectors: $actualHidden -> $expectedHidden" -ForegroundColor Cyan
                        [Array]::Copy([BitConverter]::GetBytes([UInt32]$expectedHidden), 0, $newVbr, 28, 4)
                        $vbrDirty = $true
                        $changed += "BPB HiddenSectors corrected ($actualHidden -> $expectedHidden)"
                    }
                }

                # 3c. Boot signature.
                if ($newVbr[510] -ne 0x55 -or $newVbr[511] -ne 0xAA) {
                    Write-Host "  Restoring VBR 0x55AA boot signature." -ForegroundColor Cyan
                    $newVbr[510] = 0x55; $newVbr[511] = 0xAA
                    $vbrDirty = $true
                    $changed += 'VBR boot signature restored'
                }

                if ($vbrDirty) {
                    Invoke-Logged -Description 'Write repaired VBR' -Details @{
                        DiskNumber = $diskNum; ByteOffset = $vbrOffset; Partition = $bootPart.PartitionNumber
                    } -ScriptBlock {
                        Write-RawDiskBytes -DiskNumber $diskNum -ByteOffset $vbrOffset -Data $newVbr
                    } | Out-Null
                }

                # ---- MBR ----
                if (-not $bootsectDone) {
                    $mbrSector = Read-RawDiskBytes -DiskNumber $diskNum -ByteOffset 0 -Length 512
                    $mbrInfo = ConvertFrom-MbrSector -Sector $mbrSector
                    $mbrDirty = $false

                    if (-not $mbrInfo.IsWindowsBootCode) {
                        $src = Get-WindowsMbrBootstrap -ExcludeDiskNumber $diskNum
                        if ($src) {
                            Write-Host "  Writing Windows MBR bootstrap sourced from disk $($src.SourceDisk) (partition table preserved)." -ForegroundColor Cyan
                            [Array]::Copy($src.Bootstrap, 0, $mbrSector, 0, 440)
                            $mbrDirty = $true
                            $changed += "MBR bootstrap rewritten from disk $($src.SourceDisk)"
                        }
                        else {
                            Write-Warning "  MBR bootstrap is not a Windows bootstrap and no healthy MBR disk is available on this host to copy from."
                            Write-Warning "  Supply bootsect.exe via -BootsectPath, or attach the disk to a Gen1 (BIOS/MBR) rescue VM."
                        }
                    }

                    if ($mbrSector[510] -ne 0x55 -or $mbrSector[511] -ne 0xAA) {
                        Write-Host "  Restoring MBR 0x55AA boot signature." -ForegroundColor Cyan
                        $mbrSector[510] = 0x55; $mbrSector[511] = 0xAA
                        $mbrDirty = $true
                        $changed += 'MBR boot signature restored'
                    }

                    if ($mbrDirty) {
                        Invoke-Logged -Description 'Write repaired MBR' -Details @{ DiskNumber = $diskNum } -ScriptBlock {
                            Write-RawDiskBytes -DiskNumber $diskNum -ByteOffset 0 -Data $mbrSector
                        } | Out-Null
                    }
                }
            }
            finally {
                if (-not $wasOffline) {
                    Write-Host "Bringing disk $diskNum back online..." -ForegroundColor DarkGray
                    Set-Disk -Number $diskNum -IsOffline $false -ErrorAction SilentlyContinue
                    Set-Disk -Number $diskNum -IsReadOnly $false -ErrorAction SilentlyContinue
                    # Wait for the volumes to remount before any later repair step needs them.
                    $letter = $SysDrive.TrimEnd(':')
                    for ($i = 0; $i -lt 15; $i++) {
                        Start-Sleep -Seconds 1
                        $d = Get-Disk -Number $diskNum -ErrorAction SilentlyContinue
                        if ($d -and -not $d.IsOffline -and (Get-Volume -DriveLetter $letter -ErrorAction SilentlyContinue)) { break }
                    }
                    $d = Get-Disk -Number $diskNum -ErrorAction SilentlyContinue
                    if ($d -and $d.IsOffline) {
                        Write-Warning "Disk $diskNum did not come back online automatically. Bring it online manually before continuing."
                    }
                    elseif (-not (Get-Volume -DriveLetter $letter -ErrorAction SilentlyContinue)) {
                        Write-Warning "Disk $diskNum is online but drive letter $SysDrive has not reappeared yet."
                    }
                }
            }

            Write-ActionLog -Event 'FixBootSector' -Details @{
                DiskNumber = $diskNum
                UsedBootsect = $bootsectDone
                Changes = $changed
            }

            # ---------------------------------------------------------------
            # 4. Re-inspect so the operator sees the post-repair state.
            # ---------------------------------------------------------------
            if ($changed.Count -eq 0 -and -not $bootsectDone) {
                Write-Host "No boot sector changes were applied." -ForegroundColor Yellow
            }
            else {
                Write-Host ""
                Write-Host "Boot sector changes applied:" -ForegroundColor Green
                foreach ($c in $changed) { Write-Host "  - $c" -ForegroundColor Green }
                if ($bootsectDone) { Write-Host "  - MBR/VBR bootstrap rewritten by bootsect.exe" -ForegroundColor Green }
            }

            $after = Get-BootSectorReport -DiskNumber $diskNum -BootDriveLetter $SysDrive
            Write-Host "Post-repair verification:" -ForegroundColor Cyan
            Show-BootSectorReport -Report $after
            $script:BootSectorReport = $after

            if (@($after.Findings | Where-Object { $_.Severity -eq 'CRITICAL' }).Count -eq 0) {
                Write-Host "Boot sector chain is now valid. If the VM still fails to boot, the fault is above this layer" -ForegroundColor Green
                Write-Host "(boot files / BCD -> -FixBoot, storage drivers -> -FixBootStorageDrivers, filesystem -> -FixFileSystem)." -ForegroundColor DarkGray
            }
            else {
                Write-Warning "Critical boot sector findings remain - see above."
            }
        }
        catch {
            Write-Error "FixBootSector failed: $_"
            throw
        }
    }

    function DisableStartupRepair {
        # BCD-only: removes the recovery trigger so the guest will not auto-launch
        # WinRE on the next boot failure. Intentionally does NOT touch Winre.wim,
        # the recovery partition, or reagentc registration - re-running
        # -EnableStartupRepair is a clean toggle back on.
        Write-Host "Disabling automatic startup repair loop..." -ForegroundColor Yellow
        try {
            $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
            $identifier = Get-BcdBootLoaderId -StorePath $storePath
            if (-not $identifier) { return }

            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier recoveryenabled No"
            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier bootstatuspolicy IgnoreAllFailures"
            Invoke-BcdEdit -StorePath $storePath -Command "/set {bootmgr} displaybootmenu no"
            Write-Host "Startup repair disabled in BCD. Existing WinRE files and registration were left untouched." -ForegroundColor Green
            Write-Host "To re-enable: use -EnableStartupRepair" -ForegroundColor DarkCyan
        }
        catch {
            Write-Error "DisableStartupRepair failed: $_"
            throw
        }
    }

    function EnableStartupRepair {
        # Make automatic startup repair work end-to-end on the offline guest.
        # Order of operations is important: WinRE provisioning runs FIRST so that
        # we never mutate BCD on a disk where WinRE cannot actually be registered.
        #   1. Resolve BCD store + loader id (no writes).
        #   2. Call EnableWinREOffline which discovers Winre.wim (including on hidden
        #      recovery partitions), repairs a broken recovery partition if needed,
        #      stages Winre.wim into \System32\Recovery, and registers via reagentc.
        #      reagentc /enable already writes the BCD recoverysequence GUID.
        #   3. Only on success: flip recoveryenabled Yes, clear bootstatuspolicy,
        #      hide boot menu. These are safe no-op-style toggles once WinRE exists.
        #   4. On failure: do nothing to BCD - the guest is left exactly as-is.
        Write-Host "Enabling automatic startup repair..." -ForegroundColor Yellow
        try {
            $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
            $identifier = Get-BcdBootLoaderId -StorePath $storePath
            if (-not $identifier) { return }

            $winreReady = EnableWinREOffline
            if (-not $winreReady) {
                Write-Host "Startup repair was NOT enabled because WinRE could not be provisioned on this disk." -ForegroundColor Red
                Write-Host "BCD was left unchanged. Restore Winre.wim onto the disk (e.g. into <Win>\Windows\System32\Recovery\) and rerun -EnableStartupRepair." -ForegroundColor DarkCyan
                return
            }

            # WinRE is registered. Now safely flip the BCD policy bits so the guest
            # actually triggers it on the next boot failure.
            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier recoveryenabled Yes"
            Invoke-BcdEdit -StorePath $storePath -Command "/deletevalue $identifier bootstatuspolicy"
            Invoke-BcdEdit -StorePath $storePath -Command "/set {bootmgr} displaybootmenu no"

            $loaderAfter = Get-BcdLoaderDetails -StorePath $storePath -Identifier $identifier
            $newSeq = $null
            if ($loaderAfter) {
                $m = [regex]::Match($loaderAfter.RawText, '(?im)^\s*recoverysequence\s+(.+)$')
                if ($m.Success) { $newSeq = $m.Groups[1].Value.Trim() }
            }
            Write-Host "Startup repair re-enabled and WinRE is registered for the offline guest." -ForegroundColor Green
            if ($newSeq) {
                Write-Host "BCD recoverysequence: $newSeq" -ForegroundColor Green
            }
        }
        catch {
            Write-Error "EnableStartupRepair failed: $_"
            throw
        }
    }

    function Mount-HiddenRecoveryPartition {
        # Temporarily exposes any GPT/MBR Recovery-typed partitions on $script:DiskNumber
        # that have no drive letter, so Winre.wim and ReAgent.xml can be read or repaired.
        # On GPT (Gen2) the hidden attribute 0x8000000000000001 is cleared via diskpart
        # so a drive letter can be assigned; the original attribute value is captured for
        # restore in Dismount-HiddenRecoveryPartition.
        # Returns: array of [pscustomobject] with PartitionNumber, DiskNumber, AccessPath,
        # GptType, OriginalGptAttributes (uint64 or $null on MBR), WasMounted (bool).
        $results = @()
        try {
            $disk = Get-Disk -Number $script:DiskNumber -ErrorAction Stop
        }
        catch {
            return $results
        }

        $isGpt = ($disk.PartitionStyle -eq 'GPT')
        $partitions = @(Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue |
            Where-Object { $_.Type -eq 'Recovery' })
        if ($partitions.Count -eq 0) { return $results }

        foreach ($part in $partitions) {
            $existingLetter = @($part.AccessPaths | Where-Object { $_ -and $_ -match '^[A-Za-z]:\\?$' })
            if ($existingLetter.Count -gt 0) {
                # Already mounted - record but do not touch.
                $results += [pscustomobject]@{
                    PartitionNumber       = $part.PartitionNumber
                    DiskNumber            = $script:DiskNumber
                    AccessPath            = ($existingLetter[0].TrimEnd('\') + '\')
                    GptType               = if ($isGpt) { $part.GptType } else { $null }
                    OriginalGptAttributes = $null
                    WasMounted            = $true
                }
                continue
            }

            $origAttr = $null
            if ($isGpt) {
                # Capture current GPT attributes via diskpart so we can restore them later.
                $detailScript = "select disk $script:DiskNumber`r`nselect partition $($part.PartitionNumber)`r`ndetail partition`r`nexit`r`n"
                $tmpDetail = [System.IO.Path]::GetTempFileName()
                try {
                    Set-Content -LiteralPath $tmpDetail -Value $detailScript -Encoding ASCII -NoNewline
                    $detailOut = & diskpart.exe /s $tmpDetail 2>&1
                    $attrLine = ($detailOut | Select-String -Pattern '^\s*Attributes\s*:\s*(0x[0-9a-fA-F]+)' | Select-Object -First 1)
                    if ($attrLine) {
                        $origAttr = [Convert]::ToUInt64($attrLine.Matches[0].Groups[1].Value, 16)
                    }
                }
                finally {
                    Remove-Item -LiteralPath $tmpDetail -Force -ErrorAction SilentlyContinue
                }

                # Clear the no-drive-letter / hidden bits so Add-PartitionAccessPath succeeds.
                # GPT_ATTRIBUTE_NO_DRIVE_LETTER = 0x8000000000000000
                # GPT_BASIC_DATA_ATTRIBUTE_HIDDEN = 0x4000000000000000
                $clearScript = "select disk $script:DiskNumber`r`nselect partition $($part.PartitionNumber)`r`ngpt attributes=0x0000000000000000`r`nexit`r`n"
                $tmpClear = [System.IO.Path]::GetTempFileName()
                try {
                    Set-Content -LiteralPath $tmpClear -Value $clearScript -Encoding ASCII -NoNewline
                    $null = & diskpart.exe /s $tmpClear 2>&1
                }
                finally {
                    Remove-Item -LiteralPath $tmpClear -Force -ErrorAction SilentlyContinue
                }
            }

            $assigned = $null
            try {
                $null = Add-PartitionAccessPath -DiskNumber $script:DiskNumber -PartitionNumber $part.PartitionNumber -AssignDriveLetter -ErrorAction Stop
                Start-Sleep -Milliseconds 500
                $refreshed = Get-Partition -DiskNumber $script:DiskNumber -PartitionNumber $part.PartitionNumber -ErrorAction SilentlyContinue
                if ($refreshed) {
                    $newLetter = @($refreshed.AccessPaths | Where-Object { $_ -and $_ -match '^[A-Za-z]:\\?$' })
                    if ($newLetter.Count -gt 0) {
                        $assigned = ($newLetter[0].TrimEnd('\') + '\')
                    }
                }
            }
            catch {
                Write-Warning "Mount-HiddenRecoveryPartition: failed to assign drive letter to disk $script:DiskNumber partition $($part.PartitionNumber): $_"
            }

            $results += [pscustomobject]@{
                PartitionNumber       = $part.PartitionNumber
                DiskNumber            = $script:DiskNumber
                AccessPath            = $assigned
                GptType               = if ($isGpt) { $part.GptType } else { $null }
                OriginalGptAttributes = $origAttr
                WasMounted            = $false
            }
        }

        return $results
    }

    function Dismount-HiddenRecoveryPartition {
        # Reverses Mount-HiddenRecoveryPartition. Skips entries that were already mounted
        # before we touched them. Restores GPT attributes captured at mount time.
        param(
            [Parameter(Mandatory = $false)]
            [object[]]$MountInfo
        )

        if (-not $MountInfo) { return }
        foreach ($info in $MountInfo) {
            if ($null -eq $info) { continue }
            if ($info.WasMounted) { continue }

            if ($info.AccessPath) {
                try {
                    Remove-PartitionAccessPath -DiskNumber $info.DiskNumber -PartitionNumber $info.PartitionNumber -AccessPath $info.AccessPath -ErrorAction Stop
                }
                catch {
                    Write-Warning "Dismount-HiddenRecoveryPartition: failed to remove access path $($info.AccessPath): $_"
                }
            }

            if ($null -ne $info.OriginalGptAttributes) {
                $hex = ('0x{0:X16}' -f [uint64]$info.OriginalGptAttributes)
                $restoreScript = "select disk $($info.DiskNumber)`r`nselect partition $($info.PartitionNumber)`r`ngpt attributes=$hex`r`nexit`r`n"
                $tmpRestore = [System.IO.Path]::GetTempFileName()
                try {
                    Set-Content -LiteralPath $tmpRestore -Value $restoreScript -Encoding ASCII -NoNewline
                    $null = & diskpart.exe /s $tmpRestore 2>&1
                }
                catch {
                    Write-Warning "Dismount-HiddenRecoveryPartition: failed to restore GPT attributes on partition $($info.PartitionNumber): $_"
                }
                finally {
                    Remove-Item -LiteralPath $tmpRestore -Force -ErrorAction SilentlyContinue
                }
            }
        }
    }

    function Get-WinREStatus {
        param(
            [string]$WindowsPath = $(Join-Path $script:WinDriveLetter 'Windows'),
            # When set, Recovery-typed partitions with no drive letter are temporarily
            # mounted so their Winre.wim can be discovered. The caller MUST dismount
            # them via Dismount-HiddenRecoveryPartition (pass RecoveryPartitionsMounted).
            [switch]$MountHidden
        )

        $status = [ordered]@{
            WindowsPath                 = $WindowsPath
            ReagentcAvailable           = [bool](Get-Command reagentc.exe -ErrorAction SilentlyContinue)
            ReagentInfoText             = ''
            ReStatus                    = ''
            ReLocation                  = ''
            ReBcdIdentifier             = ''
            CandidateDirectories        = @()
            PreferredDirectory          = ''
            ImageFound                  = $false
            HiddenRecoveryPartitions    = 0
            PreferredOsGuid             = ''
            WinreSourcePath             = ''
            PreferredIsRecoveryPart     = $false
            RecoveryPartitions          = @()
            RecoveryPartitionsMounted   = @()
        }

        if (-not $status.ReagentcAvailable) {
            return [PSCustomObject]$status
        }

        if ($MountHidden) {
            try {
                $status.RecoveryPartitionsMounted = @(Mount-HiddenRecoveryPartition)
            }
            catch {
                Write-Warning "Get-WinREStatus: Mount-HiddenRecoveryPartition failed: $_"
            }
        }

        $infoRaw = & reagentc.exe /info /target $WindowsPath 2>&1
        $status.ReagentInfoText = ($infoRaw -join "`n")
        $status.ReStatus = [regex]::Match($status.ReagentInfoText, '(?im)^\s*Windows RE status:\s+(.+)$').Groups[1].Value.Trim()
        $status.ReLocation = [regex]::Match($status.ReagentInfoText, '(?im)^\s*Windows RE location:\s+(.+)$').Groups[1].Value.Trim()
        $status.ReBcdIdentifier = [regex]::Match($status.ReagentInfoText, '(?im)^\s*Boot Configuration Data \(BCD\) identifier:\s+(.+)$').Groups[1].Value.Trim()

        $candidateDirs = [System.Collections.Generic.List[string]]::new()
        $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $addCandidate = {
            param([string]$Dir)
            if ([string]::IsNullOrWhiteSpace($Dir)) { return }
            $trimmed = $Dir.TrimEnd('\')
            if ($seen.Add($trimmed)) {
                $candidateDirs.Add($trimmed)
            }
        }

        $defaultDir = Join-Path $script:WinDriveLetter 'Windows\System32\Recovery'
        if (Test-Path -LiteralPath (Join-Path $defaultDir 'Winre.wim')) {
            & $addCandidate $defaultDir
        }

        $recoveryParts = [System.Collections.Generic.List[object]]::new()
        foreach ($partition in (Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue)) {
            $accessPaths = @($partition.AccessPaths | Where-Object { $_ -and $_ -match ':' })
            $isRecovery = ($partition.Type -eq 'Recovery')
            if ($isRecovery -and $accessPaths.Count -eq 0) {
                $status.HiddenRecoveryPartitions++
            }
            if ($isRecovery) {
                $letter = @($accessPaths | Where-Object { $_ -match '^[A-Za-z]:\\?$' } | Select-Object -First 1)
                $recoveryParts.Add([pscustomobject]@{
                    PartitionNumber = $partition.PartitionNumber
                    AccessPath      = if ($letter.Count -gt 0) { $letter[0].TrimEnd('\') + '\' } else { '' }
                    HasImage        = $false
                })
            }
            foreach ($accessPath in $accessPaths) {
                $candidateDir = Join-Path $accessPath 'Recovery\WindowsRE'
                if (Test-Path -LiteralPath (Join-Path $candidateDir 'Winre.wim')) {
                    & $addCandidate $candidateDir
                    if ($isRecovery -and $recoveryParts.Count -gt 0) {
                        $recoveryParts[$recoveryParts.Count - 1].HasImage = $true
                    }
                }
            }
        }
        $status.RecoveryPartitions = @($recoveryParts)

        $status.CandidateDirectories = @($candidateDirs)
        $status.ImageFound = ($candidateDirs.Count -gt 0)
        if ($candidateDirs.Count -gt 0) {
            # Prefer a dedicated recovery partition (\Recovery\WindowsRE) over \System32\Recovery
            # since that matches the layout reagentc/OEM expect.
            $status.PreferredDirectory = @($candidateDirs | Sort-Object @{ Expression = { if ($_ -match '\\Recovery\\WindowsRE$') { 0 } else { 1 } } }, @{ Expression = { if ($_ -like "$($script:WinDriveLetter.TrimEnd('\\'))*") { 1 } else { 0 } } } | Select-Object -First 1)[0]
            $status.WinreSourcePath = Join-Path $status.PreferredDirectory 'Winre.wim'
            $status.PreferredIsRecoveryPart = ($status.PreferredDirectory -match '\\Recovery\\WindowsRE$') -and `
                (-not ($status.PreferredDirectory -like "$($script:WinDriveLetter.TrimEnd('\\'))*"))
        }

        $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
        $status.PreferredOsGuid = Get-BcdPreferredOsGuid -StorePath $storePath

        return [PSCustomObject]$status
    }

    function Stage-WinReImage {
        # Ensures <WindowsPath>\System32\Recovery\Winre.wim exists by copying from a
        # discovered source if missing or different. This is the canonical layout
        # reagentc /setreimage consumes most reliably.
        # Returns the staged directory path (suitable for /setreimage /path) on success,
        # or $null on failure.
        param(
            [Parameter(Mandatory)] [string]$WindowsPath,
            [Parameter(Mandatory)] [string]$SourceWinrePath
        )

        if (-not (Test-Path -LiteralPath $SourceWinrePath)) {
            Write-Warning "Stage-WinReImage: source not found: $SourceWinrePath"
            return $null
        }

        $stagedDir = Join-Path $WindowsPath 'System32\Recovery'
        $stagedWim = Join-Path $stagedDir 'Winre.wim'

        try {
            if (-not (Test-Path -LiteralPath $stagedDir)) {
                Invoke-Logged -Description 'Create WinRE staging directory' -Details @{
                    Path = $stagedDir
                } -ScriptBlock {
                    $null = New-Item -ItemType Directory -Path $stagedDir -Force -ErrorAction Stop
                } | Out-Null
            }

            $needsCopy = $true
            if (Test-Path -LiteralPath $stagedWim) {
                $srcInfo = Get-Item -LiteralPath $SourceWinrePath -Force
                $dstInfo = Get-Item -LiteralPath $stagedWim -Force
                if ($srcInfo.Length -eq $dstInfo.Length) {
                    $srcHash = (Get-FileHash -LiteralPath $SourceWinrePath -Algorithm SHA256).Hash
                    $dstHash = (Get-FileHash -LiteralPath $stagedWim -Algorithm SHA256).Hash
                    if ($srcHash -eq $dstHash) {
                        $needsCopy = $false
                    }
                }
            }

            if ($needsCopy) {
                # Clear hidden/system/readonly so Copy-Item can overwrite.
                if (Test-Path -LiteralPath $stagedWim) {
                    Invoke-NativeCommandLogged -Description 'Clear staged WinRE image attributes' -Details @{
                        Path = $stagedWim
                    } -ScriptBlock { & cmd.exe /c "attrib -s -h -r `"$stagedWim`"" } | Out-Null
                }
                Invoke-Logged -Description 'Stage WinRE image' -Details @{
                    Source = $SourceWinrePath
                    Destination = $stagedWim
                } -ScriptBlock {
                    Copy-Item -LiteralPath $SourceWinrePath -Destination $stagedWim -Force -ErrorAction Stop
                } | Out-Null
                Invoke-NativeCommandLogged -Description 'Protect staged WinRE image attributes' -Details @{
                    Path = $stagedWim
                    Attributes = @('System', 'Hidden', 'ReadOnly')
                } -ScriptBlock { & cmd.exe /c "attrib +s +h +r `"$stagedWim`"" } | Out-Null
                Write-Host "Stage-WinReImage: copied Winre.wim -> $stagedWim" -ForegroundColor DarkCyan
            }
            else {
                Write-Host "Stage-WinReImage: existing Winre.wim already matches source (no copy)" -ForegroundColor DarkCyan
            }

            return $stagedDir
        }
        catch {
            Write-Warning "Stage-WinReImage failed: $_"
            return $null
        }
    }

    function Repair-RecoveryPartition {
        # Restores Winre.wim (and ReAgent.xml when present) onto a mounted recovery
        # partition that is missing a usable image. Uses chkdsk (best-effort) before
        # writing files. Caller is responsible for mount/dismount lifecycle.
        # Returns $true if Winre.wim ends up present at <AccessPath>\Recovery\WindowsRE\Winre.wim.
        param(
            [Parameter(Mandatory)] [string]$AccessPath,
            [Parameter(Mandatory)] [string]$SourceWinrePath,
            [string]$WindowsPath = $(Join-Path $script:WinDriveLetter 'Windows')
        )

        if (-not $AccessPath) {
            Write-Warning "Repair-RecoveryPartition: AccessPath is empty."
            return $false
        }
        if (-not (Test-Path -LiteralPath $SourceWinrePath)) {
            Write-Warning "Repair-RecoveryPartition: source Winre.wim not found at $SourceWinrePath"
            return $false
        }

        $driveLetter = ($AccessPath.Substring(0,2))
        $targetDir = Join-Path $AccessPath 'Recovery\WindowsRE'
        $targetWim = Join-Path $targetDir 'Winre.wim'
        $targetXml = Join-Path $targetDir 'ReAgent.xml'

        # Best-effort filesystem check. Tolerate non-zero exit if the volume root is still readable.
        try {
            Write-Host "Repair-RecoveryPartition: running chkdsk $driveLetter /F /X (best-effort)..." -ForegroundColor DarkCyan
            $chkResult = Invoke-NativeCommandLogged -Description 'Repair recovery partition filesystem' -Details @{
                Drive = $driveLetter
                Mode = 'F/X'
            } -AcceptedExitCodes @(0, 1, 2) -ScriptBlock { & cmd.exe /c "echo Y| chkdsk $driveLetter /F /X" }
            if (-not $chkResult.Success) {
                Write-Warning "chkdsk $driveLetter returned $($chkResult.ExitCode); will continue if volume is still readable."
            }
            if (-not (Test-Path -LiteralPath $AccessPath)) {
                Write-Warning "Repair-RecoveryPartition: $AccessPath not accessible after chkdsk; aborting."
                return $false
            }
        }
        catch {
            Write-Warning "Repair-RecoveryPartition: chkdsk invocation failed: $_"
        }

        try {
            if (-not (Test-Path -LiteralPath $targetDir)) {
                Invoke-Logged -Description 'Create recovery WindowsRE directory' -Details @{
                    Path = $targetDir
                } -ScriptBlock {
                    $null = New-Item -ItemType Directory -Path $targetDir -Force -ErrorAction Stop
                } | Out-Null
            }

            if (Test-Path -LiteralPath $targetWim) {
                Invoke-NativeCommandLogged -Description 'Clear recovery WinRE image attributes' -Details @{
                    Path = $targetWim
                } -ScriptBlock { & cmd.exe /c "attrib -s -h -r `"$targetWim`"" } | Out-Null
            }
            Invoke-Logged -Description 'Restore recovery WinRE image' -Details @{
                Source = $SourceWinrePath
                Destination = $targetWim
            } -ScriptBlock {
                Copy-Item -LiteralPath $SourceWinrePath -Destination $targetWim -Force -ErrorAction Stop
            } | Out-Null
            Invoke-NativeCommandLogged -Description 'Protect recovery WinRE image attributes' -Details @{
                Path = $targetWim
                Attributes = @('System', 'Hidden', 'ReadOnly')
            } -ScriptBlock { & cmd.exe /c "attrib +s +h +r `"$targetWim`"" } | Out-Null

            $sourceXml = Join-Path $WindowsPath 'System32\Recovery\ReAgent.xml'
            if (Test-Path -LiteralPath $sourceXml) {
                if (Test-Path -LiteralPath $targetXml) {
                    Invoke-NativeCommandLogged -Description 'Clear recovery ReAgent.xml attributes' -Details @{
                        Path = $targetXml
                    } -ScriptBlock { & cmd.exe /c "attrib -s -h -r `"$targetXml`"" } | Out-Null
                }
                Invoke-Logged -Description 'Restore recovery ReAgent.xml' -Details @{
                    Source = $sourceXml
                    Destination = $targetXml
                } -ScriptBlock {
                    Copy-Item -LiteralPath $sourceXml -Destination $targetXml -Force -ErrorAction Stop
                } | Out-Null
                Invoke-NativeCommandLogged -Description 'Protect recovery ReAgent.xml attributes' -Details @{
                    Path = $targetXml
                    Attributes = @('System', 'Hidden', 'ReadOnly')
                } -ScriptBlock { & cmd.exe /c "attrib +s +h +r `"$targetXml`"" } | Out-Null
            }
            elseif (-not (Test-Path -LiteralPath $targetXml)) {
                # Minimal default ReAgent.xml so reagentc has something to update.
                $minXml = @'
<?xml version="1.0" encoding="utf-8"?>
<WindowsRE version="2.0">
  <WinreBCD id=""/>
  <WinreLocation path="" id="0" offset="0" guid="{00000000-0000-0000-0000-000000000000}"/>
  <ImageLocation path="" id="0" offset="0" guid="{00000000-0000-0000-0000-000000000000}"/>
  <PBRImageLocation path="" id="0" offset="0" guid="{00000000-0000-0000-0000-000000000000}" index="0"/>
  <PBRCustomImageLocation path="" id="0" offset="0" guid="{00000000-0000-0000-0000-000000000000}" index="0"/>
  <InstallState state="0"/>
  <OsInstallAvailable state="0"/>
  <CustomImageAvailable state="0"/>
  <IsAutoRepairOn state="1"/>
  <WinREStaged state="0"/>
  <OperationParam path=""/>
  <OperationPermanent state="0"/>
  <OsBuildVersion path=""/>
  <OemTool state="0"/>
  <IsServer state="0"/>
  <DownlevelWinreLocation path="" id="0" offset="0" guid="{00000000-0000-0000-0000-000000000000}"/>
  <ScheduledOperation state="4"/>
</WindowsRE>
'@
                Invoke-Logged -Description 'Create recovery ReAgent.xml' -Details @{
                    Path = $targetXml
                } -ScriptBlock {
                    Set-Content -LiteralPath $targetXml -Value $minXml -Encoding ASCII -Force
                } | Out-Null
                Invoke-NativeCommandLogged -Description 'Protect recovery ReAgent.xml attributes' -Details @{
                    Path = $targetXml
                    Attributes = @('System', 'Hidden', 'ReadOnly')
                } -ScriptBlock { & cmd.exe /c "attrib +s +h +r `"$targetXml`"" } | Out-Null
            }

            Write-Host "Repair-RecoveryPartition: restored Winre.wim -> $targetWim" -ForegroundColor Green
            return (Test-Path -LiteralPath $targetWim)
        }
        catch {
            Write-Warning "Repair-RecoveryPartition: file copy failed: $_"
            return $false
        }
    }

    function EnableWinREOffline {
        # Make WinRE functional for the offline guest using only data already on the
        # broken disk. Discovers Winre.wim in <Win>\System32\Recovery or on a recovery
        # partition (mounting it temporarily if hidden), repairs a broken recovery
        # partition when an image is available elsewhere, stages Winre.wim into the
        # canonical \System32\Recovery location, then registers via reagentc.
        # Always cleans up any partitions it mounted (and restores GPT attributes on Gen2).
        # Returns $true only if reagentc reports WinRE Enabled with a non-zero BCD identifier.
        Write-Host "Registering Windows Recovery Environment (WinRE) from offline files..." -ForegroundColor Yellow
        $mountInfo = @()
        try {
            $winre = Get-WinREStatus -MountHidden
            $mountInfo = @($winre.RecoveryPartitionsMounted)

            if (-not $winre.ReagentcAvailable) {
                Write-Warning "reagentc.exe is not available on this rescue host. Cannot register WinRE offline."
                return $false
            }

            # If a recovery partition exists but has no image, AND we found one elsewhere,
            # repair the recovery partition first so we end up with the OEM-style layout.
            $brokenRecParts = @($winre.RecoveryPartitions | Where-Object { -not $_.HasImage -and $_.AccessPath })
            if ($winre.ImageFound -and $brokenRecParts.Count -gt 0) {
                $sourceWim = $winre.WinreSourcePath
                foreach ($brp in $brokenRecParts) {
                    Write-Host "Recovery partition $($brp.AccessPath) is missing Winre.wim - repairing from $sourceWim ..." -ForegroundColor Yellow
                    $repaired = Repair-RecoveryPartition -AccessPath $brp.AccessPath -SourceWinrePath $sourceWim -WindowsPath $winre.WindowsPath
                    if ($repaired) {
                        # Re-scan so PreferredDirectory now points at the recovery partition.
                        $winre = Get-WinREStatus -WindowsPath $winre.WindowsPath
                        # Re-attach the existing mount info (Get-WinREStatus without -MountHidden returns empty).
                        $winre.RecoveryPartitionsMounted = $mountInfo
                    }
                }
            }

            if (-not $winre.ImageFound) {
                Write-Warning "No usable Winre.wim was found on any partition of disk $script:DiskNumber."
                if ($winre.HiddenRecoveryPartitions -gt 0) {
                    Write-Warning "A hidden Recovery partition exists but does not contain a usable Winre.wim either."
                }
                return $false
            }

            if ([string]::IsNullOrWhiteSpace($winre.PreferredOsGuid)) {
                Write-Warning "Could not resolve the preferred OS BCD GUID required for 'reagentc /enable /osguid'."
                return $false
            }

            # Stage Winre.wim into <Win>\System32\Recovery if the source is on a recovery partition.
            # reagentc /setreimage is most reliable when /path points to a directory under /target.
            $stagedDir = $winre.PreferredDirectory
            if ($winre.PreferredIsRecoveryPart -or ($winre.PreferredDirectory -notlike "$($winre.WindowsPath)*")) {
                $maybeStaged = Stage-WinReImage -WindowsPath $winre.WindowsPath -SourceWinrePath $winre.WinreSourcePath
                if ($maybeStaged) { $stagedDir = $maybeStaged }
            }

            $windowsPath = $winre.WindowsPath
            Write-Host "reagentc /setreimage /path $stagedDir /target $windowsPath" -ForegroundColor DarkCyan
            $setResult = Invoke-NativeCommandLogged -Description 'Register offline WinRE image path' -Details @{
                Path = $stagedDir
                Target = $windowsPath
            } -ScriptBlock { & reagentc.exe /setreimage /path $stagedDir /target $windowsPath }
            if ($setResult.ExitCode -ne 0) {
                Write-Warning "reagentc /setreimage failed (exit $($setResult.ExitCode)):`n$($setResult.Output -join "`n")"
                return $false
            }

            Write-Host "reagentc /enable /osguid $($winre.PreferredOsGuid)" -ForegroundColor DarkCyan
            $enableResult = Invoke-NativeCommandLogged -Description 'Enable offline WinRE' -Details @{
                OsGuid = $winre.PreferredOsGuid
                Target = $windowsPath
            } -ScriptBlock { & reagentc.exe /enable /osguid $winre.PreferredOsGuid }
            if ($enableResult.ExitCode -ne 0) {
                Write-Warning "reagentc /enable /osguid failed (exit $($enableResult.ExitCode)):`n$($enableResult.Output -join "`n")"
                return $false
            }

            $after = Get-WinREStatus -WindowsPath $windowsPath
            $isEnabled = ($after.ReStatus -match '(?i)^enabled$') -and $after.ReBcdIdentifier -and ($after.ReBcdIdentifier -ne '00000000-0000-0000-0000-000000000000')
            if ($isEnabled) {
                Write-Host "WinRE enabled. Location: $($after.ReLocation)" -ForegroundColor Green
                Write-Host "WinRE BCD identifier: $($after.ReBcdIdentifier)" -ForegroundColor Green
                return $true
            }

            Write-Warning "WinRE registration commands completed, but WinRE still does not report as enabled.`n$($after.ReagentInfoText)"
            return $false
        }
        catch {
            Write-Error "EnableWinREOffline failed: $_"
            throw
        }
        finally {
            if ($mountInfo -and $mountInfo.Count -gt 0) {
                try { Dismount-HiddenRecoveryPartition -MountInfo $mountInfo } catch { Write-Warning "Cleanup of mounted recovery partitions failed: $_" }
            }
        }
    }

    function ResetLocalAdminPassword {
        Write-Host "Resetting local administrator account password via startup script..." -ForegroundColor Yellow
        Write-Host "Please provide the new credentials (username = existing local admin account, no .\ prefix):" -ForegroundColor Yellow
        $Credential = Get-Credential

        $Username = $Credential.GetNetworkCredential().UserName
        $Password = $Credential.GetNetworkCredential().Password

        Invoke-WithHive 'SYSTEM' {
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\resetpwd.cmd" -Type String -Force

            $resetScript = @"
@echo off
net user Username "Password" /Y
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\Temp\resetpwd.cmd > NUL
"@
            Ensure-GuestTempDir
            New-Item-Logged -Path "$script:WinDriveLetter\Temp" -Name "resetpwd.cmd" -ItemType File -Value $resetScript.Trim().Replace("Username", $Username).Replace("Password", $Password) -Force -RedactValue

            Write-Host "Password reset script placed. The password for '$Username' will be changed on next VM boot." -ForegroundColor Green
        }
    }

    function DisableThirdPartyDrivers {
        if (-not (Confirm-CriticalOperation -Operation 'Disable Third-Party Drivers (-DisableThirdPartyDrivers)' -Details @"
Sets Start=4 (Disabled) for all non-Microsoft Boot and System kernel drivers.
Revert commands are printed after completion, or use -EnableThirdPartyDrivers.
"@)) { return }

        Write-Host "Enumerating and disabling non-Microsoft kernel drivers..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            & {
                $SystemRoot = Get-SystemRootPath
                $ServicesRoot = "$SystemRoot\Services"

                # Kernel-mode start types: 0=Boot, 1=System, 2=Auto, 3=Manual, 4=Disabled
                # Target Boot(0) and System(1) drivers that are third-party

                # Azure-safe vendors: drivers from these companies may be required on Azure
                # VMs (accelerated networking, GPU, NVMe, storage). Do NOT disable them.
                $azureSafeVendors = @(
                    'Mellanox',                  # Accelerated networking (MANA/mlx5/ConnectX)
                    'NVIDIA',                    # GPU compute (NCv3, NDv2, etc.)
                    'Intel',                     # LPSS GPIO/I2C, iaStorAV, NVMe
                    'Advanced Micro Devices',    # CPU microcode, storage
                    'AMD',                       # CPU microcode, storage (short name variant)
                    'Chelsio',                   # iWARP RDMA (HPC SKUs)
                    'Marvell',                   # NVMe controllers on some hardware
                    'Broadcom'                   # Network/storage (Emulex rebranded)
                )
                $azureSafePattern = ($azureSafeVendors | ForEach-Object { [regex]::Escape($_) }) -join '|'

                $disabled = @()
                $skippedAzure = @()
                Get-ChildItem $ServicesRoot -ErrorAction SilentlyContinue | ForEach-Object {
                    $svcPath = $_.PSPath
                    $props = Get-ItemProperty -Path $svcPath -ErrorAction SilentlyContinue
                    # Only kernel/filesystem drivers (Type 1=kernel, 2=filesystem)
                    if ($props.Type -notin @(1, 2)) { return }
                    # Only Boot and System start drivers
                    if ($props.Start -notin @(0, 1)) { return }
                    # Skip if already disabled
                    if ($props.Start -eq 4) { return }

                    $imagePathRaw = $props.ImagePath
                    if (-not $imagePathRaw) { return }
                    $imagePath = Resolve-GuestImagePath $imagePathRaw

                    # Read the binary to check the company name in version info.
                    # If the binary is missing, treat the driver as third-party - a missing
                    # Boot/System binary will cause a BSOD on next boot regardless of vendor.
                    $isMicrosoft = $false
                    $isAzureSafe = $false
                    $binaryMissing = $false
                    $vendorName = ''
                    if (Test-Path $imagePath) {
                        $vi = (Get-Item $imagePath -ErrorAction SilentlyContinue).VersionInfo
                        $vendorName = if ($vi -and $vi.CompanyName) { $vi.CompanyName.Trim() } else { '' }
                        if ($vendorName -match 'Microsoft') { $isMicrosoft = $true }
                        elseif ($vendorName -and $vendorName -match $azureSafePattern) { $isAzureSafe = $true }
                    }
                    else {
                        $binaryMissing = $true   # missing binary -> will BSOD -> must disable
                    }

                    if ($isAzureSafe -and -not $binaryMissing) {
                        $skippedAzure += [PSCustomObject]@{ Service = $_.PSChildName; Vendor = $vendorName }
                        return
                    }

                    if (-not $isMicrosoft) {
                        $svcName = $_.PSChildName
                        $tag = if ($binaryMissing) { ' [binary missing - will BSOD on boot]' } else { '' }
                        Write-Host "  Disabling: $svcName$tag  ($imagePathRaw)" -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value 4 -Type DWord -Force
                        $disabled += [PSCustomObject]@{ Service = $svcName; ImagePath = $imagePathRaw; PreviousStart = $props.Start }
                    }
                }

                if ($disabled.Count -eq 0) {
                    Write-Host "No non-Microsoft Boot/System drivers found to disable." -ForegroundColor Green
                }
                else {
                    $backupPath = Get-ThirdPartyDriverStartBackupPath
                    $backupByService = @{}
                    if (Test-Path -LiteralPath $backupPath) {
                        try {
                            $rawBackup = Get-Content -LiteralPath $backupPath -Raw -ErrorAction Stop
                            if (-not [string]::IsNullOrWhiteSpace($rawBackup)) {
                                foreach ($entry in (ConvertFrom-ThirdPartyDriverStartBackupJson -Json $rawBackup)) {
                                    if ($entry.Service -and $null -ne $entry.PreviousStart) {
                                        try { $previousStart = [int]$entry.PreviousStart }
                                        catch { continue }
                                        if ($previousStart -lt 0 -or $previousStart -gt 4) { continue }
                                        $backupByService[[string]$entry.Service] = [PSCustomObject]@{
                                            Service       = [string]$entry.Service
                                            ImagePath     = [string]$entry.ImagePath
                                            PreviousStart = $previousStart
                                            DisabledAt    = [string]$entry.DisabledAt
                                        }
                                    }
                                }
                            }
                        }
                        catch {
                            Write-Warning "Could not read existing third-party driver Start backup at $backupPath. It will be replaced. $_"
                            $backupByService = @{}
                        }
                    }

                    $timestamp = (Get-Date).ToString('o')
                    foreach ($d in $disabled) {
                        $backupByService[$d.Service] = [PSCustomObject]@{
                            Service       = $d.Service
                            ImagePath     = $d.ImagePath
                            PreviousStart = [int]$d.PreviousStart
                            DisabledAt    = $timestamp
                        }
                    }
                    $backupRows = @($backupByService.GetEnumerator() | Sort-Object Name | ForEach-Object { $_.Value })
                    $backupJson = ConvertTo-Json -InputObject @($backupRows) -Depth 4
                    Set-Content -LiteralPath $backupPath -Value $backupJson -Encoding UTF8 -Force

                    Write-Host "`nDisabled $($disabled.Count) third-party driver(s)." -ForegroundColor Green
                    Write-Host "Saved previous driver Start values to $backupPath" -ForegroundColor Green
                    Write-Host "`n--- TO RE-ENABLE (run -EnableThirdPartyDrivers or run on the VM after recovery) ---" -ForegroundColor Cyan
                    foreach ($d in $disabled) {
                        $livePath = "HKLM:\SYSTEM\CurrentControlSet\Services\$($d.Service)"
                        Write-Host "Set-ItemProperty -Path '$livePath' -Name Start -Value $($d.PreviousStart) -Type DWord -Force" -ForegroundColor White
                    }
                    Write-Host "----------------------------------------------------`n" -ForegroundColor Cyan
                }

                if ($skippedAzure.Count -gt 0) {
                    Write-Host "  Azure-safe drivers kept enabled (may be needed for accelerated networking/GPU/NVMe):" -ForegroundColor DarkCyan
                    foreach ($s in $skippedAzure) {
                        Write-Host "    $($s.Service)  ($($s.Vendor))" -ForegroundColor DarkCyan
                    }
                    Write-Host ""
                }
            }
        }
    }

    function Get-PeCertificateTableSize {
        # Returns the byte size of the PE certificate table (data directory entry 4,
        # IMAGE_DIRECTORY_ENTRY_SECURITY). Zero means the image carries NO embedded
        # Authenticode signature, so its only possible route to trust is a catalog.
        # Most Windows inbox drivers are in that category - filecrypt.sys and
        # npsvctrig.sys both report 0 - which is why a damaged catalog store makes
        # byte-for-byte correct Microsoft drivers fail verification.
        # Returns -1 when the file cannot be parsed as a PE image.
        param([Parameter(Mandatory)][string]$FilePath)

        $fs = $null
        try {
            $fs = [System.IO.File]::Open($FilePath, [System.IO.FileMode]::Open,
                [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $br = New-Object System.IO.BinaryReader($fs)

            if ($fs.Length -lt 0x40) { return -1 }
            $fs.Position = 0x3C
            $peOffset = $br.ReadInt32()
            if ($peOffset -le 0 -or ($peOffset + 0x18) -ge $fs.Length) { return -1 }

            $fs.Position = $peOffset
            if ($br.ReadUInt32() -ne 0x00004550) { return -1 }      # 'PE\0\0'

            $fs.Position = $peOffset + 0x18                          # optional header
            $magic = $br.ReadUInt16()
            $ddOffset = switch ($magic) {
                0x10B { $peOffset + 0x18 + 96 }                      # PE32
                0x20B { $peOffset + 0x18 + 112 }                     # PE32+
                default { -1 }
            }
            if ($ddOffset -lt 0) { return -1 }

            $secOffset = $ddOffset + (4 * 8)                         # entry 4, 8 bytes each
            if (($secOffset + 8) -gt $fs.Length) { return -1 }
            $fs.Position = $secOffset
            $null = $br.ReadUInt32()                                 # RVA (unused)
            return [int]$br.ReadUInt32()                             # Size
        }
        catch { return -1 }
        finally { if ($fs) { $fs.Dispose() } }
    }

    function GetCatalogStoreReport {
        # Reports the health of the offline guest's Authenticode catalog store, then
        # names every Boot/System-start driver whose ability to load depends on it.
        #
        # Why this exists: boot-time Code Integrity parses the raw .cat files under
        #   \Windows\System32\CatRoot\{F750E6C3-38EE-11D1-85E5-00C04FC295EE}
        # It does NOT use CatRoot2, which is a CryptSvc database that only exists once
        # the OS is running - so the common "delete CatRoot2" advice cannot fix a boot
        # failure. A driver with an empty PE certificate table has no embedded
        # signature to fall back on, so if its catalog is missing or damaged the load
        # fails with STATUS_INVALID_IMAGE_HASH (0xC0000428) even though the binary is
        # byte-for-byte correct. When that driver also carries ErrorControl=3
        # (Critical) the failure aborts boot -> bugcheck 0x5A CRITICAL_SERVICE_FAILED.
        #
        # The tell-tale signature of a store-level fault is MULTIPLE unrelated inbox
        # drivers failing the same way: replacing binaries one at a time just moves the
        # bugcheck to the next driver in load order.
        param([switch]$IncludeHealthy)

        Write-Host "`nBuilding offline catalog store report..." -ForegroundColor Cyan

        $storePath = Get-OfflineCatalogStorePath
        Write-Host "`n=== Catalog store ===" -ForegroundColor Cyan
        Write-Host "  Path: $storePath" -ForegroundColor Gray

        if (-not $storePath -or -not (Test-Path -LiteralPath $storePath)) {
            Write-Host "  [CRITICAL] Catalog store directory does not exist." -ForegroundColor Red
            Write-Host "  Every catalog-signed driver will fail Code Integrity at boot." -ForegroundColor Red
            return
        }

        $cats = @(Get-ChildItem -LiteralPath $storePath -Filter '*.cat' -File -ErrorAction SilentlyContinue)
        $totalBytes = ($cats | Measure-Object -Property Length -Sum).Sum
        $zeroLen = @($cats | Where-Object { $_.Length -eq 0 })
        $truncated = @($cats | Where-Object { $_.Length -gt 0 -and $_.Length -lt 512 })

        Write-Host ("  Catalogs      : {0:N0}" -f $cats.Count) -ForegroundColor Gray
        Write-Host ("  Total size    : {0:N1} MB" -f ($totalBytes / 1MB)) -ForegroundColor Gray

        $zeroColor = if ($zeroLen.Count -gt 0) { 'Red' } else { 'Gray' }
        Write-Host ("  Zero-length   : {0:N0}" -f $zeroLen.Count) -ForegroundColor $zeroColor
        $truncColor = if ($truncated.Count -gt 0) { 'Yellow' } else { 'Gray' }
        Write-Host ("  Suspiciously small (<512B): {0:N0}" -f $truncated.Count) -ForegroundColor $truncColor

        # A healthy Server 2016/2019/2022 store holds thousands of catalogs. A store
        # with only a handful has been wiped or partially restored.
        if ($cats.Count -eq 0) {
            Write-Host "  [CRITICAL] Catalog store is EMPTY." -ForegroundColor Red
        }
        elseif ($cats.Count -lt 200) {
            Write-Host "  [CRITICAL] Catalog count is far below a healthy install (expect thousands)." -ForegroundColor Red
        }
        foreach ($z in ($zeroLen | Select-Object -First 10)) {
            Write-Host "    zero-length: $($z.Name)" -ForegroundColor Red
        }

        # Force the index + reference sample to run so we get the store verdict.
        $state = Initialize-OfflineCatalogIndex
        Write-Host "`n=== Store verdict ===" -ForegroundColor Cyan
        Write-Host "  State  : $state" -ForegroundColor $(if ($state -eq 'Usable') { 'Green' } else { 'Red' })
        if ($script:OfflineCatalogStoreSummary) {
            Write-Host "  Detail : $($script:OfflineCatalogStoreSummary)" -ForegroundColor Gray
        }

        if ($state -eq 'Unusable') {
            Write-Host "  The store exists but cannot resolve well-known inbox binaries." -ForegroundColor Red
            Write-Host "  That is the fingerprint of a DAMAGED CATALOG STORE, not damaged drivers." -ForegroundColor Red
        }
        elseif ($state -eq 'Disabled') {
            Write-Host "  Catalog verification was disabled with -SkipCatalogVerification." -ForegroundColor Yellow
            return
        }
        elseif ($state -ne 'Usable') {
            Write-Host "  Store could not be indexed on this repair host; results below are advisory." -ForegroundColor Yellow
        }

        # ---- which Boot/System drivers actually depend on this store? -------------
        Write-Host "`n=== Boot/System drivers that depend on the catalog store ===" -ForegroundColor Cyan

        $rows = [System.Collections.Generic.List[PSCustomObject]]::new()
        Invoke-WithHive 'SYSTEM' {
            & {
                $SystemRoot = Get-SystemRootPath
                Get-ChildItem "$SystemRoot\Services" -ErrorAction SilentlyContinue | ForEach-Object {
                    $props = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
                    if (-not $props) { return }
                    if ($null -eq $props.Start -or $null -eq $props.Type) { return }
                    if ([int]$props.Start -notin @(0, 1)) { return }
                    if ([int]$props.Type -notin @(1, 2, 4, 8)) { return }
                    if (-not $props.ImagePath) { return }

                    $imgPath = Resolve-GuestImagePath $props.ImagePath
                    $exists = Test-Path -LiteralPath $imgPath
                    $certSize = if ($exists) { Get-PeCertificateTableSize -FilePath $imgPath } else { -1 }
                    $inStore = $false
                    if ($exists) {
                        $member = Test-OfflineCatalogMembership -FilePath $imgPath
                        $inStore = [bool]$member.Found
                    }

                    $rows.Add([PSCustomObject]@{
                            Name         = $_.PSChildName
                            StartVal     = [int]$props.Start
                            ErrorControl = if ($null -ne $props.ErrorControl) { [int]$props.ErrorControl } else { 0 }
                            Image        = Split-Path $imgPath -Leaf
                            Exists       = $exists
                            CertSize     = $certSize
                            InStore      = $inStore
                        })
                }
            }
        }

        # Catalog-dependent = present, parseable PE, and no embedded signature.
        $catalogDependent = @($rows | Where-Object { $_.Exists -and $_.CertSize -eq 0 })
        $unresolved = @($catalogDependent | Where-Object { -not $_.InStore })
        $bootFatal = @($unresolved | Where-Object { $_.ErrorControl -ge 2 })

        Write-Host ("  Boot/System drivers examined : {0}" -f $rows.Count) -ForegroundColor Gray
        Write-Host ("  Catalog-dependent (no embedded signature) : {0}" -f $catalogDependent.Count) -ForegroundColor Gray
        $unresColor = if ($unresolved.Count -gt 0) { 'Red' } else { 'Green' }
        Write-Host ("  Not resolvable in this store : {0}" -f $unresolved.Count) -ForegroundColor $unresColor
        Write-Host ("  ...of which ErrorControl>=2 (would abort boot) : {0}" -f $bootFatal.Count) -ForegroundColor $unresColor

        $show = if ($IncludeHealthy) { $rows } else { $unresolved }
        if ($show.Count -gt 0) {
            Write-Host ""
            Write-Host ("  {0,-28} {1,-7} {2,-6} {3,-9} {4,-8} {5}" -f `
                    'Driver', 'Start', 'ErCtl', 'Embedded', 'InStore', 'Image') -ForegroundColor DarkGray
            foreach ($r in ($show | Sort-Object StartVal, Name)) {
                $startLabel = if ($r.StartVal -eq 0) { 'Boot' } else { 'System' }
                $errLabel = switch ($r.ErrorControl) {
                    3 { 'CRIT' } 2 { 'SEV' } 1 { 'NORM' } default { 'IGN' }
                }
                $embedded = if ($r.CertSize -gt 0) { "$($r.CertSize)B" } elseif ($r.CertSize -eq 0) { 'none' } else { 'n/a' }
                $inStore = if ($r.InStore) { 'yes' } else { 'NO' }
                $color = if (-not $r.InStore -and $r.CertSize -eq 0) {
                    if ($r.ErrorControl -ge 2) { 'Red' } else { 'Yellow' }
                }
                else { 'Gray' }
                Write-Host ("  {0,-28} {1,-7} {2,-6} {3,-9} {4,-8} {5}" -f `
                        $r.Name, $startLabel, $errLabel, $embedded, $inStore, $r.Image) -ForegroundColor $color
            }
        }

        # ---- interpretation -------------------------------------------------------
        Write-Host "`n=== Interpretation ===" -ForegroundColor Cyan
        if ($state -eq 'Usable' -and $unresolved.Count -eq 0) {
            Write-Host "  Catalog store is healthy and every catalog-dependent boot driver resolves." -ForegroundColor Green
            Write-Host "  A 0xC0000428 boot failure is NOT explained by the catalog store." -ForegroundColor Green
        }
        elseif ($unresolved.Count -ge 3 -or $state -eq 'Unusable') {
            Write-Host "  MULTIPLE unrelated Microsoft inbox drivers cannot be verified against this" -ForegroundColor Red
            Write-Host "  store. That is a STORE-level fault. Replacing individual .sys files will" -ForegroundColor Red
            Write-Host "  not help - the bugcheck simply moves to the next driver in load order." -ForegroundColor Red
            Write-Host ""
            Write-Host "  Repair options, most surgical first:" -ForegroundColor Yellow
            Write-Host "    1. Restore the catalog store from a same-build donor (see -RepairCatalogStore)." -ForegroundColor Yellow
            Write-Host "    2. DISM /Image:<mount> /Cleanup-Image /RestoreHealth /Source:<matching WIM>" -ForegroundColor Yellow
            Write-Host "    3. sfc /scannow /offbootdir=<win> /offwindir=<win>\Windows" -ForegroundColor Yellow
            Write-Host "    4. Reinstall the owning LCU offline (DISM /Add-Package)." -ForegroundColor Yellow
            Write-Host "  Do NOT bother deleting CatRoot2 - it is not consulted during boot." -ForegroundColor DarkGray
        }
        else {
            Write-Host "  A small number of drivers did not resolve. That can be legitimate (an" -ForegroundColor Yellow
            Write-Host "  out-of-band or third-party driver may be covered by its own catalog)." -ForegroundColor Yellow
            Write-Host "  Treat as store-level corruption only if the failures are inbox components." -ForegroundColor Yellow
        }
    }

    function RepairCatalogStore {
        # Merges a same-build donor's Authenticode catalogs into the offline guest's
        # store to fix a 0xC0000428 boot failure caused by store-level damage rather
        # than by any individual driver.
        #
        # This is safe in a way that replacing drivers is not. Catalogs are additive
        # and each one carries its own Microsoft signature, so adding one can only
        # widen the set of hashes boot code integrity can resolve. Nothing already
        # present is invalidated, and an existing catalog is never overwritten.
        param(
            [Parameter(Mandatory = $true)][string]$DonorPath,
            [switch]$Force
        )

        Write-Host "`nRepairing offline catalog store..." -ForegroundColor Cyan

        if (-not (Initialize-OfflineCatalogNativeType)) {
            Write-Error "The wintrust catalog APIs are unavailable on this repair host; cannot merge a donor store."
            return
        }

        $storePath = Get-OfflineCatalogStorePath
        if (-not $storePath) {
            Write-Error "Could not resolve the guest catalog store path (no Windows volume detected)."
            return
        }

        # Accept any sensible way of naming the donor: the GUID folder itself, a
        # CatRoot folder, a System32 folder, a \Windows folder, or a mounted volume.
        $donorCandidates = @(
            $DonorPath
            (Join-Path $DonorPath $script:OfflineCatalogGuid)
            (Join-Path $DonorPath "CatRoot\$($script:OfflineCatalogGuid)")
            (Join-Path $DonorPath "System32\CatRoot\$($script:OfflineCatalogGuid)")
            (Join-Path $DonorPath "Windows\System32\CatRoot\$($script:OfflineCatalogGuid)")
        )
        $donorStore = $null
        $donorFiles = @()
        foreach ($candidate in $donorCandidates) {
            if (-not (Test-Path -LiteralPath $candidate -PathType Container)) { continue }
            $found = @(Get-ChildItem -LiteralPath $candidate -Filter '*.cat' -File -ErrorAction SilentlyContinue)
            if ($found.Count -gt 0) { $donorStore = $candidate; $donorFiles = $found; break }
        }
        if (-not $donorStore) {
            Write-Error "No catalogs (*.cat) found at or under '$DonorPath'. Point -RepairCatalogStore at a same-build donor's CatRoot, its {GUID} subfolder, or the donor's mounted Windows volume."
            return
        }

        Write-Host "  Donor store : $donorStore" -ForegroundColor Gray
        Write-Host "  Guest store : $storePath" -ForegroundColor Gray
        Write-Host ("  Donor catalogs: {0:N0}" -f $donorFiles.Count) -ForegroundColor Gray

        # ---- record the guest's condition before touching anything -----------------
        $beforeState = Initialize-OfflineCatalogIndex
        $beforeSummary = $script:OfflineCatalogStoreSummary
        if ($beforeState -eq 'Disabled') {
            Write-Error "-SkipCatalogVerification is in effect, so the store cannot be assessed or repaired. Re-run without it."
            return
        }

        # ---- prove the donor actually matches this guest ---------------------------
        # A donor from the wrong build indexes perfectly well but resolves none of the
        # guest's own binaries, and merging it would add thousands of useless files
        # while leaving the machine just as unbootable.
        Write-Host "  Indexing donor store..." -ForegroundColor DarkGray
        $donorStats = [int[]]@(0, 0)
        try {
            $donorIndex = [RepairAzVMDisk.CatalogNative]::BuildIndex([string[]]($donorFiles.FullName), $donorStats)
        }
        catch {
            Write-Error "Donor catalog store could not be indexed: $($_.Exception.Message)"
            return
        }

        $sampleFiles = @(Get-CatalogReferenceSampleFile)
        $donorResolved = 0
        foreach ($samplePath in $sampleFiles) {
            foreach ($tag in (Get-AuthenticodeReferenceTag -FilePath $samplePath)) {
                if ($donorIndex.ContainsKey($tag)) { $donorResolved++; break }
            }
        }
        $donorRatio = if ($sampleFiles.Count -gt 0) { $donorResolved / $sampleFiles.Count } else { 0 }
        Write-Host ("  Donor resolves {0}/{1} of this guest's reference binaries ({2:P0}), {3:N0} hashes." -f `
                $donorResolved, $sampleFiles.Count, $donorRatio, $donorIndex.Count) -ForegroundColor Gray

        if ($sampleFiles.Count -ge 6 -and $donorRatio -lt 0.6) {
            Write-Host ""
            Write-Host "  This donor does not match the guest's build." -ForegroundColor Red
            Write-Host "  Its catalogs do not publish the hashes of this guest's own inbox binaries," -ForegroundColor Red
            Write-Host "  so merging it would add files without making the guest bootable." -ForegroundColor Red
            Write-Host "  Use a donor at the same OS build AND patch level (UBR) as the guest." -ForegroundColor Yellow
            if (-not $Force) {
                Write-Error "Refusing to merge a mismatched donor catalog store. Re-run with -Force to override."
                return
            }
            Write-Host "  -Force specified; merging anyway." -ForegroundColor Yellow
        }

        # ---- work out what is actually missing -------------------------------------
        # Same name + same content is already present. Same name + different content
        # is kept side by side under a suffixed name rather than overwritten, because
        # discarding a catalog can only ever reduce coverage.
        $existing = @{}
        foreach ($f in @(Get-ChildItem -LiteralPath $storePath -Filter '*.cat' -File -ErrorAction SilentlyContinue)) {
            $existing[$f.Name] = $f
        }

        $toCopy = [System.Collections.Generic.List[object]]::new()
        foreach ($d in $donorFiles) {
            $target = Join-Path $storePath $d.Name
            if ($existing.ContainsKey($d.Name)) {
                $sameSize = ($existing[$d.Name].Length -eq $d.Length)
                if ($sameSize -and
                    (Get-FileHash -LiteralPath $existing[$d.Name].FullName -Algorithm SHA256).Hash -eq
                    (Get-FileHash -LiteralPath $d.FullName -Algorithm SHA256).Hash) {
                    continue
                }
                $target = Join-Path $storePath ("{0}.donor{1}" -f [IO.Path]::GetFileNameWithoutExtension($d.Name), [IO.Path]::GetExtension($d.Name))
                if (Test-Path -LiteralPath $target) { continue }
            }
            $toCopy.Add([PSCustomObject]@{ Source = $d.FullName; Target = $target })
        }

        if ($toCopy.Count -eq 0) {
            Write-Host "  The guest store already contains every catalog this donor has; nothing to merge." -ForegroundColor Yellow
            Write-Host "  The damage is therefore not missing catalogs. Use DISM /RestoreHealth with a matching source." -ForegroundColor Yellow
            return
        }

        Write-Host ("  Catalogs to add: {0:N0}" -f $toCopy.Count) -ForegroundColor Gray

        # ---- copy ------------------------------------------------------------------
        # The store directory is taken once rather than per file. At a few thousand
        # catalogs, per-file ownership changes dominate the runtime.
        $originalSddl = ''
        $addedPaths = [System.Collections.Generic.List[string]]::new()
        $failures = [System.Collections.Generic.List[string]]::new()
        try {
            $originalSddl = Grant-ProtectedPathAccess -Path $storePath
            # Logged as one action rather than per catalog. A merge routinely adds a few
            # thousand files, and an action log with a line for each would bury every
            # other decision the run made; the file list lives in Details, which is what
            # a revert needs anyway - deleting exactly the catalogs this run added.
            #
            # The tallies are collections, not integers, because the scriptblock runs in
            # a child scope: '$n++' there would increment a copy and leave the outer
            # counter at zero, which would then trip the "nothing was written" guard.
            Invoke-Logged -Description 'Merge donor catalogs into the guest catalog store' -Details @{
                Operation  = 'RepairCatalogStore'
                StorePath  = $storePath
                Candidates = $toCopy.Count
                AddedPaths = $addedPaths
            } -ScriptBlock {
                foreach ($item in $toCopy) {
                    try {
                        Copy-Item -LiteralPath $item.Source -Destination $item.Target -Force -ErrorAction Stop
                        $addedPaths.Add($item.Target)
                    }
                    catch {
                        $failures.Add("$(Split-Path $item.Target -Leaf): $($_.Exception.Message)")
                        if ($failures.Count -le 5) {
                            Write-Host "    Failed to add $(Split-Path $item.Target -Leaf): $($_.Exception.Message)" -ForegroundColor DarkYellow
                        }
                    }
                }
            } | Out-Null
        }
        finally {
            if ($originalSddl) { Restore-ProtectedPathAccess -Path $storePath -Sddl $originalSddl }
        }

        $copied = $addedPaths.Count
        $failed = $failures.Count
        $copyColor = if ($failed -gt 0) { 'Yellow' } else { 'Green' }
        Write-Host ("  Added {0:N0} catalogs ({1:N0} failed)." -f $copied, $failed) -ForegroundColor $copyColor
        if ($copied -eq 0) {
            Write-Error "No catalogs could be written to the guest store; it has not been changed."
            return
        }

        # ---- re-assess -------------------------------------------------------------
        # Every cached verdict was formed against the old store and is now stale.
        $script:OfflineCatalogState = 'NotBuilt'
        $script:OfflineCatalogIndex = $null
        $script:OfflineCatalogFiles = @()
        $script:OfflineCatalogTrustCache = @{}
        $script:TrustResultCache = @{}

        $afterState = Initialize-OfflineCatalogIndex
        $afterSummary = $script:OfflineCatalogStoreSummary

        Write-Host "`n=== Result ===" -ForegroundColor Cyan
        Write-Host ("  Before : {0} - {1}" -f $beforeState, $beforeSummary) -ForegroundColor Gray
        $afterColor = if ($afterState -eq 'Usable') { 'Green' } else { 'Yellow' }
        Write-Host ("  After  : {0} - {1}" -f $afterState, $afterSummary) -ForegroundColor $afterColor

        Write-ActionLog -Event 'ActionExecuted' -Details @{
            Description   = 'RepairCatalogStore'
            DonorStore    = $donorStore
            GuestStore    = $storePath
            CatalogsAdded = $copied
            CatalogsFailed = $failed
            StateBefore   = $beforeState
            StateAfter    = $afterState
            SummaryAfter  = $afterSummary
            Success       = ($afterState -eq 'Usable')
        }

        Write-Host ""
        if ($afterState -eq 'Usable' -and $beforeState -ne 'Usable') {
            Write-Host "  The catalog store now resolves this guest's own inbox binaries." -ForegroundColor Green
            Write-Host "  Re-run -GetCatalogStoreReport to confirm no boot driver is left unresolvable," -ForegroundColor Green
            Write-Host "  then boot the VM." -ForegroundColor Green
        }
        elseif ($afterState -eq 'Usable') {
            Write-Host "  The store was already usable and is now more complete." -ForegroundColor Green
            Write-Host "  Re-run -GetCatalogStoreReport to check the per-driver picture." -ForegroundColor Green
        }
        else {
            Write-Host "  The store still cannot resolve this guest's inbox binaries." -ForegroundColor Yellow
            Write-Host "  The donor was accepted but is not the right build, or the damage is not" -ForegroundColor Yellow
            Write-Host "  confined to CatRoot. Fall back to DISM /Cleanup-Image /RestoreHealth with a" -ForegroundColor Yellow
            Write-Host "  matching WIM, or reinstall the owning LCU offline." -ForegroundColor Yellow
        }
        Write-Host "  Nothing that was already in the store was overwritten or removed." -ForegroundColor DarkGray
    }

    function GetServicesReport {
        param(
            [switch]$IncludeServices,
            [switch]$IssuesOnly
        )
        # Enumerates every entry under Services in the active ControlSet and produces a
        # grouped, colour-coded report. Each row shows:
        #   Name | [Pres] | ErCtl | Vendor | ImagePath
        # By default only kernel/filesystem drivers are shown (Type 1/2/4/8).
        # Pass -IncludeServices to include Win32 services as well.
        # Pass -IssuesOnly to suppress healthy Microsoft rows and display only:
        #   - Missing binaries
        #   - Non-Microsoft vendors
        #   - ErrorControl >= 2 (Severe/Critical)
        # Rows are sorted by Start value (Boot -> System -> Automatic -> Manual -> Disabled)
        # then alphabetically within each group.

        $reportLabel = if ($IncludeServices) { 'services/drivers' } else { 'drivers' }
        $modeLabel = if ($IssuesOnly) { ' (issues only)' } else { '' }
        Write-Host "`nBuilding offline $reportLabel report$modeLabel..." -ForegroundColor Cyan
        Invoke-WithHive 'SYSTEM' {
            & {
                $SystemRoot = Get-SystemRootPath
                $ServicesRoot = "$SystemRoot\Services"

                $startNames = @{ 0 = 'Boot'; 1 = 'System'; 2 = 'Automatic'; 3 = 'Manual'; 4 = 'Disabled' }
                $typeNames = @{ 1 = 'KernelDriver'; 2 = 'FileSystemDriver'; 4 = 'Adapter'; 8 = 'Recognizer';
                    16 = 'Win32Own'; 32 = 'Win32Share'; 256 = 'Interactive' 
                }

                $rows = [System.Collections.Generic.List[PSCustomObject]]::new()

                Get-ChildItem $ServicesRoot -ErrorAction SilentlyContinue | ForEach-Object {
                    $props = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
                    if (-not $props) { return }

                    $startVal = $props.Start
                    $typeVal = $props.Type
                    # Skip entries with no Start or no Type (e.g. sub-keys that are not real services)
                    if ($null -eq $startVal -or $null -eq $typeVal) { return }

                    $startLabel = if ($startNames.ContainsKey([int]$startVal)) { $startNames[[int]$startVal] } else { "Unknown($startVal)" }
                    $typeLabel = if ($typeNames.ContainsKey([int]$typeVal)) { $typeNames[[int]$typeVal] } else { "Type($typeVal)" }

                    $imgRaw = $props.ImagePath
                    $imgPath = $null
                    $present = $null    # $null = no ImagePath registered
                    $vendor = 'N/A'
                    $trustState = ''
                    $trustBad = $false

                    if ($imgRaw) {
                        $imgPath = Resolve-GuestImagePath $imgRaw

                        if (Test-Path $imgPath) {
                            $present = $true
                            $vi = (Get-Item $imgPath -ErrorAction SilentlyContinue).VersionInfo
                            $vendor = if ($vi -and $vi.CompanyName) { $vi.CompanyName.Trim() } else { '(no version info)' }
                            # Cryptographic trust for kernel drivers only - a Microsoft
                            # CompanyName on a tampered image must not hide the failure.
                            if ([int]$typeVal -in @(1, 2, 4, 8)) {
                                $svcSig = Test-MicrosoftSignature -FilePath $imgPath
                                $trustState = $svcSig.TrustState
                                $trustBad = [bool]$svcSig.IsHardFailure
                                if ($trustBad) { $vendor = "!TRUST FAIL! $vendor" }
                            }
                        }
                        else {
                            $present = $false
                            $vendor = '(binary missing)'
                        }
                    }

                    $rows.Add([PSCustomObject]@{
                            Name          = $_.PSChildName
                            Start         = $startLabel
                            StartVal      = [int]$startVal
                            TypeVal       = [int]$typeVal
                            Type          = $typeLabel
                            Group         = if ($props.Group) { $props.Group } else { '' }
                            Vendor        = $vendor
                            TrustState    = $trustState
                            TrustBad      = $trustBad
                            BinaryPresent = $present
                            ImagePath     = if ($imgRaw) { $imgRaw } else { '' }
                            ErrorControl  = if ($null -ne $props.ErrorControl) { [int]$props.ErrorControl } else { $null }
                        })
                }

                # Filter to drivers only unless -IncludeServices was given.
                # Driver types: 1=KernelDriver, 2=FileSystemDriver, 4=Adapter, 8=Recognizer
                if (-not $IncludeServices) {
                    $rows = [System.Collections.Generic.List[PSCustomObject]]($rows | Where-Object { $_.TypeVal -in @(1, 2, 4, 8) })
                }

                # Filter to issue rows only when -IssuesOnly is given.
                # An issue row is one that warrants attention:
                #   - Missing binary (any vendor)
                #   - Failed cryptographic trust (any vendor, including Microsoft-branded)
                #   - Non-Microsoft vendor with a binary present
                #   - ErrorControl >= 2 (Severe/Critical) AND non-Microsoft vendor
                #     (Microsoft inbox drivers legitimately carry CRIT/Sev ErrorControl - that is normal)
                if ($IssuesOnly) {
                    $rows = [System.Collections.Generic.List[PSCustomObject]]($rows | Where-Object {
                            # A tampered driver keeps its Microsoft CompanyName, so trust
                            # failure must be evaluated before the vendor suppression.
                            $isMsVendor = (-not $_.TrustBad) -and $_.Vendor -match 'Microsoft'
                            $_.TrustBad -or
                            $_.BinaryPresent -eq $false -or
                            ($_.BinaryPresent -eq $true -and -not $isMsVendor) -or
                            ($null -ne $_.ErrorControl -and $_.ErrorControl -ge 2 -and -not $isMsVendor)
                        })
                }

                if ($rows.Count -eq 0) {
                    $noneMsg = if ($IssuesOnly) { "No issues found in the offline $reportLabel ControlSet - all entries look healthy." } else { "No $reportLabel entries found in the offline ControlSet." }
                    Write-Host "  $noneMsg" -ForegroundColor $(if ($IssuesOnly) { 'Green' } else { 'DarkGray' })
                    return
                }

                # Group by Start value, then sort alphabetically within each group
                $grouped = $rows | Sort-Object StartVal, Name

                $currentStart = $null
                foreach ($r in $grouped) {
                    if ($r.Start -ne $currentStart) {
                        $currentStart = $r.Start
                        $headerColor = switch ($r.Start) {
                            'Boot' { 'Red' }
                            'System' { 'Yellow' }
                            'Automatic' { 'Cyan' }
                            'Manual' { 'White' }
                            'Disabled' { 'DarkGray' }
                            default { 'Gray' }
                        }
                        Write-Host "`n  == $($r.Start.ToUpper()) =========================================" -ForegroundColor $headerColor
                        Write-Host ("  {0,-30} {1,-28} {2,-6} {3,-6} {4}" -f 'Name', 'Vendor', '[Pres]', 'ErCtl', 'ImagePath') -ForegroundColor DarkGray
                        Write-Host ("  {0,-30} {1,-28} {2,-6} {3,-6} {4}" -f ('-' * 30), ('-' * 28), '------', '------', ('-' * 40)) -ForegroundColor DarkGray
                    }

                    # Colour logic: trust failure or missing binary = Red, non-Microsoft = Yellow, Microsoft = Green, N/A = Gray
                    $isMicrosoft = (-not $r.TrustBad) -and $r.Vendor -match 'Microsoft'
                    $isMissing = $r.BinaryPresent -eq $false
                    $noPath = $null -eq $r.BinaryPresent

                    $rowColor = if ($isMissing -or $r.TrustBad) { 'Red' }
                    elseif ($noPath) { 'DarkGray' }
                    elseif ($isMicrosoft) { 'Green' }
                    else { 'Yellow' }

                    $presTag = if ($isMissing) { 'MISS' } elseif ($noPath) { ' -- ' } elseif ($r.TrustBad) { 'BAD!' } else { ' OK ' }
                    $vendorShort = if ($r.Vendor.Length -gt 28) { $r.Vendor.Substring(0, 25) + '...' } else { $r.Vendor }

                    # ErrorControl: 0=Ignore, 1=Normal, 2=Severe (LKGC fallback), 3=Critical (boot failure)
                    $errCtlLabel = if ($null -eq $r.ErrorControl) { '    ' } else {
                        switch ($r.ErrorControl) { 0 { 'Ign' } 1 { 'Norm' } 2 { 'Sev!' } 3 { 'CRIT' } default { "EC$($r.ErrorControl)" } }
                    }

                    Write-Host ("  {0,-30} {1,-28} [{2}] {3,-6} {4}" -f $r.Name, $vendorShort, $presTag, $errCtlLabel, $r.ImagePath) -ForegroundColor $rowColor
                }

                # Summary
                $total = $rows.Count
                $missing = @($rows | Where-Object { $_.BinaryPresent -eq $false }).Count
                $nonMS = @($rows | Where-Object { $_.BinaryPresent -eq $true -and $_.Vendor -notmatch 'Microsoft' }).Count
                $boot_sys = @($rows | Where-Object { $_.StartVal -in @(0, 1) }).Count
                # ErrorControl Severe/Critical only matters for kernel drivers (Type 1/2/4/8);
                # Win32 services (Type 16/32/256) do not BSOD on failure regardless of ErrorControl.
                $isKernelDriver = @(1, 2, 4, 8)
                $sevCritDrivers = @($rows | Where-Object { $_.TypeVal -in $isKernelDriver -and $null -ne $_.ErrorControl -and $_.ErrorControl -ge 2 }).Count
                $missingBootSys = @($rows | Where-Object { $_.BinaryPresent -eq $false -and $_.StartVal -in @(0, 1) -and $_.TypeVal -in $isKernelDriver }).Count
                $trustFailed = @($rows | Where-Object { $_.TrustBad })
                $trustFailedBootSys = @($trustFailed | Where-Object { $_.StartVal -in @(0, 1) })

                Write-Host "`n  ===========================================================" -ForegroundColor Cyan
                Write-Host ("  Total {0}: {1}  |  Boot/System: {2}  |  Missing binary: {3}  |  Non-Microsoft: {4}  |  Severe/Critical EC (drivers): {5}" `
                        -f $reportLabel, $total, $boot_sys, $missing, $nonMS, $sevCritDrivers) -ForegroundColor Cyan
                if ($trustFailed.Count -gt 0) {
                    Write-Host "  [!] $($trustFailed.Count) driver(s) FAILED image trust validation: $(($trustFailed.Name | Select-Object -First 8) -join ', ')" -ForegroundColor Red
                    Write-Host "      The binary is present but its content does not match any valid signature or guest catalog entry (tampered, corrupted or truncated)." -ForegroundColor Red
                    if ($trustFailedBootSys.Count -gt 0) {
                        Write-Host "      $($trustFailedBootSys.Count) of these are Boot/System start - Code Integrity will reject them with STATUS_INVALID_IMAGE_HASH (0xC0000428) -> 0x5A CRITICAL_SERVICE_FAILED." -ForegroundColor Red
                    }
                    Write-Host "      Run -RepairSystemFile <driver.sys> to restore a clean copy from WinSxS/DriverStore." -ForegroundColor Red
                    Write-Host "      If the component store holds the same damaged bytes (a hard link to the file), add -RepairSystemFileSource <file-or-folder>." -ForegroundColor Red
                }
                if ($missingBootSys -gt 0) {
                    Write-Host "  [!] $missingBootSys missing-binary Boot/System kernel driver(s) detected - may cause BSOD (e.g. INACCESSIBLE_BOOT_DEVICE)." -ForegroundColor Red
                    Write-Host "      Run -RepairBrokenSystemFile <driver.sys> to restore from WinSxS, or -DisableThirdPartyDrivers if the driver is non-Microsoft." -ForegroundColor Red
                }
                if ($missing -gt 0 -and $missing -ne $missingBootSys) {
                    $missingSvc = $missing - $missingBootSys
                    Write-Host "  [i] $missingSvc service(s)/non-boot driver(s) have missing binaries - the service will fail to start but will not BSOD." -ForegroundColor Yellow
                }
                if ($nonMS -gt 0) {
                    Write-Host "  [!] Non-Microsoft drivers present - verify each is expected for this guest OS." -ForegroundColor Yellow
                }
                if ($sevCritDrivers -gt 0) {
                    Write-Host "  [!] $sevCritDrivers kernel driver(s) with ErrorControl Sev!(2) or CRIT(3) - failure at boot will trigger LKGC fallback or halt." -ForegroundColor Yellow
                }
                Write-Host "  ===========================================================`n" -ForegroundColor Cyan
            }
        }
    }

    function EnableThirdPartyDrivers {
        Write-Host "Re-enabling previously disabled third-party kernel drivers..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            & {
                $SystemRoot = Get-SystemRootPath
                $ServicesRoot = "$SystemRoot\Services"
                $backupPath = Get-ThirdPartyDriverStartBackupPath

                $reEnabled = @()
                if (Test-Path -LiteralPath $backupPath) {
                    try {
                        $rawBackup = Get-Content -LiteralPath $backupPath -Raw -ErrorAction Stop
                        $backupEntries = ConvertFrom-ThirdPartyDriverStartBackupJson -Json $rawBackup
                    }
                    catch {
                        Write-Warning "Could not read third-party driver Start backup at $backupPath. No drivers were re-enabled. $_"
                        return
                    }

                    foreach ($entry in $backupEntries) {
                        if (-not $entry.Service -or $null -eq $entry.PreviousStart) { continue }
                        $svcName = Assert-ValidServiceOrDriverName -Name ([string]$entry.Service) -ParameterName 'ThirdPartyDriverBackup.Service'
                        try { $startValue = [int]$entry.PreviousStart }
                        catch {
                            Write-Warning "Skipping $svcName - backup has non-numeric Start value '$($entry.PreviousStart)'. Expected 0 through 4."
                            continue
                        }
                        if ($startValue -lt 0 -or $startValue -gt 4) {
                            Write-Warning "Skipping $svcName - backup has invalid Start value '$($entry.PreviousStart)'. Expected 0 through 4."
                            continue
                        }
                        $svcPath = Join-Path $ServicesRoot $svcName

                        if (-not (Test-Path -LiteralPath $svcPath)) {
                            Write-Warning "Skipping $svcName - service path $svcPath not found."
                            continue
                        }

                        $props = Get-ItemProperty -Path $svcPath -ErrorAction SilentlyContinue
                        if ($props.Type -notin @(1, 2)) {
                            Write-Warning "Skipping $svcName - registry entry is not a kernel/filesystem driver."
                            continue
                        }

                        $imagePathRaw = $props.ImagePath
                        if ($imagePathRaw) {
                            $imagePath = Resolve-GuestImagePath $imagePathRaw
                            if (-not (Test-Path $imagePath)) {
                                Write-Warning "Skipping $svcName - binary is missing ($imagePath). Restore the driver file before re-enabling."
                                continue
                            }
                        }

                        $currentValue = $props.Start
                        if ($null -ne $currentValue -and [int]$currentValue -eq $startValue) {
                            Write-Host "  $svcName Start = $currentValue (already restored)." -ForegroundColor DarkGray
                        }
                        else {
                            Write-Host "  Restoring: $svcName Start $currentValue -> $startValue" -ForegroundColor Yellow
                            Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $startValue -Type DWord -Force
                        }
                        $reEnabled += [PSCustomObject]@{ Service = $svcName; Start = $startValue }
                    }

                    if ($reEnabled.Count -eq 0) {
                        Write-Host "No third-party driver Start values were restored from $backupPath." -ForegroundColor Yellow
                    }
                    else {
                        Write-Host "`nRestored $($reEnabled.Count) driver Start value(s) from $backupPath." -ForegroundColor Green
                        foreach ($d in $reEnabled) {
                            Write-Host "  $($d.Service) -> Start=$($d.Start)" -ForegroundColor Green
                        }
                    }
                    return
                }

                Write-Warning "No third-party driver Start backup found at $backupPath. Falling back to legacy restore behavior (Start=1)."
                Get-ChildItem $ServicesRoot -ErrorAction SilentlyContinue | ForEach-Object {
                    $svcPath = $_.PSPath
                    $props = Get-ItemProperty -Path $svcPath -ErrorAction SilentlyContinue
                    # Only disabled kernel/filesystem drivers
                    if ($props.Type -notin @(1, 2)) { return }
                    if ($props.Start -ne 4) { return }

                    $imagePathRaw = $props.ImagePath
                    if (-not $imagePathRaw) { return }
                    $imagePath = Resolve-GuestImagePath $imagePathRaw

                    $isMicrosoft = $false
                    if (Test-Path $imagePath) {
                        $vi = (Get-Item $imagePath -ErrorAction SilentlyContinue).VersionInfo
                        if ($vi -and $vi.CompanyName -match 'Microsoft') { $isMicrosoft = $true }
                    }
                    else {
                        # Binary is missing - warn and skip re-enabling (re-enabling a driver with a
                        # missing binary will cause a BSOD on boot).
                        Write-Warning "Skipping $($_.PSChildName) - binary is missing ($imagePath). Restore the driver file before re-enabling."
                        return
                    }

                    if (-not $isMicrosoft) {
                        $svcName = $_.PSChildName
                        # Restore to System (1) start - safest default for a previously Boot/System driver
                        Write-Host "  Re-enabling: $svcName" -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value 1 -Type DWord -Force
                        $reEnabled += $svcName
                    }
                }

                if ($reEnabled.Count -eq 0) {
                    Write-Host "No disabled third-party Boot/System drivers found to re-enable." -ForegroundColor Green
                }
                else {
                    Write-Host "`nRe-enabled $($reEnabled.Count) driver(s): $($reEnabled -join ', ')" -ForegroundColor Green
                    Write-Warning "Start value restored to 1 (System). If a driver was originally Boot (0), adjust manually after verifying VM boots." 
                }
            }
        }
    }

    # Remove the Credential Guard UEFI firmware variable that persists when CG is enabled with UEFI lock.
    # Registry changes alone (zeroing LsaCfgFlags) are insufficient because the EFI NVRAM variable
    # survives reboots independently of the registry.
    # This script repairs offline disks that are later reattached to their Azure VM, so the only
    # viable offline method is injecting a SecConfig.efi one-time BCD boot entry: on the VM's next
    # boot (on Azure) the EFI application runs and clears the UEFI variable inside the guest firmware.
    # NOTE: -FixBoot (RebuildBCD) only recreates the BCD store and does NOT clear this EFI variable.
    function Remove-CredentialGuardUefiLock {
        # ------------------------------------------------------------------
        # bcdedit + SecConfig.efi one-time-boot entry
        # Copies the Microsoft-supplied SecConfig.efi tool to the guest's EFI
        # partition on the offline disk and adds a one-time BCD bootsequence
        # entry. When the disk is reattached to the Azure VM and it boots,
        # SecConfig.efi runs inside the VM and clears the UEFI NVRAM variable.
        # Azure Gen2/Trusted Launch VMs auto-accept the confirmation (no
        # physical key press required).
        # ------------------------------------------------------------------
        if ($script:VMGen -ne 2 -or [string]::IsNullOrWhiteSpace($script:BootDriveLetter)) {
            Write-Warning "  SecConfig.efi method requires a mounted Gen2/UEFI EFI partition - skipping."
            Write-Error "UEFI lock could not be cleared: EFI partition not available."
            return
        }

        $efiVolume = $script:BootDriveLetter.TrimEnd('\')
        $storePath = "$efiVolume\EFI\Microsoft\Boot\BCD"
        $secDest = "$efiVolume\EFI\Microsoft\Boot\SecConfig.efi"
        $secSrc = "$env:SystemRoot\System32\SecConfig.efi"

        if (-not (Test-Path $secSrc)) {
            Write-Warning "  SecConfig.efi not found at '$secSrc' on this host."
            Write-Error "UEFI lock could not be cleared: SecConfig.efi unavailable."
            return
        }

        if (-not (Test-Path $storePath)) {
            Write-Warning "  Offline BCD not found at '$storePath'."
            Write-Error "UEFI lock could not be cleared: offline BCD not found."
            return
        }

        try {
            Write-Host "  Configuring SecConfig.efi one-time boot entry in offline BCD..." -ForegroundColor Cyan
            Copy-Item-Logged -Path $secSrc -Destination $secDest -Force

            # Well-known GUID defined by Microsoft for the CG disable tool boot entry
            $cgGuid = '{0cb3b571-2f2e-4343-a879-d86a476d7215}'

            # Remove any pre-existing entry with this GUID to ensure a clean state
            $deleteBcdCmd = "bcdedit /store `"$storePath`" /delete $cgGuid /cleanup"
            Write-Host "  [exec] $deleteBcdCmd" -ForegroundColor DarkGray
            $deleteResult = Invoke-NativeCommandLogged -Description 'Remove existing Credential Guard BCD entry' -Details @{
                StorePath = $storePath
                Identifier = $cgGuid
            } -ScriptBlock { & cmd.exe /c $deleteBcdCmd }
            if ($deleteResult.ExitCode -ne 0) {
                Write-Host "  Existing Credential Guard BCD entry was not present or could not be removed; continuing with recreation." -ForegroundColor DarkGray
            }

            # Create the one-time boot sequence entry
            $bcdCmds = @(
                "/create $cgGuid /d `"CredentialGuard UEFI Disable Tool`" /application osloader",
                "/set $cgGuid path `"\EFI\Microsoft\Boot\SecConfig.efi`"",
                "/set {bootmgr} bootsequence $cgGuid",
                "/set $cgGuid loadoptions DISABLE-LSA-ISO",
                "/set $cgGuid device partition=${efiVolume}:"
            )
            foreach ($cmd in $bcdCmds) {
                Invoke-BcdEdit -StorePath $storePath -Command $cmd
            }

            Write-Host "  [OK] SecConfig.efi one-time boot entry added to offline BCD." -ForegroundColor Green
            Write-Host ("  On the VM's first boot back on Azure, SecConfig.efi will run inside the VM " +
                "and clear the Credential Guard EFI NVRAM variable automatically.") -ForegroundColor Cyan
        }
        catch {
            Write-Warning "  bcdedit SecConfig.efi setup failed: $_"
            Write-Error "UEFI lock could not be cleared."
        }
    }

    function DisableCredentialGuard {
        Write-Host "Disabling Credential Guard and LSA protection..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath

            $lsaPath = "$SystemRoot\Control\Lsa"
            $cgPath = "HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\DeviceGuard"
            $cgSysPath = "$SystemRoot\Control\DeviceGuard"

            # Snapshot for restore
            $beforeRunAsPPL = (Get-ItemProperty $lsaPath   -ErrorAction SilentlyContinue).RunAsPPL
            $beforeLsaCfg = (Get-ItemProperty $cgSysPath -ErrorAction SilentlyContinue).LsaCfgFlags
            $beforeCGEnabled = (Get-ItemProperty $cgPath    -ErrorAction SilentlyContinue).EnableVirtualizationBasedSecurity

            # Detect UEFI lock: LsaCfgFlags=1 in Control\Lsa means CG was enabled WITH UEFI lock.
            # The EFI NVRAM variable survives registry changes and must be cleared separately.
            # LsaCfgFlags=2 means enabled WITHOUT lock - registry zeroing is sufficient.
            $lsaLsaCfgFlags = (Get-ItemProperty $lsaPath -ErrorAction SilentlyContinue).LsaCfgFlags
            if ($lsaLsaCfgFlags -eq 1) {
                $uefiLockWasActive = $true
                Write-Warning ("Credential Guard was enabled WITH UEFI lock (Control\Lsa\LsaCfgFlags=1). " +
                    "An EFI NVRAM variable is also set - registry changes alone are not sufficient. " +
                    "The UEFI firmware variable will be cleared after applying registry changes.")
            }
            elseif ($lsaLsaCfgFlags -eq 2) {
                Write-Host "  Credential Guard mode: WITHOUT UEFI lock - registry changes are sufficient." -ForegroundColor Cyan
            }

            # Zero all registry knobs (both paths that can enforce CG)
            Set-ItemProperty-Logged -Path $lsaPath   -Name RunAsPPL    -Value 0 -Type DWord -Force
            Set-ItemProperty-Logged -Path $lsaPath   -Name LsaCfgFlags -Value 0 -Type DWord -Force
            Set-ItemProperty-Logged -Path $cgSysPath -Name LsaCfgFlags -Value 0 -Type DWord -Force
            if (Test-Path $cgPath) {
                Set-ItemProperty-Logged -Path $cgPath -Name EnableVirtualizationBasedSecurity -Value 0 -Type DWord -Force
                Set-ItemProperty-Logged -Path $cgPath -Name LsaCfgFlags                       -Value 0 -Type DWord -Force
            }

            Write-Host "Credential Guard registry settings cleared. Use -EnableCredentialGuard to revert." -ForegroundColor Green
            Write-Host "`n--- REVERT COMMANDS (run on the VM after recovery) ---" -ForegroundColor Cyan
            $lsaLive = "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa"
            $cgSysLive = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard"
            $cgLive = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeviceGuard"
            Write-Host "Set-ItemProperty -Path '$lsaLive'   -Name RunAsPPL    -Value $(if ($null -ne $beforeRunAsPPL) { $beforeRunAsPPL } else { '1 # (was not set)' }) -Type DWord -Force" -ForegroundColor White
            Write-Host "Set-ItemProperty -Path '$cgSysLive' -Name LsaCfgFlags -Value $(if ($null -ne $beforeLsaCfg)  { $beforeLsaCfg  } else { '1 # (was not set)' }) -Type DWord -Force" -ForegroundColor White
            if ($null -ne $beforeCGEnabled) {
                Write-Host "Set-ItemProperty -Path '$cgLive' -Name EnableVirtualizationBasedSecurity -Value $beforeCGEnabled -Type DWord -Force" -ForegroundColor White
            }
            Write-Host "------------------------------------------------------`n" -ForegroundColor Cyan
        }

        # Hives are now safely unmounted. Clear the EFI NVRAM variable if UEFI lock was active.
        if ($uefiLockWasActive) {
            Write-Host "`nClearing Credential Guard EFI NVRAM variable (UEFI lock)..." -ForegroundColor Yellow
            Remove-CredentialGuardUefiLock
        }
    }

    function DisableLsaProtection {
        if (-not (Confirm-CriticalOperation -Operation 'Disable LSA protection only (-DisableLsaProtection)' -Details @"
Deletes only the offline SYSTEM hive value:
  Control\Lsa\RunAsPPL

This does NOT change Credential Guard, Device Guard, LsaCfgFlags, VBS, HVCI,
or application proxy connector services.

If RunAsPPL was enabled with UEFI lock, removing the registry value may not be
sufficient. In that case, boot once with the Microsoft LSA protected process
opt-out EFI tool to clear the firmware variable.
"@)) { return }

        $script:_lsaPplRunAsPPLBefore = $null
        $script:_lsaPplUefiLockLikely = $false

        Write-Host "Disabling LSA protection only..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath
            $lsaPath = "$SystemRoot\Control\Lsa"
            if (-not (Test-Path $lsaPath)) {
                Write-Warning "  LSA registry path not found: $lsaPath"
                return
            }

            $lsaProps = Get-ItemProperty $lsaPath -ErrorAction SilentlyContinue
            $runAsPPL = $lsaProps.RunAsPPL
            $script:_lsaPplRunAsPPLBefore = $runAsPPL

            if ($null -eq $runAsPPL -or [int]$runAsPPL -eq 0) {
                Write-Host "  RunAsPPL is not enabled on the offline OS." -ForegroundColor Green
                Write-ActionLog -Event 'DisableLsaProtection' -Details @{ BeforeRunAsPPL = $runAsPPL; Changed = $false }
                return
            }

            if ([int]$runAsPPL -eq 1) {
                $script:_lsaPplUefiLockLikely = $true
            }

            Remove-ItemProperty-Logged -Path $lsaPath -Name RunAsPPL -Force
            Write-Host "  Removed Control\Lsa\RunAsPPL from the offline SYSTEM hive." -ForegroundColor Green
            Write-ActionLog -Event 'DisableLsaProtection' -Details @{ BeforeRunAsPPL = $runAsPPL; Changed = $true }
        }

        if ($null -ne $script:_lsaPplRunAsPPLBefore -and [int]$script:_lsaPplRunAsPPLBefore -ne 0) {
            Write-Host "`n--- REVERT COMMAND (run on the VM after recovery, if needed) ---" -ForegroundColor Cyan
            Write-Host "Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name RunAsPPL -Value $script:_lsaPplRunAsPPLBefore -Type DWord -Force" -ForegroundColor White
            Write-Host "----------------------------------------------------------------`n" -ForegroundColor Cyan
        }

        if ($script:_lsaPplUefiLockLikely) {
            Write-Warning "RunAsPPL=1 can indicate LSA protection was enabled with UEFI lock. This switch intentionally did not modify Credential Guard. If LSASS still starts as a protected process after reboot, boot once with the Microsoft LSA protected process opt-out EFI tool to clear the firmware variable."
        }
    }

    function DisableMemoryIntegrity {
        if (-not (Confirm-CriticalOperation -Operation 'Disable Memory Integrity / HVCI (-DisableMemoryIntegrity)' -Details @"
Disables offline Hypervisor-Enforced Code Integrity settings that can cause a
Code Integrity boot failure after incompatible driver, VBS, or Device Guard changes.

This sets the active ControlSet value:
  Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity\Enabled = 0

It also clears related policy/lock values where present. If HVCI was enabled
with UEFI lock, Secure Boot may still need to be disabled once so Windows can
complete recovery.
"@)) { return }

        Write-Host "Disabling Memory Integrity / Hypervisor-Enforced Code Integrity..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $systemRoot = Get-SystemRootPath
            $hvciPath = "$systemRoot\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"
            $deviceGuardPath = "$systemRoot\Control\DeviceGuard"
            $policyPath = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\DeviceGuard'

            $beforeEnabled = (Get-ItemProperty -Path $hvciPath -ErrorAction SilentlyContinue).Enabled
            $beforeLocked = (Get-ItemProperty -Path $hvciPath -ErrorAction SilentlyContinue).Locked
            if ($beforeLocked -eq 1) {
                Write-Warning "Memory Integrity appears to be configured with a lock. Registry changes may require Secure Boot to be disabled once for recovery."
            }

            Set-ItemProperty-Logged -Path $hvciPath -Name Enabled -Value 0 -Type DWord -Force
            Set-ItemProperty-Logged -Path $hvciPath -Name Locked  -Value 0 -Type DWord -Force

            if (Test-Path $deviceGuardPath) {
                Set-ItemProperty-Logged -Path $deviceGuardPath -Name Mandatory -Value 0 -Type DWord -Force
            }

            if (Test-Path $policyPath) {
                Set-ItemProperty-Logged -Path $policyPath -Name HypervisorEnforcedCodeIntegrity -Value 0 -Type DWord -Force
                Set-ItemProperty-Logged -Path $policyPath -Name HVCIMATRequired -Value 0 -Type DWord -Force
            }

            Write-Host "Memory Integrity / HVCI registry settings cleared." -ForegroundColor Green
            Write-Host "`n--- REVERT COMMANDS (run on the VM after recovery if you want to re-enable HVCI) ---" -ForegroundColor Cyan
            $hvciLive = 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity'
            Write-Host "Set-ItemProperty -Path '$hvciLive' -Name Enabled -Value $(if ($null -ne $beforeEnabled) { $beforeEnabled } else { '1 # (was not set)' }) -Type DWord -Force" -ForegroundColor White
            if ($null -ne $beforeLocked) {
                Write-Host "Set-ItemProperty -Path '$hvciLive' -Name Locked -Value $beforeLocked -Type DWord -Force" -ForegroundColor White
            }
            Write-Host "--------------------------------------------------------------------------------`n" -ForegroundColor Cyan
        }
    }

    function EnableCredentialGuard {
        Write-Host "Re-enabling Credential Guard and LSA protection..." -ForegroundColor Yellow

        # ----------------------------------------------------------------
        # Safety gate 1: Credential Guard requires UEFI Secure Boot (Gen2/GPT).
        # Writing the registry flags on a Gen1/MBR VM causes a no-boot scenario
        # because Windows cannot satisfy the Secure Boot requirement at startup.
        # $script:VMGen is already set by Repair-OfflineDisk via Get-DiskGeneration
        # (GPT -> 2, MBR -> 1), so this check is reliable even when -DiskNumber
        # is used instead of -VMName.
        # ----------------------------------------------------------------
        if ($script:VMGen -eq 1) {
            Write-Error ("BLOCKED: This disk uses MBR/BIOS (Gen1). Credential Guard requires UEFI Secure Boot " +
                "(Gen2/GPT). Enabling it on a Gen1 VM writes flags that prevent Windows from booting. Aborting.")
            return
        }
        if ($null -eq $script:VMGen) {
            Write-Error ("BLOCKED: Disk partition style could not be determined (expected MBR=Gen1 or GPT=Gen2). " +
                "Credential Guard requires UEFI/GPT (Gen2). Aborting to prevent a potential no-boot scenario.")
            return
        }

        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath

            # ----------------------------------------------------------------
            # Safety gate 2: Credential Guard is only supported on Enterprise,
            # Education, and Server editions. Enabling it on Home/Pro/Core writes
            # the same registry flags but Windows will fail a boot-time licence
            # check resulting in an unbootable VM.
            # ----------------------------------------------------------------
            $winVer = Get-ItemProperty "HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion" -ErrorAction SilentlyContinue
            $editionId = $winVer.EditionID
            $productName = $winVer.ProductName

            # ----------------------------------------------------------------
            # Safety gate 2a: Credential Guard requires Windows 10 / Windows
            # Server 2016 (build 14393) or later. It does not exist on Windows
            # Server 2012 R2 (9600) or 2012 (9200); writing the flags there is
            # meaningless and the VBS/Secure Boot prerequisites cannot be met,
            # so block it to avoid a confusing no-op or no-boot scenario.
            # ----------------------------------------------------------------
            $cgBuild = 0
            [void][int]::TryParse([string]$winVer.CurrentBuildNumber, [ref]$cgBuild)
            if ($cgBuild -gt 0 -and $cgBuild -lt 14393) {
                Write-Error ("BLOCKED: Credential Guard requires Windows 10 / Windows Server 2016 (build 14393) or later. " +
                    "This guest is build $cgBuild ($productName), which does not support Credential Guard. Aborting.")
                return
            }

            $unsupportedEditions = @('Home', 'Pro', 'CoreSingleLanguage', 'Core', 'ProWorkstation', 'ProfessionalWorkstation')
            $editionBlocked = $unsupportedEditions | Where-Object { $editionId -match $_ }
            if ($editionBlocked) {
                Write-Error ("BLOCKED: Windows edition '$editionId' ($productName) does not support Credential Guard. " +
                    "Only Enterprise, Education, and Server editions are supported. Aborting.")
                return
            }
            if ($editionId) {
                Write-Host "  Windows edition: $editionId ($productName) - supported." -ForegroundColor Cyan
            }
            else {
                Write-Warning "  Could not read Windows edition from offline hive; proceeding with caution."
            }

            $lsaPath = "$SystemRoot\Control\Lsa"
            $cgSysPath = "$SystemRoot\Control\DeviceGuard"
            $cgPath = "HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\DeviceGuard"

            Set-ItemProperty-Logged -Path $lsaPath   -Name RunAsPPL     -Value 1 -Type DWord -Force
            Set-ItemProperty-Logged -Path $cgSysPath -Name LsaCfgFlags  -Value 1 -Type DWord -Force
            if (Test-Path $cgPath) {
                Set-ItemProperty-Logged -Path $cgPath -Name EnableVirtualizationBasedSecurity -Value 1 -Type DWord -Force
                Set-ItemProperty-Logged -Path $cgPath -Name LsaCfgFlags                       -Value 1 -Type DWord -Force
            }

            Write-Host "Credential Guard and LSA protection re-enabled." -ForegroundColor Green
            Write-Warning ("Before starting the VM, verify in Hyper-V settings that: " +
                "(1) Secure Boot is enabled, (2) Virtualization Based Security (VBS) is enabled. " +
                "If either is missing the VM will fail to boot. Use -DisableCredentialGuard to revert.")
        }
    }

    function DisableAppLocker {
        # AppLocker can prevent Windows from booting when an Enforce-mode policy incorrectly
        # blocks a system binary, service DLL, or startup script. The fix has two parts:
        #
        #  1. Set all AppLocker rule collection EnforcementMode values to 0 (Not Configured)
        #     in both the GPO-policy path (SOFTWARE\Policies) and the local policy path.
        #     This is non-destructive: the rules are preserved but not enforced, so the
        #     admin can re-enable them once the VM is healthy.
        #
        #  2. Disable the Application Identity service (AppIDSvc). AppLocker relies on this
        #     service at runtime; disabling it prevents enforcement even if the policy paths
        #     are re-applied by GPO refresh before an admin can investigate.
        #
        # EnforcementMode values:
        #   0 = Not Configured (rules ignored)
        #   1 = Enforce rules
        #   2 = Audit only

        Write-Host "Disabling AppLocker enforcement..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $SystemRoot = Get-SystemRootPath

            # Rule collection names that AppLocker enforces
            $ruleCollections = @('Exe', 'Dll', 'Script', 'Msi', 'Appx')

            # Two registry paths can carry AppLocker policy:
            #   - GPO/MDM-applied:  SOFTWARE\Policies\Microsoft\Windows\SrpV2
            #   - Local policy:     SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\AppV (rare)
            # The GPO path is by far the most common source of broken policies on Azure VMs.
            $srpPaths = @(
                'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\SrpV2',
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\AppV\SrpV2'
            )

            # --- Pass 1: scan for any actively-enforced collections (mode 1 or 2) ---
            $enforced = [System.Collections.Generic.List[hashtable]]::new()
            foreach ($srpBase in $srpPaths) {
                if (-not (Test-Path $srpBase)) { continue }
                foreach ($collection in $ruleCollections) {
                    $collPath = "$srpBase\$collection"
                    if (-not (Test-Path $collPath)) { continue }
                    $current_mode = (Get-ItemProperty $collPath -ErrorAction SilentlyContinue).EnforcementMode
                    if ($null -ne $current_mode -and $current_mode -ne 0) {
                        $modeLabel = if ($current_mode -eq 1) { 'Enforce' } else { 'Audit' }
                        Write-Host "  [$collection] EnforcementMode = $current_mode ($modeLabel) - will disable." -ForegroundColor Yellow
                        $enforced.Add(@{ Path = $collPath; Collection = $collection; Mode = $current_mode })
                    }
                }
            }

            # --- Check AppIDSvc start value ---
            $appIdPath = "$SystemRoot\Services\AppIDSvc"
            $appIdStart = if (Test-Path $appIdPath) { (Get-ItemProperty $appIdPath -ErrorAction SilentlyContinue).Start } else { $null }
            # Service runs if Start is 2 (Auto) or 3 (Manual/demand); 4 = Disabled, 1 = Boot (unlikely)
            $appIdRunning = $null -ne $appIdStart -and $appIdStart -in @(1, 2, 3)

            # --- Early exit if nothing is active ---
            if ($enforced.Count -eq 0 -and -not $appIdRunning) {
                Write-Host "  AppLocker is not enforced (no active rule collections, AppIDSvc not running). No changes made." -ForegroundColor Green
                return
            }

            # --- Pass 2: disable only what is active ---
            foreach ($item in $enforced) {
                Write-Host "  [$($item.Collection)] EnforcementMode: $($item.Mode) -> 0 (Not Configured)" -ForegroundColor Cyan
                Set-ItemProperty-Logged -Path $item.Path -Name EnforcementMode -Value 0 -Type DWord -Force
            }

            # Disable Application Identity service so AppLocker cannot enforce at runtime
            # even if GPO refreshes the policy keys before an admin can intervene.
            if ($appIdRunning) {
                Write-Host "  AppIDSvc Start: $appIdStart -> 4 (Disabled)" -ForegroundColor Cyan
                Set-ItemProperty-Logged -Path $appIdPath -Name Start -Value 4 -Type DWord -Force
            }
            elseif (-not (Test-Path $appIdPath)) {
                Write-Host "  AppIDSvc registry key not found - service not installed on this image." -ForegroundColor DarkGray
            }

            Write-Host "AppLocker enforcement disabled." -ForegroundColor Green
            Write-Host ("  NOTE: AppLocker rules are preserved (EnforcementMode=0). " +
                "To re-enable, set EnforcementMode=1 under SOFTWARE\Policies\Microsoft\Windows\SrpV2\<Collection> " +
                "and set AppIDSvc Start back to 2 (Automatic) on the live VM.") -ForegroundColor Cyan
            Write-Warning ("If AppLocker policy is delivered by Intune/MDM, the offline registry path will be empty " +
                "and policy will reapply on next MDM sync. Resolve via Intune before starting the VM.")
        }
    }

    function GetAppLockerReport {
        # Reads AppLocker configuration from the offline SOFTWARE and SYSTEM hives and
        # produces a human-readable report:
        #   - Per-collection enforcement mode
        #   - AppIDSvc service start type
        #   - Parsed rule details (Name, Action, Type, Conditions)
        Write-Host "`n========== AppLocker Report ==========" -ForegroundColor Cyan

        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            & {
                # --- AppIDSvc from SYSTEM hive ---
                $csName = Get-CurrentOfflineControlSetName
                $svcRoot = "HKLM:\BROKENSYSTEM\$csName\Services"

                $appIdPath = "$svcRoot\AppIDSvc"
                $appIdStart = if (Test-Path $appIdPath) { (Get-ItemProperty $appIdPath -ErrorAction SilentlyContinue).Start } else { $null }
                $startLabels = @{ 0 = 'Boot'; 1 = 'System'; 2 = 'Automatic'; 3 = 'Manual'; 4 = 'Disabled' }
                $startLabel = if ($null -ne $appIdStart -and $startLabels.ContainsKey([int]$appIdStart)) { $startLabels[[int]$appIdStart] } else { "Unknown($appIdStart)" }

                Write-Host "`n--- Application Identity Service (AppIDSvc) ---" -ForegroundColor Yellow
                if ($null -eq $appIdStart) {
                    Write-Host "  AppIDSvc registry key not found - service not installed." -ForegroundColor DarkGray
                }
                elseif ($appIdStart -eq 2) {
                    Write-Host "  Start = $appIdStart ($startLabel)" -ForegroundColor Red
                    Write-Host "  AppIDSvc is set to AUTO - AppLocker WILL enforce rules at boot." -ForegroundColor Red
                }
                elseif ($appIdStart -eq 3) {
                    Write-Host "  Start = $appIdStart ($startLabel)" -ForegroundColor Yellow
                    Write-Host "  AppIDSvc is Manual - may be trigger-started if AppLocker policy exists." -ForegroundColor Yellow
                }
                elseif ($appIdStart -eq 4) {
                    Write-Host "  Start = $appIdStart ($startLabel)" -ForegroundColor Green
                    Write-Host "  AppIDSvc is Disabled - AppLocker rules will NOT be enforced at runtime." -ForegroundColor Green
                }
                else {
                    Write-Host "  Start = $appIdStart ($startLabel)" -ForegroundColor Yellow
                }

                # --- AppLocker policy from SOFTWARE hive ---
                $srpPaths = @(
                    @{ Label = 'GPO/MDM Policy'; Path = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\SrpV2' },
                    @{ Label = 'Local Policy';   Path = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\AppV\SrpV2' }
                )
                $modeLabels = @{ 0 = 'Not Configured'; 1 = 'Enforce'; 2 = 'Audit Only' }
                $collections = @('Exe', 'Dll', 'Script', 'Msi', 'Appx')

                $anyFound = $false
                foreach ($srp in $srpPaths) {
                    if (-not (Test-Path $srp.Path)) { continue }

                    Write-Host "`n--- $($srp.Label): $($srp.Path -replace '^HKLM:\\BROKENSOFTWARE\\', 'SOFTWARE\') ---" -ForegroundColor Yellow

                    foreach ($col in $collections) {
                        $colPath = "$($srp.Path)\$col"
                        if (-not (Test-Path $colPath)) { continue }

                        $mode = (Get-ItemProperty $colPath -ErrorAction SilentlyContinue).EnforcementMode
                        $modeLabel = if ($null -ne $mode -and $modeLabels.ContainsKey([int]$mode)) { $modeLabels[[int]$mode] } else { "Unknown($mode)" }

                        $modeColor = switch ([int]$mode) { 1 { 'Red' } 2 { 'Yellow' } default { 'Green' } }
                        Write-Host "`n  [$col] EnforcementMode = $mode ($modeLabel)" -ForegroundColor $modeColor

                        # Enumerate GUID rule subkeys
                        $ruleKeys = @(Get-ChildItem $colPath -ErrorAction SilentlyContinue |
                            Where-Object { $_.PSChildName -match '^\{[0-9a-f-]{36}\}$' })

                        if ($ruleKeys.Count -eq 0) {
                            Write-Host "    No rules found." -ForegroundColor DarkGray
                            continue
                        }

                        $anyFound = $true
                        Write-Host "    Rules ($($ruleKeys.Count)):" -ForegroundColor White

                        foreach ($rk in $ruleKeys) {
                            $ruleId = $rk.PSChildName
                            $valueData = (Get-ItemProperty $rk.PSPath -ErrorAction SilentlyContinue).Value
                            if (-not $valueData) {
                                Write-Host "      $ruleId - (no Value data)" -ForegroundColor DarkGray
                                continue
                            }

                            # Parse the XML rule
                            try {
                                [xml]$ruleXml = $valueData
                                $ruleNode = $ruleXml.DocumentElement
                                $ruleName   = $ruleNode.Name
                                $ruleAction = $ruleNode.Action
                                $ruleDesc   = $ruleNode.Description
                                $ruleType   = $ruleNode.LocalName   # e.g. FilePublisherRule, FileHashRule, FilePathRule
                                $ruleSid    = $ruleNode.UserOrGroupSid

                                # Determine action colour
                                $actionColor = if ($ruleAction -eq 'Deny') { 'Red' } elseif ($ruleAction -eq 'Allow') { 'Green' } else { 'Yellow' }

                                Write-Host "      $ruleId" -ForegroundColor DarkGray
                                Write-Host "        Name   : $ruleName" -ForegroundColor White
                                Write-Host "        Type   : $ruleType" -ForegroundColor White
                                Write-Host "        Action : " -NoNewline; Write-Host $ruleAction -ForegroundColor $actionColor
                                if ($ruleDesc) { Write-Host "        Desc   : $ruleDesc" -ForegroundColor White }
                                Write-Host "        SID    : $ruleSid" -ForegroundColor DarkGray

                                # Extract condition details based on rule type
                                $conditions = $ruleNode.Conditions
                                if ($conditions) {
                                    foreach ($child in $conditions.ChildNodes) {
                                        switch ($child.LocalName) {
                                            'FilePublisherCondition' {
                                                Write-Host "        Publisher  : $($child.PublisherName)" -ForegroundColor Cyan
                                                Write-Host "        Product   : $($child.ProductName)" -ForegroundColor Cyan
                                                Write-Host "        Binary    : $($child.BinaryName)" -ForegroundColor Cyan
                                                $vr = $child.BinaryVersionRange
                                                if ($vr) { Write-Host "        Version   : $($vr.LowSection) - $($vr.HighSection)" -ForegroundColor DarkGray }
                                            }
                                            'FileHashCondition' {
                                                foreach ($fh in $child.ChildNodes) {
                                                    if ($fh.LocalName -eq 'FileHash') {
                                                        Write-Host "        Hash Type : $($fh.Type)" -ForegroundColor Cyan
                                                        Write-Host "        Hash      : $($fh.Data)" -ForegroundColor Cyan
                                                        Write-Host "        Source    : $($fh.SourceFileName) ($($fh.SourceFileLength) bytes)" -ForegroundColor DarkGray
                                                    }
                                                }
                                            }
                                            'FilePathCondition' {
                                                Write-Host "        Path      : $($child.Path)" -ForegroundColor Cyan
                                            }
                                        }
                                    }
                                }

                                # Exceptions
                                $exceptions = $ruleNode.Exceptions
                                if ($exceptions -and $exceptions.HasChildNodes) {
                                    Write-Host "        Exceptions:" -ForegroundColor Yellow
                                    foreach ($exc in $exceptions.ChildNodes) {
                                        switch ($exc.LocalName) {
                                            'FilePublisherCondition' { Write-Host "          Publisher: $($exc.PublisherName) / $($exc.ProductName) / $($exc.BinaryName)" -ForegroundColor Yellow }
                                            'FileHashCondition'      { foreach ($fh in $exc.ChildNodes) { if ($fh.LocalName -eq 'FileHash') { Write-Host "          Hash: $($fh.SourceFileName) ($($fh.Type))" -ForegroundColor Yellow } } }
                                            'FilePathCondition'      { Write-Host "          Path: $($exc.Path)" -ForegroundColor Yellow }
                                        }
                                    }
                                }
                            }
                            catch {
                                Write-Host "      $ruleId - failed to parse XML: $_" -ForegroundColor Red
                            }
                        }
                    }
                }

                if (-not $anyFound) {
                    Write-Host "`n  No AppLocker rule subkeys found in any collection." -ForegroundColor Green
                }
            }
        }

        Write-Host "`n========================================`n" -ForegroundColor Cyan
    }

    function FixSanPolicy {
        Write-Host "Setting SAN policy to OnlineAll so all disks come online on boot..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath
            $sanPath = "$SystemRoot\Services\partmgr\Parameters"

            $before = (Get-ItemProperty $sanPath -ErrorAction SilentlyContinue).SanPolicy
            Set-ItemProperty-Logged -Path $sanPath -Name SanPolicy -Value 1 -Type DWord -Force  # 1 = OnlineAll

            Write-Host "SAN policy set to OnlineAll (1). Previous value: $(if ($null -ne $before) { $before } else { 'not set' })." -ForegroundColor Green
            Write-Host "Revert: Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\partmgr\Parameters' -Name SanPolicy -Value $(if ($null -ne $before) { $before } else { 4 }) -Type DWord -Force" -ForegroundColor DarkCyan
        }
    }

    function FixAzureGuestAgent {
        Write-Host "Enabling Azure Guest Agent and RdAgent services..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath

            $agents = @(
                @{ Name = 'WindowsAzureGuestAgent'; StartValue = 2 },
                @{ Name = 'RdAgent'; StartValue = 2 },
                @{ Name = 'WindowsAzureTelemetryService'; StartValue = 3 }
            )

            foreach ($agent in $agents) {
                $svcPath = "$SystemRoot\Services\$($agent.Name)"
                if (Test-Path $svcPath) {
                    $before = (Get-ItemProperty $svcPath -ErrorAction SilentlyContinue).Start
                    Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $agent.StartValue -Type DWord -Force
                    Write-Host "  $($agent.Name): Start set to $($agent.StartValue) (was $before)" -ForegroundColor Green
                }
                else {
                    Write-Warning "  $($agent.Name) not found in registry - agent may not be installed."
                }
            }
            Write-Host "Azure Guest Agent services configured. Boot the VM for them to start." -ForegroundColor Green
        }
    }

    function InstallAzureVMAgentOffline {
        # Implements the offline VM Agent installation procedure from:
        # https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/install-vm-agent-offline
        #
        # Source: this Hyper-V rescue VM (must have Azure VM Agent installed locally).
        # Steps:
        #   1. Validate the host has the required service registry keys and GuestAgent files.
        #   2. Backup any existing WindowsAzure folder on the offline disk.
        #   3. Copy GuestAgent_* folder(s) from C:\WindowsAzure on the host to the offline disk.
        #   4. Mount the offline SYSTEM hive and copy the service registry keys into it.
        #   5. Set service Start values to Auto so the agent starts on next boot.

        Write-Host "Installing Azure VM Agent in offline mode..." -ForegroundColor Yellow

        # ------------------------------------------------------------------
        # Step 1: Validate host sources
        # ------------------------------------------------------------------
        $requiredSvcs = @('WindowsAzureGuestAgent', 'RdAgent')
        foreach ($svc in $requiredSvcs) {
            $hostKey = "HKLM:\SYSTEM\ControlSet001\Services\$svc"
            if (-not (Test-Path $hostKey)) {
                Write-Error ("SKIPPED: Host registry key '$hostKey' not found. " +
                    "Azure VM Agent must be installed on this Hyper-V rescue VM to use -InstallAzureVMAgent. " +
                    "Download and install the agent from https://aka.ms/vmagentwin first.")
                return
            }
        }

        $hostWaFolder = 'C:\WindowsAzure'
        if (-not (Test-Path $hostWaFolder)) {
            Write-Error ("SKIPPED: '$hostWaFolder' not found on this host. " +
                "Azure VM Agent must be installed on this Hyper-V rescue VM to use -InstallAzureVMAgent.")
            return
        }

        $agentFolders = Get-ChildItem -Path $hostWaFolder -Directory -Filter 'GuestAgent_*' -ErrorAction SilentlyContinue |
        Sort-Object Name
        if (-not $agentFolders) {
            # Fallback: check ImagePath in the host registry to find the folder
            $imgPath = (Get-ItemProperty 'HKLM:\SYSTEM\ControlSet001\Services\WindowsAzureGuestAgent' `
                    -ErrorAction SilentlyContinue).ImagePath
            $imgDir = if ($imgPath) { Split-Path $imgPath -Parent } else { $null }
            if ($imgDir -and (Test-Path $imgDir)) {
                Write-Host "  No GuestAgent_* folder found; using ImagePath directory: $imgDir" -ForegroundColor Cyan
                $agentFolders = @(Get-Item $imgDir)
            }
            else {
                Write-Error ("SKIPPED: No GuestAgent_* folders found under '$hostWaFolder' and ImagePath resolution failed. " +
                    "Cannot copy agent binaries to the offline disk.")
                return
            }
        }

        # ------------------------------------------------------------------
        # Step 2: Backup existing WindowsAzure folder on the offline disk
        # ------------------------------------------------------------------
        $offlineWaRoot = Join-Path $script:WinDriveLetter 'WindowsAzure'
        if (Test-Path $offlineWaRoot) {
            $bakPath = New-UniqueBackupPath -BasePath $offlineWaRoot -BakSuffix '.old'
            Write-Host "  Renaming existing WindowsAzure folder -> $bakPath" -ForegroundColor Yellow
            Move-Item-Logged -LiteralPath $offlineWaRoot -Destination $bakPath -Force
        }
        New-Item-Logged -Path $offlineWaRoot -ItemType Directory -Force

        # ------------------------------------------------------------------
        # Step 3: Copy GuestAgent folder(s) to the offline disk
        # ------------------------------------------------------------------
        foreach ($folder in $agentFolders) {
            $dest = Join-Path $offlineWaRoot $folder.Name
            Write-Host "  Copying $($folder.Name) -> $dest" -ForegroundColor Cyan
            Copy-Item-Logged -Path $folder.FullName -Destination $dest -Recurse -Force
        }

        # ------------------------------------------------------------------
        # Step 4 + 5: Import service registry keys into the offline SYSTEM hive
        # ------------------------------------------------------------------
        Invoke-WithHive 'SYSTEM' {
            $csName = Get-CurrentOfflineControlSetName

            foreach ($svc in $requiredSvcs) {
                $srcReg = "HKLM\SYSTEM\ControlSet001\Services\$svc"
                $dstReg = "HKLM\BROKENSYSTEM\$csName\Services\$svc"

                Write-Host "  Copying registry: $svc -> offline $csName..." -ForegroundColor Cyan
                $copyResult = Invoke-NativeCommandLogged -Description 'Copy Azure VM Agent service registry key' -Details @{
                    Service = $svc
                    Source = $srcReg
                    Destination = $dstReg
                } -ScriptBlock { & reg.exe copy $srcReg $dstReg /s /f }
                if ($copyResult.ExitCode -ne 0) {
                    throw "reg.exe copy failed for '$svc': $($copyResult.Output -join "`n")"
                }

                # Ensure Start = 2 (Automatic) - the copied key may have a different value
                Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\$csName\Services\$svc" `
                    -Name Start -Value 2 -Type DWord -Force
            }

            # RdAgent depends on TermService; make sure it isn't hard-disabled
            $termSvcPath = "HKLM:\BROKENSYSTEM\$csName\Services\TermService"
            if (Test-Path $termSvcPath) {
                $tsBefore = (Get-ItemProperty $termSvcPath -ErrorAction SilentlyContinue).Start
                if ($tsBefore -eq 4) {
                    Write-Host "  TermService was Disabled - re-enabling to Auto." -ForegroundColor Yellow
                    Set-ItemProperty-Logged -Path $termSvcPath -Name Start -Value 2 -Type DWord -Force
                }
            }

            Write-Host "`nAzure VM Agent installed offline successfully." -ForegroundColor Green
            Write-Host "  Agent binaries : $offlineWaRoot" -ForegroundColor Green
            Write-Host "  Registry keys  : BROKENSYSTEM\$csName\Services\{WindowsAzureGuestAgent,RdAgent}" -ForegroundColor Green
            Write-Host "  After booting the VM, verify the agent with: Get-Service WindowsAzureGuestAgent" -ForegroundColor Cyan
        }
    }

    function Get-DeviceClassFilterSpec {
        # Shared metadata for device class UpperFilters/LowerFilters checks.
        # SafeFilters are known Windows inbox / Azure-expected filter names (case-insensitive).
        # AllowVendors are additional binary CompanyName substrings beyond Microsoft.
        $selectedBuild = 0
        $isWindowsServer2012R2 = $false
        if ($script:SelectedWindowsInstall -and [int]::TryParse([string]$script:SelectedWindowsInstall.CurrentBuildNumber, [ref]$selectedBuild)) {
            $isWindowsServer2012R2 = ($selectedBuild -eq 9600)
        }
        if (-not $isWindowsServer2012R2 -and -not [string]::IsNullOrWhiteSpace($script:WinDriveLetter)) {
            $kernelPath = Join-Path $script:WinDriveLetter 'Windows\System32\ntoskrnl.exe'
            $kernelItem = Get-Item -LiteralPath $kernelPath -Force -ErrorAction SilentlyContinue
            $versionText = if ($kernelItem) { "$($kernelItem.VersionInfo.ProductVersion) $($kernelItem.VersionInfo.FileVersion)" } else { '' }
            $isWindowsServer2012R2 = ($versionText -match '(?i)\b6\.3\.9600\b|\b9600\b')
        }

        $diskDriveSafeFilters = [string[]]@('partmgr', 'fvevol', 'iorate', 'storqosflt', 'wcifs', 'ehstorclass')
        if ($isWindowsServer2012R2) {
            # Windows Server 2012 R2 Azure/Hyper-V images can legitimately carry storflt
            # as a DiskDrive LowerFilters entry. Treat it as expected for build 9600 only.
            $diskDriveSafeFilters += 'storflt'
        }

        return @(
            [PSCustomObject]@{
                GUID         = '{4d36e967-e325-11ce-bfc1-08002be10318}'
                Name         = 'DiskDrive'
                Risk         = 'CRITICAL'
                Description  = 'Extra filters in this class can contribute to stop error 0x7B (INACCESSIBLE_BOOT_DEVICE) on boot'
                SafeFilters  = $diskDriveSafeFilters
                AllowVendors = [string[]]@()
            }
            [PSCustomObject]@{
                GUID         = '{4d36e96a-e325-11ce-bfc1-08002be10318}'
                Name         = 'HDC'
                Risk         = 'CRITICAL'
                Description  = 'Extra filters on IDE ATA/ATAPI controllers can contribute to stop error 0x7B (INACCESSIBLE_BOOT_DEVICE)'
                SafeFilters  = [string[]]@('iasf', 'iastorf', 'iaStorAV')
                AllowVendors = [string[]]@()
            }
            [PSCustomObject]@{
                GUID         = '{4d36e97b-e325-11ce-bfc1-08002be10318}'
                Name         = 'SCSIAdapter'
                Risk         = 'CRITICAL'
                Description  = 'Extra filters on SCSI adapters can contribute to stop error 0x7B (INACCESSIBLE_BOOT_DEVICE)'
                SafeFilters  = [string[]]@('iaStorAV')
                AllowVendors = [string[]]@()
            }
            [PSCustomObject]@{
                GUID         = '{4d36e97d-e325-11ce-bfc1-08002be10318}'
                Name         = 'System'
                Risk         = 'CRITICAL'
                Description  = 'Extra filters on System devices can affect boot bus or PCI enumeration and may contribute to stop error 0x7B (INACCESSIBLE_BOOT_DEVICE)'
                SafeFilters  = [string[]]@()
                AllowVendors = [string[]]@()
            }
            [PSCustomObject]@{
                GUID         = '{71a27cdd-812a-11d0-bec7-08002be2092f}'
                Name         = 'Volume'
                Risk         = 'HIGH'
                Description  = 'Extra filters in this class can contribute to boot failures or volume access issues'
                SafeFilters  = [string[]]@('volsnap', 'fvevol', 'rdyboost', 'spldr', 'volmgrx', 'iorate', 'storqosflt')
                AllowVendors = [string[]]@()
            }
            [PSCustomObject]@{
                GUID         = '{4d36e972-e325-11ce-bfc1-08002be10318}'
                Name         = 'Net'
                Risk         = 'HIGH'
                Description  = 'Extra filters in this class can affect network connectivity'
                SafeFilters  = [string[]]@('wfplwf', 'ndiscap', 'ndisimplatformmpfilter', 'vmsproxyhnicfilter', 'vms3cap', 'mslldp', 'psched', 'bridge')
                AllowVendors = [string[]]@('Mellanox', 'NVIDIA')
            }
        )
    }

    function FixDeviceClassFilters {
        param([switch]$KeepDefaultFilters)
        # Scans UpperFilters and LowerFilters for key device class GUIDs identified by Microsoft
        # as critical for boot and network connectivity on Azure VMs.
        #
        # Classes checked (from MS troubleshooting docs):
        #   {4d36e967} DiskDrive   - extra filters can contribute to stop error 0x7B
        #   {4d36e96a} HDC/IDE     - extra filters can contribute to stop error 0x7B
        #   {4d36e97b} SCSIAdapter - extra filters can contribute to stop error 0x7B
        #   {4d36e97d} System      - extra filters can affect boot bus/PCI enumeration
        #   {71a27cdd} Volume      - extra filters can affect boot or volume access
        #   {4d36e972} Net         - extra filters can affect network connectivity
        #
        # Decision logic per filter entry (in order of precedence):
        #   1. Binary is missing from offline disk              -> REMOVE (dangling filter may BSOD/hang on boot)
        #   2. Name is in the known-safe list for that class    -> KEEP
        #   3. (skipped when -KeepDefaultFilters) Same entry exists in the host's live class key -> KEEP
        #   4. (skipped when -KeepDefaultFilters) Binary found on offline disk and CompanyName matches Microsoft or an allowed vendor -> KEEP
        #   5. Anything else                                    -> REMOVE and log
        #
        # Special allowances:
        #   Network class: Mellanox/NVIDIA drivers are expected on Azure VMs (Mellanox VF/MANA).
        #
        # GUIDs:
        #   Disk drive     : {4d36e967-e325-11ce-bfc1-08002be10318}
        #   HDC / IDE      : {4d36e96a-e325-11ce-bfc1-08002be10318}
        #   SCSI Adapter   : {4d36e97b-e325-11ce-bfc1-08002be10318}
        #   System devices : {4d36e97d-e325-11ce-bfc1-08002be10318}
        #   Volume         : {71a27cdd-812a-11d0-bec7-08002be2092f}
        #   Net adapter    : {4d36e972-e325-11ce-bfc1-08002be10318}

        Write-Host "Scanning device class and boot-critical device instance UpperFilters/LowerFilters for unsafe entries..." -ForegroundColor Yellow
        if ($KeepDefaultFilters) {
            Write-Host "  Mode: strict (-KeepDefaultFilters) - only inbox safe-list entries will be kept; Microsoft-signed non-defaults will be removed." -ForegroundColor Cyan
        }
        Invoke-WithHive 'SYSTEM' {
            $systemRoot = Get-SystemRootPath
            if (-not (Test-Path $systemRoot)) {
                Write-Warning "Active offline ControlSet path was not found: $systemRoot"
                return
            }
            $controlSetNames = [string[]]@(Split-Path -Path $systemRoot -Leaf)

            $classChecks = @(Get-DeviceClassFilterSpec)

            $anyChanges = $false

            foreach ($csName in $controlSetNames) {
                $classRoot = "HKLM:\BROKENSYSTEM\$csName\Control\Class"
                Write-Host "`n  Control set: $csName" -ForegroundColor DarkCyan

                foreach ($classDef in $classChecks) {
                $classPath = "$classRoot\$($classDef.GUID)"
                if (-not (Test-Path $classPath)) {
                    Write-Host "  [$($classDef.Name) $($classDef.GUID)] Class key not found in offline hive - skipping." -ForegroundColor DarkGray
                    continue
                }

                $riskColor = if ($classDef.Risk -eq 'CRITICAL') { 'Red' } else { 'Yellow' }
                Write-Host "`n  [$($classDef.Name)] $($classDef.Description)" -ForegroundColor Cyan

                # Build host reference path (compare against healthy running system)
                $hostClassPath = "HKLM:\SYSTEM\$csName\Control\Class\$($classDef.GUID)"
                if (-not (Test-Path $hostClassPath)) {
                    $hostClassPath = "HKLM:\SYSTEM\ControlSet001\Control\Class\$($classDef.GUID)"
                }

                foreach ($filterType in @('UpperFilters', 'LowerFilters')) {
                    $raw = (Get-ItemProperty $classPath -ErrorAction SilentlyContinue).$filterType
                    # Normalise: remove nulls/blanks, trim whitespace
                    $currentFilters = @($raw | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })

                    if ($currentFilters.Count -eq 0) {
                        Write-Host "    $filterType : (empty)" -ForegroundColor DarkGray
                        continue
                    }

                    $hostFilters = @()
                    if (Test-Path $hostClassPath) {
                        $hostRaw = (Get-ItemProperty $hostClassPath -ErrorAction SilentlyContinue).$filterType
                        $hostFilters = @($hostRaw | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                    }

                    Write-Host "    $filterType (offline) : $($currentFilters -join ', ')" -ForegroundColor White
                    if ($hostFilters.Count -gt 0) {
                        Write-Host "    $filterType (host ref): $($hostFilters -join ', ')" -ForegroundColor DarkGray
                    }

                    $toKeep = [System.Collections.Generic.List[string]]::new()
                    $removed = [System.Collections.Generic.List[string]]::new()

                    foreach ($filter in $currentFilters) {
                        # Resolve the binary path for all checks
                        $svcRegPath = "HKLM:\BROKENSYSTEM\$csName\Services\$filter"
                        $imgPathRaw = (Get-ItemProperty $svcRegPath -ErrorAction SilentlyContinue).ImagePath
                        $imgResolved = $null
                        $company = $null
                        if ($imgPathRaw) {
                            $imgResolved = Resolve-GuestImagePath $imgPathRaw
                            if (Test-Path $imgResolved) {
                                $company = (Get-Item $imgResolved -ErrorAction SilentlyContinue).VersionInfo.CompanyName
                            }
                        }

                        # Priority 1: binary missing or 0 bytes on offline disk -> dangling filter, may BSOD/hang on boot
                        $binaryMissing = ($null -eq $imgPathRaw) -or ($null -ne $imgResolved -and -not (Test-Path $imgResolved))
                        $binaryZero = (-not $binaryMissing -and $null -ne $imgResolved -and (Test-Path $imgResolved) -and (Get-Item -LiteralPath $imgResolved -ErrorAction SilentlyContinue).Length -eq 0)
                        if ($binaryMissing -or $binaryZero) {
                            $reason = if ($null -eq $imgPathRaw) { 'no ImagePath in registry' } elseif ($binaryZero) { "binary is 0 bytes (corrupt): $imgResolved" } else { "binary not found: $imgResolved" }
                            Write-Host "      [REMOVE] $filter - DANGLING FILTER ($reason) - may cause BSOD/hang on boot" -ForegroundColor Red
                            Write-ActionLog -Event 'DeviceFilterRemoved' -Details @{
                                Class      = $classDef.Name
                                GUID       = $classDef.GUID
                                FilterType = $filterType
                                Filter     = $filter
                                Company    = $null
                                Risk       = $classDef.Risk
                                Reason     = 'DanglingFilter'
                            }
                            $removed.Add($filter)
                            $anyChanges = $true
                            continue
                        }

                        # Priority 2: known-safe list (case-insensitive)
                        if ($classDef.SafeFilters -icontains $filter) {
                            $toKeep.Add($filter)
                            Write-Host "      [KEEP  ] $filter - known safe default" -ForegroundColor Green
                            continue
                        }

                        # Priority 3: present on healthy host reference (skipped in strict mode)
                        if (-not $KeepDefaultFilters -and $hostFilters -icontains $filter) {
                            $toKeep.Add($filter)
                            Write-Host "      [KEEP  ] $filter - present on host reference system" -ForegroundColor Green
                            continue
                        }

                        # Priority 4: binary company name matches an allowed vendor (skipped in strict mode)
                        $isMicrosoftBinary = $company -match 'Microsoft'
                        $isAllowedVendor = $classDef.AllowVendors | Where-Object { $_ -and $company -match $_ }

                        if (-not $KeepDefaultFilters -and ($isMicrosoftBinary -or $isAllowedVendor)) {
                            $toKeep.Add($filter)
                            Write-Host "      [KEEP  ] $filter - company: '$company'" -ForegroundColor Green
                        }
                        else {
                            # Remove: either strict mode (non-safe-list) or non-Microsoft third-party
                            $vendorInfo = if ($company) { "company: '$company'" } else { 'no version info' }
                            $removeReason = if ($KeepDefaultFilters -and ($isMicrosoftBinary -or $isAllowedVendor)) {
                                "not in safe-list (strict mode)"
                            }
                            else {
                                "non-Microsoft third-party filter ($vendorInfo)"
                            }
                            Write-Host "      [REMOVE] $filter - $removeReason" -ForegroundColor $riskColor
                            Write-ActionLog -Event 'DeviceFilterRemoved' -Details @{
                                Class      = $classDef.Name
                                GUID       = $classDef.GUID
                                FilterType = $filterType
                                Filter     = $filter
                                Company    = $company
                                Risk       = $classDef.Risk
                                Reason     = if ($KeepDefaultFilters) { 'StrictMode-NotInSafeList' } else { 'NonMicrosoftVendor' }
                            }
                            $removed.Add($filter)
                            $anyChanges = $true
                        }
                    }

                    if ($removed.Count -gt 0) {
                        if ($toKeep.Count -gt 0) {
                            Set-ItemProperty-Logged -Path $classPath -Name $filterType `
                                -Value ([string[]]$toKeep) -Type MultiString -Force
                        }
                        else {
                            # No entries remain - remove the value entirely rather than leaving an empty MultiString
                            Remove-ItemProperty-Logged -Path $classPath -Name $filterType -Force
                        }
                        Write-Host "      Removed: $($removed -join ', ')  |  Kept: $(if ($toKeep.Count) { $toKeep -join ', ' } else { '(none)' })" -ForegroundColor Yellow
                    }
                }
            }
            }

            $instanceFilterFindings = @(Get-BootCriticalDeviceInstanceFilterFindings -ControlSetNames $controlSetNames)
            if ($instanceFilterFindings.Count -gt 0) {
                Write-Host "`n  [Boot-critical device instances] UpperFilters/LowerFilters can affect PCI/VMBus enumeration and may contribute to stop error 0x7B" -ForegroundColor Cyan
                foreach ($finding in $instanceFilterFindings) {
                    Write-Host "    $($finding.ControlSet) $($finding.Device) $($finding.FilterType): $($finding.Filters -join ', ')" -ForegroundColor White
                    Write-Host "      [REMOVE] $($finding.Filters -join ', ') - boot-critical device instance filter" -ForegroundColor Red
                    Write-ActionLog -Event 'DeviceInstanceFilterRemoved' -Details @{
                        ControlSet  = $finding.ControlSet
                        Device      = $finding.Device
                        Service     = $finding.Service
                        FilterType  = $finding.FilterType
                        Filters     = $finding.Filters
                        Risk        = 'CRITICAL'
                        Reason      = 'BootCriticalDeviceInstanceFilter'
                    }
                    Remove-ItemProperty-Logged -Path $finding.RegistryPath -Name $finding.FilterType -Force
                    $anyChanges = $true
                }
            }

            if ($anyChanges) {
                Write-Host "`nDevice filter cleanup complete." -ForegroundColor Green
                Write-Warning ("If a legitimate product (backup agent, endpoint security, storage appliance) " +
                    "requires a removed filter, restore it from the action log and re-evaluate.")
            }
            else {
                Write-Host "`nNo unsafe device class or boot-critical device instance filters found. No changes made." -ForegroundColor Green
            }
        }
    }

    function FixSessionManagerBootEntries {
        # Scans the Session Manager registry key for known boot-blocking issues:
        #   1. BootExecute  - Native NT executables run by Smss.exe before Win32 starts.
        #      Default: "autocheck autochk *". Third-party entries whose binaries are missing
        #      from the offline disk will hang the system at a black screen (pre-Win32, no recovery).
        #   2. SetupExecute - Same execution context as BootExecute. Should be empty in normal
        #      operation; non-empty entries with missing binaries are equally fatal.
        #   3. ExcludeFromKnownDlls - Forces the loader to skip the KnownDlls section for listed
        #      DLLs, loading them from the application directory instead. Legitimate uses exist
        #      (app compat shims) but this is also a common DLL hijack/preloading vector.
        #
        # Decision logic for BootExecute / SetupExecute entries:
        #   - "autocheck autochk *" is the only default BootExecute entry (always kept).
        #   - For every other entry, the first token is the native executable name.
        #     Resolve it to <offline>\Windows\System32\<name>.exe and check existence.
        #   - Missing binary  -> REMOVE (will hang boot at black screen, no error message)
        #   - Present binary  -> KEEP but flag as third-party informational

        Write-Host "Scanning Session Manager boot entries for unsafe/dangling programs..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $csName = Get-CurrentOfflineControlSetName
            $smPath = "HKLM:\BROKENSYSTEM\$csName\Control\Session Manager"

            if (-not (Test-Path $smPath)) {
                Write-Host "  Session Manager key not found at $smPath - skipping." -ForegroundColor DarkGray
                return
            }

            $smProps = Get-ItemProperty $smPath -ErrorAction SilentlyContinue
            $anyChanges = $false

            # -- BootExecute ------------------------------------------------------
            $bootExec = @($smProps.BootExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
            Write-Host "`n  BootExecute entries ($($bootExec.Count)):" -ForegroundColor Cyan
            if ($bootExec.Count -eq 0) {
                Write-Host "    (empty) - WARNING: missing default 'autocheck autochk *' entry" -ForegroundColor Yellow
            }

            $toKeep = [System.Collections.Generic.List[string]]::new()
            $removed = [System.Collections.Generic.List[string]]::new()
            $sys32 = Join-Path $script:WinDriveLetter 'Windows\System32'

            foreach ($entry in $bootExec) {
                # The default entry: always keep
                if ($entry -match '^autocheck\s+autochk') {
                    $toKeep.Add($entry)
                    Write-Host "    [KEEP  ] $entry - Windows default" -ForegroundColor Green
                    continue
                }

                # Extract the native executable name (first token)
                $tokens = $entry -split '\s+', 2
                $nativeName = $tokens[0]
                $nativePath = Join-Path $sys32 "$nativeName.exe"

                if (-not (Test-Path $nativePath) -or (Get-Item -LiteralPath $nativePath -ErrorAction SilentlyContinue).Length -eq 0) {
                    $reason = if (-not (Test-Path $nativePath)) { "binary not found: $nativePath" } else { "binary is 0 bytes (corrupt): $nativePath" }
                    Write-Host "    [REMOVE] $entry - $reason (will hang boot at black screen)" -ForegroundColor Red
                    Write-ActionLog -Event 'SessionManagerEntryRemoved' -Details @{
                        ValueName = 'BootExecute'
                        Entry     = $entry
                        Expected  = $nativePath
                        Reason    = 'DanglingNativeExecutable'
                    }
                    $removed.Add($entry)
                    $anyChanges = $true
                }
                else {
                    $company = (Get-Item $nativePath -ErrorAction SilentlyContinue).VersionInfo.CompanyName
                    $vendorInfo = if ($company) { "company: '$company'" } else { 'no version info' }
                    $toKeep.Add($entry)
                    Write-Host "    [KEEP  ] $entry - third-party ($vendorInfo)" -ForegroundColor Yellow
                    Write-Host "             Binary: $nativePath" -ForegroundColor DarkGray
                }
            }

            if ($removed.Count -gt 0) {
                if ($toKeep.Count -gt 0) {
                    Set-ItemProperty-Logged -Path $smPath -Name 'BootExecute' `
                        -Value ([string[]]$toKeep) -Type MultiString -Force
                }
                else {
                    # Restore the default rather than leaving empty (empty = no autochk = potential FS corruption)
                    Set-ItemProperty-Logged -Path $smPath -Name 'BootExecute' `
                        -Value ([string[]]@('autocheck autochk *')) -Type MultiString -Force
                }
                Write-Host "    Removed $($removed.Count) dangling BootExecute entry/entries." -ForegroundColor Yellow
            }

            # -- SetupExecute -----------------------------------------------------
            $setupExec = @($smProps.SetupExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
            if ($setupExec.Count -gt 0) {
                Write-Host "`n  SetupExecute entries ($($setupExec.Count)):" -ForegroundColor Cyan
                $setupKeep = [System.Collections.Generic.List[string]]::new()
                $setupRemoved = [System.Collections.Generic.List[string]]::new()

                foreach ($entry in $setupExec) {
                    $tokens = $entry -split '\s+', 2
                    $nativeName = $tokens[0]
                    $nativePath = Join-Path $sys32 "$nativeName.exe"

                    if (-not (Test-Path $nativePath) -or (Get-Item -LiteralPath $nativePath -ErrorAction SilentlyContinue).Length -eq 0) {
                        $reason = if (-not (Test-Path $nativePath)) { "binary not found: $nativePath" } else { "binary is 0 bytes (corrupt): $nativePath" }
                        Write-Host "    [REMOVE] $entry - $reason (will hang boot)" -ForegroundColor Red
                        Write-ActionLog -Event 'SessionManagerEntryRemoved' -Details @{
                            ValueName = 'SetupExecute'
                            Entry     = $entry
                            Expected  = $nativePath
                            Reason    = 'DanglingNativeExecutable'
                        }
                        $setupRemoved.Add($entry)
                        $anyChanges = $true
                    }
                    else {
                        $company = (Get-Item $nativePath -ErrorAction SilentlyContinue).VersionInfo.CompanyName
                        $vendorInfo = if ($company) { "company: '$company'" } else { 'no version info' }
                        $setupKeep.Add($entry)
                        Write-Host "    [KEEP  ] $entry - third-party ($vendorInfo)" -ForegroundColor Yellow
                    }
                }

                if ($setupRemoved.Count -gt 0) {
                    if ($setupKeep.Count -gt 0) {
                        Set-ItemProperty-Logged -Path $smPath -Name 'SetupExecute' `
                            -Value ([string[]]$setupKeep) -Type MultiString -Force
                    }
                    else {
                        Remove-ItemProperty-Logged -Path $smPath -Name 'SetupExecute' -Force
                    }
                    Write-Host "    Removed $($setupRemoved.Count) dangling SetupExecute entry/entries." -ForegroundColor Yellow
                }
            }
            else {
                Write-Host "`n  SetupExecute: (empty - normal)" -ForegroundColor DarkGray
            }

            # -- ExcludeFromKnownDlls ---------------------------------------------
            $knownDllExcl = @($smProps.ExcludeFromKnownDlls | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
            if ($knownDllExcl.Count -gt 0) {
                Write-Host "`n  ExcludeFromKnownDlls ($($knownDllExcl.Count) entries):" -ForegroundColor Cyan
                foreach ($dll in $knownDllExcl) {
                    Write-Host "    [FLAG  ] $dll - DLL excluded from KnownDlls (app compat or potential DLL hijack vector)" -ForegroundColor Yellow
                }
                Write-Warning "ExcludeFromKnownDlls entries are not auto-removed (may be required by legitimate software). Review manually."
            }
            else {
                Write-Host "`n  ExcludeFromKnownDlls: (empty - normal)" -ForegroundColor DarkGray
            }

            if ($anyChanges) {
                Write-Host "`nSession Manager boot entry cleanup complete." -ForegroundColor Green
                Write-Warning "Removed entries were native executables with missing binaries that would have caused the VM to hang during boot (pre-Win32, no error screen)."
            }
            else {
                Write-Host "`nNo unsafe Session Manager entries found. No changes made." -ForegroundColor Green
            }
        }
    }

    function ScanNetAdapterBindings {
        # Read-only diagnostic: enumerates all installed network binding components
        # (protocols, services, clients) in the offline disk and flags third-party ones.
        # A component is considered third-party when its ComponentId does not start with "ms_".
        # This mirrors the live-system command:
        #   Get-NetAdapterBinding -AllBindings -IncludeHidden | Where ComponentID -notmatch '^ms_'

        Write-Host "Scanning offline disk for third-party network binding components..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            & {
                $csName = Get-CurrentOfflineControlSetName

                # -- Adapter inventory ----------------------------------------------------
                # Friendly-name lookup: {GUID} -> adapter name (e.g. "Ethernet")
                $adapterNames = @{}
                $netNetKey = "HKLM:\BROKENSYSTEM\$csName\Control\Network\{4D36E972-E325-11CE-BFC1-08002BE10318}"
                if (Test-Path $netNetKey) {
                    Get-ChildItem $netNetKey -ErrorAction SilentlyContinue | ForEach-Object {
                        $connName = (Get-ItemProperty "$($_.PSPath)\Connection" -ErrorAction SilentlyContinue).Name
                        if ($connName) { $adapterNames[$_.PSChildName.ToUpper()] = $connName }
                    }
                }

                # Hardware-description lookup: {GUID} -> DriverDesc (e.g. "Mellanox VF")
                $adapterDescs = @{}
                $netClassKey = "HKLM:\BROKENSYSTEM\$csName\Control\Class\{4D36E972-E325-11CE-BFC1-08002BE10318}"
                if (Test-Path $netClassKey) {
                    Get-ChildItem $netClassKey -ErrorAction SilentlyContinue |
                    Where-Object { $_.PSChildName -match '^\d{4}$' } |
                    ForEach-Object {
                        $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                        if ($p.NetCfgInstanceId) {
                            $adapterDescs[$p.NetCfgInstanceId.ToUpper()] = $p.DriverDesc
                        }
                    }
                }

                # Print adapter table
                Write-Host "`nNetwork adapters found in offline disk:" -ForegroundColor Cyan
                $adapterRows = foreach ($guid in ($adapterDescs.Keys | Sort-Object)) {
                    $friendlyGuid = $guid   # already upper, with braces or without - normalise
                    $cleanGuid = $friendlyGuid.Trim('{', '}')
                    [PSCustomObject]@{
                        FriendlyName = $adapterNames[$cleanGuid]
                        Description  = $adapterDescs[$guid]
                        GUID         = "{$cleanGuid}"
                    }
                }
                if ($adapterRows) {
                    $adapterRows | Format-Table FriendlyName, Description, GUID -AutoSize | Out-String | Write-Host
                }
                else {
                    Write-Host "  (none found)" -ForegroundColor DarkGray
                }

                # -- Component enumeration -------------------------------------------------
                # Network protocol/service/client software components each live under a
                # numbered instance key inside their Class GUID.
                $componentClasses = @(
                    [PSCustomObject]@{ GUID = '{4D36E973-E325-11CE-BFC1-08002BE10318}'; Type = 'Client' }
                    [PSCustomObject]@{ GUID = '{4D36E974-E325-11CE-BFC1-08002BE10318}'; Type = 'Service' }
                    [PSCustomObject]@{ GUID = '{4D36E975-E325-11CE-BFC1-08002BE10318}'; Type = 'Protocol' }
                )

                $allComponents = [System.Collections.Generic.List[PSCustomObject]]::new()

                foreach ($classInfo in $componentClasses) {
                    $classKey = "HKLM:\BROKENSYSTEM\$csName\Control\Class\$($classInfo.GUID)"
                    if (-not (Test-Path $classKey)) { continue }

                    Get-ChildItem $classKey -ErrorAction SilentlyContinue |
                    Where-Object { $_.PSChildName -match '^\d{4}$' } |
                    ForEach-Object {
                        $props = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                        # ComponentId casing varies across Windows versions
                        $componentId = $props.ComponentId
                        if (-not $componentId) { $componentId = $props.ComponentID }
                        if (-not $componentId) { return }

                        # Service name: prefer explicit Ndi\Service, fall back to stripping 'ms_' prefix
                        $ndiProps = Get-ItemProperty "$($_.PSPath)\Ndi" -ErrorAction SilentlyContinue
                        $serviceName = if ($ndiProps -and $ndiProps.Service) { $ndiProps.Service }
                        else { $componentId -replace '^ms_', '' }

                        # Bound-adapter list from Services\<svc>\Linkage\Bind
                        $boundAdapters = @()
                        $linkagePath = "HKLM:\BROKENSYSTEM\$csName\Services\$serviceName\Linkage"
                        if (Test-Path $linkagePath) {
                            $linkage = Get-ItemProperty $linkagePath -ErrorAction SilentlyContinue
                            $disabledList = @($linkage.Disabled | Where-Object { $_ })
                            foreach ($b in @($linkage.Bind | Where-Object { $_ })) {
                                # Bind entries look like: \Device\{GUID} or \Device\{GUID}_N
                                if ($b -match '\{([0-9A-Fa-f\-]+)\}') {
                                    $g = $Matches[1].ToUpper()
                                    $name = $adapterNames[$g]
                                    $desc = $adapterDescs["{$g}"]
                                    $label = if ($name) { $name } elseif ($desc) { $desc } else { "{$g}" }
                                    $boundAdapters += if ($disabledList -icontains $b) { "$label [disabled]" } else { $label }
                                }
                            }
                        }

                        # Binary presence on the offline disk
                        $imgPathRaw = (Get-ItemProperty "HKLM:\BROKENSYSTEM\$csName\Services\$serviceName" -ErrorAction SilentlyContinue).ImagePath
                        $binaryFound = $null
                        if ($imgPathRaw) {
                            $imgResolved = Resolve-GuestImagePath $imgPathRaw
                            $binaryFound = Test-Path $imgResolved
                        }

                        $allComponents.Add([PSCustomObject]@{
                                ComponentId   = $componentId
                                Type          = $classInfo.Type
                                DisplayName   = $props.DriverDesc
                                ServiceName   = $serviceName
                                IsThirdParty  = ($componentId -notmatch '^ms_')
                                BoundAdapters = ($boundAdapters -join '; ')
                                BinaryFound   = $binaryFound
                            })
                    }
                }

                # Deduplicate in case the same ComponentId appears in multiple class GUIDs
                $seen = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                $components = $allComponents | Where-Object { $seen.Add($_.ComponentId) }

                $firstParty = @($components | Where-Object { -not $_.IsThirdParty })
                $thirdParty = @($components | Where-Object { $_.IsThirdParty } | Sort-Object ComponentId)

                # -- Report ----------------------------------------------------------------
                Write-Host "First-party binding components (ms_*): $($firstParty.Count)" -ForegroundColor DarkGray

                if ($thirdParty.Count -eq 0) {
                    Write-Host "`nNo third-party network binding components found." -ForegroundColor Green
                }
                else {
                    Write-Host "`nThird-party network binding components: $($thirdParty.Count)" -ForegroundColor Yellow
                    Write-Host "  ComponentId does not start with 'ms_' - these extend the network stack at boot." -ForegroundColor DarkYellow
                    Write-Host ""

                    foreach ($c in $thirdParty) {
                        if ($c.BinaryFound -eq $false) {
                            $presenceTag = 'BINARY MISSING'
                            $color = 'Red'
                        }
                        elseif ($c.BinaryFound -eq $true) {
                            $presenceTag = 'binary present'
                            $color = 'Yellow'
                        }
                        else {
                            $presenceTag = 'no ImagePath registered'
                            $color = 'DarkYellow'
                        }

                        Write-Host "  [$($c.Type.PadRight(8))] $($c.ComponentId.PadRight(32)) $($c.DisplayName)" -ForegroundColor $color
                        Write-Host "             Service : $($c.ServiceName)  |  $presenceTag" -ForegroundColor $color
                        if ($c.BoundAdapters) {
                            Write-Host "             Bound to: $($c.BoundAdapters)" -ForegroundColor DarkYellow
                        }
                        else {
                            Write-Host "             Bound to: (linkage not cached offline - resolved at boot)" -ForegroundColor DarkGray
                        }
                        Write-Host ""
                    }

                    Write-Warning ("Third-party network components extend the network stack. " +
                        "If the VM has no network connectivity after boot, these components " +
                        "may be interfering. Use -FixDeviceFilters to scan NDIS UpperFilters/LowerFilters.")
                }

                Write-ActionLog -Event 'ScanNetAdapterBindings' -Details @{
                    AdapterCount    = $adapterRows.Count
                    FirstPartyCount = $firstParty.Count
                    ThirdPartyCount = $thirdParty.Count
                    ThirdPartyIds   = ($thirdParty | ForEach-Object ComponentId) -join ', '
                }
            }
        }
    }

    function RemoveOrphanedNetBindings {
        # Removes third-party network binding components whose driver binary is missing on the offline disk.
        # A dangling binding component can cause ndis.sys initialisation to fail on boot, leading to
        # network connectivity loss even when the NIC driver itself is healthy.
        #
        # This is the destructive counterpart to -ScanNetBindings. Run that first to preview.
        # Only components with an explicit ImagePath that resolves to a non-existent file are acted on;
        # components with no ImagePath at all are left untouched (they may be imageless by design).
        #
        # For each orphaned component:
        #   1. Removes the class instance key (Control\Class\{type-GUID}\NNNN)
        #   2. Disables the service (Services\<svc> Start = 4) to prevent any load attempt
        #   3. Clears Services\<svc>\Linkage\{Bind, Export, Route} to detach from all adapters

        Write-Host "Scanning for orphaned third-party network binding components (missing binary)..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            & {
                $csName = Get-CurrentOfflineControlSetName

                $componentClasses = @(
                    [PSCustomObject]@{ GUID = '{4D36E973-E325-11CE-BFC1-08002BE10318}'; Type = 'Client' }
                    [PSCustomObject]@{ GUID = '{4D36E974-E325-11CE-BFC1-08002BE10318}'; Type = 'Service' }
                    [PSCustomObject]@{ GUID = '{4D36E975-E325-11CE-BFC1-08002BE10318}'; Type = 'Protocol' }
                )

                $orphans = [System.Collections.Generic.List[PSCustomObject]]::new()
                $seen = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)

                foreach ($classInfo in $componentClasses) {
                    $classKey = "HKLM:\BROKENSYSTEM\$csName\Control\Class\$($classInfo.GUID)"
                    if (-not (Test-Path $classKey)) { continue }

                    Get-ChildItem $classKey -ErrorAction SilentlyContinue |
                    Where-Object { $_.PSChildName -match '^\d{4}$' } |
                    ForEach-Object {
                        $instPath = $_.PSPath
                        $props = Get-ItemProperty $instPath -ErrorAction SilentlyContinue
                        $componentId = if ($props.ComponentId) { $props.ComponentId } else { $props.ComponentID }
                        if (-not $componentId) { return }
                        # Deduplicate across class GUIDs
                        if (-not $seen.Add($componentId)) { return }
                        # Never touch first-party ms_ components
                        if ($componentId -match '^ms_') { return }

                        $ndiProps = Get-ItemProperty "$instPath\Ndi" -ErrorAction SilentlyContinue
                        $serviceName = if ($ndiProps -and $ndiProps.Service) { $ndiProps.Service }
                        else { $componentId -replace '^ms_', '' }

                        $imgPathRaw = (Get-ItemProperty "HKLM:\BROKENSYSTEM\$csName\Services\$serviceName" -ErrorAction SilentlyContinue).ImagePath
                        # No ImagePath -> skip; component may be imageless by design
                        if ($null -eq $imgPathRaw) { return }

                        $imgResolved = Resolve-GuestImagePath $imgPathRaw
                        # Binary present -> nothing to do
                        if (Test-Path $imgResolved) { return }

                        $orphans.Add([PSCustomObject]@{
                                ComponentId   = $componentId
                                Type          = $classInfo.Type
                                DisplayName   = $props.DriverDesc
                                ServiceName   = $serviceName
                                ClassKeyPath  = $instPath
                                MissingBinary = $imgResolved
                            })
                    }
                }

                if ($orphans.Count -eq 0) {
                    Write-Host "`nNo orphaned network binding components found. No changes made." -ForegroundColor Green
                    return
                }

                Write-Host "`nFound $($orphans.Count) orphaned network binding component(s) with missing binaries:" -ForegroundColor Red
                Write-Host ""

                foreach ($c in $orphans) {
                    Write-Host "  [$($c.Type.PadRight(8))] $($c.ComponentId)  --  $($c.DisplayName)" -ForegroundColor Red
                    Write-Host "             Service : $($c.ServiceName)" -ForegroundColor DarkRed
                    Write-Host "             Missing : $($c.MissingBinary)" -ForegroundColor DarkRed
                    Write-Host ""

                    # Step 1: Remove class instance key - de-registers the component from Windows
                    Write-Host "    [1/3] Removing class instance key..." -ForegroundColor Yellow
                    # Network class keys under Control\Class are frequently owned by
                    # TrustedInstaller, and Remove-Item-Logged swallows an access-denied
                    # delete, so the repair would report success having removed nothing.
                    [void](Remove-ProtectedRegistryKey -Path $c.ClassKeyPath -Label "class instance key $($c.ComponentId)")

                    # Step 2: Disable the service to prevent any load attempt at boot
                    $svcPath = "HKLM:\BROKENSYSTEM\$csName\Services\$($c.ServiceName)"
                    if (Test-Path $svcPath) {
                        Write-Host "    [2/3] Disabling service '$($c.ServiceName)' (Start -> 4)..." -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value 4 -Type DWord -Force
                    }
                    else {
                        Write-Host "    [2/3] Service key '$($c.ServiceName)' not found - skipping." -ForegroundColor DarkGray
                    }

                    # Step 3: Clear Linkage Bind/Export/Route to detach from all adapters
                    $linkPath = "HKLM:\BROKENSYSTEM\$csName\Services\$($c.ServiceName)\Linkage"
                    if (Test-Path $linkPath) {
                        Write-Host "    [3/3] Clearing Linkage bind entries..." -ForegroundColor Yellow
                        foreach ($val in @('Bind', 'Export', 'Route')) {
                            if ($null -ne (Get-ItemProperty $linkPath -ErrorAction SilentlyContinue).$val) {
                                Remove-ItemProperty-Logged -Path $linkPath -Name $val -Force
                            }
                        }
                    }
                    else {
                        Write-Host "    [3/3] No Linkage key found - nothing to clear." -ForegroundColor DarkGray
                    }

                    Write-ActionLog -Event 'OrphanedNetBindingRemoved' -Details @{
                        ComponentId   = $c.ComponentId
                        Type          = $c.Type
                        DisplayName   = $c.DisplayName
                        ServiceName   = $c.ServiceName
                        MissingBinary = $c.MissingBinary
                    }

                    Write-Host "    Done: $($c.ComponentId) removed." -ForegroundColor Green
                    Write-Host ""
                }

                Write-Host "Orphaned network binding cleanup complete. $($orphans.Count) component(s) removed." -ForegroundColor Green
                Write-Warning ("A full network-stack reset may still be needed. " +
                    "Consider also running -ResetNetworkStack to clear TCP/IP and Winsock state.")
            }
        }
    }

    function CopyACPISettings {
        # Copies legacy Hyper-V ACPI Enum entries to the newer ACPI device IDs.
        # Some Windows versions do not include the newer MSFT* keys, preventing
        # Hyper-V synthetic devices from being detected. This copies from the
        # legacy entries when they exist:
        #   VMBus                  -> MSFT1000
        #   Hyper_V_Gen_Counter_V1 -> MSFT1002

        Write-Host "Copying Hyper-V ACPI device entries to newer device IDs..." -ForegroundColor Cyan

        Invoke-WithHive 'SYSTEM' {
            $sysRoot = Get-SystemRootPath   # e.g. HKLM:\BROKENSYSTEM\ControlSet001
            # Convert PowerShell path to reg.exe syntax (no colon after HKLM)
            $regRoot = $sysRoot -replace '^HKLM:', 'HKLM'

            $copies = @(
                @{ SrcPs = "$sysRoot\Enum\ACPI\VMBus"; DstPs = "$sysRoot\Enum\ACPI\MSFT1000"; SrcReg = "$regRoot\Enum\ACPI\VMBus"; DstReg = "$regRoot\Enum\ACPI\MSFT1000"; Label = 'VMBus -> MSFT1000' }
                @{ SrcPs = "$sysRoot\Enum\ACPI\Hyper_V_Gen_Counter_V1"; DstPs = "$sysRoot\Enum\ACPI\MSFT1002"; SrcReg = "$regRoot\Enum\ACPI\Hyper_V_Gen_Counter_V1"; DstReg = "$regRoot\Enum\ACPI\MSFT1002"; Label = 'Hyper_V_Gen_Counter_V1 -> MSFT1002' }
            )

            $copied = 0
            foreach ($c in $copies) {
                if (-not (Test-Path $c.SrcPs)) {
                    Write-Warning "  Source key not found: $($c.SrcReg) - skipping $($c.Label)"
                    continue
                }
                # Run as SYSTEM to bypass ACL restrictions on the mounted offline hive
                ExecuteAsSystem "reg.exe copy `"$($c.SrcReg)`" `"$($c.DstReg)`" /s /f"
                # Verify the destination key was created
                if (Test-Path $c.DstPs) {
                    Write-Host "  [OK] Copied $($c.Label)" -ForegroundColor Green
                    $copied++
                }
                else {
                    Write-Warning "  reg copy $($c.Label) may have failed - destination key not found after copy"
                }
            }

            if ($copied -gt 0) {
                Write-Host "ACPI settings copied ($copied of $($copies.Count) pair(s))." -ForegroundColor Green
            }
            else {
                Write-Warning "No ACPI entries were copied - source keys may not exist on this disk."
            }

            Write-ActionLog -Event 'CopyACPISettings' -Details @{ RegRoot = $regRoot; Copied = $copied }
        }
    }

    function RunSystemCheck {
        # -------------------------------------------------------------------------
        # Read-only offline health scan. Checks BCD, registry, services, device
        # filters, networking, RDP, Azure Agent, security settings, crash
        # artifacts and Gen2 UEFI/Trusted Launch readiness (Secure Boot, vTPM,
        # VBS/HVCI, BitLocker, EarlyLaunch). At the end a prioritised summary is
        # printed with the exact -Parameter to run for each finding. The only
        # access repair made by this scan is for the protected mpssvc AppCs key:
        # if required to inspect DebugedLoopbackApps, SYSTEM takes ownership and
        # grants SYSTEM and Administrators FullControl.
        # -------------------------------------------------------------------------

        # Reuse guest computer name resolved earlier (stored in $script:GuestComputerName)
        $guestComputerName = $script:GuestComputerName
        $guestLabel = if ($guestComputerName) { "  Guest: $guestComputerName" } else { '' }

        Write-Host "`n===================================================================" -ForegroundColor Cyan
        Write-Host "  Offline System Health Check" -ForegroundColor Cyan
        Write-Host "  Disk $script:DiskNumber  |  Windows: $script:WinDriveLetter  |  Boot: $script:BootDriveLetter  |  Gen$script:VMGen$guestLabel" -ForegroundColor Cyan
        Write-Host "===================================================================`n" -ForegroundColor Cyan

        $findings = [System.Collections.Generic.List[PSCustomObject]]::new()
        $scriptFile = if ($PSCommandPath) { Split-Path -Leaf $PSCommandPath } else { 'Repair-AzVMDisk.ps1' }

        # Inline helper: emit one finding to the console and add it to $findings.
        # Called as: & $emit 'Category' 'CRIT|WARN|INFO|OK' 'Message' '-FixParam'
        $emit = {
            param([string]$Cat, [string]$Sev, [string]$Desc, [string]$Fix = '')
            $findings.Add([PSCustomObject]@{ Category = $Cat; Severity = $Sev; Description = $Desc; Fix = $Fix })
            $color = switch ($Sev) { 'CRIT' { 'Red' } 'WARN' { 'Yellow' } 'INFO' { 'Cyan' } default { 'Green' } }
            $prefix = switch ($Sev) { 'CRIT' { '[CRIT]' } 'WARN' { '[WARN]' } 'INFO' { '[INFO]' } default { '[ OK ]' } }
            Write-Host "  $prefix [$Cat] $Desc" -ForegroundColor $color
            if ($Fix) { Write-Host "         Suggestion: $Fix" -ForegroundColor DarkCyan }
        }

        # -- SysCheck severity configuration --------------------------------------
        # Controls how each finding is surfaced when it fires.
        # Values: 0 = INFO  |  1 = WARN  |  2 = CRIT
        # Change a value here to promote or demote any test without touching its logic.

        # Disk & Filesystem
        $sevDiskHealth = 2   # Disk HealthStatus is not Healthy
        $sevDiskRawFs = 2   # Partition has RAW filesystem (unreadable)
        $sevDiskFsHealth = 1   # Partition filesystem is unhealthy (non-NTFS or undetermined)
        $sevDiskDirtyBit = 1   # NTFS volume dirty bit is set (autochk runs chkdsk at next boot)
        $sevDiskSpotFix = 1   # NTFS spot-verifier logged corruption ($corrupt) - needs chkdsk /spotfix
        $sevNtfsAttrListNameOffset = 2   # Metafile attribute list entry uses a non-canonical name offset (mount failure, bugcheck 0x24)
        $sevNtfsAttrListUnknown = 2   # Non-canonical name offset outside the pattern this script repairs

        # Crash & Boot artefacts
        $sevCrashMinidumps = 1   # Minidump (.dmp) files found
        $sevBootNtbtlog = 0   # ntbtlog.txt present (check for DIDNOTLOAD)
        $sevUpdatePendingXml = 1   # pending.xml found (update boot loop risk)
        $sevUpdateTxRLogs = 1   # TxR transaction log files found
        $sevUpdateSmiLogs = 1   # SMI Store transaction log files found
        $sevUpdateLogFull = 2   # CBS.log reports 0x800719e4 / ERROR_LOG_FULL
        $sevSetupMode = 0   # SetupType active (Setup CmdLine will run at boot)

        # BCD / Boot Configuration
        $sevBcdMissing = 2   # BCD store not found
        $sevBcdNoBootLoader = 2   # No Windows Boot Loader entry in BCD
        $sevBcdSafeMode = 1   # Safe Mode flag active in BCD
        $sevBcdBootStatusPolicy = 0   # bootstatuspolicy IgnoreAllFailures set
        $sevBcdRecoveryDisabled = 0   # recoveryenabled Off
        $sevWinreDisabled = 1   # WinRE is disabled or not registered
        $sevWinreImageMissing = 1   # Winre.wim not found on mounted guest partitions
        $sevBcdTestSigning = 1   # Test signing ON
        $sevBcdUnknownDevice = 2   # BCD contains unknown device/path entries
        $sevBcdImcHive = 2   # BCD has imcdevice/imchivename entries (BSOD 0x67 CONFIG_INITIALIZATION_FAILED)
        $sevBootPartitionNotActive = 2   # Gen1 (MBR) boot partition not flagged as Active (BIOS cannot find boot sector)
        $sevBootPartitionMissing = 2   # Separate boot partition (System Reserved / EFI SP) not found on disk
        $sevBcdMultipleLoaders = 1   # More than one Windows Boot Loader entry found in BCD
        $sevBcdSetupEntry = 1   # BCD contains Windows Setup or other stale setup loader entries
        $sevMultipleWindowsInstalls = 1   # More than one Windows installation was detected on the disk
        $sevWindowsInstallSetupState = 1   # Selected Windows installation still shows setup/upgrade markers
        $sevWindowsInstallSelectionAmbiguous = 2   # Multiple Windows installations scored too closely to auto-pick confidently

        # Registry
        $sevHiveMissing = 2   # Expected registry hive file not found on disk
        $sevHiveEmpty = 2   # Expected registry hive file is 0 bytes (corrupt)
        $sevControlSetMismatch = 1   # Current ControlSet != Default
        $sevRegBackEmpty = 1   # RegBack\SYSTEM is 0 bytes
        $sevRegBackMissing = 0   # RegBack\SYSTEM not found

        # Critical Services
        $sevCriticalSvcDisabled = 2   # A critical boot/system driver is disabled
        $sevBootStorageReadiness = 2   # Boot storage Start/StartOverride settings may block migration boot

        # RDP
        $sevRdpDenied = 2   # fDenyTSConnections=1 (RDP explicitly disabled)
        $sevRdpDenyUnknown = 1   # fDenyTSConnections key missing
        $sevRdpSvcDisabledCrit = 2   # TermService/SessionEnv disabled
        $sevRdpSvcDisabledWarn = 1   # UmRdpService disabled
        $sevRdpNonDefaultPort = 1   # RDP port is not 3389
        $sevRdpSecurityLayerWeak = 1   # SecurityLayer=0 (RDP native, no SSL)
        $sevRdpNLADisabled = 1   # NLA/UserAuthentication disabled
        $sevRdpSecProtoNeg = 1   # fAllowSecProtocolNegotiation=0
        $sevRdpMinEncLevel = 1   # MinEncryptionLevel below 2
        $sevRdpTcpKeyMissing = 1   # RDP-Tcp WinStation key not found
        $sevRdpMaxInstanceZero = 2   # MaxInstanceCount=0 (RDP refuses all connections)
        $sevRdpCryptoSvcDisabled = 1   # KeyIso/CryptSvc/CertPropSvc disabled
        $sevRdpTlsDisabled = 1   # TLS 1.2 explicitly disabled in SCHANNEL
        $sevRdpNtlmRestrict = 1   # NTLM restrictions may block RDP auth
        $sevRdpLmCompat = 1   # LmCompatibilityLevel > 5
        $sevCredSspOracle = 1   # CredSSP AllowEncryptionOracle != 2
        $sevGpRdpBlocked = 2   # Group Policy is blocking RDP
        $sevGpNlaDisabled = 0   # Group Policy has disabled NLA
        $sevSslCipherPolicy = 1   # SSL cipher suite policy configured
        $sevRdpKeySystemAcl = 1   # RDP private key: SYSTEM missing FullControl
        $sevRdpKeyNetSvcAcl = 1   # RDP private key: NETWORK SERVICE missing Read
        $sevRdpKeySessionEnvAcl = 0   # RDP private key: SessionEnv missing FullControl
        $sevRdpKeyFileMissing = 1   # RDP private key file not found in MachineKeys
        $sevRdpKeyZeroLength = 1   # Zero-length files in MachineKeys
        $sevMachineKeysMissing = 1   # MachineKeys folder missing

        # Security
        $sevCredentialGuard = 1   # Credential Guard is enabled
        $sevLsaPPL = 0   # LSA RunAsPPL active
        $sevAppProxyLsaProtection = 1   # Application proxy connector + LSA protection can cause Kerberos/LSASS issues after servicing
        $sevAppLockerConfigured = 0  # AppLocker EnforcementMode != 0 only (no service, no rules)
        $sevAppLockerEnforcing = 1   # AppLocker EnforcementMode != 0 + AppIDSvc auto-start
        $sevAppLockerActive   = 2   # AppLocker EnforcementMode != 0 + AppIDSvc auto-start + rules exist
        $sevAppIdSvc = 0   # AppIDSvc (Application Identity) is running

        # Azure Guest Agent
        $sevAzureAgentDisabled = 2   # Agent service is disabled
        $sevAzureAgentWrongStart = 1   # Agent service has unexpected start type
        $sevAzureAgentMissing = 1   # Agent not found in registry or on disk

        # Networking
        $sevBfeDisabled = 1   # BFE (Base Filtering Engine) disabled
        $sevTcpipDisabled = 2   # Tcpip service disabled
        $sevNetSvcDisabled = 1   # Secondary networking services disabled (DNS/DHCP/NLA/SMB)
        $sevNsiDisabled = 2   # nsi (Network Store Interface) disabled - total networking loss
        $sevStaticIpNoAzureDhcp = 2   # EnableDHCP=0 on NIC - VM gets no Azure IP assignment
        $sevNetProviderOrphaned = 2   # NetworkProvider\Order lists a provider whose DLL is missing - logon hangs forever
        $sevSanPolicy = 0   # SAN policy is not OnlineAll
        $sevOrphanedNdis = 2   # Orphaned NDIS bindings with missing binary

        # Drivers
        $sevMissingDriverBinaries = 2  # Boot/System driver registered but binary missing

        # Device class filters
        $sevDeviceFiltersCrit = 2   # Non-standard entries in DiskDrive/SCSI class filters
        $sevDeviceFiltersWarn = 1   # Non-standard entries in Volume/Net class filters

        # Windows Update
        $sevUpdateWuDisabled = 0   # WU services (wuauserv/UsoSvc/WaaSMedicSvc) disabled
        $sevCbsPendingWarn = 1   # CBS RebootPending/PackagesPending, or SessionsPending interrupted WITH a queued pending.xml

        # ACPI
        $sevACPISettings = 0   # Hyper-V ACPI entries (MSFT1000/MSFT1002) missing

        # Disk space
        $sevDiskSpaceLow = 1   # Volume has less than 10% free space
        $sevDiskSpaceCritical = 2   # Volume has less than 500 MB free space

        # Driver Verifier
        $sevDriverVerifier = 2   # Driver Verifier is enabled (will BSOD on any violation)

        # Winlogon
        $sevWinlogonShell = 2   # Shell is not explorer.exe (black screen on logon)
        $sevWinlogonUserinit = 2   # Userinit is not the default (logon failure)

        # User Profiles
        $sevProfileBak = 1   # ProfileList has .bak duplicate (profile load failure)
        $sevProfileTempFlag = 1   # Profile has temporary flag set

        # Firewall
        $sevFirewallRdpBlocked = 1   # No inbound RDP rule enabled in firewall
        $sevFirewallLoopbackAccess = 1   # Protected AppCs value could not be inspected as SYSTEM
        # Image File Execution Options (IFEO)
        $sevIFEODebugger = 2   # IFEO Debugger set on critical service binary (prevents service from starting)
        $sevIFEODebuggerNonCritical = 1   # IFEO Debugger set on non-critical executable
        $sevIFEOGlobalFlag = 2   # IFEO GlobalFlag on critical exe (page heap/app verifier can crash or OOM services)
        $sevIFEOGlobalFlagNonCritical = 1   # IFEO GlobalFlag on non-critical executable

        # Startup Programs
        $sevStartupPrograms = 0   # Third-party auto-start programs found

        # Serial Console / EMS
        $sevEmsDisabled = 0   # EMS/Serial Console not configured

        # Static DNS
        $sevStaticDns = 1   # Static DNS servers configured (may break after migration)

        # Gen2 / UEFI / Trusted Launch (only evaluated when $script:VMGen -eq 2)
        $sevBootmgfwMissing = 2   # bootmgfw.efi missing from EFI System Partition
        $sevBootx64Missing = 1   # EFI\Boot\bootx64.efi fallback loader missing
        $sevBcdWinloadMismatch = 2   # BCD points to winload.exe on a Gen2 (UEFI) disk
        $sevBcdNoIntegrityChecks = 2   # nointegritychecks ON - fatal with Secure Boot
        $sevSecureBootConflict = 2   # testsigning/nointegritychecks ON while guest had Secure Boot
        $sevSecureBootState = 0   # Secure Boot was previously enabled (informational)
        $sevSecureBootCertNotUpdated = 1   # Secure Boot enabled but 2023 certs not applied (expires Jun-Oct 2026)
        $sevSecureBootCertError = 1   # Error during Secure Boot certificate update process
        $sevDeviceGuardVbs = 0   # VBS is enabled (informational)
        $sevDeviceGuardPlatReq = 1   # RequirePlatformSecurityFeatures=3 (requires DMA protection)
        $sevHvciEnabled = 0   # HVCI is enabled (informational)
        $sevEarlyLaunchPolicy = 1   # EarlyLaunch DriverLoadPolicy is restrictive
        $sevTpmDriverDisabled = 1   # TPM driver is disabled (vTPM-dependent features will fail)
        $sevBitLockerActive = 1   # BitLocker FVE active - recovery key needed after disk move

        # Session Manager / BootExecute
        $sevBootExecDangling = 2   # BootExecute entry references missing native binary (boot hang)
        $sevBootExecThirdParty = 1   # BootExecute has non-default third-party entries (binary exists)
        $sevSetupExecDangling = 2   # SetupExecute entry references missing native binary
        $sevSetupExecPresent = 1   # SetupExecute is non-empty (unusual outside servicing)
        $sevKnownDllExclude = 1   # ExcludeFromKnownDlls populated (DLL hijack vector or app compat)

        # Critical boot files (on-disk binary presence checks)
        $sevCriticalBootFileMissing = 2   # Core boot binary (winload/bootmgr/hal/ntdll/kernel32) missing or 0-byte
        $sevBcdTemplateMissing = 2   # BCD-Template hive missing - bcdboot fails with c000000f if absent
        $sevSyntheticDriverBroken = 2   # Boot-critical Azure synthetic driver (vmbus/storvsc) wrong Start value or binary missing
        $sevSyntheticNetworkBroken = 1  # Azure synthetic network driver (netvsc) broken; affects connectivity, not early boot storage
        $sevSessionInitMissing = 2   # Session init executable (smss/wininit/services/lsass/winlogon/logonui) missing or 0-byte
        $sevBinarySignatureBad = 2   # Critical boot/session binary is not Microsoft-signed (possible tampering)
        $sevThirdPartyBootSystemDriver = 1 # Validly signed third-party Boot/System driver; investigate before treating as boot blocker

        # Hyper-V integration services
        $sevIntegrationSvcMissing = 1  # Hyper-V integration service key missing from registry
        $sevIntegrationSvcDisabled = 1 # Hyper-V integration service disabled (Start=4)
        $sevIntegrationSvcBinMissing = 1 # Hyper-V integration service binary missing or 0-byte

        # Proxy
        $sevProxyConfigured = 1   # Machine-level proxy/PAC is configured (may block Azure connectivity)

        # Domain trust
        $sevNetlogonDisabled = 1   # Domain-joined VM has Netlogon disabled

        # Inline converter: integer level -> severity string used by $emit
        $toSev = { param([int]$L) switch ($L) { 0 { 'INFO' } 1 { 'WARN' } 2 { 'CRIT' } default { 'INFO' } } }

        # -- 1. Disk & Filesystem -------------------------------------------------
        Write-Host "--- Disk & Filesystem" -ForegroundColor DarkGray
        try {
            $disk = Get-Disk -Number $script:DiskNumber -ErrorAction SilentlyContinue
            if ($disk) {
                if ($disk.HealthStatus -ne 'Healthy') {
                    & $emit 'Disk' (& $toSev $sevDiskHealth) "Disk health: $($disk.HealthStatus)" "-CheckDiskHealth"
                }
                else {
                    & $emit 'Disk' 'OK' "Disk health: Healthy"
                }
            }
            foreach ($p in (Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue)) {
                $vol = Get-Volume -Partition $p -ErrorAction SilentlyContinue
                if (-not $vol) { continue }

                $fs = $vol.FileSystemType
                $hasLetter = ($p.DriveLetter -and $p.DriveLetter -ne "`0")
                $pLetter = if ($hasLetter) { "$($p.DriveLetter):" } else { $script:WinDriveLetter.TrimEnd('\') }

                if ([string]::IsNullOrEmpty($fs) -or $fs -eq 'Unknown') {
                    & $emit 'Disk' (& $toSev $sevDiskRawFs) "Partition $($p.PartitionNumber) ($pLetter): RAW filesystem - data may be inaccessible" "-FixFileSystem -DriveLetter $pLetter"
                    continue
                }

                # NTFS dirty-bit vs spot-verifier ($corrupt) discrimination.
                # On NTFS, a Get-Volume HealthStatus=Warning is usually the spot-verifier
                # corruption record ($corrupt), which a plain chkdsk /F does NOT reliably clear -
                # the targeted fix is chkdsk /spotfix. The classic dirty bit (fsutil dirty) is a
                # separate flag, cleared by autochk at the next guest boot or by a full chkdsk /F.
                # This split matters on Windows Server 2012 R2, whose proactive-scan model leaves a
                # persistent Warning that a one-shot /F does not retire.
                $fsState = if ($hasLetter -and $fs -eq 'NTFS') { Get-OfflineVolumeFsState -Letter $pLetter } else { $null }
                $isUnhealthy = ($vol.HealthStatus -ne 'Healthy')
                $isDirty = ($fsState -and $fsState.DirtyBit -eq $true)
                $isSpotCorrupt = ($fsState -and $fsState.RepairState -eq 'corrupt')

                if ($isDirty) {
                    & $emit 'Disk' (& $toSev $sevDiskDirtyBit) "Partition $($p.PartitionNumber) ($pLetter) ($fs): NTFS dirty bit is SET - autochk runs chkdsk at the next guest boot; -FixFileSystem clears it now" "-FixFileSystem -DriveLetter $pLetter"
                }
                elseif ($fs -eq 'NTFS' -and ($isSpotCorrupt -or $isUnhealthy)) {
                    $reason = if ($isSpotCorrupt) { "spot-verifier logged corruption (`$corrupt)" } else { "health=$($vol.HealthStatus)" }
                    & $emit 'Disk' (& $toSev $sevDiskSpotFix) "Partition $($p.PartitionNumber) ($pLetter) ($fs): $reason - a plain chkdsk /F may not clear this; -FixFileSystem auto-runs chkdsk /spotfix" "-FixFileSystem -DriveLetter $pLetter"
                }
                elseif ($isUnhealthy) {
                    & $emit 'Disk' (& $toSev $sevDiskFsHealth) "Partition $($p.PartitionNumber) ($pLetter) ($fs): health=$($vol.HealthStatus)" "-FixFileSystem -DriveLetter $pLetter"
                }
            }
        }
        catch { Write-Warning "Disk check failed: $_" }

        # -- 1a. NTFS metafile attribute lists ------------------------------------
        # A reserved file record (0-31) can carry an ATTRIBUTE_LIST_ENTRY whose
        # NameOffset is 0x1c where the canonical layout uses 0x1a. Older NTFS
        # revisions accept it; newer ones validate it, reject the record while
        # resolving the referenced stream and fail the volume mount - which the
        # guest shows as a boot loop with bugcheck 0x24 (NTFS_FILE_SYSTEM).
        # Read-only probe of every lettered NTFS volume on the disk.
        try {
            foreach ($attrTarget in (Get-NtfsAttrListScanTargets -DiskNumber $script:DiskNumber)) {
                $attrState = Get-NtfsMetafileAttrListState -Volume $attrTarget
                if (-not $attrState.Scanned) {
                    Write-Warning "Attribute list check skipped for ${attrTarget}: $($attrState.Error)"
                    continue
                }
                if ($attrState.Fixable -eq 0 -and $attrState.Unfixable -eq 0 -and -not (@($attrState.Records | Where-Object { $_.Malformed }).Count)) {
                    & $emit 'Disk' 'OK' "$attrTarget metafile attribute lists use the canonical name offset"
                    continue
                }
                foreach ($attrRecord in $attrState.Records) {
                    foreach ($attrEntry in $attrRecord.Entries) {
                        $attrLabel = if ($attrEntry.Name) { "$($attrEntry.TypeName):$($attrEntry.Name)" } else { $attrEntry.TypeName }
                        $attrOffset = "0x$($attrEntry.NameOffset.ToString('x2'))"
                        if ($attrEntry.CanRepair) {
                            & $emit 'Disk' (& $toSev $sevNtfsAttrListNameOffset) "$attrTarget $($attrRecord.Name): $attrLabel NameOffset=$attrOffset (canonical is 0x1a) - newer NTFS fails the volume mount here and the guest boot loops with bugcheck 0x24 NTFS_FILE_SYSTEM. Do NOT run chkdsk: it discards the whole attribute list instead of correcting the field" "-FixNtfsAttributeList -DriveLetter $attrTarget"
                        }
                        else {
                            & $emit 'Disk' (& $toSev $sevNtfsAttrListUnknown) "$attrTarget $($attrRecord.Name): $attrLabel NameOffset=$attrOffset (canonical is 0x1a) - outside the pattern this script repairs; do NOT run chkdsk on this volume"
                        }
                    }
                    if ($attrRecord.Malformed) {
                        & $emit 'Disk' (& $toSev $sevNtfsAttrListUnknown) "$attrTarget $($attrRecord.Name): attribute list is truncated or malformed; do NOT run chkdsk on this volume"
                    }
                }
            }
        }
        catch { Write-Warning "NTFS attribute list check failed: $_" }

        # -- 1b. Disk Space (Windows partition only) ------------------------------
        # Only check the Windows partition; small boot/EFI/recovery partitions are expected to be nearly full.
        try {
            $winLetter = $script:WinDriveLetter.TrimEnd('\')
            $winPart = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue |
            Where-Object { $_.DriveLetter -and "$($_.DriveLetter):" -eq $winLetter }
            if ($winPart) {
                $vol = Get-Volume -Partition $winPart -ErrorAction SilentlyContinue
                if ($vol -and $vol.Size -gt 0) {
                    $freeGB = [math]::Round($vol.SizeRemaining / 1GB, 2)
                    $totalGB = [math]::Round($vol.Size / 1GB, 2)
                    $freePct = [math]::Round(($vol.SizeRemaining / $vol.Size) * 100, 1)
                    $freeMB = [math]::Round($vol.SizeRemaining / 1MB, 0)
                    $label = "Windows partition ($winLetter): $freeGB GB free of $totalGB GB ($freePct%)"
                    if ($freeMB -lt 500) {
                        & $emit 'DiskSpace' (& $toSev $sevDiskSpaceCritical) "$label - CRITICALLY LOW, VM may fail to boot (no space for pagefile/logs)"
                    }
                    elseif ($freePct -lt 10) {
                        & $emit 'DiskSpace' (& $toSev $sevDiskSpaceLow) "$label - low free space may cause issues"
                    }
                    else {
                        & $emit 'DiskSpace' 'OK' $label
                    }
                }
            }
        }
        catch { Write-Warning "Disk space check failed: $_" }

        # -- 2. Crash & Boot Artefacts --------------------------------------------
        Write-Host "--- Crash & Boot Artefacts" -ForegroundColor DarkGray
        $minidumpDir = Join-Path $script:WinDriveLetter 'Windows\Minidump'
        if (Test-Path $minidumpDir) {
            $dumps = @(Get-ChildItem $minidumpDir -Filter '*.dmp' -ErrorAction SilentlyContinue)
            if ($dumps.Count -gt 0) {
                $newest = $dumps | Sort-Object LastWriteTime -Descending | Select-Object -First 1
                & $emit 'Crash' (& $toSev $sevCrashMinidumps) "$($dumps.Count) minidump(s) found - latest: $($newest.Name) [$($newest.LastWriteTime.ToString('yyyy-MM-dd HH:mm'))]" "-CollectEventLogs"
            }
            else { & $emit 'Crash' 'OK' 'No minidump files' }
        }
        else { & $emit 'Crash' 'OK' 'No Minidump folder' }

        $ntbtlogpath = Join-Path $script:WinDriveLetter 'Windows\ntbtlog.txt'
        if (Test-Path $ntbtlogpath) {
            & $emit 'Boot' (& $toSev $sevBootNtbtlog) "$($ntbtlogpath) present - check for DIDNOTLOAD entries" "-CollectEventLogs"
        }

        $pendingXmlPresent = Test-Path (Join-Path $script:WinDriveLetter 'Windows\WinSxS\pending.xml')
        if ($pendingXmlPresent) {
            & $emit 'WindowsUpdate' (& $toSev $sevUpdatePendingXml) 'Pending Windows Update transaction (pending.xml) - may cause boot loop on Configuring Updates screen' "-FixPendingUpdates"
        }

        # 0x800719e4 / ERROR_LOG_FULL - the CLFS/KTM transaction logs are exhausted, so
        # servicing cannot commit. Clearing the logs is the documented repair; reverting
        # pending updates is not needed and is heavier than the scenario calls for.
        # Evaluated before the TxR/SMI checks below because it is what makes the presence
        # of those files meaningful.
        # https://learn.microsoft.com/troubleshoot/windows-server/installing-updates-features-roles/error-0x800719e4-windows-update-fails
        $logFullHits = @()
        $cbsLogPath = Join-Path $script:WinDriveLetter 'Windows\Logs\CBS\CBS.log'
        if (Test-Path $cbsLogPath) {
            try {
                $cbsTail = Get-Content -LiteralPath $cbsLogPath -Tail 4000 -ErrorAction Stop
                $logFullHits = @($cbsTail | Where-Object {
                        $_ -match '0x800719e4' -or
                        $_ -match 'ERROR_LOG_FULL' -or
                        $_ -match 'Failed while processing non-critical driver operations queue'
                    })
                if ($logFullHits.Count -gt 0) {
                    & $emit 'WindowsUpdate' (& $toSev $sevUpdateLogFull) "CBS.log reports transaction log exhaustion ($($logFullHits.Count) hit(s), e.g. 0x800719e4/ERROR_LOG_FULL) - see KB error-0x800719e4-windows-update-fails" "-FixTxRLogs"
                }
            }
            catch {
                # SysCheck is read-only; a locked or unreadable CBS.log must not fail it.
                Write-Verbose "CBS.log could not be read for transaction log analysis: $($_.Exception.Message)"
            }
        }
        $servicingStuck = ($logFullHits.Count -gt 0) -or $pendingXmlPresent

        # Transaction log files in config\TxR and SMI\Store\Machine.
        #
        # Presence alone is NOT a fault. Every healthy Windows installation keeps these
        # files - verified on clean Server 2012 R2, 2016, 2019 and 2022 images, all of
        # which carry a full set. Reporting them as a problem produces a warning on every
        # machine ever scanned, so they are reported as INFO and only become actionable
        # when something else shows servicing is genuinely stuck.
        #
        # Note the -Force on the enumeration. These files are Hidden+System, so a plain
        # Get-ChildItem returns nothing at all and the check can never fire.
        $txrFolder = Join-Path $script:WinDriveLetter 'Windows\System32\config\TxR'
        if (Test-Path $txrFolder) {
            $txrFiles = @(Get-ChildItem $txrFolder -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in @('.blf', '.regtrans-ms') })
            if ($txrFiles.Count -gt 0) {
                $txrKB = [math]::Round((($txrFiles | Measure-Object -Property Length -Sum).Sum) / 1KB)
                if ($servicingStuck) {
                    & $emit 'WindowsUpdate' (& $toSev $sevUpdateTxRLogs) "$($txrFiles.Count) TxR transaction log file(s) in config\TxR ($txrKB KB) alongside evidence that servicing is stuck - clearing them is the documented repair" "-FixTxRLogs"
                }
                else {
                    & $emit 'WindowsUpdate' 'INFO' "config\TxR holds $($txrFiles.Count) transaction log file(s) ($txrKB KB) - normal for a healthy installation, no action needed"
                }
            }
        }

        $smiFolder = Join-Path $script:WinDriveLetter 'Windows\System32\SMI\Store\Machine'
        if (Test-Path $smiFolder) {
            $smiFiles = @(Get-ChildItem $smiFolder -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in @('.blf', '.regtrans-ms') })
            if ($smiFiles.Count -gt 0) {
                $smiKB = [math]::Round((($smiFiles | Measure-Object -Property Length -Sum).Sum) / 1KB)
                if ($servicingStuck) {
                    & $emit 'WindowsUpdate' (& $toSev $sevUpdateSmiLogs) "$($smiFiles.Count) SMI Store transaction log file(s) ($smiKB KB) alongside evidence that servicing is stuck" "-FixTxRLogs -TransactionLogScope SMI"
                }
                else {
                    & $emit 'WindowsUpdate' 'INFO' "SMI\Store\Machine holds $($smiFiles.Count) transaction log file(s) ($smiKB KB) - normal for a healthy installation, no action needed"
                }
            }
        }

        # -- 2b. Registry Hive Files -----------------------------------------------
        Write-Host "--- Registry Hive Files" -ForegroundColor DarkGray
        $configDir = Join-Path $script:WinDriveLetter 'Windows\System32\config'
        $expectedHives = @(
            @{ Name = 'SYSTEM';       IsCrit = $true;  Desc = 'kernel config - BSOD 0xC0000218 if missing' }
            @{ Name = 'SOFTWARE';     IsCrit = $true;  Desc = 'app/system config - BSOD 0xC0000218 if missing' }
            @{ Name = 'SAM';          IsCrit = $true;  Desc = 'account database - logon failure if missing' }
            @{ Name = 'SECURITY';     IsCrit = $true;  Desc = 'security policy - logon failure if missing' }
            @{ Name = 'DEFAULT';      IsCrit = $false; Desc = 'default user profile hive' }
            @{ Name = 'COMPONENTS';   IsCrit = $false; Desc = 'CBS/servicing store - update/install failures' }
            @{ Name = 'BCD-Template'; IsCrit = $false; Desc = 'bcdboot template - needed only for BCD rebuild' }
            @{ Name = 'DRIVERS';      IsCrit = $false; Desc = 'driver database' }
        )
        $hiveIssues = 0
        foreach ($h in $expectedHives) {
            $hivePath = Join-Path $configDir $h.Name
            $hiveItem = Get-Item -LiteralPath $hivePath -Force -ErrorAction SilentlyContinue
            if (-not $hiveItem) {
                $missingSev = if ($h.IsCrit) { & $toSev $sevHiveMissing } else { 'WARN' }
                & $emit 'Registry' $missingSev "$($h.Name) hive MISSING ($hivePath) - $($h.Desc)" '-RestoreRegistryFromRegBack'
                $hiveIssues++
            }
            elseif ($hiveItem.Length -eq 0) {
                $emptySev = if ($h.IsCrit) { & $toSev $sevHiveEmpty } else { 'WARN' }
                & $emit 'Registry' $emptySev "$($h.Name) hive is 0 bytes ($hivePath) - $($h.Desc)" '-RestoreRegistryFromRegBack'
                $hiveIssues++
            }
        }
        if ($hiveIssues -eq 0) {
            & $emit 'Registry' 'OK' "All expected registry hive files present and non-empty ($($expectedHives.Count) checked)"
        }

        # -- 3. BCD ---------------------------------------------------------------
        Write-Host "--- BCD / Boot Configuration" -ForegroundColor DarkGray

        # Check for missing boot partition (System Reserved on Gen1, EFI System Partition on Gen2)
        $scPartitions = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue
        $bootPartMissing = $false
        if ($script:VMGen -eq 2) {
            $espExists = $scPartitions | Where-Object { $_.Type -eq 'System' }
            if (-not $espExists) {
                & $emit 'BCD' (& $toSev $sevBootPartitionMissing) "EFI System Partition is MISSING - Gen2 (UEFI) VM cannot boot without it" "-RecreateBootPartition"
                $bootPartMissing = $true
            }
            else {
                & $emit 'BCD' 'OK' "EFI System Partition present (Partition $($espExists.PartitionNumber))"
            }
        }
        else {
            # Gen1: check if a separate boot partition exists (Active partition != Windows partition)
            $winTrimmed = $script:WinDriveLetter.TrimEnd('\')
            $separateBootPart = $scPartitions | Where-Object {
                $_.IsActive -and ($_.AccessPaths | Where-Object { $_ -and $_.TrimEnd('\') -ne $winTrimmed })
            }
            if (-not $separateBootPart) {
                # Check if Windows partition is Active (single-partition layout)
                $winIsActive = $scPartitions | Where-Object {
                    $_.AccessPaths | Where-Object { $_ -and $_.TrimEnd('\') -eq $winTrimmed }
                } | Where-Object { $_.IsActive }
                if ($winIsActive) {
                    & $emit 'BCD' 'OK' "No separate System Reserved partition - Windows partition is Active (single-partition layout)"
                }
                else {
                    & $emit 'BCD' (& $toSev $sevBootPartitionMissing) "No bootable partition found - System Reserved partition is missing and Windows partition is not Active" "-RecreateBootPartition"
                    $bootPartMissing = $true
                }
            }
            else {
                & $emit 'BCD' 'OK' "System Reserved partition present (Partition $($separateBootPart.PartitionNumber), Active)"
            }
        }

        # When the boot partition itself is missing, all BCD/boot-file findings are symptoms
        # of that root cause - redirect fix suggestions to -RecreateBootPartition
        $bcdFix = if ($bootPartMissing) { '-RecreateBootPartition' } else { '-FixBoot' }

        $installCandidates = @($script:WindowsInstallCandidates)
        if ($installCandidates.Count -gt 0) {
            $selectedInstall = @($installCandidates | Where-Object { $_.Selected } | Select-Object -First 1)
            if (-not $selectedInstall) {
                $selectedInstall = @($installCandidates | Select-Object -First 1)
            }
            if ($selectedInstall) {
                $selected = $selectedInstall[0]
                $selectedBuild = Format-WindowsBuildLabel -Build $selected.CurrentBuildNumber -Ubr $selected.UBR -Fallback 'unknown'
                & $emit 'Windows' 'INFO' "Selected Windows install: $($selected.Drive) ($($selected.ProductName), build $selectedBuild, score=$($selected.Score))"
                if ($selected.SetupEvidence) {
                    & $emit 'Windows' (& $toSev $sevWindowsInstallSetupState) "Selected Windows install still shows setup/upgrade markers: $($selected.SetupEvidence)" '-AnalyzeServicingState'
                }
            }
            if ($installCandidates.Count -gt 1) {
                $candidateSummary = ($installCandidates | ForEach-Object {
                    $build = Format-WindowsBuildLabel -Build $_.CurrentBuildNumber -Ubr $_.UBR -Fallback 'unknown'
                    $name = if ($_.ProductName) { $_.ProductName } else { 'Unknown Windows install' }
                    "$($_.Drive)=$name build $build score=$($_.Score)"
                }) -join '; '
                & $emit 'Windows' (& $toSev $sevMultipleWindowsInstalls) "Multiple Windows installs detected: $candidateSummary" $bcdFix
                if ($installCandidates.Count -gt 1 -and (($installCandidates[0].Score - $installCandidates[1].Score) -lt 5)) {
                    & $emit 'Windows' (& $toSev $sevWindowsInstallSelectionAmbiguous) "Top Windows install candidates scored too closely to auto-pick confidently: $($installCandidates[0].Drive)=$($installCandidates[0].Score), $($installCandidates[1].Drive)=$($installCandidates[1].Score)" '-GetBootPathReport'
                }
            }
        }

        $bcdPath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter.TrimEnd('\')
        $bcdItem = Get-BcdStoreItem -StorePath $bcdPath
        if (-not $bcdItem) {
            & $emit 'BCD' (& $toSev $sevBcdMissing) "BCD store not found at $bcdPath - VM will fail to boot" $bcdFix
        }
        else {
            if ($bcdItem.Length -eq 0) {
                & $emit 'BCD' (& $toSev $sevBcdMissing) "BCD store is 0 bytes (corrupt) at $bcdPath - VM will fail to boot" $bcdFix
            }
            else {
                & $emit 'BCD' 'OK' "BCD store present: $bcdPath"
                try {
                    $bcdInventory = Get-BcdInventory -StorePath $bcdPath
                    $bcdText = $bcdInventory.RawText
                    $preferredLoaderId = Get-BcdBootLoaderId -StorePath $bcdPath
                    $preferredLoaderDetails = if ($preferredLoaderId) { Get-BcdLoaderDetails -StorePath $bcdPath -Identifier $preferredLoaderId } else { $null }
                    $startupRepairConfigured = [bool]($preferredLoaderDetails -and $preferredLoaderDetails.RawText -match '(?im)^\s*recoverysequence\s+\{[^\r\n]+\}\s*$')
                    if (@($bcdInventory.Loaders).Count -eq 0) {
                        & $emit 'BCD' (& $toSev $sevBcdNoBootLoader) 'No Windows Boot Loader entry found in BCD' "-FixBoot"
                    }
                    else {
                        & $emit 'BCD' 'OK' "Windows Boot Loader entries present: $(@($bcdInventory.Loaders).Count)"
                        if (@($bcdInventory.Loaders).Count -gt 1) {
                            $loaderSummary = ($bcdInventory.Loaders | ForEach-Object {
                                $desc = if ($_.Description) { $_.Description } else { $_.Identifier }
                                if ($_.PartitionDrive) { "$desc@$($_.PartitionDrive)" } else { $desc }
                            }) -join '; '
                            & $emit 'BCD' (& $toSev $sevBcdMultipleLoaders) "Multiple Windows Boot Loader entries found: $loaderSummary" '-FixBoot'
                        }
                        $setupLoaders = @($bcdInventory.Loaders | Where-Object { $_.IsSetupEntry })
                        if ($setupLoaders.Count -gt 0) {
                            $setupSummary = ($setupLoaders | ForEach-Object { if ($_.Description) { $_.Description } else { $_.Identifier } }) -join '; '
                            & $emit 'BCD' (& $toSev $sevBcdSetupEntry) "BCD contains setup/stale loader entries: $setupSummary" '-FixBoot'
                        }
                    }
                if ($bcdText -match 'safeboot\s+(\S+)') {
                    & $emit 'BCD' (& $toSev $sevBcdSafeMode) "Safe Mode boot flag is active (safeboot $($Matches[1])) - VM will boot into Safe Mode" "-RemoveSafeModeFlag"
                }
                if ($bcdText -match 'bootstatuspolicy\s+ignoreallfailures') {
                    & $emit 'BCD' (& $toSev $sevBcdBootStatusPolicy) 'bootstatuspolicy IgnoreAllFailures is set - startup repair is suppressed'
                }
                if ($bcdText -match 'recoveryenabled\s+no') {
                    & $emit 'BCD' (& $toSev $sevBcdRecoveryDisabled) 'recoveryenabled is Off - WinRE recovery disabled'
                }
                $winre = Get-WinREStatus
                if (-not $winre.ReagentcAvailable) {
                    & $emit 'WinRE' 'INFO' 'reagentc.exe is not available on the rescue host, so offline WinRE status could not be evaluated'
                }
                elseif ($startupRepairConfigured -and -not $winre.ImageFound) {
                    $detail = 'No usable Winre.wim found on mounted guest partitions.'
                    if ($winre.HiddenRecoveryPartitions -gt 0) {
                        $detail += " Hidden Recovery partition(s) without drive letters detected: $($winre.HiddenRecoveryPartitions)."
                    }
                    & $emit 'WinRE' (& $toSev $sevWinreImageMissing) "$detail WinRE cannot be registered until a recovery image is accessible." '-EnableStartupRepair'
                }
                elseif ($startupRepairConfigured) {
                    $winreEnabled = ($winre.ReStatus -match '(?i)^enabled$') -and $winre.ReBcdIdentifier -and ($winre.ReBcdIdentifier -ne '00000000-0000-0000-0000-000000000000')
                    if ($winreEnabled) {
                        $locationLabel = if ($winre.ReLocation) { $winre.ReLocation } else { $winre.PreferredDirectory }
                        & $emit 'WinRE' 'OK' "Windows RE is enabled and registered ($locationLabel)"
                    }
                    else {
                        & $emit 'WinRE' (& $toSev $sevWinreDisabled) "WinRE image found at $($winre.PreferredDirectory), but Windows RE is disabled or not registered (BCD id: $($winre.ReBcdIdentifier))." '-EnableStartupRepair'
                    }
                }
                if ($bcdText -match 'testsigning\s+yes') {
                    & $emit 'BCD' (& $toSev $sevBcdTestSigning) 'Test signing is ON - unsigned drivers are permitted to load' "-DisableTestSigning"
                }
                if ($bcdText -match 'nointegritychecks\s+yes') {
                    & $emit 'BCD' (& $toSev $sevBcdNoIntegrityChecks) 'nointegritychecks is ON - code integrity checks are bypassed; FATAL if Secure Boot is enabled' "-FixBoot"
                }
                if ($bcdText -match '\bunknown\b') {
                    & $emit 'BCD' (& $toSev $sevBcdUnknownDevice) 'BCD contains entries with unknown device/path - may point to wrong or missing partition' "-FixBoot"
                }
                if ($bcdText -match 'imcdevice|imchivename') {
                    & $emit 'BCD' (& $toSev $sevBcdImcHive) 'BCD contains imcdevice/imchivename entries (IMC.hiv) - causes BSOD 0x67 CONFIG_INITIALIZATION_FAILED; rebuild BCD to remove' "-FixBoot"
                }
                # Gen2 UEFI-specific BCD checks
                if ($script:VMGen -eq 2) {
                    # winload path mismatch: Gen2 must use winload.efi, not winload.exe
                    if ($bcdText -match 'path\s+.*\\winload\.exe') {
                        & $emit 'BCD' (& $toSev $sevBcdWinloadMismatch) 'BCD Boot Loader path references winload.exe on a Gen2 (UEFI) disk - must be winload.efi' "-FixBoot"
                    }
                }
            }
            catch { & $emit 'BCD' 'WARN' "Could not enumerate BCD: $_" }
            }
        }

        # Gen2 UEFI: verify EFI System Partition boot files
        if ($script:VMGen -eq 2) {
            $efiBootmgfw = Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot\bootmgfw.efi'
            $efiBootx64 = Join-Path $script:BootDriveLetter 'EFI\Boot\bootx64.efi'

            if (-not (Test-Path $efiBootmgfw)) {
                & $emit 'BCD' (& $toSev $sevBootmgfwMissing) "bootmgfw.efi missing from EFI System Partition ($efiBootmgfw) - UEFI firmware cannot start Windows Boot Manager" $bcdFix
            }
            elseif ((Get-Item -LiteralPath $efiBootmgfw -ErrorAction SilentlyContinue).Length -eq 0) {
                & $emit 'BCD' (& $toSev $sevBootmgfwMissing) "bootmgfw.efi is 0 bytes (corrupt) on EFI System Partition ($efiBootmgfw) - UEFI firmware cannot start Windows Boot Manager" $bcdFix
            }
            else {
                $efiMgfwSig = Test-MicrosoftSignature -FilePath $efiBootmgfw
                if (-not $efiMgfwSig.IsAcceptableMicrosoft) {
                    $mgfwSev = if ($efiMgfwSig.IsHardFailure) { 'CRIT' } else { & $toSev $sevBinarySignatureBad }
                    & $emit 'Security' $mgfwSev "bootmgfw.efi failed trust validation - $(Get-TrustStateDescription -Signature $efiMgfwSig)" $bcdFix
                }
                else {
                    & $emit 'BCD' 'OK' 'bootmgfw.efi present on EFI System Partition'
                }
            }
            if (-not (Test-Path $efiBootx64)) {
                & $emit 'BCD' (& $toSev $sevBootx64Missing) "EFI\\Boot\\bootx64.efi fallback loader missing - some UEFI firmware relies on this path" $bcdFix
            }
            elseif ((Get-Item -LiteralPath $efiBootx64 -ErrorAction SilentlyContinue).Length -eq 0) {
                & $emit 'BCD' (& $toSev $sevBootx64Missing) "EFI\\Boot\\bootx64.efi is 0 bytes (corrupt) - some UEFI firmware relies on this path" $bcdFix
            }
            else {
                $efiX64Sig = Test-MicrosoftSignature -FilePath $efiBootx64
                if (-not $efiX64Sig.IsAcceptableMicrosoft) {
                    $x64Sev = if ($efiX64Sig.IsHardFailure) { 'CRIT' } else { & $toSev $sevBinarySignatureBad }
                    & $emit 'Security' $x64Sev "bootx64.efi failed trust validation - $(Get-TrustStateDescription -Signature $efiX64Sig)" $bcdFix
                }
            }
        }

        # Gen1 BIOS: verify boot partition has the Active flag set
        if ($script:VMGen -eq 1) {
            $bootPartition = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue |
            Where-Object {
                $_.AccessPaths | Where-Object {
                    $_ -and $script:BootDriveLetter.TrimEnd('\') -eq $_.TrimEnd('\')
                }
            }
            if ($bootPartition) {
                if (-not $bootPartition.IsActive) {
                    & $emit 'BCD' (& $toSev $sevBootPartitionNotActive) "Gen1 boot partition (Partition $($bootPartition.PartitionNumber)) is NOT marked as Active - BIOS cannot locate the boot sector; VM will fail to boot (black screen)" "-FixBoot"
                }
                else {
                    & $emit 'BCD' 'OK' "Gen1 boot partition (Partition $($bootPartition.PartitionNumber)) is marked as Active"
                }
            }
        }

        # -- 3b. Critical boot/system binaries ------------------------------------
        Write-Host "--- Critical Boot Files" -ForegroundColor DarkGray
        $winloadFile = if ($script:VMGen -eq 2) { 'winload.efi' } else { 'winload.exe' }
        $bootBinaries = @(
            @{ Name = $winloadFile; Path = (Join-Path $script:WinDriveLetter "Windows\System32\$winloadFile"); Fix = "-RepairSystemFile $winloadFile" }
            @{ Name = 'ntdll.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntdll.dll'); Fix = '-RepairSystemFile ntdll.dll' }
            @{ Name = 'kernel32.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\kernel32.dll'); Fix = '-RepairSystemFile kernel32.dll' }
            @{ Name = 'hal.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\hal.dll'); Fix = '-RepairSystemFile hal.dll' }
            @{ Name = 'ntoskrnl.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntoskrnl.exe'); Fix = '-RepairSystemFile ntoskrnl.exe' }
            @{ Name = 'ci.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ci.dll'); Fix = '-RepairSystemFile ci.dll' }
        )
        if ($script:VMGen -eq 1) {
            $bootBinaries += @{ Name = 'bootmgr'; Path = (Join-Path $script:BootDriveLetter 'bootmgr'); Fix = '-FixBoot' }
        }

        # BCD-Template hive: required by bcdboot to create a new BCD store. If missing, -FixBoot
        # will fail with BFSVC error c000000f (cannot open BCD template store).
        $bcdTemplateHive = Join-Path $script:WinDriveLetter 'Windows\System32\config\BCD-Template'
        $bcdTemplateItem = Get-Item -LiteralPath $bcdTemplateHive -Force -ErrorAction SilentlyContinue
        if (-not $bcdTemplateItem) {
            & $emit 'Boot' (& $toSev $sevBcdTemplateMissing) "BCD-Template hive MISSING ($bcdTemplateHive) - bcdboot will fail with error c000000f; -FixBoot cannot succeed until this file is restored" '-FixBoot'
        }
        elseif ($bcdTemplateItem.Length -eq 0) {
            & $emit 'Boot' (& $toSev $sevBcdTemplateMissing) "BCD-Template hive is 0 bytes (corrupt) ($bcdTemplateHive) - bcdboot will fail with error c000000f; restore from a healthy Windows source" '-FixBoot'
        }
        else {
            & $emit 'Boot' 'OK' "BCD-Template hive present ($bcdTemplateHive)"
        }

        # Boot sectors (Gen1/BIOS only). bcdboot repairs boot FILES; it never writes
        # sector 0 of the disk or of the boot partition. A damaged MBR bootstrap or a
        # stale BPB HiddenSectors value fails the boot before bootmgr ever loads, and
        # is invisible to chkdsk, sfc and every BCD-level check above.
        if ($script:VMGen -eq 1) {
            try {
                $bsReport = Get-BootSectorReport -DiskNumber $script:DiskNumber -BootDriveLetter $script:BootDriveLetter
                $script:BootSectorReport = $bsReport
                if ($bsReport.Findings.Count -eq 0 -and $bsReport.Errors.Count -eq 0) {
                    & $emit 'Boot' 'OK' 'MBR bootstrap, active flag and volume boot record (VBR) all valid'
                }
                foreach ($bsf in $bsReport.Findings) {
                    $bsSev = if ($bsf.Severity -eq 'CRITICAL') { & $toSev 2 } else { & $toSev 1 }
                    & $emit 'Boot' $bsSev $bsf.Message $bsf.Fix
                }
                foreach ($bsErr in $bsReport.Errors) {
                    & $emit 'Boot' (& $toSev 1) "Boot sector check incomplete: $bsErr"
                }
            }
            catch {
                & $emit 'Boot' (& $toSev 1) "Boot sector check could not run: $_"
            }
        }
        $bootFileIssues = 0
        $sigIssues = 0
        foreach ($bf in $bootBinaries) {
            $bfExists = Test-Path -LiteralPath $bf.Path
            $bfSize = if ($bfExists) { (Get-Item -LiteralPath $bf.Path -Force -ErrorAction SilentlyContinue).Length } else { 0 }
            if (-not $bfExists) {
                & $emit 'Boot' (& $toSev $sevCriticalBootFileMissing) "$($bf.Name) is MISSING ($($bf.Path)) - VM will fail to boot" $bf.Fix
                $bootFileIssues++
            }
            elseif ($bfSize -eq 0) {
                & $emit 'Boot' (& $toSev $sevCriticalBootFileMissing) "$($bf.Name) is 0 bytes (corrupt) ($($bf.Path)) - VM will fail to boot" $bf.Fix
                $bootFileIssues++
            }
            else {
                # Binary exists and is non-zero  -  verify Microsoft signature
                if (-not ([bool]$bf.SkipSignature)) {
                    $sigCheck = Test-MicrosoftSignature -FilePath $bf.Path
                    if (-not $sigCheck.IsAcceptableMicrosoft) {
                        $bfSev = if ($sigCheck.IsHardFailure) { 'CRIT' } else { & $toSev $sevBinarySignatureBad }
                        & $emit 'Security' $bfSev "$($bf.Name) failed trust validation - $(Get-TrustStateDescription -Signature $sigCheck)" $bf.Fix
                        $sigIssues++
                    }
                }
            }
        }
        if ($bootFileIssues -eq 0 -and $sigIssues -eq 0) {
            & $emit 'Boot' 'OK' "All critical boot binaries present, non-empty, and Microsoft-signed"
        }
        elseif ($bootFileIssues -eq 0) {
            & $emit 'Boot' 'OK' "All critical boot binaries present and non-empty"
        }

        # -- 3c. Session initialization executables --------------------------------
        # These run early in the Windows boot chain after ntoskrnl hands off to user mode.
        # Missing or tampered copies cause boot loops, black screens, or automatic repair loops.
        Write-Host "--- Session Init Executables" -ForegroundColor DarkGray
        $sessionBinaries = @(
            @{ Name = 'smss.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\smss.exe'); Desc = 'Session Manager - first user-mode process; missing = immediate boot failure' }
            @{ Name = 'csrss.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\csrss.exe'); Desc = 'Client/Server Runtime - Win32 subsystem; missing = BSOD STOP 0xEF' }
            @{ Name = 'wininit.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\wininit.exe'); Desc = 'Windows Init - starts services.exe and lsass.exe' }
            @{ Name = 'services.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\services.exe'); Desc = 'Service Control Manager - without it no services start' }
            @{ Name = 'lsass.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\lsass.exe'); Desc = 'Local Security Authority - auth/logon; missing = boot loop' }
            @{ Name = 'winlogon.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\winlogon.exe'); Desc = 'Winlogon - interactive logon handler; missing = black screen' }
            @{ Name = 'logonui.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\logonui.exe'); Desc = 'Logon UI - credential provider host; missing = black screen at logon' }
        )
        $sessIssues = 0
        $sessSigIssues = 0
        foreach ($sb in $sessionBinaries) {
            $sbExists = Test-Path -LiteralPath $sb.Path
            $sbSize = if ($sbExists) { (Get-Item -LiteralPath $sb.Path -Force -ErrorAction SilentlyContinue).Length } else { 0 }
            if (-not $sbExists) {
                & $emit 'Boot' (& $toSev $sevSessionInitMissing) "$($sb.Name) is MISSING - $($sb.Desc)" "-RepairSystemFile $($sb.Name)"
                $sessIssues++
            }
            elseif ($sbSize -eq 0) {
                & $emit 'Boot' (& $toSev $sevSessionInitMissing) "$($sb.Name) is 0 bytes (corrupt) - $($sb.Desc)" "-RepairSystemFile $($sb.Name)"
                $sessIssues++
            }
            else {
                $sigCheck = Test-MicrosoftSignature -FilePath $sb.Path
                if (-not $sigCheck.IsAcceptableMicrosoft) {
                    $sbSev = if ($sigCheck.IsHardFailure) { 'CRIT' } else { & $toSev $sevBinarySignatureBad }
                    & $emit 'Security' $sbSev "$($sb.Name) failed trust validation - $(Get-TrustStateDescription -Signature $sigCheck)" "-RepairSystemFile $($sb.Name)"
                    $sessSigIssues++
                }
            }
        }
        if ($sessIssues -eq 0 -and $sessSigIssues -eq 0) {
            & $emit 'Boot' 'OK' "All session init executables present, non-empty, and Microsoft-signed"
        }
        elseif ($sessIssues -eq 0) {
            & $emit 'Boot' 'OK' "All session init executables present and non-empty"
        }

        # -- 4. SYSTEM hive -------------------------------------------------------
        Write-Host "--- Registry / Services (SYSTEM hive)" -ForegroundColor DarkGray
        Invoke-WithHive 'SYSTEM' {
            # Run all SYSTEM hive checks in a child scope so .NET RegistryKey objects
            # go out of scope (and become GC-collectible) before the finally block
            # calls UnmountOffHive. Without this, cached handles prevent reg.exe unload.
            & {
                $sel = Get-ItemProperty 'HKLM:\BROKENSYSTEM\Select' -ErrorAction SilentlyContinue
                $curSet = $sel.Current
                $lkgcSet = $sel.LastKnownGood
                $defSet = $sel.Default
                $csName = Get-CurrentOfflineControlSetName
                $SystemRoot = "HKLM:\BROKENSYSTEM\$csName"
                $svcRoot = "$SystemRoot\Services"
                $ctrlRoot = "$SystemRoot\Control"

                # ControlSet mismatch
                if ($null -ne $curSet -and $null -ne $defSet -and $curSet -ne $defSet) {
                    & $emit 'Registry' (& $toSev $sevControlSetMismatch) "ControlSet mismatch: Current=$curSet Default=$defSet - LKGC switch may help" "-TryLGKC"
                }
                else {
                    & $emit 'Registry' 'OK' "ControlSet: Current=ControlSet$("{0:d3}" -f $curSet)  LKGC=ControlSet$("{0:d3}" -f $lkgcSet)"
                }

                # RegBack
                # On Windows 10 1803 / Server 2019 (build 17134)+ the RegBack auto-backup is OFF by
                # default and -EnableRegBackup (EnablePeriodicBackup) re-enables it. On earlier builds
                # (Server 2012 R2 = 9600, Server 2016 = 14393) RegBack is maintained by the RegIdleBackup
                # scheduled task and an empty RegBack is normal, so -EnableRegBackup is not the remedy there.
                $regBackGuestBuild = 0
                [void][int]::TryParse((Get-GuestCurrentVersion).CurrentBuildNumber, [ref]$regBackGuestBuild)
                $regBackTaskDriven = ($regBackGuestBuild -gt 0 -and $regBackGuestBuild -lt 17134)
                $rbSystem = Join-Path $script:WinDriveLetter 'Windows\System32\config\RegBack\SYSTEM'
                $rbSystemItem = Get-Item -LiteralPath $rbSystem -Force -ErrorAction SilentlyContinue
                if ($rbSystemItem) {
                    $rbSize = $rbSystemItem.Length
                    if ($rbSize -eq 0) {
                        if ($regBackTaskDriven) {
                            & $emit 'Registry' 'INFO' "RegBack\SYSTEM is 0 bytes - normal on build $regBackGuestBuild; RegBack is refreshed by the RegIdleBackup scheduled task inside the running guest, not by -EnableRegBackup"
                        }
                        else {
                            & $emit 'Registry' (& $toSev $sevRegBackEmpty) 'RegBack\SYSTEM is 0 bytes - no registry backup is available' "-EnableRegBackup"
                        }
                    }
                    else {
                        & $emit 'Registry' 'OK' "RegBack\SYSTEM is $([math]::Round($rbSize/1MB, 1)) MB"
                    }
                }
                else {
                    if ($regBackTaskDriven) {
                        & $emit 'Registry' 'INFO' "RegBack\SYSTEM not found - on build $regBackGuestBuild RegBack is populated by the RegIdleBackup scheduled task inside the running guest (not -EnableRegBackup)"
                    }
                    else {
                        & $emit 'Registry' (& $toSev $sevRegBackMissing) 'RegBack\SYSTEM not found - registry backups not configured' "-EnableRegBackup"
                    }
                }

                # Pending Setup CmdLine
                $setupProps = Get-ItemProperty 'HKLM:\BROKENSYSTEM\Setup' -ErrorAction SilentlyContinue
                if ($setupProps.SetupType -and $setupProps.SetupType -ne 0) {
                    & $emit 'Boot' (& $toSev $sevSetupMode) "Setup mode active (SetupType=$($setupProps.SetupType)) - VM will run: '$($setupProps.CmdLine)' on next boot"
                }

                # -- Critical boot services ------------------------------------------
                # These disabled = guaranteed BSOD 0x7B or non-boot
                $critical = @(
                    @{ N = 'disk'; ExpStart = 0; Desc = 'storage bus driver (0x7B if disabled)' }
                    @{ N = 'volmgr'; ExpStart = 0; Desc = 'volume manager (0x7B if disabled)' }
                    @{ N = 'partmgr'; ExpStart = 1; Desc = 'partition manager (0x7B if disabled)' }
                    @{ N = 'storport'; ExpStart = 0; Desc = 'storage port driver (0x7B if disabled)' }
                    @{ N = 'NTFS'; ExpStart = 1; Desc = 'NTFS filesystem driver (0x7B if disabled)' }
                    @{ N = 'volsnap'; ExpStart = 1; Desc = 'volume shadow copy filter' }
                    @{ N = 'msrpc'; ExpStart = 2; Desc = 'RPC subsystem' }
                    @{ N = 'rpcss'; ExpStart = 2; Desc = 'RPC Endpoint Mapper' }
                    @{ N = 'LSM'; ExpStart = 2; Desc = 'Local Session Manager' }
                )
                foreach ($s in $critical) {
                    $sp = "$svcRoot\$($s.N)"
                    if (Test-Path $sp) {
                        $start = (Get-ItemProperty $sp -ErrorAction SilentlyContinue).Start
                        if ($start -eq 4) {
                            & $emit 'Services' (& $toSev $sevCriticalSvcDisabled) "$($s.N) is DISABLED (Start=4) - $($s.Desc) [ re-enable: Set Start=$($s.ExpStart) ]" "-EnableDriverOrService $($s.N) -DriverStartType $(ConvertTo-DriverStartTypeName -StartValue $s.ExpStart)"
                        }
                    }
                }

                # -- Migration boot storage readiness ------------------------------
                # Report only unexpected settings. These values control whether the
                # boot bus/storage stack can enumerate the OS disk early enough to
                # satisfy the loader-provided boot device path.
                $bootStorageFindings = @(Get-BootStorageDriverFindings -ControlSetNames @($csName))
                foreach ($bs in $bootStorageFindings) {
                    $bsSeverity = if ($null -ne $bs.Severity) { [int]$bs.Severity } else { $sevBootStorageReadiness }
                    & $emit 'BootStorage' (& $toSev $bsSeverity) "$($bs.ControlSet): $($bs.Message)" $bs.Fix
                }

                # -- Azure/Hyper-V synthetic drivers ---------------------------------
                $synBad = 0
                foreach ($sd in (Get-SyntheticDriverSpec)) {
                    $sdSeverity = if ($null -ne $sd.Severity) { [int]$sd.Severity } else { $sevSyntheticDriverBroken }
                    $sdSvcPath = "$svcRoot\$($sd.Name)"
                    $sdExists = Test-Path $sdSvcPath
                    $sdStart = if ($sdExists) { (Get-ItemProperty $sdSvcPath -ErrorAction SilentlyContinue).Start } else { $null }
                    $sdBin = Resolve-DriverBinaryCandidate -Binary $sd.Bin -AlternatePatterns $sd.AlternateBinPatterns
                    $sdBinExists = [bool]$sdBin.Exists
                    $sdBinZero = $sdBinExists -and $sdBin.Size -eq 0
                    $sdBinName = if ($sdBinExists) { $sdBin.Name } else { $sd.Bin }
                    if (-not $sdExists) {
                        $sdFix = if (-not $sdBinExists -or $sdBinZero) {
                            "-RepairSystemFile $($sd.Bin), then restore the $($sd.Name) service key from a matching Windows image or registry backup"
                        }
                        else {
                            "Restore the $($sd.Name) service key from a matching Windows image or registry backup, then run -EnsureSyntheticDriversEnabled"
                        }
                        & $emit 'Drivers' (& $toSev $sdSeverity) "$($sd.Name) service key missing - $($sd.Desc) will not load" $sdFix
                        $synBad++
                    }
                    elseif (-not $sdBinExists -or $sdBinZero) {
                        $state = if (-not $sdBinExists) { 'missing' } else { '0-byte' }
                        & $emit 'Drivers' (& $toSev $sdSeverity) "$($sd.Name) binary $($sd.Bin) is $state - $($sd.Desc)" "-RepairSystemFile $($sd.Bin)"
                        $synBad++
                    }
                    elseif ($null -ne $sdStart -and [int]$sdStart -ne [int]$sd.Start) {
                        & $emit 'Drivers' (& $toSev $sdSeverity) "$($sd.Name) Start=$sdStart (expected $($sd.Start)) - $($sd.Desc)" "-EnsureSyntheticDriversEnabled"
                        $synBad++
                    }
                    else {
                        # Binary exists, non-zero, start value correct  -  verify signature
                        $sdSig = Test-MicrosoftSignature -FilePath $sdBin.Path
                        if (-not $sdSig.IsAcceptableMicrosoft) {
                            $sigSeverity = if ($sdSig.TrustState -eq 'ValidOtherPublisher') { $sevThirdPartyBootSystemDriver } else { $sdSeverity }
                            $sigSev = if ($sdSig.IsHardFailure) { 'CRIT' } else { & $toSev $sigSeverity }
                            & $emit 'Security' $sigSev "$sdBinName failed trust validation - $(Get-TrustStateDescription -Signature $sdSig)" "-RepairSystemFile $sdBinName"
                            $synBad++
                        }
                    }
                }
                if ($synBad -eq 0) {
                    & $emit 'Drivers' 'OK' "Azure synthetic drivers (vmbus/storvsc/netvsc) healthy"
                }

                # -- Hyper-V integration services ------------------------------------
                # These don't block boot but missing/broken ones cause "VM running but
                # unusable" states on Azure (no heartbeat, no graceful shutdown, no time
                # sync, no KVP metadata exchange, no VSS backup).
                $intSvcs = @(
                    @{ Name = 'vmicheartbeat'; Desc = 'Heartbeat (host knows OS is alive)' }
                    @{ Name = 'vmicshutdown'; Desc = 'Graceful shutdown from host/portal' }
                    @{ Name = 'vmictimesync'; Desc = 'Time synchronisation with host' }
                    @{ Name = 'vmickvpexchange'; Desc = 'KVP data exchange (Azure metadata/hostname)' }
                    @{ Name = 'vmicvss'; Desc = 'VSS integration (Azure Backup snapshots)' }
                )
                $intBad = 0
                foreach ($ic in $intSvcs) {
                    $icPath = "$svcRoot\$($ic.Name)"
                    $icExists = Test-Path $icPath
                    if (-not $icExists) {
                        & $emit 'HyperV' (& $toSev $sevIntegrationSvcMissing) "$($ic.Name) service key missing - $($ic.Desc)" "-EnableDriverOrService $($ic.Name) -DriverStartType Manual"
                        $intBad++
                        continue
                    }
                    $icProps = Get-ItemProperty $icPath -ErrorAction SilentlyContinue
                    $icStart = $icProps.Start
                    if ($icStart -eq 4) {
                        & $emit 'HyperV' (& $toSev $sevIntegrationSvcDisabled) "$($ic.Name) is DISABLED (Start=4) - $($ic.Desc)" "-EnableDriverOrService $($ic.Name) -DriverStartType Manual"
                        $intBad++
                        continue
                    }
                    # Check binary exists and signature
                    if ($icProps.ImagePath) {
                        $icBinPath = Resolve-GuestImagePath $icProps.ImagePath
                        $icBinExists = Test-Path -LiteralPath $icBinPath
                        $icBinZero = $icBinExists -and (Get-Item -LiteralPath $icBinPath -Force -ErrorAction SilentlyContinue).Length -eq 0
                        if (-not $icBinExists -or $icBinZero) {
                            $bState = if (-not $icBinExists) { 'missing' } else { '0-byte' }
                            & $emit 'HyperV' (& $toSev $sevIntegrationSvcBinMissing) "$($ic.Name) binary is $bState ($icBinPath) - $($ic.Desc)"
                            $intBad++
                        }
                        elseif ($icBinExists) {
                            $icSig = Test-MicrosoftSignature -FilePath $icBinPath
                            if (-not $icSig.IsAcceptableMicrosoft) {
                                & $emit 'Security' (& $toSev $sevBinarySignatureBad) "$($ic.Name) binary failed trust validation - $(Get-TrustStateDescription -Signature $icSig)" "-RepairSystemFile $(Split-Path $icBinPath -Leaf)"
                                $intBad++
                            }
                        }
                    }
                }
                if ($intBad -eq 0) {
                    & $emit 'HyperV' 'OK' 'Hyper-V integration services present and enabled (heartbeat/shutdown/timesync/kvp/vss)'
                }

                # -- Domain trust / Netlogon -----------------------------------------
                $tcpipParams = "$svcRoot\Tcpip\Parameters"
                $domainVal = (Get-ItemProperty $tcpipParams -ErrorAction SilentlyContinue).Domain
                $netlogonSt = (Get-ItemProperty "$svcRoot\Netlogon" -ErrorAction SilentlyContinue).Start
                $isDomainJoined = $domainVal -and $domainVal -notmatch '^(WORKGROUP|LOCALDOMAIN)?$'
                if ($isDomainJoined -and $netlogonSt -eq 4) {
                    & $emit 'Networking' (& $toSev $sevNetlogonDisabled) "Domain-joined (domain='$domainVal') but Netlogon is DISABLED (Start=4) - domain auth and RDP will fail" "-EnableDriverOrService Netlogon -DriverStartType Manual"
                }

                # -- RDP ------------------------------------------------------------
                $tsPath = "$ctrlRoot\Terminal Server"
                $rdpTcpPath = "$ctrlRoot\Terminal Server\WinStations\RDP-Tcp"
                $fDeny = (Get-ItemProperty $tsPath -ErrorAction SilentlyContinue).fDenyTSConnections
                if ($fDeny -eq 1) {
                    & $emit 'RDP' (& $toSev $sevRdpDenied) 'fDenyTSConnections=1 - RDP is disabled at canonical key' "-FixRDP"
                }
                elseif ($null -eq $fDeny) {
                    & $emit 'RDP' (& $toSev $sevRdpDenyUnknown) 'fDenyTSConnections not found - RDP state unclear' "-FixRDP"
                }
                else {
                    & $emit 'RDP' 'OK' 'fDenyTSConnections=0 - RDP is enabled'
                }

                # TermService, SessionEnv, UmRdpService
                foreach ($rdpSvc in @(
                        @{ N = 'TermService'; Desc = 'Remote Desktop Services'; Crit = $true }
                        @{ N = 'SessionEnv'; Desc = 'Remote Desktop Config'; Crit = $true }
                        @{ N = 'UmRdpService'; Desc = 'RDP UserMode Port Redirector'; Crit = $false }
                    )) {
                    $svcStart = (Get-ItemProperty "$svcRoot\$($rdpSvc.N)" -ErrorAction SilentlyContinue).Start
                    if ($svcStart -eq 4) {
                        $sev = if ($rdpSvc.Crit) { (& $toSev $sevRdpSvcDisabledCrit) } else { (& $toSev $sevRdpSvcDisabledWarn) }
                        & $emit 'RDP' $sev "$($rdpSvc.N) ($($rdpSvc.Desc)) is DISABLED (Start=4) - RDP will not work" "-FixRDP"
                    }
                    elseif ($null -ne $svcStart) {
                        & $emit 'RDP' 'OK' "$($rdpSvc.N) Start=$svcStart"
                    }
                }

                if (Test-Path $rdpTcpPath) {
                    $rdpP = Get-ItemProperty $rdpTcpPath -ErrorAction SilentlyContinue

                    # Port number
                    $rdpPort = $rdpP.PortNumber
                    if ($null -ne $rdpPort -and $rdpPort -ne 3389) {
                        & $emit 'RDP' (& $toSev $sevRdpNonDefaultPort) "RDP-Tcp port is $rdpPort (not the default 3389) - ensure firewall allows this port or run -FixRDP to reset" "-FixRDP"
                    }
                    else {
                        & $emit 'RDP' 'OK' "RDP-Tcp port: $(if ($null -eq $rdpPort) { '(not set, default 3389)' } else { $rdpPort })"
                    }

                    # Security layer
                    $sl = $rdpP.SecurityLayer
                    if ($null -ne $sl) {
                        $slDesc = switch ($sl) { 0 { 'RDP native (no SSL) - weakest encryption' } 1 { 'Negotiate' } 2 { 'SSL/TLS required' } default { "Unknown ($sl)" } }
                        $slSev = if ($sl -eq 0) { (& $toSev $sevRdpSecurityLayerWeak) } else { 'INFO' }
                        & $emit 'RDP' $slSev "SecurityLayer=$sl ($slDesc)"
                    }

                    # NLA / UserAuthentication
                    $ua = $rdpP.UserAuthentication
                    if ($ua -eq 0) {
                        & $emit 'RDP' (& $toSev $sevRdpNLADisabled) 'NLA is DISABLED (UserAuthentication=0) - any user can attempt login without pre-auth; run -EnableNLA to restore' "-EnableNLA"
                    }
                    elseif ($ua -eq 1) {
                        & $emit 'RDP' 'OK' 'NLA is enabled (UserAuthentication=1)'
                    }
                    else {
                        & $emit 'RDP' 'INFO' 'NLA/UserAuthentication not set on RDP-Tcp key (policy may control this)'
                    }

                    # fAllowSecProtocolNegotiation (also touched by -DisableNLA)
                    $aspn = $rdpP.fAllowSecProtocolNegotiation
                    if ($aspn -eq 0) {
                        & $emit 'RDP' (& $toSev $sevRdpSecProtoNeg) 'fAllowSecProtocolNegotiation=0 - security protocol negotiation disabled; run -EnableNLA or -FixRDP to reset' "-EnableNLA"
                    }

                    # MinEncryptionLevel (1=Low was set by -DisableNLA; default is typically 2)
                    $mel = $rdpP.MinEncryptionLevel
                    if ($null -ne $mel -and $mel -lt 2) {
                        & $emit 'RDP' (& $toSev $sevRdpMinEncLevel) "MinEncryptionLevel=$mel (below recommended 2) - may indicate NLA was disabled" "-EnableNLA"
                    }

                    # SSL certificate thumbprint - absence is normal (Windows generates one on first RDP connection)
                    $cert = $rdpP.SSLCertificateSHA1Hash
                    if ($null -ne $cert -and -not ($cert -is [byte[]] -and $cert.Count -eq 0)) {
                        & $emit 'RDP' 'OK' 'RDP SSL certificate thumbprint is present'
                    }
                    # No thumbprint = not flagged; Windows auto-generates one at first RDP connection

                    # MaxInstanceCount - if 0, RDP refuses every connection attempt
                    $maxInst = $rdpP.MaxInstanceCount
                    if ($null -ne $maxInst -and $maxInst -eq 0) {
                        & $emit 'RDP' (& $toSev $sevRdpMaxInstanceZero) "MaxInstanceCount=0 on RDP-Tcp - RDP will refuse ALL connections; run -FixRDP to reset" "-FixRDP"
                    }
                }
                else {
                    & $emit 'RDP' (& $toSev $sevRdpTcpKeyMissing) 'RDP-Tcp WinStation key not found - RDP listener may be misconfigured' "-FixRDP"
                }

                # RDP-related crypto services (required for certificate/key operations)
                foreach ($cryptSvc in @(
                        @{ N = 'KeyIso'; DefStart = 3; Desc = 'CNG Key Isolation (needed for RDP private key)' }
                        @{ N = 'CryptSvc'; DefStart = 2; Desc = 'Cryptographic Services (needed for cert store)' }
                        @{ N = 'CertPropSvc'; DefStart = 3; Desc = 'Certificate Propagation (needed for user certs)' }
                    )) {
                    $cs = (Get-ItemProperty "$svcRoot\$($cryptSvc.N)" -ErrorAction SilentlyContinue).Start
                    if ($cs -eq 4) {
                        & $emit 'RDP' (& $toSev $sevRdpCryptoSvcDisabled) "$($cryptSvc.N) ($($cryptSvc.Desc)) is DISABLED - RDP certificate operations will fail" "-FixRDPPermissions"
                    }
                }

                # TLS 1.2 explicitly disabled in SCHANNEL
                foreach ($tlsRole in @('Client', 'Server')) {
                    $tlsPath = "$ctrlRoot\SecurityProviders\SCHANNEL\Protocols\TLS 1.2\$tlsRole"
                    if (Test-Path $tlsPath) {
                        $tlsProps = Get-ItemProperty $tlsPath -ErrorAction SilentlyContinue
                        if ($tlsProps.Enabled -eq 0 -or $tlsProps.DisabledByDefault -eq 1) {
                            & $emit 'RDP' (& $toSev $sevRdpTlsDisabled) "TLS 1.2 $tlsRole is explicitly DISABLED in SCHANNEL - RDP SSL handshake may fail" "-FixRDP"
                        }
                    }
                }

                # NTLM restrictions
                $msv1 = Get-ItemProperty "$ctrlRoot\Lsa\MSV1_0" -ErrorAction SilentlyContinue
                if ($msv1) {
                    if ($msv1.RestrictSendingNTLMTraffic -ge 2 -or $msv1.RestrictReceivingNTLMTraffic -ge 1) {
                        & $emit 'RDP' (& $toSev $sevRdpNtlmRestrict) "NTLM restrictions: RestrictSending=$($msv1.RestrictSendingNTLMTraffic) RestrictReceiving=$($msv1.RestrictReceivingNTLMTraffic) - may block RDP auth" "-FixRDPAuth"
                    }
                }

                # LmCompatibilityLevel (too restrictive blocks older clients)
                $lsaProps = Get-ItemProperty "$ctrlRoot\Lsa" -ErrorAction SilentlyContinue
                $lmCompat = $lsaProps.LmCompatibilityLevel
                if ($null -ne $lmCompat -and $lmCompat -gt 5) {
                    & $emit 'RDP' (& $toSev $sevRdpLmCompat) "LmCompatibilityLevel=$lmCompat (>5) - may block NTLM-based RDP auth from some clients" "-FixRDPAuth"
                }

                # -- Credential Guard ------------------------------------------------
                $cgLsa = $lsaProps.LsaCfgFlags
                if ($cgLsa -and $cgLsa -ne 0) {
                    $lockType = if ($cgLsa -eq 1) { 'UEFI lock - registry change alone is insufficient' } else { 'software lock' }
                    & $emit 'Security' (& $toSev $sevCredentialGuard) "Credential Guard is enabled (LsaCfgFlags=$cgLsa, $lockType)" "-DisableCredentialGuard"
                }
                $runAsPPL = $lsaProps.RunAsPPL
                if ($null -ne $runAsPPL -and [int]$runAsPPL -ne 0) {
                    & $emit 'Security' (& $toSev $sevLsaPPL) "LSA Protected Process (RunAsPPL=$runAsPPL) is active - may affect some security tools"
                }
                $appProxyConnectorServices = [System.Collections.Generic.List[string]]::new()
                foreach ($svcKey in (Get-ChildItem $svcRoot -ErrorAction SilentlyContinue)) {
                    $svcProps = Get-ItemProperty $svcKey.PSPath -ErrorAction SilentlyContinue
                    $svcName = $svcKey.PSChildName
                    $svcDisplay = [string]$svcProps.DisplayName
                    $svcImage = [string]$svcProps.ImagePath
                    if ($svcName -in @('WAPCSvc', 'WAPCUpdaterSvc') -or
                        $svcDisplay -match '(?i)(AAD|Entra).*Application Proxy.*Connector|Application Proxy Connector' -or
                        $svcImage -match '(?i)AAD App Proxy Connector|Application Proxy Connector|WAPC') {
                        $label = if ($svcDisplay) { "$svcName ($svcDisplay)" } else { $svcName }
                        if (-not $appProxyConnectorServices.Contains($label)) { $appProxyConnectorServices.Add($label) }
                    }
                }
                if ($appProxyConnectorServices.Count -gt 0 -and $null -ne $runAsPPL -and [int]$runAsPPL -ne 0) {
                    & $emit 'Security' (& $toSev $sevAppProxyLsaProtection) "Microsoft Entra application proxy connector installed ($($appProxyConnectorServices -join ', ')) and LSA protection is enabled (RunAsPPL=$runAsPPL) - if Kerberos delegation fails or LSASS restarts after servicing, disable only LSA protection" "-DisableLsaProtection"
                }

                # -- Azure Guest Agent ------------------------------------------------
                foreach ($ag in @('WindowsAzureGuestAgent', 'RdAgent')) {
                    $ap = "$svcRoot\$ag"
                    if (Test-Path $ap) {
                        $aStart = (Get-ItemProperty $ap -ErrorAction SilentlyContinue).Start
                        if ($aStart -eq 4) {
                            & $emit 'AzureAgent' (& $toSev $sevAzureAgentDisabled) "$ag is DISABLED (Start=4) - VM will not respond to Azure platform operations" "-FixAzureGuestAgent"
                        }
                        elseif ($aStart -ne 2) {
                            & $emit 'AzureAgent' (& $toSev $sevAzureAgentWrongStart) "$ag Start=$aStart (expected 2/Auto)" "-FixAzureGuestAgent"
                        }
                        else {
                            & $emit 'AzureAgent' 'OK' "$ag Start=2 (Auto)"
                        }
                    }
                    else {
                        & $emit 'AzureAgent' (& $toSev $sevAzureAgentMissing) "$ag not found in registry - agent may not be installed" "-InstallAzureVMAgent"
                    }
                }

                # -- Networking: BFE & TCP/IP -----------------------------------------
                $bfeStart = (Get-ItemProperty "$svcRoot\BFE" -ErrorAction SilentlyContinue).Start
                if ($bfeStart -eq 4) {
                    & $emit 'Networking' (& $toSev $sevBfeDisabled) 'BFE (Base Filtering Engine) is DISABLED - Windows Firewall and IPSec/network policy will not function' "-EnableBFE"
                }
                elseif ($null -ne $bfeStart) {
                    & $emit 'Networking' 'OK' "BFE Start=$bfeStart (enabled)"
                }
                $tcpStart = (Get-ItemProperty "$svcRoot\Tcpip" -ErrorAction SilentlyContinue).Start
                if ($tcpStart -eq 4) {
                    & $emit 'Networking' (& $toSev $sevTcpipDisabled) 'Tcpip service is DISABLED - no network will be available' "-ResetNetworkStack"
                }

                # nsi (Network Store Interface) - core TCP/IP dependency; if disabled, zero networking
                $nsiStart = (Get-ItemProperty "$svcRoot\nsi" -ErrorAction SilentlyContinue).Start
                if ($nsiStart -eq 4) {
                    & $emit 'Networking' (& $toSev $sevNsiDisabled) "nsi (Network Store Interface) is DISABLED - TCP/IP stack is non-functional; all networking will fail" "-EnableDriverOrService nsi -DriverStartType Automatic"
                }

                # Additional networking services
                foreach ($netSvc in @(
                        @{ N = 'Dnscache'; Desc = 'DNS Client - name resolution will fail' }
                        @{ N = 'NlaSvc'; Desc = 'Network Location Awareness - network profile detection will fail' }
                        @{ N = 'Dhcp'; Desc = 'DHCP Client - automatic IP configuration will not work' }
                        @{ N = 'LanmanWorkstation'; Desc = 'Workstation service (SMB client) - file sharing access will fail' }
                        @{ N = 'LanmanServer'; Desc = 'Server service (SMB server) - file sharing hosting will fail' }
                    )) {
                    $ns = (Get-ItemProperty "$svcRoot\$($netSvc.N)" -ErrorAction SilentlyContinue).Start
                    if ($ns -eq 4) {
                        & $emit 'Networking' (& $toSev $sevNetSvcDisabled) "$($netSvc.N) is DISABLED - $($netSvc.Desc)" "-ResetNetworkStack"
                    }
                }

                # SAN policy (partmgr)
                $sanPolicy = (Get-ItemProperty "$svcRoot\partmgr\Parameters" -ErrorAction SilentlyContinue).SanPolicy
                if ($null -ne $sanPolicy -and $sanPolicy -ne 1 -and $sanPolicy -ne 0) {
                    $sanDesc = switch ($sanPolicy) { 2 { 'OfflineShared - shared disks stay offline' } 3 { 'OfflineAll - all SAN disks stay offline' } 4 { 'OfflineInternal - internal SAN disks offline' } default { "Value=$sanPolicy" } }
                    & $emit 'Networking' (& $toSev $sevSanPolicy) "SAN policy is set to $sanDesc - data disks may not come online after migration; run -FixSanPolicy to set OnlineAll" "-FixSanPolicy"
                }
                elseif ($null -ne $sanPolicy) {
                    & $emit 'Networking' 'OK' "SAN policy: OnlineAll ($sanPolicy)"
                }

                # -- Boot/System driver binary + trust health ---------------------------
                # We flag drivers registered to load at boot/system start whose binary is
                # ABSENT, zero-byte, or fails image trust validation - all three WILL stop
                # the boot. Inbox hardware drivers (LSI, Intel RST, Broadcom HBA, etc.)
                # ship with Windows but carry vendor company names; validly signed ones
                # are reported separately because they are safe and present on disk.
                # Use -DisableThirdPartyDrivers to intentionally suppress all non-MS
                # drivers when troubleshooting a clean-boot scenario.
                $missingDrivers = [System.Collections.Generic.List[string]]::new()
                $thirdPartyBootSystemDrivers = [System.Collections.Generic.List[string]]::new()
                $badSignatureDrivers = [System.Collections.Generic.List[PSCustomObject]]::new()
                $unverifiedDrivers = [System.Collections.Generic.List[string]]::new()
                $trustedDriverCount = 0
                $knownSafeBootSystemDriverNames = [string[]]@()
                foreach ($safeDriverSpec in (Get-DeviceClassFilterSpec | Where-Object { $_.Name -in @('HDC', 'SCSIAdapter') })) {
                    foreach ($safeDriverName in @($safeDriverSpec.SafeFilters | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
                        if ($knownSafeBootSystemDriverNames -inotcontains $safeDriverName) {
                            $knownSafeBootSystemDriverNames += $safeDriverName
                        }
                    }
                }
                Get-ChildItem $svcRoot -ErrorAction SilentlyContinue | ForEach-Object {
                    $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                    # Only kernel/filesystem drivers (Type 1/2) at Boot(0) or System(1) start
                    if ($p.Type -notin @(1, 2) -or $p.Start -notin @(0, 1)) { return }
                    $svcName = $_.PSChildName
                    # Windows default: when ImagePath is absent the driver file is
                    # System32\drivers\<ServiceName>.sys, so those still get checked.
                    $imgDisplay = if ($p.ImagePath) { $p.ImagePath } else { "system32\drivers\$svcName.sys (default path)" }
                    $imgR = if ($p.ImagePath) {
                        Resolve-GuestImagePath $p.ImagePath
                    }
                    else {
                        Join-Path $script:WinDriveLetter "Windows\System32\drivers\$svcName.sys"
                    }
                    # Flag if binary is missing or 0 bytes (corrupt/truncated)
                    if (-not (Test-Path $imgR)) { $missingDrivers.Add("$svcName ($imgDisplay)") }
                    elseif ((Get-Item -LiteralPath $imgR -ErrorAction SilentlyContinue).Length -eq 0) { $missingDrivers.Add("$svcName ($imgDisplay) [0 bytes]") }
                    else {
                        # Validate image trust on present boot/system drivers
                        $drvSig = Test-MicrosoftSignature -FilePath $imgR
                        $isKnownSafeBootSystemDriver = ($drvSig.TrustState -eq 'ValidOtherPublisher' -and
                            $knownSafeBootSystemDriverNames -icontains $svcName -and
                            ([IO.Path]::GetFileName($imgR) -ieq "$svcName.sys"))
                        $driverSummary = "$svcName ($imgDisplay) [$($drvSig.Status)]"

                        if ($drvSig.IsHardFailure) {
                            $badSignatureDrivers.Add([PSCustomObject]@{
                                    Name         = $svcName
                                    ImagePath    = $imgDisplay
                                    ResolvedPath = $imgR
                                    FileName     = [IO.Path]::GetFileName($imgR)
                                    Start        = [int]$p.Start
                                    Type         = [int]$p.Type
                                    ErrorControl = if ($null -ne $p.ErrorControl) { [int]$p.ErrorControl } else { 1 }
                                    Group        = if ($p.Group) { [string]$p.Group } else { '' }
                                    Signature    = $drvSig
                                })
                        }
                        elseif ($isKnownSafeBootSystemDriver) { return }
                        elseif ($drvSig.TrustState -eq 'ValidOtherPublisher') { $thirdPartyBootSystemDrivers.Add($driverSummary) }
                        elseif ($drvSig.TrustState -eq 'ValidMicrosoft') { $trustedDriverCount++ }
                        elseif ($drvSig.IsAcceptableMicrosoft) { $unverifiedDrivers.Add($driverSummary) }
                        else { $unverifiedDrivers.Add($driverSummary) }
                    }
                }
                if ($missingDrivers.Count -gt 0) {
                    & $emit 'Drivers' (& $toSev $sevMissingDriverBinaries) "$($missingDrivers.Count) Boot/System driver(s) registered but binary MISSING or 0-byte - will BSOD on boot: $($missingDrivers -join ', ')" "-RepairSystemFile <name.sys> or -DisableThirdPartyDrivers"
                }
                else {
                    # Presence and trust are different results; say which one this is.
                    $trustSummary = "trust: $trustedDriverCount verified, $($badSignatureDrivers.Count) invalid, $($unverifiedDrivers.Count) unverified, $($thirdPartyBootSystemDrivers.Count) third-party"
                    if ($badSignatureDrivers.Count -gt 0) {
                        # Every path resolved, but at least one of those files will be
                        # refused at load. Reporting that as OK reads as an all-clear,
                        # which is the opposite of what the next line goes on to say.
                        & $emit 'Drivers' 'WARN' "All Boot/System driver paths are present and non-zero, but $($badSignatureDrivers.Count) failed image trust validation ($trustSummary)" '-RepairSystemFile <name.sys>'
                    }
                    else {
                        & $emit 'Drivers' 'OK' "All Boot/System driver paths are present and non-zero ($trustSummary)"
                    }
                }
                if ($badSignatureDrivers.Count -gt 0) {
                    # Connect the trust failure to real boot risk. A Boot/System driver with
                    # ErrorControl=3 that the kernel refuses to load is boot-fatal and is the
                    # exact shape of CRITICAL_SERVICE_FAILED (0x5A) / STATUS_INVALID_IMAGE_HASH.
                    foreach ($bad in ($badSignatureDrivers | Sort-Object @{E = { $_.ErrorControl }; Descending = $true }, Name)) {
                        $startName = if ($bad.Start -eq 0) { 'Boot' } else { 'System' }
                        $typeName = if ($bad.Type -eq 2) { 'file-system driver' } else { 'kernel driver' }
                        $ecName = switch ($bad.ErrorControl) { 0 { 'Ignore' } 1 { 'Normal' } 2 { 'Severe' } 3 { 'Critical' } default { "$($bad.ErrorControl)" } }
                        $trustText = Get-TrustStateDescription -Signature $bad.Signature
                        $impact = if ($bad.ErrorControl -ge 3) {
                            'Windows will stop with CRITICAL_SERVICE_FAILED (0x5A, STATUS_INVALID_IMAGE_HASH 0xC0000428) during driver initialization; Safe Mode does not avoid it'
                        }
                        elseif ($bad.ErrorControl -eq 2) {
                            'Windows will fail this driver and fall back to Last Known Good; boot may still fail'
                        }
                        else {
                            'the driver will not load; dependent storage/network/security functionality will be unavailable'
                        }
                        $severity = if ($bad.ErrorControl -ge 3) { 'CRIT' } else { & $toSev $sevBinarySignatureBad }
                        & $emit 'Security' $severity ("$($bad.Name) is a $startName-start $typeName with ErrorControl=$ecName; $($bad.FileName) $trustText - $impact") "-RepairSystemFile $($bad.FileName)"
                    }
                }
                if ($unverifiedDrivers.Count -gt 0) {
                    # Honest reporting: Microsoft-branded images this host cannot prove or
                    # disprove. Grouped into one advisory so it never floods the report.
                    & $emit 'Security' 'INFO' "$($unverifiedDrivers.Count) Boot/System driver(s) are Microsoft-branded but could not be cryptographically verified from this host ($($script:OfflineCatalogStoreSummary)): $($unverifiedDrivers -join ', ')" ''
                }
                if ($thirdPartyBootSystemDrivers.Count -gt 0) {
                    & $emit 'Security' (& $toSev $sevThirdPartyBootSystemDriver) "$($thirdPartyBootSystemDrivers.Count) Boot/System driver(s) are validly signed by non-Microsoft publishers: $($thirdPartyBootSystemDrivers -join ', ')" "-GetServicesReport -IssuesOnly"
                }

                # -- Device class filters ---------------------------------------------
                $classRoot = "HKLM:\BROKENSYSTEM\$csName\Control\Class"
                foreach ($fc in (Get-DeviceClassFilterSpec)) {
                    $cp = "$classRoot\$($fc.GUID)"
                    if (-not (Test-Path $cp)) { continue }
                    $safe = [string[]]$fc.SafeFilters
                    $filterSev = if ($fc.Risk -eq 'CRITICAL') { & $toSev $sevDeviceFiltersCrit } else { & $toSev $sevDeviceFiltersWarn }
                    foreach ($ft in @('UpperFilters', 'LowerFilters')) {
                        $raw = (Get-ItemProperty $cp -ErrorAction SilentlyContinue).$ft
                        $active = @($raw | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                        $suspect = @($active | Where-Object { $safe -inotcontains $_ })
                        if ($suspect.Count -gt 0) {
                            & $emit 'DeviceFilters' $filterSev "$($fc.Name) $ft contains non-standard entries: $($suspect -join ', ')" "-FixDeviceFilters"
                        }
                    }
                }

                $instanceFilterFindings = @(Get-BootCriticalDeviceInstanceFilterFindings -ControlSetNames @($csName))
                foreach ($instanceFilter in $instanceFilterFindings) {
                    & $emit 'DeviceFilters' (& $toSev $sevDeviceFiltersCrit) "$($instanceFilter.ControlSet): $($instanceFilter.Message)" $instanceFilter.Fix
                }

                # -- Orphaned NDIS bindings --------------------------------------------
                $orphanIds = [System.Collections.Generic.List[string]]::new()
                $seenComp = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
                foreach ($cg in @('{4D36E973-E325-11CE-BFC1-08002BE10318}', '{4D36E974-E325-11CE-BFC1-08002BE10318}', '{4D36E975-E325-11CE-BFC1-08002BE10318}')) {
                    $ck = "HKLM:\BROKENSYSTEM\$csName\Control\Class\$cg"
                    if (-not (Test-Path $ck)) { continue }
                    Get-ChildItem $ck -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
                        $pp = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                        $cid = if ($pp.ComponentId) { $pp.ComponentId } else { $pp.ComponentID }
                        if (-not $cid -or $cid -match '^ms_' -or -not $seenComp.Add($cid)) { return }
                        $sn = $cid -replace '^ms_', ''
                        $ipp = (Get-ItemProperty "$svcRoot\$sn" -ErrorAction SilentlyContinue).ImagePath
                        if ($null -eq $ipp) { return }
                        $ir = Resolve-GuestImagePath $ipp
                        if (-not (Test-Path $ir) -or (Test-Path $ir) -and (Get-Item -LiteralPath $ir -ErrorAction SilentlyContinue).Length -eq 0) { $orphanIds.Add($cid) }
                    }
                }
                if ($orphanIds.Count -gt 0) {
                    & $emit 'Networking' (& $toSev $sevOrphanedNdis) "Orphaned NDIS binding(s) with missing binary: $($orphanIds -join ', ') - may prevent network initialisation at boot" "-FixNetBindings"
                }
                else {
                    & $emit 'Networking' 'OK' 'No orphaned NDIS binding components'
                }

                # -- Windows Update services ------------------------------------------
                foreach ($wu in @('wuauserv', 'UsoSvc', 'WaaSMedicSvc')) {
                    $wuS = (Get-ItemProperty "$svcRoot\$wu" -ErrorAction SilentlyContinue).Start
                    if ($wuS -eq 4) {
                        & $emit 'WindowsUpdate' (& $toSev $sevUpdateWuDisabled) "$wu is disabled (Start=4) - intentionally stopped via -DisableWindowsUpdate; re-enable on the live VM with: Set-Service -Name $wu -StartupType Automatic"
                    }
                }

                # AppIDSvc (AppLocker enforcement service)
                $appIdSvc = (Get-ItemProperty "$svcRoot\AppIDSvc" -ErrorAction SilentlyContinue).Start
                $script:_sysCheckAppIdSvcStart = $appIdSvc
                if ($null -ne $appIdSvc -and $appIdSvc -ne 4) {
                    & $emit 'Security' (& $toSev $sevAppIdSvc) "AppIDSvc (Application Identity) Start=$appIdSvc - this service is required for AppLocker to enforce rules"
                }

                # -- Hyper-V ACPI device IDs -----------------------------------------
                $enumAcpiRoot = "HKLM:\BROKENSYSTEM\$csName\Enum\ACPI"
                $msft1000Present = Test-Path "$enumAcpiRoot\MSFT1000"
                $msft1002Present = Test-Path "$enumAcpiRoot\MSFT1002"
                if (-not $msft1000Present -or -not $msft1002Present) {
                    $missing = @()
                    if (-not $msft1000Present) { $missing += 'MSFT1000 (VMBus)' }
                    if (-not $msft1002Present) { $missing += 'MSFT1002 (Hyper-V Gen Counter)' }
                    & $emit 'ACPI' (& $toSev $sevACPISettings) "Hyper-V ACPI device $(if ($missing.Count -gt 1){'entries'}else{'entry'}) missing: $($missing -join ', ') - newer ACPI IDs needed for full Hyper-V synthetic device support" "-CopyACPISettings"
                }
                else {
                    & $emit 'ACPI' 'OK' 'Hyper-V ACPI device entries present (MSFT1000, MSFT1002)'
                }

                # -- Driver Verifier --------------------------------------------------
                $mmPath = "$ctrlRoot\Session Manager\Memory Management"
                if (Test-Path $mmPath) {
                    $vDrivers = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDrivers
                    $vLevel = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDriverLevel
                    if ($vDrivers -or $vLevel) {
                        $targets = if ($vDrivers -eq '*') { 'ALL drivers' } elseif ($vDrivers) { "drivers: $vDrivers" } else { "level=$vLevel" }
                        & $emit 'Drivers' (& $toSev $sevDriverVerifier) "Driver Verifier is ENABLED ($targets) - will BSOD on any verification failure; disable with -DisableDriverVerifier" "-DisableDriverVerifier"
                    }
                    else {
                        & $emit 'Drivers' 'OK' 'Driver Verifier is not configured'
                    }
                }

                # -- Firewall state ---------------------------------------------------
                $fwBase = "$SystemRoot\Services\SharedAccess\Parameters\FirewallPolicy"
                $fwAllDisabled = $true
                foreach ($fwProf in @('DomainProfile', 'StandardProfile', 'PublicProfile')) {
                    $fwPath = "$fwBase\$fwProf"
                    if (Test-Path $fwPath) {
                        $fwEnabled = (Get-ItemProperty $fwPath -ErrorAction SilentlyContinue).EnableFirewall
                        if ($fwEnabled -ne 0) { $fwAllDisabled = $false }
                    }
                }
                if ($fwAllDisabled) {
                    & $emit 'Firewall' 'OK' 'Windows Firewall is disabled on all profiles'
                }

                # Duplicate package SIDs can grow this value to hundreds of entries and
                # leave mpssvc cycling between Starting and Stopping with error 0x45b.
                $appCsPath = "$svcRoot\mpssvc\Parameters\AppCs"
                $loopbackState = $null
                try {
                    $loopbackState = Invoke-FirewallDebugLoopbackAppsAsSystem -AppCsPath $appCsPath -Operation Inspect
                }
                catch {
                    & $emit 'Firewall' (& $toSev $sevFirewallLoopbackAccess) "Unable to inspect protected mpssvc DebugedLoopbackApps as SYSTEM: $($_.Exception.Message)"
                }
                if ($loopbackState) {
                    if ($loopbackState.PermissionsAdjusted) {
                        & $emit 'Firewall' 'INFO' 'mpssvc AppCs denied access; SYSTEM temporarily took ownership and FullControl, then restored the original owner and DACL'
                    }
                    if ($loopbackState.ActiveValueExists) {
                        $loopbackSeverity = Get-FirewallDebugLoopbackAppsEntrySeverity -EntryCount $loopbackState.EntryCount
                        $previewText = ''
                        if ($loopbackSeverity -eq 'CRIT') {
                            $duplicatePreview = @($loopbackState.DuplicateSids | Select-Object -First 5)
                            if ($duplicatePreview.Count -gt 0) {
                                $suffix = if ($loopbackState.DuplicateSidCount -gt $duplicatePreview.Count) { ', ...' } else { '' }
                                $previewText = "; duplicate examples: $($duplicatePreview -join ', ')$suffix"
                            }
                        }
                        $duplicateText = if ($loopbackState.DuplicateSidCount -gt 0) {
                            " with $($loopbackState.DuplicateSidCount) duplicated SID(s) and $($loopbackState.DuplicateEntryCount) extra duplicate occurrence(s)$previewText"
                        }
                        else {
                            ' with no duplicate SIDs'
                        }

                        if ($loopbackSeverity -eq 'CRIT') {
                            & $emit 'Firewall' 'CRIT' "mpssvc DebugedLoopbackApps contains $($loopbackState.EntryCount) entries$duplicateText, at or above the documented 683-entry failure scale - known Windows Defender Firewall start/stop loop and error 0x45b risk" "-FixFirewallDebugLoopbackApps"
                        }
                        elseif ($loopbackSeverity -eq 'WARN') {
                            & $emit 'Firewall' 'WARN' "mpssvc DebugedLoopbackApps contains $($loopbackState.EntryCount) entries$duplicateText, above the 600-entry warning threshold - approaching the observed Windows Defender Firewall error 0x45b failure scale" "-FixFirewallDebugLoopbackApps"
                        }
                        else {
                            & $emit 'Firewall' 'OK' "mpssvc DebugedLoopbackApps contains $($loopbackState.EntryCount) entries$duplicateText (normal; warning threshold is above 600 entries)"
                        }
                    }
                    elseif ($loopbackState.RenamedValueExists) {
                        & $emit 'Firewall' 'CRIT' 'mpssvc DebugedLoopbackApps_ archive exists but the required empty DebugedLoopbackApps value is missing; mpssvc may fail to start' '-FixFirewallDebugLoopbackApps'
                    }
                    else {
                        & $emit 'Firewall' 'OK' 'mpssvc DebugedLoopbackApps value not present'
                    }
                }

                # -- Gen2 UEFI / Trusted Launch security (registry-based) ------------
                if ($script:VMGen -eq 2) {
                    Write-Host "--- Gen2 UEFI / Trusted Launch Security" -ForegroundColor DarkGray

                    # Secure Boot state: did the guest OS previously boot with Secure Boot?
                    $sbStatePath = "$ctrlRoot\SecureBoot\State"
                    $sbEnabled = $null
                    if (Test-Path $sbStatePath) {
                        $sbEnabled = (Get-ItemProperty $sbStatePath -ErrorAction SilentlyContinue).UEFISecureBootEnabled
                    }
                    if ($sbEnabled -eq 1) {
                        & $emit 'UEFI' (& $toSev $sevSecureBootState) 'Guest was previously running with Secure Boot enabled (UEFISecureBootEnabled=1)'
                        # Cross-reference: testsigning or nointegritychecks in BCD would be fatal
                        try {
                            $bcdPathSb = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter.TrimEnd('\')
                            if (Test-Path $bcdPathSb) {
                                $bcdSbText = (& bcdedit.exe /store "$bcdPathSb" /enum all 2>&1) | Out-String
                                if ($bcdSbText -match 'testsigning\s+yes') {
                                    & $emit 'UEFI' (& $toSev $sevSecureBootConflict) 'CONFLICT: Test signing is ON but guest had Secure Boot enabled - VM will fail to boot with Secure Boot; disable test signing first' "-DisableTestSigning"
                                }
                                if ($bcdSbText -match 'nointegritychecks\s+yes') {
                                    & $emit 'UEFI' (& $toSev $sevSecureBootConflict) 'CONFLICT: nointegritychecks is ON but guest had Secure Boot enabled - VM will fail to boot with Secure Boot' "-FixBoot"
                                }
                            }
                        }
                        catch { <# BCD already checked above; non-fatal here #> }
                    }
                    elseif ($null -ne $sbEnabled) {
                        & $emit 'UEFI' 'OK' 'Secure Boot was not active on guest (UEFISecureBootEnabled=0)'
                    }
                    else {
                        & $emit 'UEFI' 'INFO' 'SecureBoot\\State key not found - guest may not have booted with UEFI Secure Boot awareness'
                    }

                    # Secure Boot 2023 certificate update status (registry snapshot from last boot on real firmware)
                    $sbServicingPath = "$ctrlRoot\SecureBoot\Servicing"
                    $sbMainPath = "$ctrlRoot\SecureBoot"
                    $hvCaveat = '(Note: these registry values reflect the last boot environment; if this VM was previously booted as nested on Hyper-V, these values may reflect Hyper-V firmware, not the original Azure VM)'
                    if ($sbEnabled -eq 1) {
                        # UEFICA2023Status
                        if (Test-Path $sbServicingPath) {
                            $sbServProps = Get-ItemProperty $sbServicingPath -ErrorAction SilentlyContinue
                            $certStatus = $sbServProps.UEFICA2023Status
                            if ($certStatus -eq 'Updated') {
                                & $emit 'UEFI' 'INFO' 'Secure Boot 2023 certificates were applied (UEFICA2023Status=Updated)'
                            }
                            elseif ($null -ne $certStatus) {
                                & $emit 'UEFI' (& $toSev $sevSecureBootCertNotUpdated) "Secure Boot 2023 certificates not yet applied (UEFICA2023Status=$certStatus) - certificates expire Jun-Oct 2026. $hvCaveat"
                            }
                            else {
                                & $emit 'UEFI' (& $toSev $sevSecureBootCertNotUpdated) "Secure Boot enabled but UEFICA2023Status not set - 2023 certificate update may not have started. $hvCaveat"
                            }
                            # UEFICA2023Error
                            $certError = $sbServProps.UEFICA2023Error
                            if ($null -ne $certError) {
                                $certErrorEvent = $sbServProps.UEFICA2023ErrorEvent
                                $errorDetail = "Secure Boot certificate update error detected (UEFICA2023Error=$certError)"
                                if ($null -ne $certErrorEvent) { $errorDetail += " (ErrorEvent=$certErrorEvent)" }
                                $errorDetail += ". $hvCaveat"
                                & $emit 'UEFI' (& $toSev $sevSecureBootCertError) $errorDetail
                            }
                        }
                        else {
                            & $emit 'UEFI' (& $toSev $sevSecureBootCertNotUpdated) "Secure Boot enabled but SecureBoot\Servicing key absent - 2023 certificate update status unknown. $hvCaveat"
                        }
                        # AvailableUpdates bitmask (informational)
                        if (Test-Path $sbMainPath) {
                            $availUpdates = (Get-ItemProperty $sbMainPath -ErrorAction SilentlyContinue).AvailableUpdates
                            if ($null -ne $availUpdates) {
                                $availHex = '0x{0:X}' -f [int]$availUpdates
                                if ($availUpdates -eq 0 -or $availUpdates -eq 0x4000) {
                                    & $emit 'UEFI' 'INFO' "Secure Boot AvailableUpdates=$availHex - all certificate update steps completed"
                                }
                                else {
                                    & $emit 'UEFI' 'INFO' "Secure Boot AvailableUpdates=$availHex - certificate update steps still pending (0x40=DB, 0x800/0x1000=3P certs, 0x4=KEK, 0x100=boot mgr)"
                                }
                            }
                        }
                    }

                    # VBS / DeviceGuard configuration
                    $dgPath = "$ctrlRoot\DeviceGuard"
                    if (Test-Path $dgPath) {
                        $dgProps = Get-ItemProperty $dgPath -ErrorAction SilentlyContinue
                        $vbsEnabled = $dgProps.EnableVirtualizationBasedSecurity
                        if ($vbsEnabled -eq 1) {
                            & $emit 'UEFI' (& $toSev $sevDeviceGuardVbs) 'Virtualization-Based Security (VBS) is enabled in DeviceGuard registry'
                        }
                        $platReq = $dgProps.RequirePlatformSecurityFeatures
                        if ($null -ne $platReq -and $platReq -ge 3) {
                            & $emit 'UEFI' (& $toSev $sevDeviceGuardPlatReq) "DeviceGuard RequirePlatformSecurityFeatures=$platReq (requires Secure Boot + DMA protection) - not all Azure VM sizes support DMA protection; may prevent VBS from starting"
                        }
                        elseif ($null -ne $platReq -and $platReq -ge 1) {
                            & $emit 'UEFI' 'OK' "DeviceGuard RequirePlatformSecurityFeatures=$platReq (Secure Boot only)"
                        }
                    }

                    # HVCI (Hypervisor-enforced Code Integrity)
                    $hvciPath = "$ctrlRoot\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"
                    if (Test-Path $hvciPath) {
                        $hvciEnabled = (Get-ItemProperty $hvciPath -ErrorAction SilentlyContinue).Enabled
                        if ($hvciEnabled -eq 1) {
                            & $emit 'UEFI' (& $toSev $sevHvciEnabled) 'HVCI (Hypervisor-enforced Code Integrity) is enabled - unsigned kernel drivers will be blocked at runtime'
                        }
                    }

                    # Early Launch Anti-Malware driver load policy
                    $elamPath = "$ctrlRoot\EarlyLaunch"
                    if (Test-Path $elamPath) {
                        $driverLoadPolicy = (Get-ItemProperty $elamPath -ErrorAction SilentlyContinue).DriverLoadPolicy
                        if ($null -ne $driverLoadPolicy) {
                            $policyDesc = switch ([int]$driverLoadPolicy) {
                                1 { 'Good only - unknown/bad boot drivers will be blocked' }
                                3 { 'Good and unknown' }
                                7 { 'Good, unknown, and bad (but not malicious)' }
                                8 { 'All drivers allowed' }
                                default { "Value=$driverLoadPolicy" }
                            }
                            if ([int]$driverLoadPolicy -eq 1) {
                                & $emit 'UEFI' (& $toSev $sevEarlyLaunchPolicy) "EarlyLaunch DriverLoadPolicy=$driverLoadPolicy ($policyDesc) - restrictive policy may block third-party boot drivers"
                            }
                            else {
                                & $emit 'UEFI' 'OK' "EarlyLaunch DriverLoadPolicy=$driverLoadPolicy ($policyDesc)"
                            }
                        }
                    }

                    # TPM driver state (relevant for vTPM-dependent features)
                    $tpmSvcPath = "$svcRoot\TPM"
                    if (Test-Path $tpmSvcPath) {
                        $tpmStart = (Get-ItemProperty $tpmSvcPath -ErrorAction SilentlyContinue).Start
                        if ($tpmStart -eq 4) {
                            & $emit 'UEFI' (& $toSev $sevTpmDriverDisabled) 'TPM service is DISABLED (Start=4) - vTPM-dependent features (BitLocker auto-unlock, Windows Hello, attestation) will not function'
                        }
                    }
                }

                # -- Session Manager (BootExecute / SetupExecute) -----------------
                $smPath = "$ctrlRoot\Session Manager"
                if (Test-Path $smPath) {
                    $smProps = Get-ItemProperty $smPath -ErrorAction SilentlyContinue
                    $sys32Path = Join-Path $script:WinDriveLetter 'Windows\System32'

                    # BootExecute
                    $bootExec = @($smProps.BootExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                    $danglingBoot = @()
                    $thirdPartyBoot = @()
                    foreach ($entry in $bootExec) {
                        if ($entry -match '^autocheck\s+autochk') { continue }
                        $nativeName = ($entry -split '\s+', 2)[0]
                        $nativePath = Join-Path $sys32Path "$nativeName.exe"
                        if (-not (Test-Path $nativePath) -or (Test-Path $nativePath) -and (Get-Item -LiteralPath $nativePath -ErrorAction SilentlyContinue).Length -eq 0) {
                            $danglingBoot += $entry
                        }
                        else {
                            $thirdPartyBoot += $entry
                        }
                    }
                    # Signature check on third-party BootExecute entries
                    $unsignedBoot = @()
                    foreach ($entry in $thirdPartyBoot) {
                        $tpName = ($entry -split '\s+', 2)[0]
                        $tpPath = Join-Path $sys32Path "$tpName.exe"
                        $tpSig = Test-MicrosoftSignature -FilePath $tpPath
                        if (-not $tpSig.IsAcceptableMicrosoft) { $unsignedBoot += $entry }
                    }
                    if ($danglingBoot.Count -gt 0) {
                        & $emit 'Boot' (& $toSev $sevBootExecDangling) "BootExecute has $($danglingBoot.Count) entry/entries with missing binaries (will hang boot at black screen): $($danglingBoot -join '; ')" "-FixSessionManager"
                    }
                    elseif ($unsignedBoot.Count -gt 0) {
                        & $emit 'Security' (& $toSev $sevBinarySignatureBad) "BootExecute has $($unsignedBoot.Count) non-Microsoft-signed entry/entries (possible tampering): $($unsignedBoot -join '; ')" "-FixSessionManager"
                    }
                    elseif ($thirdPartyBoot.Count -gt 0) {
                        & $emit 'Boot' (& $toSev $sevBootExecThirdParty) "BootExecute has $($thirdPartyBoot.Count) third-party entry/entries (binaries present): $($thirdPartyBoot -join '; ')" "-FixSessionManager"
                    }
                    else {
                        & $emit 'Boot' 'OK' 'BootExecute: default (autocheck autochk *)'
                    }

                    # SetupExecute
                    $setupExec = @($smProps.SetupExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                    if ($setupExec.Count -gt 0) {
                        $danglingSetup = @()
                        $unsignedSetup = @()
                        foreach ($entry in $setupExec) {
                            $nativeName = ($entry -split '\s+', 2)[0]
                            $nativePath = Join-Path $sys32Path "$nativeName.exe"
                            if (-not (Test-Path $nativePath) -or (Test-Path $nativePath) -and (Get-Item -LiteralPath $nativePath -ErrorAction SilentlyContinue).Length -eq 0) {
                                $danglingSetup += $entry
                            }
                            else {
                                $seSig = Test-MicrosoftSignature -FilePath $nativePath
                                if (-not $seSig.IsAcceptableMicrosoft) { $unsignedSetup += $entry }
                            }
                        }
                        if ($danglingSetup.Count -gt 0) {
                            & $emit 'Boot' (& $toSev $sevSetupExecDangling) "SetupExecute has $($danglingSetup.Count) entry/entries with missing binaries (will hang boot): $($danglingSetup -join '; ')" "-FixSessionManager"
                        }
                        elseif ($unsignedSetup.Count -gt 0) {
                            & $emit 'Security' (& $toSev $sevBinarySignatureBad) "SetupExecute has $($unsignedSetup.Count) non-Microsoft-signed entry/entries (possible tampering): $($unsignedSetup -join '; ')" "-FixSessionManager"
                        }
                        else {
                            & $emit 'Boot' (& $toSev $sevSetupExecPresent) "SetupExecute is non-empty ($($setupExec.Count) entries) - unusual outside servicing: $($setupExec -join '; ')" "-FixSessionManager"
                        }
                    }

                    # ExcludeFromKnownDlls
                    $knownDllExcl = @($smProps.ExcludeFromKnownDlls | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                    if ($knownDllExcl.Count -gt 0) {
                        & $emit 'Security' (& $toSev $sevKnownDllExclude) "ExcludeFromKnownDlls has $($knownDllExcl.Count) entry/entries (app compat or DLL hijack vector): $($knownDllExcl -join ', ')"
                    }
                }

                # -- Static DNS -------------------------------------------------------
                $ifBase = "$SystemRoot\Services\Tcpip\Parameters\Interfaces"
                if (Test-Path $ifBase) {
                    $staticDns = [System.Collections.Generic.List[string]]::new()
                    Get-ChildItem $ifBase -ErrorAction SilentlyContinue | ForEach-Object {
                        $ns = (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).NameServer
                        if ($ns) { $staticDns.Add("$($_.PSChildName): $ns") }
                    }
                    $globalNs = (Get-ItemProperty "$SystemRoot\Services\Tcpip\Parameters" -ErrorAction SilentlyContinue).NameServer
                    if ($globalNs) { $staticDns.Add("Global: $globalNs") }
                    if ($staticDns.Count -gt 0) {
                        & $emit 'Networking' (& $toSev $sevStaticDns) "Static DNS server(s) configured on $($staticDns.Count) interface(s) - may not resolve after migration; -ResetNetworkStack clears them" "-ResetNetworkStack"
                    }
                }

                # -- Static IP / DHCP disabled ----------------------------------------
                # Azure requires DHCP for IP assignment. EnableDHCP=0 means the VM
                # keeps a stale on-prem IP and gets zero Azure connectivity.
                if (Test-Path $ifBase) {
                    $staticIpIfs = [System.Collections.Generic.List[string]]::new()
                    Get-ChildItem $ifBase -ErrorAction SilentlyContinue | ForEach-Object {
                        $dhcpVal = (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).EnableDHCP
                        if ($null -ne $dhcpVal -and $dhcpVal -eq 0) {
                            $staticIpIfs.Add($_.PSChildName)
                        }
                    }
                    if ($staticIpIfs.Count -gt 0) {
                        & $emit 'Networking' (& $toSev $sevStaticIpNoAzureDhcp) "EnableDHCP=0 on $($staticIpIfs.Count) interface(s) - Azure requires DHCP for IP assignment; VM will have NO connectivity; run -ResetInterfacesToDHCP" "-ResetInterfacesToDHCP"
                    }
                }

                # -- NetworkProvider\Order orphan check --------------------------------
                # If a provider is listed in ProviderOrder but its DLL is missing,
                # Windows hangs indefinitely at logon ("Please wait..." forever).
                # Common after uninstalling VPN software (Cisco AnyConnect, GlobalProtect, Zscaler).
                $npOrderPath = "$ctrlRoot\NetworkProvider\Order"
                if (Test-Path $npOrderPath) {
                    $providerOrder = (Get-ItemProperty $npOrderPath -ErrorAction SilentlyContinue).ProviderOrder
                    if ($providerOrder) {
                        $providers = $providerOrder -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ }
                        $orphanedProviders = [System.Collections.Generic.List[string]]::new()
                        foreach ($prov in $providers) {
                            $provSvcPath = "$svcRoot\$prov\NetworkProvider"
                            if (-not (Test-Path $provSvcPath)) {
                                $orphanedProviders.Add("$prov (service key missing)")
                                continue
                            }
                            $provDllRaw = (Get-ItemProperty $provSvcPath -ErrorAction SilentlyContinue).ProviderPath
                            if (-not $provDllRaw) { continue }
                            # Resolve %SystemRoot% and map to offline drive
                            $provDll = $provDllRaw -replace '(?i)%SystemRoot%', (Join-Path $script:WinDriveLetter 'Windows')
                            $provDll = $provDll -replace '(?i)\\SystemRoot\\', (Join-Path $script:WinDriveLetter 'Windows\')
                            if (-not (Test-Path -LiteralPath $provDll)) {
                                $orphanedProviders.Add("$prov ($provDllRaw -> not found)")
                            }
                        }
                        if ($orphanedProviders.Count -gt 0) {
                            & $emit 'Networking' (& $toSev $sevNetProviderOrphaned) "NetworkProvider\Order lists $($orphanedProviders.Count) provider(s) with missing DLL - logon will hang indefinitely: $($orphanedProviders -join '; ')" "-FixNetBindings"
                        }
                    }
                }

                # -- EMS / Serial Console ---------------------------------------------
                # Check BCD for EMS (done outside hive, but while we're still here)
            } # end & { } child scope - all registry variables die here
        }

        # EMS / Serial Console check (reads BCD store; no hive needed)
        try {
            $bcdPathEms = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter.TrimEnd('\')
            if (Test-Path $bcdPathEms) {
                $emsOut = & bcdedit.exe /store $bcdPathEms /enum "{emssettings}" 2>&1 | Out-String
                if ($emsOut -notmatch 'emsport' -and $emsOut -notmatch 'emsbaudrate') {
                    & $emit 'Boot' (& $toSev $sevEmsDisabled) 'EMS/Serial Console is not configured - enable with -EnableSerialConsole for Azure Serial Console access' "-EnableSerialConsole"
                }
                else {
                    & $emit 'Boot' 'OK' 'EMS/Serial Console is configured'
                }
            }
        }
        catch { <# non-critical #> }

        # -- 5. SOFTWARE hive -----------------------------------------------------
        Write-Host "--- Registry (SOFTWARE hive)" -ForegroundColor DarkGray
        Invoke-WithHive 'SOFTWARE' {
            # Child scope: all variables holding registry data die when this block returns,
            # releasing .NET RegistryKey handles before the finally block calls UnmountOffHive.
            & {
                # OS edition & build
                $ntCv = Get-ItemProperty 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
                if ($ntCv) {
                    $build = Format-WindowsBuildLabel -Build $ntCv.CurrentBuildNumber -Ubr $ntCv.UBR -Prefix 'Build '
                    & $emit 'OS' 'INFO' "$($ntCv.ProductName)  |  Edition: $($ntCv.EditionID)  |  $build"
                }

                # CredSSP AllowEncryptionOracle
                $credSsp = (Get-ItemProperty 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\CredSSP\Parameters' -ErrorAction SilentlyContinue).AllowEncryptionOracle
                if ($null -ne $credSsp -and $credSsp -ne 2) {
                    $oDesc = switch ($credSsp) { 0 { 'Force Updated Clients (most restrictive)' } 1 { 'Mitigated' } default { "Value=$credSsp" } }
                    & $emit 'RDP' (& $toSev $sevCredSspOracle) "CredSSP AllowEncryptionOracle=$credSsp ($oDesc) - may block RDP from clients without latest patches" "-FixRDPAuth"
                }

                # -- Gen2: BitLocker / FVE policy (SOFTWARE hive side) ----------------
                if ($script:VMGen -eq 2) {
                    $fvePath = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\FVE'
                    if (Test-Path $fvePath) {
                        $fveProps = Get-ItemProperty $fvePath -ErrorAction SilentlyContinue
                        $useTPM = $fveProps.UseTPM
                        $useTPMPIN = $fveProps.UseTPMPIN
                        $useTPMKey = $fveProps.UseTPMKey
                        $fveDetail = [System.Collections.Generic.List[string]]::new()
                        if ($null -ne $useTPM) { $fveDetail.Add("UseTPM=$useTPM") }
                        if ($null -ne $useTPMPIN) { $fveDetail.Add("UseTPMPIN=$useTPMPIN") }
                        if ($null -ne $useTPMKey) { $fveDetail.Add("UseTPMKey=$useTPMKey") }
                        if ($fveDetail.Count -gt 0) {
                            & $emit 'UEFI' (& $toSev $sevBitLockerActive) "BitLocker FVE policy configured ($($fveDetail -join ', ')) - if BitLocker is active with TPM protector, the disk CANNOT auto-unlock on a different VM; a recovery key is required"
                        }
                    }
                    # Note: HKLM\SOFTWARE\Microsoft\BitLocker is intentionally NOT checked here.
                    # That key exists by default on virtually every Windows install regardless of
                    # whether any volume is actually encrypted, so testing for its presence would
                    # fire on nearly every Gen2 VM. The FVE policy check above is gated on real
                    # configured policy values and is the meaningful BitLocker signal.
                }

                # AppLocker enforced collections
                $srpBase = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows\SrpV2'
                $enforcedCols   = @()  # collections with EnforcementMode != 0
                $colsWithRules  = @()  # subset that also contain GUID rule subkeys
                foreach ($col in @('Exe', 'Dll', 'Script', 'Msi', 'Appx')) {
                    $colPath = "$srpBase\$col"
                    if (-not (Test-Path $colPath)) { continue }
                    $mode = (Get-ItemProperty $colPath -ErrorAction SilentlyContinue).EnforcementMode
                    if ($null -eq $mode -or $mode -eq 0) { continue }
                    $enforcedCols += $col
                    # Check for GUID subkeys (each AppLocker rule is stored as a GUID-named subkey)
                    $ruleKeys = @(Get-ChildItem $colPath -ErrorAction SilentlyContinue |
                        Where-Object { $_.PSChildName -match '^\{[0-9a-f-]{36}\}$' })
                    if ($ruleKeys.Count -gt 0) { $colsWithRules += $col }
                }
                $appIdAutoStart = ($script:_sysCheckAppIdSvcStart -eq 2)
                if ($enforcedCols.Count -gt 0) {
                    if ($appIdAutoStart -and $colsWithRules.Count -gt 0) {
                        # CRIT: enforcement configured + service will auto-start + rules exist
                        & $emit 'Security' (& $toSev $sevAppLockerActive) "AppLocker ACTIVE for: $($colsWithRules -join ', ') - EnforcementMode on, AppIDSvc=Auto, rules present - will block processes" "-DisableAppLocker"
                    }
                    elseif ($appIdAutoStart) {
                        # WARN: enforcement configured + service will auto-start (but no rule subkeys found)
                        & $emit 'Security' (& $toSev $sevAppLockerEnforcing) "AppLocker enforcement configured for: $($enforcedCols -join ', ') with AppIDSvc=Auto, but no rule subkeys found - may still enforce default-deny" "-DisableAppLocker"
                    }
                    else {
                        # OK/INFO: enforcement configured but AppIDSvc is not auto-start
                        & $emit 'Security' (& $toSev $sevAppLockerConfigured) "AppLocker EnforcementMode set for: $($enforcedCols -join ', ') but AppIDSvc is not auto-start (Start=$($script:_sysCheckAppIdSvcStart)) - rules will not be enforced at runtime"
                    }
                }
                else {
                    & $emit 'Security' 'OK' 'AppLocker is not enforcing any rule collections'
                }

                # AppIDSvc - if enforcing above, check service state
                # (service state is in SYSTEM hive, checked there; this just notes correlation)

                # NLA policy via Group Policy / TS Policy path (SOFTWARE side)
                $tsPolicyBase = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Windows NT\Terminal Services'
                if (Test-Path $tsPolicyBase) {
                    $tsPol = Get-ItemProperty $tsPolicyBase -ErrorAction SilentlyContinue
                    if ($null -ne $tsPol.fDenyTSConnections -and $tsPol.fDenyTSConnections -eq 1) {
                        & $emit 'RDP' (& $toSev $sevGpRdpBlocked) 'Group Policy is BLOCKING RDP: Software\Policies\...\Terminal Services fDenyTSConnections=1 - -FixRDP clears this' "-FixRDP"
                    }
                    if ($null -ne $tsPol.UserAuthentication -and $tsPol.UserAuthentication -eq 0) {
                        & $emit 'RDP' (& $toSev $sevGpNlaDisabled) 'Group Policy has disabled NLA (Software\Policies UserAuthentication=0) - this overrides the listener setting'
                    }
                    $sslFuncPath = 'HKLM:\BROKENSOFTWARE\Policies\Microsoft\Cryptography\Configuration\SSL\00010002'
                    if (Test-Path $sslFuncPath) {
                        $sslFunc = (Get-ItemProperty $sslFuncPath -ErrorAction SilentlyContinue).Functions
                        if ($null -ne $sslFunc) {
                            & $emit 'RDP' (& $toSev $sevSslCipherPolicy) "SSL cipher suite policy (SSL\00010002 Functions) is configured - may restrict TLS cipher suites available to RDP; run -FixRDP to clear" "-FixRDP"
                        }
                    }
                }

                # CBS / Component Based Servicing pending state
                # The genuine "Configuring Windows Updates" boot loop is driven by a queued
                # WinSxS\pending.xml that CBS replays on boot. A leftover SessionsPending session
                # record is only a SYMPTOM and is frequently benign: CBS keeps the last *completed*
                # exclusive session (Successful=1) as history until the next servicing run prunes
                # it, so flagging "Exclusive != 0" alone produces false positives on healthy,
                # fully-serviced VMs. We therefore classify each session and correlate it with the
                # authoritative pending.xml marker before deciding WARN vs INFO.
                $cbsBase = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
                $cbsPendingXml = Test-Path -LiteralPath (Join-Path $script:WinDriveLetter 'Windows\WinSxS\pending.xml')
                $cbsIssues = [System.Collections.Generic.List[string]]::new()
                $cbsInfos = [System.Collections.Generic.List[string]]::new()
                $cbsPendingKeyFound = $false
                foreach ($cbsKey in @('RebootPending', 'PackagesPending', 'SessionsPending')) {
                    $cbsKeyPath = "$cbsBase\$cbsKey"
                    if (-not (Test-Path $cbsKeyPath)) { continue }
                    $cbsPendingKeyFound = $true

                    # Collect detail: subkey names + any values on the key itself
                    $subkeys = @(Get-ChildItem $cbsKeyPath -ErrorAction SilentlyContinue | Select-Object -ExpandProperty PSChildName)
                    $vals = Get-ItemProperty $cbsKeyPath -ErrorAction SilentlyContinue
                    $valNames = @($vals.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' } | Select-Object -ExpandProperty Name)

                    switch ($cbsKey) {
                        'RebootPending' {
                            # Values here are package names pending reboot - a genuine pending marker.
                            $rp = if ($valNames.Count -gt 0) { "pending package(s): $($valNames[0..([Math]::Min(2,$valNames.Count-1))] -join ', ')$(if ($valNames.Count -gt 3){ " (+$($valNames.Count-3) more)" })" } else { 'key exists (no values)' }
                            $cbsIssues.Add("RebootPending ($rp) - may cause 'Configuring Windows Updates' boot loop")
                        }
                        'PackagesPending' {
                            # Subkeys are package names queued for install - a genuine pending marker.
                            $pp = if ($subkeys.Count -gt 0) { "$($subkeys.Count) package(s) pending: $($subkeys[0..([Math]::Min(1,$subkeys.Count-1))] -join ', ')$(if ($subkeys.Count -gt 2){ " (+$($subkeys.Count-2) more)" })" } else { 'key exists (no subkeys)' }
                            $cbsIssues.Add("PackagesPending ($pp) - may cause 'Configuring Windows Updates' boot loop")
                        }
                        'SessionsPending' {
                            # Classify each session record. An exclusive session that did NOT finish
                            # is "interrupted"; one CBS has marked finished is completed history.
                            # Finished is signalled by Complete=1 (Server 2012 R2 / 2016 servicing
                            # stack) or Successful=1 (newer stacks). Only an interrupted exclusive
                            # session combined with a queued pending.xml is a real boot-loop candidate.
                            # Sessions with no Exclusive value are non-exclusive history and ignored.
                            $interrupted = [System.Collections.Generic.List[string]]::new()
                            $completed = [System.Collections.Generic.List[string]]::new()
                            foreach ($s in $subkeys) {
                                $sp = Get-ItemProperty "$cbsKeyPath\$s" -ErrorAction SilentlyContinue
                                if ($null -eq $sp -or $null -eq $sp.Exclusive -or [int]$sp.Exclusive -eq 0) { continue }
                                $sessionDone = ($null -ne $sp.Complete -and [int]$sp.Complete -eq 1) -or ($null -ne $sp.Successful -and [int]$sp.Successful -eq 1)
                                if ($sessionDone) { $completed.Add($s) }
                                else { $interrupted.Add($s) }
                            }
                            if ($interrupted.Count -gt 0 -and $cbsPendingXml) {
                                $cbsIssues.Add("SessionsPending (EXCLUSIVE session interrupted mid-flight AND a queued WinSxS\pending.xml is present - genuine 'Configuring Windows Updates' boot-loop risk; session ID(s): $($interrupted -join ', '))")
                            }
                            elseif ($interrupted.Count -gt 0) {
                                $cbsInfos.Add("CBS SessionsPending: stale exclusive session ($($interrupted -join ', ')), no pending.xml - not a boot-loop risk")
                            }
                            elseif ($completed.Count -gt 0) {
                                $cbsInfos.Add("CBS SessionsPending: completed session history ($($completed -join ', ')) - normal, not pending")
                            }
                            # else: only non-exclusive session entries -> stale history, suppress entirely
                        }
                    }
                }
                foreach ($issue in $cbsIssues) {
                    & $emit 'WindowsUpdate' (& $toSev $sevCbsPendingWarn) "CBS pending state: $issue" '-FixPendingUpdates'
                }
                foreach ($info in $cbsInfos) {
                    & $emit 'WindowsUpdate' 'INFO' $info
                }
                if ($cbsIssues.Count -eq 0 -and $cbsInfos.Count -eq 0) {
                    if (-not $cbsPendingKeyFound) {
                        & $emit 'WindowsUpdate' 'OK' 'No CBS pending state keys detected'
                    }
                    else {
                        & $emit 'WindowsUpdate' 'OK' 'CBS pending keys exist but contain only stale, non-actionable session history'
                    }
                }

                # -- Winlogon Shell / Userinit ----------------------------------------
                $wlPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
                if (Test-Path $wlPath) {
                    $wlProps = Get-ItemProperty $wlPath -ErrorAction SilentlyContinue
                    $wlShell = $wlProps.Shell
                    $wlUserinit = $wlProps.Userinit
                    if ($wlShell -and $wlShell -ne 'explorer.exe') {
                        & $emit 'Security' (& $toSev $sevWinlogonShell) "Winlogon Shell is '$wlShell' (expected 'explorer.exe') - will cause black screen or wrong shell on logon" "-FixWinlogon"
                    }
                    $expectedUi = 'C:\Windows\system32\userinit.exe,'
                    if ($wlUserinit -and $wlUserinit -ne $expectedUi -and $wlUserinit -ne 'C:\Windows\system32\userinit.exe') {
                        & $emit 'Security' (& $toSev $sevWinlogonUserinit) "Winlogon Userinit is '$wlUserinit' (expected default) - may cause logon failure or malware execution" "-FixWinlogon"
                    }
                }

                # -- User Profile List ------------------------------------------------
                $plBase = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
                if (Test-Path $plBase) {
                    $profEntries = Get-ChildItem $plBase -ErrorAction SilentlyContinue
                    foreach ($pf in $profEntries) {
                        $sid = $pf.PSChildName
                        if ($sid -notmatch '^S-1-5-21-') { continue }
                        $bakProfPath = "$plBase\$sid.bak"
                        if (Test-Path $bakProfPath) {
                            $pfPath = (Get-ItemProperty $pf.PSPath -ErrorAction SilentlyContinue).ProfileImagePath
                            & $emit 'UserProfile' (& $toSev $sevProfileBak) "Profile SID $sid has .bak duplicate (path: $pfPath) - user will get 'The User Profile Service failed the sign-in' error" "-FixProfileLoad"
                        }
                        $pfState = (Get-ItemProperty $pf.PSPath -ErrorAction SilentlyContinue).State
                        if ($null -ne $pfState -and ($pfState -band 0x8)) {
                            & $emit 'UserProfile' (& $toSev $sevProfileTempFlag) "Profile SID $sid has temporary profile flag (State=$pfState) - user gets temporary profile on each logon" "-FixProfileLoad"
                        }
                    }
                }

                # -- Image File Execution Options (IFEO) ------------------------------------
                # IFEO keys can contain values that prevent or break process execution:
                #   Debugger     - replaces the process entirely with a debugger; if that binary
                #                  is missing (procdump uninstalled), the service silently fails.
                #   GlobalFlag   - gflags.exe settings. Dangerous flags include:
                #                  0x02000000 = page heap (massive memory, OOM crashes)
                #                  0x00000100 = Application Verifier (crashes if verifier DLLs removed)
                #                  0x00000040 = validate all heap (extreme slowdown -> SCM timeout)
                #   MitigationOptions - forces DEP/ASLR/CFG/SEHOP on binaries that may not
                #                  be compiled for them, causing access violations.
                $ifeoRoot = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
                if (Test-Path $ifeoRoot) {
                    # Critical executables whose IFEO entries would prevent boot or core services
                    $ifeoCriticalExes = @(
                        'svchost.exe', 'services.exe', 'lsass.exe', 'smss.exe', 'csrss.exe',
                        'wininit.exe', 'winlogon.exe', 'logonui.exe', 'dwm.exe',
                        'spoolsv.exe', 'lsm.exe', 'userinit.exe', 'explorer.exe',
                        'rdpclip.exe', 'rdpinit.exe', 'mstsc.exe', 'termsrv.dll',
                        'WaAppAgent.exe', 'WindowsAzureGuestAgent.exe',
                        'WaSecAgentProv.exe'
                    )
                    # GlobalFlag bits that are known to crash or OOM services
                    $dangerousGFlags = @(
                        @{ Mask = 0x02000000; Name = 'FLG_HEAP_PAGE_ALLOCS (page heap)'; Risk = 'massive memory overhead - causes OOM on constrained services' }
                        @{ Mask = 0x00000100; Name = 'FLG_APPLICATION_VERIFIER'; Risk = 'crashes if Application Verifier provider DLLs are missing' }
                        @{ Mask = 0x00000040; Name = 'FLG_HEAP_VALIDATE_ALL'; Risk = 'validates every heap operation - extreme slowdown causes SCM timeout' }
                        @{ Mask = 0x00001000; Name = 'FLG_USER_STACK_TRACE_DB'; Risk = 'stack trace database - significant memory overhead' }
                    )
                    $ifeoCount = 0
                    foreach ($ifeoKey in (Get-ChildItem $ifeoRoot -ErrorAction SilentlyContinue)) {
                        $ifeoProps = Get-ItemProperty $ifeoKey.PSPath -ErrorAction SilentlyContinue
                        $exeName = $ifeoKey.PSChildName
                        $isCritical = $ifeoCriticalExes -contains $exeName

                        # 1. Debugger redirect (most severe - process never runs)
                        $ifeoDebugger = $ifeoProps.Debugger
                        if ($ifeoDebugger) {
                            $dbgBin = ($ifeoDebugger -split '\s+', 2)[0].Trim('"')
                            $dbgResolved = if ($dbgBin -match '^[A-Z]:\\') {
                                $dbgBin -replace '^[A-Z]:\\', "$($script:WinDriveLetter)"
                            } else { $null }
                            $dbgExists = $dbgResolved -and (Test-Path -LiteralPath $dbgResolved)
                            $existsTag = if ($dbgResolved) { if ($dbgExists) { 'binary exists' } else { 'BINARY MISSING' } } else { 'path not resolvable' }
                            $sev = if ($isCritical) { (& $toSev $sevIFEODebugger) } else { (& $toSev $sevIFEODebuggerNonCritical) }
                            $impact = if ($isCritical) { 'CRITICAL - service/process will not start' } else { 'process will launch debugger instead of running normally' }
                            & $emit 'IFEO' $sev "IFEO Debugger on $exeName -> '$ifeoDebugger' ($existsTag) - $impact"
                            $ifeoCount++
                        }

                        # 2. GlobalFlag (second most common - gflags/page heap/app verifier leftovers)
                        $gfValue = $ifeoProps.GlobalFlag
                        if ($null -ne $gfValue -and [int]$gfValue -ne 0) {
                            $gfInt = [int]$gfValue
                            $gfHex = '0x{0:X8}' -f $gfInt
                            $hitFlags = @()
                            foreach ($df in $dangerousGFlags) {
                                if ($gfInt -band $df.Mask) { $hitFlags += "$($df.Name) - $($df.Risk)" }
                            }
                            if ($hitFlags.Count -gt 0) {
                                $sev = if ($isCritical) { (& $toSev $sevIFEOGlobalFlag) } else { (& $toSev $sevIFEOGlobalFlagNonCritical) }
                                foreach ($hf in $hitFlags) {
                                    & $emit 'IFEO' $sev "IFEO GlobalFlag on $exeName ($gfHex): $hf"
                                }
                                $ifeoCount++
                            }
                        }

                    }
                    if ($ifeoCount -eq 0) {
                        & $emit 'IFEO' 'OK' 'No IFEO debugger redirects or GlobalFlag overrides found'
                    }
                }

                # -- Startup Programs (Run/RunOnce) -----------------------------------
                $runPaths = @(
                    'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Run'
                    'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
                )
                $startupEntries = [System.Collections.Generic.List[string]]::new()
                foreach ($rp in $runPaths) {
                    if (-not (Test-Path $rp)) { continue }
                    $rpProps = Get-ItemProperty $rp -ErrorAction SilentlyContinue
                    foreach ($rpv in ($rpProps.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' })) {
                        $startupEntries.Add("$($rpv.Name)")
                    }
                }
                if ($startupEntries.Count -gt 0) {
                    & $emit 'Startup' (& $toSev $sevStartupPrograms) "$($startupEntries.Count) auto-start entry(s) in HKLM Run/RunOnce: $($startupEntries -join ', ') - use -ListStartupPrograms to review" "-ListStartupPrograms"
                }

                # -- Machine proxy/PAC ------------------------------------------------
                $inetPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings'
                if (Test-Path $inetPath) {
                    $inetProps = Get-ItemProperty $inetPath -ErrorAction SilentlyContinue
                    if ($inetProps.ProxyEnable -eq 1 -or $inetProps.ProxyServer -or $inetProps.AutoConfigURL) {
                        $proxyDetail = @()
                        if ($inetProps.ProxyServer) { $proxyDetail += "ProxyServer='$($inetProps.ProxyServer)'" }
                        if ($inetProps.AutoConfigURL) { $proxyDetail += "AutoConfigURL='$($inetProps.AutoConfigURL)'" }
                        if ($inetProps.ProxyEnable -eq 1) { $proxyDetail += 'ProxyEnable=1' }
                        & $emit 'Networking' (& $toSev $sevProxyConfigured) "Machine-level proxy configured: $($proxyDetail -join ', ') - may block Azure agent and remote management" "-ClearProxyState"
                    }
                }
            } # end & { } child scope - all registry variables die here
        }

        # -- 6. Azure Agent binaries on disk --------------------------------------
        Write-Host "--- Azure VM Agent" -ForegroundColor DarkGray
        $azureDir = Join-Path $script:WinDriveLetter 'WindowsAzure'
        if (Test-Path $azureDir) {
            $gaDirs = @(Get-ChildItem $azureDir -Filter 'GuestAgent_*' -Directory -ErrorAction SilentlyContinue)
            if ($gaDirs.Count -gt 0) {
                & $emit 'AzureAgent' 'OK' "Agent binaries present: $($gaDirs[-1].Name)"
            }
            else {
                & $emit 'AzureAgent' (& $toSev $sevAzureAgentMissing) 'WindowsAzure folder exists but no GuestAgent_* subfolder found' "-InstallAzureVMAgent"
            }
        }
        else {
            & $emit 'AzureAgent' (& $toSev $sevAzureAgentMissing) "WindowsAzure folder not found on $script:WinDriveLetter - VM Agent may not be installed" "-InstallAzureVMAgent"
        }

        # -- 7. RDP private key / MachineKeys -------------------------------------
        Write-Host "--- RDP Certificate & MachineKeys" -ForegroundColor DarkGray
        $machineKeysPath = Join-Path $script:WinDriveLetter 'ProgramData\Microsoft\Crypto\RSA\MachineKeys'
        if (Test-Path $machineKeysPath) {
            # The RDP private key file has a well-known name prefix f686aace6942fb7f7ceb231212eef4a4
            $rdpKeyFiles = @(Get-ChildItem $machineKeysPath -Filter 'f686aace6942fb7f7ceb231212eef4a4*' -ErrorAction SilentlyContinue)
            if ($rdpKeyFiles.Count -gt 0) {
                & $emit 'RDP' 'OK' "RDP private key file present ($($rdpKeyFiles[0].Name))"

                # Check ACLs on the key file. Required principals (matched by well-known SID):
                #   S-1-5-18  = NT AUTHORITY\SYSTEM        -> needs FullControl
                #   S-1-5-20  = NT AUTHORITY\NETWORK SERVICE -> needs at least Read (TermService runs as this)
                #   S-1-5-80-* matching SessionEnv service  -> needs FullControl (checked by display name)
                try {
                    $keyAcl = Get-Acl -Path $rdpKeyFiles[0].FullName -ErrorAction Stop
                    $rules = $keyAcl.Access

                    $sidSystem = [System.Security.Principal.SecurityIdentifier]'S-1-5-18'
                    $sidNetSvc = [System.Security.Principal.SecurityIdentifier]'S-1-5-20'

                    $systemOk = $rules | Where-Object {
                        try { $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $sidSystem } catch { $false }
                    } | Where-Object { $_.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::FullControl }

                    $netSvcOk = $rules | Where-Object {
                        try { $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $sidNetSvc } catch { $false }
                    } | Where-Object { $_.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::Read }

                    # SessionEnv runs as NT Service\SessionEnv - no fixed SID, match by identity string
                    $sessionEnvOk = $rules | Where-Object {
                        $_.IdentityReference.Value -match 'SessionEnv'
                    } | Where-Object { $_.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::FullControl }

                    if (-not $systemOk) {
                        & $emit 'RDP' (& $toSev $sevRdpKeySystemAcl) "RDP private key: NT AUTHORITY\SYSTEM does not have FullControl - RDP service may fail to use the certificate" "-FixRDPPermissions"
                    }
                    if (-not $netSvcOk) {
                        & $emit 'RDP' (& $toSev $sevRdpKeyNetSvcAcl) "RDP private key: NT AUTHORITY\NETWORK SERVICE does not have Read access - TermService will fail to load the RDP certificate" "-FixRDPPermissions"
                    }
                    else {
                        & $emit 'RDP' 'OK' 'RDP private key ACLs: SYSTEM and NETWORK SERVICE have required permissions'
                    }
                    if (-not $sessionEnvOk) {
                        & $emit 'RDP' (& $toSev $sevRdpKeySessionEnvAcl) 'RDP private key: NT Service\SessionEnv FullControl not found - may cause RDP session issues on some Windows versions' "-FixRDPPermissions"
                    }
                }
                catch {
                    & $emit 'RDP' 'INFO' "Could not read ACLs on RDP private key file: $_"
                }
            }
            else {
                & $emit 'RDP' (& $toSev $sevRdpKeyFileMissing) 'RDP private key file (f686aace...) not found in MachineKeys - RDP certificate will need to be regenerated' "-FixRDPCert"
            }
            # Check for zero-length or suspiciously small key files (corrupted)
            $emptyKeys = @(Get-ChildItem $machineKeysPath -ErrorAction SilentlyContinue | Where-Object { $_.Length -eq 0 })
            if ($emptyKeys.Count -gt 0) {
                & $emit 'RDP' (& $toSev $sevRdpKeyZeroLength) "$($emptyKeys.Count) zero-length file(s) found in MachineKeys - may indicate corrupted key store; run -FixRDPPermissions" "-FixRDPPermissions"
            }
        }
        else {
            & $emit 'RDP' (& $toSev $sevMachineKeysMissing) 'MachineKeys folder missing - RDP certificate operations will fail on boot' "-FixRDPPermissions"
        }

        # -- Summary --------------------------------------------------------------
        $crits = @($findings | Where-Object Severity -eq 'CRIT')
        $warns = @($findings | Where-Object Severity -eq 'WARN')
        $infos = @($findings | Where-Object Severity -eq 'INFO')
        $oks = @($findings | Where-Object Severity -eq 'OK')

        Write-Host "`n===================================================================" -ForegroundColor Cyan
        Write-Host "  System Check Summary  -  $($crits.Count) critical  /  $($warns.Count) warnings  /  $($infos.Count) info  /  $($oks.Count) ok" -ForegroundColor Cyan
        Write-Host "===================================================================" -ForegroundColor Cyan

        # Echo back the same target form the user invoked with (-VMName <name> or
        # -DiskNumber <n>); fall back to the resolved disk number if not captured.
        $targetArg = if ($script:InvocationTarget) { $script:InvocationTarget } else { "-DiskNumber $script:DiskNumber" }

        if ($crits.Count -gt 0) {
            Write-Host "`nCRITICAL - likely preventing boot or connectivity:" -ForegroundColor Red
            foreach ($f in $crits) {
                Write-Host "  [$($f.Category)] $($f.Description)" -ForegroundColor Red
                if ($f.Fix) {
                    if ($f.Fix.TrimStart().StartsWith('-')) {
                        Write-Host "    > .\$scriptFile $targetArg $($f.Fix)" -ForegroundColor DarkCyan
                    }
                    else {
                        Write-Host "    $($f.Fix)" -ForegroundColor DarkCyan
                    }
                }
            }
        }
        if ($warns.Count -gt 0) {
            Write-Host "`nWARNINGS - should be investigated:" -ForegroundColor Yellow
            foreach ($f in $warns) {
                Write-Host "  [$($f.Category)] $($f.Description)" -ForegroundColor Yellow
                if ($f.Fix) {
                    if ($f.Fix.TrimStart().StartsWith('-')) {
                        Write-Host "    > .\$scriptFile $targetArg $($f.Fix)" -ForegroundColor DarkCyan
                    }
                    else {
                        Write-Host "    $($f.Fix)" -ForegroundColor DarkCyan
                    }
                }
            }
        }
        if ($crits.Count -eq 0 -and $warns.Count -eq 0) {
            Write-Host "`nNo critical issues or warnings detected." -ForegroundColor Green
        }

        Write-Host ""
        Write-ActionLog -Event 'RunSystemCheck' -Details @{
            Critical = $crits.Count
            Warnings = $warns.Count
            Findings = ($findings | ForEach-Object { "$($_.Severity)[$($_.Category)] $($_.Description)" }) -join ' | '
        }
    }

    function ResetNetworkStack {
        Write-Host "Placing network stack reset script to run at next boot..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\resetnet.cmd" -Type String -Force

            # Also reset DNS client settings to DHCP defaults across all interfaces offline
            $SystemRoot = Get-SystemRootPath
            $ifBase = "$SystemRoot\Services\Tcpip\Parameters\Interfaces"
            if (Test-Path $ifBase) {
                $ifCount = 0
                Get-ChildItem $ifBase -ErrorAction SilentlyContinue | ForEach-Object {
                    $ifProps = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                    $changed = $false
                    # Remove statically configured DNS servers (NameServer); leave DhcpNameServer untouched
                    if ($ifProps.NameServer) {
                        Write-Host "  Interface $($_.PSChildName): clearing static DNS ($($ifProps.NameServer))" -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $_.PSPath -Name NameServer -Value '' -Type String -Force
                        $changed = $true
                    }
                    if ($changed) { $ifCount++ }
                }
                # Also clear the global NameServer override
                $tcpParams = "$SystemRoot\Services\Tcpip\Parameters"
                $globalNs = (Get-ItemProperty $tcpParams -ErrorAction SilentlyContinue).NameServer
                if ($globalNs) {
                    Write-Host "  Global Tcpip\Parameters: clearing static DNS ($globalNs)" -ForegroundColor Yellow
                    Set-ItemProperty-Logged -Path $tcpParams -Name NameServer -Value '' -Type String -Force
                }
                if ($ifCount -gt 0 -or $globalNs) {
                    Write-Host "  DNS settings reset to DHCP defaults on $ifCount interface(s)." -ForegroundColor Green
                }
                else {
                    Write-Host "  No static DNS settings found (already using DHCP)." -ForegroundColor DarkGray
                }
            }

            $netScript = @"
@echo off
netsh int ip reset C:\temp\netsh_ip_reset.log
netsh winsock reset
netsh advfirewall reset
rem Re-enable critical inbound rules that advfirewall reset disables by default
netsh advfirewall firewall set rule group="remote desktop" new enable=yes
netsh advfirewall firewall set rule group="file and printer sharing" new enable=yes
netsh advfirewall firewall set rule group="windows remote management" new enable=yes
ipconfig /flushdns
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\Temp\resetnet.cmd > NUL
shutdown /r /t 10 /c "Network stack reset complete - rebooting"
"@
            Ensure-GuestTempDir
            New-Item-Logged -Path "$script:WinDriveLetter\Temp" -Name "resetnet.cmd" -ItemType File -Value $netScript.Trim() -Force

            Write-Host "Network stack reset script placed. On next boot: IP stack, Winsock, firewall and DNS cache will be reset, then VM will reboot automatically." -ForegroundColor Green
        }
    }

    function DisableWindowsUpdate {
        Write-Host "Disabling Windows Update services to prevent boot loops from update processing..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath

            $services = @('wuauserv', 'UsoSvc', 'WaaSMedicSvc', 'UpdateOrchestrator')
            foreach ($svc in $services) {
                $svcPath = "$SystemRoot\Services\$svc"
                if (Test-Path $svcPath) {
                    $before = (Get-ItemProperty $svcPath -ErrorAction SilentlyContinue).Start
                    Set-ItemProperty-Logged -Path $svcPath -Name Start -Value 4 -Type DWord -Force
                    Write-Host "  $svc disabled (was $before)" -ForegroundColor Yellow
                }
            }

            Write-Host "Windows Update services disabled. Re-enable them after recovery." -ForegroundColor Green
            Write-Host "`n--- REVERT COMMANDS (run on the VM after recovery) ---" -ForegroundColor Cyan
            Write-Host "Set-Service wuauserv -StartupType Automatic" -ForegroundColor White
            Write-Host "Set-Service UsoSvc   -StartupType Automatic" -ForegroundColor White
            Write-Host "# Or use: sc.exe config wuauserv start= auto" -ForegroundColor DarkGray
            Write-Host "------------------------------------------------------`n" -ForegroundColor Cyan
        }
    }

    function Test-RegistryHiveFile {
        param([Parameter(Mandatory = $true)][string]$Path)

        $result = [ordered]@{
            Path    = $Path
            IsValid = $false
            Size    = 0
            Reason  = $null
        }

        $stream = $null
        $reader = $null
        $handle = [IntPtr]::Zero
        $temporaryHivePath = $null
        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            if ($item.PSIsContainer) {
                throw "Path is a directory."
            }

            $result.Size = $item.Length
            if ($item.Length -lt 4096) {
                throw "File is smaller than the minimum registry hive structure (4096 bytes)."
            }

            $stream = [System.IO.File]::Open(
                $item.FullName,
                [System.IO.FileMode]::Open,
                [System.IO.FileAccess]::Read,
                [System.IO.FileShare]::ReadWrite
            )
            $reader = New-Object System.IO.BinaryReader($stream)
            $signature = [System.Text.Encoding]::ASCII.GetString($reader.ReadBytes(4))
            if ($signature -ne 'regf') {
                throw "Registry hive header signature 'regf' is missing."
            }
            $reader.Dispose()
            $reader = $null
            $stream = $null

            if (-not ('RepairAzVmDisk.RegistryHiveNativeMethods' -as [type])) {
                Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

namespace RepairAzVmDisk
{
    public static class RegistryHiveNativeMethods
    {
        [DllImport("advapi32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
        public static extern int RegLoadAppKey(
            string lpFile,
            out IntPtr phkResult,
            int samDesired,
            int dwOptions,
            int reserved);

        [DllImport("advapi32.dll", SetLastError = true)]
        public static extern int RegCloseKey(IntPtr hKey);
    }
}
'@
            }

            $temporaryHivePath = Join-Path `
                ([System.IO.Path]::GetTempPath()) `
                ("RepairAzVMDisk-HiveValidation-{0}.hiv" -f [guid]::NewGuid().ToString('N'))
            [System.IO.File]::Copy($item.FullName, $temporaryHivePath, $true)

            $status = [RepairAzVmDisk.RegistryHiveNativeMethods]::RegLoadAppKey(
                $temporaryHivePath,
                [ref]$handle,
                0x20019,
                1,
                0
            )
            if ($status -ne 0) {
                $message = (New-Object System.ComponentModel.Win32Exception($status)).Message
                throw "Windows could not open the hive: $message (error $status)."
            }

            $result.IsValid = $true
        }
        catch {
            $result.Reason = $_.Exception.Message
        }
        finally {
            if ($handle -ne [IntPtr]::Zero -and ('RepairAzVmDisk.RegistryHiveNativeMethods' -as [type])) {
                [void][RepairAzVmDisk.RegistryHiveNativeMethods]::RegCloseKey($handle)
            }
            if ($reader) { $reader.Dispose() }
            elseif ($stream) { $stream.Dispose() }
            if ($temporaryHivePath -and (Test-Path -LiteralPath $temporaryHivePath)) {
                Remove-Item -LiteralPath $temporaryHivePath -Force -ErrorAction SilentlyContinue
            }
        }

        return [pscustomobject]$result
    }

    function Get-RegBackRestorePlan {
        param(
            [Parameter(Mandatory = $true)][string]$ConfigPath,
            [timespan]$MaximumTimestampSkew = ([timespan]::FromHours(24))
        )

        $regBackPath = Join-Path $ConfigPath 'RegBack'
        $specifications = @(
            [pscustomobject]@{ HiveName = 'SYSTEM'; Required = $true },
            [pscustomobject]@{ HiveName = 'SOFTWARE'; Required = $true },
            [pscustomobject]@{ HiveName = 'SAM'; Required = $false },
            [pscustomobject]@{ HiveName = 'SECURITY'; Required = $false },
            [pscustomobject]@{ HiveName = 'DEFAULT'; Required = $false },
            [pscustomobject]@{ HiveName = 'COMPONENTS'; Required = $false }
        )

        $valid = @()
        $excluded = @()
        $warnings = @()
        foreach ($spec in $specifications) {
            $sourcePath = Join-Path $regBackPath $spec.HiveName
            $sourceItem = Get-Item -LiteralPath $sourcePath -Force -ErrorAction SilentlyContinue
            if (-not $sourceItem -or $sourceItem.PSIsContainer) {
                if ($spec.Required) {
                    $excluded += [pscustomobject]@{
                        HiveName = $spec.HiveName
                        Reason   = 'Required RegBack file is missing.'
                    }
                }
                continue
            }

            $validation = Test-RegistryHiveFile -Path $sourcePath
            if (-not $validation.IsValid) {
                $excluded += [pscustomobject]@{
                    HiveName = $spec.HiveName
                    Reason   = $validation.Reason
                }
                continue
            }

            $valid += [pscustomobject]@{
                HiveName          = $spec.HiveName
                Required          = $spec.Required
                SourcePath        = $sourcePath
                SourceItem        = $sourceItem
                LivePath          = Join-Path $ConfigPath $spec.HiveName
                LiveBackup        = $null
                LogBackups        = @()
                CopyStarted       = $false
            }
        }

        $missingCore = @(
            @('SYSTEM', 'SOFTWARE') | Where-Object {
                $_ -notin @($valid.HiveName)
            }
        )
        if ($missingCore.Count -gt 0) {
            return [pscustomobject]@{
                CanRestore  = $false
                Hives       = @()
                Excluded    = $excluded
                Warnings    = $warnings
                MissingCore = $missingCore
            }
        }

        $core = @($valid | Where-Object { $_.HiveName -in @('SYSTEM', 'SOFTWARE') })
        $coreTimes = @($core | ForEach-Object { $_.SourceItem.LastWriteTimeUtc })
        $oldestCore = ($coreTimes | Sort-Object | Select-Object -First 1)
        $newestCore = ($coreTimes | Sort-Object -Descending | Select-Object -First 1)
        if (($newestCore - $oldestCore) -gt $MaximumTimestampSkew) {
            $warnings += "SYSTEM and SOFTWARE RegBack timestamps differ by more than $([math]::Round($MaximumTimestampSkew.TotalHours, 1)) hours."
        }

        $selected = @($core)
        foreach ($candidate in @($valid | Where-Object { -not $_.Required })) {
            $skew = [timespan]::FromTicks([math]::Abs(($candidate.SourceItem.LastWriteTimeUtc - $newestCore).Ticks))
            if ($skew -gt $MaximumTimestampSkew) {
                $excluded += [pscustomobject]@{
                    HiveName = $candidate.HiveName
                    Reason   = "Timestamp differs from the core backup set by $([math]::Round($skew.TotalHours, 1)) hours."
                }
                continue
            }
            $selected += $candidate
        }

        $sam = @($selected | Where-Object { $_.HiveName -eq 'SAM' })
        $security = @($selected | Where-Object { $_.HiveName -eq 'SECURITY' })
        if (($sam.Count -eq 1) -xor ($security.Count -eq 1)) {
            $selected = @($selected | Where-Object { $_.HiveName -notin @('SAM', 'SECURITY') })
            $missingPairMember = if ($sam.Count -eq 1) { 'SECURITY' } else { 'SAM' }
            $excluded += [pscustomobject]@{
                HiveName = 'SAM/SECURITY'
                Reason   = "Both identity hives must be restored together; $missingPairMember is unavailable or invalid."
            }
        }
        elseif ($sam.Count -eq 1 -and $security.Count -eq 1) {
            $pairSkew = [timespan]::FromTicks(
                [math]::Abs(($sam[0].SourceItem.LastWriteTimeUtc - $security[0].SourceItem.LastWriteTimeUtc).Ticks)
            )
            if ($pairSkew -gt $MaximumTimestampSkew) {
                $selected = @($selected | Where-Object { $_.HiveName -notin @('SAM', 'SECURITY') })
                $excluded += [pscustomobject]@{
                    HiveName = 'SAM/SECURITY'
                    Reason   = "Identity hive timestamps differ by $([math]::Round($pairSkew.TotalHours, 1)) hours."
                }
            }
        }

        return [pscustomobject]@{
            CanRestore  = $true
            Hives       = @($selected)
            Excluded    = $excluded
            Warnings    = $warnings
            MissingCore = @()
        }
    }

    function RestoreRegistryFromRegBack {
        Write-Host "Validating RegBack registry hives..." -ForegroundColor Yellow
        $configPath = Join-Path $script:WinDriveLetter 'Windows\System32\config'
        $regBackPath = Join-Path $configPath 'RegBack'

        if (-not (Test-Path -LiteralPath $regBackPath -PathType Container)) {
            Write-Warning "RegBack folder not found at $regBackPath. Cannot restore."
            return
        }

        $plan = Get-RegBackRestorePlan -ConfigPath $configPath
        foreach ($warning in $plan.Warnings) {
            Write-Warning $warning
        }
        foreach ($item in $plan.Excluded) {
            Write-Warning "  $($item.HiveName) will not be restored: $($item.Reason)"
        }
        if (-not $plan.CanRestore) {
            Write-Error "RegBack restore requires valid SYSTEM and SOFTWARE hives. Missing or invalid: $($plan.MissingCore -join ', ')."
            return
        }

        $hiveSummary = @(
            $plan.Hives | ForEach-Object {
                "  $($_.HiveName): $([math]::Round($_.SourceItem.Length / 1MB, 2)) MB, $($_.SourceItem.LastWriteTime)"
            }
        ) -join "`n"
        if (-not (Confirm-CriticalOperation -Operation 'Restore Registry from RegBack (-RestoreRegistryFromRegBack)' -Details @"
The following validated hives will replace the live copies:
$hiveSummary

All destination hives and their .LOG/.LOG1/.LOG2 files are backed up before any RegBack hive is copied.
SAM and SECURITY are restored only as a validated pair. If any copy or hash verification fails, the function attempts to roll back the full set.
"@)) { return }

        Write-Host "Backing up live registry hives and transaction logs..." -ForegroundColor Yellow
        try {
            foreach ($hive in $plan.Hives) {
                if (Test-Path -LiteralPath $hive.LivePath -PathType Leaf) {
                    $liveBackup = New-UniqueBackupPath -BasePath $hive.LivePath -BakSuffix '.regback.bak'
                    Move-Item-Logged -LiteralPath $hive.LivePath -Destination $liveBackup -Force
                    $hive.LiveBackup = $liveBackup
                }

                foreach ($logSuffix in @('.LOG', '.LOG1', '.LOG2')) {
                    $logPath = Join-Path $configPath "$($hive.HiveName)$logSuffix"
                    if (Test-Path -LiteralPath $logPath -PathType Leaf) {
                        $logBackup = New-UniqueBackupPath -BasePath $logPath -BakSuffix '.regback.bak'
                        Move-Item-Logged -LiteralPath $logPath -Destination $logBackup -Force
                        $hive.LogBackups += [pscustomobject]@{
                            LivePath   = $logPath
                            BackupPath = $logBackup
                        }
                    }
                }
            }

            Write-Host "Copying validated RegBack hives..." -ForegroundColor Yellow
            foreach ($hive in $plan.Hives) {
                $hive.CopyStarted = $true
                Copy-Item-Logged -Path $hive.SourcePath -Destination $hive.LivePath -Force
                if (-not (Test-Path -LiteralPath $hive.LivePath -PathType Leaf)) {
                    throw "Copy did not create the destination hive $($hive.LivePath)."
                }

                $sourceHash = (Get-FileHash -LiteralPath $hive.SourcePath -Algorithm SHA256 -ErrorAction Stop).Hash
                $destinationHash = (Get-FileHash -LiteralPath $hive.LivePath -Algorithm SHA256 -ErrorAction Stop).Hash
                if ($sourceHash -ne $destinationHash) {
                    throw "Hash verification failed for the restored $($hive.HiveName) hive."
                }

                Write-Host "  $($hive.HiveName) restored and verified." -ForegroundColor Green
            }
        }
        catch {
            $restoreError = $_
            Write-Warning "RegBack restore failed. Attempting to roll back every touched hive..."
            for ($index = $plan.Hives.Count - 1; $index -ge 0; $index--) {
                $hive = $plan.Hives[$index]
                if (-not $hive.CopyStarted -and -not $hive.LiveBackup -and $hive.LogBackups.Count -eq 0) { continue }

                try {
                    if ($hive.CopyStarted -and (Test-Path -LiteralPath $hive.LivePath)) {
                        Invoke-Logged -Description 'Remove failed RegBack hive copy' -Details @{
                            Path = $hive.LivePath
                        } -ScriptBlock {
                            Remove-Item -LiteralPath $hive.LivePath -Force -ErrorAction Stop
                        } | Out-Null
                    }
                    if ($hive.LiveBackup -and (Test-Path -LiteralPath $hive.LiveBackup)) {
                        Move-Item-Logged -LiteralPath $hive.LiveBackup -Destination $hive.LivePath -Force
                    }

                    foreach ($logBackup in $hive.LogBackups) {
                        if (Test-Path -LiteralPath $logBackup.LivePath) {
                            Invoke-Logged -Description 'Remove failed RegBack transaction log' -Details @{
                                Path = $logBackup.LivePath
                            } -ScriptBlock {
                                Remove-Item -LiteralPath $logBackup.LivePath -Force -ErrorAction Stop
                            } | Out-Null
                        }
                        if (Test-Path -LiteralPath $logBackup.BackupPath) {
                            Move-Item-Logged -LiteralPath $logBackup.BackupPath -Destination $logBackup.LivePath -Force
                        }
                    }
                }
                catch {
                    Write-Warning "  Rollback failed for $($hive.HiveName): $($_.Exception.Message)"
                }
            }
            throw $restoreError
        }

        $restoredNames = @($plan.Hives.HiveName) -join ', '
        $script:ActionLog.Add("Restored and hash-verified RegBack hives: $restoredNames")
        Write-Host "RegBack restore complete ($restoredNames). Boot the VM to verify." -ForegroundColor Green
    }

    function SetTestSigning {
        param([bool]$Enable)
        $action = if ($Enable) { "Enabling" } else { "Disabling" }
        Write-Host "$action test signing mode..." -ForegroundColor Yellow
        try {
            $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
            $identifier = Get-BcdBootLoaderId -StorePath $storePath
            if (-not $identifier) { return }

            $val = if ($Enable) { "on" } else { "off" }
            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier testsigning $val"

            if ($Enable) {
                Write-Warning "Test signing is now ENABLED. This reduces security by allowing unsigned drivers. Disable after recovery with -DisableTestSigning."
            }
            else {
                Write-Host "Test signing disabled." -ForegroundColor Green
            }
        }
        catch {
            Write-Error "SetTestSigning failed: $_"
            throw
        }
    }

    function CheckDiskHealth {
        Write-Host "`nDisk Health Report" -ForegroundColor Cyan
        Write-Host "==================" -ForegroundColor Cyan

        $targetDisk = Get-Disk -Number $script:DiskNumber -ErrorAction SilentlyContinue
        if (-not $targetDisk) { Write-Warning "Could not retrieve disk info."; return }

        Write-Host "Disk $script:DiskNumber: $($targetDisk.FriendlyName)"
        Write-Host "  Style      : $($targetDisk.PartitionStyle)"
        Write-Host "  Size       : $([math]::Round($targetDisk.Size/1GB,2)) GB"
        Write-Host "  Health     : $($targetDisk.HealthStatus)"
        Write-Host "  Operational: $($targetDisk.OperationalStatus)"

        $partitions = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue
        Write-Host "`nPartitions:" -ForegroundColor Cyan
        foreach ($p in $partitions) {
            $sizeMB = [math]::Round($p.Size / 1MB)
            $letter = if ($p.DriveLetter) { "$($p.DriveLetter):" } else { "(no letter)" }
            $vol = Get-Volume -Partition $p -ErrorAction SilentlyContinue
            $fs = if ($vol) { $vol.FileSystemType } else { "N/A" }
            $health = if ($vol) { $vol.HealthStatus } else { "N/A" }
            $raw = if ($fs -eq 'Unknown' -or $fs -eq '') { " !!! RAW FILESYSTEM - data may be inaccessible" } else { "" }

            $color = if ($raw) { 'Red' } elseif ($health -ne 'Healthy' -and $health -ne 'N/A') { 'Yellow' } else { 'White' }
            Write-Host ("  Partition {0,2}: {1,-10} | {2,-12} | {3} MB | FS: {4,-8} | Health: {5}{6}" -f `
                    $p.PartitionNumber, $letter, $p.Type, $sizeMB, $fs, $health, $raw) -ForegroundColor $color
        }
        Write-Host ""
        Write-Host "Windows drive : $script:WinDriveLetter"  -ForegroundColor Green
        Write-Host "Boot drive    : $script:BootDriveLetter" -ForegroundColor Green
        Write-Host "VM Generation : Gen$script:VMGen"        -ForegroundColor Green
        Write-Host ""

        Invoke-Logged -Description "CheckDiskHealth" -Details @{ Disk = $script:DiskNumber; PartitionCount = $partitions.Count } -ScriptBlock { "OK" } | Out-Null
    }

    function CollectEventLogs {
        $destBase = if (Test-Path "C:\temp") { "C:\temp" } else { New-Item "C:\temp" -ItemType Directory -Force | Select-Object -ExpandProperty FullName }
        $destFolder = Join-Path $destBase "GuestEventLogs_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
        New-Item -Path $destFolder -ItemType Directory -Force | Out-Null

        Write-Host "Collecting guest event logs to $destFolder ..." -ForegroundColor Yellow

        $logSources = @(
            @{ Src = "$script:WinDriveLetter\Windows\System32\winevt\Logs\System.evtx"; Dst = "System.evtx" },
            @{ Src = "$script:WinDriveLetter\Windows\System32\winevt\Logs\Application.evtx"; Dst = "Application.evtx" },
            @{ Src = "$script:WinDriveLetter\Windows\System32\winevt\Logs\Security.evtx"; Dst = "Security.evtx" },
            @{ Src = "$script:WinDriveLetter\Windows\inf\setupapi.dev.log"; Dst = "setupapi.dev.log" },
            @{ Src = "$script:WinDriveLetter\Windows\inf\setupapi.setup.log"; Dst = "setupapi.setup.log" },
            @{ Src = "$script:WinDriveLetter\Windows\ntbtlog.txt"; Dst = "ntbtlog.txt" },
            @{ Src = "$script:WinDriveLetter\Windows\Minidump"; Dst = "Minidump" }
        )

        foreach ($log in $logSources) {
            if (Test-Path $log.Src) {
                $dstPath = Join-Path $destFolder $log.Dst
                Copy-Item-Logged -Path $log.Src -Destination $dstPath -Recurse -Force
                Write-Host "  Copied: $($log.Dst)" -ForegroundColor Green
            }
            else {
                Write-Host "  Not found (skipped): $($log.Dst)" -ForegroundColor DarkGray
            }
        }

        Write-Host "Event logs collected to: $destFolder" -ForegroundColor Green
        Write-Host "Tip: Use 'Get-WinEvent -Path <.evtx>' or Event Viewer to open .evtx files from the host." -ForegroundColor DarkCyan
    }

    function ResetUserRights {
        Invoke-WithHive 'SYSTEM' {
            Write-Host "Configuring setup and adding script..." -ForegroundColor Green
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name SetupType -Value 2 -Type DWord -Force
            Set-ItemProperty-Logged -Path "HKLM:\BROKENSYSTEM\Setup" -Name CmdLine -Value "cmd.exe /c c:\temp\resetuserrights.cmd" -Type String -Force

            $resetuserrights = @"
@echo off
secedit /export /areas USER_RIGHTS /cfg C:\temp\UserRightsBefore.txt
secedit /configure /cfg C:\Windows\inf\defltbase.inf /db defltbase.sdb /verbose
secedit /export /areas USER_RIGHTS /cfg C:\temp\UserRightsAfter.txt
reg add "HKLM\SYSTEM\Setup" /v SetupType /t REG_DWORD /d 0 /f
reg add "HKLM\SYSTEM\Setup" /v CmdLine /t REG_SZ /d "" /f
del /F C:\temp\resetuserrights.cmd > NUL
"@

            Ensure-GuestTempDir
            New-Item-Logged -Path "$WinDriveLetter\Temp" -Name "resetuserrights.cmd" -ItemType File -Value $resetuserrights.ToString().Trim() -Force
        }
    }

    function DisableDriverVerifier {
        Write-Host "Disabling Driver Verifier on offline guest..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath
            $mmPath = "$SystemRoot\Control\Session Manager\Memory Management"
            $verifyPath = "$SystemRoot\Services\VeriDrv"

            if (Test-Path $mmPath) {
                $verifyDrivers = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDrivers
                $verifyLevel = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDriverLevel
                if ($verifyDrivers -or $verifyLevel) {
                    Write-Host "  Current VerifyDrivers : $verifyDrivers" -ForegroundColor White
                    Write-Host "  Current VerifyDriverLevel : $verifyLevel" -ForegroundColor White
                    Set-ItemProperty-Logged -Path $mmPath -Name VerifyDrivers -Value '' -Type String -Force
                    Remove-ItemProperty-Logged -Path $mmPath -Name VerifyDriverLevel -ErrorAction SilentlyContinue
                    Write-Host "  [OK] Driver Verifier settings cleared." -ForegroundColor Green
                }
                else {
                    Write-Host "  Driver Verifier is not configured (VerifyDrivers and VerifyDriverLevel not set)." -ForegroundColor DarkGray
                }
            }

            # Also clear the verifier service if it is set to start
            if (Test-Path $verifyPath) {
                $vStart = (Get-ItemProperty $verifyPath -ErrorAction SilentlyContinue).Start
                if ($null -ne $vStart -and $vStart -ne 4) {
                    Set-ItemProperty-Logged -Path $verifyPath -Name Start -Value 4 -Type DWord -Force
                    Write-Host "  VeriDrv service disabled (Start=4)." -ForegroundColor Green
                }
            }

            Write-Host "Driver Verifier disabled. The VM will no longer enforce verification on boot." -ForegroundColor Green
        }
    }

    function EnableDriverVerifier {
        param([string]$DriverList)
        Write-Host "Enabling Driver Verifier on offline guest..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath
            $mmPath = "$SystemRoot\Control\Session Manager\Memory Management"
            $verifyPath = "$SystemRoot\Services\VeriDrv"

            if (-not (Test-Path $mmPath)) {
                throw "Memory Management key not found: $mmPath"
            }

            # Determine driver list to verify
            $drivers = if (-not [string]::IsNullOrWhiteSpace($DriverList)) {
                # User supplied specific drivers
                ($DriverList -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) -join ' '
            }
            else {
                # Default: verify all drivers
                '*'
            }

            # Standard verification level 0x209BB = standard flags
            # (Pool Tracking + Force IRQL Checking + Deadlock Detection + I/O Verification +
            #  DMA Checking + Security Checks + Miscellaneous Checks + DDI compliance)
            $standardLevel = 0x209BB

            # Show current state
            $currentDrivers = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDrivers
            $currentLevel = (Get-ItemProperty $mmPath -ErrorAction SilentlyContinue).VerifyDriverLevel
            if ($currentDrivers -or $currentLevel) {
                Write-Host "  Current VerifyDrivers     : $currentDrivers" -ForegroundColor DarkGray
                Write-Host "  Current VerifyDriverLevel : $currentLevel" -ForegroundColor DarkGray
            }

            # Set verifier settings
            Set-ItemProperty-Logged -Path $mmPath -Name VerifyDrivers -Value $drivers -Type String -Force
            Set-ItemProperty-Logged -Path $mmPath -Name VerifyDriverLevel -Value $standardLevel -Type DWord -Force
            Write-Host "  [OK] VerifyDrivers set to: $drivers" -ForegroundColor Green
            Write-Host "  [OK] VerifyDriverLevel set to: 0x$($standardLevel.ToString('X'))" -ForegroundColor Green

            # Enable the VeriDrv service (Start=3 = Manual/Demand)
            if (Test-Path $verifyPath) {
                $vStart = (Get-ItemProperty $verifyPath -ErrorAction SilentlyContinue).Start
                if ($null -eq $vStart -or $vStart -eq 4) {
                    Set-ItemProperty-Logged -Path $verifyPath -Name Start -Value 3 -Type DWord -Force
                    Write-Host "  VeriDrv service enabled (Start=3)." -ForegroundColor Green
                }
            }

            Write-Host "Driver Verifier enabled. The VM will enforce standard verification on next boot." -ForegroundColor Green
            if ($drivers -eq '*') {
                Write-Warning "All drivers will be verified. This may cause significant performance impact. Use -EnableDriverVerifier 'driver1.sys,driver2.sys' to target specific drivers."
            }
        }
    }

    function CollectMinidumps {
        $destBase = if (Test-Path "C:\temp") { "C:\temp" } else { New-Item "C:\temp" -ItemType Directory -Force | Select-Object -ExpandProperty FullName }
        $destFolder = Join-Path $destBase "Minidumps_$(Get-Date -Format 'yyyyMMdd_HHmmss')"

        Write-Host "Collecting crash dump files from guest disk..." -ForegroundColor Yellow

        $sources = @(
            @{ Path = Join-Path $script:WinDriveLetter 'Windows\Minidump'; Desc = 'Minidump folder' }
            @{ Path = Join-Path $script:WinDriveLetter 'Windows\MEMORY.DMP'; Desc = 'Full memory dump (MEMORY.DMP)' }
            @{ Path = Join-Path $script:WinDriveLetter 'Windows\LiveKernelReports'; Desc = 'Live Kernel Reports' }
        )

        $anyFound = $false
        foreach ($src in $sources) {
            if (Test-Path $src.Path) {
                if (-not $anyFound) {
                    New-Item -Path $destFolder -ItemType Directory -Force | Out-Null
                    $anyFound = $true
                }
                $dstPath = Join-Path $destFolder (Split-Path $src.Path -Leaf)
                Copy-Item-Logged -Path $src.Path -Destination $dstPath -Recurse -Force
                $size = if ((Get-Item $src.Path).PSIsContainer) {
                    $files = @(Get-ChildItem $src.Path -Recurse -File -ErrorAction SilentlyContinue)
                    "$($files.Count) file(s), $([math]::Round(($files | Measure-Object -Property Length -Sum).Sum / 1MB, 1)) MB"
                }
                else {
                    "$([math]::Round((Get-Item $src.Path).Length / 1MB, 1)) MB"
                }
                Write-Host "  Copied: $($src.Desc) ($size)" -ForegroundColor Green
            }
            else {
                Write-Host "  Not found (skipped): $($src.Desc)" -ForegroundColor DarkGray
            }
        }

        if ($anyFound) {
            Write-Host "Crash dumps collected to: $destFolder" -ForegroundColor Green
            Write-Host "Tip: Use WinDbg or 'dumpchk.exe <file.dmp>' to analyse crash dumps." -ForegroundColor DarkCyan
        }
        else {
            Write-Host "No crash dump files found on the guest disk." -ForegroundColor DarkGray
        }
    }

    function ResetGroupPolicy {
        if (-not (Confirm-CriticalOperation -Operation 'Reset Group Policy (-ResetGroupPolicy)' -Details @"
Deletes the local Group Policy cache folders:
  \Windows\System32\GroupPolicy\*
  \Windows\System32\GroupPolicyUsers\*
And clears cached HKLM\SOFTWARE\Policies keys.
On next boot, local policies will revert to defaults.
Domain-joined VMs will re-download GPOs on next gpupdate cycle.
"@)) { return }

        Write-Host "Resetting local Group Policy..." -ForegroundColor Yellow

        $gpPaths = @(
            (Join-Path $script:WinDriveLetter 'Windows\System32\GroupPolicy')
            (Join-Path $script:WinDriveLetter 'Windows\System32\GroupPolicyUsers')
        )
        foreach ($gp in $gpPaths) {
            if (Test-Path $gp) {
                $items = @(Get-ChildItem $gp -Recurse -Force -ErrorAction SilentlyContinue)
                Remove-Item-Logged -Path "$gp\*" -Recurse -Force
                Write-Host "  Cleared: $gp ($($items.Count) items)" -ForegroundColor Green
            }
            else {
                Write-Host "  Not found (skipped): $gp" -ForegroundColor DarkGray
            }
        }

        # Clear cached policy keys in SOFTWARE hive
        Invoke-WithHive 'SOFTWARE' {
            & {
                $polPath = 'HKLM:\BROKENSOFTWARE\Policies'
                if (Test-Path $polPath) {
                    $subKeys = @(Get-ChildItem $polPath -ErrorAction SilentlyContinue)
                    if ($subKeys.Count -gt 0) {
                        foreach ($sk in $subKeys) {
                            Remove-Item-Logged -Path $sk.PSPath -Recurse -Force
                        }
                        Write-Host "  Cleared SOFTWARE\Policies ($($subKeys.Count) top-level keys)" -ForegroundColor Green
                    }
                }
            }
        }

        Write-Host "Group Policy reset complete. On next boot, local policies will be factory defaults." -ForegroundColor Green
        Write-Host "  Domain-joined VMs will re-apply domain GPOs on next Group Policy refresh." -ForegroundColor DarkCyan
    }

    function FixWinlogon {
        Write-Host "Resetting Winlogon shell and Userinit to Windows defaults..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $wlPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
            if (-not (Test-Path $wlPath)) {
                Write-Warning "Winlogon key not found at $wlPath."
                return
            }

            $currentShell = (Get-ItemProperty $wlPath -ErrorAction SilentlyContinue).Shell
            $currentUserinit = (Get-ItemProperty $wlPath -ErrorAction SilentlyContinue).Userinit

            Write-Host "  Current Shell   : $currentShell" -ForegroundColor White
            Write-Host "  Current Userinit: $currentUserinit" -ForegroundColor White

            $changed = $false
            if ($currentShell -ne 'explorer.exe') {
                Set-ItemProperty-Logged -Path $wlPath -Name Shell -Value 'explorer.exe' -Type String -Force
                Write-Host "  [FIXED] Shell -> explorer.exe" -ForegroundColor Green
                $changed = $true
            }
            # Standard Userinit value (must end with comma)
            $expectedUserinit = 'C:\Windows\system32\userinit.exe,'
            if ($currentUserinit -ne $expectedUserinit) {
                Set-ItemProperty-Logged -Path $wlPath -Name Userinit -Value $expectedUserinit -Type String -Force
                Write-Host "  [FIXED] Userinit -> $expectedUserinit" -ForegroundColor Green
                $changed = $true
            }

            if (-not $changed) {
                Write-Host "  Winlogon Shell and Userinit are already at default values." -ForegroundColor DarkGray
            }
        }
    }

    function FixProfileLoad {
        Write-Host "Scanning user profile list for corrupted entries..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $plBase = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
            if (-not (Test-Path $plBase)) {
                Write-Warning "ProfileList key not found."
                return
            }

            $profiles = Get-ChildItem $plBase -ErrorAction SilentlyContinue
            $fixCount = 0

            foreach ($prof in $profiles) {
                $sid = $prof.PSChildName
                # Only process user SIDs (S-1-5-21-*)
                if ($sid -notmatch '^S-1-5-21-') { continue }

                $bakPath = "$plBase\$sid.bak"
                $hasBak = Test-Path $bakPath

                if ($hasBak) {
                    # The .bak duplicate is the corrupt one; the primary has the wrong profile
                    # Fix: rename primary to .old, rename .bak to primary
                    $props = Get-ItemProperty $prof.PSPath -ErrorAction SilentlyContinue
                    $bakProps = Get-ItemProperty $bakPath -ErrorAction SilentlyContinue
                    Write-Host "  [FIX] SID $sid has a .bak duplicate (profile load failure pattern)" -ForegroundColor Yellow
                    Write-Host "        Primary ProfileImagePath: $($props.ProfileImagePath)" -ForegroundColor White
                    Write-Host "        .bak    ProfileImagePath: $($bakProps.ProfileImagePath)" -ForegroundColor White

                    # Rename primary -> .old
                    $oldPath = "$plBase\$sid.old"
                    if (Test-Path $oldPath) { Remove-Item-Logged -Path $oldPath -Recurse -Force }
                    Rename-Item-Logged -Path $prof.PSPath -NewName "$sid.old" -Force
                    # Rename .bak -> primary
                    Rename-Item-Logged -Path $bakPath -NewName $sid -Force

                    # Fix the State value (remove temporary profile flag)
                    $newPrimary = "$plBase\$sid"
                    $state = (Get-ItemProperty $newPrimary -ErrorAction SilentlyContinue).State
                    if ($null -ne $state -and ($state -band 0x8)) {
                        $newState = $state -band (-bnot 0x8)  # Clear bit 3 (temporary profile)
                        Set-ItemProperty-Logged -Path $newPrimary -Name State -Value $newState -Type DWord -Force
                        Write-Host "        Cleared temporary profile flag (State: $state -> $newState)" -ForegroundColor Green
                    }
                    # Set RefCount to 0 if present
                    $refCount = (Get-ItemProperty $newPrimary -ErrorAction SilentlyContinue).RefCount
                    if ($null -ne $refCount -and $refCount -ne 0) {
                        Set-ItemProperty-Logged -Path $newPrimary -Name RefCount -Value 0 -Type DWord -Force
                    }
                    $fixCount++
                }
                else {
                    # Check for corrupt State (bit 3 = temporary profile)
                    $state = (Get-ItemProperty $prof.PSPath -ErrorAction SilentlyContinue).State
                    if ($null -ne $state -and ($state -band 0x8)) {
                        Write-Host "  [FIX] SID $sid has temporary profile flag set (State=$state)" -ForegroundColor Yellow
                        $newState = $state -band (-bnot 0x8)
                        Set-ItemProperty-Logged -Path $prof.PSPath -Name State -Value $newState -Type DWord -Force
                        Write-Host "        Cleared temporary profile flag (State: $state -> $newState)" -ForegroundColor Green
                        $fixCount++
                    }
                }
            }

            if ($fixCount -gt 0) {
                Write-Host "Fixed $fixCount profile entry(s). Users should be able to log on normally." -ForegroundColor Green
            }
            else {
                Write-Host "  No corrupted profile entries found. All profiles appear healthy." -ForegroundColor DarkGray
            }
        }
    }

    function CheckRepairRegistryHives {
        param([switch]$Repair)
        # Downloads Microsoft's chkreg.exe utility and runs it against copies of the
        # offline VM's SYSTEM and SOFTWARE registry hives.
        #
        # Without -Repair: read-only check - reports corruption without modifying anything.
        # With    -Repair: repairs in-place (/R) and compacts (/C).  If any fixes were
        #                   applied, the original hives are backed up and the repaired
        #                   versions are copied back to the guest disk.
        #
        # chkreg.exe source: https://github.com/Azure/repair-script-library
        # (Microsoft Corporation, x64, used by Azure VM repair extensions)

        $mode = if ($Repair) { 'Repair' } else { 'Check' }
        Write-Host "Registry hive integrity $mode (using chkreg.exe)..." -ForegroundColor Yellow

        # -- 1. Download chkreg.exe -----------------------------------------------
        $toolDir = Join-Path $env:TEMP 'chkreg'
        $chkregPath = Join-Path $toolDir 'chkreg.exe'
        if (-not (Test-Path $toolDir)) { New-Item -Path $toolDir -ItemType Directory -Force | Out-Null }

        if (-not (Test-Path $chkregPath)) {
            $downloadUrl = 'https://github.com/Azure/repair-script-library/raw/main/src/windows/common/tools/chkreg.exe'
            Write-Host "  Downloading chkreg.exe from Azure repair-script-library..." -ForegroundColor Cyan
            try {
                $prevPref = $ProgressPreference
                $ProgressPreference = 'SilentlyContinue'
                Invoke-WebRequest -Uri $downloadUrl -OutFile $chkregPath -UseBasicParsing -ErrorAction Stop
                $ProgressPreference = $prevPref
            }
            catch {
                $ProgressPreference = $prevPref
                Write-Error "Failed to download chkreg.exe: $_"
                return
            }
            if (-not (Test-Path $chkregPath) -or (Get-Item $chkregPath).Length -lt 1024) {
                Write-Error "chkreg.exe download appears corrupt or incomplete."
                return
            }
            Write-Host "  Downloaded: $chkregPath" -ForegroundColor Green
        }
        else {
            Write-Host "  Using cached chkreg.exe: $chkregPath" -ForegroundColor DarkGray
        }

        # -- 2. Process each hive -------------------------------------------------
        $configDir = Join-Path $script:WinDriveLetter 'Windows\System32\config'
        $hivesToCheck = @('SYSTEM', 'SOFTWARE')
        $anyRepaired = $false

        foreach ($hiveName in $hivesToCheck) {
            $originalHive = Join-Path $configDir $hiveName
            if (-not (Test-Path $originalHive)) {
                Write-Warning "$hiveName hive not found at $originalHive - skipping."
                continue
            }
            if ((Get-Item $originalHive).Length -eq 0) {
                Write-Warning "$hiveName hive is 0 bytes (empty/corrupt) at $originalHive - chkreg cannot process an empty file."
                continue
            }

            Write-Host "`n  -- $hiveName hive --" -ForegroundColor Cyan

            # Copy hive to temp location to work on a copy, not the live file
            $tempHive = Join-Path $toolDir $hiveName
            Write-Host "  Copying $originalHive -> $tempHive" -ForegroundColor DarkGray
            Copy-Item -LiteralPath $originalHive -Destination $tempHive -Force

            # Also copy .LOG files if present (chkreg may need them for replay)
            foreach ($logSuffix in @('.LOG', '.LOG1', '.LOG2')) {
                $logFile = "$originalHive$logSuffix"
                if (Test-Path $logFile) {
                    Copy-Item -LiteralPath $logFile -Destination "$tempHive$logSuffix" -Force
                }
            }

            # -- 3. Run chkreg ----------------------------------------------------
            # chkreg.exe writes informational messages to stderr; capture both
            # streams and coerce ErrorRecord objects to plain strings so
            # PowerShell does not display red NativeCommandError noise.
            if ($Repair) {
                Write-Host "  Running: chkreg /F `"$tempHive`" /R /C" -ForegroundColor White
                $output = & $chkregPath /F "$tempHive" /R /C 2>&1 | ForEach-Object { "$_" } | Out-String
            }
            else {
                Write-Host "  Running: chkreg /F `"$tempHive`"" -ForegroundColor White
                $output = & $chkregPath /F "$tempHive" 2>&1 | ForEach-Object { "$_" } | Out-String
            }

            # Display the output
            $output.Trim().Split("`n") | ForEach-Object {
                $line = $_.TrimEnd()
                if ($line -match 'fixed') {
                    Write-Host "    $line" -ForegroundColor Yellow
                }
                elseif ($line -match 'SUMMARY|Total Hive|Bins') {
                    Write-Host "    $line" -ForegroundColor Cyan
                }
                elseif ($line -match 'successfully|no errors found') {
                    Write-Host "    $line" -ForegroundColor Green
                }
                elseif ($line -match 'error|corrupt|invalid' -and $line -notmatch 'fixed') {
                    Write-Host "    $line" -ForegroundColor Red
                }
                elseif (-not [string]::IsNullOrWhiteSpace($line)) {
                    Write-Host "    $line" -ForegroundColor DarkGray
                }
            }

            # -- 4. If repair mode and fixes were applied, copy back --------------
            $wasFixed = $output -match '\.\.\.\s*fixed'
            if ($Repair -and $wasFixed) {
                $anyRepaired = $true
                Write-Host "`n  [FIXED] $hiveName hive had corruption that was repaired." -ForegroundColor Yellow

                # Determine the best repaired file: /C writes compacted version to .BAK
                $compactedHive = "$tempHive.BAK"
                $repairedSource = if (Test-Path $compactedHive) {
                    Write-Host "  Using compacted version: $compactedHive" -ForegroundColor DarkGray
                    $compactedHive
                }
                else {
                    $tempHive
                }

                # Backup the original hive on the guest disk
                $bakPath = New-UniqueBackupPath -BasePath $originalHive -BakSuffix '.chkreg.bak'
                Write-Host "  Backing up original: $originalHive -> $bakPath" -ForegroundColor DarkGray
                Invoke-Logged -Description 'Back up registry hive before repair' -Details @{
                    Hive = $hiveName
                    Source = $originalHive
                    Destination = $bakPath
                } -ScriptBlock {
                    Copy-Item -LiteralPath $originalHive -Destination $bakPath -Force -ErrorAction Stop
                } | Out-Null

                # Copy repaired hive back
                Write-Host "  Copying repaired hive back: $repairedSource -> $originalHive" -ForegroundColor Green
                Invoke-Logged -Description 'Replace registry hive with repaired copy' -Details @{
                    Hive = $hiveName
                    Source = $repairedSource
                    Destination = $originalHive
                } -ScriptBlock {
                    Copy-Item -LiteralPath $repairedSource -Destination $originalHive -Force -ErrorAction Stop
                } | Out-Null

                Write-ActionLog -Event 'RegistryHiveRepaired' -Details @{
                    Hive           = $hiveName
                    OriginalBackup = $bakPath
                    RepairedFrom   = $repairedSource
                    ChkregOutput   = ($output.Trim() -replace "`r?`n", ' | ')
                }
            }
            elseif ($Repair) {
                Write-Host "`n  [OK] $hiveName hive: no corruption found." -ForegroundColor Green
            }
            else {
                # Check-only mode
                if ($wasFixed) {
                    # chkreg reports what WOULD be fixed even without /R
                    Write-Host "`n  [WARN] $hiveName hive has corruption. Run -FixRegistryCorruption to repair." -ForegroundColor Yellow
                }
                else {
                    Write-Host "`n  [OK] $hiveName hive: no corruption detected." -ForegroundColor Green
                }
            }
        }

        # -- 5. Summary -----------------------------------------------------------
        if ($Repair -and $anyRepaired) {
            Write-Host "`nRegistry hive repair complete. Original hives backed up with .chkreg.bak suffix." -ForegroundColor Green
            Write-Warning "If the VM still fails to boot after repair, the backup hives can be restored manually."
        }
        elseif (-not $Repair -and $anyRepaired) {
            Write-Host "`nCorruption detected. Use -FixRegistryCorruption to repair the hives." -ForegroundColor Yellow
        }
        else {
            Write-Host "`nNo registry hive corruption detected." -ForegroundColor Green
        }
    }

    function EnableSerialConsole {
        Write-Host "Enabling Emergency Management Services (EMS) / Serial Console..." -ForegroundColor Yellow
        try {
            $storePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $script:BootDriveLetter
            $identifier = Get-BcdBootLoaderId -StorePath $storePath
            if (-not $identifier) { return }

            # Enable EMS on the boot manager
            Invoke-BcdEdit -StorePath $storePath -Command "/bootems $identifier on"
            # Set EMS port (port 1) and baud rate (115200 is Azure Serial Console standard)
            Invoke-BcdEdit -StorePath $storePath -Command "/emssettings emsport:1 emsbaudrate:115200"
            # Enable EMS on the OS loader
            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier ems on"
            # Enable boot debugging output to serial
            Invoke-BcdEdit -StorePath $storePath -Command "/set $identifier bootems on"

            Write-Host "[OK] EMS / Serial Console enabled (port 1, baud 115200)." -ForegroundColor Green
            Write-Host "  On Azure, use: az serial-console connect --name <vm-name> --resource-group <rg>" -ForegroundColor DarkCyan
            Write-Host "  Or via Azure Portal -> VM -> Serial Console (under Help)" -ForegroundColor DarkCyan
        }
        catch {
            Write-Error "EnableSerialConsole failed: $_"
            throw
        }
    }

    function ListInstalledUpdates {
        Write-Host "Enumerating installed Windows Updates from offline guest disk..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $cbsBase = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\Packages'
            if (-not (Test-Path $cbsBase)) {
                Write-Warning "CBS Packages key not found."
                return
            }

            $packages = Get-ChildItem $cbsBase -ErrorAction SilentlyContinue | Where-Object {
                $_.PSChildName -match 'KB\d+'
            }

            # Extract KB numbers and deduplicate
            $kbList = [System.Collections.Generic.SortedDictionary[string, PSCustomObject]]::new()
            foreach ($pkg in $packages) {
                if ($pkg.PSChildName -match '(KB\d+)') {
                    $kb = $Matches[1]
                    if ($kbList.ContainsKey($kb)) { continue }
                    $props = Get-ItemProperty $pkg.PSPath -ErrorAction SilentlyContinue
                    $state = switch ($props.CurrentState) {
                        0 { 'Absent' }
                        5 { 'Uninstall Pending' }
                        16 { 'Resolving' }
                        32 { 'Resolved' }
                        48 { 'Staging' }
                        64 { 'Staged' }
                        80 { 'Superseded' }
                        96 { 'Install Pending' }
                        101 { 'partially Installed' }
                        112 { 'Installed' }
                        128 { 'Permanent' }
                        default { "State=$($props.CurrentState)" }
                    }
                    $installDate = $null
                    if ($props.InstallTimeHigh -and $props.InstallTimeLow) {
                        try {
                            $ft = ([long]$props.InstallTimeHigh -shl 32) -bor [long]$props.InstallTimeLow
                            if ($ft -gt 0) { $installDate = [datetime]::FromFileTimeUtc($ft).ToString('yyyy-MM-dd HH:mm') }
                        }
                        catch {}
                    }
                    $kbList[$kb] = [PSCustomObject]@{
                        KB      = $kb
                        State   = $state
                        Date    = if ($installDate) { $installDate } else { 'N/A' }
                        Package = $pkg.PSChildName
                    }
                }
            }

            if ($kbList.Count -eq 0) {
                Write-Host "  No KB packages found in CBS." -ForegroundColor DarkGray
                return
            }

            Write-Host "`n  $($kbList.Count) unique KB(s) found:`n" -ForegroundColor Cyan
            Write-Host ("  {0,-12} {1,-22} {2,-20} {3}" -f 'KB', 'State', 'Install Date', 'Package') -ForegroundColor DarkGray
            Write-Host ("  {0,-12} {1,-22} {2,-20} {3}" -f '----', '-----', '------------', '-------') -ForegroundColor DarkGray
            foreach ($entry in $kbList.Values) {
                $color = switch -Wildcard ($entry.State) {
                    'Installed' { 'Green' }
                    'Permanent' { 'Green' }
                    'Superseded' { 'DarkGray' }
                    'Staged' { 'Cyan' }
                    'Staging' { 'Cyan' }
                    '*Pending*' { 'Yellow' }
                    'Absent' { 'DarkGray' }
                    default { 'White' }
                }
                Write-Host ("  {0,-12} {1,-22} {2,-20} {3}" -f $entry.KB, $entry.State, $entry.Date, $entry.Package) -ForegroundColor $color
            }

            $staged = @($kbList.Values | Where-Object { $_.State -in @('Staged', 'Staging') })
            $pending = @($kbList.Values | Where-Object { $_.State -match 'Pending' })
            if ($pending.Count -gt 0) {
                Write-Host "  $($pending.Count) package(s) in pending state - these may cause boot loops. Consider -FixPendingUpdates." -ForegroundColor Yellow
            }
            if ($staged.Count -gt 0) {
                Write-Host "  $($staged.Count) package(s) in staged state (downloaded but not installed - harmless, no action needed)." -ForegroundColor DarkCyan
            }
            Write-Host ""
        }
    }

    function UninstallWindowsUpdate {
        param([Parameter(Mandatory = $true)][string]$KBNumber)

        # Normalise: accept "KB5001234" or just "5001234"
        $KBNumber = $KBNumber.Trim()
        if ($KBNumber -notmatch '^KB') { $KBNumber = "KB$KBNumber" }

        if (-not (Confirm-CriticalOperation -Operation "Uninstall Windows Update $KBNumber (-UninstallWindowsUpdate)" -Details @"
Marks the CBS package for $KBNumber as Absent (CurrentState=0) in the offline SOFTWARE hive.
Also clears any pending state for this package in CBS SessionsPending/PackagesPending.
On next boot, CBS should skip this update. This is an offline best-effort operation;
not all updates can be cleanly reversed this way.
"@)) { return }

        Write-Host "Attempting offline uninstall of $KBNumber..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $cbsBase = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\Packages'
            $packages = Get-ChildItem $cbsBase -ErrorAction SilentlyContinue | Where-Object {
                $_.PSChildName -match $KBNumber
            }

            if ($packages.Count -eq 0) {
                Write-Warning "No CBS packages matching $KBNumber found."
                return
            }

            $modified = 0
            foreach ($pkg in $packages) {
                $props = Get-ItemProperty $pkg.PSPath -ErrorAction SilentlyContinue
                $curState = $props.CurrentState
                if ($null -ne $curState -and $curState -ne 0) {
                    Write-Host "  $($pkg.PSChildName): CurrentState $curState -> 0 (Absent)" -ForegroundColor Yellow
                    Set-ItemProperty-Logged -Path $pkg.PSPath -Name CurrentState -Value 0 -Type DWord -Force
                    $modified++
                }
                else {
                    Write-Host "  $($pkg.PSChildName): already Absent" -ForegroundColor DarkGray
                }
            }

            # Clear pending state referencing this KB
            foreach ($pendKey in @('PackagesPending', 'SessionsPending')) {
                $pendPath = "HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\$pendKey"
                if (-not (Test-Path $pendPath)) { continue }
                Get-ChildItem $pendPath -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match $KBNumber } | ForEach-Object {
                    Remove-Item-Logged -Path $_.PSPath -Recurse -Force
                    Write-Host "  Removed pending entry: $pendKey\$($_.PSChildName)" -ForegroundColor Green
                }
            }

            Write-Host "$modified package(s) for $KBNumber marked as Absent." -ForegroundColor Green
            Write-Host "Boot the VM to verify. If the update was mid-install, also run -FixPendingUpdates." -ForegroundColor DarkCyan
        }
    }

    function ListStartupPrograms {
        Write-Host "Enumerating auto-start programs from offline guest registry..." -ForegroundColor Yellow
        $OfflineWindowsPath = Join-Path $script:WinDriveLetter "Windows"

        $allEntries = [System.Collections.Generic.List[PSCustomObject]]::new()

        # SOFTWARE hive (HKLM Run/RunOnce)
        Invoke-WithHive 'SOFTWARE' {
            $swPaths = @(
                @{ Key = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Run'; Scope = 'HKLM Run' }
                @{ Key = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'; Scope = 'HKLM RunOnce' }
            )
            foreach ($sp in $swPaths) {
                if (-not (Test-Path $sp.Key)) { continue }
                $props = Get-ItemProperty $sp.Key -ErrorAction SilentlyContinue
                foreach ($p in ($props.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' })) {
                    $allEntries.Add([PSCustomObject]@{ Scope = $sp.Scope; Name = $p.Name; Command = $p.Value })
                }
            }
        }

        # SYSTEM hive: check SetupType/CmdLine (setup-mode startup script)
        Invoke-WithHive 'SYSTEM' {
            $setupType = (Get-ItemProperty 'HKLM:\BROKENSYSTEM\Setup' -ErrorAction SilentlyContinue).SetupType
            $cmdLine = (Get-ItemProperty 'HKLM:\BROKENSYSTEM\Setup' -ErrorAction SilentlyContinue).CmdLine
            if ($setupType -and $setupType -ne 0 -and $cmdLine) {
                $allEntries.Add([PSCustomObject]@{ Scope = 'Setup CmdLine'; Name = "(SetupType=$setupType)"; Command = $cmdLine })
            }
        }

        # Startup folders on disk
        $startupFolders = @(
            @{ Path = Join-Path $script:WinDriveLetter 'ProgramData\Microsoft\Windows\Start Menu\Programs\Startup'; Scope = 'All Users Startup Folder' }
        )
        # Also scan per-user startup folders
        $usersDir = Join-Path $script:WinDriveLetter 'Users'
        if (Test-Path $usersDir) {
            Get-ChildItem $usersDir -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                $userStartup = Join-Path $_.FullName 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup'
                if (Test-Path $userStartup) {
                    $startupFolders += @{ Path = $userStartup; Scope = "User Startup ($($_.Name))" }
                }
            }
        }
        foreach ($sf in $startupFolders) {
            if (-not (Test-Path $sf.Path)) { continue }
            Get-ChildItem $sf.Path -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' } | ForEach-Object {
                $allEntries.Add([PSCustomObject]@{ Scope = $sf.Scope; Name = $_.Name; Command = $_.FullName })
            }
        }

        if ($allEntries.Count -eq 0) {
            Write-Host "  No auto-start entries found." -ForegroundColor DarkGray
            return
        }

        Write-Host "`n  $($allEntries.Count) auto-start entry(s) found:`n" -ForegroundColor Cyan
        Write-Host ("  {0,-25} {1,-28} {2}" -f 'Source', 'Name', 'Command') -ForegroundColor DarkGray
        Write-Host ("  {0,-25} {1,-28} {2}" -f '------', '----', '-------') -ForegroundColor DarkGray
        foreach ($e in $allEntries) {
            Write-Host ("  {0,-25} {1,-28} {2}" -f $e.Scope, $e.Name, $e.Command) -ForegroundColor White
        }
        Write-Host ""
    }

    function DisableStartupPrograms {
        if (-not (Confirm-CriticalOperation -Operation 'Disable Startup Programs (-DisableStartupPrograms)' -Details @"
Clears all entries from:
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Run
  HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce
And renames .exe/.bat/.cmd/.lnk/.vbs files in:
  All Users Startup folder
  Per-user Startup folders
to .disabled extension. Does NOT remove them; they can be re-enabled by renaming back.
"@)) { return }

        Write-Host "Disabling auto-start programs on offline guest..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $swPaths = @(
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Run'
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
            )
            foreach ($regPath in $swPaths) {
                if (-not (Test-Path $regPath)) { continue }
                $props = Get-ItemProperty $regPath -ErrorAction SilentlyContinue
                $cleared = 0
                foreach ($p in ($props.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' })) {
                    Remove-ItemProperty-Logged -Path $regPath -Name $p.Name
                    $cleared++
                }
                $keyLabel = ($regPath -split '\\')[-1]
                if ($cleared -gt 0) {
                    Write-Host "  Cleared $cleared entry(s) from HKLM\...\$keyLabel" -ForegroundColor Green
                }
                else {
                    Write-Host "  ${keyLabel}: already empty" -ForegroundColor DarkGray
                }
            }
        }

        # Rename startup folder items
        $disableExts = @('.exe', '.bat', '.cmd', '.lnk', '.vbs', '.vbe', '.js', '.wsf', '.wsh')
        $startupFolders = @(
            (Join-Path $script:WinDriveLetter 'ProgramData\Microsoft\Windows\Start Menu\Programs\Startup')
        )
        $usersDir = Join-Path $script:WinDriveLetter 'Users'
        if (Test-Path $usersDir) {
            Get-ChildItem $usersDir -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                $userStartup = Join-Path $_.FullName 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup'
                if (Test-Path $userStartup) { $startupFolders += $userStartup }
            }
        }
        foreach ($folder in $startupFolders) {
            if (-not (Test-Path $folder)) { continue }
            Get-ChildItem $folder -File -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -ne 'desktop.ini' -and $disableExts -contains $_.Extension.ToLower()
            } | ForEach-Object {
                $newName = "$($_.Name).disabled"
                Rename-Item-Logged -Path $_.FullName -NewName $newName -Force
                Write-Host "  Disabled: $($_.Name) -> $newName" -ForegroundColor Green
            }
        }

        Write-Host "Startup programs disabled. Run -ListStartupPrograms to review." -ForegroundColor Green
    }

    function DisableFirewall {
        Write-Host "Disabling Windows Firewall for all profiles on offline guest..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $SystemRoot = Get-SystemRootPath
            $fwBase = "$SystemRoot\Services\SharedAccess\Parameters\FirewallPolicy"

            $profiles = @(
                @{ Name = 'DomainProfile'; Desc = 'Domain' }
                @{ Name = 'StandardProfile'; Desc = 'Private' }
                @{ Name = 'PublicProfile'; Desc = 'Public' }
            )

            foreach ($prof in $profiles) {
                $profPath = "$fwBase\$($prof.Name)"
                if (-not (Test-Path $profPath)) {
                    Write-Host "  $($prof.Desc) profile key not found - skipping." -ForegroundColor DarkGray
                    continue
                }
                $current = (Get-ItemProperty $profPath -ErrorAction SilentlyContinue).EnableFirewall
                if ($current -eq 0) {
                    Write-Host "  $($prof.Desc): already disabled" -ForegroundColor DarkGray
                }
                else {
                    Set-ItemProperty-Logged -Path $profPath -Name EnableFirewall -Value 0 -Type DWord -Force
                    Write-Host "  $($prof.Desc): DISABLED (was $current)" -ForegroundColor Green
                }
            }

            Write-Host "`nWindows Firewall disabled for all profiles." -ForegroundColor Green
            Write-Warning "Remember to re-enable the firewall after recovery:"
            Write-Warning "  Set-NetFirewallProfile -Profile Domain,Public,Private -Enabled True"
        }
    }

    function FixFirewallDebugLoopbackApps {
        Write-Host "Checking the offline Windows Firewall loopback-app registry value..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            & {
                $systemRoot = Get-SystemRootPath
                $appCsPath = "$systemRoot\Services\mpssvc\Parameters\AppCs"
                $activeValueName = 'DebugedLoopbackApps'
                $renamedValueName = 'DebugedLoopbackApps_'
                $state = Invoke-FirewallDebugLoopbackAppsAsSystem -AppCsPath $appCsPath -Operation Inspect
                if ($state.PermissionsAdjusted) {
                    Write-Host "  [OK] Temporarily adjusted AppCs access and restored its captured owner and DACL after inspection." -ForegroundColor Green
                }

                if (-not $state.PathExists) {
                    Write-Warning "Windows Firewall AppCs key not found in the active offline ControlSet: $appCsPath"
                    return
                }
                if (-not $state.ActiveValueExists) {
                    if (-not $state.RenamedValueExists) {
                        Write-Warning "Registry value $activeValueName was not found at $appCsPath. No changes were made."
                        return
                    }
                }
                $duplicateSummary = if ($state.DuplicateSidCount -gt 0) {
                    "$($state.DuplicateSidCount) duplicated SID(s), $($state.DuplicateEntryCount) extra duplicate occurrence(s)"
                }
                else {
                    'no exact duplicate SIDs detected'
                }
                $operationDetails = if ($state.ActiveValueExists) {
@"
Archives the current registry value in the active offline ControlSet:
  $appCsPath
  $activeValueName -> $renamedValueName

Current value: $($state.EntryCount) entries; $duplicateSummary.
The original data is preserved under the new value name, then an empty
$activeValueName value is recreated with the original registry type.
$(
    if ($state.RenamedValueExists) {
        "An existing $renamedValueName value will be replaced before the current value is renamed."
    }
)
"@
                }
                else {
@"
Recreates the missing empty registry value in the active offline ControlSet:
  $appCsPath
  $activeValueName

The registry type is copied from the existing $renamedValueName value.
The archived data in $renamedValueName is not changed.
"@
                }
                if (-not (Confirm-CriticalOperation -Operation 'Fix Windows Firewall loopback-app SID accumulation (-FixFirewallDebugLoopbackApps)' -Details @"
$operationDetails
Default and LastKnownGood control sets are not modified.
"@)) { return }

                $afterState = Invoke-FirewallDebugLoopbackAppsAsSystem -AppCsPath $appCsPath -Operation Rename
                if ($afterState.OriginalMissing -and -not $afterState.EmptyValueCreated) {
                    Write-Warning "$activeValueName was no longer present when the SYSTEM repair step ran. No registry values were changed."
                    return
                }
                if ($afterState.EmptyValueCreated -and -not $afterState.RenamePerformed) {
                    Write-Host "  [OK] Recreated the missing empty $activeValueName value using the registry type from $renamedValueName." -ForegroundColor Green
                }
                elseif (-not $afterState.RenamePerformed -or
                    -not $afterState.ActiveValueExists -or
                    -not $afterState.RenamedValueExists -or
                    $afterState.EntryCount -ne 0) {
                    throw "Failed to archive $activeValueName as $renamedValueName and recreate an empty original value at $appCsPath."
                }

                if ($afterState.PermissionsAdjusted) {
                    Write-Host "  [OK] Restored and verified the captured AppCs owner and DACL after the rename." -ForegroundColor Green
                }
                if ($afterState.RenamePerformed) {
                    $replacementText = if ($afterState.ReplacedExistingRenamed) { ' after replacing the previous renamed value' } else { '' }
                    Write-Host "  [OK] Archived $activeValueName as $renamedValueName$replacementText and recreated an empty original value in $(Get-CurrentOfflineControlSetName)." -ForegroundColor Green
                }
                Write-Warning "Restart the repaired guest so the Windows Defender Firewall service can rebuild its loopback-app state."
                Write-ActionLog -Event 'FixFirewallDebugLoopbackApps' -Details @{
                    Path                 = $appCsPath
                    OldName              = $activeValueName
                    NewName              = $renamedValueName
                    EntryCount           = $state.EntryCount
                    DuplicateSidCount    = $state.DuplicateSidCount
                    DuplicateEntryCount  = $state.DuplicateEntryCount
                    PermissionsAdjusted  = [bool]($state.PermissionsAdjusted -or $afterState.PermissionsAdjusted)
                    PermissionsRestored  = [bool](((-not $state.PermissionsAdjusted) -or $state.PermissionsRestored) -and ((-not $afterState.PermissionsAdjusted) -or $afterState.PermissionsRestored))
                    RenamePerformed      = [bool]$afterState.RenamePerformed
                    ReplacedExistingRenamed = [bool]$afterState.ReplacedExistingRenamed
                    EmptyValueCreated    = [bool]$afterState.EmptyValueCreated
                    ExecutedAsSystem      = $true
                }
            }
        }
    }

    function AnalyzeCriticalBootFiles {
        Write-Host "Analyzing critical boot/system files on offline guest..." -ForegroundColor Yellow
        $checks = @(
            @{ Name = 'BCD store'; Path = (Get-BcdStorePath -BootDrive $script:BootDriveLetter -Generation $script:VMGen); Category = 'Boot Loader' }
            @{ Name = 'winload'; Path = (Join-Path $script:WinDriveLetter $(if ($script:VMGen -eq 2) { 'Windows\System32\winload.efi' } else { 'Windows\System32\winload.exe' })); Category = 'Boot Loader' }
            @{ Name = 'ntoskrnl.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntoskrnl.exe'); Category = 'Kernel & HAL' }
            @{ Name = 'hal.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\hal.dll'); Category = 'Kernel & HAL' }
            @{ Name = 'ci.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ci.dll'); Category = 'Kernel & HAL' }
            @{ Name = 'Driver.stl'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\CodeIntegrity\Driver.stl'); Category = 'Code Integrity Policy'; Optional = $true }
            @{ Name = 'DriverSiPolicy.p7b'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\CodeIntegrity\DriverSiPolicy.p7b'); Category = 'Code Integrity Policy'; Optional = $true }
            @{ Name = 'ntdll.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntdll.dll'); Category = 'Core DLL' }
            @{ Name = 'kernel32.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\kernel32.dll'); Category = 'Core DLL' }
            @{ Name = 'smss.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\smss.exe'); Category = 'Session Init' }
            @{ Name = 'csrss.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\csrss.exe'); Category = 'Session Init' }
            @{ Name = 'wininit.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\wininit.exe'); Category = 'Session Init' }
            @{ Name = 'services.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\services.exe'); Category = 'Session Init' }
            @{ Name = 'lsass.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\lsass.exe'); Category = 'Session Init' }
            @{ Name = 'winlogon.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\winlogon.exe'); Category = 'Session Init' }
            @{ Name = 'logonui.exe'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\logonui.exe'); Category = 'Session Init' }
        )
        # Gen1 BIOS: bootmgr lives at the root of the boot partition
        if ($script:VMGen -eq 1) {
            $checks += @(
                @{ Name = 'bootmgr'; Path = (Join-Path $script:BootDriveLetter 'bootmgr'); Category = 'Boot Loader' }
            )
        }
        # Gen2 UEFI: firmware boot manager and fallback loader
        if ($script:VMGen -eq 2) {
            $checks += @(
                @{ Name = 'bootmgfw source'; Path = (Join-Path $script:WinDriveLetter 'Windows\Boot\EFI\bootmgfw.efi'); Category = 'Boot Loader Source' }
                @{ Name = 'bootmgfw.efi'; Path = (Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot\bootmgfw.efi'); Category = 'Boot Loader' }
                @{ Name = 'bootx64.efi'; Path = (Join-Path $script:BootDriveLetter 'EFI\Boot\bootx64.efi'); Category = 'Boot Loader' }
            )
        }
        # Azure/Hyper-V critical drivers - missing any of these will BSOD or cripple the VM
        # Only includes inbox Hyper-V drivers present on every guest; storflt/vmstorfl are
        # Azure-agent or version-specific and checked conditionally in GetBootPathReport instead.
        $azureCriticalDrivers = @(
            @{ Name = 'vmbus.sys';    Desc = 'Hyper-V VMBus' }
            @{ Name = 'storvsc.sys';  Desc = 'Hyper-V Storage' }
            @{ Name = 'netvsc.sys';   Desc = 'Hyper-V Network'; AlternateBinPatterns = @('netvsc*.sys') }
        )
        foreach ($drv in $azureCriticalDrivers) {
            $bin = Resolve-DriverBinaryCandidate -Binary $drv.Name -AlternatePatterns $drv.AlternateBinPatterns
            $name = if ($bin.Exists) { $bin.Name } else { $drv.Name }
            $checks += @{ Name = $name; Path = $bin.Path; Category = "Azure Driver ($($drv.Desc))" }
        }

        $rows = foreach ($c in $checks) {
            $exists = Test-Path -LiteralPath $c.Path
            $size = if ($exists) { (Get-Item -LiteralPath $c.Path -Force -ErrorAction SilentlyContinue).Length } else { 0 }
            # Signature check for existing non-zero binaries (skip BCD store  -  it's not a PE)
            $sigStatus = ''
            $sigIsHardFailure = $false
            if ($exists -and $size -gt 0 -and $c.Name -ne 'BCD store' -and -not ([bool]$c.SkipSignature)) {
                $sig = Test-MicrosoftSignature -FilePath $c.Path
                $sigIsHardFailure = [bool]$sig.IsHardFailure
                $sigStatus = switch ($sig.TrustState) {
                    'ValidMicrosoft' { 'Microsoft' }
                    'ValidOtherPublisher' { "Signed: $($sig.SignerSubject)" }
                    'Invalid' { "INVALID ($($sig.Status))" }
                    'CatalogUnverified' { 'Unverified (MS metadata)' }
                    default { $sig.Status }
                }
            }
            [PSCustomObject]@{
                Category  = $c.Category
                Artifact  = $c.Name
                Exists    = $exists
                Size      = if ($exists) { "{0:N0}" -f $size } else { '' }
                Signature = $sigStatus
                HardFail  = $sigIsHardFailure
                Path      = $c.Path
                Optional  = [bool]$c.Optional
            }
        }

        $rows | Format-Table Category, Artifact, Exists, Size, Signature, Path -AutoSize
        $missing = @($rows | Where-Object { -not $_.Exists -and -not $_.Optional })
        $zeroLen = @($rows | Where-Object { $_.Exists -and $_.Size -eq '0' })
        $invalidTrust = @($rows | Where-Object { $_.HardFail })
        $notMsSigned = @($rows | Where-Object { $_.Signature -and $_.Signature -ne 'Microsoft' -and -not $_.HardFail -and $_.Artifact -ne 'BCD store' })
        if ($missing.Count -gt 0) {
            Write-Warning "Missing critical artifact(s): $($missing.Artifact -join ', ')."
        }
        if ($zeroLen.Count -gt 0) {
            Write-Warning "Zero-byte (corrupt) critical artifact(s): $($zeroLen.Artifact -join ', ') - file exists but is empty."
        }
        if ($invalidTrust.Count -gt 0) {
            Write-Warning "FAILED image trust validation: $($invalidTrust.Artifact -join ', ') - the file content does not match its signature or is published in no guest catalog. Windows Code Integrity will refuse to load these."
            Write-Host "  These produce STATUS_INVALID_IMAGE_HASH (0xC0000428) at load, which surfaces as 0x5A CRITICAL_SERVICE_FAILED." -ForegroundColor Red
            Write-Host "  Fix: -RepairSystemFile $(($invalidTrust.Artifact | Select-Object -First 4) -join ', ')" -ForegroundColor Red
            Write-Host "  If the component store holds the same damaged bytes (a hard link to the file), add -RepairSystemFileSource <file-or-folder>." -ForegroundColor Red
        }
        if ($notMsSigned.Count -gt 0) {
            Write-Warning "Not verified as Microsoft: $($notMsSigned.Artifact -join ', ') - third-party publisher or trust not provable from this host."
        }

        if ($script:VMGen -eq 2) {
            Write-Host "`nSecure Boot payload comparison (advisory):" -ForegroundColor Cyan

            $secureBootPayloadPairs = @(
                @{ Label = 'bootmgfw.efi'; Source = (Join-Path $script:WinDriveLetter 'Windows\Boot\EFI\bootmgfw.efi'); Target = (Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot\bootmgfw.efi'); TargetRole = 'EFI\Microsoft\Boot' }
                @{ Label = 'bootx64.efi fallback loader'; Source = (Join-Path $script:WinDriveLetter 'Windows\Boot\EFI\bootmgfw.efi'); Target = (Join-Path $script:BootDriveLetter 'EFI\Boot\bootx64.efi'); TargetRole = 'EFI\Boot' }
                @{ Label = 'SKUSiPolicy.p7b'; Source = (Join-Path $script:WinDriveLetter 'Windows\System32\SecureBootUpdates\SKUSiPolicy.p7b'); Target = (Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot\SKUSiPolicy.p7b'); TargetRole = 'EFI\Microsoft\Boot' }
            )

            $payloadRows = foreach ($pair in $secureBootPayloadPairs) {
                $sourceItem = Get-Item -LiteralPath $pair.Source -Force -ErrorAction SilentlyContinue
                $targetItem = Get-Item -LiteralPath $pair.Target -Force -ErrorAction SilentlyContinue
                $status = 'OK'
                $detail = ''

                if (-not $sourceItem) {
                    $detail = 'Windows-staged source not present; no ESP comparison available.'
                }
                elseif ($sourceItem.Length -eq 0) {
                    $status = 'WARN'
                    $detail = 'Windows-staged source is 0 bytes; repair component store before using it as a source.'
                }
                elseif (-not $targetItem) {
                    $detail = 'Not present on ESP; can be normal until Secure Boot mitigation is applied.'
                }
                elseif ($targetItem.Length -eq 0) {
                    $status = 'WARN'
                    $detail = 'ESP target is 0 bytes; suspicious payload state.'
                }
                else {
                    $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $pair.Source -ErrorAction SilentlyContinue).Hash
                    $targetHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $pair.Target -ErrorAction SilentlyContinue).Hash
                    if (-not $sourceHash -or -not $targetHash) {
                        $status = 'WARN'
                        $detail = 'Could not hash source or ESP target.'
                    }
                    elseif ($sourceItem.Length -eq $targetItem.Length -and $sourceHash -eq $targetHash) {
                        $detail = 'ESP target matches Windows-staged source.'
                    }
                    else {
                        $detail = 'ESP target differs from Windows-staged source; advisory only and can be normal on a healthy VM.'
                    }
                }

                [PSCustomObject]@{
                    Status     = $status
                    Artifact   = $pair.Label
                    SourceSize = if ($sourceItem) { "{0:N0}" -f $sourceItem.Length } else { '' }
                    TargetSize = if ($targetItem) { "{0:N0}" -f $targetItem.Length } else { '' }
                    Target     = $pair.TargetRole
                    Detail     = $detail
                }
            }

            $payloadRows | Format-Table Status, Artifact, SourceSize, TargetSize, Target, Detail -AutoSize
            $payloadWarnings = @($payloadRows | Where-Object { $_.Status -eq 'WARN' })
            if ($payloadWarnings.Count -gt 0) {
                Write-Warning "Suspicious Secure Boot payload state(s): $($payloadWarnings.Artifact -join ', ')."
                Write-Host "If the VM fails with winload.efi / Code Integrity error 0xc0430001, run -FixSecureBootCodeIntegrity." -ForegroundColor Yellow
            }
            else {
                Write-Host "Secure Boot payload comparison found no suspicious zero-byte or unreadable payloads." -ForegroundColor Green
            }
        }

        if ($missing.Count -eq 0 -and $zeroLen.Count -eq 0 -and $invalidTrust.Count -eq 0 -and $notMsSigned.Count -eq 0) {
            Write-Host "All checked critical boot/system files are present, non-empty, and Microsoft-signed." -ForegroundColor Green
        }
    }

    function New-ProtectedSystemFileAcl {
        $acl = [System.Security.AccessControl.FileSecurity]::new()
        $acl.SetAccessRuleProtection($true, $false)

        $trustedInstallerSid = [System.Security.Principal.SecurityIdentifier]::new('S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')
        $acl.SetOwner($trustedInstallerSid)
        # Windows ships its system files with TrustedInstaller as the primary group as
        # well as the owner. Leaving the group unset stamps the rescue VM's own primary
        # group onto the guest's file, which makes the repaired file the odd one out in
        # any ACL comparison against its neighbours even though its DACL is identical.
        $acl.SetGroup($trustedInstallerSid)

        $accessType = [System.Security.AccessControl.AccessControlType]::Allow
        $inheritanceFlags = [System.Security.AccessControl.InheritanceFlags]::None
        $propagationFlags = [System.Security.AccessControl.PropagationFlags]::None
        $readExecute = [System.Security.AccessControl.FileSystemRights]::ReadAndExecute

        $rules = @(
            @{ Sid = 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464'; Rights = [System.Security.AccessControl.FileSystemRights]::FullControl }, # NT SERVICE\TrustedInstaller
            @{ Sid = 'S-1-5-32-544'; Rights = $readExecute }, # BUILTIN\Administrators
            @{ Sid = 'S-1-5-18'; Rights = $readExecute }, # NT AUTHORITY\SYSTEM
            @{ Sid = 'S-1-5-32-545'; Rights = $readExecute }, # BUILTIN\Users
            @{ Sid = 'S-1-15-2-1'; Rights = $readExecute }, # ALL APPLICATION PACKAGES
            @{ Sid = 'S-1-15-2-2'; Rights = $readExecute } # ALL RESTRICTED APPLICATION PACKAGES
        )

        foreach ($ruleInfo in $rules) {
            $identity = [System.Security.Principal.SecurityIdentifier]::new($ruleInfo.Sid)
            $rule = [System.Security.AccessControl.FileSystemAccessRule]::new(
                $identity,
                $ruleInfo.Rights,
                $inheritanceFlags,
                $propagationFlags,
                $accessType
            )
            $acl.AddAccessRule($rule)
        }

        return $acl
    }

    # Builds a single-pass index of replacement sources for one or more file names.
    #
    # The previous implementation ran `Get-ChildItem -Recurse` over WinSxS *and*
    # DriverStore once per requested file name. WinSxS holds tens of thousands of
    # component directories, so each pass walked the whole tree again and the cost
    # grew linearly with the number of files being repaired. This walks both roots
    # exactly once for the whole batch using the BCL enumerator (no FileInfo/PSObject
    # allocation per traversed entry) and caches the result for the session.
    function Get-FileIdentity {
        # Returns the volume serial and file index that together identify one MFT
        # record, plus how many directory entries point at it.
        #
        # This is how a hard link is spotted. Most Windows inbox files are stored once
        # and linked into both \Windows\WinSxS\<component>\ and their live location, so
        # the "component store copy" is frequently the very same data. When the live
        # file is damaged in place, restoring from that link would change nothing while
        # reporting success.
        param([Parameter(Mandatory = $true)][string]$Path)

        if (-not ([System.Management.Automation.PSTypeName]'RepairAzVMDisk.FileIdentity').Type) {
            try {
                Add-Type -Namespace RepairAzVMDisk -Name FileIdentity -MemberDefinition @'
[StructLayout(LayoutKind.Sequential)]
public struct BY_HANDLE_FILE_INFORMATION {
    public uint FileAttributes;
    // FILETIME is two DWORDs and only 4-byte aligned. Declaring these as long would
    // make the CLR insert 4 bytes of padding after FileAttributes, shifting every
    // field that follows and yielding a zero volume serial and a nonsense link count.
    public uint CreationTimeLow;
    public uint CreationTimeHigh;
    public uint LastAccessTimeLow;
    public uint LastAccessTimeHigh;
    public uint LastWriteTimeLow;
    public uint LastWriteTimeHigh;
    public uint VolumeSerialNumber;
    public uint FileSizeHigh;
    public uint FileSizeLow;
    public uint NumberOfLinks;
    public uint FileIndexHigh;
    public uint FileIndexLow;
}
[DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
public static extern IntPtr CreateFileW(string path, uint access, uint share, IntPtr sec, uint disposition, uint flags, IntPtr template);
[DllImport("kernel32.dll", SetLastError = true)]
public static extern bool GetFileInformationByHandle(IntPtr handle, out BY_HANDLE_FILE_INFORMATION info);
[DllImport("kernel32.dll", SetLastError = true)]
public static extern bool CloseHandle(IntPtr handle);
'@ -ErrorAction Stop
            }
            catch {
                Write-Verbose "Hard-link detection is unavailable: $($_.Exception.Message)"
                return $null
            }
        }

        $handle = [IntPtr]::Zero
        try {
            # Zero desired access asks only for metadata, so this succeeds on a
            # TrustedInstaller-owned file that we are not yet permitted to read.
            # Sharing everything, including DELETE, avoids disturbing other openers.
            $handle = [RepairAzVMDisk.FileIdentity]::CreateFileW(
                $Path, 0, 7, [IntPtr]::Zero, 3, 0x02000000, [IntPtr]::Zero)
            if ($handle -eq [IntPtr]::Zero -or $handle -eq [IntPtr](-1)) { return $null }

            $info = New-Object RepairAzVMDisk.FileIdentity+BY_HANDLE_FILE_INFORMATION
            if (-not [RepairAzVMDisk.FileIdentity]::GetFileInformationByHandle($handle, [ref]$info)) { return $null }

            $index = ([uint64]$info.FileIndexHigh -shl 32) -bor [uint64]$info.FileIndexLow
            return [PSCustomObject]@{
                VolumeSerialNumber = $info.VolumeSerialNumber
                FileIndex          = $index
                LinkCount          = [int]$info.NumberOfLinks
                Id                 = ('{0:X8}:{1:X16}' -f $info.VolumeSerialNumber, $index)
            }
        }
        catch {
            return $null
        }
        finally {
            if ($handle -ne [IntPtr]::Zero -and $handle -ne [IntPtr](-1)) {
                [void][RepairAzVMDisk.FileIdentity]::CloseHandle($handle)
            }
        }
    }

    function Initialize-FastFileSearchType {
        if ($null -ne $script:FastFileSearchReady) { return $script:FastFileSearchReady }
        if ('RepairAzVMDisk.FastFileSearch' -as [type]) {
            $script:FastFileSearchReady = $true
            return $true
        }
        try {
            Add-Type -TypeDefinition @'
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;

namespace RepairAzVMDisk
{
    public static class FastFileSearch
    {
        // Finds every file under root whose name matches one of the wanted names.
        //
        // WinSxS holds tens of thousands of component directories, and walking them
        // one at a time from PowerShell costs minutes: the per-directory overhead of
        // the interpreter dwarfs the actual I/O. The same walk in .NET, with the
        // top-level component folders spread across threads, is bound by the disk
        // instead of by the loop.
        //
        // Each directory is enumerated inside its own try/catch so that one unreadable
        // folder cannot abort the traversal - which is what SearchOption.AllDirectories
        // would do, silently returning a partial result as if it were complete.
        public static string[] Find(string root, string[] wantedNames, int[] stats)
        {
            HashSet<string> wanted = new HashSet<string>(wantedNames, StringComparer.OrdinalIgnoreCase);
            ConcurrentBag<string> hits = new ConcurrentBag<string>();
            int dirCount = 0;

            List<string> topLevel = new List<string>();
            topLevel.Add(root);
            try
            {
                foreach (string d in Directory.EnumerateDirectories(root)) topLevel.Add(d);
            }
            catch { }

            ParallelOptions options = new ParallelOptions();
            options.MaxDegreeOfParallelism = Math.Min(16, Math.Max(2, Environment.ProcessorCount * 2));

            Parallel.ForEach(topLevel, options, delegate(string start)
            {
                Stack<string> pending = new Stack<string>();
                pending.Push(start);
                int localDirs = 0;
                bool isRoot = string.Equals(start, root, StringComparison.OrdinalIgnoreCase);

                while (pending.Count > 0)
                {
                    string dir = pending.Pop();
                    localDirs++;

                    // The root itself is handled for its own files only; its
                    // subdirectories are the parallel work items and must not be
                    // walked twice.
                    if (!(isRoot && localDirs == 1))
                    {
                        try
                        {
                            foreach (string sub in Directory.EnumerateDirectories(dir)) pending.Push(sub);
                        }
                        catch { }
                    }

                    try
                    {
                        foreach (string file in Directory.EnumerateFiles(dir))
                        {
                            if (wanted.Contains(Path.GetFileName(file))) hits.Add(file);
                        }
                    }
                    catch { }
                }
                System.Threading.Interlocked.Add(ref dirCount, localDirs);
            });

            if (stats != null && stats.Length >= 1) { stats[0] = dirCount; }
            List<string> result = new List<string>(hits);
            result.Sort(StringComparer.OrdinalIgnoreCase);
            return result.ToArray();
        }
    }
}
'@ -ErrorAction Stop
            $script:FastFileSearchReady = $true
        }
        catch {
            $script:FastFileSearchReady = $false
            Write-Verbose "Native file search is unavailable; falling back to the managed walk: $($_.Exception.Message)"
        }
        return $script:FastFileSearchReady
    }

    function Get-SystemFileRepairSourceIndex {
        param(
            [Parameter(Mandatory = $true)][string[]]$FileNames,
            [Parameter(Mandatory = $true)][string]$WinRoot,
            [string]$SourcePath = ''
        )

        $wanted = @{}
        foreach ($name in $FileNames) {
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $wanted[$name.Trim().ToLowerInvariant()] = $true
        }
        if ($wanted.Count -eq 0) { return @{} }

        if ($null -eq $script:RepairSourceIndexCache) { $script:RepairSourceIndexCache = @{} }
        $cacheKey = '{0}|{1}|{2}' -f $WinRoot.ToLowerInvariant(), $SourcePath.ToLowerInvariant(), (($wanted.Keys | Sort-Object) -join ';')
        if ($script:RepairSourceIndexCache.ContainsKey($cacheKey)) {
            return $script:RepairSourceIndexCache[$cacheKey]
        }

        $index = @{}
        foreach ($key in $wanted.Keys) { $index[$key] = [System.Collections.Generic.List[PSCustomObject]]::new() }

        $roots = @(
            [PSCustomObject]@{ Path = (Join-Path $WinRoot 'WinSxS'); Source = 'WinSxS' }
            [PSCustomObject]@{ Path = (Join-Path $WinRoot 'System32\DriverStore\FileRepository'); Source = 'DriverStore' }
        )
        if (-not [string]::IsNullOrWhiteSpace($SourcePath) -and (Test-Path -LiteralPath $SourcePath)) {
            # Searched first so an operator-supplied known-good copy outranks the
            # component store, which on a damaged guest may hold the same bad bytes.
            $roots = @([PSCustomObject]@{ Path = $SourcePath; Source = 'SuppliedSource' }) + $roots
        }

        foreach ($root in $roots) {
            if (-not (Test-Path -LiteralPath $root.Path)) { continue }
            # A supplied source may name the file itself rather than a folder holding it.
            if (Test-Path -LiteralPath $root.Path -PathType Leaf) {
                $leaf = [System.IO.Path]::GetFileName($root.Path).ToLowerInvariant()
                if ($wanted.ContainsKey($leaf)) {
                    $index[$leaf].Add([PSCustomObject]@{ Path = $root.Path; Source = $root.Source })
                    Write-Host "  Using supplied source file: $($root.Path)" -ForegroundColor DarkGray
                }
                else {
                    Write-Warning "  The supplied source file is named '$leaf', which is not one of the files being repaired. It was ignored."
                }
                continue
            }
            Write-Host "  Indexing $($root.Source)..." -ForegroundColor DarkGray
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            $dirCount = 0
            $hitCount = 0

            if (Initialize-FastFileSearchType) {
                $searchStats = [int[]]@(0)
                $found = @()
                try {
                    $found = @([RepairAzVMDisk.FastFileSearch]::Find($root.Path, [string[]]@($wanted.Keys), $searchStats))
                }
                catch {
                    Write-Verbose "Native search failed on $($root.Path): $($_.Exception.Message)"
                    $found = $null
                }
                if ($null -ne $found) {
                    $dirCount = $searchStats[0]
                    foreach ($file in $found) {
                        $leaf = [System.IO.Path]::GetFileName($file).ToLowerInvariant()
                        if ($index.ContainsKey($leaf)) {
                            $index[$leaf].Add([PSCustomObject]@{ Path = $file; Source = $root.Source })
                            $hitCount++
                        }
                    }
                    $sw.Stop()
                    Write-Host ("    {0}: {1:N0} directories scanned, {2} candidate file(s), {3:N1}s" -f $root.Source, $dirCount, $hitCount, $sw.Elapsed.TotalSeconds) -ForegroundColor DarkGray
                    continue
                }
            }

            $pending = [System.Collections.Generic.Stack[string]]::new()
            $pending.Push($root.Path)
            while ($pending.Count -gt 0) {
                $dir = $pending.Pop()
                $dirCount++
                # Enumerate per directory so a single ACL-denied or transient failure
                # cannot abort the whole traversal (AllDirectories would throw out).
                try {
                    foreach ($sub in [System.IO.Directory]::EnumerateDirectories($dir)) { $pending.Push($sub) }
                }
                catch { }
                try {
                    foreach ($file in [System.IO.Directory]::EnumerateFiles($dir)) {
                        $leaf = [System.IO.Path]::GetFileName($file).ToLowerInvariant()
                        if ($wanted.ContainsKey($leaf)) {
                            $index[$leaf].Add([PSCustomObject]@{ Path = $file; Source = $root.Source })
                            $hitCount++
                        }
                    }
                }
                catch { }
            }
            $sw.Stop()
            Write-Host ("    {0}: {1:N0} directories scanned, {2} candidate file(s), {3:N1}s" -f $root.Source, $dirCount, $hitCount, $sw.Elapsed.TotalSeconds) -ForegroundColor DarkGray
        }

        # \Windows\WinSxS\Backup is deliberately NOT searched. It looks like the ideal
        # spare - genuinely separate files rather than the hard links the component
        # directories hold - but its contents are reverse delta patches, not binaries.
        # Their names are mangled to <component-identity>_<filename>_<hash>, and each
        # file begins with the "DCS" Delta Compression Storage signature and is roughly
        # 40% of the size of the binary it relates to. Handing one to a caller as a
        # replacement would install a compressed blob in place of a driver.

        $script:RepairSourceIndexCache[$cacheKey] = $index
        return $index
    }

    function RepairBrokenSystemFile {
        param(
            [Parameter(Mandatory = $true)]
            [string[]]$FileNames,
            [string]$SourcePath = ''
        )
        # Replaces a missing, 0-byte, or wrong-architecture Windows system binary
        # from the offline disk's WinSxS component store or DriverStore.
        #
        # Search sources:
        #   1. \Windows\WinSxS\<component>\<filename>          (component store - primary)
        #   2. \Windows\System32\DriverStore\FileRepository\*\<filename>  (driver packages)
        #
        # Known PE architecture mismatches are excluded before version/source ranking.
        # Only Microsoft/Windows binaries are expected targets (e.g. storvsc.sys, ntoskrnl.exe).
        # The original file (if present) is backed up before replacement.
        #
        # Reference: https://learn.microsoft.com/en-us/troubleshoot/azure/virtual-machines/windows/virtual-machines-windows-repair-replace-system-binary-file

        $portableExecutableExtensions = @('.sys', '.dll', '.exe', '.efi')
        if (-not [string]::IsNullOrWhiteSpace($SourcePath)) {
            if (-not (Test-Path -LiteralPath $SourcePath)) {
                Write-Error "The -RepairSystemFileSource path does not exist: $SourcePath"
                return
            }
            Write-Host "Repair source supplied: $SourcePath" -ForegroundColor DarkGray
        }
        $guestArchitecture = Get-OfflineGuestProcessorArchitecture
        if ($guestArchitecture -eq 'Unknown') {
            $guestArchitecture = 'AMD64'
            Write-Warning "The offline guest architecture could not be determined. Defaulting to AMD64/x64, which is the supported Azure Windows VM image architecture."
            Write-Warning "Do not continue on a legacy specialized 32-bit VHD unless its x86 architecture can be confirmed from the offline registry or kernel."
        }
        else {
            Write-Host "Offline guest architecture: $guestArchitecture" -ForegroundColor DarkGray
        }

        foreach ($fileName in $FileNames) {
            $fileName = $fileName.Trim()
            if ([string]::IsNullOrWhiteSpace($fileName)) { continue }

            Write-Host "`nProcessing: $fileName" -ForegroundColor Cyan

            # -- 1. Determine the expected target path on the offline disk --------
            $ext = [System.IO.Path]::GetExtension($fileName).ToLower()
            $winRoot = Join-Path $script:WinDriveLetter 'Windows'

            # Decide target directory based on extension/convention
            $targetDir = switch -Wildcard ($ext) {
                '.sys' { Join-Path $winRoot 'System32\drivers' }
                '.dll' { Join-Path $winRoot 'System32' }
                '.exe' { Join-Path $winRoot 'System32' }
                '.efi' {
                    # EFI binaries live on the boot partition
                    if ($fileName -ieq 'bootmgfw.efi') { Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot' }
                    elseif ($fileName -ieq 'bootx64.efi') { Join-Path $script:BootDriveLetter 'EFI\Boot' }
                    else { Join-Path $winRoot 'System32' }
                }
                default { Join-Path $winRoot 'System32' }
            }
            $targetPath = Join-Path $targetDir $fileName

            # Check current state
            $targetItem = Get-Item -LiteralPath $targetPath -Force -ErrorAction SilentlyContinue
            $targetExists = $null -ne $targetItem
            $targetIsDirectory = $targetExists -and $targetItem.PSIsContainer
            $targetSize = if ($targetExists -and -not $targetIsDirectory) { $targetItem.Length } else { 0 }
            $targetVersion = if ($targetExists -and -not $targetIsDirectory) { $targetItem.VersionInfo } else { $null }
            $targetPeInfo = $null
            $targetArchitectureMismatch = $false
            if ($targetExists -and -not $targetIsDirectory -and $targetSize -gt 0 -and
                $portableExecutableExtensions -contains $ext) {
                $targetPeInfo = Get-PortableExecutableInfo -FilePath $targetPath
                if ($guestArchitecture -ne 'Unknown' -and $targetPeInfo.IsPortableExecutable -and
                    $targetPeInfo.Architecture -ne 'Unknown') {
                    $targetArchitectureMismatch = -not (Test-PortableExecutableArchitectureCompatible `
                            -ExpectedArchitecture $guestArchitecture `
                            -ActualArchitecture $targetPeInfo.Architecture)
                }
            }

            $targetTrustFailed = $false
            $targetTrust = $null
            if ($targetExists -and -not $targetIsDirectory -and $targetSize -gt 0 -and
                $portableExecutableExtensions -contains $ext) {
                $targetTrust = Test-MicrosoftSignature -FilePath $targetPath
                $targetTrustFailed = [bool]$targetTrust.IsHardFailure
            }

            $isBroken = (-not $targetExists) -or $targetIsDirectory -or ($targetSize -eq 0) -or $targetArchitectureMismatch -or $targetTrustFailed
            if ($targetTrustFailed) {
                Write-Host "  Image trust: $(Get-TrustStateDescription -Signature $targetTrust)" -ForegroundColor Red
            }
            if ($targetExists -and ($targetIsDirectory -or $targetSize -gt 0)) {
                $currentSizeText = if ($targetIsDirectory) { 'directory' } else { "$targetSize bytes" }
                $currentArchitecture = if ($targetPeInfo -and $targetPeInfo.IsPortableExecutable) {
                    "$($targetPeInfo.Architecture) ($($targetPeInfo.Machine))"
                }
                else {
                    'not verified'
                }
                Write-Host "  $targetPath already exists ($currentSizeText, version: $($targetVersion.FileVersion), architecture: $currentArchitecture)" -ForegroundColor DarkGray
                if (-not (Confirm-CriticalOperation -Operation "Force replace existing system file ($fileName)" -Details @"
The target path already exists:
    $targetPath

Current state       : $currentSizeText
Current version     : $($targetVersion.FileVersion)
Current architecture: $currentArchitecture
Guest architecture : $guestArchitecture

The script will search WinSxS and DriverStore for a replacement candidate,
back up the existing target to a .replaced.bak file, copy the selected candidate
to the target path, verify its content and PE architecture when possible, and
apply a protected Windows system-file ACL/owner baseline.
"@)) {
                    Write-Host "  Skipped. Existing path was left unchanged." -ForegroundColor DarkGray
                    continue
                }
            }

            $stateDesc = if (-not $targetExists) {
                'MISSING'
            }
            elseif ($targetIsDirectory) {
                'directory where a file is required'
            }
            elseif ($targetSize -eq 0) {
                '0 bytes (corrupt)'
            }
            elseif ($targetArchitectureMismatch) {
                "$($targetPeInfo.Architecture) PE architecture mismatches $guestArchitecture guest"
            }
            elseif ($targetTrustFailed) {
                'FAILED IMAGE TRUST VALIDATION (STATUS_INVALID_IMAGE_HASH candidate)'
            }
            elseif ($isBroken) {
                'corrupt'
            }
            else {
                'present/non-zero (forced replacement)'
            }
            Write-Host "  Target: $targetPath [$stateDesc]" -ForegroundColor Yellow

            # -- 2. Search WinSxS and DriverStore for replacement candidates ------
            # Sources are indexed once for the whole batch (see
            # Get-SystemFileRepairSourceIndex) instead of re-walking WinSxS per file.
            $candidates = [System.Collections.Generic.List[PSCustomObject]]::new()
            $sourceIndex = Get-SystemFileRepairSourceIndex -FileNames $FileNames -WinRoot $winRoot -SourcePath $SourcePath
            $indexedSources = @()
            if ($sourceIndex.ContainsKey($fileName.ToLowerInvariant())) {
                $indexedSources = @($sourceIndex[$fileName.ToLowerInvariant()])
            }

            foreach ($src in $indexedSources) {
                $srcItem = Get-Item -LiteralPath $src.Path -Force -ErrorAction SilentlyContinue
                if (-not $srcItem -or $srcItem.Length -eq 0) { continue }
                # Skip \f\ and \r\ subdirectories - these contain forward/reverse
                # delta patches (not usable PE binaries).
                if ($src.Source -eq 'WinSxS' -and $srcItem.DirectoryName -match '\\(f|r)$') { continue }
                $ver = $srcItem.VersionInfo
                # Filter out delta stubs: no version info + under 1KB = not a real PE binary
                if ($src.Source -eq 'WinSxS' -and $srcItem.Length -lt 1024 -and -not $ver.FileVersion) { continue }
                $peInfo = Get-PortableExecutableInfo -FilePath $srcItem.FullName
                $candidates.Add([PSCustomObject]@{
                        Path       = $srcItem.FullName
                        Size       = $srcItem.Length
                        Version    = $ver.FileVersion
                        ProductVer = $ver.ProductVersion
                        Company    = $ver.CompanyName
                        LastWrite  = $srcItem.LastWriteTime
                        Source     = $src.Source
                        IsPortableExecutable = $peInfo.IsPortableExecutable
                        Architecture = $peInfo.Architecture
                        Machine      = $peInfo.Machine
                    })
            }

            # -- 2a. Discard candidates that are the target itself ----------------
            # Windows stores component files once and hard-links them into place, so
            # \WinSxS\<component>\<file> and the live path are usually two names for one
            # MFT record. When the live file was damaged in place, that "store copy" holds
            # the same damaged bytes; copying it back would repair nothing while reporting
            # success, and Copy-Item would in fact fail because it opens the one file for
            # reading and for writing at the same time.
            $hardLinkedCandidates = @()
            $targetIdentity = if ($targetExists -and -not $targetIsDirectory) { Get-FileIdentity -Path $targetPath } else { $null }
            if ($targetIdentity -and $candidates.Count -gt 0) {
                $distinctCandidates = [System.Collections.Generic.List[PSCustomObject]]::new()
                foreach ($cand in $candidates) {
                    $candIdentity = Get-FileIdentity -Path $cand.Path
                    if ($candIdentity -and $candIdentity.Id -eq $targetIdentity.Id) {
                        $hardLinkedCandidates += $cand
                    }
                    else {
                        $distinctCandidates.Add($cand)
                    }
                }
                if ($hardLinkedCandidates.Count -gt 0) {
                    Write-Warning "  Excluded $($hardLinkedCandidates.Count) candidate(s) that are hard links to the target itself, not separate copies:"
                    foreach ($hl in $hardLinkedCandidates) { Write-Warning "    $($hl.Path)" }
                    Write-Warning "  Target file ID $($targetIdentity.Id) has $($targetIdentity.LinkCount) hard link(s) on this volume."
                    $candidates = $distinctCandidates
                }
            }

            if ($candidates.Count -eq 0) {
                if ($hardLinkedCandidates.Count -gt 0) {
                    Write-Error "  No independent replacement source exists on this disk for '$fileName'."
                    Write-Warning "  Every copy found is a hard link to the damaged file, which is what Windows does for inbox files: the component store holds one instance and links it into place. A file damaged where it lies is therefore damaged in the store too."
                    Write-Warning "  \Windows\WinSxS\Backup is not an alternative: it holds reverse delta patches (DCS), not usable binaries."
                    Write-Warning "  Supply a known-good copy instead, taken from a machine running the same OS build and patch level, or extracted from matching installation media:"
                    Write-Warning "    -RepairSystemFile $fileName -RepairSystemFileSource <file-or-folder>"
                }
                else {
                    Write-Warning "  No replacement candidates found for '$fileName' in WinSxS or DriverStore."
                    Write-Warning "  The file may need to be copied from another VM with the same OS version, then supplied with -RepairSystemFileSource <file-or-folder>."
                }
                continue
            }

            $candidateSelection = if ($portableExecutableExtensions -contains $ext) {
                Select-SystemFileRepairCandidates `
                    -Candidates @($candidates) `
                    -ExpectedArchitecture $guestArchitecture
            }
            else {
                [pscustomobject]@{
                    Eligible               = @($candidates)
                    Matching               = @()
                    Unverified             = @()
                    Mismatched             = @()
                    UsedUnverifiedFallback = $false
                }
            }

            if ($candidateSelection.Mismatched.Count -gt 0) {
                $mismatchSummary = @(
                    $candidateSelection.Mismatched |
                    Group-Object Architecture |
                    ForEach-Object { "$($_.Name): $($_.Count)" }
                ) -join ', '
                Write-Warning "  Excluded $($candidateSelection.Mismatched.Count) known architecture-mismatched candidate(s) ($mismatchSummary)."
            }

            $eligibleCandidates = @($candidateSelection.Eligible)
            if ($eligibleCandidates.Count -eq 0) {
                Write-Warning "  No candidate matches the offline guest architecture ($guestArchitecture)."
                Write-Warning "  Do not use a binary from a different architecture. Use matching installation media or a same-build VM if the local stores are incomplete."
                continue
            }
            if ($candidateSelection.UsedUnverifiedFallback) {
                Write-Warning "  No architecture-verified candidate was available. Only candidates whose PE architecture could not be verified remain."
            }

            # Display eligible candidates
            Write-Host "  Found $($eligibleCandidates.Count) eligible candidate(s):" -ForegroundColor Green
            $eligibleCandidates | Sort-Object LastWrite -Descending |
            Format-Table @{L = 'Source'; E = { $_.Source } },
            @{L = 'Arch'; E = { if ($_.Architecture -eq 'Unknown') { '?' } else { $_.Architecture } } },
            @{L = 'Version'; E = { $_.Version } },
            @{L = 'Size'; E = { "{0:N0}" -f $_.Size } },
            @{L = 'Date'; E = { $_.LastWrite.ToString('yyyy-MM-dd HH:mm') } },
            @{L = 'Company'; E = { $_.Company } },
            @{L = 'Path'; E = { $_.Path } } -AutoSize

            # -- 3. Pick the best candidate ---------------------------------------
            # For driver (.sys) files, prefer the DriverStore FileRepository copy whose
            # INF package folder matches the driver name (e.g. netvsc.inf_*\netvsc.sys).
            # That copy is the version actually bound to the installed driver and is the
            # most reliable replacement - ahead of any superseded WinSxS component copy
            # that may merely be larger/newer. This matches the manual recovery pattern
            # used for Azure/Hyper-V synthetic drivers (netvsc.sys, storvsc.sys, vmbus.sys).
            # After that, prefer candidates with valid version info (real PE binaries),
            # then largest size (most complete), then newest date.
            # Files without version info are likely delta stubs or placeholders.
            $driverBaseName = [System.IO.Path]::GetFileNameWithoutExtension($fileName)
            $infMatchPattern = '\\' + [regex]::Escape($driverBaseName) + '\.inf_'

            # Reject sources that themselves fail image trust, and prefer sources whose
            # content is cryptographically provable. Restoring a corrupt WinSxS copy would
            # simply reproduce the STATUS_INVALID_IMAGE_HASH failure being repaired.
            $trustRanked = @()
            if ($portableExecutableExtensions -contains $ext) {
                foreach ($cand in $eligibleCandidates) {
                    $candSig = Test-MicrosoftSignature -FilePath $cand.Path
                    $candRank = switch ($candSig.TrustState) {
                        'ValidMicrosoft' { 0 }
                        'CatalogUnverified' { 1 }
                        'NotVerifiable' { 2 }
                        'ValidOtherPublisher' { 3 }
                        default { 9 }
                    }
                    Add-Member -InputObject $cand -NotePropertyName 'TrustState' -NotePropertyValue $candSig.TrustState -Force
                    Add-Member -InputObject $cand -NotePropertyName 'TrustBad' -NotePropertyValue ([bool]$candSig.IsHardFailure) -Force
                    Add-Member -InputObject $cand -NotePropertyName 'TrustRank' -NotePropertyValue ([int]$candRank) -Force
                }
                $trustRejected = @($eligibleCandidates | Where-Object { $_.TrustBad })
                if ($trustRejected.Count -gt 0) {
                    Write-Warning "  Discarded $($trustRejected.Count) replacement candidate(s) that failed image trust validation:"
                    foreach ($rej in $trustRejected) { Write-Warning "    $($rej.Path) [$($rej.TrustState)]" }
                }
                $trustRanked = @($eligibleCandidates | Where-Object { -not $_.TrustBad })
                if ($trustRanked.Count -eq 0) {
                    Write-Error "  Every replacement candidate for '$fileName' failed image trust validation. Refusing to install a known-bad binary."
                    Write-Warning "  The component store itself may be damaged. Copy the file from another VM with the same OS build, or run DISM /RestoreHealth online."
                    continue
                }
                $eligibleCandidates = $trustRanked
            }

            $best = $eligibleCandidates |
                Sort-Object @{Expression = {
                                if ($ext -eq '.sys' -and $_.Source -eq 'DriverStore' -and $_.Path -match $infMatchPattern) { 0 } else { 1 } } },
                            @{Expression = { if ($null -ne $_.TrustRank) { $_.TrustRank } else { 0 } } },
                            @{Expression = { if ($_.Version -and $_.Company) { 0 } else { 1 } } },
                            @{Expression = 'Size'; Descending = $true },
                            @{Expression = 'LastWrite'; Descending = $true } |
                Select-Object -First 1

            if ($ext -eq '.sys' -and $best.Source -eq 'DriverStore' -and $best.Path -match $infMatchPattern) {
                Write-Host "  Preferring DriverStore INF-matched driver package copy ($driverBaseName.inf_*)." -ForegroundColor DarkGray
            }

            Write-Host "  Selected: $($best.Path)" -ForegroundColor Cyan
            Write-Host "    Architecture: $($best.Architecture) $($best.Machine)  |  Version: $($best.Version)  |  Size: $("{0:N0}" -f $best.Size) bytes" -ForegroundColor White
            Write-Host "    Date: $($best.LastWrite.ToString('yyyy-MM-dd HH:mm'))  |  Company: $($best.Company)" -ForegroundColor White

            # Verify it's a Microsoft binary (safety check)
            if ($best.Company -and $best.Company -notmatch 'Microsoft') {
                Write-Warning "  Selected binary is not from Microsoft (Company: '$($best.Company)')."
                Write-Warning "  Proceeding anyway - verify the replacement is correct."
            }

            # -- 4/5. Install the replacement -------------------------------------
            # Everything that makes writing to an offline guest disk hard - the
            # TrustedInstaller ownership, the backup, the hard-link guard, the hash
            # check, replaying the file's original descriptor and rolling back a bad
            # copy - lives in Install-ProtectedSystemFile, so every caller in this
            # script behaves identically. Only the checks specific to a Windows system
            # binary are supplied here, as a validation block that rejects the copy by
            # throwing.
            $backupSuffix = if ($targetExists -and $targetSize -eq 0 -and -not $targetIsDirectory) { '.broken.bak' } else { '.replaced.bak' }

            $validateReplacement = {
                param($installedPath)

                if ($portableExecutableExtensions -notcontains $ext) { return }

                $replacementPeInfo = Get-PortableExecutableInfo -FilePath $installedPath
                if ($replacementPeInfo.IsPortableExecutable -and $replacementPeInfo.Architecture -ne 'Unknown') {
                    if ($guestArchitecture -ne 'Unknown' -and
                        -not (Test-PortableExecutableArchitectureCompatible `
                                -ExpectedArchitecture $guestArchitecture `
                                -ActualArchitecture $replacementPeInfo.Architecture)) {
                        throw "Replacement PE architecture $($replacementPeInfo.Architecture) ($($replacementPeInfo.Machine)) does not match guest architecture $guestArchitecture."
                    }
                    Write-Host "  [OK] Replacement PE architecture: $($replacementPeInfo.Architecture) ($($replacementPeInfo.Machine))." -ForegroundColor Green
                }
                else {
                    Write-Warning "  The copied file's PE architecture could not be verified: $($replacementPeInfo.Error)"
                }

                # Re-verify trust at the destination. This is the check that proves the
                # repair actually cleared STATUS_INVALID_IMAGE_HASH rather than moving it.
                $postSig = Test-MicrosoftSignature -FilePath $installedPath
                if ($postSig.IsHardFailure) {
                    throw "Replacement still fails image trust validation at the destination - $(Get-TrustStateDescription -Signature $postSig)."
                }
                switch ($postSig.TrustState) {
                    'ValidMicrosoft' { Write-Host "  [OK] Image trust verified: $(Get-TrustStateDescription -Signature $postSig)." -ForegroundColor Green }
                    'CatalogUnverified' { Write-Host "  [i] Image trust could not be proven offline (no usable guest catalog store); PE and hash checks passed." -ForegroundColor DarkGray }
                    default { Write-Host "  [i] Image trust after replacement: $(Get-TrustStateDescription -Signature $postSig)." -ForegroundColor DarkGray }
                }
            }

            $install = Install-ProtectedSystemFile `
                -Source $best.Path `
                -Destination $targetPath `
                -BackupSuffix $backupSuffix `
                -PostCopyValidation $validateReplacement `
                -Description "system file '$fileName'"

            if (-not $install.Installed) {
                Write-Error "  '$fileName' was not replaced: $($install.Reason)"
                Write-ActionLog -Event 'SystemFileReplacementFailed' -Details @{
                    FileName   = $fileName
                    TargetPath = $targetPath
                    SourcePath = $best.Path
                    RolledBack = $install.RolledBack
                    Reason     = $install.Reason
                }
                continue
            }

            Write-ActionLog -Event 'SystemFileAclRestored' -Details @{
                FileName   = $fileName
                TargetPath = $targetPath
                SourcePath = $best.Path
                AclSource  = $install.AclSource
            }

            $newSize = (Get-Item -LiteralPath $targetPath).Length
            Write-Host "  [OK] Replaced: $targetPath ($("{0:N0}" -f $newSize) bytes)" -ForegroundColor Green
            if ($install.BackupPath) {
                Write-Host "  Backup: $($install.BackupPath)" -ForegroundColor DarkGray
            }

            Write-ActionLog -Event 'SystemFileReplaced' -Details @{
                FileName              = $fileName
                TargetPath            = $targetPath
                SourcePath            = $best.Path
                Source                = $best.Source
                Version               = $best.Version
                Size                  = $best.Size
                Company               = $best.Company
                Sha256                = $install.Hash
                BackupPath            = $install.BackupPath
                AclSource             = $install.AclSource
                GuestArchitecture     = $guestArchitecture
                CandidateArchitecture = $best.Architecture
                CandidateMachine      = $best.Machine
                PreviousState         = $stateDesc
            }
        }
    }

    function Get-SyntheticDriverSpec {
        @(
            @{ Name = 'vmbus'; Start = 0; Bin = 'vmbus.sys'; Desc = 'Hyper-V VMBus'; Severity = 2 }
            @{ Name = 'storvsc'; Start = 0; Bin = 'storvsc.sys'; Desc = 'Hyper-V StorVSC (synthetic storage)'; Severity = 2 }
            @{ Name = 'netvsc'; Start = 3; Bin = 'netvsc.sys'; AlternateBinPatterns = @('netvsc*.sys'); Desc = 'Hyper-V NetVSC (synthetic network)'; Severity = 1 }
        )
    }

    function AnalyzeSyntheticDrivers {
        Write-Host "Analyzing Azure/Hyper-V synthetic driver readiness..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM' {
            $sysRoot = Get-SystemRootPath
            $rows = foreach ($d in (Get-SyntheticDriverSpec)) {
                $svcPath = "$sysRoot\Services\$($d.Name)"
                $exists = Test-Path $svcPath
                $start = if ($exists) { (Get-ItemProperty $svcPath -ErrorAction SilentlyContinue).Start } else { $null }
                $bin = Resolve-DriverBinaryCandidate -Binary $d.Bin -AlternatePatterns $d.AlternateBinPatterns
                [PSCustomObject]@{
                    Driver       = $d.Name
                    Expected     = $d.Start
                    CurrentStart = if ($null -ne $start) { $start } else { 'MissingKey' }
                    Binary       = if ($bin.Exists) { $bin.Name } else { $d.Bin }
                    BinaryExists = $bin.Exists
                    Healthy      = ($exists -and $bin.Exists -and $bin.Size -gt 0 -and [int]$start -eq [int]$d.Start)
                    Notes        = if ($bin.IsAlternate) { "$($d.Desc); using $($bin.Name)" } else { $d.Desc }
                }
            }
            $rows | Format-Table -AutoSize
            $bad = @($rows | Where-Object { -not $_.Healthy })
            if ($bad.Count -gt 0) {
                Write-Warning "One or more synthetic drivers are not healthy. Use -EnsureSyntheticDriversEnabled for wrong Start values, -RepairSystemFile <driver.sys> for missing/0-byte binaries, or restore missing service keys from a matching Windows image or registry backup."
            }
            else {
                Write-Host "Synthetic driver checks look healthy." -ForegroundColor Green
            }
        }
    }

    function EnsureSyntheticDriversEnabled {
        if (-not (Confirm-CriticalOperation -Operation 'Enable Azure synthetic drivers (-EnsureSyntheticDriversEnabled)' -Details @"
Sets Start values for core Hyper-V synthetic drivers when service key and binary are present:
    vmbus=0, storvsc=0, netvsc=3
Skips entries if service key or driver binary is missing.
"@)) { return }

        Invoke-WithHive 'SYSTEM' {
            $sysRoot = Get-SystemRootPath
            foreach ($d in (Get-SyntheticDriverSpec)) {
                $svcPath = "$sysRoot\Services\$($d.Name)"
                $bin = Resolve-DriverBinaryCandidate -Binary $d.Bin -AlternatePatterns $d.AlternateBinPatterns
                if (-not (Test-Path $svcPath)) {
                    Write-Host "  $($d.Name): service key missing, skipped." -ForegroundColor Yellow
                    continue
                }
                if (-not $bin.Exists -or $bin.Size -eq 0) {
                    Write-Host "  $($d.Name): binary missing or 0 bytes ($($d.Bin)), skipped." -ForegroundColor Yellow
                    continue
                }
                $cur = (Get-ItemProperty $svcPath -ErrorAction SilentlyContinue).Start
                if ($null -ne $cur -and [int]$cur -eq [int]$d.Start) {
                    Write-Host "  $($d.Name): already Start=$cur" -ForegroundColor DarkGray
                }
                else {
                    Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $d.Start -Type DWord -Force
                    Write-Host "  $($d.Name): Start set to $($d.Start)" -ForegroundColor Green
                }
            }
        }
    }

    function FixBootStorageDrivers {
        if (-not (Confirm-CriticalOperation -Operation 'Repair boot storage driver readiness (-FixBootStorageDrivers)' -Details @"
Checks the active offline ControlSet for migration boot-storage settings that can block disk enumeration.
Only unexpected values are changed:
    - boot bus/storage service Start values are set to 0 when the service key exists
    - StartOverride entries are changed only for drivers with an explicit expected override value
    - Hyper-V synthetic boot path StartOverride values are expected to be 0
    - optional IDE/AHCI StartOverride values are expected to be 3 on healthy Windows images
    - missing required inbox boot-storage service keys are recreated only when the Microsoft driver binary exists on disk
"@)) { return }

        Invoke-WithHive 'SYSTEM' {
            $csName = Get-CurrentOfflineControlSetName
            if (-not (Test-Path "HKLM:\BROKENSYSTEM\$csName")) {
                Write-Warning "Active offline ControlSet path was not found: HKLM:\BROKENSYSTEM\$csName"
                return
            }
            $controlSets = [string[]]@($csName)

            $changes = 0
            $created = [System.Collections.Generic.List[string]]::new()
            $missing = [System.Collections.Generic.List[string]]::new()

            foreach ($csName in $controlSets) {
                Write-Host "  Checking $csName..." -ForegroundColor Cyan
                $svcRoot = "HKLM:\BROKENSYSTEM\$csName\Services"
                foreach ($spec in (Get-BootStorageDriverSpec)) {
                    $svcPath = "$svcRoot\$($spec.Name)"
                    if (-not (Test-Path $svcPath)) {
                        if ($spec.Required) {
                            $createdKey = New-BootStorageServiceKey -ControlSetName $csName -Spec $spec
                            if ($createdKey) {
                                $created.Add("$csName\Services\$($spec.Name)")
                                $changes++
                            }
                            else {
                                $missing.Add("$csName\Services\$($spec.Name)")
                            }
                        }
                        continue
                    }

                    $props = Get-ItemProperty $svcPath -ErrorAction SilentlyContinue
                    if ($null -eq $props.Start -or [int]$props.Start -notin @($spec.AllowedStarts)) {
                        Write-Host "    $($spec.Name) Start: $($props.Start) -> $($spec.Start)" -ForegroundColor Yellow
                        Set-ItemProperty-Logged -Path $svcPath -Name Start -Value $spec.Start -Type DWord -Force
                        $changes++
                    }

                    if ($spec.CheckStartOverride -and $null -ne $spec.ExpectedStartOverride) {
                        $expectedStartOverride = [int]$spec.ExpectedStartOverride
                        $overridePath = "$svcPath\StartOverride"
                        if (Test-Path $overridePath) {
                            $overrideProps = Get-ItemProperty $overridePath -ErrorAction SilentlyContinue
                            foreach ($prop in @($overrideProps.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' })) {
                                if ($null -eq $prop.Value) { continue }
                                if ([int]$prop.Value -ne $expectedStartOverride) {
                                    Write-Host "    $($spec.Name) StartOverride\$($prop.Name): $($prop.Value) -> $expectedStartOverride" -ForegroundColor Yellow
                                    Set-ItemProperty-Logged -Path $overridePath -Name $prop.Name -Value $expectedStartOverride -Type DWord -Force
                                    $changes++
                                }
                            }
                        }
                    }
                }
            }

            if ($missing.Count -gt 0) {
                Write-Warning "Required boot-storage service keys are still missing or were not safe to recreate: $($missing -join ', ')"
            }
            if ($created.Count -gt 0) {
                Write-Host "Created missing boot-storage service key(s): $($created -join ', ')" -ForegroundColor Green
            }
            if ($changes -eq 0) {
                Write-Host 'No unexpected boot storage driver settings were found. No registry values changed.' -ForegroundColor Green
            }
            else {
                Write-Host "Boot storage driver readiness repair complete. Registry values changed: $changes" -ForegroundColor Green
            }

            Write-ActionLog -Event 'FixBootStorageDrivers' -Details @{ ControlSets = ($controlSets -join ', '); Changes = $changes; CreatedServiceKeys = ($created -join ', '); MissingRequiredKeys = ($missing -join ', ') }
        }
    }

    function ResetInterfacesToDHCP {
        if (-not (Confirm-CriticalOperation -Operation 'Reset interfaces to DHCP (-ResetInterfacesToDHCP)' -Details @"
For all offline NIC interface keys under Tcpip\Parameters\Interfaces:
  - sets EnableDHCP=1
  - removes static IPv4 and static DNS fields (IPAddress, SubnetMask, DefaultGateway, NameServer)
Use this for migrated/cloned VMs stuck with stale static networking.
"@)) { return }

        Invoke-WithHive 'SYSTEM' {
            $sysRoot = Get-SystemRootPath
            $ifRoot = "$sysRoot\Services\Tcpip\Parameters\Interfaces"
            if (-not (Test-Path $ifRoot)) {
                Write-Warning "Interfaces key not found: $ifRoot"
                return
            }
            $changed = 0
            $propsToClear = @('IPAddress', 'SubnetMask', 'DefaultGateway', 'DefaultGatewayMetric', 'NameServer')
            foreach ($if in (Get-ChildItem $ifRoot -ErrorAction SilentlyContinue)) {
                $ifPath = $if.PSPath
                Set-ItemProperty-Logged -Path $ifPath -Name EnableDHCP -Value 1 -Type DWord -Force
                $changed++
                $pnames = (Get-ItemProperty $ifPath -ErrorAction SilentlyContinue).PSObject.Properties.Name
                foreach ($pn in $propsToClear) {
                    if ($pnames -contains $pn) {
                        Remove-ItemProperty-Logged -Path $ifPath -Name $pn
                    }
                }
            }
            Write-Host "Reset DHCP/static settings on $changed interface key(s)." -ForegroundColor Green
        }
    }

    function AnalyzeProxyState {
        Write-Host "Analyzing machine proxy/PAC state..." -ForegroundColor Yellow
        Invoke-WithHive 'SOFTWARE' {
            $paths = @(
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings'
                'HKLM:\BROKENSOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Internet Settings'
            )
            $rows = foreach ($p in $paths) {
                if (-not (Test-Path $p)) { continue }
                $r = Get-ItemProperty $p -ErrorAction SilentlyContinue
                [PSCustomObject]@{
                    Key           = $p
                    ProxyEnable   = $r.ProxyEnable
                    ProxyServer   = $r.ProxyServer
                    AutoConfigURL = $r.AutoConfigURL
                    AutoDetect    = $r.AutoDetect
                }
            }
            if (-not $rows) {
                Write-Host "No proxy keys found." -ForegroundColor DarkGray
                return
            }
            $rows | Format-Table -AutoSize
            if (@($rows | Where-Object { $_.ProxyEnable -eq 1 -or $_.ProxyServer -or $_.AutoConfigURL }).Count -gt 0) {
                Write-Warning "Proxy/PAC settings detected. If remote access is blocked, consider -ClearProxyState."
            }
        }
    }

    function ClearProxyState {
        if (-not (Confirm-CriticalOperation -Operation 'Clear machine proxy state (-ClearProxyState)' -Details @"
Clears ProxyServer/ProxyOverride/AutoConfigURL and sets ProxyEnable=0 in machine Internet Settings.
Use this when stale proxy/PAC settings prevent WinRM/RDP reachability after migration.
"@)) { return }

        Invoke-WithHive 'SOFTWARE' {
            $paths = @(
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings'
                'HKLM:\BROKENSOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Internet Settings'
            )
            foreach ($p in $paths) {
                if (-not (Test-Path $p)) { continue }
                Set-ItemProperty-Logged -Path $p -Name ProxyEnable -Value 0 -Type DWord -Force
                $pnames = (Get-ItemProperty $p -ErrorAction SilentlyContinue).PSObject.Properties.Name
                foreach ($pn in @('ProxyServer', 'ProxyOverride', 'AutoConfigURL')) {
                    if ($pnames -contains $pn) { Remove-ItemProperty-Logged -Path $p -Name $pn }
                }
                Write-Host "  Cleared proxy settings in $p" -ForegroundColor Green
            }
        }
    }

    function GetBootPathReport {
        <#
        .SYNOPSIS
            Boot Path Health Check  -  traces the full Windows boot chain on the offline disk
            and validates every artifact (file, registry key, driver, service) in load order.

            Phases:
                1  Pre-Boot (BIOS/UEFI firmware + MBR/GPT partition table)
                2  Boot Manager (bootmgr/bootmgfw.efi -> BCD store)
                3  OS Loader (winload.exe/.efi -> kernel, HAL, SYSTEM hive, boot-start drivers)
                4  NTOS Kernel Init (Session Manager, Csrss, Wininit, Services.exe, boot/system drivers)
                5  Logon & Desktop (Winlogon, LogonUI, Lsass, Userinit, Explorer shell)

            For each artifact the report shows:
                * Load order position within its phase
                * Expected file path on the offline disk
                * Exists / Missing / 0-byte status
                * File size and Microsoft signature verification
                * Registry configuration that references it (when applicable)
                * Health verdict:  OK / WARN / FAIL
        #>

        #region -- colour / symbol helpers ----------------------------------------
        $symOK    = [char]0x2714   # check mark
        $symFAIL  = [char]0x2718   # X mark
        $symWARN  = [char]0x26A0   # warning sign
        $symINFO  = [char]0x2139   # info
        $symARROW = [char]0x25B6   # right-pointing triangle
        $symCHAIN = [char]0x2502   # vertical line for chain visual
        $symLINK  = [char]0x251C   # tee connector
        $symEND   = [char]0x2514   # corner connector
        $symEQ    = [char]0x2550   # double horizontal line
        $symVert  = [char]0x2551   # double vertical line
        $symTL    = [char]0x2554   # top-left corner
        $symBL    = [char]0x255A   # bottom-left corner

        function Write-Phase {
            param([int]$Number, [string]$Title, [string]$Description)
            $bar = "  $symTL$("$symEQ" * 76)"
            $end = "  $symBL$("$symEQ" * 76)"
            Write-Host ""
            Write-Host $bar -ForegroundColor DarkCyan
            Write-Host "  $symVert  PHASE $Number - $Title" -ForegroundColor Cyan
            Write-Host "  $symVert  $Description" -ForegroundColor DarkGray
            Write-Host $end -ForegroundColor DarkCyan
        }

        function Write-ChainItem {
            param(
                [string]$Label,
                [string]$Status,        # OK, WARN, FAIL, INFO
                [string]$Detail = '',
                [switch]$IsLast
            )
            $connector = if ($IsLast) { $symEND } else { $symLINK }
            switch ($Status) {
                'OK'   { $icon = $symOK;   $col = 'Green'  }
                'WARN' { $icon = $symWARN; $col = 'Yellow' }
                'FAIL' { $icon = $symFAIL; $col = 'Red'    }
                'INFO' { $icon = $symINFO; $col = 'DarkGray' }
                default { $icon = $symARROW; $col = 'White' }
            }
            Write-Host "  $symCHAIN" -ForegroundColor DarkGray -NoNewline
            Write-Host "  $connector " -ForegroundColor DarkGray -NoNewline
            Write-Host "$icon " -ForegroundColor $col -NoNewline
            Write-Host "$Label" -ForegroundColor White -NoNewline
            if ($Detail) { Write-Host "  $Detail" -ForegroundColor DarkGray }
            else { Write-Host "" }
        }

        function Test-BootFile {
            param([string]$Path, [string]$Label, [switch]$SkipSignature)
            $obj = [PSCustomObject]@{
                Label     = $Label
                Path      = $Path
                Exists    = $false
                Size      = 0
                SizeStr   = ''
                SigStatus = ''
                IsMicrosoft = $false
                TrustState = ''
                Health    = 'FAIL'
                Detail    = ''
            }
            if (-not $Path -or -not (Test-Path -LiteralPath $Path)) {
                $obj.Detail = "MISSING  -  $Path"
                return $obj
            }
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
            $obj.Exists = $true
            $obj.Size = if ($item) { $item.Length } else { 0 }
            $obj.SizeStr = '{0:N0}' -f $obj.Size

            if ($obj.Size -eq 0) {
                $obj.Health = 'FAIL'
                $obj.Detail = "0 BYTES (corrupt)  -  $Path"
                return $obj
            }

            if (-not $SkipSignature) {
                $sig = Test-MicrosoftSignature -FilePath $Path
                $obj.SigStatus = $sig.Status
                $obj.IsMicrosoft = $sig.IsMicrosoft
                $obj.TrustState = $sig.TrustState
                if ($sig.IsHardFailure) {
                    $obj.Health = 'FAIL'
                    $obj.Detail = "IMAGE TRUST FAILURE  -  $(Get-TrustStateDescription -Signature $sig)  -  $Path ($($obj.SizeStr) bytes)"
                    return $obj
                }
                elseif ($sig.TrustState -eq 'ValidOtherPublisher') {
                    $obj.Health = 'WARN'
                    $obj.Detail = "Signed by '$($sig.SignerSubject)' (not Microsoft)  -  $Path ($($obj.SizeStr) bytes)"
                    return $obj
                }
                elseif (-not $sig.IsAcceptableMicrosoft) {
                    $obj.Health = 'WARN'
                    $obj.Detail = "$(Get-TrustStateDescription -Signature $sig)  -  $Path ($($obj.SizeStr) bytes)"
                    return $obj
                }
                elseif ($sig.TrustState -eq 'CatalogUnverified') {
                    $obj.Health = 'OK'
                    $obj.Detail = "$Path ($($obj.SizeStr) bytes, trust unverified offline)"
                    return $obj
                }
            }

            $obj.Health = 'OK'
            $obj.Detail = "$Path ($($obj.SizeStr) bytes)"
            return $obj
        }
        #endregion

        # Accumulate issues for the summary
        $issues = [System.Collections.Generic.List[PSCustomObject]]::new()
        $totalChecks = 0

        Write-Host ""
        Write-Host "  $("$symEQ" * 76)" -ForegroundColor Cyan
        Write-Host "                     WINDOWS BOOT PATH HEALTH CHECK" -ForegroundColor White
        Write-Host "  $("$symEQ" * 76)" -ForegroundColor Cyan
        $genLabel = if ($script:VMGen -eq 2) { 'Generation 2 (UEFI / GPT)' } else { 'Generation 1 (BIOS / MBR)' }
        Write-Host "  VM Generation  : $genLabel" -ForegroundColor DarkGray
        Write-Host "  Windows Drive  : $($script:WinDriveLetter)" -ForegroundColor DarkGray
        Write-Host "  Boot Drive     : $($script:BootDriveLetter)" -ForegroundColor DarkGray

        #region ===================================================================
        # PHASE 1  -  PRE-BOOT: Partition Table & Disk Layout
        #=========================================================================
        Write-Phase 1 'PRE-BOOT' 'Firmware POST -> partition table -> identify boot partition'

        $disk = Get-Disk -Number $script:DiskNumber -ErrorAction SilentlyContinue
        $partStyle = if ($disk) { $disk.PartitionStyle } else { 'Unknown' }
        Write-ChainItem -Label "Partition style: $partStyle" -Status 'INFO'

        $partitions = Get-Partition -DiskNumber $script:DiskNumber -ErrorAction SilentlyContinue
        $bootPartFound = $false
        $winPartFound = $false

        foreach ($part in $partitions) {
            $access = ($part.AccessPaths | Where-Object { $_ -match '^[A-Z]:\\$' }) | Select-Object -First 1
            if (-not $access) { continue }
            $accessClean = $access.TrimEnd('\')

            $isBootPart = ($accessClean -eq $script:BootDriveLetter.TrimEnd('\'))
            $isWinPart  = ($accessClean -eq $script:WinDriveLetter.TrimEnd('\'))

            $roles = @()
            if ($isBootPart) { $roles += 'BOOT'; $bootPartFound = $true }
            if ($isWinPart)  { $roles += 'WINDOWS'; $winPartFound = $true }
            if ($roles.Count -eq 0) { continue }

            $roleStr = $roles -join ' + '
            $sizeGB  = '{0:N2} GB' -f ($part.Size / 1GB)

            # Boot partition health checks
            if ($isBootPart) {
                if ($script:VMGen -eq 1) {
                    $actStatus = if ($part.IsActive) { 'OK' } else { 'FAIL' }
                    Write-ChainItem -Label "Partition $($part.PartitionNumber) [$roleStr]  -  $sizeGB" -Status $actStatus -Detail $(if ($part.IsActive) { '(Active flag set)' } else { 'Active flag NOT set  -  firmware cannot find this partition' })
                    if (-not $part.IsActive) {
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 1; Severity = 'FAIL'; Message = "Boot partition $($part.PartitionNumber) missing Active flag"; Fix = '-FixBoot' })
                    }
                }
                else {
                    $typeLabel = if ($part.GptType -eq '{c12a7328-f81f-11d2-ba4b-00a0c93ec93b}') { 'EFI System Partition' } else { $part.GptType }
                    Write-ChainItem -Label "Partition $($part.PartitionNumber) [$roleStr]  -  $sizeGB  -  $typeLabel" -Status 'OK'
                }
            }
            if ($isWinPart -and -not $isBootPart) {
                Write-ChainItem -Label "Partition $($part.PartitionNumber) [$roleStr]  -  $sizeGB" -Status 'OK'
            }
        }

        if (-not $bootPartFound) {
            Write-ChainItem -Label 'Boot partition' -Status 'FAIL' -Detail 'NOT FOUND  -  firmware has no partition to start from' -IsLast
            $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 1; Severity = 'FAIL'; Message = 'No boot partition found'; Fix = '-RecreateBootPartition' })
        }
        if (-not $winPartFound) {
            Write-ChainItem -Label 'Windows partition' -Status 'FAIL' -Detail 'NOT FOUND  -  no partition contains Windows\System32' -IsLast
            $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 1; Severity = 'FAIL'; Message = 'No Windows partition found'; Fix = '' })
        }
        $totalChecks += 2  # boot + win partition

        #endregion

        #region ===================================================================
        # PHASE 2  -  BOOT MANAGER: bootmgr / BCD Store
        #=========================================================================
        Write-Phase 2 'BOOT MANAGER' 'Firmware loads boot manager -> reads BCD -> selects OS entry'

        # 2a. Boot manager binary
        $bootMgrFiles = @()
        if ($script:VMGen -eq 1) {
            $bootMgrFiles += @{ Label = 'bootmgr'; Path = (Join-Path $script:BootDriveLetter 'bootmgr') }
        }
        else {
            $bootMgrFiles += @{ Label = 'bootmgfw.efi'; Path = (Join-Path $script:BootDriveLetter 'EFI\Microsoft\Boot\bootmgfw.efi') }
            $bootMgrFiles += @{ Label = 'bootx64.efi (fallback)'; Path = (Join-Path $script:BootDriveLetter 'EFI\Boot\bootx64.efi') }
        }
        foreach ($bmf in $bootMgrFiles) {
            $r = Test-BootFile -Path $bmf.Path -Label $bmf.Label
            Write-ChainItem -Label "$($bmf.Label)" -Status $r.Health -Detail $r.Detail
            $totalChecks++
            if ($r.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 2; Severity = $r.Health; Message = "$($bmf.Label): $($r.Detail)"; Fix = '-FixBoot' }) }
        }

        # 2b. BCD store
        $bcdStore = Get-BcdStorePath -BootDrive $script:BootDriveLetter -Generation $script:VMGen
        $bcdResult = Test-BootFile -Path $bcdStore -Label 'BCD store' -SkipSignature
        Write-ChainItem -Label "BCD store" -Status $bcdResult.Health -Detail $bcdResult.Detail
        $totalChecks++
        if ($bcdResult.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 2; Severity = $bcdResult.Health; Message = "BCD store: $($bcdResult.Detail)"; Fix = '-FixBoot' }) }
        if ($script:WindowsInstallCandidates.Count -gt 0) {
            $selectedInstall = @($script:WindowsInstallCandidates | Where-Object { $_.Selected } | Select-Object -First 1)
            if (-not $selectedInstall) {
                $selectedInstall = @($script:WindowsInstallCandidates | Select-Object -First 1)
            }
            if ($selectedInstall) {
                $selected = $selectedInstall[0]
                $buildLabel = Format-WindowsBuildLabel -Build $selected.CurrentBuildNumber -Ubr $selected.UBR -Fallback 'unknown'
                Write-ChainItem -Label "Selected Windows install: $($selected.Drive) ($($selected.ProductName), build $buildLabel, score=$($selected.Score))" -Status 'INFO'
                if ($selected.SetupEvidence) {
                    Write-ChainItem -Label 'Selected install has setup markers' -Status 'WARN' -Detail $selected.SetupEvidence
                    $totalChecks++
                    $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "Selected Windows install still has setup/upgrade markers: $($selected.SetupEvidence)"; Fix = '-AnalyzeServicingState' })
                }
            }
            if ($script:WindowsInstallCandidates.Count -gt 1) {
                $candidateSummary = ($script:WindowsInstallCandidates | ForEach-Object { "$($_.Drive) score=$($_.Score)" }) -join '; '
                Write-ChainItem -Label 'Multiple Windows installs detected' -Status 'WARN' -Detail $candidateSummary
                $totalChecks++
                $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "Multiple Windows installs detected: $candidateSummary"; Fix = '-FixBoot' })
            }
        }

        # 2c. Parse BCD entries if store exists
        $bcdWinloadPath = $null
        $bcdSystemRoot = '\Windows'
        $bcdFlags = @()
        if ($bcdResult.Exists -and $bcdResult.Size -gt 0) {
            try {
                $bcdInventory = Get-BcdInventory -StorePath $bcdStore
                $bcdText = $bcdInventory.RawText

                # Boot Manager section
                $bmgrTimeout = if ($bcdText -match '(?im)timeout\s+(\d+)') { $Matches[1] + 's' } else { 'default' }
                Write-ChainItem -Label "BCD timeout: $bmgrTimeout" -Status 'INFO'

                # Extract Boot Manager section and validate its path
                $bmgrSection = ''
                $allSections = $bcdText -split '(?m)^-{3,}'
                foreach ($sec in $allSections) {
                    if ($sec -match 'bootmgr|Windows Boot Manager') {
                        $bmgrSection = $sec
                        break
                    }
                }
                if ($bmgrSection) {
                    $bmgrPath = if ($bmgrSection -match '(?im)^\s*path\s+(.+)$') { $Matches[1].Trim() } else { '' }
                    if ($bmgrPath) {
                        $expectedBmgr = if ($script:VMGen -eq 2) { '\EFI\Microsoft\Boot\bootmgfw.efi' } else { '\bootmgr' }
                        Write-ChainItem -Label "Boot Manager path : $bmgrPath" -Status 'INFO'
                        if (-not [string]::Equals($bmgrPath, $expectedBmgr, [System.StringComparison]::OrdinalIgnoreCase)) {
                            Write-ChainItem -Label "Boot Manager path mismatch" -Status 'WARN' -Detail "Expected '$expectedBmgr', found '$bmgrPath'"
                            $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "Boot Manager path is '$bmgrPath' (expected '$expectedBmgr')"; Fix = '-FixBoot' })
                        }
                    }
                }

                # Windows Boot Loader section
                if (@($bcdInventory.Loaders).Count -eq 0) {
                    Write-ChainItem -Label 'Windows Boot Loader entry' -Status 'FAIL' -Detail 'No osloader/Windows Boot Loader entry found in BCD'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'FAIL'; Message = 'No Windows Boot Loader entry in BCD'; Fix = '-FixBoot' })
                }
                else {
                    $preferredLoaderId = Get-BcdBootLoaderId -StorePath $bcdStore
                    $preferredLoader = $null
                    if ($preferredLoaderId) {
                        $preferredLoader = Get-BcdLoaderDetails -StorePath $bcdStore -Identifier $preferredLoaderId
                    }
                    if (-not $preferredLoader) {
                        $fallbackLoader = @($bcdInventory.Loaders | Select-Object -First 1)
                        if ($fallbackLoader) {
                            $preferredLoader = Get-BcdLoaderDetails -StorePath $bcdStore -Identifier $fallbackLoader[0].Identifier
                            if (-not $preferredLoader) {
                                $preferredLoader = $fallbackLoader[0]
                            }
                        }
                    }
                    Write-ChainItem -Label 'Windows Boot Loader entry present' -Status 'OK'
                    if (@($bcdInventory.Loaders).Count -gt 1) {
                        $loaderSummary = ($bcdInventory.Loaders | ForEach-Object {
                            $desc = if ($_.Description) { $_.Description } else { $_.Identifier }
                            if ($_.PartitionDrive) { "$desc@$($_.PartitionDrive)" } else { $desc }
                        }) -join '; '
                        Write-ChainItem -Label 'Multiple Windows Boot Loader entries found' -Status 'WARN' -Detail $loaderSummary
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "Multiple Windows Boot Loader entries found: $loaderSummary"; Fix = '-FixBoot' })
                    }
                    $setupLoaders = @($bcdInventory.Loaders | Where-Object { $_.IsSetupEntry })
                    if ($setupLoaders.Count -gt 0) {
                        $setupSummary = ($setupLoaders | ForEach-Object { if ($_.Description) { $_.Description } else { $_.Identifier } }) -join '; '
                        Write-ChainItem -Label 'BCD setup/stale loader entries found' -Status 'WARN' -Detail $setupSummary
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "BCD contains setup/stale loader entries: $setupSummary"; Fix = '-FixBoot' })
                    }

                    $bcdDevice = $preferredLoader.Device
                    $bcdOsDevice = $preferredLoader.OsDevice
                    $bcdPath = $preferredLoader.Path
                    $bcdSysRoot = if ($preferredLoader.SystemRoot) { $preferredLoader.SystemRoot } else { '\Windows' }
                    $bcdNx = if ($bcdText -match '(?im)^\s*nx\s+(.+)$') { $Matches[1].Trim() } else { '' }

                    $bcdWinloadPath = $bcdPath
                    $bcdSystemRoot = $bcdSysRoot

                    Write-ChainItem -Label "device     : $bcdDevice" -Status 'INFO'
                    Write-ChainItem -Label "osdevice   : $bcdOsDevice" -Status 'INFO'
                    Write-ChainItem -Label "path       : $bcdPath" -Status 'INFO'
                    Write-ChainItem -Label "systemroot : $bcdSysRoot" -Status 'INFO'
                    if ($bcdNx) { Write-ChainItem -Label "nx         : $bcdNx" -Status 'INFO' }

                    # Device pointing to unknown
                    if ($bcdDevice -match '\bunknown\b' -or $bcdOsDevice -match '\bunknown\b') {
                        Write-ChainItem -Label 'BCD device references UNKNOWN partition' -Status 'FAIL' -Detail 'device/osdevice points to missing or wrong partition'
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'FAIL'; Message = 'BCD device/osdevice references unknown partition'; Fix = '-FixBoot' })
                    }

                    # Path mismatch for Gen
                    $expectedLoader = if ($script:VMGen -eq 2) { '\Windows\System32\winload.efi' } else { '\Windows\System32\winload.exe' }
                    if ($bcdPath -and -not [string]::Equals($bcdPath, $expectedLoader, [System.StringComparison]::OrdinalIgnoreCase)) {
                        Write-ChainItem -Label "BCD path mismatch" -Status 'WARN' -Detail "Expected '$expectedLoader', found '$bcdPath'"
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "BCD loader path is '$bcdPath' (expected '$expectedLoader')"; Fix = '-FixBoot' })
                    }
                }

                # BCD flags that affect boot behaviour
                if ($bcdText -match 'safeboot\s+(\S+)') {
                    $bcdFlags += "SafeMode=$($Matches[1])"
                    Write-ChainItem -Label "Safe Mode flag active ($($Matches[1]))" -Status 'WARN' -Detail 'VM will boot into Safe Mode'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = "SafeMode boot flag is set ($($Matches[1]))"; Fix = '-RemoveSafeModeFlag' })
                }
                if ($bcdText -match 'testsigning\s+yes') {
                    $bcdFlags += 'TestSigning'
                    Write-ChainItem -Label 'Test Signing is ON' -Status 'WARN' -Detail 'Unsigned drivers are allowed to load'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = 'Test signing is enabled'; Fix = '-DisableTestSigning' })
                }
                if ($bcdText -match 'nointegritychecks\s+yes') {
                    $bcdFlags += 'NoIntegrityChecks'
                    Write-ChainItem -Label 'nointegritychecks is ON' -Status 'WARN' -Detail 'Code integrity checks bypassed; FATAL with Secure Boot'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'WARN'; Message = 'nointegritychecks is ON'; Fix = '-FixBoot' })
                }
                if ($bcdText -match 'recoveryenabled\s+no') {
                    $bcdFlags += 'RecoveryDisabled'
                    Write-ChainItem -Label 'Recovery is disabled' -Status 'WARN' -Detail 'WinRE recovery environment will not launch on failure'
                }
                if ($bcdText -match 'bootstatuspolicy\s+ignoreallfailures') {
                    $bcdFlags += 'IgnoreAllFailures'
                    Write-ChainItem -Label 'bootstatuspolicy: IgnoreAllFailures' -Status 'INFO' -Detail 'Startup repair suppressed on failure'
                }
                if ($bcdText -match 'bootlog\s+yes') {
                    $bcdFlags += 'BootLog'
                    Write-ChainItem -Label 'Boot logging enabled' -Status 'INFO' -Detail 'ntbtlog.txt will be created on boot'
                }
                if ($bcdText -match '(?im)^\s*debug\s+Yes') {
                    $bcdFlags += 'KernelDebug'
                    Write-ChainItem -Label 'Kernel debugging enabled' -Status 'INFO'
                }
                if ($bcdText -match 'imcdevice|imchivename') {
                    $bcdFlags += 'IMC-Hive'
                    Write-ChainItem -Label 'IMC hive (imcdevice/imchivename) in BCD' -Status 'FAIL' -Detail 'Causes BSOD 0x67 CONFIG_INITIALIZATION_FAILED'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 2; Severity = 'FAIL'; Message = 'BCD contains IMC hive entries  -  causes BSOD 0x67'; Fix = '-FixBoot' })
                }

                # Resume object (hibernate)
                if ($bcdText -match 'resumeobject') {
                    Write-ChainItem -Label 'Resume from Hibernation entry present' -Status 'INFO'
                }
            }
            catch {
                Write-ChainItem -Label "BCD parse error: $_" -Status 'WARN'
            }
        }

        #endregion

        #region ===================================================================
        # PHASE 3  -  OS LOADER: winload -> Kernel + HAL + SYSTEM hive + Boot drivers
        #=========================================================================
        Write-Phase 3 'OS LOADER' 'winload loads kernel, HAL, SYSTEM hive, registry, boot-start drivers (Start=0)'

        # 3a. winload binary
        $winloadPath = if ($script:VMGen -eq 2) { 'Windows\System32\winload.efi' } else { 'Windows\System32\winload.exe' }
        $winloadFull = Join-Path $script:WinDriveLetter $winloadPath
        $winloadName = if ($script:VMGen -eq 2) { 'winload.efi' } else { 'winload.exe' }
        $r = Test-BootFile -Path $winloadFull -Label $winloadName
        Write-ChainItem -Label "$winloadName (OS Loader)" -Status $r.Health -Detail $r.Detail
        $totalChecks++
        if ($r.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 3; Severity = $r.Health; Message = "$winloadName : $($r.Detail)"; Fix = '-FixBoot' }) }

        # 3b. Kernel and HAL
        $kernelFiles = @(
            @{ Label = 'ntoskrnl.exe (Windows Kernel)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntoskrnl.exe') }
            @{ Label = 'hal.dll (Hardware Abstraction Layer)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\hal.dll') }
            @{ Label = 'ci.dll (Code Integrity)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ci.dll') }
            @{ Label = 'clfs.sys (Common Log File System)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\drivers\clfs.sys') }
            @{ Label = 'pshed.dll (Platform-Specific HW Error Driver)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\pshed.dll') }
            @{ Label = 'bootvid.dll (Boot Video Driver)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\bootvid.dll') }
        )
        foreach ($kf in $kernelFiles) {
            $r = Test-BootFile -Path $kf.Path -Label $kf.Label
            Write-ChainItem -Label $kf.Label -Status $r.Health -Detail $r.Detail
            $totalChecks++
            if ($r.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 3; Severity = $r.Health; Message = "$($kf.Label): $($r.Detail)"; Fix = "-RepairSystemFile $(Split-Path -Leaf $kf.Path)" }) }
        }

        # 3c. SYSTEM registry hive
        $sysHivePath = Join-Path $script:WinDriveLetter 'Windows\System32\config\SYSTEM'
        $sysHiveResult = Test-BootFile -Path $sysHivePath -Label 'SYSTEM registry hive' -SkipSignature
        Write-ChainItem -Label 'SYSTEM registry hive' -Status $sysHiveResult.Health -Detail $sysHiveResult.Detail
        $totalChecks++
        if ($sysHiveResult.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 3; Severity = 'FAIL'; Message = "SYSTEM hive: $($sysHiveResult.Detail)"; Fix = '-RestoreRegistryFromRegBack' }) }

        # 3d. Boot-start drivers (Start=0)  -  loaded by winload before kernel takes over
        Write-Host ""
        Write-Host "  $symCHAIN  $symARROW  Boot-Start Drivers (Start=0)  -  loaded by $winloadName before kernel init" -ForegroundColor White

        $bootDriverResults = [System.Collections.Generic.List[PSCustomObject]]::new()
        $bootDriverFail = 0
        $bootDriverWarn = 0

        Invoke-WithHive 'SYSTEM' {
            $sysRoot = Get-SystemRootPath
            $svcPath = "$sysRoot\Services"
            $startNames = @{ 0 = 'Boot'; 1 = 'System'; 2 = 'Automatic'; 3 = 'Manual'; 4 = 'Disabled' }
            $typeNames  = @{ 1 = 'Kernel'; 2 = 'FileSystem'; 4 = 'Adapter'; 8 = 'Recognizer' }
            $errorCtlNames = @{ 0 = 'Ignore'; 1 = 'Normal'; 2 = 'Severe'; 3 = 'Critical' }

            # Drivers that are functionally critical on Azure/Hyper-V regardless of ErrorControl.
            # Missing any of these will BSOD the VM (e.g. 0x7B INACCESSIBLE_BOOT_DEVICE) even
            # though their ErrorControl may be Normal (1).
            $azureCriticalDrivers = @('vmbus', 'storvsc', 'storflt', 'vmstorfl', 'netvsc')

            # Enumerate Start=0 (boot) drivers
            $bootDrivers = @()
            Get-ChildItem $svcPath -ErrorAction SilentlyContinue | ForEach-Object {
                $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                if ($null -eq $p -or $null -eq $p.Start -or $null -eq $p.Type) { return }
                if ([int]$p.Start -ne 0) { return }
                if ([int]$p.Type -notin @(1, 2, 4, 8)) { return }  # Drivers only
                $bootDrivers += [PSCustomObject]@{
                    Name         = $_.PSChildName
                    Type         = $typeNames[[int]$p.Type]
                    Group        = if ($p.Group) { $p.Group } else { '(none)' }
                    ErrorControl = if ($null -ne $p.ErrorControl) { [int]$p.ErrorControl } else { 1 }
                    ErrorCtlName = $errorCtlNames[$(if ($null -ne $p.ErrorControl) { [int]$p.ErrorControl } else { 1 })]
                    ImagePath    = $p.ImagePath
                    Tag          = if ($null -ne $p.Tag) { [int]$p.Tag } else { 9999 }
                }
            }

            # Sort by Group then Tag (mimics Windows boot driver load order)
            # Read ServiceGroupOrder from registry for authentic ordering
            $groupOrderPath = "$sysRoot\Control\ServiceGroupOrder"
            $groupList = @()
            if (Test-Path $groupOrderPath) {
                $groupList = @((Get-ItemProperty $groupOrderPath -ErrorAction SilentlyContinue).List)
            }
            # Build group priority map
            $groupPriority = @{}
            for ($i = 0; $i -lt $groupList.Count; $i++) { $groupPriority[$groupList[$i]] = $i }

            $bootDrivers = $bootDrivers | Sort-Object @{
                Expression = { if ($groupPriority.ContainsKey($_.Group)) { $groupPriority[$_.Group] } else { 9999 } }
            }, Tag

            $currentGroup = ''
            foreach ($drv in $bootDrivers) {
                if ($drv.Group -ne $currentGroup) {
                    $currentGroup = $drv.Group
                    Write-Host "  $symCHAIN      -- Group: $currentGroup --" -ForegroundColor DarkCyan
                }
                # Windows default: if ImagePath is absent, the driver file is System32\Drivers\<name>.sys
                $imgResolved = if ($drv.ImagePath) {
                    Resolve-GuestImagePath $drv.ImagePath
                } else {
                    Join-Path $script:WinDriveLetter "Windows\System32\drivers\$($drv.Name).sys"
                }
                $fileExists = if ($imgResolved) { Test-Path -LiteralPath $imgResolved } else { $false }
                $fileSize = if ($fileExists) { (Get-Item -LiteralPath $imgResolved -Force -ErrorAction SilentlyContinue).Length } else { 0 }

                $health = 'OK'
                $detail = ''
                $isAzureCritical = $azureCriticalDrivers -contains $drv.Name
                if (-not $imgResolved -or -not $fileExists) {
                    $health = if ($drv.ErrorControl -ge 2 -or $isAzureCritical) { 'FAIL' } else { 'WARN' }
                    $detail = "MISSING binary  -  ErrorControl=$($drv.ErrorCtlName)"
                    if ($isAzureCritical) { $detail += ' (Azure/Hyper-V critical  -  will BSOD)' }
                    elseif ($drv.ErrorControl -ge 3) { $detail += ' (CRITICAL  -  will BSOD)' }
                    elseif ($drv.ErrorControl -ge 2) { $detail += ' (SEVERE  -  LKGC fallback)' }
                }
                elseif ($fileSize -eq 0) {
                    $health = if ($drv.ErrorControl -ge 2 -or $isAzureCritical) { 'FAIL' } else { 'WARN' }
                    $detail = "0 BYTES (corrupt)  -  ErrorControl=$($drv.ErrorCtlName)"
                    if ($isAzureCritical) { $detail += ' (Azure/Hyper-V critical  -  will BSOD)' }
                }
                else {
                    # Cryptographic trust check (catalog-aware, offline-safe)
                    $drvSig = Test-MicrosoftSignature -FilePath $imgResolved
                    if ($drvSig.IsHardFailure) {
                        $health = 'FAIL'
                        $detail = "IMAGE TRUST FAILURE  -  $(Get-TrustStateDescription -Signature $drvSig)  -  ErrorControl=$($drv.ErrorCtlName)"
                        if ($drv.ErrorControl -ge 3 -or $isAzureCritical) { $detail += ' (0x5A CRITICAL_SERVICE_FAILED  -  will BSOD)' }
                    }
                    elseif ($drvSig.TrustState -eq 'ValidOtherPublisher') {
                        $detail = "3rd-party (signed: $($drvSig.SignerSubject))"
                    }
                    elseif (-not $drvSig.IsAcceptableMicrosoft) {
                        $health = 'WARN'
                        $detail = "$(Get-TrustStateDescription -Signature $drvSig)"
                    }
                    elseif ($drvSig.TrustState -eq 'CatalogUnverified') {
                        $detail = "$('{0:N0}' -f $fileSize) bytes (trust unverified)"
                    }
                    else {
                        $detail = "$('{0:N0}' -f $fileSize) bytes"
                    }
                }

                $label = "$($drv.Name) ($($drv.Type))"
                Write-Host "  $symCHAIN      " -ForegroundColor DarkGray -NoNewline
                switch ($health) {
                    'OK'   { Write-Host "$symOK " -ForegroundColor Green -NoNewline }
                    'WARN' { Write-Host "$symWARN " -ForegroundColor Yellow -NoNewline }
                    'FAIL' { Write-Host "$symFAIL " -ForegroundColor Red -NoNewline }
                }
                Write-Host "$label" -ForegroundColor White -NoNewline
                if ($detail) { Write-Host "  $detail" -ForegroundColor DarkGray } else { Write-Host "" }

                $totalChecks++
                if ($health -eq 'FAIL') {
                    $bootDriverFail++
                    $issues.Add([PSCustomObject]@{ Phase = 3; Severity = 'FAIL'; Message = "Boot driver '$($drv.Name)': $detail"; Fix = "-RepairSystemFile $(Split-Path -Leaf $drv.ImagePath)" })
                }
                elseif ($health -eq 'WARN') {
                    $bootDriverWarn++
                    $issues.Add([PSCustomObject]@{ Phase = 3; Severity = 'WARN'; Message = "Boot driver '$($drv.Name)': $detail"; Fix = '' })
                }
            }

            Write-Host "  $symCHAIN      -- $($bootDrivers.Count) boot-start drivers ($bootDriverFail fail, $bootDriverWarn warn) --" -ForegroundColor DarkGray

            #region ===============================================================
            # PHASE 4  -  NTOS KERNEL INIT: Session Manager, system drivers, services
            #=====================================================================
            Write-Phase 4 'NTOS KERNEL' 'Kernel init -> Session Manager -> Csrss -> Wininit -> Services.exe -> system drivers (Start=1)'

            # 4a. Core kernel-phase executables
            $kernelInitFiles = @(
                @{ Label = 'ntoskrnl.exe (Kernel)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ntoskrnl.exe'); Fix = '-RepairSystemFile ntoskrnl.exe' }
                @{ Label = 'hal.dll (HAL)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\hal.dll'); Fix = '-RepairSystemFile hal.dll' }
                @{ Label = 'ci.dll (Code Integrity)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\ci.dll'); Fix = '-RepairSystemFile ci.dll' }
                @{ Label = 'kdcom.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\kdcom.dll'); Fix = '-RepairSystemFile kdcom.dll' }
                @{ Label = 'pshed.dll'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\pshed.dll'); Fix = '-RepairSystemFile pshed.dll' }
                @{ Label = 'lsass.exe (Local Security Authority)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\lsass.exe') }
                @{ Label = 'svchost.exe (Service Host)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\svchost.exe') }
                @{ Label = 'KernelBase.dll (Kernel Base)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\KernelBase.dll') }
                @{ Label = 'advapi32.dll (Advanced API)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\advapi32.dll') }
            )
            foreach ($kif in $kernelInitFiles) {
                $r = Test-BootFile -Path $kif.Path -Label $kif.Label -SkipSignature:([bool]$kif.SkipSignature)
                Write-ChainItem -Label $kif.Label -Status $r.Health -Detail $r.Detail
                $totalChecks++
                if ($r.Health -ne 'OK') {
                    $fix = if ($kif.Fix) { $kif.Fix } else { "-RepairSystemFile $(Split-Path -Leaf $kif.Path)" }
                    $issues.Add([PSCustomObject]@{ Phase = 4; Severity = $r.Health; Message = "$($kif.Label): $($r.Detail)"; Fix = $fix })
                }
            }
            # 4b. Session Manager registry configuration
            Write-Host ""
            Write-Host "  $symCHAIN  $symARROW  Session Manager Configuration (BootExecute / SetupExecute)" -ForegroundColor White
            $smPath = "$sysRoot\Control\Session Manager"
            if (Test-Path $smPath) {
                $smProps = Get-ItemProperty $smPath -ErrorAction SilentlyContinue
                $sys32Path = Join-Path $script:WinDriveLetter 'Windows\System32'

                # BootExecute
                $bootExec = @($smProps.BootExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                if ($bootExec.Count -eq 0) {
                    Write-ChainItem -Label 'BootExecute: (empty)' -Status 'WARN' -Detail 'Missing default autocheck entry'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'WARN'; Message = 'BootExecute is empty (missing autocheck autochk *)'; Fix = '-FixSessionManager' })
                }
                else {
                    foreach ($entry in $bootExec) {
                        $nativeName = ($entry -split '\s+', 2)[0]
                        $nativePath = Join-Path $sys32Path "$nativeName.exe"
                        $isDefault = ($entry -match '^autocheck\s+autochk')
                        if ($isDefault) {
                            $exists = Test-Path -LiteralPath (Join-Path $sys32Path 'autochk.exe')
                            Write-ChainItem -Label "BootExecute: $entry" -Status $(if ($exists) { 'OK' } else { 'FAIL' }) -Detail $(if (-not $exists) { 'autochk.exe MISSING' } else { '' })
                            $totalChecks++
                            if (-not $exists) { $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'FAIL'; Message = 'autochk.exe missing for BootExecute'; Fix = '-RepairSystemFile autochk.exe' }) }
                        }
                        else {
                            $exists = Test-Path -LiteralPath $nativePath
                            $status = if (-not $exists) { 'WARN' } else { 'INFO' }
                            Write-ChainItem -Label "BootExecute: $entry" -Status $status -Detail $(if (-not $exists) { "Binary $nativeName.exe MISSING (third-party)" } else { '(non-default entry)' })
                            $totalChecks++
                            if (-not $exists) { $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'WARN'; Message = "BootExecute entry '$entry' references missing binary $nativeName.exe"; Fix = '-FixSessionManager' }) }
                        }
                    }
                }

                # SetupExecute (should be empty after setup completes)
                $setupExec = @($smProps.SetupExecute | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                if ($setupExec.Count -gt 0) {
                    foreach ($entry in $setupExec) {
                        Write-ChainItem -Label "SetupExecute: $entry" -Status 'WARN' -Detail 'Should be empty on a fully provisioned OS  -  pending setup operation'
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'WARN'; Message = "SetupExecute is not empty: '$entry'"; Fix = '-FixSessionManager' })
                    }
                }
                else {
                    Write-ChainItem -Label 'SetupExecute: (empty  -  normal)' -Status 'OK'
                }

                # PendingFileRenameOperations
                $pendRenames = @($smProps.PendingFileRenameOperations | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
                if ($pendRenames.Count -gt 0) {
                    Write-ChainItem -Label "PendingFileRenameOperations: $($pendRenames.Count) entries" -Status 'INFO' -Detail 'Pending file renames will execute on boot'
                }

                # SubSystems  -  required for csrss.exe
                $requiredSubsys = $smProps.Required
                if ($requiredSubsys) {
                    Write-ChainItem -Label "Required SubSystems: $($requiredSubsys -join ', ')" -Status 'INFO'
                }
            }
            else {
                Write-ChainItem -Label 'Session Manager key' -Status 'FAIL' -Detail 'Registry key not found'
                $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'FAIL'; Message = 'Session Manager registry key not found'; Fix = '-RestoreRegistryFromRegBack' })
            }

            # 4c. System-start drivers (Start=1)  -  loaded by kernel after boot-start drivers
            Write-Host ""
            Write-Host "  $symCHAIN  $symARROW  System-Start Drivers (Start=1)  -  loaded after kernel takes control" -ForegroundColor White

            $sysDriverFail = 0
            $sysDriverWarn = 0
            $sysDrivers = @()
            Get-ChildItem $svcPath -ErrorAction SilentlyContinue | ForEach-Object {
                $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                if ($null -eq $p -or $null -eq $p.Start -or $null -eq $p.Type) { return }
                if ([int]$p.Start -ne 1) { return }
                if ([int]$p.Type -notin @(1, 2, 4, 8)) { return }
                $sysDrivers += [PSCustomObject]@{
                    Name         = $_.PSChildName
                    Type         = $typeNames[[int]$p.Type]
                    Group        = if ($p.Group) { $p.Group } else { '(none)' }
                    ErrorControl = if ($null -ne $p.ErrorControl) { [int]$p.ErrorControl } else { 1 }
                    ErrorCtlName = $errorCtlNames[$(if ($null -ne $p.ErrorControl) { [int]$p.ErrorControl } else { 1 })]
                    ImagePath    = $p.ImagePath
                    Tag          = if ($null -ne $p.Tag) { [int]$p.Tag } else { 9999 }
                }
            }

            $sysDrivers = $sysDrivers | Sort-Object @{
                Expression = { if ($groupPriority.ContainsKey($_.Group)) { $groupPriority[$_.Group] } else { 9999 } }
            }, Tag

            $currentGroup = ''
            foreach ($drv in $sysDrivers) {
                if ($drv.Group -ne $currentGroup) {
                    $currentGroup = $drv.Group
                    Write-Host "  $symCHAIN      -- Group: $currentGroup --" -ForegroundColor DarkCyan
                }
                # Windows default: if ImagePath is absent, the driver file is System32\Drivers\<name>.sys
                $imgResolved = if ($drv.ImagePath) {
                    Resolve-GuestImagePath $drv.ImagePath
                } else {
                    Join-Path $script:WinDriveLetter "Windows\System32\drivers\$($drv.Name).sys"
                }
                $fileExists = if ($imgResolved) { Test-Path -LiteralPath $imgResolved } else { $false }
                $fileSize = if ($fileExists) { (Get-Item -LiteralPath $imgResolved -Force -ErrorAction SilentlyContinue).Length } else { 0 }

                $health = 'OK'
                $detail = ''
                $isAzureCritical = $azureCriticalDrivers -contains $drv.Name
                if (-not $imgResolved -or -not $fileExists) {
                    $health = if ($drv.ErrorControl -ge 2 -or $isAzureCritical) { 'FAIL' } else { 'WARN' }
                    $detail = "MISSING binary  -  ErrorControl=$($drv.ErrorCtlName)"
                    if ($isAzureCritical) { $detail += ' (Azure/Hyper-V critical  -  will BSOD)' }
                    elseif ($drv.ErrorControl -ge 3) { $detail += ' (CRITICAL  -  will BSOD)' }
                    elseif ($drv.ErrorControl -ge 2) { $detail += ' (SEVERE  -  LKGC fallback)' }
                }
                elseif ($fileSize -eq 0) {
                    $health = if ($drv.ErrorControl -ge 2 -or $isAzureCritical) { 'FAIL' } else { 'WARN' }
                    $detail = "0 BYTES (corrupt)  -  ErrorControl=$($drv.ErrorCtlName)"
                    if ($isAzureCritical) { $detail += ' (Azure/Hyper-V critical  -  will BSOD)' }
                }
                else {
                    $drvSig = Test-MicrosoftSignature -FilePath $imgResolved
                    if ($drvSig.IsHardFailure) {
                        $health = 'FAIL'
                        $detail = "IMAGE TRUST FAILURE  -  $(Get-TrustStateDescription -Signature $drvSig)  -  ErrorControl=$($drv.ErrorCtlName)"
                        if ($drv.ErrorControl -ge 3 -or $isAzureCritical) { $detail += ' (0x5A CRITICAL_SERVICE_FAILED  -  will BSOD)' }
                    }
                    elseif ($drvSig.TrustState -eq 'ValidOtherPublisher') {
                        $detail = "3rd-party (signed: $($drvSig.SignerSubject))"
                    }
                    elseif (-not $drvSig.IsAcceptableMicrosoft) {
                        $health = 'WARN'
                        $detail = "$(Get-TrustStateDescription -Signature $drvSig)"
                    }
                    elseif ($drvSig.TrustState -eq 'CatalogUnverified') {
                        $detail = "$('{0:N0}' -f $fileSize) bytes (trust unverified)"
                    }
                    else {
                        $detail = "$('{0:N0}' -f $fileSize) bytes"
                    }
                }

                Write-Host "  $symCHAIN      " -ForegroundColor DarkGray -NoNewline
                switch ($health) {
                    'OK'   { Write-Host "$symOK " -ForegroundColor Green -NoNewline }
                    'WARN' { Write-Host "$symWARN " -ForegroundColor Yellow -NoNewline }
                    'FAIL' { Write-Host "$symFAIL " -ForegroundColor Red -NoNewline }
                }
                Write-Host "$($drv.Name) ($($drv.Type))" -ForegroundColor White -NoNewline
                if ($detail) { Write-Host "  $detail" -ForegroundColor DarkGray } else { Write-Host "" }

                $totalChecks++
                if ($health -eq 'FAIL') {
                    $sysDriverFail++
                    $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'FAIL'; Message = "System driver '$($drv.Name)': $detail"; Fix = "-RepairSystemFile $(Split-Path -Leaf $drv.ImagePath)" })
                }
                elseif ($health -eq 'WARN') {
                    $sysDriverWarn++
                    $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'WARN'; Message = "System driver '$($drv.Name)': $detail"; Fix = '' })
                }
            }
            Write-Host "  $symCHAIN      -- $($sysDrivers.Count) system-start drivers ($sysDriverFail fail, $sysDriverWarn warn) --" -ForegroundColor DarkGray

            # 4d. Auto-start services (Start=2)  -  launched by services.exe
            Write-Host ""
            Write-Host "  $symCHAIN  $symARROW  Auto-Start Services (Start=2)  -  launched by services.exe" -ForegroundColor White

            $autoSvcFail = 0
            $autoSvcWarn = 0
            $autoSvcCount = 0
            Get-ChildItem $svcPath -ErrorAction SilentlyContinue | ForEach-Object {
                $p = Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue
                if ($null -eq $p -or $null -eq $p.Start -or $null -eq $p.Type) { return }
                if ([int]$p.Start -ne 2) { return }
                if ([int]$p.Type -notin @(16, 32, 256)) { return }  # Win32 services only

                $imgRaw = $p.ImagePath
                $imgResolved = if ($imgRaw) { Resolve-GuestImagePath $imgRaw } else { $null }
                $fileExists = if ($imgResolved) { Test-Path -LiteralPath $imgResolved } else { $false }
                $fileSize = if ($fileExists) { (Get-Item -LiteralPath $imgResolved -Force -ErrorAction SilentlyContinue).Length } else { 0 }

                $health = 'OK'
                $detail = ''
                if (-not $imgResolved -or -not $fileExists) {
                    # svchost-hosted services may not have their own binary
                    if ($imgRaw -match 'svchost\.exe') {
                        $health = 'OK'
                        $detail = 'svchost-hosted'
                    }
                    else {
                        $health = 'WARN'
                        $detail = "MISSING binary: $imgRaw"
                    }
                }
                elseif ($fileSize -eq 0) {
                    $health = 'WARN'
                    $detail = '0 BYTES (corrupt)'
                }

                # Only show issues or first few OK to keep noise down
                if ($health -ne 'OK') {
                    Write-Host "  $symCHAIN      " -ForegroundColor DarkGray -NoNewline
                    $icon = if ($health -eq 'FAIL') { $symFAIL } else { $symWARN }
                    $col = if ($health -eq 'FAIL') { 'Red' } else { 'Yellow' }
                    Write-Host "$icon " -ForegroundColor $col -NoNewline
                    Write-Host "$($_.PSChildName)" -ForegroundColor White -NoNewline
                    Write-Host "  $detail" -ForegroundColor DarkGray
                    $totalChecks++
                    if ($health -eq 'FAIL') { $autoSvcFail++ }
                    else { $autoSvcWarn++ }
                    $issues.Add([PSCustomObject]@{ Phase = 4; Severity = $health; Message = "Auto-start service '$($_.PSChildName)': $detail"; Fix = '' })
                }
                $autoSvcCount++
            }
            Write-Host "  $symCHAIN      -- $autoSvcCount auto-start services ($autoSvcFail fail, $autoSvcWarn warn) --" -ForegroundColor DarkGray

            # 4e. Critical registry keys checked during kernel init
            Write-Host ""
            Write-Host "  $symCHAIN  $symARROW  Critical Registry Configuration" -ForegroundColor White

            # ControlSet active check
            $current = (Get-ItemProperty 'HKLM:\BROKENSYSTEM\Select' -ErrorAction SilentlyContinue).Current
            $default = (Get-ItemProperty 'HKLM:\BROKENSYSTEM\Select' -ErrorAction SilentlyContinue).Default
            $lastKnown = (Get-ItemProperty 'HKLM:\BROKENSYSTEM\Select' -ErrorAction SilentlyContinue).LastKnownGood
            if ($current) {
                $csMatch = ($current -eq $default)
                $csLabel = "Active ControlSet: ControlSet{0:d3} (Current=$current, Default=$default, LKGC=$lastKnown)" -f $current
                Write-ChainItem -Label $csLabel -Status $(if ($csMatch) { 'OK' } else { 'INFO' }) -Detail $(if (-not $csMatch) { 'Current != Default (LKGC may have been used)' } else { '' })
            }

            # Memory Management  -  paging settings
            $mmPath = "$sysRoot\Control\Session Manager\Memory Management"
            if (Test-Path $mmPath) {
                $mmProps = Get-ItemProperty $mmPath -ErrorAction SilentlyContinue
                $pagingFiles = $mmProps.PagingFiles
                if ($pagingFiles) {
                    Write-ChainItem -Label "PagingFiles: $($pagingFiles -join '; ')" -Status 'INFO'
                }
                # Driver Verifier
                $verifyDrivers = $mmProps.VerifyDrivers
                $verifyLevel = $mmProps.VerifyDriverLevel
                if ($verifyDrivers -or $verifyLevel) {
                    Write-ChainItem -Label "Driver Verifier ACTIVE  -  Targets: $verifyDrivers (Level: $verifyLevel)" -Status 'WARN' -Detail 'Can cause BSODs if misconfigured'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 4; Severity = 'WARN'; Message = "Driver Verifier is active (targets: $verifyDrivers)"; Fix = '-DisableDriverVerifier' })
                }
            }

            # CrashControl  -  dump settings
            $ccPath = "$sysRoot\Control\CrashControl"
            if (Test-Path $ccPath) {
                $ccProps = Get-ItemProperty $ccPath -ErrorAction SilentlyContinue
                $dumpType = switch ([int]$ccProps.CrashDumpEnabled) { 0 { 'None' }; 1 { 'Complete' }; 2 { 'Kernel' }; 3 { 'Small (minidump)' }; 7 { 'Automatic' }; default { "$($ccProps.CrashDumpEnabled)" } }
                Write-ChainItem -Label "Crash Dump: $dumpType -> $($ccProps.DumpFile)" -Status 'INFO'
            }
        }  # End Invoke-WithHive SYSTEM

        #endregion

        #region ===================================================================
        # PHASE 5  -  LOGON & DESKTOP: Winlogon, LogonUI, credentials, shell
        #=========================================================================
        Write-Phase 5 'LOGON & DESKTOP' 'Winlogon -> LogonUI -> Lsass credential validation -> Userinit -> Explorer shell'

        # 5a. Logon-phase binaries
        $logonFiles = @(
            @{ Label = 'winlogon.exe (Windows Logon)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\winlogon.exe') }
            @{ Label = 'LogonUI.exe (Logon UI)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\LogonUI.exe') }
            @{ Label = 'lsass.exe (Security Authority)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\lsass.exe') }
            @{ Label = 'userinit.exe (User Initialization)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\userinit.exe') }
            @{ Label = 'explorer.exe (Windows Shell)'; Path = (Join-Path $script:WinDriveLetter 'Windows\explorer.exe') }
            @{ Label = 'dwm.exe (Desktop Window Manager)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\dwm.exe') }
            @{ Label = 'consent.exe (UAC Consent UI)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\consent.exe') }
            @{ Label = 'mpssvc.dll (Windows Firewall)'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\mpssvc.dll') }
        )
        foreach ($lf in $logonFiles) {
            $r = Test-BootFile -Path $lf.Path -Label $lf.Label
            Write-ChainItem -Label $lf.Label -Status $r.Health -Detail $r.Detail
            $totalChecks++
            if ($r.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 5; Severity = $r.Health; Message = "$($lf.Label): $($r.Detail)"; Fix = "-RepairSystemFile $(Split-Path -Leaf $lf.Path)" }) }
        }

        # 5b. Winlogon registry settings (Shell, Userinit)
        Write-Host ""
        Write-Host "  $symCHAIN  $symARROW  Winlogon & Shell Configuration" -ForegroundColor White

        Invoke-WithHive 'SOFTWARE' {
            $wlPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
            if (Test-Path $wlPath) {
                $wlProps = Get-ItemProperty $wlPath -ErrorAction SilentlyContinue

                # Shell
                $shell = $wlProps.Shell
                if (-not $shell) {
                    Write-ChainItem -Label 'Winlogon Shell: (not set)' -Status 'FAIL' -Detail 'No shell will launch after logon'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'FAIL'; Message = 'Winlogon Shell is not set'; Fix = '-FixWinlogon' })
                }
                elseif ($shell -ne 'explorer.exe') {
                    Write-ChainItem -Label "Winlogon Shell: $shell" -Status 'WARN' -Detail "Non-default shell (expected 'explorer.exe')"
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'WARN'; Message = "Winlogon Shell is '$shell' (expected 'explorer.exe')"; Fix = '-FixWinlogon' })
                }
                else {
                    Write-ChainItem -Label 'Winlogon Shell: explorer.exe' -Status 'OK'
                }

                # Userinit
                $userinit = $wlProps.Userinit
                $expectedUserinit = 'C:\Windows\system32\userinit.exe,'
                if (-not $userinit) {
                    Write-ChainItem -Label 'Winlogon Userinit: (not set)' -Status 'FAIL' -Detail 'Userinit missing  -  logon sequence will fail'
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'FAIL'; Message = 'Winlogon Userinit is not set'; Fix = '-FixWinlogon' })
                }
                elseif ($userinit -ne $expectedUserinit) {
                    Write-ChainItem -Label "Winlogon Userinit: $userinit" -Status 'WARN' -Detail "Non-default (expected '$expectedUserinit')"
                    $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'WARN'; Message = "Winlogon Userinit is '$userinit' (non-default)"; Fix = '-FixWinlogon' })
                }
                else {
                    Write-ChainItem -Label "Winlogon Userinit: $userinit" -Status 'OK'
                }

                # GpExtensions / AppInit_DLLs  -  potential boot blockers
                $appInitPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows'
                if (Test-Path $appInitPath) {
                    $appInitProps = Get-ItemProperty $appInitPath -ErrorAction SilentlyContinue
                    $appInitDlls = $appInitProps.AppInit_DLLs
                    $loadAppInit = $appInitProps.LoadAppInit_DLLs
                    if ($loadAppInit -eq 1 -and $appInitDlls) {
                        Write-ChainItem -Label "AppInit_DLLs ACTIVE: $appInitDlls" -Status 'WARN' -Detail 'Third-party DLLs injected into every process  -  common boot blocker'
                        $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'WARN'; Message = "AppInit_DLLs loaded: $appInitDlls"; Fix = '' })
                    }
                }

                # Credential providers
                $cpPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\Credential Providers'
                if (Test-Path $cpPath) {
                    $cpCount = (Get-ChildItem $cpPath -ErrorAction SilentlyContinue).Count
                    Write-ChainItem -Label "Credential Providers: $cpCount registered" -Status 'INFO'
                }
            }
            else {
                Write-ChainItem -Label 'Winlogon key' -Status 'FAIL' -Detail 'HKLM:\SOFTWARE\...\Winlogon not found'
                $totalChecks++; $issues.Add([PSCustomObject]@{ Phase = 5; Severity = 'FAIL'; Message = 'Winlogon registry key not found'; Fix = '-RestoreRegistryFromRegBack' })
            }

            # 5c. Other critical SOFTWARE hive checks
            # Run / RunOnce startup programs
            $runPaths = @(
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Run'
                'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce'
            )
            foreach ($rp in $runPaths) {
                if (-not (Test-Path $rp)) { continue }
                $entries = Get-ItemProperty $rp -ErrorAction SilentlyContinue
                $names = $entries.PSObject.Properties | Where-Object { $_.Name -notin @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider') }
                if ($names.Count -gt 0) {
                    $keyName = Split-Path -Leaf $rp
                    $preview = ($names | Select-Object -First 3 | ForEach-Object { $_.Name }) -join ', '
                    Write-ChainItem -Label "$keyName : $($names.Count) startup entries" -Status 'INFO' -Detail $preview
                }
            }
        }  # End Invoke-WithHive SOFTWARE

        # 5d. Additional registry hive files health (SOFTWARE, SAM, SECURITY)
        Write-Host ""
        Write-Host "  $symCHAIN  $symARROW  Registry Hive Files Health" -ForegroundColor White
        $hiveFiles = @(
            @{ Label = 'SOFTWARE hive'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\config\SOFTWARE') }
            @{ Label = 'SAM hive'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\config\SAM') }
            @{ Label = 'SECURITY hive'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\config\SECURITY') }
            @{ Label = 'DEFAULT hive'; Path = (Join-Path $script:WinDriveLetter 'Windows\System32\config\DEFAULT') }
        )
        foreach ($hf in $hiveFiles) {
            $r = Test-BootFile -Path $hf.Path -Label $hf.Label -SkipSignature
            Write-ChainItem -Label $hf.Label -Status $r.Health -Detail $r.Detail
            $totalChecks++
            if ($r.Health -ne 'OK') { $issues.Add([PSCustomObject]@{ Phase = 5; Severity = $r.Health; Message = "$($hf.Label): $($r.Detail)"; Fix = '-RestoreRegistryFromRegBack' }) }
        }

        #endregion

        #region ===================================================================
        # SUMMARY
        #=========================================================================
        Write-Host ""
        Write-Host "  $("$symEQ" * 76)" -ForegroundColor Cyan
        Write-Host "                          BOOT PATH HEALTH SUMMARY" -ForegroundColor White
        Write-Host "  $("$symEQ" * 76)" -ForegroundColor Cyan

        $fails = @($issues | Where-Object { $_.Severity -eq 'FAIL' })
        $warns = @($issues | Where-Object { $_.Severity -eq 'WARN' })

        Write-Host ""
        Write-Host "  Total checks performed : $totalChecks" -ForegroundColor White
        Write-Host -NoNewline "  Critical failures      : "; Write-Host "$($fails.Count)" -ForegroundColor $(if ($fails.Count -gt 0) { 'Red' } else { 'Green' })
        Write-Host -NoNewline "  Warnings               : "; Write-Host "$($warns.Count)" -ForegroundColor $(if ($warns.Count -gt 0) { 'Yellow' } else { 'Green' })

        if ($fails.Count -eq 0 -and $warns.Count -eq 0) {
            Write-Host ""
            Write-Host "  $symOK  All boot path artifacts verified  -  boot chain looks healthy." -ForegroundColor Green
        }
        else {
            if ($fails.Count -gt 0) {
                Write-Host ""
                Write-Host "  -- CRITICAL Issues (will prevent boot) --" -ForegroundColor Red
                $phaseNames = @{ 1 = 'Pre-Boot'; 2 = 'Boot Manager'; 3 = 'OS Loader'; 4 = 'NTOS Kernel'; 5 = 'Logon & Desktop' }
                foreach ($f in $fails) {
                    $phaseName = $phaseNames[[int]$f.Phase]
                    Write-Host "  $symFAIL  [Phase $($f.Phase) - $phaseName] $($f.Message)" -ForegroundColor Red
                    if ($f.Fix) { Write-Host "           Fix: $($f.Fix)" -ForegroundColor Yellow }
                }
            }
            if ($warns.Count -gt 0) {
                Write-Host ""
                Write-Host "  -- Warnings (may affect boot or indicate risk) --" -ForegroundColor Yellow
                foreach ($w in $warns | Select-Object -First 15) {
                    Write-Host "  $symWARN  [Phase $($w.Phase)] $($w.Message)" -ForegroundColor Yellow
                    if ($w.Fix) { Write-Host "           Fix: $($w.Fix)" -ForegroundColor DarkYellow }
                }
                if ($warns.Count -gt 15) {
                    Write-Host "  ... and $($warns.Count - 15) additional warnings." -ForegroundColor DarkGray
                }
            }
        }

        Write-Host ""
        Write-Host "  Tip: Use -AnalyzeCriticalBootFiles for a quick file-only table, -AnalyzeBcdConsistency for detailed BCD." -ForegroundColor DarkGray
        Write-Host "  $("$symEQ" * 76)" -ForegroundColor Cyan
        Write-Host ""
    }
    # End GetBootPathReport

    function AnalyzeBcdConsistency {
        Write-Host "Analyzing BCD consistency..." -ForegroundColor Yellow
        $store = Get-BcdStorePath -BootDrive $script:BootDriveLetter -Generation $script:VMGen
        $hasStructuralWarnings = $false
        if (-not (Test-Path -LiteralPath $store)) {
            Write-Warning "BCD store not found: $store"
            return
        }
        $inventory = Get-BcdInventory -StorePath $store
        $loaders = @($inventory.Loaders)
        if ($loaders.Count -eq 0) {
            Write-Warning "Unable to resolve Windows Boot Loader identifier in BCD."
            return
        }

        $id = Get-BcdBootLoaderId -StorePath $store
        $loader = $null
        if ($id) {
            $loader = Get-BcdLoaderDetails -StorePath $store -Identifier $id
        }
        if (-not $loader) {
            $fallbackLoader = @($loaders | Select-Object -First 1)
            if ($fallbackLoader) {
                $loader = Get-BcdLoaderDetails -StorePath $store -Identifier $fallbackLoader[0].Identifier
                if (-not $loader) {
                    $loader = $fallbackLoader[0]
                }
            }
        }

        if ($loaders.Count -gt 1) {
            Write-Host "Windows Boot Loader entries:" -ForegroundColor Cyan
            $loaders | Select-Object Identifier, Description, PartitionDrive, Path, IsSetupEntry | Format-Table -AutoSize
            Write-Warning "Multiple Windows Boot Loader entries were found. -FixBoot can rebuild the store around the selected Windows installation."
            $hasStructuralWarnings = $true
        }

        $setupLoaders = @($loaders | Where-Object { $_.IsSetupEntry })
        if ($setupLoaders.Count -gt 0) {
            $setupSummary = ($setupLoaders | ForEach-Object { if ($_.Description) { $_.Description } else { $_.Identifier } }) -join '; '
            Write-Warning "BCD contains setup/stale loader entries: $setupSummary"
            $hasStructuralWarnings = $true
        }

        if ($script:SelectedWindowsInstall) {
            $selected = $script:SelectedWindowsInstall
            $selectedBuild = Format-WindowsBuildLabel -Build $selected.CurrentBuildNumber -Ubr $selected.UBR -Fallback 'unknown'
            Write-Host "Selected Windows install: $($selected.Drive) ($($selected.ProductName), build $selectedBuild, score=$($selected.Score))" -ForegroundColor Cyan
            if ($selected.SetupEvidence) {
                Write-Warning "Selected install still shows setup/upgrade markers: $($selected.SetupEvidence)"
                $hasStructuralWarnings = $true
            }
        }

        $device = $loader.Device
        $osdev = $loader.OsDevice
        $path = $loader.Path
        $sysrt = if ($loader.SystemRoot) { $loader.SystemRoot } else { '\Windows' }

        $expectedPath = if ($script:VMGen -eq 2) { '\Windows\System32\winload.efi' } else { '\Windows\System32\winload.exe' }
        $expectedFile = Join-Path $script:WinDriveLetter ($expectedPath.TrimStart('\'))
        $pathOk = [string]::Equals($path, $expectedPath, [System.StringComparison]::OrdinalIgnoreCase)
        $fileOk = Test-Path -LiteralPath $expectedFile

        [PSCustomObject]@{
            BcdStore       = $store
            LoaderId       = $id
            Device         = $device
            OsDevice       = $osdev
            Path           = $path
            SystemRoot     = $sysrt
            LoaderCount     = $loaders.Count
            BootDefault     = $inventory.DefaultId
            IsSetupEntry    = $loader.IsSetupEntry
            ExpectedPath   = $expectedPath
            ExpectedExists = $fileOk
        } | Format-List

        if ($script:SelectedWindowsInstall -and $loader.PartitionDrive -and $loader.PartitionDrive -ne $script:SelectedWindowsInstall.Drive) {
            Write-Warning "Preferred BCD loader points to $($loader.PartitionDrive), but the selected Windows install is $($script:SelectedWindowsInstall.Drive)."
            $hasStructuralWarnings = $true
        }

        if (-not $pathOk -or -not $fileOk) {
            Write-Warning "BCD entry may be inconsistent (path mismatch or winload file missing). Consider -FixBoot if boot fails."
        }
        elseif ($hasStructuralWarnings) {
            Write-Warning "Preferred BCD loader path looks consistent, but the BCD store still has structural issues. Consider -FixBoot if you want to collapse stale or setup entries."
        }
        else {
            Write-Host "BCD loader path and winload target look consistent." -ForegroundColor Green
        }
    }

    function AnalyzeComponentStore {
        Write-Host "Analyzing component store integrity from offline CBS log..." -ForegroundColor Yellow

        $cbsLogPath = Join-Path $script:WinDriveLetter 'Windows\Logs\CBS\CBS.log'
        if (-not (Test-Path $cbsLogPath)) {
            Write-Warning "CBS.log not found at $cbsLogPath - cannot analyze offline."
            Write-Host "Run -RepairComponentStore to trigger a DISM /ScanHealth which will produce a CBS.log." -ForegroundColor DarkCyan
            return
        }

        # Detect guest OS version for context
        $guestVersion = Get-GuestCurrentVersion
        $guestBuild = $guestVersion.CurrentBuildNumber
        $guestUBR = $guestVersion.UBR
        $guestProduct = $guestVersion.ProductName

        $fullBuild = Format-WindowsBuildLabel -Build $guestBuild -Ubr $guestUBR -Fallback 'unknown'
        Write-Host "Guest OS: $guestProduct (Build $fullBuild)" -ForegroundColor Cyan

        $hostBuild = [System.Environment]::OSVersion.Version.Build
        if ($guestBuild -and $hostBuild -and $guestBuild -ne "$hostBuild") {
            Write-Host "Host OS build: $hostBuild (DIFFERENT from guest - host WinSxS cannot be used as repair source)" -ForegroundColor Yellow
        }

        Write-Host "Parsing CBS.log for corruption entries..." -ForegroundColor Cyan
        $cbsContent = Get-Content $cbsLogPath -ErrorAction SilentlyContinue

        # Pattern 1: CSI Payload Corrupt lines
        # Format: (p)   CSI Payload Corrupt   (n)   <arch>_<component>_<version>\<file>
        $corruptPayloads = @()
        $repairFailures = @()
        $corruptComponents = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

        foreach ($line in $cbsContent) {
            if ($line -match 'CSI Payload Corrupt.*?(\S+_[0-9a-f]{16}_\S+)\\(\S+)') {
                $componentFull = $Matches[1]
                $fileName = $Matches[2]
                $null = $corruptComponents.Add($componentFull)
                $corruptPayloads += [PSCustomObject]@{
                    Component = $componentFull
                    File      = $fileName
                }
            }
            elseif ($line -match 'CSI Manifest Corrupt.*?(\S+_[0-9a-f]{16}_\S+)') {
                $null = $corruptComponents.Add($Matches[1])
                $corruptPayloads += [PSCustomObject]@{
                    Component = $Matches[1]
                    File      = '(manifest)'
                }
            }
            elseif ($line -match 'Repair failed.*Missing replacement') {
                $repairFailures += $line.Trim()
            }
            elseif ($line -match 'CBS_E_SOURCE_MISSING|PSFX_E_MATCHING_BINARY_MISSING|ERROR_SXS_ASSEMBLY_NOT_FOUND') {
                $repairFailures += $line.Trim()
            }
        }

        if ($corruptPayloads.Count -eq 0) {
            # Also check for ScanHealth summary
            $scanResult = $cbsContent | Where-Object { $_ -match 'Total Detected Corruption:\s+(\d+)' }
            if ($scanResult -and $Matches[1] -eq '0') {
                Write-Host "No component corruption detected in CBS.log." -ForegroundColor Green
                return
            }
            elseif ($scanResult) {
                Write-Host "CBS.log reports $($Matches[1]) corruption(s) detected but specific components could not be parsed." -ForegroundColor Yellow
                Write-Host "Run -RepairComponentStore to trigger a fresh scan and check the updated CBS.log." -ForegroundColor DarkCyan
                return
            }

            Write-Host "No corruption entries found in CBS.log." -ForegroundColor Green
            Write-Host "To trigger a fresh scan, run -RepairComponentStore (DISM /ScanHealth)." -ForegroundColor DarkCyan
            return
        }

        # Extract version info from component names to identify required KB
        # Component format: <arch>_<name>_<publickeytoken>_<version>_<locale>_<hash>
        $versionMap = @{}
        foreach ($comp in $corruptComponents) {
            if ($comp -match '_(\d+\.\d+\.\d+\.\d+)_') {
                $ver = $Matches[1]
                if (-not $versionMap.ContainsKey($ver)) { $versionMap[$ver] = [System.Collections.Generic.List[string]]::new() }
                $versionMap[$ver].Add($comp)
            }
        }

        Write-Host ""
        Write-Host "=== Component Store Corruption Report ===" -ForegroundColor Cyan
        Write-Host ""
        Write-Host "Corrupt components: $($corruptComponents.Count)" -ForegroundColor Red
        Write-Host "Corrupt files:" -ForegroundColor Red
        $corruptPayloads | ForEach-Object {
            Write-Host "  $($_.File)  ($($_.Component))" -ForegroundColor Yellow
        }

        if ($repairFailures.Count -gt 0) {
            Write-Host ""
            Write-Host "Previous repair attempts failed ($($repairFailures.Count) errors):" -ForegroundColor Red
            $repairFailures | Select-Object -First 5 | ForEach-Object {
                Write-Host "  $_" -ForegroundColor DarkYellow
            }
        }

        Write-Host ""
        Write-Host "=== Required Update Versions ===" -ForegroundColor Cyan
        foreach ($ver in $versionMap.Keys | Sort-Object) {
            $parts = $ver -split '\.'
            $majorBuild = "$($parts[2]).$($parts[3])"
            Write-Host ""
            Write-Host "  Version: $ver  (build $majorBuild)" -ForegroundColor White
            Write-Host "  Components: $($versionMap[$ver].Count)" -ForegroundColor DarkGray
            # Try to help identify the KB
            if ($parts[2] -match '^\d+$') {
                $buildNum = [int]$parts[2]
                # NOTE: PowerShell 'switch' runs the body of EVERY matching clause unless
                # 'break' is used. Each clause below ends in 'break' so the FIRST (highest)
                # matching threshold wins; without it every build collapsed to the lowest
                # match (e.g. 9600 was mislabelled 'Server 2012' instead of '2012 R2').
                $osName = switch ($buildNum) {
                    { $_ -ge 26100 } { 'Windows Server 2025 / Windows 11 24H2'; break }
                    { $_ -ge 22631 } { 'Windows 11 23H2'; break }
                    { $_ -ge 22621 } { 'Windows 11 22H2'; break }
                    { $_ -ge 22000 } { 'Windows 11 21H2'; break }
                    { $_ -ge 20348 } { 'Windows Server 2022'; break }
                    { $_ -ge 19045 } { 'Windows 10 22H2'; break }
                    { $_ -ge 19044 } { 'Windows 10 21H2'; break }
                    { $_ -ge 19041 } { 'Windows 10 2004+'; break }
                    { $_ -ge 17763 } { 'Windows Server 2019 / Windows 10 1809'; break }
                    { $_ -ge 17134 } { 'Windows 10 1803'; break }
                    { $_ -ge 16299 } { 'Windows 10 1709'; break }
                    { $_ -ge 15063 } { 'Windows 10 1703'; break }
                    { $_ -ge 14393 } { 'Windows Server 2016 / Windows 10 1607'; break }
                    { $_ -ge 10240 } { 'Windows 10 1507'; break }
                    { $_ -ge 9600 } { 'Windows Server 2012 R2 / Windows 8.1'; break }
                    { $_ -ge 9200 } { 'Windows Server 2012 / Windows 8'; break }
                    default { 'Unknown OS' }
                }
                Write-Host "  OS:      $osName" -ForegroundColor DarkGray
                Write-Host "  Search:  https://www.catalog.update.microsoft.com/Search.aspx?q=$majorBuild" -ForegroundColor DarkCyan
            }
        }

        Write-Host ""
        Write-Host "=== How to Repair ===" -ForegroundColor Cyan
        Write-Host "1. Download the cumulative update (.msu) for build $fullBuild from the Microsoft Update Catalog" -ForegroundColor White
        Write-Host "   (use the search links above or search for the build number)" -ForegroundColor DarkGray
        Write-Host "2. Run:" -ForegroundColor White
        $scriptName = if ($PSCommandPath) { Split-Path -Leaf $PSCommandPath } else { 'RepairVM.ps1' }
        Write-Host "   .\$scriptName -DiskNumber $($script:DiskNumber) -RepairComponentStore -RepairSource <path-to-downloaded.msu>" -ForegroundColor Green
        Write-Host "3. Alternatively, use a matching install.wim or .iso as source:" -ForegroundColor White
        Write-Host "   .\$scriptName -DiskNumber $($script:DiskNumber) -RepairComponentStore -RepairSource <path-to-install.wim>" -ForegroundColor Green
        Write-Host ""
        Write-Host "Note: A base ISO may not contain updated components. The cumulative .msu matching" -ForegroundColor DarkGray
        Write-Host "build $fullBuild is the most reliable source for the exact file versions needed." -ForegroundColor DarkGray
    }

    function Ensure-RecentChangeRegistryLastWriteAccessor {
        if (([System.Management.Automation.PSTypeName]'RepairAzVmDiskRegistryLastWrite').Type) { return }

        $source = @"
using System;
using System.Runtime.InteropServices;
public static class RepairAzVmDiskRegistryLastWrite {
  [DllImport("advapi32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
  public static extern int RegQueryInfoKey(IntPtr hKey, System.Text.StringBuilder lpClass, ref uint lpcchClass, IntPtr lpReserved, out uint lpcSubKeys, out uint lpcbMaxSubKeyLen, out uint lpcbMaxClassLen, out uint lpcValues, out uint lpcbMaxValueNameLen, out uint lpcbMaxValueLen, out uint lpcbSecurityDescriptor, out long lpftLastWriteTime);
  public static object GetLastWriteTime(Microsoft.Win32.RegistryKey key) {
    if (key == null) return null;
    uint classLength = 0, subKeys, maxSubKeyLength, maxClassLength, values, maxValueNameLength, maxValueLength, securityDescriptor;
    long fileTime;
    int result = RegQueryInfoKey(key.Handle.DangerousGetHandle(), null, ref classLength, IntPtr.Zero, out subKeys, out maxSubKeyLength, out maxClassLength, out values, out maxValueNameLength, out maxValueLength, out securityDescriptor, out fileTime);
    if (result != 0) return null;
    return DateTime.FromFileTimeUtc(fileTime).ToLocalTime();
  }
}
"@
        Add-Type -TypeDefinition $source -ErrorAction Stop
    }

    function Get-RegistryKeyLastWriteTime {
        param([Parameter(Mandatory = $true)][string]$Path)

        try { Ensure-RecentChangeRegistryLastWriteAccessor }
        catch { return $null }

        $subKey = ''
        if ($Path -match '^Microsoft\.PowerShell\.Core\\Registry::HKEY_LOCAL_MACHINE\\(.+)$') {
            $subKey = $Matches[1]
        }
        elseif ($Path -match '^HKEY_LOCAL_MACHINE\\(.+)$') {
            $subKey = $Matches[1]
        }
        elseif ($Path -match '^HKLM:\\(.+)$') {
            $subKey = $Matches[1]
        }
        else {
            return $null
        }

        $registryKey = $null
        try {
            $registryKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($subKey)
            if (-not $registryKey) { return $null }
            $lastWrite = [RepairAzVmDiskRegistryLastWrite]::GetLastWriteTime($registryKey)
            if ($lastWrite) { return [datetime]$lastWrite }
        }
        catch { return $null }
        finally { if ($registryKey) { $registryKey.Close() } }
        return $null
    }

    function ConvertTo-RecentChangeShortText {
        param([string]$Text, [int]$MaxLength = 180)
        if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
        $trimmed = $Text.Trim()
        if ($trimmed.Length -le $MaxLength) { return $trimmed }
        return ($trimmed.Substring(0, $MaxLength) + '...')
    }

    function Get-RecentChangeTimestampFromText {
        param([string]$Text)

        if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
        $culture = [System.Globalization.CultureInfo]::InvariantCulture
        $styles = [System.Globalization.DateTimeStyles]::AssumeLocal
        if ($Text -match '(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2}:\d{2})') {
            $value = $Matches[1] + ' ' + $Matches[2]
            $parsed = [datetime]::MinValue
            if ([datetime]::TryParseExact($value, 'yyyy-MM-dd HH:mm:ss', $culture, $styles, [ref]$parsed)) { return $parsed }
        }
        if ($Text -match '(\d{4}/\d{2}/\d{2})\s+(\d{2}:\d{2}:\d{2})(?:\.\d+)?') {
            $value = $Matches[1] + ' ' + $Matches[2]
            $parsed = [datetime]::MinValue
            if ([datetime]::TryParseExact($value, 'yyyy/MM/dd HH:mm:ss', $culture, $styles, [ref]$parsed)) { return $parsed }
        }
        return $null
    }

    function ConvertFrom-RecentChangeInstallDate {
        param([string]$InstallDate)

        if ([string]::IsNullOrWhiteSpace($InstallDate) -or $InstallDate -notmatch '^\d{8}$') { return $null }
        $parsed = [datetime]::MinValue
        if ([datetime]::TryParseExact($InstallDate, 'yyyyMMdd', [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeLocal, [ref]$parsed)) {
            return $parsed
        }
        return $null
    }

    function New-RecentChangeFinding {
        param(
            [ValidateSet('CRITICAL', 'WARN', 'INFO')][string]$Severity = 'INFO',
            [int]$Priority = 80,
            [string]$Category = 'General',
            [Nullable[datetime]]$Timestamp = $null,
            [string]$Source = '',
            [string]$Item = '',
            [string]$ChangeType = '',
            [string]$Evidence = '',
            [string]$Confidence = 'Medium',
            [string]$LikelyImpact = '',
            [string]$SuggestedNextStep = '',
            [string]$SuggestedRepairSwitch = '',
            [string]$Path = ''
        )

        [PSCustomObject]@{
            Severity              = $Severity
            Priority              = $Priority
            Category              = $Category
            Timestamp             = $Timestamp
            Source                = $Source
            Item                  = $Item
            ChangeType            = $ChangeType
            Evidence              = ConvertTo-RecentChangeShortText -Text $Evidence -MaxLength 600
            Confidence            = $Confidence
            LikelyImpact          = $LikelyImpact
            SuggestedNextStep     = $SuggestedNextStep
            SuggestedRepairSwitch = $SuggestedRepairSwitch
            Path                  = $Path
        }
    }

    function Add-RecentChangeFinding {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [ValidateSet('CRITICAL', 'WARN', 'INFO')][string]$Severity = 'INFO',
            [int]$Priority = 80,
            [string]$Category = 'General',
            [Nullable[datetime]]$Timestamp = $null,
            [string]$Source = '',
            [string]$Item = '',
            [string]$ChangeType = '',
            [string]$Evidence = '',
            [string]$Confidence = 'Medium',
            [string]$LikelyImpact = '',
            [string]$SuggestedNextStep = '',
            [string]$SuggestedRepairSwitch = '',
            [string]$Path = ''
        )

        $Findings.Add((New-RecentChangeFinding -Severity $Severity -Priority $Priority -Category $Category -Timestamp $Timestamp -Source $Source -Item $Item -ChangeType $ChangeType -Evidence $Evidence -Confidence $Confidence -LikelyImpact $LikelyImpact -SuggestedNextStep $SuggestedNextStep -SuggestedRepairSwitch $SuggestedRepairSwitch -Path $Path)) | Out-Null
    }

    function Add-RecentChangeCollectorFailure {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][string]$Collector,
            [Parameter(Mandatory = $true)][string]$ErrorText
        )

        Add-RecentChangeFinding -Findings $Findings -Severity 'INFO' -Priority 95 -Category 'Analyzer' -Timestamp (Get-Date) -Source $Collector -Item $Collector -ChangeType 'CollectorSkipped' -Evidence $ErrorText -Confidence 'High' -LikelyImpact 'This collector could not complete; other evidence is still usable.'
    }

    function Read-RecentChangeLogMatches {
        param(
            [Parameter(Mandatory = $true)][string]$Path,
            [Parameter(Mandatory = $true)][string]$Pattern,
            [Parameter(Mandatory = $true)][datetime]$Cutoff,
            [int]$Tail = 6000,
            [int]$Limit = 50
        )

        $matches = [System.Collections.Generic.List[object]]::new()
        if (-not (Test-Path -LiteralPath $Path)) { return @() }
        try {
            $lines = Get-Content -LiteralPath $Path -Tail $Tail -ErrorAction Stop
            foreach ($line in $lines) {
                if ($line -notmatch $Pattern) { continue }
                $timestamp = Get-RecentChangeTimestampFromText -Text $line
                if ($timestamp -and $timestamp -lt $Cutoff) { continue }
                $matches.Add([PSCustomObject]@{ Timestamp = $timestamp; Line = [string]$line }) | Out-Null
                if ($matches.Count -ge $Limit) { break }
            }
        }
        catch {}
        return @($matches)
    }

    function Add-RecentChangeServicingFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        $windowsRoot = Join-Path $script:WinDriveLetter 'Windows'
        $pendingXml = Join-Path $windowsRoot 'WinSxS\pending.xml'
        if (Test-Path -LiteralPath $pendingXml) {
            $pendingItem = Get-Item -LiteralPath $pendingXml -Force -ErrorAction SilentlyContinue
            Add-RecentChangeFinding -Findings $Findings -Severity 'WARN' -Priority 25 -Category 'Servicing' -Timestamp $pendingItem.LastWriteTime -Source 'pending.xml' -Item 'pending.xml' -ChangeType 'PendingServicing' -Evidence 'Windows\WinSxS\pending.xml is present.' -Confidence 'High' -LikelyImpact 'The guest may be stuck completing or rolling back servicing operations.' -SuggestedNextStep 'Review servicing state before removing pending transactions.' -SuggestedRepairSwitch '-AnalyzeServicingState / -FixPendingUpdates' -Path $pendingXml
        }

        $cbsLog = Join-Path $windowsRoot 'Logs\CBS\CBS.log'
        foreach ($entry in (Read-RecentChangeLogMatches -Path $cbsLog -Pattern 'Package_for_|KB\d{6,}|Failed|failure|error|0x800719e4|ERROR_LOG_FULL|Reboot required|corrupt|rollback|Session:' -Cutoff $Cutoff -Tail 8000 -Limit 40)) {
            $line = [string]$entry.Line
            $severity = 'INFO'
            $priority = 70
            $impact = 'Recent component servicing activity was observed.'
            $nextStep = 'Review CBS and servicing state if the boot failure began after updates.'
            $switch = '-AnalyzeServicingState'
            if ($line -match 'CSI Payload Corrupt|CSI Manifest Corrupt|CBS_E_STORE_CORRUPTION|Mark store corruption') {
                $severity = 'CRITICAL'; $priority = 15; $impact = 'Component store corruption can block updates, repair, or boot.'; $switch = '-AnalyzeComponentStore'
            }
            # Must stay above the generic Failed/error branch: an ERROR_LOG_FULL line
            # also matches 'error', and the generic branch would mis-route it to
            # -AnalyzeServicingState instead of the transaction log repair.
            elseif ($line -match '0x800719e4|ERROR_LOG_FULL') {
                $severity = 'CRITICAL'; $priority = 20
                $impact = 'The CLFS/KTM transaction logs are full, so servicing cannot commit. Updates fail and the guest can hang in the update stage.'
                $nextStep = 'Clear the transaction logs, then boot and retry the update. Reverting pending updates is not required for this failure.'
                $switch = '-FixTxRLogs'
            }
            elseif ($line -match 'Failed|failure|\[HRESULT = 0x(?!00000000)|CBS_E_|error') {
                $severity = 'WARN'; $priority = 35; $impact = 'A recent CBS package or session error may be related to update rollback or boot loops.'; $switch = '-AnalyzeServicingState'
            }
            elseif ($line -match 'Reboot required|pending') {
                $severity = 'WARN'; $priority = 40; $impact = 'Pending reboot servicing can explain update-stage boot loops.'; $switch = '-AnalyzeServicingState'
            }
            $item = if ($line -match '(KB\d{6,8})') { $Matches[1] } elseif ($line -match '(Package_for_[^,\s]+)') { $Matches[1] } else { 'CBS.log' }
            Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'Servicing' -Timestamp $entry.Timestamp -Source 'CBS.log' -Item $item -ChangeType 'ServicingLog' -Evidence $line -Confidence 'Medium' -LikelyImpact $impact -SuggestedNextStep $nextStep -SuggestedRepairSwitch $switch -Path $cbsLog
        }

        $dismLog = Join-Path $windowsRoot 'Logs\DISM\dism.log'
        foreach ($entry in (Read-RecentChangeLogMatches -Path $dismLog -Pattern 'Error|Warning|Failed|Package|RestoreHealth|ScanHealth|Add-Package|Remove-Package' -Cutoff $Cutoff -Tail 5000 -Limit 30)) {
            $line = [string]$entry.Line
            $severity = 'INFO'
            $priority = 75
            $impact = 'DISM activity was observed in the recent window.'
            if ($line -match 'Failed to create dismhost|InternalExecute failed|DismOpenSessionInternal|RestoreHealth|ScanHealth|Add-Package|Remove-Package') {
                $severity = 'WARN'; $priority = 45; $impact = 'A recent DISM operation failed or changed the servicing state.'
            }
            elseif ($line -match 'Failed to Load the provider') {
                $severity = 'INFO'; $priority = 88; $impact = 'Provider-load warnings are often non-fatal during offline DISM probing.'
            }
            Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'Servicing' -Timestamp $entry.Timestamp -Source 'DISM.log' -Item 'DISM' -ChangeType 'DismLog' -Evidence $line -Confidence 'Medium' -LikelyImpact $impact -SuggestedNextStep 'Review DISM.log only if servicing or component-store symptoms match.' -SuggestedRepairSwitch '-AnalyzeComponentStore' -Path $dismLog
        }

        Invoke-WithHive 'SOFTWARE', 'COMPONENTS' {
            & {
                $cbsRoot = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
                foreach ($subName in @('PackagesPending', 'SessionsPending', 'RebootPending')) {
                    $subPath = Join-Path $cbsRoot $subName
                    if (-not (Test-Path $subPath)) { continue }
                    $lastWrite = Get-RegistryKeyLastWriteTime -Path $subPath
                    $childCount = (Get-ChildItem $subPath -ErrorAction SilentlyContinue | Measure-Object).Count
                    $isRecentPendingMarker = ($lastWrite -and $lastWrite -ge $Cutoff)
                    $pendingSeverity = if ($isRecentPendingMarker) { 'WARN' } else { 'INFO' }
                    $pendingPriority = if ($isRecentPendingMarker) { 30 } else { 86 }
                    $pendingImpact = if ($isRecentPendingMarker) { 'Recent pending servicing registry markers can indicate interrupted updates or rollback loops.' } else { 'Pending servicing registry markers exist, but their key timestamp is outside the selected recent-change window.' }
                    Add-RecentChangeFinding -Findings $Findings -Severity $pendingSeverity -Priority $pendingPriority -Category 'Servicing' -Timestamp $lastWrite -Source 'CBS registry' -Item $subName -ChangeType 'PendingServicingRegistry' -Evidence "$subName exists with $childCount child item(s)." -Confidence 'High' -LikelyImpact $pendingImpact -SuggestedNextStep 'Review servicing state and CBS log before applying repairs.' -SuggestedRepairSwitch '-AnalyzeServicingState' -Path $subPath
                }

                $componentRoot = 'HKLM:\BROKENCOMPONENTS'
                $componentProps = Get-ItemProperty $componentRoot -ErrorAction SilentlyContinue
                if ($componentProps) {
                    foreach ($propertyName in @('ExecutionState', 'PendingXmlIdentifier', 'StoreDirty')) {
                        $propertyValue = $componentProps.$propertyName
                        if ($null -eq $propertyValue -or $propertyValue -eq 0 -or $propertyValue -eq '') { continue }
                        $lastWrite = Get-RegistryKeyLastWriteTime -Path $componentRoot
                        Add-RecentChangeFinding -Findings $Findings -Severity 'WARN' -Priority 35 -Category 'Servicing' -Timestamp $lastWrite -Source 'COMPONENTS hive' -Item $propertyName -ChangeType 'ComponentStoreState' -Evidence "$propertyName = $propertyValue" -Confidence 'High' -LikelyImpact 'The COMPONENTS hive records active or dirty servicing state.' -SuggestedNextStep 'Review CBS pending state and avoid blind package removal.' -SuggestedRepairSwitch '-AnalyzeServicingState' -Path $componentRoot
                    }
                }
            }
        }
    }

    function Add-RecentChangeSetupApiFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        $infRoot = Join-Path $script:WinDriveLetter 'Windows\INF'
        $logs = @(
            @{ Name = 'setupapi.dev.log'; Path = (Join-Path $infRoot 'setupapi.dev.log') }
            @{ Name = 'setupapi.app.log'; Path = (Join-Path $infRoot 'setupapi.app.log') }
            @{ Name = 'setupapi.offline.log'; Path = (Join-Path $infRoot 'setupapi.offline.log') }
        )

        foreach ($log in $logs) {
            if (-not (Test-Path -LiteralPath $log.Path)) { continue }
            $currentSection = ''
            $sectionStart = $null
            $reported = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            $offlineHiveUnloadMatches = [System.Collections.Generic.List[object]]::new()
            try {
                foreach ($line in (Get-Content -LiteralPath $log.Path -Tail 7000 -ErrorAction Stop)) {
                    if ($line -match '^>>>\s+\[(.+)\]') {
                        $currentSection = $Matches[1]
                        continue
                    }
                    if ($line -match '^>>>\s+Section start\s+(.+)$') {
                        $sectionStart = Get-RecentChangeTimestampFromText -Text $line
                        continue
                    }
                    if (-not $sectionStart -or $sectionStart -lt $Cutoff) { continue }

                    if ($log.Name -eq 'setupapi.offline.log' -and $line -match '(?i)Unable to unload hive key.*Windows[\\/]+System32[\\/]+config[\\/]+(SYSTEM|DRIVERS|SOFTWARE|SECURITY|SAM|DEFAULT).*Error\s*=\s*(0x[0-9a-f]+)') {
                        $offlineHiveUnloadMatches.Add([PSCustomObject]@{
                            Timestamp = $sectionStart
                            Section   = $currentSection
                            Hive      = $Matches[1].ToUpperInvariant()
                            Error     = $Matches[2]
                        }) | Out-Null
                        continue
                    }

                    if ($line -notmatch 'Configure Driver Package|Publish Driver Package|Unpublish Driver Package|Driver Package\s*=|Exit status|!!!|failed|error|Device Install|Driver Install') { continue }

                    $severity = 'INFO'
                    $priority = 72
                    $impact = 'Recent driver or device setup activity was recorded.'
                    if ($line -match '^<<<\s+\[Exit status:\s*SUCCESS\]') {
                        $severity = 'INFO'; $priority = 82; $impact = 'Recent setupapi section completed successfully; supporting timeline evidence only.'
                    }
                    elseif ($line -match '!!!|failed|error|exit\(0x(?!00000000)|Exit status:\s*(?!SUCCESS)') {
                        $severity = 'WARN'; $priority = 28; $impact = 'Failed driver/device setup can cause boot, storage, network, or device initialization problems.'
                    }
                    elseif ($currentSection -match 'Device Install|Driver Install|Install Driver Updates') {
                        $priority = 55
                    }

                    $item = if ($line -match 'FileRepository\\([^\\]+)\\([^\\]+\.inf)') { $Matches[2] } elseif ($line -match 'Driver Package\s*=\s*(\S+)') { $Matches[1] } elseif ($currentSection) { $currentSection } else { $log.Name }
                    $key = "$($log.Name)|$sectionStart|$item|$severity|$line"
                    if (-not $reported.Add($key)) { continue }
                    Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'DriverSetup' -Timestamp $sectionStart -Source $log.Name -Item $item -ChangeType $currentSection -Evidence $line -Confidence 'Medium' -LikelyImpact $impact -SuggestedNextStep 'Correlate this INF/device with Services, DriverStore, and Kernel-PnP evidence.' -SuggestedRepairSwitch '-GetServicesReport -IssuesOnly' -Path $log.Path
                    if ($reported.Count -ge 60) { break }
                }
            }
            catch {}

            if ($offlineHiveUnloadMatches.Count -gt 0) {
                $latest = @($offlineHiveUnloadMatches | Sort-Object Timestamp -Descending | Select-Object -First 1)[0]
                $hives = (@($offlineHiveUnloadMatches | Select-Object -ExpandProperty Hive -Unique | Sort-Object) -join ', ')
                $errors = (@($offlineHiveUnloadMatches | Select-Object -ExpandProperty Error -Unique | Sort-Object) -join ', ')
                $sections = (@($offlineHiveUnloadMatches | Select-Object -ExpandProperty Section -Unique | Where-Object { $_ } | Select-Object -First 4) -join '; ')
                $firstTime = @($offlineHiveUnloadMatches | Sort-Object Timestamp | Select-Object -First 1)[0].Timestamp
                $timeText = if ($firstTime -and $latest.Timestamp -and $firstTime -ne $latest.Timestamp) { "$($firstTime.ToString('yyyy-MM-dd HH:mm:ss')) to $($latest.Timestamp.ToString('yyyy-MM-dd HH:mm:ss'))" } elseif ($latest.Timestamp) { $latest.Timestamp.ToString('yyyy-MM-dd HH:mm:ss') } else { 'timestamp unavailable' }
                $evidence = "Collapsed $($offlineHiveUnloadMatches.Count) repeated offline hive-unload cleanup line(s); Hives=$hives; Error=$errors; Time=$timeText"
                if ($sections) { $evidence += "; Sections=$sections" }

                Add-RecentChangeFinding -Findings $Findings -Severity 'INFO' -Priority 84 -Category 'DriverSetup' -Timestamp $latest.Timestamp -Source $log.Name -Item 'Offline registry hive unload cleanup' -ChangeType 'OfflineHiveUnloadCleanup' -Evidence $evidence -Confidence 'Medium' -LikelyImpact 'Offline driver servicing could not unload temporary registry hives. This is usually cleanup noise unless it aligns with the boot failure time or nearby driver-package errors.' -SuggestedNextStep 'Use this as timeline context only; prioritize actual setupapi failure lines, boot-critical services/files, and registry changes first.' -SuggestedRepairSwitch '-GetServicesReport -IssuesOnly' -Path $log.Path
            }
        }
    }

    function Add-RecentChangeServiceFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        Invoke-WithHive 'SYSTEM' {
            & {
                $systemRoot = Get-SystemRootPath
                $servicesRoot = "$systemRoot\Services"
                if (-not (Test-Path $servicesRoot)) { return }
                $startNames = @{ 0 = 'Boot'; 1 = 'System'; 2 = 'Automatic'; 3 = 'Manual'; 4 = 'Disabled' }
                $typeNames = @{ 1 = 'KernelDriver'; 2 = 'FileSystemDriver'; 4 = 'Adapter'; 8 = 'RecognizerDriver'; 16 = 'Win32OwnProcess'; 32 = 'Win32ShareProcess'; 256 = 'Interactive' }
                $importantServices = @{
                    TermService              = @{ Role = 'Remote access (RDP)'; Priority = 30; DisabledImpact = 'Remote Desktop Services is disabled; this directly explains no RDP even when the guest boots successfully.' }
                    WinRM                    = @{ Role = 'Remote access (WinRM)'; Priority = 31; DisabledImpact = 'Windows Remote Management is disabled; PowerShell remoting and automation access will fail.' }
                    WindowsAzureGuestAgent   = @{ Role = 'Azure VM agent'; Priority = 32; DisabledImpact = 'The Azure VM Guest Agent is disabled; Azure extensions, health reporting, and some recovery workflows can fail.' }
                    RdAgent                  = @{ Role = 'Azure fabric/guest agent'; Priority = 32; DisabledImpact = 'The Azure RdAgent service is disabled; Azure guest/fabric integration may be impaired.' }
                    WindowsAzureTelemetryService = @{ Role = 'Azure telemetry agent'; Priority = 54; DisabledImpact = 'The Azure telemetry service is disabled; this is usually not a boot blocker, but can affect platform visibility.' }
                    Dhcp                     = @{ Role = 'Network connectivity'; Priority = 34; DisabledImpact = 'DHCP Client is disabled; the VM may boot without a usable IP address.' }
                    Dnscache                 = @{ Role = 'Network name resolution'; Priority = 36; DisabledImpact = 'DNS Client is disabled; network may appear up while name resolution fails.' }
                    NlaSvc                   = @{ Role = 'Network profile detection'; Priority = 40; DisabledImpact = 'Network Location Awareness is disabled; firewall/profile behavior and domain detection can be wrong.' }
                    Netlogon                 = @{ Role = 'Domain connectivity'; Priority = 38; DisabledImpact = 'Netlogon is disabled; domain authentication and domain-dependent services can fail.' }
                    LanmanWorkstation        = @{ Role = 'SMB/client networking'; Priority = 42; DisabledImpact = 'Workstation service is disabled; SMB client access and domain resource access can fail.' }
                    LanmanServer             = @{ Role = 'SMB/server networking'; Priority = 48; DisabledImpact = 'Server service is disabled; inbound SMB/admin-share access can fail.' }
                    RpcSs                    = @{ Role = 'Core service control'; Priority = 28; DisabledImpact = 'Remote Procedure Call is disabled; Windows service control and many core components cannot function correctly.' }
                    EventLog                 = @{ Role = 'Core logging/service dependency'; Priority = 52; DisabledImpact = 'Windows Event Log is disabled; diagnostics and dependent services can be impaired.' }
                    PlugPlay                 = @{ Role = 'Device initialization'; Priority = 35; DisabledImpact = 'Plug and Play is disabled; device initialization and driver binding can fail.' }
                }
                $reportedCount = 0
                foreach ($serviceKey in (Get-ChildItem $servicesRoot -ErrorAction SilentlyContinue)) {
                    if ($reportedCount -ge 80) { break }
                    $serviceName = [string]$serviceKey.PSChildName
                    $serviceRole = if ($importantServices.ContainsKey($serviceName)) { $importantServices[$serviceName] } else { $null }
                    $props = Get-ItemProperty -Path $serviceKey.PSPath -ErrorAction SilentlyContinue
                    if (-not $props -or $null -eq $props.Start -or $null -eq $props.Type) { continue }
                    $typeValue = [int]$props.Type
                    $isDriverType = (($typeValue -band 0x0F) -ne 0)
                    $isWin32ServiceType = (($typeValue -band 0x30) -ne 0)
                    if (-not ($isDriverType -or $isWin32ServiceType)) { continue }
                    $startValue = [int]$props.Start
                    $keyLastWrite = Get-RegistryKeyLastWriteTime -Path $serviceKey.Name
                    $imageRaw = if ($props.ImagePath) { [string]$props.ImagePath } else { '' }
                    $imagePath = if ($imageRaw) { Resolve-GuestImagePath $imageRaw } else { '' }
                    $fileItem = if ($imagePath -and (Test-Path -LiteralPath $imagePath)) { Get-Item -LiteralPath $imagePath -Force -ErrorAction SilentlyContinue } else { $null }
                    $fileLastWrite = if ($fileItem) { $fileItem.LastWriteTime } else { $null }
                    $isRecentKey = ($keyLastWrite -and $keyLastWrite -ge $Cutoff)
                    $isRecentBinary = ($fileLastWrite -and $fileLastWrite -ge $Cutoff)
                    $isRecent = ($isRecentKey -or $isRecentBinary)
                    $binaryMissing = ($imageRaw -and -not $fileItem)
                    $binaryZero = ($fileItem -and $fileItem.Length -eq 0)
                    $vendor = 'N/A'
                    $isMicrosoft = $false
                    if ($fileItem) {
                        $vendor = if ($fileItem.VersionInfo.CompanyName) { $fileItem.VersionInfo.CompanyName.Trim() } else { '(no version info)' }
                        $isMicrosoft = ($vendor -match 'Microsoft')
                    }
                    $isBootOrSystem = ($startValue -in @(0, 1))
                    $isAutomatic = ($startValue -eq 2)
                    $isSevere = ($null -ne $props.ErrorControl -and [int]$props.ErrorControl -ge 2)
                    $interesting = $isRecent -or (($binaryMissing -or $binaryZero) -and $isBootOrSystem)
                    if (-not $interesting) { continue }

                    $severity = 'INFO'
                    $priority = 78
                    $impact = 'A driver/service registry key or binary changed recently.'
                    $suggested = '-GetServicesReport -IssuesOnly'
                    if (($binaryMissing -or $binaryZero) -and $isBootOrSystem) {
                        $severity = 'CRITICAL'; $priority = 12; $impact = 'A Boot/System driver with a missing or zero-byte binary can block boot.'; $suggested = if ($fileItem -and $fileItem.Length -eq 0) { '-RepairSystemFile <driver.sys>' } else { '-GetServicesReport -IssuesOnly' }
                    }
                    elseif ($isRecentBinary -and $isBootOrSystem -and -not $isMicrosoft) {
                        $severity = 'WARN'; $priority = 22; $impact = 'A recent non-Microsoft Boot/System driver binary change is a strong boot-failure suspect.'; $suggested = '-DisableDriverOrService <name> after snapshot/backup'
                    }
                    elseif ($isRecentBinary -and $isSevere -and -not $isMicrosoft) {
                        $severity = 'WARN'; $priority = 32; $impact = 'A recent non-Microsoft driver binary with Severe/Critical ErrorControl can fail closed during boot.'
                    }
                    elseif ($isRecentKey -and $isBootOrSystem -and -not $isMicrosoft) {
                        $severity = 'INFO'; $priority = 76; $impact = 'A non-Microsoft Boot/System driver service key changed recently, but the driver binary timestamp did not. Treat as supporting evidence only.'; $suggested = '-GetServicesReport -IssuesOnly'
                    }
                    elseif ($isRecent -and $isBootOrSystem) {
                        $severity = 'INFO'; $priority = 60; $impact = 'A Microsoft Boot/System driver changed recently; correlate with updates before treating it as suspicious.'
                    }
                    elseif ($isRecentKey -and $serviceRole -and $startValue -eq 4) {
                        $severity = 'WARN'; $priority = [int]$serviceRole.Priority; $impact = [string]$serviceRole.DisabledImpact; $suggested = '-LoadHive SYSTEM / -GetServicesReport -IssuesOnly'
                    }
                    elseif ($isRecentKey -and $serviceRole) {
                        $severity = 'INFO'; $priority = 58; $impact = "A service involved in $($serviceRole.Role) changed recently. Treat as timeline evidence unless the symptom matches."
                    }
                    elseif (($binaryMissing -or $binaryZero) -and $isWin32ServiceType -and $isAutomatic -and -not $isMicrosoft) {
                        $severity = 'WARN'; $priority = 44; $impact = 'An automatic non-Microsoft service points to a missing or empty executable; this can break agent, networking, security, or application startup.'
                    }
                    elseif ($isRecentKey -and $isWin32ServiceType -and $isAutomatic -and -not $isMicrosoft) {
                        $severity = 'WARN'; $priority = 48; $impact = 'An automatic non-Microsoft service configuration changed recently. This is a common footprint of agent, updater, security, or application changes.'
                    }
                    elseif ($isRecentKey -and $isWin32ServiceType) {
                        $severity = 'INFO'; $priority = 70; $impact = 'A Win32 service registry key changed recently; treat as timeline evidence unless it lines up with the failure or another warning.'
                    }

                    $timestampCandidates = @($keyLastWrite, $fileLastWrite) | Where-Object { $_ } | Sort-Object -Descending
                    $timestamp = @($timestampCandidates | Select-Object -First 1)[0]
                    $startName = if ($startNames.ContainsKey($startValue)) { $startNames[$startValue] } else { "Start=$startValue" }
                    $typeLabelParts = @($typeNames.Keys | Where-Object { ($typeValue -band $_) -ne 0 } | Sort-Object | ForEach-Object { $typeNames[$_] })
                    $typeLabel = if ($typeLabelParts.Count -gt 0) { $typeLabelParts -join '+' } else { "Type=$typeValue" }
                    $evidence = "Start=$startName; Type=$typeValue ($typeLabel); ErrorControl=$($props.ErrorControl); Vendor=$vendor; ImagePath=$imageRaw"
                    if ($serviceRole) { $evidence += "; Role=$($serviceRole.Role)" }
                    if ($keyLastWrite) { $evidence += "; KeyLastWrite=$($keyLastWrite.ToString('yyyy-MM-dd HH:mm:ss'))" }
                    if ($fileLastWrite) { $evidence += "; BinaryLastWrite=$($fileLastWrite.ToString('yyyy-MM-dd HH:mm:ss'))" }
                    if ($binaryMissing) { $evidence += '; Binary missing' }
                    if ($binaryZero) { $evidence += '; Binary is 0 bytes' }
                    Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'DriversServices' -Timestamp $timestamp -Source 'SYSTEM Services' -Item $serviceKey.PSChildName -ChangeType 'ServiceKeyOrBinary' -Evidence $evidence -Confidence 'Medium' -LikelyImpact $impact -SuggestedNextStep 'Use the services report and setupapi evidence to decide whether this service should be disabled, restored, or repaired.' -SuggestedRepairSwitch $suggested -Path $serviceKey.Name
                    $reportedCount++
                }
            }
        }
    }

    function Add-RecentChangeRegistryRiskFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            & {
                $systemRoot = Get-SystemRootPath
                $sessionManagerPath = "$systemRoot\Control\Session Manager"
                $sessionLastWrite = Get-RegistryKeyLastWriteTime -Path $sessionManagerPath
                if ($sessionLastWrite -and $sessionLastWrite -ge $Cutoff -and (Test-Path $sessionManagerPath)) {
                    $sessionProps = Get-ItemProperty $sessionManagerPath -ErrorAction SilentlyContinue
                    foreach ($propertyName in @('BootExecute', 'SetupExecute', 'PendingFileRenameOperations')) {
                        $value = $sessionProps.$propertyName
                        if ($null -eq $value) { continue }
                        $valueText = if ($value -is [array]) { $value -join '; ' } else { [string]$value }
                        $severity = if ($propertyName -eq 'BootExecute' -and $valueText -match '^autocheck autochk \*$') { 'INFO' } else { 'WARN' }
                        $priority = if ($severity -eq 'WARN') { 26 } else { 68 }
                        Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'BootRegistry' -Timestamp $sessionLastWrite -Source 'Session Manager' -Item $propertyName -ChangeType 'RegistryValue' -Evidence "$propertyName = $valueText" -Confidence 'High' -LikelyImpact 'Session Manager startup commands can hang boot before logon if they reference missing or problematic binaries.' -SuggestedNextStep 'Review Session Manager startup commands before booting.' -SuggestedRepairSwitch '-FixSessionManager' -Path $sessionManagerPath
                    }
                }

                $winlogonPath = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'
                $winlogonLastWrite = Get-RegistryKeyLastWriteTime -Path $winlogonPath
                if ($winlogonLastWrite -and $winlogonLastWrite -ge $Cutoff -and (Test-Path $winlogonPath)) {
                    $winlogonProps = Get-ItemProperty $winlogonPath -ErrorAction SilentlyContinue
                    $shell = [string]$winlogonProps.Shell
                    $userinit = [string]$winlogonProps.Userinit
                    if ($shell -and $shell -ne 'explorer.exe') {
                        Add-RecentChangeFinding -Findings $Findings -Severity 'WARN' -Priority 24 -Category 'LogonRegistry' -Timestamp $winlogonLastWrite -Source 'Winlogon' -Item 'Shell' -ChangeType 'RegistryValue' -Evidence "Shell=$shell" -Confidence 'High' -LikelyImpact 'A non-default shell can cause black screen or missing desktop after boot.' -SuggestedNextStep 'Validate the shell path and source of the change.' -SuggestedRepairSwitch '-FixWinlogon' -Path $winlogonPath
                    }
                    if ($userinit -and $userinit -notmatch '(?i)userinit\.exe') {
                        Add-RecentChangeFinding -Findings $Findings -Severity 'WARN' -Priority 24 -Category 'LogonRegistry' -Timestamp $winlogonLastWrite -Source 'Winlogon' -Item 'Userinit' -ChangeType 'RegistryValue' -Evidence "Userinit=$userinit" -Confidence 'High' -LikelyImpact 'A non-default Userinit value can prevent interactive logon.' -SuggestedNextStep 'Validate Userinit and restore defaults if needed.' -SuggestedRepairSwitch '-FixWinlogon' -Path $winlogonPath
                    }
                }

                $runPaths = @(
                    'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Run',
                    'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
                    'HKLM:\BROKENSOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Run',
                    'HKLM:\BROKENSOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\RunOnce'
                )
                foreach ($runPath in $runPaths) {
                    if (-not (Test-Path $runPath)) { continue }
                    $lastWrite = Get-RegistryKeyLastWriteTime -Path $runPath
                    if (-not $lastWrite -or $lastWrite -lt $Cutoff) { continue }
                    $runProps = Get-ItemProperty $runPath -ErrorAction SilentlyContinue
                    $entries = @($runProps.PSObject.Properties | Where-Object { $_.Name -notin @('PSPath', 'PSParentPath', 'PSChildName', 'PSDrive', 'PSProvider') })
                    foreach ($entry in ($entries | Select-Object -First 12)) {
                        Add-RecentChangeFinding -Findings $Findings -Severity 'INFO' -Priority 76 -Category 'Startup' -Timestamp $lastWrite -Source (Split-Path -Leaf $runPath) -Item $entry.Name -ChangeType 'StartupRegistry' -Evidence "$($entry.Name) = $($entry.Value)" -Confidence 'Medium' -LikelyImpact 'Recent autoruns can affect startup/logon, but are not boot blockers by themselves.' -SuggestedNextStep 'Review startup programs if boot reaches logon then hangs.' -SuggestedRepairSwitch '-ListStartupPrograms / -DisableStartupPrograms' -Path $runPath
                    }
                }

                $controlSetName = Get-CurrentOfflineControlSetName
                $classRoot = "HKLM:\BROKENSYSTEM\$controlSetName\Control\Class"
                foreach ($classSpec in (Get-DeviceClassFilterSpec)) {
                    $classPath = "$classRoot\$($classSpec.GUID)"
                    if (-not (Test-Path $classPath)) { continue }
                    $lastWrite = Get-RegistryKeyLastWriteTime -Path $classPath
                    $classProps = Get-ItemProperty $classPath -ErrorAction SilentlyContinue
                    foreach ($filterType in @('UpperFilters', 'LowerFilters')) {
                        $filters = @($classProps.$filterType | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object { $_.Trim() })
                        if ($filters.Count -eq 0) { continue }
                        $unsafe = @($filters | Where-Object { $classSpec.SafeFilters -inotcontains $_ })
                        if ($unsafe.Count -eq 0 -and (-not $lastWrite -or $lastWrite -lt $Cutoff)) { continue }
                        $severity = if ($unsafe.Count -gt 0 -and $classSpec.Risk -eq 'CRITICAL') { 'WARN' } else { 'INFO' }
                        $priority = if ($severity -eq 'WARN') { 23 } else { 74 }
                        $evidence = "$filterType = $($filters -join ', ')"
                        if ($unsafe.Count -gt 0) { $evidence += "; non-safe-list entries: $($unsafe -join ', ')" }
                        Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'DeviceFilters' -Timestamp $lastWrite -Source 'Class filters' -Item $classSpec.Name -ChangeType $filterType -Evidence $evidence -Confidence 'High' -LikelyImpact $classSpec.Description -SuggestedNextStep 'Review filter drivers and binaries before booting.' -SuggestedRepairSwitch '-FixDeviceFilters' -Path $classPath
                    }
                }
            }
        }
    }

    function Add-RecentChangeSoftwareFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        Invoke-WithHive 'SOFTWARE' {
            & {
                $uninstallRoots = @(
                    'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
                    'HKLM:\BROKENSOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
                )
                $reportedCount = 0
                foreach ($root in $uninstallRoots) {
                    if (-not (Test-Path $root)) { continue }
                    foreach ($appKey in (Get-ChildItem $root -ErrorAction SilentlyContinue)) {
                        if ($reportedCount -ge 50) { break }
                        $props = Get-ItemProperty $appKey.PSPath -ErrorAction SilentlyContinue
                        if (-not $props -or [string]::IsNullOrWhiteSpace($props.DisplayName)) { continue }
                        $lastWrite = Get-RegistryKeyLastWriteTime -Path $appKey.Name
                        $installDate = ConvertFrom-RecentChangeInstallDate -InstallDate ([string]$props.InstallDate)
                        $timestamp = if ($installDate) { $installDate } else { $lastWrite }
                        if (-not $timestamp -or $timestamp -lt $Cutoff) { continue }
                        $publisher = if ($props.Publisher) { [string]$props.Publisher } else { '' }
                        $name = [string]$props.DisplayName
                        $riskySoftware = ($name -match '(?i)driver|vpn|filter|network|backup|endpoint|security|antivirus|defender|crowd|sentinel|carbon|zscaler|globalprotect|storage|disk' -or $publisher -match '(?i)crowd|sentinel|carbon|zscaler|palo alto|cisco|symantec|mcafee|trend|veeam|commvault')
                        $isMicrosoft = ($publisher -match 'Microsoft')
                        $severity = if ($riskySoftware -and -not $isMicrosoft) { 'WARN' } else { 'INFO' }
                        $priority = if ($severity -eq 'WARN') { 42 } else { 82 }
                        $evidence = "Publisher=$publisher; Version=$($props.DisplayVersion); InstallDate=$($props.InstallDate)"
                        Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'Software' -Timestamp $timestamp -Source 'Uninstall registry' -Item $name -ChangeType 'InstalledOrModifiedSoftware' -Evidence $evidence -Confidence 'Medium' -LikelyImpact 'Recently installed or modified software may have added drivers, filters, services, or startup tasks.' -SuggestedNextStep 'Correlate this software with services, drivers, filters, and setupapi evidence.' -SuggestedRepairSwitch '-ListStartupPrograms / -GetServicesReport -IssuesOnly' -Path $appKey.Name
                        $reportedCount++
                    }
                }
            }
        }
    }

    function Add-RecentChangeFileFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        $windowsRoot = Join-Path $script:WinDriveLetter 'Windows'
        $netvscCandidate = Resolve-DriverBinaryCandidate -Binary 'netvsc.sys' -AlternatePatterns @('netvsc*.sys')
        $netvscName = if ($netvscCandidate.Exists) { $netvscCandidate.Name } else { 'netvsc.sys' }
        $criticalFiles = @(
            @{ Name = 'BCD store'; Path = (Get-BcdStorePath -BootDrive $script:BootDriveLetter -Generation $script:VMGen); Category = 'BootFiles'; Signed = $false }
            @{ Name = 'winload'; Path = (Join-Path $script:WinDriveLetter $(if ($script:VMGen -eq 2) { 'Windows\System32\winload.efi' } else { 'Windows\System32\winload.exe' })); Category = 'BootFiles'; Signed = $true }
            @{ Name = 'ntoskrnl.exe'; Path = (Join-Path $windowsRoot 'System32\ntoskrnl.exe'); Category = 'BootFiles'; Signed = $true }
            @{ Name = 'hal.dll'; Path = (Join-Path $windowsRoot 'System32\hal.dll'); Category = 'BootFiles'; Signed = $true }
            @{ Name = 'ci.dll'; Path = (Join-Path $windowsRoot 'System32\ci.dll'); Category = 'BootFiles'; Signed = $true }
            @{ Name = 'smss.exe'; Path = (Join-Path $windowsRoot 'System32\smss.exe'); Category = 'LogonFiles'; Signed = $true }
            @{ Name = 'wininit.exe'; Path = (Join-Path $windowsRoot 'System32\wininit.exe'); Category = 'LogonFiles'; Signed = $true }
            @{ Name = 'services.exe'; Path = (Join-Path $windowsRoot 'System32\services.exe'); Category = 'LogonFiles'; Signed = $true }
            @{ Name = 'lsass.exe'; Path = (Join-Path $windowsRoot 'System32\lsass.exe'); Category = 'LogonFiles'; Signed = $true }
            @{ Name = 'winlogon.exe'; Path = (Join-Path $windowsRoot 'System32\winlogon.exe'); Category = 'LogonFiles'; Signed = $true }
            @{ Name = 'vmbus.sys'; Path = (Join-Path $windowsRoot 'System32\drivers\vmbus.sys'); Category = 'DriverFiles'; Signed = $true }
            @{ Name = 'storvsc.sys'; Path = (Join-Path $windowsRoot 'System32\drivers\storvsc.sys'); Category = 'DriverFiles'; Signed = $true }
            @{ Name = $netvscName; Path = $netvscCandidate.Path; Category = 'DriverFiles'; Signed = $true }
        )

        foreach ($fileSpec in $criticalFiles) {
            $fileItem = Get-Item -LiteralPath $fileSpec.Path -Force -ErrorAction SilentlyContinue
            if (-not $fileItem) {
                Add-RecentChangeFinding -Findings $Findings -Severity 'CRITICAL' -Priority 10 -Category $fileSpec.Category -Timestamp $null -Source 'Critical file inventory' -Item $fileSpec.Name -ChangeType 'MissingCriticalFile' -Evidence 'Critical boot/logon artifact is missing.' -Confidence 'High' -LikelyImpact 'Missing boot, kernel, session, or Azure synthetic driver files can prevent startup.' -SuggestedNextStep 'Confirm whether the file is expected for this OS and restore from WinSxS or a known-good source.' -SuggestedRepairSwitch '-AnalyzeCriticalBootFiles / -RepairSystemFile <name>' -Path $fileSpec.Path
                continue
            }
            if ($fileItem.Length -eq 0) {
                Add-RecentChangeFinding -Findings $Findings -Severity 'CRITICAL' -Priority 10 -Category $fileSpec.Category -Timestamp $fileItem.LastWriteTime -Source 'Critical file inventory' -Item $fileSpec.Name -ChangeType 'ZeroByteCriticalFile' -Evidence 'Critical file exists but is 0 bytes.' -Confidence 'High' -LikelyImpact 'A zero-byte critical binary can prevent boot or logon.' -SuggestedNextStep 'Restore the file from WinSxS or a known-good source.' -SuggestedRepairSwitch '-RepairSystemFile <name>' -Path $fileSpec.Path
                continue
            }
            if ($fileItem.LastWriteTime -lt $Cutoff) { continue }
            $severity = 'INFO'
            $priority = 76
            $evidence = "LastWriteTime=$($fileItem.LastWriteTime); Size=$($fileItem.Length)"
            if ($fileSpec.Signed) {
                $signature = Test-MicrosoftSignature -FilePath $fileSpec.Path
                $evidence += "; Trust=$($signature.TrustState); Signature=$($signature.Status); Subject=$($signature.SignerSubject)"
                if ($signature.IsHardFailure) { $severity = 'CRITICAL'; $priority = 10 }
                elseif (-not $signature.IsAcceptableMicrosoft) { $severity = 'WARN'; $priority = 18 }
            }
            Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category $fileSpec.Category -Timestamp $fileItem.LastWriteTime -Source 'Critical file timestamp' -Item $fileSpec.Name -ChangeType 'RecentCriticalFileTimestamp' -Evidence $evidence -Confidence 'Medium' -LikelyImpact 'A recently modified critical file should be correlated with servicing or driver installation evidence.' -SuggestedNextStep 'Use file health and servicing analysis before replacing files.' -SuggestedRepairSwitch '-AnalyzeCriticalBootFiles' -Path $fileSpec.Path
        }

        $driversRoot = Join-Path $windowsRoot 'System32\drivers'
        if (Test-Path -LiteralPath $driversRoot) {
            foreach ($driverFile in (Get-ChildItem -LiteralPath $driversRoot -Filter '*.sys' -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $Cutoff } | Sort-Object LastWriteTime -Descending | Select-Object -First 40)) {
                $signature = Test-MicrosoftSignature -FilePath $driverFile.FullName
                $severity = if ($signature.IsHardFailure) { 'CRITICAL' } elseif ($signature.IsAcceptableMicrosoft) { 'INFO' } else { 'WARN' }
                $priority = if ($severity -eq 'CRITICAL') { 10 } elseif ($severity -eq 'WARN') { 34 } else { 84 }
                Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'DriverFiles' -Timestamp $driverFile.LastWriteTime -Source 'System32\drivers' -Item $driverFile.Name -ChangeType 'RecentDriverFile' -Evidence "Size=$($driverFile.Length); Company=$($driverFile.VersionInfo.CompanyName); Trust=$($signature.TrustState); Signature=$($signature.Status)" -Confidence 'Medium' -LikelyImpact 'A recently modified driver file may correspond to an update or third-party driver install.' -SuggestedNextStep 'Correlate with Services and setupapi evidence before disabling anything.' -SuggestedRepairSwitch '-GetServicesReport -IssuesOnly' -Path $driverFile.FullName
            }
        }

        $driverStoreRoot = Join-Path $windowsRoot 'System32\DriverStore\FileRepository'
        if (Test-Path -LiteralPath $driverStoreRoot) {
            foreach ($driverStoreDir in (Get-ChildItem -LiteralPath $driverStoreRoot -Directory -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $Cutoff } | Sort-Object LastWriteTime -Descending | Select-Object -First 40)) {
                $severity = if ($driverStoreDir.Name -match '(?i)stor|disk|scsi|net|ndis|filter|vpn|av|edr|crowd|sentinel|zscaler|globalprotect') { 'WARN' } else { 'INFO' }
                $priority = if ($severity -eq 'WARN') { 46 } else { 86 }
                Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category 'DriverStore' -Timestamp $driverStoreDir.LastWriteTime -Source 'DriverStore' -Item $driverStoreDir.Name -ChangeType 'RecentDriverPackageDirectory' -Evidence "DriverStore package directory timestamp: $($driverStoreDir.LastWriteTime)" -Confidence 'Low' -LikelyImpact 'DriverStore timestamps are supporting evidence; correlate with setupapi and service keys.' -SuggestedNextStep 'Inspect matching INF/service entries before treating this as causal.' -SuggestedRepairSwitch '-GetServicesReport -IssuesOnly' -Path $driverStoreDir.FullName
            }
        }
    }

    function Add-RecentChangeEventFindings {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff
        )

        $logRoot = Join-Path $script:WinDriveLetter 'Windows\System32\winevt\Logs'
        $eventLogs = @(
            @{ Name = 'Setup'; Path = (Join-Path $logRoot 'Setup.evtx'); Category = 'ServicingEvents' }
            @{ Name = 'WindowsUpdateClient'; Path = (Join-Path $logRoot 'Microsoft-Windows-WindowsUpdateClient%4Operational.evtx'); Category = 'ServicingEvents' }
            @{ Name = 'DeviceSetupManager'; Path = (Join-Path $logRoot 'Microsoft-Windows-DeviceSetupManager%4Admin.evtx'); Category = 'DeviceEvents' }
            @{ Name = 'Kernel-PnP'; Path = (Join-Path $logRoot 'Microsoft-Windows-Kernel-PnP%4Configuration.evtx'); Category = 'DeviceEvents' }
            @{ Name = 'CodeIntegrity'; Path = (Join-Path $logRoot 'Microsoft-Windows-CodeIntegrity%4Operational.evtx'); Category = 'SecurityEvents' }
            @{ Name = 'User Profile Service'; Path = (Join-Path $logRoot 'Microsoft-Windows-User Profile Service%4Operational.evtx'); Category = 'LogonEvents' }
        )

        foreach ($eventLog in $eventLogs) {
            if (-not (Test-Path -LiteralPath $eventLog.Path)) { continue }
            try {
                $recentEvents = @(Get-WinEvent -Path $eventLog.Path -MaxEvents 120 -ErrorAction Stop | Where-Object { $_.TimeCreated -and $_.TimeCreated -ge $Cutoff } | Sort-Object TimeCreated | Select-Object -First 20)
                foreach ($eventRecord in $recentEvents) {
                    $message = [string]$eventRecord.Message
                    $severity = 'INFO'
                    $priority = 88
                    $impact = 'Supporting event-log evidence in the recent window.'
                    if ($eventRecord.LevelDisplayName -match 'Error|Critical' -or $message -match '(?i)failed|failure|cannot|0x[0-9a-f]{8}') {
                        $severity = 'WARN'; $priority = 44; $impact = 'Recent error event may correlate with update, driver, device, security, or logon failure.'
                    }
                    if ($eventLog.Name -eq 'WindowsUpdateClient' -and $eventRecord.Id -eq 25 -and $message -match '0x8024402C') {
                        $severity = 'INFO'; $priority = 92; $impact = 'Windows Update connectivity check failure; usually not a boot blocker by itself.'
                    }
                    if ($eventLog.Name -eq 'Kernel-PnP' -and $eventRecord.Id -in @(400, 410)) {
                        $priority = 80
                    }
                    $item = if ($message -match '(KB\d{6,8})') { $Matches[1] } elseif ($message -match 'Driver Name:\s*([^\r\n]+)') { $Matches[1].Trim() } else { "$($eventRecord.ProviderName)#$($eventRecord.Id)" }
                    Add-RecentChangeFinding -Findings $Findings -Severity $severity -Priority $priority -Category $eventLog.Category -Timestamp $eventRecord.TimeCreated -Source $eventLog.Name -Item $item -ChangeType "EventId $($eventRecord.Id)" -Evidence $message -Confidence 'Medium' -LikelyImpact $impact -SuggestedNextStep 'Correlate this event with registry, file, setupapi, and servicing evidence.' -SuggestedRepairSwitch '' -Path $eventLog.Path
                }
            }
            catch {
                if ($_.Exception.Message -notmatch 'No events were found') {
                    Add-RecentChangeCollectorFailure -Findings $Findings -Collector $eventLog.Name -ErrorText $_.Exception.Message
                }
            }
        }
    }

    function Get-RecentChangeInsights {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings
        )

        $insights = [System.Collections.Generic.List[object]]::new()
        if ($Findings.Count -eq 0) { return [object[]]@() }

        $criticalsAndWarns = @($Findings | Where-Object { $_.Severity -in @('CRITICAL', 'WARN') })
        $addInsight = {
            param($sev, $title, $why, $support, $action, $conf)
            $insights.Add([pscustomobject]@{
                Severity           = $sev
                Title              = $title
                WhyItMatters       = $why
                SupportingFindings = $support
                SuggestedAction    = $action
                Confidence         = $conf
            }) | Out-Null
        }

        $missingBoot = @($Findings | Where-Object { $_.Severity -eq 'CRITICAL' -and $_.Category -in @('BootFiles', 'LogonFiles', 'DriverFiles') -and $_.ChangeType -in @('MissingCriticalFile', 'ZeroByteCriticalFile') })
        if ($missingBoot.Count -gt 0) {
            & $addInsight 'CRITICAL' 'Critical boot/logon binary is missing or empty' 'A missing or 0-byte boot, kernel, session, or logon binary will prevent the guest from starting or reaching logon.' (($missingBoot | Select-Object -ExpandProperty Item -First 8) -join ', ') 'Restore the binary from WinSxS or a same-build source: -RepairSystemFile <name>' 'High'
        }

        $driverBinReg = @($Findings | Where-Object { $_.Severity -eq 'CRITICAL' -and $_.Category -eq 'DriversServices' -and $_.Evidence -match '(?i)binary (missing|is 0 bytes)' })
        if ($driverBinReg.Count -gt 0) {
            & $addInsight 'CRITICAL' 'Boot/System driver has a missing or empty binary' 'A Boot/System start driver with no binary will fail to load and can BSOD before Last Known Good recovers.' (($driverBinReg | Select-Object -ExpandProperty Item -First 8) -join ', ') 'Restore the .sys (-RepairSystemFile <driver.sys>) or disable the service (-DisableDriverOrService <name>).' 'High'
        }

        $servPending = @($Findings | Where-Object { $_.Severity -eq 'WARN' -and $_.Category -eq 'Servicing' -and ($_.ChangeType -match 'Pending|Sessions|Packages' -or $_.Evidence -match '(?i)pending\.xml|SessionsPending|PackagesPending') })
        $servErrors = @($Findings | Where-Object { $_.Severity -in @('CRITICAL', 'WARN') -and $_.Category -eq 'Servicing' -and ($_.Evidence -match '(?i)failed|failure|hresult|0x8|corrupt|rollback') })
        if ($servPending.Count -gt 0 -and $servErrors.Count -gt 0) {
            $support = ((@($servPending) + @($servErrors)) | Select-Object -ExpandProperty Item -First 6 -Unique) -join ', '
            & $addInsight 'WARN' 'Interrupted Windows Update / servicing transaction' 'Pending servicing markers combined with recent CBS/DISM errors suggest an update that did not complete cleanly. This frequently causes update-stage boot loops.' $support 'Run -AnalyzeServicingState first; then -FixPendingUpdates if that report confirms pending operations.' 'Medium'
        }

        $thirdPartyBoot = @($Findings | Where-Object { $_.Severity -eq 'WARN' -and $_.Category -eq 'DriversServices' -and $_.Evidence -notmatch '(?i)vendor=.*microsoft' -and $_.Evidence -match '(?i)start=(boot|system)' })
        if ($thirdPartyBoot.Count -gt 0) {
            & $addInsight 'WARN' 'Recent non-Microsoft Boot/System driver change' 'Third-party drivers loading at Boot or System start are a top boot-failure suspect, especially storage, network, AV/EDR, VPN, or filter drivers.' (($thirdPartyBoot | Select-Object -ExpandProperty Item -First 8) -join ', ') 'Snapshot disk, then -DisableDriverOrService <name> on the suspect driver and retry boot.' 'Medium'
        }

        $logonTamper = @($Findings | Where-Object { $_.Severity -in @('CRITICAL', 'WARN') -and $_.Category -in @('LogonRegistry', 'BootRegistry') })
        if ($logonTamper.Count -gt 0) {
            & $addInsight 'WARN' 'Boot/logon registry values modified recently' 'Changes to Winlogon Shell/Userinit or Session Manager BootExecute can prevent logon (black screen) or hang boot before the Service Control Manager starts.' (($logonTamper | ForEach-Object { "$($_.Source):$($_.Item)" }) -join ', ') 'Inspect values with -LoadHive SOFTWARE,SYSTEM and run -FixWinlogon / -FixSessionManager if values are non-default.' 'High'
        }

        $driverInstallFail = @($Findings | Where-Object { $_.Category -eq 'DriverSetup' -and $_.Severity -in @('WARN', 'CRITICAL') -and ($_.Evidence -match '!!!|failed|error|Exit status:\s*(?!SUCCESS)') })
        if ($driverInstallFail.Count -gt 0) {
            & $addInsight 'WARN' 'Recent driver/device installation failed' 'A failed driver/device install can leave half-registered services, broken filter chains, or pending reboot state that breaks boot.' (($driverInstallFail | Select-Object -ExpandProperty Item -First 6) -join ', ') 'Cross-reference Services and DriverFiles for the failed package; use -GetServicesReport -IssuesOnly.' 'Medium'
        }

        $unsafeFilters = @($Findings | Where-Object { $_.Category -eq 'DeviceFilters' -and $_.Severity -eq 'WARN' })
        if ($unsafeFilters.Count -gt 0) {
            & $addInsight 'WARN' 'Unsafe device-class filter drivers detected' 'Non-inbox UpperFilters/LowerFilters on boot-critical device classes (disk, volume, partmgr) can prevent disk enumeration at boot.' (($unsafeFilters | Select-Object -ExpandProperty Item) -join ', ') 'Use -FixDeviceFilters to restore the safe inbox list.' 'High'
        }

        $secProduct = @($Findings | Where-Object { $_.Category -eq 'Software' -and $_.Severity -eq 'WARN' -and ($_.Evidence -match '(?i)crowd|sentinel|carbon|zscaler|globalprotect|symantec|mcafee|trend|veeam|commvault|defender' -or $_.Item -match '(?i)edr|antivirus|defender|crowd|sentinel|carbon|zscaler|globalprotect') })
        if ($secProduct.Count -gt 0) {
            & $addInsight 'WARN' 'Recent security/EDR/AV product change' 'Security agents register filter drivers and boot-time minifilters; recent install or upgrade is a common boot regression source.' (($secProduct | Select-Object -ExpandProperty Item -First 6) -join ', ') 'Identify the agent service and consider -DisableDriverOrService <minifilter> after a disk snapshot.' 'Medium'
        }

        $bootFileTouched = @($Findings | Where-Object { $_.Severity -eq 'WARN' -and $_.Category -in @('BootFiles', 'LogonFiles', 'DriverFiles') -and $_.ChangeType -eq 'RecentCriticalFileTimestamp' })
        if ($bootFileTouched.Count -gt 0) {
            & $addInsight 'WARN' 'Critical boot/logon file modified by a non-Microsoft signer' 'A critical boot/logon binary with a non-Microsoft signature should never appear on a healthy Windows install; this often indicates corruption, replacement, or tampering.' (($bootFileTouched | Select-Object -ExpandProperty Item -First 6) -join ', ') 'Compare against WinSxS reference: -AnalyzeCriticalBootFiles, then -RepairSystemFile <name>.' 'High'
        }

        $timedWarn = @($criticalsAndWarns | Where-Object { $_.Timestamp } | Sort-Object Timestamp)
        if ($timedWarn.Count -ge 3) {
            for ($i = 0; $i -le ($timedWarn.Count - 3); $i++) {
                $windowStart = $timedWarn[$i].Timestamp
                $window = @($timedWarn | Where-Object { $_.Timestamp -ge $windowStart -and $_.Timestamp -le $windowStart.AddMinutes(60) })
                $distinctCats = @($window.Category | Sort-Object -Unique)
                if ($window.Count -ge 3 -and $distinctCats.Count -ge 2) {
                    $title = "Cluster of $($window.Count) suspect changes within 60 minutes starting $($windowStart.ToString('yyyy-MM-dd HH:mm'))"
                    $support = (($window | ForEach-Object { "[$($_.Category)] $($_.Item)" } | Select-Object -First 8) -join ', ')
                    & $addInsight 'WARN' $title 'Multiple unrelated changes within a short window usually map to a single triggering event (update install, agent deployment, GPO push, sysprep). Treat them as one incident.' $support 'Investigate the parent event (servicing log, GPO log, deployment record) and address that root cause, not each child symptom.' 'Medium'
                    break
                }
            }
        }

        $driverStorePkgs = @($Findings | Where-Object { $_.Category -eq 'DriverStore' -and $_.ChangeType -eq 'RecentDriverPackageDirectory' })
        if ($driverStorePkgs.Count -ge 5) {
            $title = "DriverStore churn: $($driverStorePkgs.Count) recent driver packages"
            & $addInsight 'INFO' $title 'A burst of new DriverStore packages usually indicates a Windows Update wave, an agent push, or a driver pack install.' (($driverStorePkgs | Select-Object -ExpandProperty Item -First 8) -join ', ') 'If post-update boot is broken, focus on the most recent storage/network/AV-related package and use -GetServicesReport -IssuesOnly.' 'Low'
        }

        return $insights.ToArray()
    }

    function Write-RecentChangeReport {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][System.Collections.Generic.List[object]]$Findings,
            [Parameter(Mandatory = $true)][datetime]$Cutoff,
            [Parameter(Mandatory = $true)][int]$RecentChangeDays,
            [Parameter(Mandatory = $true)][datetime]$Started
        )

        $ended = Get-Date
        $sorted = @($Findings | Sort-Object @{ Expression = 'Priority'; Ascending = $true }, @{ Expression = 'Timestamp'; Descending = $true }, Category, Item)
        $critical = @($sorted | Where-Object { $_.Severity -eq 'CRITICAL' })
        $warnings = @($sorted | Where-Object { $_.Severity -eq 'WARN' })
        $infos = @($sorted | Where-Object { $_.Severity -eq 'INFO' })

        Write-Host ""
        Write-Host "=== Recent Change Analysis ===" -ForegroundColor Cyan
        Write-Host "Lookback window : $RecentChangeDays day(s)"
        Write-Host "Cutoff          : $($Cutoff.ToString('o'))"
        Write-Host "Findings        : $($sorted.Count) total | $($critical.Count) critical | $($warnings.Count) warnings | $($infos.Count) info"
        Write-Host ""
        Write-Host "These findings are timestamped correlation signals, not proof of root cause." -ForegroundColor DarkGray

        $insights = @(Get-RecentChangeInsights -Findings $sorted)
        Write-Host ""
        Write-Host "=== Insights (correlated hypotheses) ===" -ForegroundColor Magenta
        if ($insights.Count -eq 0) {
            Write-Host "No high-confidence correlated insights from the recent change window." -ForegroundColor DarkGray
        }
        else {
            $insightIndex = 0
            foreach ($insight in $insights) {
                $insightIndex++
                $color = switch ($insight.Severity) {
                    'CRITICAL' { 'Red' }
                    'WARN' { 'Yellow' }
                    default { 'Cyan' }
                }
                Write-Host ""
                Write-Host ("[{0}] {1}  (Severity: {2}, Confidence: {3})" -f $insightIndex, $insight.Title, $insight.Severity, $insight.Confidence) -ForegroundColor $color
                Write-Host ("    Why it matters : {0}" -f $insight.WhyItMatters) -ForegroundColor Gray
                Write-Host ("    Evidence       : {0}" -f $insight.SupportingFindings) -ForegroundColor Gray
                Write-Host ("    Suggested fix  : {0}" -f $insight.SuggestedAction) -ForegroundColor Green
            }
        }

        $topSuspects = @($sorted | Where-Object { $_.Severity -in @('CRITICAL', 'WARN') } | Select-Object -First 10)
        Write-Host ""
        Write-Host "=== Top suspects (top 10) ===" -ForegroundColor Yellow
        if ($topSuspects.Count -eq 0) {
            Write-Host "No critical or warning-level recent change suspects were found." -ForegroundColor Green
        }
        else {
            $suspectIndex = 0
            foreach ($s in $topSuspects) {
                $suspectIndex++
                $color = if ($s.Severity -eq 'CRITICAL') { 'Red' } else { 'Yellow' }
                $ts = if ($s.Timestamp) { ([datetime]$s.Timestamp).ToString('yyyy-MM-dd HH:mm:ss') } else { '(no timestamp)' }
                Write-Host ""
                Write-Host ("#{0,-2} [{1,-8}] [{2}] {3}" -f $suspectIndex, $s.Severity, $s.Category, $s.Item) -ForegroundColor $color
                Write-Host ("     Timestamp : {0}" -f $ts) -ForegroundColor Gray
                Write-Host ("     Change    : {0}" -f $s.ChangeType) -ForegroundColor Gray
                Write-Host ("     Evidence  : {0}" -f $s.Evidence) -ForegroundColor Gray
                if ($s.LikelyImpact) { Write-Host ("     Impact    : {0}" -f $s.LikelyImpact) -ForegroundColor Gray }
                if ($s.SuggestedRepairSwitch) { Write-Host ("     Repair    : {0}" -f $s.SuggestedRepairSwitch) -ForegroundColor Green }
                if ($s.Path) { Write-Host ("     Path      : {0}" -f $s.Path) -ForegroundColor DarkGray }
            }
        }

        Write-Host ""
        Write-Host "=== Findings by category (most recent first, up to 10 per category) ===" -ForegroundColor Cyan
        foreach ($category in @($sorted.Category | Sort-Object -Unique)) {
            $categoryAll = @($sorted | Where-Object { $_.Category -eq $category })
            $categoryRows = @($categoryAll |
                    Sort-Object @{ Expression = { if ($_.Timestamp) { [datetime]$_.Timestamp } else { [datetime]::MinValue } }; Descending = $true },
                        @{ Expression = 'Priority'; Ascending = $true },
                        Item |
                    Select-Object -First 10)
            if ($categoryRows.Count -eq 0) { continue }
            Write-Host ""
            Write-Host "[$category]" -ForegroundColor Cyan
            $categoryRows |
                Select-Object Severity,
                    @{ Name = 'Timestamp'; Expression = { if ($_.Timestamp) { ([datetime]$_.Timestamp).ToString('yyyy-MM-dd HH:mm') } else { '' } } },
                    Item,
                    ChangeType,
                    Evidence |
                Format-Table -Wrap |
                Out-String -Width 200 |
                Write-Host
        }

        $topForLog = @($sorted | Select-Object -First 60)
        Write-ActionLog -Event 'RecentChangeAnalysis' -Details @{
            Description      = 'AnalyzeRecentChanges'
            Success          = $true
            Start            = $Started.ToString('o')
            End              = $ended.ToString('o')
            RecentChangeDays = $RecentChangeDays
            Cutoff           = $Cutoff.ToString('o')
            TotalFindings    = $sorted.Count
            CriticalCount    = $critical.Count
            WarningCount     = $warnings.Count
            InfoCount        = $infos.Count
            Insights         = $insights
            TopFindings      = $topForLog
        }
    }

    function AnalyzeRecentChanges {
        param([int]$RecentChangeDays = 14)

        $started = Get-Date
        $cutoff = $started.AddDays(-1 * [math]::Abs($RecentChangeDays))
        $findings = [System.Collections.Generic.List[object]]::new()

        Write-Host "Analyzing recent offline OS changes (last $RecentChangeDays day(s))..." -ForegroundColor Yellow
        Write-Host "Cutoff: $($cutoff.ToString('o'))" -ForegroundColor DarkGray

        try {
            Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
                $currentVersion = Get-ItemProperty 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
                if ($currentVersion) {
                    $buildText = Format-WindowsBuildLabel -Build $currentVersion.CurrentBuildNumber -Ubr $currentVersion.UBR -Fallback 'unknown'
                    Write-Host "Guest OS: $($currentVersion.ProductName) build $buildText" -ForegroundColor Cyan
                }

                foreach ($collector in @(
                        @{ Name = 'Servicing'; Script = { Add-RecentChangeServicingFindings -Findings $findings -Cutoff $cutoff } }
                        @{ Name = 'Services'; Script = { Add-RecentChangeServiceFindings -Findings $findings -Cutoff $cutoff } }
                        @{ Name = 'Registry risks'; Script = { Add-RecentChangeRegistryRiskFindings -Findings $findings -Cutoff $cutoff } }
                        @{ Name = 'Software'; Script = { Add-RecentChangeSoftwareFindings -Findings $findings -Cutoff $cutoff } }
                    )) {
                    try { & $collector.Script }
                    catch { Add-RecentChangeCollectorFailure -Findings $findings -Collector $collector.Name -ErrorText $_.Exception.Message }
                }
            }
        }
        catch { Add-RecentChangeCollectorFailure -Findings $findings -Collector 'Registry-backed collectors' -ErrorText $_.Exception.Message }

        foreach ($collector in @(
                @{ Name = 'SetupAPI'; Script = { Add-RecentChangeSetupApiFindings -Findings $findings -Cutoff $cutoff } }
                @{ Name = 'Critical files'; Script = { Add-RecentChangeFileFindings -Findings $findings -Cutoff $cutoff } }
                @{ Name = 'Event logs'; Script = { Add-RecentChangeEventFindings -Findings $findings -Cutoff $cutoff } }
            )) {
            try { & $collector.Script }
            catch { Add-RecentChangeCollectorFailure -Findings $findings -Collector $collector.Name -ErrorText $_.Exception.Message }
        }

        Write-RecentChangeReport -Findings $findings -Cutoff $cutoff -RecentChangeDays $RecentChangeDays -Started $started
    }
    function AnalyzeServicingState {
        Write-Host "Analyzing servicing/CBS pending state..." -ForegroundColor Yellow
        $pendingXml = Join-Path $script:WinDriveLetter 'Windows\WinSxS\pending.xml'
        $hasPendingXml = Test-Path -LiteralPath $pendingXml

        # Transaction log inventory. Read-only, and reported alongside the pending
        # markers so the two failure modes can be told apart: log exhaustion needs
        # -FixTxRLogs, an interrupted install needs -FixPendingUpdates.
        $logPlan = @(Get-TransactionLogCleanupPlan -Scope 'TxR', 'Config', 'SMI' -SkipHiveState)
        $totalLogFiles = 0
        foreach ($scopePlan in $logPlan) { $totalLogFiles += $scopePlan.Snapshot.LogFiles.Count }

        $logFullHits = 0
        $cbsLog = Join-Path $script:WinDriveLetter 'Windows\Logs\CBS\CBS.log'
        if (Test-Path -LiteralPath $cbsLog) {
            try {
                $logFullHits = @(Get-Content -LiteralPath $cbsLog -Tail 4000 -ErrorAction Stop |
                        Where-Object { $_ -match '0x800719e4' -or $_ -match 'ERROR_LOG_FULL' }).Count
            }
            catch { Write-Verbose "CBS.log could not be read: $($_.Exception.Message)" }
        }

        Invoke-WithHive 'SOFTWARE', 'COMPONENTS' {
            $cbs = 'HKLM:\BROKENSOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing'
            $counts = @{}
            foreach ($k in @('PackagesPending', 'SessionsPending', 'RebootPending')) {
                $p = Join-Path $cbs $k
                $counts[$k] = if (Test-Path $p) { (Get-ChildItem $p -ErrorAction SilentlyContinue | Measure-Object).Count } else { 0 }
            }

            $comp = 'HKLM:\BROKENCOMPONENTS'
            $cp = Get-ItemProperty $comp -ErrorAction SilentlyContinue
            [PSCustomObject]@{
                PendingXmlPresent    = $hasPendingXml
                PackagesPending      = $counts['PackagesPending']
                SessionsPending      = $counts['SessionsPending']
                RebootPending        = $counts['RebootPending']
                ExecutionState       = $cp.ExecutionState
                PendingXmlIdentifier = $cp.PendingXmlIdentifier
                NextQueueEntryIndex  = $cp.NextQueueEntryIndex
                StoreDirty           = $cp.StoreDirty
                TxRLogFiles          = ($logPlan | Where-Object { $_.Scope -eq 'TxR' }).Snapshot.LogFiles.Count
                ConfigLogFiles       = ($logPlan | Where-Object { $_.Scope -eq 'Config' }).Snapshot.LogFiles.Count
                SmiLogFiles          = ($logPlan | Where-Object { $_.Scope -eq 'SMI' }).Snapshot.LogFiles.Count
                LogFullErrors        = $logFullHits
            } | Format-List

            $hasPendingMarkers = ($hasPendingXml -or $counts['PackagesPending'] -gt 0 -or $counts['SessionsPending'] -gt 0 -or $counts['RebootPending'] -gt 0)

            if ($logFullHits -gt 0) {
                Write-Warning "CBS.log reports transaction log exhaustion ($logFullHits hit(s) of 0x800719e4/ERROR_LOG_FULL)."
                Write-Host "  Run -FixTxRLogs to clear the transaction logs, then boot and retry the update." -ForegroundColor DarkCyan
                Write-Host "  See: https://learn.microsoft.com/troubleshoot/windows-server/installing-updates-features-roles/error-0x800719e4-windows-update-fails" -ForegroundColor DarkCyan
            }

            if ($hasPendingMarkers) {
                Write-Warning "Servicing pending markers detected. If boot loops in update stage, consider -FixPendingUpdates."
            }
            elseif ($totalLogFiles -gt 0 -and $logFullHits -eq 0) {
                Write-Host "No pending servicing markers, but $totalLogFiles transaction log file(s) are present." -ForegroundColor Yellow
                Write-Host "  If the guest hangs in the update stage, -FixTxRLogs clears them without reverting any update." -ForegroundColor DarkCyan
            }
            elseif (-not $hasPendingMarkers) {
                Write-Host "No major pending servicing markers detected." -ForegroundColor Green
            }
        }
    }

    function AnalyzeDomainTrustState {
        Write-Host "Analyzing likely domain-join/trust state signals..." -ForegroundColor Yellow
        Invoke-WithHive 'SYSTEM', 'SOFTWARE' {
            $sysRoot = Get-SystemRootPath
            $tcpip = "$sysRoot\Services\Tcpip\Parameters"
            $domain = (Get-ItemProperty $tcpip -ErrorAction SilentlyContinue).Domain
            $dhcpDomain = (Get-ItemProperty $tcpip -ErrorAction SilentlyContinue).DhcpDomain
            $netlogonStart = (Get-ItemProperty "$sysRoot\Services\Netlogon" -ErrorAction SilentlyContinue).Start
            $defaultDomain = (Get-ItemProperty 'HKLM:\BROKENSOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -ErrorAction SilentlyContinue).DefaultDomainName
            $joined = (($domain -and $domain -notmatch '^(WORKGROUP|LOCALDOMAIN)$') -or ($dhcpDomain -and $dhcpDomain -notmatch '^(WORKGROUP|LOCALDOMAIN)$') -or ($defaultDomain -and $defaultDomain -notmatch '^(WORKGROUP|LOCALDOMAIN)$'))

            [PSCustomObject]@{
                Domain             = $domain
                DhcpDomain         = $dhcpDomain
                DefaultDomainName  = $defaultDomain
                NetlogonStart      = $netlogonStart
                LikelyDomainJoined = $joined
                NetlogonDisabled   = ($netlogonStart -eq 4)
            } | Format-List

            if ($joined -and $netlogonStart -eq 4) {
                Write-Warning "Domain-join signals found but Netlogon is disabled. This can break domain authentication and RDP."
            }
        }
    }

    function PrepareRecoveryDiagnostics {
        if (-not (Confirm-CriticalOperation -Operation 'Prepare Recovery Diagnostics (-PrepareRecoveryDiagnostics)' -Details @"
Applies a conservative diagnostics bundle for a broken VM:
  - Enable boot logging (ntbtlog.txt)
  - Enable serial console (EMS)
  - Configure full memory dump settings
No destructive file or registry cleanup is performed.
"@)) { return }

        SetBootLog
        EnableSerialConsole
        ConfigureFullMemDump
        Write-Host "Recovery diagnostics bundle applied." -ForegroundColor Green
    }

    ################################################################################
    # Initialize-TargetDisk
    #
    # Resolves a VM name (Hyper-V) or a raw disk number to a physical disk,
    # brings it online, assigns temporary drive letters to unmounted partitions,
    # detects the Windows and Boot partitions, and populates the script-scoped
    # variables consumed by all repair functions:
    #   $script:WinDriveLetter   - e.g. "E:\"
    #   $script:BootDriveLetter  - e.g. "F:\" (may equal WinDriveLetter on Gen1)
    #   $script:VMGen            - 1 (MBR/BIOS) or 2 (GPT/UEFI)
    #
    # Returns $true on success, $false on failure.
    function Initialize-TargetDisk {
        param(
            [string]$VMName = "",
            [int]   $DiskNumber = -1
        )

        # ------------------------------------------------------------------
        # 1. Resolve VMName -> DiskNumber (Hyper-V path)
        # ------------------------------------------------------------------
        $script:AutoMountedVHDPath = $null   # track if we auto-mounted a VHD for cleanup
        if (-not [string]::IsNullOrWhiteSpace($VMName)) {
            Write-Host "Resolving Hyper-V VM '$VMName'..." -ForegroundColor Cyan

            if (-not (Get-Command Get-VM -ErrorAction SilentlyContinue)) {
                Write-Error "Hyper-V module is not available on this host. Install/enable the Hyper-V role or use -DiskNumber instead of -VMName."
                return $false
            }

            $vm = Get-VM -Name $VMName -ErrorAction SilentlyContinue
            if (-not $vm) {
                Write-Error "VM '$VMName' not found."
                return $false
            }

            # Stop VM before accessing its disk
            if ($vm.State -ne 'Off') {
                Write-Host "Stopping VM '$VMName'..."
                $script:VMIPAddress = (Get-VM -Name $VMName | Get-VMNetworkAdapter).IPAddresses |
                Where-Object { $_ -match "\." } | Select-Object -First 1
                $vm | Stop-VM -TurnOff -Force
                Start-Sleep -Seconds 2
            }

            # Resolve VM hard drive -> physical disk number
            # Strategy: Get-VHD (authoritative) -> HardDrive.DiskNumber (cross-validated) -> auto-mount
            $osDrive = $vm.HardDrives | Where-Object { $_.ControllerNumber -eq 0 -and $_.ControllerLocation -eq 0 }
            if (-not $osDrive) { $osDrive = $vm.HardDrives | Select-Object -First 1 }
            if (-not $osDrive -or -not $osDrive.Path) {
                Write-Error "VM '$VMName' has no hard drives attached."
                return $false
            }
            $vhdPath = $osDrive.Path
            $DiskNumber = -1

            # 1) Authoritative: Get-VHD tells us the real disk number when the VHD is mounted
            if (Test-Path -LiteralPath $vhdPath) {
                $vhd = Get-VHD -Path $vhdPath -ErrorAction SilentlyContinue
                if ($vhd -and $null -ne $vhd.DiskNumber -and [int]$vhd.DiskNumber -ge 0) {
                    $DiskNumber = [int]$vhd.DiskNumber
                }
            }

            # 2) Cross-validate HardDrive.DiskNumber -- Hyper-V returns 0 as default when
            #    the VHD is not mounted, which would incorrectly point at the host OS disk.
            if ($DiskNumber -lt 0 -and $null -ne $osDrive.DiskNumber -and [int]$osDrive.DiskNumber -ge 0) {
                $rawNum = [int]$osDrive.DiskNumber
                # Reject if it matches the local OS disk (almost certainly a false default)
                if ($null -ne $script:LocalOsDiskNumber -and $rawNum -eq $script:LocalOsDiskNumber) {
                    Write-Host "  Hyper-V reports DiskNumber=$rawNum for this VM, but that is the local OS disk - ignoring." -ForegroundColor DarkYellow
                }
                else {
                    $DiskNumber = $rawNum
                }
            }

            # 3) VHD exists on disk but is not mounted -- auto-mount it
            if ($DiskNumber -lt 0 -and (Test-Path -LiteralPath $vhdPath)) {
                Write-Host "VM disk is not mounted on the host. Mounting VHD: $vhdPath..." -ForegroundColor Cyan
                try {
                    Mount-VHD -Path $vhdPath -ErrorAction Stop
                    Start-Sleep -Seconds 2
                    $vhd = Get-VHD -Path $vhdPath -ErrorAction SilentlyContinue
                    if ($vhd -and $null -ne $vhd.DiskNumber -and [int]$vhd.DiskNumber -ge 0) {
                        $DiskNumber = [int]$vhd.DiskNumber
                        $script:AutoMountedVHDPath = $vhdPath
                        Write-Host "  Mounted as Disk $DiskNumber" -ForegroundColor Green
                    }
                }
                catch {
                    Write-Error "Failed to mount VHD '$vhdPath': $_"
                }
            }
            elseif ($DiskNumber -lt 0 -and -not (Test-Path -LiteralPath $vhdPath)) {
                Write-Error "VM disk path not found: $vhdPath"
                return $false
            }

            if ($null -eq $DiskNumber -or $DiskNumber -lt 0) {
                Write-Error "Could not determine disk number for VM '$VMName'. Attach the disk manually and use -DiskNumber instead."
                return $false
            }

            Write-Host "[OK] VM disk resolved to Disk $DiskNumber`n" -ForegroundColor Green
        }

        if ($DiskNumber -lt 0) {
            Write-Error "No disk specified. Provide -VMName (Hyper-V) or -DiskNumber."
            return $false
        }

        # Guard: never operate on the local OS disk - applies to both -DiskNumber and -VMName paths
        if ($null -ne $script:LocalOsDiskNumber -and $DiskNumber -eq $script:LocalOsDiskNumber) {
            Write-Error "Disk $DiskNumber hosts the local C: drive. Cannot use it as a repair target - this would risk breaking the Hyper-V host."
            return $false
        }

        # ------------------------------------------------------------------
        # 2. Get disk and validate
        # ------------------------------------------------------------------
        $targetDisk = Get-Disk -Number $DiskNumber -ErrorAction SilentlyContinue
        if (-not $targetDisk) {
            Write-Error "Disk $DiskNumber not found. Use the script without parameters to list available disks."
            return $false
        }

        Write-Host "Target Disk: Disk $DiskNumber | $($targetDisk.PartitionStyle) | $([math]::Round($targetDisk.Size / 1GB)) GB"

        # ------------------------------------------------------------------
        # 2.5 Check if disk is currently owned by a running VM
        # ------------------------------------------------------------------
        $owningVM = if (Get-Command Get-VM -ErrorAction SilentlyContinue) {
            Get-VM -ErrorAction SilentlyContinue | Where-Object { $_.State -ne 'Off' } | ForEach-Object {
                $checkVM = $_
                foreach ($hd in $checkVM.HardDrives) {
                    $resolvedNum = -1
                    if ($null -ne $hd.DiskNumber -and [int]$hd.DiskNumber -ge 0) {
                        $resolvedNum = [int]$hd.DiskNumber
                    }
                    elseif ($hd.Path -match '\.vhdx?$') {
                        $vhd = Get-VHD -Path $hd.Path -ErrorAction SilentlyContinue
                        if ($vhd -and $null -ne $vhd.DiskNumber -and [int]$vhd.DiskNumber -ge 0) {
                            $resolvedNum = [int]$vhd.DiskNumber
                        }
                    }
                    if ($resolvedNum -eq $DiskNumber) {
                        $checkVM.Name
                        return
                    }
                }
            } | Select-Object -First 1
        }
        if ($owningVM) {
            Write-Error "Disk $DiskNumber is currently attached to running VM '$owningVM'. Stop the VM first, or re-run with -VMName '$owningVM' to have the script stop it automatically."
            return $false
        }

        # ------------------------------------------------------------------
        # 3. Bring disk online and writable
        # ------------------------------------------------------------------
        $usedLetters = (Get-Volume).DriveLetter | Where-Object { $_ } | ForEach-Object { ([string]$_).ToUpper() }

        if ($targetDisk.OperationalStatus -eq 'Offline' -or $targetDisk.IsOffline) {
            Write-Host "Bringing disk $DiskNumber online..." -ForegroundColor Cyan
            try {
                $targetDisk | Set-Disk -IsOffline $false
                $targetDisk | Set-Disk -IsReadOnly $false
            }
            catch {
                if ($_ -match 'Access Denied|40001') {
                    Write-Error "Access denied bringing disk $DiskNumber online. The disk is likely in use by a running VM. Stop the VM first, or re-run with -VMName <name> to have the script stop it automatically."
                }
                else {
                    Write-Error "Failed to bring disk $DiskNumber online: $($_.Exception.Message)"
                }
                return $false
            }
            Start-Sleep -Seconds 2
            $targetDisk = Get-Disk -Number $DiskNumber
        }
        elseif ($targetDisk.IsReadOnly) {
            Write-Host "Clearing read-only flag on disk $DiskNumber..." -ForegroundColor Cyan
            try {
                $targetDisk | Set-Disk -IsReadOnly $false
            }
            catch {
                if ($_ -match 'Access Denied|40001') {
                    Write-Error "Access denied clearing read-only flag on disk $DiskNumber. The disk is likely in use by a running VM."
                }
                else {
                    Write-Error "Failed to clear read-only flag on disk ${DiskNumber}: $($_.Exception.Message)"
                }
                return $false
            }
            $targetDisk = Get-Disk -Number $DiskNumber
        }

        # ------------------------------------------------------------------
        # 4. Detect generation (MBR = Gen1, GPT = Gen2)
        # ------------------------------------------------------------------
        $script:VMGen = Get-DiskGeneration -Disk $targetDisk
        $script:WindowsInstallCandidates = @()
        $script:SelectedWindowsInstall = $null
        $script:BcdInventory = $null
        Write-Host "Detected Partition Style: $(if ($script:VMGen -eq 1) { 'MBR (BIOS) - Gen1' } else { 'GPT (UEFI) - Gen2' })"

        # ------------------------------------------------------------------
        # 5. Assign drive letters to unmounted useful partitions
        # ------------------------------------------------------------------
        $partitions = $targetDisk | Get-Partition
        foreach ($part in $partitions) {
            if (-not $part.DriveLetter -and ($part.Type -in @('System', 'Basic', 'IFS'))) {
                Write-Host "Assigning drive letter to Partition $($part.PartitionNumber) ($($part.Type))..."
                $part | Add-PartitionAccessPath -AssignDriveLetter -ErrorAction SilentlyContinue
            }
        }

        # ------------------------------------------------------------------
        # 6. Detect Windows and Boot partitions via AccessPaths
        # ------------------------------------------------------------------
        $winDrive = $null
        $bootDrive = $null

        $partitions = $targetDisk | Get-Partition
        Write-Host "`nPartition Analysis:" -ForegroundColor Cyan
        foreach ($part in $partitions) {
            $accessPaths = $part.AccessPaths | Where-Object { $_ -match ":" }
            foreach ($accessPath in $accessPaths) {
                $role = Get-PartitionRole -AccessPath $accessPath -PartitionInfo $part
                Write-Host "  Partition $($part.PartitionNumber) ($accessPath): $role"

                if ((Test-Path (Join-Path $accessPath "Windows\System32\ntdll.dll")) -and -not $winDrive) {
                    $winDrive = $accessPath
                }

                if ($script:VMGen -eq 1) {
                    # Active MBR partition with Boot\BCD present
                    if ($part.IsActive -and (Test-BcdStorePath -StorePath (Join-Path $accessPath "Boot\BCD")) -and -not $bootDrive) {
                        $bootDrive = $accessPath
                    }
                    # Fallback: active MBR partition even without BCD (BCD missing/corrupted)
                    elseif ($part.IsActive -and -not $bootDrive) {
                        $bootDrive = $accessPath
                        Write-Host "  ** Boot partition identified by MBR Active flag (BCD file missing - run -FixBoot to rebuild)" -ForegroundColor Yellow
                    }
                }
                elseif ($script:VMGen -eq 2) {
                    # GPT System partition with EFI\Microsoft\Boot\BCD present
                    if ($part.Type -eq 'System' -and (Test-BcdStorePath -StorePath (Join-Path $accessPath "EFI\Microsoft\Boot\BCD")) -and -not $bootDrive) {
                        $bootDrive = $accessPath
                    }
                    # Fallback 1: GPT System partition with EFI\Microsoft\Boot folder (BCD deleted)
                    elseif ($part.Type -eq 'System' -and (Test-Path (Join-Path $accessPath "EFI\Microsoft\Boot")) -and -not $bootDrive) {
                        $bootDrive = $accessPath
                        Write-Host "  ** Boot partition identified by GPT System type + EFI folder (BCD missing - run -FixBoot to rebuild)" -ForegroundColor Yellow
                    }
                    # Fallback 2: GPT System partition exists but EFI folder is also gone
                    elseif ($part.Type -eq 'System' -and -not $bootDrive) {
                        $bootDrive = $accessPath
                        Write-Host "  ** Boot partition identified by GPT System partition type only (EFI/BCD missing - run -FixBoot to rebuild)" -ForegroundColor Yellow
                    }
                }
            }
        }

        $newUsedLetters = (Get-Volume).DriveLetter | Where-Object { $_ } | ForEach-Object { ([string]$_).ToUpper() }
        $addedLetters = $newUsedLetters | Where-Object { $usedLetters -notcontains $_ }
        if ($addedLetters) { Write-Host "Added letter(s): $($addedLetters -join ', ')" }

        # ------------------------------------------------------------------
        # 7. Validate and publish script-scoped variables
        # ------------------------------------------------------------------
        if (-not $winDrive) {
            Write-Error "Cannot proceed: Windows partition (containing \Windows\System32\ntdll.dll) not detected on disk $DiskNumber."
            return $false
        }

        if (-not $bootDrive) {
            $bootDrive = $winDrive
            if ($script:VMGen -eq 2) {
                Write-Host "[WARNING] No EFI System Partition found on disk $DiskNumber - Gen2 (UEFI) VMs cannot boot without it." -ForegroundColor Red
                Write-Host "          Use -RecreateBootPartition to create a new ESP and populate it with boot files." -ForegroundColor Yellow
            }
            else {
                Write-Host "No separate boot partition found; using Windows drive as boot drive." -ForegroundColor Yellow
                Write-Host "          If the System Reserved partition was deleted, use -RecreateBootPartition to recreate it." -ForegroundColor Yellow
            }
        }

        $bootStorePath = Get-BcdStorePath -Generation $script:VMGen -BootDrive $bootDrive
        $bcdInventory = Get-BcdInventory -StorePath $bootStorePath
        $installCandidates = Get-WindowsInstallCandidates -DiskNumber $DiskNumber -Generation $script:VMGen -BcdLoaders $bcdInventory.Loaders -BcdDefaultId $bcdInventory.DefaultId
        if ($installCandidates.Count -gt 0) {
            $selectedInstall = @($installCandidates | Where-Object { $_.Selected } | Select-Object -First 1)
            if (-not $selectedInstall) {
                $selectedInstall = @($installCandidates | Select-Object -First 1)
            }
            if ($selectedInstall) {
                $winDrive = $selectedInstall[0].AccessPath
                $script:SelectedWindowsInstall = $selectedInstall[0]
            }
            $script:WindowsInstallCandidates = $installCandidates
            $script:BcdInventory = $bcdInventory
        }

        # Normalize to trailing backslash
        if ($winDrive -notmatch '\\$') { $winDrive = "$winDrive\" }
        if ($bootDrive -notmatch '\\$') { $bootDrive = "$bootDrive\" }

        $script:WinDriveLetter = $winDrive
        $script:BootDriveLetter = $bootDrive
        $script:DiskNumber = $DiskNumber

        # Capture the target parameter the user actually invoked with, so -SysCheck
        # fix suggestions echo the same form: -VMName <name> when a VM was resolved,
        # otherwise -DiskNumber <n>. Quote the VM name if it contains whitespace.
        if (-not [string]::IsNullOrWhiteSpace($VMName)) {
            $targetName = if ($VMName -match '\s') { '"' + $VMName + '"' } else { $VMName }
            $script:InvocationTarget = "-VMName $targetName"
        }
        else {
            $script:InvocationTarget = "-DiskNumber $DiskNumber"
        }

        Write-Host ""
        Write-Host "[OK] Windows drive : $script:WinDriveLetter"  -ForegroundColor Green
        Write-Host "[OK] Boot drive    : $script:BootDriveLetter" -ForegroundColor Green
        Write-Host "[OK] VM Generation : Gen$script:VMGen"        -ForegroundColor Green
        if ($script:WindowsInstallCandidates.Count -gt 0) {
            Write-Host "[INFO] Windows installs detected: $($script:WindowsInstallCandidates.Count)" -ForegroundColor Cyan
            foreach ($candidate in $script:WindowsInstallCandidates) {
                $marker = if ($candidate.Selected) { '[selected]' } else { '          ' }
                $buildLabel = Format-WindowsBuildLabel -Build $candidate.CurrentBuildNumber -Ubr $candidate.UBR -Prefix 'Build ' -Fallback 'Build unknown'
                $productLabel = if ($candidate.ProductName) { $candidate.ProductName } else { 'Unknown Windows install' }
                $stateLabel = if ($candidate.SetupInProgress) { 'setup-state' } else { 'normal-state' }
                Write-Host "  $marker $($candidate.Drive) Part$($candidate.PartitionNumber) | $productLabel | $buildLabel | $stateLabel | score=$($candidate.Score)" -ForegroundColor $(if ($candidate.Selected) { 'Green' } else { 'DarkCyan' })
                if ($candidate.MappedBcdEntries) {
                    Write-Host "            BCD: $($candidate.MappedBcdEntries)" -ForegroundColor DarkGray
                }
                if ($candidate.SetupEvidence) {
                    Write-Host "            Evidence: $($candidate.SetupEvidence)" -ForegroundColor DarkGray
                }
            }
        }
        Write-Host ""

        return $true
    }

    ################################################################################
    # Consolidated helper: Repair-OfflineDisk
    #
    # Parameters: same as the script-level parameters. Callers may pass the script's
    # bound parameters via `Repair-OfflineDisk @PSBoundParameters`.
    #
    # What it does (summary):
    #  - Initializes the target disk or resolves a VM to a disk
    #  - Brings the disk online and assigns temporary letters as needed
    #  - Detects Windows and Boot partitions
    #  - Executes requested repair actions (chkdsk, DISM, BCD rebuild, RDP fixes,
    #    user additions, registry fixes, etc.) according to the provided switches
    #  - Optionally leaves the disk online or takes it offline when finished
    function Repair-OfflineDisk {
        param (
            [string]$VMName = "",
            [int]$DiskNumber = -1,
            [switch]$FixFileSystem,
            [switch]$FixNtfsAttributeList,
            [switch]$FixBoot,
            [switch]$FixSecureBootCodeIntegrity,
            [string]$CodeIntegrityPolicySourcePath = '',
            [switch]$Force,
            [switch]$FixBootSector,
            [string]$BootsectPath = '',
            [switch]$FixBootStorageDrivers,
            [switch]$RecreateBootPartition,
            [switch]$RepairComponentStore,
            [string]$RepairSource = '',
            [string]$RepairSystemFileSource = '',
            [switch]$AnalyzeComponentStore,
            [switch]$TryLGKC,
            [switch]$TryOtherBootConfig,        
            [switch]$TrySafeMode,
            [switch]$RemoveSafeModeFlag,
            [switch]$RunSFC,
            [switch]$EnableBootLog,
            [switch]$DisableStartupRepair,
            [switch]$EnableStartupRepair,
            [switch]$DisableBFE,
            [switch]$EnableBFE,
            [switch]$AddTempUser,
            [switch]$AddTempUser2,
            [switch]$ResetLocalAdminPassword,
            [switch]$SetFullMemDump,
            [switch]$DisableNLA,
            [switch]$EnableNLA,
            [switch]$EnableWinRMHTTPS,
            [switch]$CheckRDPPolicies,
            [switch]$FixRDP,
            [switch]$FixRDPCert,
            [switch]$FixRDPPermissions,
            [switch]$FixRDPAuth,
            [switch]$FixUserRights,
            [switch]$FixPendingUpdates,
        [switch]$FixTxRLogs,
        [string[]]$TransactionLogScope = @('TxR'),
            [switch]$DisableWindowsUpdate,
            [switch]$RestoreRegistryFromRegBack,
            [switch]$EnableRegBackup,
            [switch]$DisableThirdPartyDrivers,
            [switch]$EnableThirdPartyDrivers,
            [switch]$GetServicesReport,
            [switch]$GetCatalogStoreReport,
            [string]$RepairCatalogStore,
            [switch]$IncludeHealthy,
            [switch]$IncludeServices,
            [switch]$IssuesOnly,
            [string[]]$DisableDriverOrService = @(),
            [string[]]$EnableDriverOrService = @(),
            [ValidateSet('Boot', 'System', 'Automatic', 'Manual', 'Disabled')][string]$DriverStartType,
            [switch]$DisableLsaProtection,
            [switch]$DisableCredentialGuard,
            [switch]$EnableCredentialGuard,
            [switch]$DisableMemoryIntegrity,
            [switch]$DisableAppLocker,
            [switch]$GetAppLockerReport,
            [switch]$FixSanPolicy,
            [switch]$FixAzureGuestAgent,
            [switch]$InstallAzureVMAgent,
            [switch]$FixSessionManager,
            [switch]$FixDeviceFilters,
            [switch]$KeepDefaultFilters,
            [switch]$CopyACPISettings,
            [switch]$ScanNetBindings,
            [switch]$FixNetBindings,
            [switch]$SysCheck,
            [switch]$ResetNetworkStack,
            [switch]$EnableTestSigning,
            [switch]$DisableTestSigning,
            [switch]$CheckDiskHealth,
            [switch]$CollectEventLogs,
            [switch]$CollectMinidumps,
            [switch]$AnalyzeCriticalBootFiles,
            [string[]]$RepairSystemFile = @(),
            [switch]$AnalyzeSyntheticDrivers,
            [switch]$EnsureSyntheticDriversEnabled,
            [switch]$ResetInterfacesToDHCP,
            [switch]$AnalyzeProxyState,
            [switch]$ClearProxyState,
            [switch]$GetBootPathReport,
            [switch]$AnalyzeBcdConsistency,
            [switch]$AnalyzeServicingState,
            [switch]$AnalyzeRecentChanges,
            [int]$RecentChangeDays = 14,
            [switch]$AnalyzeDomainTrustState,
            [switch]$PrepareRecoveryDiagnostics,
            [switch]$DisableDriverVerifier,
            [string]$EnableDriverVerifier = '',
            [switch]$ResetGroupPolicy,
            [switch]$FixWinlogon,
            [switch]$FixProfileLoad,
            [switch]$CheckRegistryHealth,
            [switch]$FixRegistryCorruption,
            [switch]$EnableSerialConsole,
            [switch]$ListInstalledUpdates,
            [string]$UninstallWindowsUpdate = '',
            [switch]$ListStartupPrograms,
            [switch]$DisableStartupPrograms,
            [switch]$DisableFirewall,
            [switch]$FixFirewallDebugLoopbackApps,
            [switch]$LeaveDiskOnline,
            [switch]$SkipCatalogVerification,
            [ValidateSet('SYSTEM', 'SOFTWARE', 'COMPONENTS', 'SAM', 'SECURITY')][string[]]$LoadHive = @(),
            [ValidateSet('SYSTEM', 'SOFTWARE', 'COMPONENTS', 'SAM', 'SECURITY')][string[]]$UnloadHive = @(),
            [string]$DriveLetter = ''
        )

        Show-RepairScriptVersionHeader

        # Identify the local OS disk (C: drive) to prevent accidental modification of the Hyper-V host
        $script:LocalOsDiskNumber = (Get-Partition -DriveLetter 'C' -ErrorAction SilentlyContinue).DiskNumber
        $script:RepairForceConfirm = [bool]$Force
        $script:BootsectPath = $BootsectPath
        $script:SkipCatalogVerification = [bool]$SkipCatalogVerification

        foreach ($pair in $mutuallyExclusiveParameterPairs) {
            if ($PSBoundParameters.ContainsKey($pair.Left) -and
                $PSBoundParameters.ContainsKey($pair.Right)) {
                Write-Error "Parameters -$($pair.Left) and -$($pair.Right) cannot be used together."
                return
            }
        }

        # Show usage/disk list when called with no actionable parameters
        if ($DiskNumber -lt 0 -and [string]::IsNullOrWhiteSpace($VMName)) {
            Write-Host @"
====================================================================
  Windows Boot Troubleshooting Script - Offline Disk Repair
====================================================================

USAGE:
  .\$(Split-Path -Leaf $PSCommandPath) -DiskNumber <N> [Options]
  .\$(Split-Path -Leaf $PSCommandPath) -VMName <Name> [Options]

PARAMETERS:
  -DiskNumber <int>      Disk number visible in Disk Management
  -VMName <string>       Hyper-V VM name (auto-detects disk, stops VM first)
    -Force                 Bypass confirmation prompts for scripted repair runs
  -LeaveDiskOnline       Keep disk online after repairs (default: take offline)
  -LoadHive <hive[,...]> Mount one or more offline registry hives and leave them loaded for manual
                           inspection/editing (implies disk stays online). Valid: SYSTEM SOFTWARE COMPONENTS SAM SECURITY
                           Example: -LoadHive SYSTEM  -> HKLM:\BROKENSYSTEM available in regedit
  -UnloadHive <hive[,...]> Unmount previously loaded hives and take the disk offline

--- AZURE AGENT ---------------------------------------------------------------
  -FixAzureGuestAgent    Enable Azure Guest Agent and RdAgent services (registry already present)
  -InstallAzureVMAgent   Install Azure VM Agent fully offline from host files (use when agent is missing)

--- DIAGNOSTICS (read-only) ---------------------------------------------------
  -CheckDiskHealth       Show disk/partition/filesystem health report
  -CheckRDPPolicies      Show current RDP auth policy values
  -CollectEventLogs      Copy guest event logs and crash dumps to C:\temp on the host
  -CollectMinidumps      Copy minidumps, MEMORY.DMP and LiveKernelReports to C:\temp on the host
  -AnalyzeCriticalBootFiles  Validate presence of critical boot/system binaries used during startup
  -AnalyzeSyntheticDrivers  Validate Azure/Hyper-V synthetic drivers (vmbus/storvsc/netvsc)
  -AnalyzeProxyState     Show machine proxy/PAC settings that may block remote management
  -AnalyzeBcdConsistency Validate BCD loader/device/path consistency for current boot mode
    -AnalyzeRecentChanges  Build a read-only 14-day timeline of recent servicing, driver, registry,
                                                     software, event log, and critical file changes that may explain a broken VM
        -RecentChangeDays <N>   (sub-option) lookback window in days, default 14, range 1-180
  -GetBootPathReport     Full boot chain health check: traces all 5 boot phases (Pre-Boot -> Boot Manager
                           -> OS Loader -> NTOS Kernel -> Logon) validating every file, driver, and registry
                           setting in load order with signature verification and fix suggestions
  -AnalyzeDomainTrustState  Assess likely domain-join/trust indicators from offline registry
  -ListStartupPrograms   List all auto-start programs (Run/RunOnce/Startup folders/Setup CmdLine)
  -ScanNetBindings       Report third-party network binding components (non-ms_ ComponentId)
  -SysCheck              Full offline diagnostic scan: BCD, services, device filters, RDP, networking,
                           Azure Agent, security settings, crash artefacts - with fix suggestions

--- BOOT & BCD ----------------------------------------------------------------
    -DisableStartupRepair  Suppress BCD-driven startup repair only (does not remove WinRE files/registration)
  -EnableBootLog         Enable ntbtlog.txt boot logging
  -EnableSerialConsole   Enable EMS/Serial Console (Azure Serial Console access via SAC)
    -EnableStartupRepair   Re-enable startup repair in BCD and also attempt offline WinRE registration
  -EnableTestSigning     Enable BCD test signing (allow unsigned drivers)
  -DisableTestSigning    Disable BCD test signing
  -FixBoot               Rebuild BCD from scratch
        -FixSecureBootCodeIntegrity  Refresh Gen2 EFI boot manager + SKUSiPolicy.p7b and repair CodeIntegrity Driver.stl/DriverSiPolicy.p7b for winload.efi / 0xc0430001
            -CodeIntegrityPolicySourcePath <path> Optional known-good CodeIntegrity folder/file source; otherwise uses offline WinSxS, then same-build rescue host fallback
            -RepairSystemFileSource <path> Optional known-good file or folder to repair from, for when every copy on the disk is a hard link to the damaged file
  -FixBootSector         Inspect and repair the MBR bootstrap + NTFS volume boot record (Gen1/BIOS only).
                         Fixes what -FixBoot cannot: "Operating system not found", "Missing operating
                         system", "A disk read error occurred" and a stale BPB HiddenSectors after a
                         disk/partition resize. Uses bootsect.exe when available, otherwise repairs
                         natively from the NTFS backup boot sector and a healthy local MBR.
    -BootsectPath <path> Optional explicit path to bootsect.exe (ADK, or \boot\bootsect.exe on Windows media)
    -FixBootStorageDrivers Repair boot storage Start/StartOverride settings and recreate safe missing inbox service keys
  -RecreateBootPartition Recreate missing boot partition (System Reserved for Gen1, EFI SP for Gen2) and run bcdboot
  -RemoveSafeModeFlag    Remove Safe Mode flag
  -TryLGKC               Switch boot to Last Known Good Control Set
  -TryOtherBootConfig    Switch boot to a different HKLM ControlSet
  -FixSessionManager     Remove BootExecute/SetupExecute entries with missing binaries (black screen fix)
  -TrySafeMode           Set boot to Safe Mode (minimal)

--- DISK & FILESYSTEM ---------------------------------------------------------
  -RepairComponentStore   Run DISM ScanHealth + RestoreHealth on the component store
    -RepairSource <path>     (sub-option) .wim, .iso, .msu, or .cab to use as repair source
  -FixFileSystem         Run chkdsk on the Windows partition
    -DriveLetter <letter>    (sub-option) target a specific drive letter instead of the auto-detected Windows partition
  -FixNtfsAttributeList  Repair NTFS metafile attribute list entries whose name offset is 0x1c instead of
                           the canonical 0x1a. Newer NTFS revisions reject that layout and fail the volume
                           mount, which the guest shows as a boot loop with bugcheck 0x24 (NTFS_FILE_SYSTEM).
                           Use this instead of chkdsk: chkdsk discards the whole attribute list rather than
                           correcting the field, dropping the child records it referenced (including the
                           `$Secure `$SDS security-descriptor stream).
    -DriveLetter <letter>    (sub-option) repair one volume instead of every NTFS volume on the disk
  -FixSanPolicy          Set SAN policy to OnlineAll (fix offline disks after migration)
  -RepairSystemFile <name[,name,...]>  Replace missing/0-byte/wrong-architecture binary from WinSxS or DriverStore
  -RunSFC                Run SFC in offline mode
  -SetFullMemDump        Configure full memory dump + pagefile on C:

--- DRIVERS & DEVICE FILTERS --------------------------------------------------
  -DisableDriverOrService <name[,name,...]>  Disable one or more named services or drivers (sets Start=4)
  -DisableDriverVerifier   Disable Driver Verifier (clears VerifyDrivers/VerifyDriverLevel)
  -EnableDriverVerifier [driver1.sys,...]  Enable Driver Verifier with standard flags; omit value to verify all drivers
  -EnsureSyntheticDriversEnabled  Re-enable core Azure synthetic drivers (vmbus/storvsc/netvsc)
  -EnableDriverOrService  <name[,name,...]>  Re-enable one or more named services or drivers
    -DriverStartType <type>           Required with -EnableDriverOrService: Boot, System, Automatic, Manual, Disabled
  -DisableThirdPartyDrivers    Disable all non-Microsoft Boot/System kernel drivers
  -EnableThirdPartyDrivers     Re-enable previously disabled third-party kernel drivers
  -GetServicesReport           List drivers from the offline ControlSet grouped by start type,
                                 flagging missing binaries and non-Microsoft vendors
    -IncludeServices             (sub-option) also include Win32 services, not just kernel drivers
    -IssuesOnly                  (sub-option) show only rows that need attention: missing binary,
                                   non-Microsoft vendor, or ErrorControl Severe/Critical (>=2)
  -GetCatalogStoreReport       Report the health of the guest's Authenticode catalog store
                                 (\Windows\System32\CatRoot) and name every Boot/System driver whose
                                 load depends on it. Use when boot fails with STATUS_INVALID_IMAGE_HASH
                                 (0xC0000428) or bugcheck 0x5A on a Microsoft driver whose binary is
                                 known good - multiple unrelated inbox drivers failing means the
                                 catalog store is at fault, not the drivers.
    -IncludeHealthy              (sub-option) list every catalog-dependent driver, not just failures
  -RepairCatalogStore <path>   Merge a same-build donor's catalogs into the guest's damaged store.
                                 <path> may be the donor's CatRoot, its {GUID} subfolder, or the
                                 donor's mounted Windows volume. The donor is rejected unless its
                                 catalogs actually publish this guest's own inbox binaries, so a
                                 wrong-build donor cannot be merged by accident (override with -Force).
                                 Purely additive: existing catalogs are never overwritten or removed,
                                 because each catalog is independently Microsoft-signed and adding one
                                 can only widen the hashes boot code integrity can resolve.
    -FixDeviceFilters      Scan and remove unsafe UpperFilters/LowerFilters from device classes and boot-critical device instances
    -KeepDefaultFilters    (sub-option) strict mode: only inbox safe-list entries kept; removes Microsoft-signed
                             non-defaults like InDskFlt that are not standard on Azure VMs
  -CopyACPISettings      Copy legacy Hyper-V ACPI Enum entries to newer device IDs (VMBus->MSFT1000,
                           Hyper_V_Gen_Counter_V1->MSFT1002); fixes missing synthetic device detection

--- NETWORKING & FIREWALL -----------------------------------------------------
  -DisableBFE            Disable Base Filtering Engine service
  -DisableFirewall       Disable Windows Firewall for all profiles (Domain/Private/Public)
  -EnableBFE             Re-enable Base Filtering Engine service
  -FixFirewallDebugLoopbackApps  Archive mpssvc DebugedLoopbackApps and recreate an empty value
                                  when duplicate SIDs risk the Firewall error 0x45b start/stop loop;
                                  captures/restores the existing AppCs owner/DACL around the repair
  -FixNetBindings        Remove orphaned third-party network binding components (missing binary; prevents NDIS init failure)
  -ResetNetworkStack     Reset TCP/IP stack, Winsock, firewall and DNS at next boot (also clears static DNS offline)
  -ResetInterfacesToDHCP Reset interface IPv4 settings to DHCP and clear static DNS/gateway values
  -ClearProxyState       Clear machine-level proxy/PAC settings in offline SOFTWARE hive

--- RDP & REMOTE ACCESS -------------------------------------------------------
  -DisableNLA            Disable Network Level Authentication
  -EnableNLA             Enable Network Level Authentication
  -EnableWinRMHTTPS      Configure WinRM HTTPS listener via startup script
  -FixRDP                Reset RDP settings, clear pinned listener cert, restore net services
  -FixRDPAuth            Set optimal RDP/NLA/NTLM auth policy for recovery
  -FixRDPCert            Recreate the self-signed RDP certificate
  -FixRDPPermissions     Reset RDP private key and certificate service permissions

--- REGISTRY ------------------------------------------------------------------
  -CheckRegistryHealth         Read-only integrity check of SYSTEM/SOFTWARE hives using chkreg.exe
  -FixRegistryCorruption       Repair corrupted SYSTEM/SOFTWARE hives using chkreg.exe (backs up originals)
  -EnableRegBackup             Enable periodic registry backups to RegBack folder
  -RestoreRegistryFromRegBack  Restore SYSTEM/SOFTWARE hives from RegBack backup
  -ResetGroupPolicy            Delete local Group Policy cache and clear SOFTWARE\Policies

--- SECURITY ------------------------------------------------------------------
  -DisableAppLocker            Disable AppLocker enforcement and AppIDSvc (fixes boot blocked by bad policy)
  -GetAppLockerReport          Show AppLocker enforcement state, AppIDSvc config, and parsed rules per collection
    -DisableLsaProtection        Disable only LSA protected process mode (RunAsPPL); does not change Credential Guard
  -DisableCredentialGuard      Disable Credential Guard and LSA protection
  -EnableCredentialGuard       Re-enable Credential Guard and LSA protection
    -DisableMemoryIntegrity      Disable Hypervisor-Enforced Code Integrity / Memory Integrity offline
  -FixWinlogon                 Reset Winlogon Shell/Userinit to Windows defaults (fixes black screen)
  -FixProfileLoad              Fix corrupted user profiles (.bak duplicates, temporary profile flags)

--- STARTUP PROGRAMS ----------------------------------------------------------
  -DisableStartupPrograms      Disable all auto-start programs (Run/RunOnce registry + Startup folders)

--- USERS & RIGHTS ------------------------------------------------------------
  -AddTempUser           Add a local admin via Group Policy startup script
  -AddTempUser2          Add a local admin via Setup CmdLine (domain-joined VMs)
  -FixUserRights         Reset user rights assignments to Windows defaults
  -ResetLocalAdminPassword  Reset an existing local admin account password at next boot

--- WINDOWS UPDATE ------------------------------------------------------------
  -AnalyzeComponentStore Analyze CBS.log for corrupt components and identify required update versions
  -AnalyzeServicingState Check pending CBS/servicing markers (pending.xml, SessionsPending, RebootPending)
    -AnalyzeRecentChanges  Correlate recent update, driver, software, registry and file changes into top suspects
  -ListInstalledUpdates  List installed Windows Updates (KB numbers) from offline CBS packages
  -DisableWindowsUpdate  Disable Windows Update services to stop boot loops
  -FixTxRLogs            Clear TxR/config/SMI transaction logs only (KB 0x800719e4, no update rollback)
    -TransactionLogScope <TxR|Config|SMI|All>  Which folders to clear (default: TxR)
  -FixPendingUpdates     Remove pending Windows Update transactions
  -UninstallWindowsUpdate <KB>  Mark a KB update as Absent in CBS (offline best-effort uninstall)
  -PrepareRecoveryDiagnostics  Bundle for broken VMs: boot log + serial console + full memory dump config

AVAILABLE DISKS:
"@
            if ($null -ne $script:LocalOsDiskNumber) {
                Write-Host "  (Disk $script:LocalOsDiskNumber excluded - hosts the local C: drive and cannot be a repair target)" -ForegroundColor DarkYellow
            }

            # Build a disk-number -> VM-name map for all non-Off VMs
            # VHD/VHDX-backed drives don't expose DiskNumber on HardDrives directly;
            # resolve via Get-VHD which populates DiskNumber when the VHD is mounted.
            # Include ALL VMs (any state) so the listing is informational for Off VMs too.
            # A running VM tag is appended with its state when not Running.
            $diskToVM = @{}
            if (Get-Command Get-VM -ErrorAction SilentlyContinue) {
                Get-VM -ErrorAction SilentlyContinue | ForEach-Object {
                    $v = $_
                    $stateLabel = if ($v.State -eq 'Running') { $v.Name } else { "$($v.Name) [$($v.State)]" }
                    foreach ($hd in $v.HardDrives) {
                        $resolvedNum = -1
                        if ($null -ne $hd.DiskNumber -and [int]$hd.DiskNumber -ge 0) {
                            $resolvedNum = [int]$hd.DiskNumber
                        }
                        elseif ($hd.Path -match '\.vhdx?$') {
                            $vhd = Get-VHD -Path $hd.Path -ErrorAction SilentlyContinue
                            if ($vhd -and $null -ne $vhd.DiskNumber -and [int]$vhd.DiskNumber -ge 0) {
                                $resolvedNum = [int]$vhd.DiskNumber
                            }
                        }
                        if ($resolvedNum -ge 0) {
                            $diskToVM[$resolvedNum] = $stateLabel
                        }
                    }
                }
            }

            Get-Disk | Sort-Object Number | Where-Object { $null -eq $script:LocalOsDiskNumber -or $_.Number -ne $script:LocalOsDiskNumber } | ForEach-Object {
                $d = $_
                $vmTag = if ($diskToVM.ContainsKey([int]$d.Number)) { " [attached to VM: $($diskToVM[[int]$d.Number])]" } else { '' }
                Write-Host "  Disk $($d.Number): $($d.PartitionStyle) | $([math]::Round($d.Size / 1GB)) GB | $($d.FriendlyName)$vmTag"
                $parts = Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue
                if (-not $parts) { Write-Host "    (no partitions)"; return }
                foreach ($p in $parts) {
                    $sz = [math]::Round($p.Size / 1MB)
                    $ltr = if ($p.DriveLetter) { "$($p.DriveLetter):" } else { '(no letter)' }
                    Write-Host "    +- Partition $($p.PartitionNumber): $ltr | $($p.Type) | $($sz) MB"
                }
            }
            Write-Host ""
            return
        }

        # Refuse to operate on the local OS disk when -DiskNumber is supplied directly
        if ($null -ne $script:LocalOsDiskNumber -and $DiskNumber -ge 0 -and $DiskNumber -eq $script:LocalOsDiskNumber) {
            Write-Error "Disk $DiskNumber hosts the local C: drive. Refusing to modify it to prevent breaking the Hyper-V host."
            return
        }

        # Initialize logging and target (resolve VM/disk, bring disk online, detect partitions)
        # Determine if any write/repair action was requested (exclude pure read-only switches)
        $readOnlySwitches = @('SysCheck', 'CheckDiskHealth', 'ScanNetBindings', 'CheckRDPPolicies', 'CollectEventLogs', 'CollectMinidumps', 'ShowLastSession', 'GetServicesReport', 'GetCatalogStoreReport', 'GetAppLockerReport', 'ListInstalledUpdates', 'ListStartupPrograms', 'AnalyzeCriticalBootFiles', 'AnalyzeSyntheticDrivers', 'AnalyzeProxyState', 'GetBootPathReport', 'AnalyzeBcdConsistency', 'AnalyzeComponentStore', 'AnalyzeServicingState', 'AnalyzeRecentChanges', 'AnalyzeDomainTrustState')
        $hasRepairAction = $PSBoundParameters.Keys | Where-Object { $readOnlySwitches -notcontains $_ -and $_ -notin @('VMName', 'DiskNumber', 'Force', 'LeaveDiskOnline', 'DriveLetter', 'RepairSource', 'CodeIntegrityPolicySourcePath', 'RepairSystemFileSource', 'IncludeServices', 'IssuesOnly', 'KeepDefaultFilters', 'DriverStartType', 'RecentChangeDays', 'LoadHive', 'UnloadHive', 'TransactionLogScope') }
        if ($hasRepairAction) {
            Write-Host "  Tip: if you haven't already, a VM snapshot or disk backup before making changes is always a safe starting point." -ForegroundColor DarkGray
            Write-Host ""
        }
        if (-not (Initialize-TargetDisk -VMName $VMName -DiskNumber $DiskNumber)) {
            return
        }

        # Guest computer name is captured opportunistically by Invoke-WithHive
        # the first time the SYSTEM hive is loaded for any action.
        $script:GuestComputerName = ''

        # Infrastructure setup is intentionally not action-logged. Start the repair
        # session after the target disk is ready so only guest mutations are recorded.
        Start-ActionLog -HeaderMessage 'Repair-OfflineDisk start' -ParameterValues $PSBoundParameters

        try {
            if ($FixFileSystem) { FixDiskCorruption -DriveLetter $DriveLetter }
            if ($FixNtfsAttributeList) { FixNtfsAttributeList -DriveLetter $DriveLetter }
            if ($FixBoot) { RebuildBCD }
            if ($FixSecureBootCodeIntegrity) { RepairSecureBootCodeIntegrity -CodeIntegrityPolicySourcePath $CodeIntegrityPolicySourcePath }
            if ($FixBootSector) { FixBootSector }
            if ($FixBootStorageDrivers) { FixBootStorageDrivers }
            if ($RecreateBootPartition) { RecreateBootPartition }
            if ($RepairComponentStore) { RunDismHealth -RepairSource $RepairSource }
            if ($AnalyzeComponentStore) { AnalyzeComponentStore }
            if ($RunSFC) { RunSFC }
            if ($TryLGKC) { SetLKGC }
            if ($TryOtherBootConfig) { RevertLKGC }
            if ($TrySafeMode) { SetSafeMode }
            if ($RemoveSafeModeFlag) { RemoveSafeMode }
            if ($EnableBootLog) { SetBootLog }
            if ($DisableStartupRepair) { DisableStartupRepair }
            if ($EnableStartupRepair) { EnableStartupRepair }
            if ($DisableBFE) { Disable-ServiceOrDriver -ServiceName BFE }
            if ($EnableBFE) { Enable-ServiceOrDriver -ServiceName BFE -StartValue 2 }
            if ($AddTempUser) {
                Write-Host "Please provide the credential (no .\ or domain\user, just user): " -ForegroundColor Yellow
                AddNewUser -WinDrive $script:WinDriveLetter -Credential (Get-Credential)
            }
            if ($AddTempUser2) {
                Write-Host "Please provide the credential (no .\ or domain\user, just user): " -ForegroundColor Yellow
                AddNewUser2 -Credential (Get-Credential)
            }
            if ($ResetLocalAdminPassword) { ResetLocalAdminPassword }
            if ($SetFullMemDump) { ConfigureFullMemDump }
            if ($FixRDP) { ResetRDPSettings }
            if ($FixRDPCert) { RecreateRDPCertificate }
            if ($FixRDPPermissions) { ResetRDPPrivKeyPermissions }
            if ($DisableNLA) { SetNLA -Enable $false }
            if ($EnableNLA) { SetNLA -Enable $true }
            if ($EnableWinRMHTTPS) { SetWinRMHTTPSEnabled }
            if ($FixPendingUpdates) { ClearPendingUpdates }
        if ($FixTxRLogs) { ClearTxRLogs -Scope $TransactionLogScope }
            if ($DisableWindowsUpdate) { DisableWindowsUpdate }
            if ($FixUserRights) { ResetUserRights }
            if ($RestoreRegistryFromRegBack) { RestoreRegistryFromRegBack }
            if ($EnableRegBackup) { EnableRegBackup }
            if ($DisableThirdPartyDrivers) { DisableThirdPartyDrivers }
            if ($EnableThirdPartyDrivers) { EnableThirdPartyDrivers }
            if ($GetServicesReport) { GetServicesReport -IncludeServices:$IncludeServices -IssuesOnly:$IssuesOnly }
            if ($GetCatalogStoreReport) { GetCatalogStoreReport -IncludeHealthy:$IncludeHealthy }
            if ($RepairCatalogStore) { RepairCatalogStore -DonorPath $RepairCatalogStore -Force:$Force }
            foreach ($d in $DisableDriverOrService) { if (-not [string]::IsNullOrWhiteSpace($d)) { Disable-ServiceOrDriver -ServiceName $d.Trim() } }
            if ($EnableDriverOrService.Count -gt 0) {
                if (-not $PSBoundParameters.ContainsKey('DriverStartType')) {
                    Write-Error "-DriverStartType is required when using -EnableDriverOrService. Specify Boot, System, Automatic, Manual, or Disabled."
                    return
                }
                $startInt = ConvertTo-ServiceStartValue -DriverStartType $DriverStartType
                foreach ($d in $EnableDriverOrService) { if (-not [string]::IsNullOrWhiteSpace($d)) { Enable-ServiceOrDriver -ServiceName $d.Trim() -StartValue $startInt } }
            }
            if ($DisableLsaProtection) { DisableLsaProtection }
            if ($DisableCredentialGuard) { DisableCredentialGuard }
            if ($EnableCredentialGuard) { EnableCredentialGuard }
            if ($DisableMemoryIntegrity) { DisableMemoryIntegrity }
            if ($DisableAppLocker) { DisableAppLocker }
            if ($GetAppLockerReport) { GetAppLockerReport }
            if ($FixSanPolicy) { FixSanPolicy }
            if ($FixAzureGuestAgent) { FixAzureGuestAgent }
            if ($InstallAzureVMAgent) { InstallAzureVMAgentOffline }
            if ($FixDeviceFilters) { FixDeviceClassFilters -KeepDefaultFilters:$KeepDefaultFilters }
            if ($FixSessionManager) { FixSessionManagerBootEntries }
            if ($CopyACPISettings) { CopyACPISettings }
            if ($ScanNetBindings) { ScanNetAdapterBindings }
            if ($FixNetBindings) { RemoveOrphanedNetBindings }
            if ($SysCheck) { RunSystemCheck }
            if ($ResetNetworkStack) { ResetNetworkStack }
            if ($EnableTestSigning) { SetTestSigning -Enable $true }
            if ($DisableTestSigning) { SetTestSigning -Enable $false }
            if ($CheckDiskHealth) { CheckDiskHealth }
            if ($CollectEventLogs) { CollectEventLogs }
            if ($AnalyzeCriticalBootFiles) { AnalyzeCriticalBootFiles }
            if ($RepairSystemFile.Count -gt 0) { RepairBrokenSystemFile -FileNames $RepairSystemFile -SourcePath $RepairSystemFileSource }
            if ($AnalyzeSyntheticDrivers) { AnalyzeSyntheticDrivers }
            if ($EnsureSyntheticDriversEnabled) { EnsureSyntheticDriversEnabled }
            if ($ResetInterfacesToDHCP) { ResetInterfacesToDHCP }
            if ($AnalyzeProxyState) { AnalyzeProxyState }
            if ($ClearProxyState) { ClearProxyState }
            if ($GetBootPathReport) { GetBootPathReport }
            if ($AnalyzeBcdConsistency) { AnalyzeBcdConsistency }
            if ($AnalyzeServicingState) { AnalyzeServicingState }
            if ($AnalyzeRecentChanges) { AnalyzeRecentChanges -RecentChangeDays $RecentChangeDays }
            if ($AnalyzeDomainTrustState) { AnalyzeDomainTrustState }
            if ($PrepareRecoveryDiagnostics) { PrepareRecoveryDiagnostics }
            if ($CheckRDPPolicies) { GetRdpAuthPolicySnapshot }
            if ($FixRDPAuth) { SetRdpAuthPolicyOptimal }
            if ($DisableDriverVerifier) { DisableDriverVerifier }
            if ($PSBoundParameters.ContainsKey('EnableDriverVerifier')) { EnableDriverVerifier -DriverList $EnableDriverVerifier }
            if ($CollectMinidumps) { CollectMinidumps }
            if ($ResetGroupPolicy) { ResetGroupPolicy }
            if ($FixWinlogon) { FixWinlogon }
            if ($FixProfileLoad) { FixProfileLoad }
            if ($CheckRegistryHealth) { CheckRepairRegistryHives }
            if ($FixRegistryCorruption) { CheckRepairRegistryHives -Repair }
            if ($EnableSerialConsole) { EnableSerialConsole }
            if ($ListInstalledUpdates) { ListInstalledUpdates }
            if (-not [string]::IsNullOrWhiteSpace($UninstallWindowsUpdate)) { UninstallWindowsUpdate -KBNumber $UninstallWindowsUpdate }
            if ($ListStartupPrograms) { ListStartupPrograms }
            if ($DisableStartupPrograms) { DisableStartupPrograms }
            if ($DisableFirewall) { DisableFirewall }
            if ($FixFirewallDebugLoopbackApps) { FixFirewallDebugLoopbackApps }

            # -LoadHive: mount requested hives and leave them loaded for manual inspection
            foreach ($hive in $LoadHive) {
                $OfflineWindowsPath = Join-Path $script:WinDriveLetter 'Windows'
                Write-Host "Loading offline $hive hive..." -ForegroundColor Cyan
                MountOffHive -WinPath $OfflineWindowsPath -Hive $hive
                Write-Host "  [OK] HKLM:\BROKEN$hive is now loaded. Use regedit or reg.exe to inspect/edit." -ForegroundColor Green
                $scriptName = if ($PSCommandPath) { Split-Path -Leaf $PSCommandPath } else { 'Repair-AzVMDisk.ps1' }
                Write-Host "  [!]  Run: .\$scriptName -DiskNumber $($script:DiskNumber) -UnloadHive $hive  to unload and take the disk offline when done." -ForegroundColor Yellow
            }

            # -UnloadHive: unmount requested hives (before the disk-offline step in finally)
            foreach ($hive in $UnloadHive) {
                Write-Host "Unloading offline $hive hive..." -ForegroundColor Cyan
                UnmountOffHive -Hive $hive
                Write-Host "  [OK] HKLM:\BROKEN$hive unloaded." -ForegroundColor Green
            }
        }
        catch {
            if (-not $script:_userFacingError) { Write-Error "Repair-OfflineDisk encountered an error: $_" }
            throw
        }
        finally {
            # When -LoadHive was used, keep the disk online so the loaded hives remain accessible
            $keepOnlineForHive = $LoadHive.Count -gt 0 -and $UnloadHive.Count -eq 0
            if (-not $LeaveDiskOnline -and -not $keepOnlineForHive -and $script:DiskNumber -ge 0) {
                Write-Host "`r`nSetting disk $script:DiskNumber offline..."
                try {
                    Set-Disk -Number $script:DiskNumber -IsOffline $true
                    Write-Host "[OK] Disk $script:DiskNumber is now offline and can be safely reconnected or used with the VM." -ForegroundColor Green
                }
                catch {
                    Write-Warning "Could not set disk $script:DiskNumber offline: $_"
                }

                # Dismount VHD if we auto-mounted it (prevents "file locked" when starting the VM)
                if ($script:AutoMountedVHDPath) {
                    Write-Host "Dismounting auto-mounted VHD: $($script:AutoMountedVHDPath)..."
                    try {
                        Dismount-VHD -Path $script:AutoMountedVHDPath -ErrorAction Stop
                        Write-Host "[OK] VHD dismounted." -ForegroundColor Green
                    }
                    catch {
                        Write-Warning "Could not dismount VHD: $_"
                    }
                    $script:AutoMountedVHDPath = $null
                }
            }
        }
    }

    # Promote dynamic sub-parameters to local variables so the rest of the script can use them.
    # Dynamic params are in $PSBoundParameters but not in automatic $variables.
    $CodeIntegrityPolicySourcePath = if ($PSBoundParameters.ContainsKey('CodeIntegrityPolicySourcePath')) { $PSBoundParameters['CodeIntegrityPolicySourcePath'] } else { '' }
    $DriveLetter = if ($PSBoundParameters.ContainsKey('DriveLetter')) { $PSBoundParameters['DriveLetter'] }      else { '' }
    $RepairSource = if ($PSBoundParameters.ContainsKey('RepairSource')) { $PSBoundParameters['RepairSource'] }     else { '' }
    $RepairSystemFileSource = if ($PSBoundParameters.ContainsKey('RepairSystemFileSource')) { $PSBoundParameters['RepairSystemFileSource'] } else { '' }
    $IncludeServices = [bool]$PSBoundParameters.ContainsKey('IncludeServices')
    $IssuesOnly = [bool]$PSBoundParameters.ContainsKey('IssuesOnly')
    $KeepDefaultFilters = [bool]$PSBoundParameters.ContainsKey('KeepDefaultFilters')
    $DriverStartType = if ($PSBoundParameters.ContainsKey('DriverStartType')) { $PSBoundParameters['DriverStartType'] }  else { $null }
    $RecentChangeDays = if ($PSBoundParameters.ContainsKey('RecentChangeDays')) { $PSBoundParameters['RecentChangeDays'] } else { 14 }
    $Detailed = [bool]$PSBoundParameters.ContainsKey('Detailed')
    $All = [bool]$PSBoundParameters.ContainsKey('All')
    $SessionId = if ($PSBoundParameters.ContainsKey('SessionId')) { $PSBoundParameters['SessionId'] }        else { '' }
    $ExportTo = if ($PSBoundParameters.ContainsKey('ExportTo')) { $PSBoundParameters['ExportTo'] }         else { '' }

    # Show log entries and exit when -ShowLastSession is requested
    if ($ShowLastSession) {
        Get-LastRepairSession -SessionId $SessionId -Detailed:$Detailed -All:$All -ExportTo $ExportTo
        return
    }

    # Invoke consolidated helper with script-bound parameters
    try {
        Repair-OfflineDisk @PSBoundParameters
    }
    catch {
        # User-facing pre-flight errors are already printed cleanly; suppress the redundant
        # unhandled-exception trace that PowerShell would otherwise show at the prompt.
        if (-not $script:_userFacingError) { throw }
    }
} # end
